INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Εν αρχή εποίησεν ο Θεός τον ουρανόν και την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Η δε γη ήτο άμορφος και έρημος· και σκότος επί του προσώπου της αβύσσου. Και πνεύμα Θεού εφέρετο επί της επιφανείας των υδάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Και είπεν ο Θεός, Γενηθήτω φώς· και έγεινε φώς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'και είδεν ο Θεός το φως ότι ήτο καλόν· και διεχώρισεν ο Θεός το φως από του σκότους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'και εκάλεσεν ο Θεός το φως, Ημέραν· το δε σκότος εκάλεσε, Νύκτα. Και έγεινεν εσπέρα και έγεινε πρωΐ, ημέρα πρώτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Και είπεν ο Θεός, Γενηθήτω στερέωμα αναμέσον των υδάτων, και ας διαχωρίζη ύδατα από υδάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Και εποίησεν ο Θεός το στερέωμα, και διεχώρισε τα ύδατα τα υποκάτωθεν του στερεώματος από των υδάτων των επάνωθεν του στερεώματος. Και έγεινεν ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Και εκάλεσεν ο Θεός το στερέωμα, Ουρανόν. Και έγεινεν εσπέρα και έγεινε πρωΐ, ημέρα δευτέρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Και είπεν ο Θεός, Ας συναχθώσι τα ύδατα τα υποκάτω του ουρανού εις τόπον ένα, και ας φανή η ξηρά. Και έγεινεν ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Και εκάλεσεν ο Θεός την ξηράν, γήν· και το σύναγμα των υδάτων εκάλεσε, Θαλάσσας· και είδεν ο Θεός ότι ήτο καλόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Και είπεν ο Θεός, Ας βλαστήση η γη χλωρόν χόρτον, χόρτον κάμνοντα σπόρον, και δένδρον κάρπιμον κάμνον καρπόν κατά το είδος αυτού, του οποίου το σπέρμα να ήναι εν αυτώ επί της γης. Και έγεινεν ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Και εβλάστησεν η γη χλωρόν χόρτον, χόρτον κάμνοντα σπόρον κατά το είδος αυτού, και δένδρον κάμνον καρπόν, του οποίου το σπέρμα είναι εν αυτώ κατά το είδος αυτού· και είδεν ο Θεός ότι ήτο καλόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Και έγεινεν εσπέρα και έγεινε πρωΐ, ημέρα τρίτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Και είπεν ο Θεός, Ας γείνωσι φωστήρες εν τω στερεώματι του ουρανού, διά να διαχωρίζωσι την ημέραν από της νυκτός· και ας ήναι διά σημεία και καιρούς και ημέρας και ενιαυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'και ας ήναι διά φωστήρας εν τω στερεώματι του ουρανού, διά να φέγγωσιν επί της γης. Και έγεινεν ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Και έκαμεν ο Θεός τους δύο φωστήρας τους μεγάλους, τον φωστήρα τον μέγαν διά να εξουσιάζη επί της ημέρας, και τον φωστήρα τον μικρόν διά να εξουσιάζη επί της νυκτός· και τους αστέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'και έθεσεν αυτούς ο Θεός εν τω στερεώματι του ουρανού, διά να φέγγωσιν επί της γης,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'και να εξουσιάζωσιν επί της ημέρας και επί της νυκτός και να διαχωρίζωσι το φως από του σκότους. Και είδεν ο Θεός ότι ήτο καλόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Και έγεινεν εσπέρα και έγεινε πρωΐ, ημέρα τετάρτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Και είπεν ο Θεός, Ας γεννήσωσι τα ύδατα εν αφθονία νηκτά έμψυχα και πετεινά ας πέτωνται επάνωθεν της γης κατά το στερέωμα του ουρανού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Και εποίησεν ο Θεός τα κήτη τα μεγάλα και παν έμψυχον κινούμενον, τα οποία εγέννησαν εν αφθονία τα ύδατα κατά το είδος αυτών, και παν πετεινόν πτερωτόν κατά το είδος αυτού. Και είδεν ο Θεός ότι ήτο καλόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Και ευλόγησεν αυτά ο Θεός, λέγων, Αυξάνεσθε και πληθύνεσθε και γεμίσατε τα ύδατα εν ταις θαλάσσαις· και τα πετεινά ας πληθύνωνται επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Και έγεινεν εσπέρα και έγεινε πρωΐ, ημέρα πέμπτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Και είπεν ο Θεός, Ας γεννήση η γη ζώα έμψυχα κατά το είδος αυτών, κτήνη και ερπετά και ζώα της γης κατά το είδος αυτών· και έγεινεν ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Και έκαμεν ο Θεός τα ζώα της γης κατά το είδος αυτών, και τα κτήνη κατά το είδος αυτών, και παν ερπετόν της γης κατά το είδος αυτού. Και είδεν ο Θεός ότι ήτο καλόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Και είπεν ο θεός, Ας κάμωμεν άνθρωπον κατ\' εικόνα ημών, καθ\' ομοίωσιν ημών· και ας εξουσιάζη επί των ιχθύων της θαλάσσης και επί των πετεινών του ουρανού και επί των κτηνών και επί πάσης της γης και επί παντός ερπετού, έρποντος επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Και εποίησεν ο Θεός τον άνθρωπον κατ\' εικόνα εαυτού· κατ\' εικόνα Θεού εποίησεν αυτόν· άρσεν και θήλυ εποίησεν αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'και ευλόγησεν αυτούς ο Θεός· και είπε προς αυτούς ο Θεός, Αυξάνεσθε και πληθύνεσθε και γεμίσατε την γην και κυριεύσατε αυτήν, και εξουσιάζετε επί των ιχθύων της θαλάσσης και επί των πετεινών του ουρανού και επί παντός ζώου κινουμένου επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Και είπεν ο Θεός, Ιδού, σας έδωκα πάντα χόρτον κάμνοντα σπόρον, όστις είναι επί του προσώπου πάσης της γης, και παν δένδρον, το οποίον έχει εν εαυτώ καρπόν δένδρου κάμνοντος σπόρον· ταύτα θέλουσιν είσθαι εις εσάς προς τροφήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'και εις πάντα τα ζώα της γης και εις πάντα τα πετεινά του ουρανού και εις παν ερπετόν έρπον επί της γης και έχον εν εαυτώ ψυχήν ζώσαν, έδωκα πάντα χλωρόν χόρτον εις τροφήν. Και έγεινεν ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Και είδεν ο Θεός πάντα όσα εποίησε· και ιδού, ήσαν καλά λίαν. Και έγεινεν εσπέρα και έγεινε πρωΐ, ημέρα έκτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Και συνετελέσθησαν ο ουρανός και η γη και πάσα η στρατιά αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Και είχε συντετελεσμένα ο Θεός εν τη ημέρα τη εβδόμη τα έργα αυτού, τα οποία έκαμε· και ανεπαύθη την ημέραν την εβδόμην από πάντων των έργων αυτού, τα οποία έκαμε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Και ευλόγησεν ο Θεός την ημέραν την εβδόμην και ηγίασεν αυτήν· διότι εν αυτή ανεπαύθη από πάντων των έργων αυτού, τα οποία έκτισε και έκαμεν ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Αύτη είναι η γένεσις του ουρανού και της γης, ότε εκτίσθησαν αυτά, καθ\' ην ημέραν εποίησε Κύριος ο Θεός γην και ουρανόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'και πάντα τα φυτά του αγρού, πριν γείνωσιν επί της γης, και πάντα χόρτον του αγρού, πριν βλαστήση· διότι δεν είχε βρέξει Κύριος ο Θεός επί της γης, και άνθρωπος δεν ήτο διά να εργάζηται την γήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'ο ατμός δε ανέβαινεν από της γης και επότιζε παν το πρόσωπον της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Και έπλασε Κύριος ο Θεός τον άνθρωπον από χώματος εκ της γης. και ενεφύσησεν εις τους μυκτήρας αυτού πνοήν ζωής, και έγεινεν ο άνθρωπος εις ψυχήν ζώσαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Και εφύτευσε Κύριος ο Θεός παράδεισον εν τη Εδέμ κατά ανατολάς και έθεσεν εκεί τον άνθρωπον, τον οποίον έπλασε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Και Κύριος ο Θεός έκαμε να βλαστήση εκ της γης παν δένδρον ώραίον εις την όρασιν και καλόν εις την γεύσιν· και το ξύλον της ζωής εν μέσω του παραδείσου και το ξύλον της γνώσεως του καλού και του κακού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Ποταμός δε εξήρχετο εκ της Εδέμ διά να ποτίζη τον παράδεισον· και εκείθεν εμερίζετο εις τέσσαρας κλάδους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Το όνομα του ενός, Φισών· ούτος είναι ο περικυκλόνων πάσαν την γην Αβιλά· όπου ευρίσκεται το χρυσίον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'το δε χρυσίον της γης εκείνης είναι καλόν· εκεί είναι το βδέλλιον και ο λίθος ο ονυχίτης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Και το όνομα του ποταμού του δευτέρου, Γιών· ούτος είναι ο περικυκλόνων πάσαν την γην Χούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Και το όνομα του ποταμού του τρίτου, Τίγρις· ούτος είναι ο ρέων προς ανατολάς της Ασσυρίας. Ο δε ποταμός ο τέταρτος, ούτος είναι ο Ευφράτης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Και έλαβε Κύριος ο Θεός τον άνθρωπον και έθεσεν αυτόν εν τω παραδείσω της Εδέμ διά να εργάζηται αυτόν και να φυλάττη αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Προσέταξε δε Κύριος ο Θεός εις τον Αδάμ λέγων, Από παντός δένδρου του παραδείσου ελευθέρως θέλεις τρώγει,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'από δε του ξύλου της γνώσεως του καλού και του κακού δεν θέλεις φάγει απ\' αυτού· διότι καθ\' ην ημέραν φάγης απ\' αυτού, θέλεις εξάπαντος αποθάνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Και είπε Κύριος ο Θεός, Δεν είναι καλόν να ήναι ο άνθρωπος μόνος· θέλω κάμει εις αυτόν βοηθόν όμοιον με αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Έπλασε δε Κύριος ο Θεός εκ της γης πάντα τα ζώα του αγρού και πάντα τα πετεινά του ουρανού, και έφερεν αυτά προς τον Αδάμ, διά να ίδη πως να ονομάση αυτά· και ό,τι όνομα ήθελε δώσει ο Αδάμ εις παν έμψυχον, τούτο να ήναι το όνομα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Και έδωκεν ο Αδάμ ονόματα εις πάντα τα κτήνη και εις τα πτηνά του ουρανού και εις πάντα τα ζώα του αγρού· εις δε τον Αδάμ δεν ευρίσκετο βοηθός όμοιος με αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Και επέβαλε Κύριος ο Θεός έκστασιν επί τον Αδάμ, και εκοιμήθη· και έλαβε μίαν εκ των πλευρών αυτού και έκλεισε με σάρκα τον τόπον αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Και κατεσκεύασε Κύριος ο Θεός την πλευράν, την οποίαν έλαβεν από του Αδάμ, εις γυναίκα και έφερεν αυτήν προς τον Αδάμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Και είπεν ο Αδάμ, Τούτο είναι τώρα οστούν εκ των οστέων μου και σαρξ εκ της σαρκός μου· αύτη θέλει ονομασθή ανδρίς, διότι εκ του ανδρός αύτη ελήφθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Διά τούτο θέλει αφήσει ο άνθρωπος τον πατέρα αυτού και την μητέρα αυτού, και θέλει προσκολληθή εις την γυναίκα αυτού· και θέλουσιν είσθαι οι δύο εις σάρκα μίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Ήσαν δε και οι δύο γυμνοί, ο Αδάμ και η γυνή αυτού, και δεν ησχύνοντο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Ο δε όφις ήτο το φρονιμώτερον πάντων των ζώων του αγρού, τα οποία έκαμε Κύριος ο Θεός· και είπεν ο όφις προς την γυναίκα, Τω όντι είπεν ο Θεός, Μη φάγητε από παντός δένδρου του παραδείσου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Και είπεν η γυνή προς τον όφιν, Από του καρπού των δένδρων του παραδείσου δυνάμεθα να φάγωμεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'από δε του καρπού του δένδρου, το οποίον είναι εν μέσω του παραδείσου, είπεν ο Θεός, Μη φάγητε απ\' αυτού, μηδέ εγγίσητε αυτόν, διά να μη αποθάνητε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Και είπεν ο όφις προς την γυναίκα, Δεν θέλετε βεβαίως αποθάνει');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'αλλ\' εξεύρει ο Θεός, ότι καθ\' ην ημέραν φάγητε απ\' αυτού, θέλουσιν ανοιχθή οι οφθαλμοί σας, και θέλετε είσθαι ως θεοί, γνωρίζοντες το καλόν και το κακόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Και είδεν η γυνή, ότι το δένδρον ήτο καλόν εις βρώσιν, και ότι ήτο αρεστόν εις τους οφθαλμούς, και επιθυμητόν το δένδρον ως δίδον γνώσιν· και λαβούσα εκ του καρπού αυτού, έφαγε· και έδωκε και εις τον άνδρα αυτής μεθ\' εαυτής, και αυτός έφαγε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Και ηνοίχθησαν οι οφθαλμοί αμφοτέρων, και εγνώρισαν ότι ήσαν γυμνοί· και ράψαντες φύλλα συκής, έκαμον εις εαυτούς περιζώματα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Και ήκουσαν την φωνήν Κυρίου του Θεού, περιπατούντος εν τω παραδείσω προς το δειλινόν· και εκρύφθησαν ο Αδάμ και η γυνή αυτού από προσώπου Κυρίου του Θεού, μεταξύ των δένδρων του παραδείσου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Εκάλεσε δε Κύριος ο Θεός τον Αδάμ, και είπε προς αυτόν, Που είσαι;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Ο δε είπε, Την φωνήν σου ήκουσα εν τω παραδείσω, και εφοβήθην, διότι είμαι γυμνός· και εκρύφθην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Και είπε προς αυτόν ο Θεός, Τις εφανέρωσεν εις σε ότι είσαι γυμνός; Μήπως έφαγες από του δένδρου, από του οποίου προσέταξα εις σε να μη φάγης;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Και είπεν ο Αδάμ, Η γυνή την οποίαν έδωκας να ήναι μετ\' εμού, αυτή μοι έδωκεν από του δένδρου, και έφαγον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Και είπε Κύριος ο Θεός προς την γυναίκα, Τι είναι τούτο το οποίον έκαμες; Και η γυνή είπεν, Ο όφις με ηπάτησε, και έφαγον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Και είπε Κύριος ο Θεός προς τον όφιν, Επειδή έκαμες τούτο, επικατάρατος να ήσαι μεταξύ πάντων των κτηνών, και πάντων των ζώων του αγρού· επί της κοιλίας σου θέλεις περιπατεί, και χώμα θέλεις τρώγει, πάσας τας ημέρας της ζωής σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'και έχθραν θέλω στήσει αναμέσον σου και της γυναικός, και αναμέσον του σπέρματός σου και του σπέρματος αυτής· αυτό θέλει σου συντρίψει την κεφαλήν, και συ θέλεις κεντήσει την πτέρναν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Προς δε την γυναίκα είπε, Θέλω υπερπληθύνει τας λύπας σου και τους πόνους της κυοφορίας σου· με λύπας θέλεις γεννά τέκνα· και προς τον άνδρα σου θέλει είσθαι η επιθυμία σου, και αυτός θέλει σε εξουσιάζει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Προς δε τον Αδάμ είπεν, Επειδή υπήκουσας εις τον λόγον της γυναικός σου, και έφαγες από του δένδρου, από του οποίου προσέταξα εις σε λέγων, Μη φάγης απ\' αυτού, κατηραμένη να ήναι η γη εξ αιτίας σου· με λύπας θέλεις τρώγει τους καρπούς αυτής πάσας τας ημέρας της ζωής σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'και ακάνθας και τριβόλους θέλει βλαστάνει εις σέ· και θέλεις τρώγει τον χόρτον του αγρού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'εν τω ιδρώτι του προσώπου σου θέλεις τρώγει τον άρτον σου, εωσού επιστρέψης εις την γην, εκ της οποίας ελήφθης· επειδή γη είσαι, και εις γην θέλεις επιστρέψει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Και εκάλεσεν ο Αδάμ το όνομα της γυναικός αυτού, Εύαν· διότι αυτή ήτο μήτηρ πάντων των ζώντων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Και έκαμε Κύριος ο Θεός εις τον Αδάμ και εις την γυναίκα αυτού χιτώνας δερματίνους, και ενέδυσεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Και είπε Κύριος ο Θεός, Ιδού, έγεινεν ο Αδάμ ως εις εξ ημών, εις το γινώσκειν το καλόν και το κακόν· και τώρα μήπως εκτείνη την χείρα αυτού, και λάβη και από του ξύλου της ζωής, και φάγη, και ζήση αιωνίως·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Όθεν Κύριος ο Θεός εξαπέστειλεν αυτόν εκ του παραδείσου της Εδέμ, διά να εργάζηται την γην εκ της οποίας ελήφθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Και εξεδίωξε τον Αδάμ· και κατά ανατολάς του παραδείσου της Εδέμ έθεσε τα Χερουβείμ, και την ρομφαίαν την φλογίνην, την περιστρεφομένην, διά να φυλάττωσι την οδόν του ξύλου της ζωής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Ο δε Αδάμ εγνώρισεν Εύαν την γυναίκα αυτού· και συνέλαβε, και εγέννησε τον Κάϊν· και είπεν, Απέκτησα άνθρωπον διά του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Και προσέτι εγέννησε τον αδελφόν αυτού τον Άβελ. Και ήτο ο Άβελ ποιμήν προβάτων, ο δε Κάϊν ήτο γεωργός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Και μεθ\' ημέρας προσέφερεν ο Κάϊν από των καρπών της γης προσφοράν προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Και ο Άβελ προσέφερε και αυτός από των πρωτοτόκων των προβάτων αυτού, και από των στεάτων αυτών. Και επέβλεψε με ευμένειαν Κύριος επί τον Άβελ και επί την προσφοράν αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'επί δε τον Κάϊν και επί την προσφοράν αυτού δεν επέβλεψε. Και ηγανάκτησεν ο Κάϊν σφόδρα, και εκατηφίασε το πρόσωπον αυτού');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Και είπε Κύριος προς τον Κάϊν, Διά τι ηγανάκτησας; και διά τι εκατηφίασε το πρόσωπόν σου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'αν συ πράττης καλώς, δεν θέλεις είσθαι ευπρόσδεκτος; και εάν δεν πράττης καλώς, εις την θύραν κείται η αμαρτία. Αλλ\' εις σε θέλει είσθαι η επιθυμία αυτού, και συ θέλεις εξουσιάζει επ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Και είπεν ο Κάϊν προς Άβελ τον αδελφόν αυτού, Ας υπάγωμεν εις την πεδιάδα· και ενώ ήσαν εν τη πεδιάδι, σηκωθείς ο Κάϊν κατά του αδελφού αυτού Άβελ εφόνευσεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Και είπε Κύριος προς τον Κάϊν, Που είναι Άβελ ο αδελφός σου; Ο δε είπε, Δεν εξεύρω· μη φύλαξ του αδελφού μου είμαι εγώ;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Και είπεν ο Θεός, Τι έκαμες; η φωνή του αίματος του αδελφού σου βοά προς εμέ εκ της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'και τώρα επικατάρατος να ήσαι από της γης, ήτις ήνοιξε το στόμα αυτής διά να δεχθή το αίμα του αδελφού σου εκ της χειρός σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'όταν εργάζησαι την γην, δεν θέλει εις το εξής σοι δώσει τον καρπόν αυτής· πλανήτης και φυγάς θέλεις είσθαι επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Και είπεν ο Κάϊν προς τον Κύριον, Η αμαρτία μου είναι μεγαλητέρα παρ\' ώστε να συγχωρηθή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'ιδού, με διώκεις σήμερον από προσώπου της γης, και από του προσώπου σου θέλω κρυφθή, και θέλω είσθαι πλανήτης και φυγάς επί της γής· και πας όστις με εύρη, θέλει με φονεύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Είπε δε προς αυτόν ο Κύριος, διά τούτο, πας όστις φονεύση τον Κάϊν, επταπλασίως θέλει τιμωρηθή. Και έβαλεν ο Κύριος σημείον εις τον Κάϊν, διά να μη φονεύση αυτόν πας όστις εύρη αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Και εξήλθεν ο Κάϊν από προσώπου του Κυρίου, και κατώκησεν εν τη γη Νωδ, προς ανατολάς της Εδέμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Εγνώρισε δε ο Κάϊν την γυναίκα αυτού, και συνέλαβε, και εγέννησε τον Ενώχ· έκτισε δε πόλιν, και εκάλεσε το όνομα της πόλεως κατά το όνομα του υιού αυτού, Ενώχ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Εγεννήθη δε εις τον Ενώχ ο Ιράδ· και Ιράδ εγέννησε τον Μεχουϊαήλ· και Μεχουϊαήλ εγέννησε τον Μεθουσαήλ· και Μεθουσαήλ εγέννησε τον Λάμεχ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Και έλαβεν εις εαυτόν ο Λάμεχ δύο γυναίκας· το όνομα της μιας, Αδά, και το όνομα της άλλης, Σιλλά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Και εγέννησεν η Αδά τον Ιαβάλ· ούτος ήτο πατήρ των κατοικούντων εν σκηναίς και τρεφόντων κτήνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Και το όνομα του αδελφού αυτού ήτο Ιουβάλ· ούτος ήτο πατήρ πάντων των παιζόντων κιθάραν και αυλόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Η Σιλλά δε και αυτή εγέννησε τον Θουβάλ-κάϊν, χαλκέα παντός εργαλείου χαλκού και σιδήρου· αδελφή δε του Θουβάλ-κάϊν ήτο η Νααμά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Και είπεν ο Λάμεχ προς τας γυναίκας εαυτού, Αδά και Σιλλά, Ακούσατε την φωνήν μου· γυναίκες του Λάμεχ, ακροασθήτε τους λόγους μου· επειδή άνδρα εφόνευσα εις πληγήν μου· και νέον εις μάστιγά μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'διότι ο μεν Κάϊν επταπλασίως θέλει εκδικηθή· ο δε Λάμεχ εβδομηκοντάκις επτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Εγνώρισε δε πάλιν ο Αδάμ την γυναίκα αυτού, και εγέννησεν υιόν, και εκάλεσε το όνομα αυτού Σηθ, λέγουσα, Ότι έδωκεν εις εμέ ο Θεός άλλο σπέρμα αντί του Άβελ, τον οποίον εφόνευσεν ο Κάϊν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Και εις τον Σηθ ομοίως εγεννήθη υιός· και εκάλεσε το όνομα αυτού Ενώς. Τότε έγεινεν αρχή να ονομάζωνται με το όνομα του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Τούτο είναι το βιβλίον της γενεαλογίας του ανθρώπου. Καθ\' ην ημέραν εποίησεν ο Θεός τον Αδάμ, κατ\' εικόνα Θεού εποίησεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Άρσεν και θήλυ εποίησεν αυτούς· και ευλόγησεν αυτούς, και εκάλεσε το όνομα αυτών, Αδάμ, καθ\' ην ημέραν εποίησεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Έζησε δε ο Αδάμ εκατόν τριάκοντα έτη, και εγέννησεν υιόν κατά την ομοίωσιν αυτού, κατά την εικόνα αυτού, και εκάλεσε το όνομα αυτού Σήθ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'και έγειναν αι ημέραι του Αδάμ, αφού εγέννησε τον Σηθ, οκτακόσια έτη· και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'και έγειναν πάσαι αι ημέραι του Αδάμ, τας οποίας έζησεν, εννεακόσια τριάκοντα έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Και έζησεν ο Σηθ εκατόν πέντε έτη, και εγέννησε τον Ενώς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'και έζησεν ο Σηθ αφού εγέννησε τον Ενώς, οκτακόσια επτά έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'έγειναν δε πάσαι αι ημέραι του Σηθ εννεακόσια δώδεκα έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Και έζησεν ο Ενώς ενενήκοντα έτη, και εγέννησε τον Καϊνάν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'έζησε δε ο Ενώς, αφού εγέννησε τον Καϊνάν, οκτακόσια δεκαπέντε έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'και έγειναν πάσαι αι ημέραι του Ενώς εννεακόσια πέντε έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Και έζησεν ο Καϊνάν εβδομήκοντα έτη, και εγέννησε τον Μααλαλεήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'έζησε δε ο Καϊνάν, αφού εγέννησε τον Μααλαλεήλ, οκτακόσια τεσσαράκοντα έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'και έγειναν πάσαι αι ημέραι του Καϊνάν εννεακόσια δέκα έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Και έζησεν ο Μααλαλεήλ εξήκοντα πέντε έτη, και εγέννησε τον Ιάρεδ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'έζησε δε ο Μααλαλεήλ, αφού εγέννησε τον Ιάρεδ, οκτακόσια τριάκοντα έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'και έγειναν πάσαι αι ημέραι του Μααλαλεήλ οκτακόσια ενενήκοντα πέντε έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Και έζησεν ο Ιάρεδ εκατόν εξήκοντα δύο έτη, και εγέννησε τον Ενώχ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'έζησε δε ο Ιάρεδ, αφού εγέννησε τον Ενώχ, οκτακόσια έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'και έγειναν πάσαι αι ημέραι του Ιάρεδ εννεακόσια εξήκοντα δύο έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Και έζησεν ο Ενώχ εξήκοντα πέντε έτη, και εγέννησε τον Μαθουσάλα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'και περιεπάτησεν ο Ενώχ μετά του Θεού, αφού εγέννησε τον Μαθουσάλα, τριακόσια έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'και έγειναν πάσαι αι ημέραι του Ενώχ τριακόσια εξήκοντα πέντε έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Και περιεπάτησεν ο Ενώχ μετά του Θεού, και δεν ευρίσκετο πλέον· διότι μετέθεσεν αυτόν ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Και έζησεν ο Μαθουσάλα εκατόν ογδοήκοντα επτά έτη, και εγέννησε τον Λάμεχ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'έζησε δε ο Μαθουσάλα, αφού εγέννησε τον Λάμεχ, επτακόσια ογδοήκοντα δύο έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'και έγειναν πάσαι αι ημέραι του Μαθουσάλα εννεακόσια εξήκοντα εννέα έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Έζησε δε ο Λάμεχ εκατόν ογδοήκοντα δύο έτη, και εγέννησεν υιόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'και εκάλεσε το όνομα αυτού Νώε, λέγων, Ούτος θέλει ανακουφίσει ημάς από του έργου ημών, και από του μόχθου των χειρών ημών, εξ αιτίας της γης την οποίαν κατηράσθη ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Έζησε δε ο Λάμεχ, αφού εγέννησε τον Νώε, πεντακόσια ενενήκοντα πέντε έτη, και εγέννησεν υιούς και θυγατέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'και έγειναν πάσαι αι ημέραι του Λάμεχ επτακόσια εβδομήκοντα επτά έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Και ο Νώε ήτο ηλικίας πεντακοσίων ετών· και εγέννησεν ο Νώε τον Σημ, τον Χαμ, και τον Ιάφεθ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Και ότε ήρχισαν οι άνθρωποι να πληθύνωνται επί του προσώπου της γης, και θυγατέρες εγεννήθησαν εις αυτούς,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'ιδόντες οι υιοί του Θεού τας θυγατέρας των ανθρώπων, ότι ήσαν ώραίαι, έλαβον εις εαυτούς γυναίκας εκ πασών όσας έκλεξαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Και είπε Κύριος, Δεν θέλει καταμείνει πάντοτε το πνεύμά μου μετά του ανθρώπου, διότι είναι σάρξ· αι ημέραι αυτού θέλουσιν είσθαι ακόμη εκατόν είκοσι έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Κατ\' εκείνας τας ημέρας ήσαν οι γίγαντες επί της γης, και έτι, ύστερον, αφού οι υιοί του Θεού εισήλθον εις τας θυγατέρας των ανθρώπων, και αύται ετεκνοποίησαν εις αυτούς· εκείνοι ήσαν οι δυνατοί, οι έκπαλαι άνδρες ονομαστοί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Και είδεν ο Κύριος ότι επληθύνετο η κακία του ανθρώπου επί της γης, και πάντες οι σκοποί των διαλογισμών της καρδίας αυτού ήσαν μόνον κακία πάσας τας ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Και μετεμελήθη ο Κύριος ότι εποίησε τον άνθρωπον επί της γης. και ελυπήθη εν τη καρδία αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Και είπεν ο Κύριος, Θέλω εξαλείψει τον άνθρωπον, τον οποίον εποίησα, από προσώπου της γής· από ανθρώπου έως κτήνους, έως ερπετού, και έως πτηνού του ουρανού· επειδή μετεμελήθην ότι εποίησα αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Ο δε Νώε εύρε χάριν ενώπιον Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Αύτη είναι η γενεαλογία του Νώε. Ο Νώε ήτο άνθρωπος δίκαιος, τέλειος μεταξύ των συγχρόνων αυτού· μετά του Θεού περιεπάτησεν ο Νώε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Και εγέννησεν ο Νώε τρεις υιούς, τον Σημ, τον Χαμ και τον Ιάφεθ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Διεφθάρη δε η γη ενώπιον του Θεού, και ενεπλήσθη η γη αδικίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Και είδεν ο Θεός την γην, και ιδού, ήτο διεφθαρμένη· διότι πάσα σαρξ είχε διαφθείρει την οδόν αυτής επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Και είπεν ο Θεός προς τον Νώε, Το τέλος πάσης σαρκός ήλθεν ενώπιόν μου, διότι η γη ενεπλήσθη αδικίας απ\' αυτών· και ιδού, θέλω εξολοθρεύσει αυτούς και την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Κάμε εις σεαυτόν κιβωτόν εκ ξύλων Γόφερ· κατά δωμάτια θέλεις κάμει την κιβωτόν, και θέλεις αλείψει αυτήν έσωθεν και έξωθεν με πίσσαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Και ούτω θέλεις κάμει αυτήν· το μεν μήκος της κιβωτού θέλει είσθαι τριακοσίων πηχών, το δε πλάτος αυτής πεντήκοντα πηχών, και το ύψος αυτής τριάκοντα πηχών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Στέγην θέλεις κάμει εις την κιβωτόν, και εις πήχην θέλεις τελειώσει αυτήν άνωθεν· και την θύραν της κιβωτού θέλεις βάλει εκ πλαγίων· κατώγαια, διώροφα, και τριώροφα θέλεις κάμει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Εγώ δε, ιδού, εγώ επιφέρω τον κατακλυσμόν των υδάτων επί της γης, διά να εξολοθρεύσω πάσαν σάρκα, έχουσαν εν εαυτή πνεύμα ζωής υποκάτω του ουρανού· παν ό,τι είναι επί της γης, θέλει αποθάνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Και θέλω στήσει την διαθήκην μου προς σέ· και θέλεις εισέλθει εις την κιβωτόν, συ, και οι υιοί σου, και η γυνή σου, και αι γυναίκες των υιών σου μετά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Και από παντός ζώου εκ πάσης σαρκός, ανά δύο εκ πάντων θέλεις εισάξει εις την κιβωτόν, διά να φυλάξης την ζωήν αυτών μετά σεαυτού· άρσεν και θήλυ θέλουσιν είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Από των πτηνών κατά το είδος αυτών, και από των κτηνών κατά το είδος αυτών, από πάντων των ερπετών της γης κατά το είδος αυτών, ανά δύο εκ πάντων θέλουσιν εισέλθει προς σε, διά να φυλάξης την ζωήν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Και συ λάβε εις σεαυτόν από παντός φαγητού το οποίον τρώγεται, και θέλεις συνάξει αυτό πλησίον σου· και θέλει είσθαι εις σε, και εις αυτά, προς τροφήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Και έκαμεν ο Νώε κατά πάντα όσα προσέταξεν εις αυτόν ο Θεός· ούτως έκαμε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Και είπε Κύριος προς τον Νώε, Είσελθε συ, και πας ο οίκός σου, εις την κιβωτόν· διότι σε είδον δίκαιον ενώπιόν μου εν τη γενεά ταύτη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'από πάντων των κτηνών των καθαρών λάβε εις σεαυτόν επτά επτά, άρσεν και το θήλυ αυτού· και από των κτηνών των μη καθαρών ανά δύο, άρσεν και το θήλυ αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'και από των πτηνών του ουρανού επτά επτά, άρσεν και θήλυ· διά να διατηρήσης σπέρμα επί προσώπου πάσης της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'επειδή έτι μετά επτά ημέρας εγώ φέρω βροχήν επί της γης τεσσαράκοντα ημέρας και τεσσαράκοντα νύκτας· και θέλω εξαλείψει από προσώπου της γης παν ό,τι υπάρχει, το οποίον εποίησα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Και έκαμεν ο Νώε κατά πάντα όσα προσέταξεν εις αυτόν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Ήτο δε ο Νώε εξακοσίων ετών, ότε έγεινεν ο κατακλυσμός των υδάτων επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Και εισήλθεν ο Νώε, και οι υιοί αυτού, και η γυνή αυτού, και αι γυναίκες των υιών αυτού μετ\' αυτού, εις την κιβωτόν, εξ αιτίας των υδάτων του κατακλυσμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Από των κτηνών των καθαρών, και από των κτηνών των μη καθαρών, και από των πτηνών, και από πάντων των ερπόντων επί της γης,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'δύο δύο εισήλθον προς τον Νώε εις την κιβωτόν, άρσεν και θήλυ, καθώς προσέταξεν ο Θεός εις τον Νώε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Και μετά τας επτά ημέρας, τα ύδατα του κατακλυσμού επήλθον επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Το εξακοσιοστόν έτος της ζωής του Νώε, τον δεύτερον μήνα, την δεκάτην εβδόμην ημέραν του μηνός, ταύτην την ημέραν εσχίσθησαν πάσαι αι πηγαί της μεγάλης αβύσσου, και οι καταρράκται των ουρανών ηνοίχθησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Και έγεινεν ο υετός επί της γης τεσσαράκοντα ημέρας και τεσσαράκοντα νύκτας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Κατά την αυτήν ταύτην ημέραν εισήλθεν ο Νώε, και οι υιοί του Νώε, Σημ και Χαμ και Ιάφεθ, και η γυνή του Νώε, και αι τρεις γυναίκες των υιών αυτού μετ\' αυτών, εις την κιβωτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'αυτοί, και πάντα τα ζώα κατά το είδος αυτών, και πάντα τα κτήνη κατά το είδος αυτών, και πάντα τα ερπετά τα έρποντα επί της γης κατά το είδος αυτών, και πάντα τα πτηνά κατά το είδος αυτών, και παν πτερωτόν παντός είδους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Και εισήλθον προς τον Νώε εις την κιβωτόν, δύο δύο από πάσης σαρκός ήτις έχει πνεύμα ζωής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Και τα εισερχόμενα, άρσεν και θήλυ από πάσης σαρκός, εισήλθον, καθώς προσέταξεν εις αυτόν ο Θεός· και έκλεισεν ο Κύριος την κιβωτόν επάνω αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Και έγεινεν ο κατακλυσμός τεσσαράκοντα ημέρας επί της γής· και επληθύνθησαν τα ύδατα, και εσήκωσαν την κιβωτόν, και υψώθη υπεράνω της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Και εκραταιούντο τα ύδατα, και επληθύνοντο σφόδρα επί της γής· και η κιβωτός εφέρετο επί της επιφανείας των υδάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Και τα ύδατα υπερεκραταιούντο σφόδρα επί της γής· και εσκεπάσθησαν πάντα τα όρη τα υψηλά τα υποκάτω παντός του ουρανού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Δεκαπέντε πήχας υπεράνω υψώθησαν τα ύδατα, και εσκεπάσθησαν τα όρη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Και απέθανε πάσα σαρξ κινουμένη επί της γης, των πτηνών και των κτηνών και των ζώων, και πάντων των ερπετών των ερπόντων επί της γης, και πας άνθρωπος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Εκ πάντων των όντων επί της ξηράς, πάντα όσα είχον πνοήν ζωής εις τους μυκτήρας αυτών, απέθανον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Και εξηλείφθη παν το υπάρχον επί του προσώπου της γης, από ανθρώπου έως κτήνους, έως ερπετού και έως πτηνού του ουρανού, και εξηλείφθησαν από της γής· έμενε δε μόνον ο Νώε, και όσα ήσαν μετ\' αυτού εν τη κιβωτώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Και εκραταιούντο τα ύδατα επί της γης εκατόν πεντήκοντα ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Και ενεθυμήθη ο Θεός τον Νώε, και πάντα τα ζώα, και πάντα τα κτήνη, τα μετ\' αυτού εν τη κιβωτώ· και διεβίβασεν ο Θεός άνεμον επί την γην, και τα ύδατα εστάθησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Και εκλείσθησαν αι πηγαί της αβύσσου, και οι καταρράκται του ουρανού, και εκρατήθη ο υετός από των ουρανών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Και εσύροντο τα ύδατα από της γης κατά συνέχειαν· και ωλιγόστευον τα ύδατα μετά τας εκατόν πεντήκοντα ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Και εκάθισεν η κιβωτός την δεκάτην εβδόμην του εβδόμου μηνός επί των ορέων Αραράτ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Τα δε ύδατα ωλιγόστευον κατά συνέχειαν έως του δεκάτου μηνός· την πρώτην του δεκάτου μηνός εφάνησαν αι κορυφαί των ορέων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Και μετά τεσσαράκοντα ημέρας ήνοιξεν ο Νώε την θυρίδα της κιβωτού, την οποίαν είχε κάμει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'και απέστειλε τον κόρακα, όστις εξελθών υπήγαινε και ήρχετο, εωσού εξηράνθησαν τα ύδατα από της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Και απέστειλε την περιστεράν κατόπιν αυτού, διά να ίδη αν έπαυσαν τα ύδατα από προσώπου της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'και μη ευρίσκουσα η περιστερά ανάπαυσιν των ποδών αυτής, επέστρεψε προς αυτόν εις την κιβωτόν, διότι τα ύδατα ήσαν επί του προσώπου πάσης της γής· και εκτείνας την χείρα αυτού, επίασεν αυτήν και εισήγαγεν αυτήν προς εαυτόν εις την κιβωτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Και ανέμεινεν έτι άλλας επτά ημέρας, και πάλιν απέστειλε την περιστεράν εκ της κιβωτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'και επέστρεψε προς αυτόν η περιστερά προς το εσπέρας, και ιδού, ήτο εν τω στόματι αυτής φύλλον ελαίας, απεσπασμένον· και εγνώρισεν ο Νώε ότι έπαυσαν τα ύδατα από της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Και ανέμεινεν έτι άλλας επτά ημέρας, και απέστειλε την περιστεράν· και δεν επανέστρεψε πλέον προς αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Κατά δε το εξακοσιοστόν πρώτον έτος του Νώε, την πρώτην του πρώτου μηνός, εξέλιπον τα ύδατα από της γής· και εσήκωσεν ο Νώε την στέγην της κιβωτού, και είδε, και ιδού, εξέλιπε το ύδωρ από προσώπου της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Και την εικοστήν εβδόμην ημέραν του δευτέρου μηνός εξηράνθη η γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'και ελάλησεν ο Θεός προς τον Νώε, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Έξελθε εκ της κιβωτού, συ, και η γυνή σου, και οι υιοί σου, και αι γυναίκες των υιών σου μετά σού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'πάντα τα ζώα τα μετά σου, από πάσης σαρκός, και πτηνά και κτήνη και παν ερπετόν έρπον επί της γης, εξάγαγε μετά σου, και ας πολυπλασιασθώσιν επί της γης, και ας αυξηνθώσι και ας πληθυνθώσιν επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Και εξήλθεν ο Νώε, και οι υιοί αυτού, και η γυνή αυτού, και αι γυναίκες των υιών αυτού μετ\' αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'πάντα τα ζώα, πάντα τα ερπετά και πάντα τα πτηνά, παν ό,τι κινείται επί της γης, κατά τα είδη αυτών, εξήλθον εκ της κιβωτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Και ωκοδόμησεν ο Νώε θυσιαστήριον εις τον Κύριον· και έλαβεν από παντός κτήνους καθαρού, και από παντός πτηνού καθαρού, και προσέφερεν ολοκαυτώματα επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Και ωσφράνθη Κύριος οσμήν ευωδίας· και είπε Κύριος εν τη καρδία αυτού, Δεν θέλω καταρασθή πλέον την γην εξ αιτίας του ανθρώπου· διότι ο λογισμός της καρδίας του ανθρώπου είναι κακός εκ νηπιότητος αυτού· ουδέ θέλω πατάξει πλέον πάντα τα ζώντα, καθώς έκαμον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'εν όσω μένει γη, σπορά και θερισμός, και ψύχος και καύμα, και θέρος και χειμών, και ημέρα και νυξ, δεν θέλουσι παύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Και ευλόγησεν ο Θεός τον Νώε και τους υιούς αυτού· και είπε προς αυτούς, Αυξάνεσθε και πληθύνεσθε, και γεμίσατε την γήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'και ο φόβος σας και ο τρόμος σας θέλει είσθαι επί πάντα τα ζώα της γης, και επί πάντα τα πτηνά του ουρανού, επί παν ό,τι έρπει επί της γης, και επί πάντας τους ιχθύας της θαλάσσης· εις τας χείρας σας εδόθησαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'παν κινούμενον, το οποίον ζη, θέλει είσθαι εις σας προς τροφήν· ως τον χλωρόν χόρτον έδωκα τα πάντα εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'κρέας όμως με την ζωήν αυτού, με το αίμα αυτού, δεν θέλετε φάγει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'και εξάπαντος το αίμα σας, το αίμα της ζωής σας, θέλω εκζητήσει εκ της χειρός παντός ζώου θέλω εκζητήσει αυτό, και εκ της χειρός του ανθρώπου· εκ της χειρός παντός αδελφού αυτού θέλω εκζητήσει την ζωήν του ανθρώπου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'όστις χύση αίμα ανθρώπου, υπό ανθρώπου θέλει χυθή το αίμα αυτού· διότι κατ\' εικόνα Θεού εποίησεν ο Θεός τον άνθρωπον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'σεις δε αυξάνεσθε και πληθύνεσθε, πολλαπλασιάζεσθε επί της γης, και πληθύνεσθε επ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Και είπεν ο Θεός προς τον Νώε και προς τους υιούς αυτού μετ\' αυτού, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Και εγώ, ιδού, στήνω την διαθήκην μου προς εσάς, και προς το σπέρμα σας ύστερον από σάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'και προς παν έμψυχον ζώον, το οποίον είναι με σας, εκ των πτηνών, εκ των κτηνών και εκ πάντων των ζώων της γης, τα οποία είναι με σάς· από παντός του εξελθόντος εκ της κιβωτού, έως παντός ζώου της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'και στήνω την διαθήκην μου προς εσάς· και δεν θέλει πλέον εξολοθρευθή πάσα σαρξ από των υδάτων του κατακλυσμού· ουδέ θέλει είσθαι πλέον κατακλυσμός διά να φθείρη την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Και είπεν ο Θεός, Τούτο είναι το σημείον της διαθήκης, την οποίαν εγώ κάμνω μεταξύ εμού και υμών και παντός εμψύχου ζώου το οποίον είναι με σας, εις γενεάς αιωνίους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Θέτω το τόξον μου εν τη νεφέλη, και θέλει είσθαι εις σημείον διαθήκης μεταξύ εμού και της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'και όταν συννεφώσω νεφέλην επί της γης, θέλει φανή το τόξον εν τη νεφέλη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'και θέλω ενθυμηθή την διαθήκην μου, την μεταξύ εμού και υμών, και παντός εμψύχου ζώου εκ πάσης σαρκός· και τα ύδατα δεν θέλουσιν είσθαι πλέον εις κατακλυσμόν διά να εξαλείψωσι πάσαν σάρκα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'και το τόξον θέλει είσθαι εν τη νεφέλη· και θέλω βλέπει αυτό, διά να ενθυμώμαι την παντοτεινήν διαθήκην την μεταξύ Θεού και παντός εμψύχου ζώου εκ πάσης σαρκός ήτις είναι επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Και είπεν ο Θεός προς τον Νώε, Τούτο είναι το σημείον της διαθήκης, την οποίαν έστησα μεταξύ εμού και πάσης σαρκός ήτις είναι επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Ήσαν δε οι υιοί του Νώε, οι εξελθόντες εκ της κιβωτού, Σημ και Χαμ και Ιάφεθ. Ο δε Χαμ ήτο πατήρ του Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Οι τρεις ούτοι είναι οι υιοί του Νώε, και εκ τούτων διεσπάρησαν εις πάσαν την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Και ήρχισεν ο Νώε να ήναι γεωργός και εφύτευσεν αμπελώνα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'και έπιεν εκ του οίνου και εμεθύσθη, και εγυμνώθη εν τη σκηνή αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Και είδεν ο Χαμ, ο πατήρ του Χαναάν, την γύμνωσιν του πατρός αυτού· και ανήγγειλε τούτο προς τους δύο αδελφούς αυτού έξω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Και λαβόντες ο Σημ και ο Ιάφεθ το ένδυμα, επέθηκαν αυτό επί τα δύο αυτών νώτα· και βαδίσαντες οπισθόνωτα, εσκέπασαν την γύμνωσιν του πατρός αυτών· και τα πρόσωπα αυτών ήσαν προς τα οπίσω, και την γύμνωσιν του πατρός αυτών δεν είδον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Ανανήψας δε ο Νώε από του οίνου αυτού, έμαθεν όσα έκαμεν εις αυτόν ο υιός αυτού ο νεώτερος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Και είπεν, Επικατάρατος ο Χαναάν· δούλος των δούλων θέλει είσθαι εις τους αδελφούς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Και είπεν, Ευλογητός Κύριος ο Θεός του Σημ. Και ο Χαναάν θέλει είσθαι δούλος εις αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'ο Θεός θέλει πλατύνει τον Ιάφεθ, και θέλει κατοικήσει εν ταις σκηναίς του Σημ, ο δε Χαναάν θέλει είσθαι δούλος εις αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Και έζησεν ο Νώε μετά τον κατακλυσμόν τριακόσια πεντήκοντα έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Και έγειναν πάσαι αι ημέραι του Νώε εννεακόσια πεντήκοντα έτη· και απέθανε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Και αύται είναι αι γενεαλογίαι των υιών του Νώε, Σημ, Χαμ και Ιάφεθ· και εγεννήθησαν εις αυτούς υιοί μετά τον κατακλυσμόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Οι υιοί του Ιάφεθ ήσαν Γομέρ, και Μαγώγ, και Μαδαΐ, και Ιαυάν, και Θουβάλ, και Μεσέχ, και Θειράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Και οι υιοί του Γομέρ, Ασχενάζ, και Ριφάθ, και Θωγαρμά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Και οι υιοί του Ιαυάν, Ελεισά, και Θαρσείς, Κιττείμ, και Δωδανείμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Εκ τούτων εμοιράσθησαν αι νήσοι των εθνών εις τους τόπους αυτών· εκάστου κατά την γλώσσαν αυτού, κατά τας φυλάς αυτών, εις τα έθνη αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Και οι υιοί του Χαμ, Χούς, και Μισραΐμ, και Φούθ, και Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Και οι υιοί του Χούς, Σεβά, και Αβιλά, και Σαβθά, και Ρααμά, και Σαβθεκά· και οι υιοί του Ρααμά, Σεβά, και Δαιδάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Και ο Χούς εγέννησε τον Νεβρώδ· ούτος ήρχισε να ήναι ισχυρός επί της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'αυτός ήτο ισχυρός κυνηγός ενώπιον του Κυρίου· διά τούτο λέγεται, Ως Νεβρώδ, ισχυρός κυνηγός ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'και η αρχή της βασιλείας αυτού εστάθη Βαβυλών, και Ερέχ, και Αχάδ, και Χαλνέ, εν τη γη Σενναάρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Εκ της γης εκείνης εξήλθεν ο Ασσούρ, και ωκοδόμησε την Νινευή, και την πόλιν Ρεχωβώθ, και την Χαλάχ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'και την Ρεσέν μεταξύ της Νινευή και της Χαλάχ· αύτη είναι η πόλις η μεγάλη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Και ο Μισραΐμ εγέννησε τους Λουδείμ, και τους Αναμείμ, και τους Λεαβείμ, και τους Ναφθουχείμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'και τους Πατρουσείμ, και τους Χασλουχείμ, εκ των οποίων εξήλθον οι Φιλισταίοι, και τους Χαφθορείμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Και ο Χαναάν εγέννησε τον Σιδώνα, πρωτότοκον αυτού, και τον Χετταίον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'και τον Ιεβουσαίον, και τον Αμορραίον, και τον Γεργεσαίον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'και τον Ευαίον, και τον Αρουχαίον, και τον Ασενναίον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'και τον Αρβάδιον, και τον Σαμαραίον, και τον Αμαθαίον. Και μετά τούτο διεσπάρησαν αι φυλαί των Χαναναίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Και ήσαν τα όρια των Χαναναίων από Σιδώνος, καθώς υπάγει τις εις Γέραρα, έως Γάζης, και καθώς υπάγει τις εις Σόδομα και Γόμορρα, και Αδαμά, και Σεβωείμ, έως Λασά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Ούτοι είναι οι υιοί του Χαμ, κατά τας φυλάς αυτών, κατά τας γλώσσας αυτών, εις τους τόπους αυτών, εις τα έθνη αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Και εις τον Σημ, τον πατέρα πάντων των υιών του Έβερ, τον αδελφόν Ιάφεθ του μεγαλητέρου, εγεννήθησαν και εις αυτόν υιοί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Υιοί του Σημ ήσαν Ελάμ, και Ασσούρ, και Αρφαξάδ, και Λούδ, και Αράμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Και οι υιοί του Αράμ, Ουζ, και Ουλ, και Γεθέρ, και Μας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Και ο Αρφαξάδ εγέννησε τον Σαλά· και ο Σαλά εγέννησε τον Έβερ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Και εις τον Έβερ εγεννήθησαν δύο υιοί· το όνομα του ενός, Φαλέγ· διότι εν ταις ημέραις αυτού διεμερίσθη η γή· και το όνομα του αδελφού αυτού, Ιοκτάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Και ο Ιοκτάν εγέννησε τον Αλμωδάδ, και τον Σαλέφ, και τον Ασαρμαβέθ, και τον Ιαράχ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'και τον Αδωράμ, και τον Ουζάλ, και τον Δικλά,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'και τον Οβάλ, και τον Αβιμαήλ, και τον Σεβά,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'και τον Οφείρ, και τον Αβιλά, και τον Ιωβάβ· πάντες ούτοι ήσαν υιοί του Ιοκτάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Και η κατοικία αυτών ήτο από Μησά, καθώς υπάγει τις εις Σεφαρά, όρος της Ανατολής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Ούτοι είναι οι υιοί του Σημ, κατά τας φυλάς αυτών, κατά τας γλώσσας αυτών, εις τους τόπους αυτών, κατά τα έθνη αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Αύται είναι αι φυλαί των υιών του Νώε, κατά τας γενεάς αυτών, εις τα έθνη αυτών· και εκ τούτων διεσπάρησαν τα έθνη επί της γης μετά τον κατακλυσμόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Και ήτο πάσα η γη μιας γλώσσης και μιας φωνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Και ότε εκίνησαν από της ανατολής, εύρον πεδιάδα εν τη γη Σενναάρ· και κατώκησαν εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Και είπεν ο εις προς τον άλλον, Έλθετε, ας κάμωμεν πλίνθους, και ας ψήσωμεν αυτάς εν πυρί· και εχρησίμευσεν εις αυτούς η μεν πλίνθος αντί πέτρας, η δε άσφαλτος εχρησίμευσεν εις αυτούς αντί πηλού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Και είπον, Έλθετε, ας οικοδομήσωμεν εις εαυτούς πόλιν και πύργον, του οποίου η κορυφή να φθάνη έως του ουρανού· και ας αποκτήσωμεν εις εαυτούς όνομα, μήπως διασπαρώμεν επί του προσώπου πάσης της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Κατέβη δε ο Κύριος διά να ίδη την πόλιν και τον πύργον, τον οποίον ωκοδόμησαν οι υιοί των ανθρώπων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Και είπεν ο Κύριος, Ιδού, εις λαός, και πάντες έχουσι μίαν γλώσσαν, και ήρχισαν να κάμνωσι τούτο· και τώρα δεν θέλει εμποδισθή εις αυτούς παν ό,τι σκοπεύουσι να κάμωσιν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'έλθετε, ας καταβώμεν και ας συγχύσωμεν εκεί την γλώσσαν αυτών, διά να μη εννοή ο εις του άλλου την γλώσσαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Και διεσκόρπισεν αυτούς ο Κύριος εκείθεν επί του προσώπου πάσης της γής· και έπαυσαν να οικοδομώσι την πόλιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Διά τούτο ωνομάσθη το όνομα αυτής Βαβέλ· διότι εκεί συνέχεεν ο Κύριος την γλώσσαν πάσης της γής· και εκείθεν διεσκόρπισεν αυτούς ο Κύριος επί το πρόσωπον πάσης της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Αύτη είναι η γενεαλογία του Σημ. Ο Σημ ήτο ετών εκατόν, ότε εγέννησε τον Αρφαξάδ δύο έτη μετά τον κατακλυσμόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'και έζησεν ο Σημ, αφού εγέννησε τον Αρφαξάδ, πεντακόσια έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Και ο Αρφαξάδ έζησε τριάκοντα πέντε έτη, και εγέννησε τον Σαλά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'και έζησεν ο Αρφαξάδ, αφού εγέννησε τον Σαλά, τετρακόσια τρία έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Και ο Σαλά έζησε τριάκοντα έτη, και εγέννησε τον Εβερ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'και έζησεν ο Σαλά, αφού εγέννησε τον Έβερ, τετρακόσια τρία έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Και έζησεν ο Έβερ τριάκοντα τέσσαρα έτη, και εγέννησε τον Φαλέγ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'και έζησεν ο Έβερ, αφού εγέννησε τον Φαλέγ, τετρακόσια τριάκοντα έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Και έζησεν ο Φαλέγ τριάκοντα έτη, και εγέννησε τον Ραγαύ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'και έζησεν ο Φαλέγ, αφού εγέννησε τον Ραγαύ, διακόσια εννέα έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Και έζησεν ο Ραγαύ τριάκοντα δύο έτη, και εγέννησε τον Σερούχ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'και έζησεν ο Ραγαύ, αφού εγέννησε τον Σερούχ, διακόσια επτά έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Και έζησεν ο Σερούχ τριάκοντα έτη, και εγέννησε τον Ναχώρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'και έζησεν ο Σερούχ, αφού εγέννησε τον Ναχώρ, διακόσια έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Και έζησεν ο Ναχώρ εικοσιεννέα έτη, και εγέννησε τον Θάρα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'και έζησεν ο Ναχώρ, αφού εγέννησε τον Θάρα, εκατόν δεκαεννέα έτη, και εγέννησεν υιούς και θυγατέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Και έζησεν ο Θάρα εβδομήκοντα έτη, και εγέννησε τον Άβραμ, τον Ναχώρ, και τον Αρράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Και αύτη είναι η γενεαλογία του Θάρα· ο Θάρα εγέννησε τον Άβραμ, τον Ναχώρ, και τον Αρράν· και ο Αρράν εγέννησε τον Λωτ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Και απέθανεν ο Αρράν ενώπιον Θάρα του πατρός αυτού εν τω τόπω της γεννήσεως αυτού, εν Ουρ των Χαλδαίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Και έλαβον ο Άβραμ και ο Ναχώρ εις εαυτούς γυναίκας· το όνομα της γυναικός του Άβραμ ήτο Σάρα· και το όνομα της γυναικός του Ναχώρ, Μελχά, θυγάτηρ του Αρράν, πατρός Μελχά, και πατρός Ιεσχά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Η δε Σάρα ήτο στείρα, δεν είχε τέκνον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Και έλαβεν ο Θάρα Άβραμ τον υιόν αυτού και Λωτ τον υιόν του Αρράν εγγονόν εαυτού, και Σάραν την εαυτού νύμφην, την γυναίκα Άβραμ του υιού αυτού· και εξήλθον ομού από της Ουρ των Χαλδαίων, διά να υπάγωσιν εις την γην Χαναάν· και ήλθον έως Χαρράν και κατώκησαν εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Και έγειναν αι ημέραι του Θάρα διακόσια πέντε έτη· και απέθανεν ο Θάρα εν Χαρράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Ο δε Κύριος είπε προς τον Άβραμ, Έξελθε εκ της γης σου, και εκ της συγγενείας σου, και εκ του οίκου του πατρός σου, εις την γην την οποίαν θέλω σοι δείξει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'και θέλω σε κάμει εις έθνος μέγα· και θέλω σε ευλογήσει, και θέλω μεγαλύνει το όνομά σου· και θέλεις είσθαι εις ευλογίαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'και θέλω ευλογήσει τους ευλογούντάς σε, και τους καταρωμένους σε θέλω καταρασθή· και θέλουσιν ευλογηθή εν σοι πάσαι αι φυλαί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Και υπήγεν ο Άβραμ, καθώς είπε προς αυτόν ο Κύριος· και μετ\' αυτού υπήγε και ο Λώτ· ο δε Άβραμ ήτο ηλικίας εβδομήκοντα πέντε ετών, ότε εξήλθεν από Χαρράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Και έλαβεν ο Άβραμ Σάραν την γυναίκα αυτού, και Λωτ τον υιόν του αδελφού αυτού, και πάντα τα υπάρχοντα αυτών όσα είχον αποκτήσει, και τους ανθρώπους τους οποίους είχον αποκτήσει εν Χαρράν, και εξήλθον διά να υπάγωσιν εις την γην Χαναάν· και ήλθον εις την γην Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Και διεπέρασεν ο Άβραμ την γην εκείνην έως του τόπου Συχέμ, έως της δρυός Μορέχ· οι δε Χαναναίοι τότε κατώκουν εν τη γη ταύτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Και εφάνη ο Κύριος εις τον Άβραμ και είπεν, Εις το σπέρμα σου θέλω δώσει την γην ταύτην. Και ωκοδόμησεν εκεί θυσιαστήριον εις τον Κύριον, όστις εφάνη εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Και εκείθεν μετέβη προς το όρος, το κατά ανατολάς της Βαιθήλ, και έστησε την σκηνήν αυτού έχων την Βαιθήλ προς δυσμάς και την Γαί προς ανατολάς· και ωκοδόμησεν εκεί θυσιαστήριον εις τον Κύριον, και επεκαλέσθη το όνομα του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Και μετεσκήνωσεν ο Άβραμ, οδοιπορών και προχωρών προς μεσημβρίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Έγεινε δε πείνα εν τη γη ταύτη· και κατέβη ο Άβραμ εις την Αίγυπτον διά να παροικήση εκεί· διότι η πείνα ήτο βαρεία εν τη γη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Και ότε επλησίαζε να εισέλθη εις την Αίγυπτον, είπε προς Σάραν την γυναίκα αυτού, Ιδού, γνωρίζω ότι είσαι γυνή ευειδής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'θέλει συμβή λοιπόν, ώστε καθώς σε ίδωσιν οι Αιγύπτιοι, θέλουσιν ειπεί, Γυνή αυτού είναι αύτη· και θέλουσι φονεύσει εμέ, σε δε θέλουσι φυλάξει ζώσαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Ειπέ λοιπόν, ότι είσαι αδελφή μου, διά να γείνη καλόν εις εμέ εξ αιτίας σου, και να φυλαχθή η ζωή μου διά σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Και ότε εισήλθεν ο Άβραμ εις την Αίγυπτον, είδον οι Αιγύπτιοι την γυναίκα ότι ήτο ώραία σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Και οι άρχοντες του Φαραώ είδον αυτήν, και επήνεσαν αυτήν προς τον Φαραώ· και ελήφθη η γυνή εις την οικίαν του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Τον δε Άβραμ μετεχειρίσθησαν καλώς δι\' αυτήν· και είχε πρόβατα και βόας και όνους και δούλους και δούλας και όνους θηλυκάς και καμήλους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Και επέφερεν ο Κύριος επί τον Φαραώ και επί τον οίκον αυτού πληγάς μεγάλας εξ αιτίας Σάρας της γυναικός του Άβραμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Εκάλεσε δε ο Φαραώ τον Άβραμ, και είπε, Τι είναι τούτο, το οποίον έκαμες εις εμέ; διά τι δεν μ\' εφανέρωσας ότι αύτη είναι γυνή σου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'διά τι είπας, Αδελφή μου είναι αύτη; και έλαβον αυτήν εις εμαυτόν διά γυναίκα· και τώρα, ιδού η γυνή σου· λάβε αυτήν, και ύπαγε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Και διώρισεν ο Φαραώ ανθρώπους εις αυτόν· και συμπροέπεμψαν αυτόν, και την γυναίκα αυτού και πάντα όσα είχε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Ανέβη δε ο Άβραμ εξ Αιγύπτου, αυτός και η γυνή αυτού, και πάντα όσα είχε, και ο Λωτ μετ\' αυτού, προς μεσημβρίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Και ο Άβραμ ήτο πλούσιος σφόδρα εις κτήνη, εις αργύριον και εις χρυσίον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Και υπήγεν οδεύων από μεσημβρίας έως Βαιθήλ έως του τόπου όπου ήτο η σκηνή αυτού το πρότερον μεταξύ Βαιθήλ και Γαί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'εις τον τόπον του θυσιαστηρίου, το οποίον είχε κάμει εκεί καταρχάς· και επεκαλέσθη εκεί ο Άβραμ το όνομα του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Και ο Λωτ ακόμη, ο συμπορευόμενος μετά του Άβραμ, είχε πρόβατα και βόας και σκηνάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Και δεν εχώρει αυτούς η γη διά να κατοικώσιν ομού· διότι ήσαν τα υπάρχοντα αυτών πολλά, και δεν ηδύναντο να κατοικώσιν ομού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Και συνέβη έρις μεταξύ των ποιμένων των κτηνών του Άβραμ και των ποιμένων των κτηνών του Λώτ· οι δε Χαναναίοι και οι Φερεζαίοι κατώκουν τότε την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Είπε δε ο Άβραμ προς τον Λωτ, Ας μη ήναι, παρακαλώ, έρις μεταξύ εμού και σου και μεταξύ των ποιμένων μου και των ποιμένων σου· διότι αδελφοί είμεθα ημείς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'δεν είναι πάσα η γη έμπροσθέν σου; διαχωρίσθητι λοιπόν απ\' εμού· εάν συ υπάγης εις τα αριστερά, εγώ υπάγω εις τα δεξιά· και εάν συ εις τα δεξιά, εγώ εις τα αριστερά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Και υψώσας ο Λωτ τους οφθαλμούς αυτού, είδε πάσαν την περίχωρον του Ιορδάνου, ότι εποτίζετο όλη προ του να καταστρέψη ο Κύριος τα Σόδομα και τα Γόμορρα, ως παράδεισος του Κυρίου, ως η γη της Αιγύπτου, έως να υπάγη τις εις Σηγώρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Και έκλεξεν εις εαυτόν ο Λωτ πάσαν την περίχωρον του Ιορδάνου· και μετεσκήνωσεν ο Λωτ προς ανατολάς, και διεχωρίσθησαν ο εις από του άλλου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Ο μεν Άβραμ κατώκησεν εν τη γη Χαναάν· ο δε Λωτ κατώκησε μεταξύ των πόλεων της περιχώρου, και έστησε τας σκηνάς αυτού έως Σοδόμων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Οι δε άνθρωποι των Σοδόμων ήσαν κακοί και αμαρτωλοί σφόδρα ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Και είπε Κύριος προς τον Άβραμ, αφού διεχωρίσθη ο Λωτ απ\' αυτού, Ύψωσον τώρα τους οφθαλμούς σου, και ιδέ από του τόπου όπου είσαι, προς άρκτον και μεσημβρίαν και ανατολήν και δύσιν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'διότι πάσαν την γην την οποίαν βλέπεις, εις σε θέλω δώσει αυτήν και εις το σπέρμα σου έως αιώνος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'και θέλω καταστήσει το σπέρμα σου ως την άμμον της γής· ώστε εάν δύναταί τις να εξαριθμήση την άμμον της γης, θέλει αριθμηθή και το σπέρμα σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Σηκωθείς διόδευσον την γην εις τε το μήκος αυτής και εις το πλάτος αυτής· διότι εις σε θέλω δώσει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Και εσήκωσε την σκηνήν αυτού ο Άβραμ, και ελθών κατώκησε πλησίον των δρυών Μαμβρή, αίτινες είναι εν Χεβρών, και ωκοδόμησεν εκεί θυσιαστήριον εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Επί των ημερών δε του Αμαρφέλ βασιλέως Σενναάρ, του Αριώχ βασιλέως Ελλασάρ, του Χοδολλογομόρ βασιλέως Ελάμ, και του Θαργάλ βασιλέως εθνών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'έκαμον αυτοί πόλεμον μετά του Βερά βασιλέως Σοδόμων, και του Βαρσά βασιλέως Γομόρρων, του Σενναάβ βασιλέως Αδαμά, και του Σεμοβόρ βασιλέως Σεβωείμ, και του βασιλέως της Βελά· αύτη είναι η Σηγώρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Πάντες ούτοι ηνώθησαν ομού εν τη κοιλάδι Σιδδίμ ήτις είναι η αλμυρά θάλασσα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Δώδεκα έτη εδούλευον εις τον Χοδολλογομόρ· εν δε τω δεκάτω τρίτω απεστάτησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Και εν τω δεκάτω τετάρτω έτει ήλθεν ο Χοδολλογομόρ και οι βασιλείς οι μετ\' αυτού, και επάταξαν τους Ραφαείμ εν Ασταρώθ-καρναΐμ, και τους Ζουζείμ εν Αμ, και τους Εμμαίους εν Σαυή-κιριαθαΐμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'και τους Χορραίους εν τω όρει αυτών Σηείρ έως της πεδιάδος Φαράν, ήτις είναι εν τη ερήμω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Επέστρεψαν δε και ήλθον εις την Εν-μισπάτ ήτις είναι η Κάδης· και επάταξαν πάντα τον τόπον του Αμαλήκ, και τους Αμορραίους τους κατοικούντας εν Ασασών-θαμάρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Εξήλθε δε ο βασιλεύς των Σοδόμων, και ο βασιλεύς των Γομόρρων, και ο βασιλεύς της Αδαμά, και ο βασιλεύς των Σεβωείμ, και ο βασιλεύς της Βελά, ήτις είναι η Σηγώρ· και συνεκρότησαν μάχην μετ\' αυτών εν τη κοιλάδι Σιδδίμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'μετά του Χοδολλογομόρ βασιλέως Ελάμ, και του Θαργάλ βασιλέως εθνών, και του Αμραφέλ βασιλέως Σενναάρ, και του Αριώχ βασιλέως Ελλασάρ· τέσσαρες βασιλείς προς πέντε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Η δε κοιλάς Σιδδίμ ήτο πλήρης φρεάτων ασφάλτου· ετράπησαν δε εις φυγήν οι βασιλείς των Σοδόμων και των Γομόρρων και έπεσον εκεί· οι δε εναπολειφθέντες έφυγον εις το όρος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Και έλαβον πάντα τα υπάρχοντα των Σοδόμων και των Γομόρρων και πάσαν αυτών την ζωοτροφίαν, και ανεχώρησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Έλαβον δε και τον Λωτ υιόν του αδελφού του Άβραμ, όστις κατώκει εν Σοδόμοις, και τα υπάρχοντα αυτού, και ανεχώρησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Υπήγε δε τις εκ των διασωθέντων και απήγγειλε τούτο προς τον Άβραμ τον Εβραίον, όστις κατώκει πλησίον των δρυών Μαμβρή του Αμορραίου, αδελφού του Εσχώλ, και αδελφού του Ανήρ, οίτινες ήσαν σύμμαχοι του Άβραμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Ακούσας δε ο Άβραμ ότι ηχμαλωτίσθη ο αδελφός αυτού, εφώπλισε τριακοσίους δεκαοκτώ εκ των δούλων αυτού, των γεννηθέντων εν τη οικία αυτού, και κατεδίωξεν οπίσω αυτών έως Δαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Και διαιρέσας τους εαυτού ώρμησε κατ\' αυτών την νύκτα, αυτός και οι δούλοι αυτού, και επάταξεν αυτούς, και κατεδίωξεν αυτούς έως Χοβά ήτις είναι κατά τα αριστερά της Δαμασκού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Και επανέφερε πάντα τα υπάρχοντα και έτι επανέφερε Λωτ τον αδελφόν αυτού και τα υπάρχοντα αυτού, έτι δε και τας γυναίκας και τον λαόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Εξήλθε δε ο βασιλεύς των Σοδόμων εις συνάντησιν αυτού, αφού επέστρεψεν από της καταστροφής του Χοδολλογομόρ και των βασιλέων των μετ\' αυτού, εν τη κοιλάδι Σαυή ήτις είναι η κοιλάς του βασιλέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Και ο Μελχισεδέκ βασιλεύς Σαλήμ έφερεν έξω άρτον και οίνον· ήτο δε ιερεύς του Θεού του Υψίστου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Και ευλόγησεν αυτόν και είπεν, Ευλογημένος ο Άβραμ παρά του Θεού του Υψίστου, όστις έκτισε τον ουρανόν και την γήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'και ευλογητός ο Θεός ο Ύψιστος όστις παρέδωκε τους εχθρούς σου εις την χείρα σου. Και Άβραμ έδωκεν εις αυτόν δέκατον από πάντων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Και είπεν ο βασιλεύς των Σοδόμων προς τον Άβραμ, Δος μοι τους ανθρώπους, τα δε υπάρχοντα λάβε εις σεαυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Είπε δε ο Άβραμ προς τον βασιλέα των Σοδόμων, Εγώ ύψωσα την χείρα μου προς Κύριον, τον Θεόν τον Ύψιστον, όστις έκτισε τον ουρανόν και την γην,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'ότι δεν θέλω λάβει από πάντων των ιδικών σου από κλωστής έως λωρίου υποδήματος, διά να μη είπης, Εγώ επλούτισα τον Αβραμ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'εκτός μόνον εκείνου το οποίον έφαγον οι νέοι, και της μερίδος των ανθρώπων των ελθόντων μετ\' εμού, του Ανήρ του Εσχώλ και του Μαμβρή, ούτοι ας λάβωσι την μερίδα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Μετά τα πράγματα ταύτα έγεινε λόγος Κυρίου προς τον Άβραμ εν οράματι, λέγων, Μη φοβού, Αβραμ· εγώ είμαι ο υπερασπιστής σου, ο μισθός σου θέλει είσθαι πολύς σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Και είπεν ο Άβραμ, Δέσποτα Κύριε, τι θέλεις δώσει εις εμέ, ενώ εγώ απέρχομαι άτεκνος, ο δε κληρονόμος της οικίας μου είναι ούτος ο εκ Δαμασκού Ελιέζερ;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'είπε προσέτι ο Άβραμ, Ιδού, δεν έδωκας εις εμέ σπέρμα· και ιδού, οικέτης μου θέλει με κληρονομήσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Και ιδού, λόγος Κυρίου έγεινε προς αυτόν, λέγων, Δεν θέλει σε κληρονομήσει ούτος· αλλ\' εκείνος όστις θέλει εξέλθει εκ των σπλάγχνων σου, αυτός θέλει σε κληρονομήσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Και έφερεν αυτόν έξω και είπεν, Ανάβλεψον τώρα εις τον ουρανόν και αρίθμησον τα άστρα, εάν δύνασαι να εξαριθμήσης αυτά· και είπε προς αυτόν, Ούτω θέλει είσθαι το σπέρμα σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Και επίστευσεν εις τον Κύριον· και ελογίσθη εις αυτόν εις δικαιοσύνην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Και είπε προς αυτόν, Εγώ είμαι ο Κύριος όστις σε εξήγαγον εκ της Ουρ των Χαλδαίων, διά να σοι δώσω την γην ταύτην εις κληρονομίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Ο δε είπε, Δέσποτα Κύριε, Πόθεν να γνωρίσω ότι θέλω κληρονομήσει αυτήν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Και είπε προς αυτόν, Λάβε μοι δάμαλιν τριών ετών, και αίγα τριών ετών, και κριόν τριών ετών, και τρυγόνα, και περιστεράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Και έλαβεν εις αυτόν πάντα ταύτα, και διέσχισεν αυτά εις το μέσον, και έθεσεν έκαστον τμήμα απέναντι του ομοίου αυτού· τα πτηνά όμως δεν διέσχισε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Κατέβησαν δε όρνεα επί τα πτώματα, και ο Άβραμ εδίωξεν αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Περί δε την δύσιν του ηλίου, επέπεσεν έκστασις επί τον Αβραμ· και ιδού, φόβος σκοτεινός μέγας επιπίπτει επ\' αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Και είπεν ο Κύριος προς τον Άβραμ, Έξευρε βεβαίως ότι το σπέρμα σου θέλει παροικήσει εν γη ουχί εαυτών, και θέλουσι δουλώσει αυτούς, και θέλουσι καταθλίψει αυτούς, τετρακόσια έτη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'το έθνος όμως, εις το οποίον θέλουσι δουλωθή, εγώ θέλω κρίνει· μετά δε ταύτα θέλουσιν εξέλθει με μεγάλα υπάρχοντα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'συ δε θέλεις απέλθει προς τους πατέρας σου εν ειρήνη· θέλεις ενταφιασθή εν γήρατι καλώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'εν δε τη τετάρτη γενεά θέλουσιν επιστρέψει εδώ· διότι ακόμη δεν ανεπληρώθη η ανομία των Αμορραίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Ότε δε ο ήλιος έδυσε και έγεινε πυκνόν σκότος, ιδού, κάμινος καπνίζουσα και λαμπάς πυρός ήτις διεπέρασε μεταξύ των διχοτομημάτων τούτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Την ημέραν εκείνην έκαμε διαθήκην ο Κύριος προς τον Άβραμ, λέγων, εις το σπέρμα σου έδωκα την γην ταύτην, από του ποταμού της Αιγύπτου έως του ποταμού του μεγάλου, του ποταμού Ευφράτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'τους Κεναίους, και τους Κενεζαίους, και τους Κεδμωναίους,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'και τους Χετταίους, και τους Φερεζαίους, και τους Ραφαείμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'και τους Αμορραίους, και τους Χαναναίους, και τους Γεργεσαίους, και τους Ιεβουσαίους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Η δε Σάρα, η γυνή του Άβραμ, δεν ετεκνοποίει εις αυτόν· είχε δε δούλην Αιγυπτίαν, ονομαζομένην Άγαρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Και είπεν η Σάρα προς τον Άβραμ, Ιδού, ο Κύριος με απέκλεισε της τεκνοποιΐας· είσελθε λοιπόν προς την δούλην μου, ίσως αποκτήσω τέκνον εξ αυτής. Υπήκουσε δε ο Άβραμ εις τον λόγον της Σάρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Και έλαβεν η Σάρα η γυνή του Άβραμ την Άγαρ την Αιγυπτίαν, την δούλην αυτής, αφού ο Άβραμ είχε κατοικήσει δέκα έτη εν τη γη Χαναάν, και έδωκεν αυτήν εις Άβραμ τον άνδρα αυτής, διά να ήναι γυνή αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Και εισήλθε προς την Άγαρ, και εκείνη συνέλαβε· και ότε είδεν ότι συνέλαβεν, η κυρία αυτής κατεφρονείτο ενώπιον αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Και είπεν η Σάρα προς τον Άβραμ, Εξ αιτίας σου αδικούμαι. Εγώ έδωκα την δούλην μου εις τον κόλπον σου· και αφού είδεν ότι συνέλαβεν, εγώ κατεφρονήθην ενώπιον αυτής· ας κρίνη ο Κύριος μεταξύ εμού και σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Ο δε Άβραμ είπε προς την Σάραν, Ιδού, η δούλη σου είναι εις την χείρα σου· κάμε εις αυτήν όπως είναι αρεστόν εις τους οφθαλμούς σου. Και μετεχειρίσθη η Σάρα αυτήν κακώς, και εκείνη έφυγεν από προσώπου αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Εύρε δε αυτήν άγγελος Κυρίου πλησίον πηγής ύδατος, εν τη ερήμω, πλησίον της πηγής κατά την οδόν Σούρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'και είπεν, Άγαρ, δούλη της Σάρας, πόθεν έρχεσαι και που υπάγεις; Η δε είπεν, Από προσώπου Σάρας της κυρίας μου φεύγω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Και είπε προς αυτήν ο άγγελος του Κυρίου, Επίστρεψον προς την κυρίαν σου και ταπεινώθητι υπό τας χείρας αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Είπεν έτι ο άγγελος του Κυρίου προς αυτήν, Θέλω πληθύνει σφόδρα το σπέρμα σου, ώστε να μη αριθμήται διά το πλήθος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Και είπε προς αυτήν ο άγγελος του Κυρίου, Ιδού, συ είσαι έγκυος, και θέλεις γεννήσει υιόν, και θέλεις καλέσει το όνομα αυτού Ισμαήλ· διότι ήκουσεν ο Κύριος την θλίψιν σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'και ούτος θέλει είσθαι άνθρωπος άγριος· η χειρ αυτού θέλει είσθαι εναντίον πάντων, και η χειρ πάντων εναντίον αυτού· και κατά πρόσωπον πάντων των αδελφών αυτού θέλει κατοικήσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Και εκάλεσεν Άγαρ το όνομα του Κυρίου του λαλούντος προς αυτήν, Συ Θεός όστις με είδες· διότι είπεν, Είδον έτι εγώ ενταύθα εκείνον όστις με είδε;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Διά τούτο ωνομάσθη το φρέαρ εκείνο, Φρέαρ Λαχαΐ-ροΐ· ιδού, κείται μεταξύ Κάδης και Βαράδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Και εγέννησεν η Άγαρ υιόν εις τον Αβραμ· και ο Άβραμ εκάλεσε το όνομα του υιού αυτού, τον οποίον εγέννησεν Άγαρ, Ισμαήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Ήτο δε ο Άβραμ ογδοήκοντα εξ ετών, ότε η Άγαρ εγέννησε τον Ισμαήλ εις τον Άβραμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Και ότε ήτο ο Άβραμ ενενήκοντα εννέα ετών, εφάνη ο Κύριος εις τον Άβραμ και είπε προς αυτόν, Εγώ είμαι Θεός ο Παντοκράτωρ· περιπάτει ενώπιόν μου, και έσο τέλειος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Και θέλω στήσει την διαθήκην μου αναμέσον εμού και σού· και θέλω σε πληθύνει σφόδρα σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Και έπεσεν ο Άβραμ επί πρόσωπον αυτού· και ελάλησε προς αυτόν ο Θεός, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Εγώ, ιδού, η διαθήκη μου είναι προς σέ· και θέλεις γείνει πατήρ πλήθους εθνών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'και δεν θέλει καλείσθαι πλέον το όνομά σου Άβραμ, αλλά το όνομά σου θέλει είσθαι Αβραάμ· διότι πατέρα πλήθους εθνών σε κατέστησα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'και θέλω σε αυξήσει σφόδρα σφόδρα, και θέλω σε καταστήσει εις έθνη, και βασιλείς θέλουσιν εξέλθει εκ σού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'και θέλω στήσει την διαθήκην μου αναμέσον εμού και σου, και του σπέρματός σου μετά σε εις τας γενεάς αυτών, εις διαθήκην αιώνιον, διά να ήμαι Θεός εις σε και εις το σπέρμα σου μετά σέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'και θέλω δώσει εις σε, και εις το σπέρμα σου μετά σε, την γην της παροικίας σου, πάσαν την γην Χαναάν, εις κατάσχεσιν αιώνιον· και θέλω είσθαι ο Θεός αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Και είπεν ο Θεός προς τον Αβραάμ, συ δε την διαθήκην μου θέλεις φυλάξει, συ και το σπέρμα σου μετά σε εις τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Αύτη είναι η διαθήκη μου την οποίαν θέλετε φυλάξει, αναμέσον εμού και υμών και του σπέρματός σου μετά σέ· παν άρσεν υμών θέλει περιτέμνεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Και θέλετε περιτέμνει την σάρκα της ακροβυστίας υμών, και θέλει είσθαι εις σημείον της διαθήκης μεταξύ εμού και υμών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'και παιδίον οκτώ ημερών θέλει περιτέμνεσθαι μεταξύ σας, παν άρσεν εις τας γενεάς υμών ο γεγεννημένος εν τη οικία, και ο αργυρώνητος εκ παντός ξένου, όστις δεν είναι εκ του σπέρματός σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'θέλει εξάπαντος περιτέμνεσθαι ο γεγεννημένος εν τη οικία σου, και ο αργυρώνητός σου· και θέλει είσθαι η διαθήκη μου επί της σαρκός υμών εις διαθήκην αιώνιον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'και το απερίτμητον άρσεν, του οποίου δεν ήθελε περιτμηθή η σαρξ της ακροβυστίας αυτού, η ψυχή εκείνη θέλει εξολοθρευθή εκ μέσου του λαού αυτής· την διαθήκην μου παρέβη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Και είπεν ο Θεός προς τον Αβραάμ, Σάραν την γυναίκα σου, δεν θέλεις καλέσει πλέον το όνομα αυτής Σάραν, αλλά Σάρρα θέλει είσθαι το όνομα αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Και θέλω ευλογήσει αυτήν, και θέλω προσέτι δώσει εις σε υιόν εξ αυτής· και θέλω ευλογήσει αυτήν, και θέλει γείνει μήτηρ εθνών· βασιλείς λαών θέλουσιν εξέλθει εξ αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Και έπεσεν ο Αβραάμ επί πρόσωπον αυτού και εγέλασε, και είπεν εν τη καρδία αυτού, Εις άνθρωπον εκατονταετή θέλει γεννηθή τέκνον; και η Σάρρα, γυνή ενενήκοντα ετών, θέλει γεννήσει;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Και είπεν ο Αβραάμ προς τον Θεόν, Είθε ο Ισμαήλ να ζήση ενώπιόν σου');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Και είπεν ο Θεός, Ναι η γυνή σου Σάρρα θέλει γεννήσει υιόν εις σε, και θέλεις καλέσει το όνομα αυτού Ισαάκ· και θέλω στήσει την διαθήκην μου προς αυτόν εις διαθήκην αιώνιον, και προς το σπέρμα αυτού μετ\' αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'περί δε του Ισμαήλ σου εισήκουσα· Ιδού, ευλόγησα αυτόν, και θέλω αυξήσει αυτόν, και θέλω πληθύνει αυτόν σφόδρα σφόδρα· δώδεκα άρχοντας θέλει γεννήσει, και θέλω κάμει αυτόν έθνος μέγα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'αλλά την διαθήκην μου θέλω στήσει προς τον Ισαάκ, τον οποίον θέλει γεννήσει η Σάρρα εις σε το ερχόμενον έτος, εν τω αυτώ τούτω καιρώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Αφού δε ετελείωσε να λαλή μετ\' αυτού, ανέβη ο Θεός από του Αβραάμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Και έλαβεν ο Αβραάμ Ισμαήλ τον υιόν αυτού, και πάντας τους γεγεννημένους εν τη οικία αυτού, και πάντας τους αργυρωνήτους αυτού, παν άρσεν των ανθρώπων της οικίας του Αβραάμ, και περιέτεμε την σάρκα της ακροβυστίας αυτών την αυτήν εκείνην ημέραν, καθώς είπε προς αυτόν ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Ο δε Αβραάμ ήτο ενενήκοντα εννέα ετών, ότε περιετμήθη την σάρκα της ακροβυστίας αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Ισμαήλ δε ο υιός αυτού ήτο δεκατριών ετών, ότε περιετμήθη την σάρκα της ακροβυστίας αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'την αυτήν εκείνην ημέραν περιετμήθη ο Αβραάμ, και Ισμαήλ ο υιός αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'και πάντες οι άνθρωποι της οικίας αυτού, οι γεγεννημένοι εν τη οικία, και οι εξ αλλογενών αργυρώνητοι περιετμήθησαν μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Και εφάνη εις αυτόν ο Κύριος εις τας δρυς Μαμβρή, ενώ εκάθητο εν τη θύρα της σκηνής εις το καύμα της ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Και υψώσας τους οφθαλμούς αυτού, είδε· και ιδού, τρεις άνδρες ιστάμενοι έμπροσθεν αυτού· και ως είδεν, έδραμεν εις προϋπάντησιν αυτών από της θύρας της σκηνής, και προσεκύνησεν έως εδάφους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'και είπε, Κύριέ μου, εάν εύρηκα χάριν εις τους οφθαλμούς σου, μη παρέλθης, παρακαλώ, τον δούλον σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'ας φερθή, παρακαλώ, ολίγον ύδωρ, και νίψατε τους πόδας σας, και αναπαύθητε υπό το δένδρον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'και εγώ θέλω φέρει ολίγον άρτον, και στηρίξατε την καρδίαν σας· έπειτα θέλετε παρέλθει· επειδή διά τούτο επεράσατε προς τον δούλον σας· οι δε είπον, Κάμε ούτω, καθώς είπας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Και έσπευσεν ο Αβραάμ εις την σκηνήν προς την Σάρραν και είπε, Σπεύσον ζύμωσον τρία μέτρα σεμιδάλεως, και κάμε εγκρυφίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Ο δε Αβραάμ έδραμεν εις τους βόας, και έλαβε μοσχάριον απαλόν και καλόν, και έδωκεν εις τον δούλον· ο δε έσπευσε να ετοιμάση αυτό·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'έπειτα έλαβε βούτυρον και γάλα και το μοσχάριον, το οποίον ητοίμασε, και έθεσεν έμπροσθεν αυτών· αυτός δε ίστατο πλησίον αυτών υπό το δένδρον, και αυτοί έφαγον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Είπον δε προς αυτόν, Που είναι Σάρρα η γυνή σου; Ο δε είπεν, Ιδού, εν τη σκηνή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Και είπεν, Εξάπαντος θέλω επιστρέψει προς σε κατά τον αυτόν τούτον καιρόν του έτους· και ιδού, Σάρρα η γυνή σου θέλει έχει υιόν. Η δε Σάρρα ήκουσεν εν τη θύρα της σκηνής ήτις ήτο όπισθεν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Ο δε Αβραάμ και η Σάρρα ήσαν γέροντες, προβεβηκότες εις ηλικίαν· εις την Σάρραν είχον παύσει να γίνωνται τα γυναικεία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Εγέλασε δε η Σάρρα καθ\' εαυτήν λέγουσα, Αφού εγήρασα, θέλει γείνει εις εμέ ηδονή και ο κύριός μου γέρων;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Και είπε Κύριος προς τον Αβραάμ, Διά τι εγέλασεν η Σάρρα, λέγουσα, Αφού εγώ εγήρασα, θέλω τωόντι γεννήσει;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'είναι τι αδύνατον εις τον Κύριον; εν τω ωρισμένω καιρώ θέλω επιστρέψει προς σε κατά τον αυτόν τούτον καιρόν του έτους, και η Σάρρα θέλει έχει υιόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Τότε η Σάρρα ηρνήθη λέγουσα, δεν εγέλασα· διότι εφοβήθη. Ο δε είπεν, Ουχί, αλλ\' εγέλασας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Σηκωθέντες δε εκείθεν οι άνδρες διευθύνθησαν προς τα Σόδομα· και ο Αβραάμ επορεύετο μετ\' αυτών διά να συμπροπέμψη αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Και είπε Κύριος, Θέλω κρύψει εγώ από του Αβραάμ ό,τι κάμνω;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'ο δε Αβραάμ θέλει εξάπαντος γείνει έθνος μέγα και δυνατόν· και θέλουσιν ευλογηθή εις αυτόν πάντα τα έθνη της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'επειδή γνωρίζω αυτόν ότι θέλει διατάξει προς τους υιούς αυτού και προς τον οίκον αυτού, μεθ\' εαυτόν, και θέλουσι φυλάξει την οδόν του Κυρίου, διά να πράττωσι δικαιοσύνην και κρίσιν, ώστε να επιφέρη ο Κύριος επί τον Αβραάμ τα όσα ελάλησε προς αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Είπε δε Κύριος, Η κραυγή των Σοδόμων και των Γομόρρων επλήθυνε, και η αμαρτία αυτών βαρεία σφόδρα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'θέλω λοιπόν καταβή και θέλω ιδεί αν έπραξαν ολοκλήρως κατά την κραυγήν την ερχομένην προς εμέ· και θέλω γνωρίσει, αν ουχί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Και αναχωρήσαντες εκείθεν οι άνδρες υπήγον προς τα Σόδομα· ο δε Αβραάμ ίστατο έτι ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Και πλησιάσας ο Αβραάμ είπε, Μήπως θέλεις απολέσει τον δίκαιον μετά του ασεβούς;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'εάν ήναι πεντήκοντα δίκαιοι εν τη πόλει, θέλεις άρα γε απολέσει αυτούς; και δεν ήθελες συγχωρήσει εις τον τόπον διά τους πεντήκοντα δικαίους, τους εν αυτώ;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'μη γένοιτο ποτέ συ να πράξης τοιούτον πράγμα, να θανατώσης δίκαιον μετά ασεβούς, και ο δίκαιος να ήναι ως ο ασεβής μη γένοιτο ποτέ εις σε ο κρίνων πάσαν την γην δεν θέλει κάμει κρίσιν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Είπε δε Κύριος, Εάν εύρω εν Σοδόμοις πεντήκοντα δικαίους εν τη πόλει, θέλω συγχωρήσει εις πάντα τον τόπον δι\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Και αποκριθείς ο Αβραάμ είπεν, Ιδού, τώρα ετόλμησα να ομιλήσω προς τον Κύριόν μου, ενώ είμαι γη και σποδός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'εάν λείψωσι πέντε εκ των πεντήκοντα δικαίων, θέλεις απολέσει πάσαν την πόλιν εξ αιτίας των πέντε; Και είπε, Δεν θέλω απολέσει αυτήν εάν εύρω εκεί τεσσαράκοντα πέντε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Και προσέθεσεν έτι ο Αβραάμ να λαλήση προς αυτόν, και είπεν, Εάν ευρεθώσιν εκεί τεσσαράκοντα; Και είπε, Δεν θέλω απολέσει αυτήν χάριν των τεσσαράκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Και είπεν ο Αβραάμ, Ας μη παροξυνθή ο Κύριός μου εάν έτι λαλήσω· εάν ευρεθώσιν εκεί τριάκοντα; Και είπε, Δεν θέλω απολέσει αυτήν εάν εύρω εκεί τριάκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Και είπεν ο Αβραάμ, Ιδού, τώρα ετόλμησα να λαλήσω προς τον Κύριόν μου· εάν ευρεθώσιν εκεί είκοσι; και είπε, Δεν θέλω απολέσει αυτήν χάριν των είκοσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Και είπεν ο Αβραάμ, Ας μη παροξυνθή ο Κύριός μου, εάν λαλήσω έτι άπαξ· εάν ευρεθώσιν εκεί δέκα; και είπε, Δεν θέλω απολέσει αυτήν χάριν των δέκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Και ανεχώρησεν ο Κύριος, αφού έπαυσε να λαλή προς τον Αβραάμ· και ο Αβραάμ επέστρεψεν εις τον τόπον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Ήλθον δε οι δύο άγγελοι εις τα Σόδομα το εσπέρας· και εκάθητο ο Λωτ παρά την πύλην των Σοδόμων· ιδών δε ο Λωτ, εσηκώθη εις συνάντησιν αυτών και προσεκύνησεν επί πρόσωπον έως εδάφους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'και είπεν, Ιδού, κύριοί μου, εκκλίνατε, παρακαλώ, προς την οικίαν του δούλου σας, και διανυκτερεύσατε και πλύνατε τους πόδας σας· και σηκωθέντες πρωΐ, θέλετε υπάγει εις την οδόν σας· οι δε είπον, Ουχί, αλλ\' εν τη πλατεία θέλομεν διανυκτερεύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Αφού δε εβίασεν αυτούς πολύ, εξέκλιναν προς αυτόν και εισήλθον εις την οικίαν αυτού· και έκαμεν εις αυτούς συμπόσιον, και έψησεν άζυμα και έφαγον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Πριν δε κοιμηθώσιν, οι άνδρες της πόλεως, οι άνδρες των Σοδόμων, περιεκύκλωσαν την οικίαν, νέοι και γέροντες, άπας ο λαός ομού πανταχόθεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'και έκραζον προς τον Λωτ και έλεγον προς αυτόν, Που είναι οι άνδρες οι εισελθόντες προς σε την νύκτα; έκβαλε αυτούς προς ημάς, διά να γνωρίσωμεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Εξήλθε δε ο Λωτ προς αυτούς εις το πρόθυρον, και έκλεισε την θύραν οπίσω αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'και είπε, Μη, αδελφοί μου, μη πράξητε τοιούτον κακόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'ιδού, έχω δύο θυγατέρας αίτινες δεν εγνώρισαν άνδρα· να σας φέρω λοιπόν αυτάς έξω· και κάμετε εις αυτάς, όπως φανή εις εσάς αρεστόν· μόνον εις τους άνδρας τούτους μη πράξητε μηδέν, επειδή διά τούτο εισήλθον υπό την σκιάν της στέγης μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Οι δε είπον, Φύγε απ\' εκεί. Και είπον, ούτος ήλθε διά να παροικήση· θέλει να γείνη και κριτής; τώρα θέλομεν καποποιήσει σε μάλλον παρά εκείνους. Και εβίαζον τον άνθρωπον τον Λωτ καθ\' υπερβολήν, και επλησίασαν διά να συντρίψωσι την θύραν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Εκτείναντες δε οι άνδρες τας χείρας αυτών έσυραν τον Λωτ προς εαυτούς εις την οικίαν, και έκλεισαν την θύραν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'τους δε ανθρώπους, τους όντας εις την θύραν της οικίας, εκτύπησαν με αορασίαν από μικρού έως μεγάλου, ώστε απέκαμον ζητούντες την θύραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Και είπον οι άνδρες προς τον Λωτ, Έχεις εδώ άλλον τινά; γαμβρόν υιούς ή θυγατέρας ή όντινα άλλον έχεις εν τη πόλει, εξάγαγε αυτούς εκ του τόπου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'διότι ημείς καταστρέφομεν τον τόπον τούτον, επειδή η κραυγή αυτών εμεγάλυνεν ενώπιον του Κυρίου· και απέστειλεν ημάς ο Κύριος διά να καταστρέψωμεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Εξήλθε λοιπόν ο Λωτ και ελάλησε προς τους γαμβρούς αυτού, τους μέλλοντας να λάβωσι τας θυγατέρας αυτού, και είπε, Σηκώθητε, εξέλθετε εκ του τόπου τούτου· διότι καταστρέφει ο Κύριος την πόλιν. Αλλ\' εφάνη εις τους γαμβρούς αυτού ως αστεϊζόμενος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Και ότε έγεινεν αυγή, εβίαζον οι άγγελοι τον Λωτ, λέγοντες· Σηκώθητι, λάβε την γυναίκα σου και τας δύο σου θυγατέρας, τας ευρισκομένας εδώ, διά να μη συναπολεσθής και συ εν τη ανομία της πόλεως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Επειδή δε εβράδυνεν, οι άνδρες πιάσαντες την χείρα αυτού και την χείρα της γυναικός αυτού και τας χείρας των δύο θυγατέρων αυτού, διότι εσπλαγχνίσθη αυτόν ο Κύριος, εξήγαγον αυτόν και έθεσαν αυτόν έξω της πόλεως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Και ότε εξήγαγον αυτούς έξω, είπεν ο Κύριος, Διάσωσον την ζωήν σου· μη περιβλέψης οπίσω σου, και μη σταθής καθ\' όλην την περίχωρον· διασώθητι εις το όρος, διά να μη απολεσθής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Και είπεν ο Λωτ προς αυτούς, Μη, παρακαλώ, Κύριε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'ιδού, ο δούλός σου εύρηκε χάριν ενώπιόν σου, και εμεγάλυνας το έλεός σου, το οποίον έκαμες προς εμέ, φυλάττων την ζωήν μου· αλλ\' εγώ δεν θέλω δυνηθή να διασωθώ εις το όρος, μήπως με προφθάση το κακόν και αποθάνω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'ιδού, παρακαλώ, η πόλις αύτη είναι πλησίον ώστε να καταφύγω εκεί, και είναι μικρά· εκεί, παρακαλώ, να διασωθώ· δεν είναι μικρά; και θέλει ζήσει η ψυχή μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Και είπε προς αυτόν ο Κύριος, Ιδού, επήκουσά σου και εις το πράγμα τούτο, να μη καταστρέψω την πόλιν, περί της οποίας ελάλησας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'τάχυνον, διασώθητι εκεί· διότι δεν θέλω δυνηθή να κάμω ουδέν, εωσού φθάσης εκεί· διά τούτο εκάλεσε το όνομα της πόλεως Σηγώρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Ο ήλιος ανέτειλεν επί την γην, ότε ο Λωτ εισήλθεν εις Σηγώρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Και έβρεξεν ο Κύριος επί τα Σόδομα και Γόμορρα θείον και πυρ παρά Κυρίου εκ του ουρανού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'και κατέστρεψε τας πόλεις ταύτας, και πάντα τα περίχωρα και πάντας τους κατοίκους των πόλεων και τα φυτά της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Αλλ\' γυνή αυτού περιβλέψασα όπισθεν αυτού έγεινε στήλη άλατος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Ο δε Αβραάμ σηκωθείς ενωρίς το πρωΐ ήλθεν εις τον τόπον όπου είχε σταθή ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'και βλέψας επί τα Σόδομα και Γόμορρα και εφ\' όλην την γην της περιχώρου, είδε, και ιδού, ανέβαινε καπνός από της γης, ως καπνός καμίνου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Ούτω λοιπόν, ότε ο Θεός κατέστρεψε τας πόλεις της περιχώρου, ενεθυμήθη ο Θεός τον Αβραάμ, και εξαπέστειλε τον Λωτ εκ μέσου της καταστροφής, ότε κατέστρεψε τας πόλεις, εις τας οποίας κατώκει ο Λωτ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Ανέβη δε ο Λωτ από Σηγώρ και κατώκησεν εν τω όρει, και μετ\' αυτού αι δύο θυγατέρες αυτού, διότι εφοβήθη να κατοικήση εν Σηγώρ· και κατώκησεν εν σπηλαίω, αυτός και αι δύο θυγατέρες αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Και είπεν η πρεσβυτέρα προς την νεωτέραν, Ο πατήρ ημών είναι γέρων, και άνθρωπος δεν είναι επί της γης, διά να εισέλθη προς ημάς κατά την συνήθειαν πάσης της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'ελθέ, ας ποτίσωμεν τον πατέρα, ημών οίνον, και ας κοιμηθώμεν μετ\' αυτού, και ας αναστήσωμεν σπέρμα εκ του πατρός ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Επότισαν λοιπόν τον πατέρα αυτών οίνον κατ\' εκείνην την νύκτα· και εισήλθεν η πρεσβυτέρα και εκοιμήθη μετά του πατρός αυτής· και εκείνος δεν ενόησεν ούτε πότε επλαγίασεν αυτή, και πότε εσηκώθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Και την επαύριον είπεν η πρεσβυτέρα προς την νεωτέραν, Ιδού, εγώ εκοιμήθην χθές την νύκτα μετά του πατρός ημών· ας ποτίσωμεν αυτόν οίνον και την νύκτα ταύτην, και εισελθούσα συ, κοιμήθητι μετ\' αυτού, και ας αναστήσωμεν σπέρμα εκ του πατρός ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Επότισαν λοιπόν και την νύκτα εκείνην τον πατέρα αυτών οίνον, και σηκωθείσα η νεωτέρα, εκοιμήθη μετ\' αυτού· και εκείνος δεν ενόησεν ούτε πότε επλαγίασεν αυτή, και πότε εσηκώθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Και συνέλαβον αι δύο θυγατέρες του Λωτ εκ του πατρός αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Και εγέννησεν η πρεσβυτέρα υιόν και εκάλεσε το όνομα αυτού Μωάβ· ούτος είναι ο πατήρ των Μωαβιτών έως της σήμερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Εγέννησε δε και η νεωτέρα υιόν και εκάλεσε το όνομα αυτού Βεν-αμμί· ούτος είναι ο πατήρ των Αμμωνιτών έως της σήμερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Και εκίνησεν εκείθεν ο Αβραάμ εις την γην την προς μεσημβρίαν, και κατώκησε μεταξύ Κάδης και Σούρ· και παρώκησεν εν Γεράροις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Και είπεν ο Αβραάμ περί Σάρρας της γυναικός αυτού, Αδελφή μου είναι. Έστειλε δε Αβιμέλεχ ο βασιλεύς των Γεράρων, και έλαβε την Σάρραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Και ήλθεν ο Θεός προς τον Αβιμέλεχ κατ\' όναρ την νύκτα, και είπε προς αυτόν, Ιδού, συ αποθνήσκεις εξ αιτίας της γυναικός, την οποίαν έλαβες· διότι είναι νενυμφευμένη με άνδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Ο δε Αβιμέλεχ δεν είχε πλησιάσει εις αυτήν· και είπε, Κύριε, ήθελες φονεύσει έθνος έτι και δίκαιον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'δεν μοι είπεν αυτός, Αδελφή μου είναι; και αυτή πάλιν, αυτή είπεν, Αδελφός μου είναι. Εν ευθύτητι της καρδίας μου και εν καθαρότητι των χειρών μου έπραξα τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Είπε δε προς αυτόν ο Θεός κατ\' όναρ, Και εγώ εγνώρισα ότι εν ευθύτητι της καρδίας σου έπραξας τούτο· όθεν και εγώ σε εμπόδισα από του να αμαρτήσης εις εμέ· διά τούτο δεν σε αφήκα να εγγίσης αυτήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'τώρα λοιπόν απόδος την γυναίκα προς τον άνθρωπον, διότι είναι προφήτης· και θέλει προσευχηθή υπέρ σου και θέλεις ζήσει· αλλ\' εάν δεν αποδώσης αυτήν, έξευρε ότι εξάπαντος θέλεις αποθάνει, συ και πάντα όσα έχεις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Σηκωθείς δε ο Αβιμέλεχ ενωρίς το πρωΐ, εκάλεσε πάντας τους δούλους αυτού, και ελάλησε πάντας τους λόγους τούτους εις επήκοον αυτών· και εφοβήθησαν οι άνθρωποι σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Και εκάλεσεν ο Αβιμέλεχ τον Αβραάμ και είπε προς αυτόν, Τι έπραξας εις ημάς; και τι αμάρτημα έπραξα εις σε, ώστε επέφερες επ\' εμέ και επί το βασίλειόν μου, αμαρτίαν μεγάλην; έπραξας εις εμέ πράγμα, το οποίον δεν έπρεπε να πραχθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Και είπεν ο Αβιμέλεχ προς τον Αβραάμ, Τι είδες, ώστε να πράξης το πράγμα τούτο;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Και είπεν ο Αβραάμ, Επειδή εγώ είπον, Βέβαια δεν είναι φόβος Θεού εν τω τόπω τούτω και θέλουσι με φονεύσει διά την γυναίκα μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'και όμως αληθώς αδελφή μου είναι, θυγάτηρ του πατρός μου, αλλ\' ουχί θυγάτηρ της μητρός μου· και έγεινε γυνή μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'και ότε με έκαμεν ο Θεός να εξέλθω εκ του οίκου του πατρός μου, είπον προς αυτήν, Ταύτην την χάριν θέλεις κάμει εις εμέ· εις πάντα τόπον όπου αν υπάγωμεν, λέγε περί εμού, Ούτος είναι αδελφός μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Και έλαβεν ο Αβιμέλεχ πρόβατα και βόας και δούλους και δούλας, και έδωκεν εις τον Αβραάμ, και απέδωκεν εις αυτόν Σάρραν την γυναίκα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'και είπεν ο Αβιμέλεχ, Ιδού, η γη μου έμπροσθέν σου. κατοίκησον όπου σοι αρέσκει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Και προς την Σάρραν είπεν, Ιδού, έδωκα χίλια αργύρια εις τον αδελφόν σου· ιδού, αυτός είναι εις σε σκέπη των οφθαλμών προς πάντας τους μετά σου και προς πάντας τους άλλους. Ούτως αύτη επεπλήχθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Προσηυχήθη δε ο Αβραάμ προς τον Θεόν· και εθεράπευσεν ο Θεός τον Αβιμέλεχ και την γυναίκα αυτού και τας θεραπαίνας αυτού, και ετεκνοποίησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'διότι ο Κύριος είχε κλείσει διόλου πάσαν μήτραν εν τη οικία του Αβιμέλεχ, εξ αιτίας Σάρρας της γυναικός του Αβραάμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Και επεσκέφθη ο Κύριος την Σάρραν, ως είπε· και έκαμεν ο Κύριος εις την Σάρραν, ως ελάλησε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Και συνέλαβεν η Σάρρα, και εγέννησεν εις τον Αβραάμ υιόν εν τω γήρατι αυτού· κατά τον καιρόν, τον οποίον είπε προς αυτόν ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Και εκάλεσεν ο Αβραάμ το όνομα του υιού αυτού, του γεννηθέντος εις αυτόν, τον οποίον η Σάρρα εγέννησεν εις αυτόν, Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Περιέτεμε δε ο Αβραάμ τον υιόν αυτού Ισαάκ την ογδόην ημέραν, ως προσέταξεν εις αυτόν ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Ήτο δε ο Αβραάμ εκατόν ετών, ότε εγεννήθη εις αυτόν Ισαάκ ο υιός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Και είπεν η Σάρρα, Ο Θεός με έκαμε να γελώ· όστις ακούση, θέλει γελά μετ\' εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Και είπε, Τις ήθελεν ειπεί προς τον Αβραάμ, ότι ήθελε θηλάσει τέκνα η Σάρρα; επειδή εγέννησα υιόν εν τω γήρατι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Το δε παιδίον ηύξησε και απεγαλακτίσθη· και έκαμεν ο Αβραάμ μέγα συμπόσιον, καθ\' ην ημέραν απεγαλακτίσθη ο Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Και είδεν η Σάρρα τον υιόν της Άγαρ της Αιγυπτίας, τον οποίον εγέννησεν εις τον Αβραάμ, περιγελώντα τον Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Και είπε προς τον Αβραάμ, Δίωξον την δούλην ταύτην και τον υιόν αυτής· διότι δεν θέλει κληρονομήσει ο υιός της δούλης ταύτης μετά του υιού μου, του Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Εφάνη δε σκληρόν σφόδρα το πράγμα εις τους οφθαλμούς του Αβραάμ περί του υιού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Και είπεν ο Θεός προς τον Αβραάμ, Ας μη φανή σκληρόν εις τους οφθαλμούς σου περί του παιδίου και περί της δούλης σου· κατά πάντα όσα είπη προς σε η Σάρρα, άκουε τους λόγους αυτής· διότι εν τω Ισαάκ θέλει κληθή εις σε σπέρμα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'και τον υιόν δε της δούλης εις έθνος θέλω καταστήσει αυτόν· διότι είναι σπέρμα σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Σηκωθείς δε ο Αβραάμ ενωρίς το πρωΐ, έλαβεν άρτους και ασκόν ύδατος και έδωκεν εις την Άγαρ, επιθέσας αυτά επί τον ώμον αυτής, και το παιδίον, και απέπεμψεν αυτήν. Η δε αναχωρήσασα περιεπλανάτο εν τη ερήμω Βηρ-σαβεέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Και αφού ετελείωσε το ύδωρ από του ασκού, έρριψε το παιδίον υποκάτω ενός θάμνου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'και ελθούσα εκάθισεν απέναντι, μακράν έως τόξου βολής· διότι είπε, να μη ίδω τον θάνατον του παιδίου. Και εκάθισεν απέναντι και ύψωσε την φωνήν αυτής και έκλαυσεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Εισήκουσε δε ο Θεός την φωνήν του παιδίου· και εφώνησεν άγγελος Θεού προς την Άγαρ εκ του ουρανού, και είπε προς αυτήν, Τι έχεις, Άγαρ; μη φοβού· διότι ήκουσεν ο Θεός την φωνήν του παιδίου εκ του τόπου ένθα κείται·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'σηκώθητι, λάβε το παιδίον, και κράτει αυτό με την χείρα σου· διότι θέλω καταστήσει αυτό εις έθνος μέγα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Και ήνοιξεν ο Θεός τους οφθαλμούς αυτής, και ιδούσα φρέαρ ύδατος υπήγε και εγέμισε τον ασκόν ύδωρ και επότισε το παιδίον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Και ήτο ο Θεός μετά του παιδίου, και ηύξησε, και κατώκησεν εν τη ερήμω και έγεινε τοξότης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Και κατώκησεν εν τη ερήμω Φαράν· και η μήτηρ αυτού έλαβεν εις αυτόν γυναίκα εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Κατ\' εκείνον δε τον καιρόν ο Αβιμέλεχ, μετά του Φιχόλ αρχιστρατήγου της δυνάμεως αυτού, είπε προς τον Αβραάμ, λέγων, Ο Θεός είναι μετά σου εις πάντα όσα πράττεις·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'τώρα λοιπόν όμοσον προς εμέ εδώ εις τον Θεόν, ότι δεν θέλεις ψευσθή προς εμέ, ούτε προς τον υιόν μου, ούτε προς τους εγγόνους μου· αλλά κατά το έλεος, το οποίον έκαμα εις σε, θέλεις κάμει εις εμέ, και εις την γην όπου παρώκησας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Και είπεν ο Αβραάμ, Εγώ θέλω ομόσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Και έλεγξεν ο Αβραάμ τον Αβιμέλεχ διά το φρέαρ του ύδατος, το οποίον αφήρπασαν οι δούλοι του Αβιμέλεχ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Και είπεν ο Αβιμέλεχ, Δεν εξεύρω τις έπραξε το πράγμα τούτο· και ούτε συ με εφανέρωσας και ούτε εγώ ήκουσα, ειμή σήμερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Και λαβών ο Αβραάμ πρόβατα και βόας, έδωκεν εις τον Αβιμέλεχ· και έκαμον αμφότεροι συνθήκην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Και έβαλεν ο Αβραάμ κατά μέρος επτά θηλυκά αρνία του ποιμνίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Και είπεν ο Αβιμέλεχ προς τον Αβραάμ, Τι είναι ταύτα τα επτά θηλυκά αρνία, τα οποία έβαλες κατά μέρος;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Ο δε είπεν, Ότι ταύτα τα επτά θηλυκά αρνία θέλεις λάβει εκ της χειρός μου, διά να ήναι εις εμέ εις μαρτύριον ότι εγώ έσκαψα το φρέαρ τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'διά τούτο ωνόμασε τον τόπον εκείνον, Βηρ-σαβεέ· διότι εκεί ώμοσαν αμφότεροι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Και έκαμον συνθήκην εν Βηρ-σαβεέ. Εσηκώθη δε ο Αβιμέλεχ και Φιχόλ ο αρχιστράτηγος της δυνάμεως αυτού, και επέστρεψαν εις την γην των Φιλισταίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Και εφύτευσεν ο Αβραάμ δρυμόν εν Βηρ-σαβεέ· και επεκαλέσθη εκεί το όνομα του Κυρίου, του αιωνίου Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Παρώκησε δε ο Αβραάμ εν τη γη των Φιλισταίων ημέρας πολλάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Μετά δε τα πράγματα ταύτα ο Θεός εδοκίμασε τον Αβραάμ, και είπε προς αυτόν, Αβραάμ· ο δε είπεν, Ιδού, εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Και είπε, Λάβε τώρα τον υιόν σου τον μονογενή, τον οποίον ηγάπησας, τον Ισαάκ, και ύπαγε εις τον τόπον Μοριά, και πρόσφερε αυτόν εκεί εις ολοκαύτωμα, επί ενός των ορέων, το οποίον θέλω σοι ειπεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Σηκωθείς δε Αβραάμ ενωρίς το πρωΐ, εσαμάρωσε την όνον αυτού και έλαβε μεθ\' εαυτού δύο εκ των δούλων αυτού και Ισαάκ τον υιόν αυτού· και σχίσας ξύλα διά την ολοκαύτωσιν, εσηκώθη και υπήγεν εις τον τόπον τον οποίον είπε προς αυτόν ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Την δε τρίτην ημέραν υψώσας ο Αβραάμ τους οφθαλμούς αυτού, είδε τον τόπον μακρόθεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Και είπεν ο Αβραάμ προς τους δούλους αυτού, Σεις καθίσατε αυτού μετά της όνου· εγώ δε και το παιδάριον θέλομεν υπάγει έως εκεί· και αφού προσκυνήσωμεν, θέλομεν επιστρέψει προς εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Και λαβών ο Αβραάμ τα ξύλα της ολοκαυτώσεως, επέθεσεν επί τον Ισαάκ τον υιόν αυτού· και έλαβεν εις την χείρα αυτού το πυρ, και την μάχαιραν, και υπήγον οι δύο ομού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Τότε ελάλησεν ο Ισαάκ προς Αβραάμ τον πατέρα αυτού και είπε, Πάτερ μου. Ο δε είπεν, Ιδού, εγώ, τέκνον μου. Και είπεν ο Ισαάκ, Ιδού, το πυρ και τα ξύλα· αλλά που το πρόβατον διά την ολοκαύτωσιν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Και είπεν ο Αβραάμ, Ο Θεός, τέκνον μου, θέλει προβλέψει εις εαυτόν το πρόβατον διά την ολοκαύτωσιν. Και επορεύοντο οι δύο ομού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Αφού δε έφθασαν εις τον τόπον τον οποίον είπε προς αυτόν ο Θεός, ωκοδόμησεν εκεί ο Αβραάμ το θυσιαστήριον και διέθεσε τα ξύλα, και δέσας τον Ισαάκ τον υιόν αυτού έβαλεν αυτόν επί το θυσιαστήριον επάνω των ξύλων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'και εκτείνας ο Αβραάμ την χείρα αυτού, έλαβε την μάχαιραν διά να σφάξη τον υιόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Άγγελος δε Κυρίου εφώνησε προς αυτόν εκ του ουρανού και είπεν, Αβραάμ, Αβραάμ. Ο δε είπεν, Ιδού, εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Και είπε, Μη επιβάλης την χείρα σου επί το παιδάριον, και μη πράξης εις αυτό μηδέν· διότι τώρα εγνώρισα ότι συ φοβείσαι τον Θεόν, επειδή δεν ελυπήθης τον υιόν σου τον μονογενή δι\' εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Και υψώσας ο Αβραάμ τους οφθαλμούς αυτού είδε· και ιδού, κριός όπισθεν αυτού, κρατούμενος από των κεράτων αυτού εις φυτόν πυκνόκλαδον· και ελθών ο Αβραάμ, έλαβε τον κριόν και προσέφερεν αυτόν εις ολοκαύτωμα αντί του υιού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Και εκάλεσεν ο Αβραάμ το όνομα του τόπου εκείνου Ιεοβά-ιρέ· ως λέγεται και την σήμερον, Εν τω όρει ο Κύριος θέλει εμφανισθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Και εφώνησε δεύτερον ο άγγελος του Κυρίου προς τον Αβραάμ εκ του ουρανού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'και είπεν, Ώμοσα εις εμαυτόν, λέγει Κύριος, ότι, επειδή έπραξας το πράγμα τούτο και δεν ελυπήθης τον υιόν σου, τον μονογενή σου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'ότι ευλογών θέλω σε ευλογήσει, και πληθύνων θέλω πληθύνει το σπέρμα σου ως τα άστρα του ουρανού και ως την άμμον την παρά το χείλος της θαλάσσης· και το σπέρμα σου θέλει κυριεύσει τας πύλας των εχθρών αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'και εν τω σπέρματί σου θέλουσιν ευλογηθή πάντα τα έθνη της γής· διότι υπήκουσας εις την φωνήν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Και επέστρεψεν ο Αβραάμ προς τους δούλους αυτού· και σηκωθέντες, υπήγον ομού εις Βηρ-σαβεέ· και κατώκησεν ο Αβραάμ εν Βηρ-σαβεέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Μετά δε τα πράγματα ταύτα, ανήγγειλαν προς τον Αβραάμ λέγοντες, Ιδού, η Μελχά εγέννησε και αυτή υιούς εις τον Ναχώρ τον αδελφόν σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'τον Ουζ πρωτότοκον αυτού, και τον Βουζ αδελφόν αυτού, και τον Κεμουήλ τον πατέρα του Αράμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'και τον Κεσέδ, και τον Αζαύ, και τον Φαλδές, και τον Ιελδάφ, και τον Βαθουήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Ο δε Βαθουήλ εγέννησε την Ρεβέκκαν· τους οκτώ τούτους εγέννησεν η Μελχά εις τον Ναχώρ τον αδελφόν του Αβραάμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Και η παλλακή αυτού, η ονομαζομένη Ρευμά, εγέννησε και αυτή τον Ταβέκ και τον Γαάμ και τον Ταχάς και τον Μααχά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Και έζησεν η Σάρρα εκατόν εικοσιεπτά έτη· ταύτα είναι τα έτη της ζωής της Σάρρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Και απέθανεν η Σάρρα εν Κιριάθ-αρβά· αύτη είναι η Χεβρών εν γη Χαναάν· και ήλθεν ο Αβραάμ διά να κλαύση την Σάρραν και να πενθήση αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Και σηκωθείς ο Αβραάμ απ\' έμπροσθεν του νεκρού αυτού, ελάλησε προς τους υιούς του Χετ λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'ξένος και πάροικος είμαι εγώ μεταξύ σας· δότε μοι κτήμα τάφου μεταξύ σας, διά να θάψω τον νεκρόν μου απ\' έμπροσθέν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Απεκρίθησαν δε οι υιοί του Χετ προς τον Αβραάμ λέγοντες προς αυτόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Άκουσον ημάς, κύριέ μου· συ είσαι μεταξύ ημών ηγεμών εκ Θεού· θάψον τον νεκρόν σου εις το εκλεκτότερον εκ των μνημείων ημών· ουδείς εξ ημών θέλει αρνηθή το μνημείον αυτού προς σε, διά να θάψης τον νεκρόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Τότε σηκωθείς ο Αβραάμ προσεκύνησε προς τον λαόν του τόπου, προς τους υιούς του Χέτ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'και ελάλησε προς αυτούς λέγων, Εάν ευαρεστήται η ψυχή σας να θάψω τον νεκρόν μου απ\' έμπροσθέν μου, ακούσατέ μου και μεσιτεύσατε υπέρ εμού προς τον Εφρών τον υιόν του Σωάρ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'και ας μοι δώση το σπήλαιον αυτού Μαχπελάχ, το εν τη άκρα του αγρού αυτού· εις πλήρη τιμήν ας μοι δώση αυτό, διά κτήμα τάφου μεταξύ σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Ο δε Εφρών εκάθητο εν τω μέσω των υιών του Χέτ· και απεκρίθη ο Εφρών ο Χετταίος προς τον Αβραάμ εις επήκοον των υιών του Χετ, πάντων των εισερχομένων εις την πύλην της πόλεως αυτού, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Ουχί, κύριέ μου, άκουσόν μου· σοι δίδω τον αγρόν, σοι δίδω και το σπήλαιον το εν αυτώ· επί παρουσία των υιών του λαού μου δίδω αυτά εις σέ· θάψον τον νεκρόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Και προσεκύνησεν ο Αβραάμ έμπροσθεν του λαού του τόπου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'και είπε προς τον Εφρών εις επήκοον του λαού του τόπου λέγων, Εάν συ θέλης, άκουσόν μου, παρακαλώ· θέλω δώσει το αργύριον του αγρού· λάβε αυτό παρ\' εμού, και θέλω θάψει τον νεκρόν μου εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ο δε Εφρών απεκρίθη προς τον Αβραάμ, λέγων προς αυτόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Ακουσόν μου, κύριέ μου· γη τετρακοσίων σίκλων αργυρίου, τι είναι μεταξύ εμού και σου; θάψον λοιπόν τον νεκρόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Και ήκουσεν ο Αβραάμ τον Εφρών· και εζύγισεν ο Αβραάμ εις τον Εφρών το αργύριον, το οποίον είπεν εις επήκοον των υιών του Χετ τετρακοσίους σίκλους αργυρίου, δεκτού μεταξύ εμπόρων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Και ο αγρός του Εφρών, όστις ήτο εν Μαχπελάχ, έμπροσθεν της Μαμβρή, ο αγρός και το σπήλαιον το εν αυτώ και πάντα τα δένδρα τα εν τω αγρώ και εν πάσι τοις ορίοις κύκλω, ησφαλίσθησαν');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'εις τον Αβραάμ διά κτήμα, ενώπιον των υιών του Χετ, ενώπιον πάντων των εισερχομένων εις την πύλην της πόλεως αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Και μετά ταύτα έθαψεν ο Αβραάμ Σάρραν την γυναίκα αυτού εν τω σπηλαίω του αγρού Μαχπελάχ, έμπροσθεν της Μαμβρή· αύτη είναι Χεβρών εν γη Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Και ο αγρός και το σπήλαιον το εν αυτώ, ησφαλίσθησαν εις τον Αβραάμ διά κτήμα τάφον παρά των υιών του Χετ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Ήτο δε ο Αβραάμ γέρων προβεβηκώς την ηλικίαν· και ο Κύριος ευλόγησε τον Αβραάμ κατά πάντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Και είπεν ο Αβραάμ προς τον δούλον αυτού τον πρεσβύτερον της οικίας αυτού, τον επιστάτην πάντων των υπαρχόντων αυτού, Βάλε, παρακαλώ, την χείρα σου υπό τον μηρόν μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'και θέλω σε ορκίσει εις Κύριον τον Θεόν του ουρανού και τον Θεόν της γης, ότι δεν θέλεις λάβει γυναίκα εις τον υιόν μου εκ των θυγατέρων των Χαναναίων, μεταξύ των οποίων εγώ κατοικώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'αλλ\' εις τον τόπον μου, και εις την συγγένειάν μου θέλεις υπάγει, και θέλεις λάβει γυναίκα εις τον υιόν μου τον Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Είπε δε προς αυτόν ο δούλος, Ίσως δεν θελήση η γυνή να μοι ακολουθήση εις την γην ταύτην· πρέπει να φέρω τον υιόν σου εις την γην εκ της οποίας εξήλθες;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Και είπε προς αυτόν ο Αβραάμ, Πρόσεχε, μη φέρης τον υιόν μου εκεί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Κύριος ο Θεός του ουρανού, όστις με έλαβεν εκ του οίκου του πατρός μου και εκ της γης της γεννήσεώς μου, και όστις ελάλησε προς εμέ και όστις ώμοσεν εις εμέ λέγων, εις το σπέρμα σου θέλω δώσει την γην ταύτην, αυτός θέλει αποστείλει τον άγγελον αυτού έμπροσθέν σου· και θέλεις λάβει γυναίκα εις τον υιόν μου εκείθεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'εάν δε η γυνή δεν θέλη να σε ακολουθήση, τότε θέλεις είσθαι ελεύθερος από του όρκου μου τούτου· μόνον τον υιόν μου να μη φέρης εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Και έβαλεν ο δούλος την χείρα αυτού υπό τον μηρόν του Αβραάμ του κυρίου αυτού, και ώρκίσθη εις αυτόν περί του πράγματος τούτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Και έλαβεν ο δούλος δέκα καμήλους εκ των καμήλων του κυρίου αυτού και ανεχώρησε, φέρων μεθ\' εαυτού από πάντων των αγαθών του κυρίου αυτού· και σηκωθείς, υπήγεν εις την Μεσοποταμίαν, εις την πόλιν του Ναχώρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Και εγονάτισε τας καμήλους έξω της πόλεως παρά το φρέαρ του ύδατος, προς το εσπέρας, ότε εξέρχονται αι γυναίκες διά να αντλήσωσιν ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Και είπε, Κύριε Θεέ του κυρίου μου Αβραάμ, δος μοι, δέομαι, καλόν συνάντημα σήμερον, και κάμε έλεος εις τον κύριόν μου Αβραάμ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'ιδού, εγώ ίσταμαι πλησίον της πηγής του ύδατος· αι δε θυγατέρες των κατοίκων της πόλεως εξέρχονται διά να αντλήσωσιν ύδωρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'και η κόρη προς την οποίαν είπω, Επίκλινον, παρακαλώ, την υδρίαν σου διά να πίω, και αυτή είπη, Πίε και θέλω ποτίσει και τας καμήλους σου, αύτη ας ήναι εκείνη, την οποίαν ητοίμασας εις τον δούλον σου τον Ισαάκ· και εκ τούτου θέλω γνωρίσει ότι έκαμες έλεος εις τον κύριόν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Και πριν αυτός παύση λαλών, ιδού, εξήρχετο η Ρεβέκκα, ήτις εγεννήθη εις τον Βαθουήλ, υιόν της Μελχάς, γυναικός του Ναχώρ, αδελφού του Αβραάμ, έχουσα την υδρίαν αυτής επί του ώμου αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Η δε κόρη ήτο ώραία την όψιν σφόδρα, παρθένος, και ανήρ δεν είχε γνωρίσει αυτήν· αφού λοιπόν κατέβη εις την πηγήν, εγέμισε την υδρίαν αυτής και ανέβαινε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Δραμών δε ο δούλος εις συνάντησιν αυτής είπε, Πότισόν με, παρακαλώ, ολίγον ύδωρ εκ της υδρίας σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Η δε είπε, Πίε, κύριέ μου. και έσπευσε και κατεβίβασε την υδρίαν αυτής επί τον βραχίονα αυτής, και επότισεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'και αφού έπαυσε ποτίζουσα αυτόν είπε, Και διά τας καμήλους σου θέλω αντλήσει, εωσού πίωσι πάσαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Και παρευθύς εξεκένωσε την υδρίαν αυτής εις την ποτίστραν, και έδραμεν έτι εις το φρέαρ διά να αντλήση, και ήντλησε διά πάσας τας καμήλους αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Ο δε άνθρωπος, θαυμάζων δι\' αυτήν, εσιώπα, διά να γνωρίση αν κατευώδωσεν ο Κύριος την οδόν αυτού ή ουχί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Και αφού έπαυσαν αι κάμηλοι πίνουσαι, έλαβεν ο άνθρωπος ενώτια χρυσά βάρους ημίσεος σίκλου, και δύο βραχιόλια διά τας χείρας αυτής, βάρους δέκα σίκλων χρυσίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'και είπε, Τίνος θυγάτηρ είσαι συ; ειπέ μοι, παρακαλώ· είναι εν τη οικία του πατρός σου τόπος δι\' ημάς προς κατάλυμα;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Η δε είπε προς αυτόν· είμαι θυγάτηρ Βαθουήλ του υιού της Μελχάς, τον οποίον εγέννησεν εις τον Ναχώρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'είπεν έτι προς αυτόν, Είναι εις ημάς και άχυρα και τροφή πολλή και τόπος προς κατάλυμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Τότε έκλινεν ο άνθρωπος και προσεκύνησε τον Κύριον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'και είπεν, Ευλογητός Κύριος ο Θεός του κυρίου μου Αβραάμ, όστις δεν εγκατέλιπε το έλεος αυτού και την αλήθειαν αυτού από του κυρίου μου· ο Κύριος με κατευώδωσεν εις τον οίκον των αδελφών του κυρίου μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Δραμούσα δε η κόρη ανήγγειλεν εις τον οίκον της μητρός αυτής τα πράγματα ταύτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Είχε δε η Ρεβέκκα αδελφόν ονομαζόμενον Λάβαν· και έδραμεν ο Λάβαν προς τον άνθρωπον έξω εις την πηγήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Και ως είδε τα ενώτια και τα βραχιόλια εις τας χείρας της αδελφής αυτού, και ως ήκουσε τους λόγους Ρεβέκκας της αδελφής αυτού, λεγούσης, Ούτως ελάλησε προς εμέ ο άνθρωπος, ήλθε προς τον άνθρωπον· και ιδού, ίστατο πλησίον των καμήλων επί της πηγής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Και είπεν, Είσελθε, ευλογημένε του Κυρίου· διά τι ίστασαι έξω; επειδή εγώ ητοίμασα την οικίαν και τόπον διά τας καμήλους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Και εισήλθεν ο άνθρωπος εις την οικίαν, και εκείνος εξεφόρτωσε τας καμήλους και έδωκεν άχυρα και τροφήν εις τας καμήλους και ύδωρ διά νίψιμον των ποδών αυτού και των ποδών των ανθρώπων των μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Και παρετέθη έμπροσθεν αυτού φαγητόν· αυτός όμως είπε, Δεν θέλω φάγει, εωσού λαλήσω τον λόγον μου. Ο δε είπε, Λάλησον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Και είπεν, Εγώ είμαι δούλος του Αβραάμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Και ο Κύριος ευλόγησε τον κύριόν μου σφόδρα, και έγεινε μέγας· και έδωκεν εις αυτόν πρόβατα και βόας και αργύριον και χρυσίον και δούλους και δούλας και καμήλους και όνους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Και εγέννησε Σάρρα, η γυνή του κυρίου μου, υιόν εις τον κύριόν μου, αφού εγήρασε· και έδωκεν εις αυτόν πάντα όσα έχει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Και με ώρκισεν ο κύριός μου, λέγων, Δεν θέλεις λάβει γυναίκα εις τον υιόν μου εκ των θυγατέρων των Χαναναίων, εις την γην των οποίων εγώ κατοικώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'αλλ\' εις τον οίκον του πατρός μου θέλεις υπάγει και εις την συγγένειάν μου, και θέλεις λάβει γυναίκα εις τον υιόν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Και είπον προς τον κύριόν μου, Ίσως δεν θελήση η γυνή να με ακολουθήση.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Ο δε είπε προς εμέ, Ο Κύριος, έμπροσθεν του οποίου περιεπάτησα, θέλει αποστείλει τον άγγελον αυτού μετά σου και θέλει κατευοδώσει την οδόν σου· και θέλεις λάβει γυναίκα εις τον υιόν μου εκ της συγγενείας μου και εκ του οίκου του πατρός μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'τότε θέλεις είσθαι ελεύθερος από του ορκισμού μου· όταν υπάγης προς την συγγένειάν μου και δεν δώσωσιν εις σε, τότε θέλεις είσθαι ελεύθερος από του ορκισμού μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Και ελθών σήμερον εις την πηγήν, είπον, Κύριε ο Θεός του κυρίου μου Αβραάμ, κατευόδωσον, δέομαι, την οδόν μου, εις την οποίαν εγώ υπάγω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'ιδού, εγώ ίσταμαι πλησίον της πηγής του ύδατος· και η κόρη ήτις εξέρχεται διά να αντλήση και προς την οποίαν είπω, Πότισόν με, παρακαλώ, ολίγον ύδωρ εκ της υδρίας σου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'και αυτή με είπη, Και συ πίε, και διά τας καμήλους σου ακόμη θέλω αντλήσει, αύτη ας ήναι η γυνή, την οποίαν ητοίμασεν ο Κύριος διά τον υιόν του κυρίου μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Και πριν παύσω λαλών εν τη καρδία μου, ιδού, η Ρεβέκκα εξήρχετο έχουσα την υδρίαν αυτής επί του ώμου αυτής· και κατέβη εις την πηγήν και ήντλησεν· είπον δε προς αυτήν, Πότισόν με, παρακαλώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Η δε έσπευσε και κατεβίβασε την υδρίαν αυτής επάνωθεν αυτής και είπε, Πίε, και θέλω ποτίσει και τας καμήλους σου· έπιον λοιπόν και επότισε και τας καμήλους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Και ηρώτησα αυτήν και είπον, Τίνος θυγάτηρ είσαι; η δε είπε, Θυγάτηρ του Βαθουήλ, υιού του Ναχώρ, τον οποίον εγέννησεν εις αυτόν η Μελχά· και περιέθεσα τα ενώτια εις το πρόσωπον αυτής και τα βραχιόλια επί τας χείρας αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Και κλίνας προσεκύνησα τον Κύριον· και ευλόγησα Κύριον τον Θεόν του κυρίον μου Αβραάμ, όστις με κατευώδωσεν εις την αληθινήν οδόν, διά να λάβω την θυγατέρα του αδελφού του κυρίου μου εις τον υιόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Τώρα λοιπόν, εάν θέλητε να κάμητε έλεος και αλήθειαν προς τον κύριόν μου, είπατέ μοι, ει δε μη, είπατέ μοι, διά να στραφώ δεξιά ή αριστερά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Και αποκριθέντες ο Λάβαν και ο Βαθουήλ, είπον, Παρά Κυρίου εξήλθε το πράγμα· ημείς δεν δυνάμεθα να σοι είπωμεν κακόν ή καλόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'ιδού, η Ρεβέκκα έμπροσθέν σου· λάβε αυτήν και ύπαγε· και ας ήναι γυνή του υιού του κυρίου σου, καθώς ελάλησεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Και ότε ήκουσεν ο δούλος του Αβραάμ τους λόγους αυτών, προσεκύνησεν έως εδάφους τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Και εκβαλών ο δούλος σκεύη αργυρά και σκεύη χρυσά και ενδύματα, έδωκεν εις την Ρεβέκκαν· έδωκεν έτι δώρα εις τον αδελφόν αυτής και εις την μητέρα αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Και έφαγον και έπιον, αυτός και οι άνθρωποι οι μετ\' αυτού, και διενυκτέρευσαν· και αφού εσηκώθησαν το πρωΐ, είπεν, Εξαποστείλατέ με προς τον κύριόν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Είπον δε ο αδελφός αυτής και η μήτηρ αυτής, Ας μείνη η κόρη μεθ\' ημών ημέρας τινάς, τουλάχιστον δέκα· μετά ταύτα θέλει απέλθει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Και είπε προς αυτούς, Μη με κρατείτε, διότι ο Κύριος κατευώδωσε την οδόν μου· εξαποστείλατέ με να υπάγω προς τον κύριόν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Οι δε είπον, Ας καλέσωμεν την κόρην και ας ερωτήσωμεν την γνώμην αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Και εκάλεσαν την Ρεβέκκαν και είπον προς αυτήν, Υπάγεις μετά του ανθρώπου τούτου; Η δε είπεν, Υπάγω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Και εξαπέστειλαν την Ρεβέκκαν την αδελφήν αυτών και την τροφόν αυτής, και τον δούλον του Αβραάμ και τους ανθρώπους αυτού');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Και ευλόγησαν την Ρεβέκκαν και είπον προς αυτήν, Αδελφή ημών είσαι, είθε να γείνης εις χιλιάδας μυριάδων, και το σπέρμα σου να εξουσιάση τας πύλας των εχθρών αυτού');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Και εσηκώθη η Ρεβέκκα και αι θεράπαιναι αυτής, και εκάθισαν επί τας καμήλους, και υπήγον κατόπιν του ανθρώπου· και έλαβεν ο δούλος την Ρεβέκκαν και ανεχώρησεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Ο δε Ισαάκ επέστρεφεν από του φρέατος Λαχαΐ-ροΐ· διότι κατώκει εν τη γη της μεσημβρίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Και εξήλθεν ο Ισαάκ να προσευχηθή εν τη πεδιάδι περί το εσπέρας· και υψώσας τους οφθαλμούς αυτού, είδε, και ιδού, ήρχοντο κάμηλοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'και υψώσασα η Ρεβέκκα τους οφθαλμούς αυτής είδε τον Ισαάκ και κατεπήδησεν από της καμήλου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Διότι είχεν ειπεί προς τον δούλον, Τις είναι ο άνθρωπος εκείνος, ο ερχόμενος διά της πεδιάδος εις συνάντησιν ημών; Ο δε δούλος είχεν ειπεί, Είναι ο κύριός μου. Και αυτή λαβούσα την καλύπτραν, εσκεπάσθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Και διηγήθη ο δούλος προς τον Ισαάκ πάντα όσα είχε πράξει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Ο δε Ισαάκ έφερεν αυτήν εις την σκηνήν της μητρός αυτού Σάρρας· και έλαβε την Ρεβέκκαν, και έγεινεν αυτού γυνή, και ηγάπησεν αυτήν· και παρηγορήθη ο Ισαάκ περί της μητρός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Έλαβε δε ο Αβραάμ και άλλην γυναίκα, ονομαζομένην Χεττούραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Και αύτη εγέννησεν εις αυτόν τον Ζεμβράν και τον Ιοξάν και τον Μαδάν και τον Μαδιάμ και τον Ιεσβώκ και τον Σουά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'και ο Ιοξάν εγέννησε τον Σεβά και τον Δαιδάν· οι δε υιοί του Δαιδάν ήσαν Ασσουρείμ και Λετουσιείμ και Λαωμείμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Οι υιοί δε του Μαδιάμ ήσαν Γεφά και Εφέρ και Ανώχ και Αβειδά και Ελδαγά· πάντες ούτοι υιοί της Χεττούρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Έδωκε δε ο Αβραάμ πάντα τα υπάρχοντα αυτού εις τον Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Εις δε τους υιούς των παλλακών αυτού έδωκεν ο Αβραάμ χαρίσματα, και εξαπέστειλεν αυτούς, έτι ζων, μακράν από του υιού αυτού Ισαάκ προς ανατολάς, εις την γην της Ανατολής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Και ταύτα είναι τα έτη των ημερών της ζωής του Αβραάμ, όσα έζησεν, έτη εκατόν εβδομήκοντα πέντε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Και εκπνεύσας απέθανεν ο Αβραάμ εν γήρατι καλώ, γέρων και πλήρης ημερών· και προσετέθη εις τον λαόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Και έθαψαν αυτόν ο Ισαάκ και ο Ισμαήλ οι υιοί αυτού εν τω σπηλαίω Μαχπελάχ, εν τω αγρώ του Εφρών, υιού του Σωάρ του Χετταίου, τω απέναντι της Μαμβρή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'τω αγρώ, τον οποίον ηγόρασεν ο Αβραάμ παρά των υιών του Χέτ· εκεί ετάφη ο Αβραάμ και Σάρρα η γυνή αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Και μετά τον θάνατον του Αβραάμ, ευλόγησεν ο Θεός Ισαάκ τον υιόν αυτού· και κατώκησεν ο Ισαάκ πλησίον του φρέατος Λαχαΐ-ροΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Αύτη δε είναι η γενεαλογία του Ισμαήλ, υιού του Αβραάμ, τον οποίον εγέννησεν εις τον Αβραάμ Άγαρ η Αιγυπτία, η δούλη της Σάρρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'και ταύτα είναι τα ονόματα των υιών του Ισμαήλ, κατά τα ονόματα αυτών, εις τας γενεάς αυτών· πρωτότοκος του Ισμαήλ Ναβαϊώθ, έπειτα Κηδάρ και Αβδεήλ και Μιβσάμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'και Μισμά, και Δουμά και Μασσά');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Χαδδάρ, και Θαιμά, Ιετούρ, Ναφίς, και Κεδμά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'ούτοι είναι οι υιοί του Ισμαήλ, και ταύτα τα ονόματα αυτών κατά τας κώμας αυτών και κατά τας κατοικίας αυτών· δώδεκα άρχοντες κατά τα έθνη αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Και ταύτα είναι τα έτη της ζωής του Ισμαήλ, έτη εκατόν τριάκοντα επτά· και εκπνεύσας απέθανε και προσετέθη εις τον λαόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Κατώκησαν δε από Αβιλά έως Σούρ, της κατά πρόσωπον Αιγύπτου, καθώς υπάγει τις προς την Ασσυρίαν· ο Ισμαήλ κατώκησεν έμπροσθεν πάντων των αδελφών αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Και αύτη είναι η γενεαλογία του Ισαάκ, υιού του Αβραάμ· ο Αβραάμ εγέννησε τον Ισαάκ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'ήτο δε ο Ισαάκ ετών τεσσαράκοντα, ότε έλαβεν εις εαυτόν γυναίκα την Ρεβέκκαν, θυγατέρα Βαθουήλ του Σύρου από Παδάν-αράμ, αδελφήν Λάβαν του Σύρου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Και εδέετο ο Ισαάκ προς τον Κύριον περί της γυναικός αυτού, διότι ήτο στείρα· και επήκουσεν ο Κύριος αυτού, και συνέλαβεν η Ρεβέκκα η γυνή αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Και τα παιδία συνεκρούοντο εντός αυτής· και είπεν, Αν μέλλη ούτω να γείνη, διά τι εγώ να συλλάβω; και υπήγε να ερωτήση τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Και είπεν ο Κύριος προς αυτήν, Δύο έθνη είναι εν τη κοιλία σου· και δύο λαοί θέλουσι διαχωρισθή από των εντοσθίων σου· και ο εις λαός θέλει είσθαι δυνατώτερος του άλλου λαού· και ο μεγαλήτερος θέλει δουλεύσει εις τον μικρότερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Και ότε επληρώθησαν αι ημέραι αυτής διά να γεννήση, ιδού, ήσαν δίδυμα εν τη κοιλία αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Εξήλθε δε ο πρώτος ερυθρός και όλος ως δέρμα δασύτριχος· και εκάλεσαν το όνομα αυτού, Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Και έπειτα εξήλθεν ο αδελφός αυτού· και η χειρ αυτού εκράτει την πτέρναν του Ησαύ· διά τούτο ωνομάσθη Ιακώβ· ο δε Ισαάκ ήτο ετών εξήκοντα, ότε εγέννησεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Ηύξησαν δε τα παιδία· και έγεινεν ο μεν Ησαύ άνθρωπος έμπειρος εις το κυνήγιον, άνθρωπος του αγρού· ο δε Ιακώβ, άνθρωπος απλούς, κατοικών εν σκηναίς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Και ο μεν Ισαάκ ηγάπα τον Ησαύ, διότι το κυνήγιον ήτο τροφή εις αυτόν· η δε Ρεβέκκα ηγάπα τον Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Εμαγείρευε δε ο Ιακώβ μαγείρευμα· και ήλθεν ο Ησαύ εκ του αγρού και ήτο αποκαμωμένος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'και είπεν ο Ησαύ προς τον Ιακώβ, Δος μοι, παρακαλώ, να φάγω από το κόκκινον, το κόκκινον τούτο, διότι είμαι αποκαμωμένος· διά τούτο εκλήθη το όνομα αυτού, Εδώμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Και είπεν ο Ιακώβ, Πώλησόν μοι σήμερον τα πρωτοτόκιά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Και ο Ησαύ είπεν, Ιδού, εγώ υπάγω να αποθάνω, και τι με ωφελούσι ταύτα τα πρωτοτόκια;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Και είπεν ο Ιακώβ, Ομοσόν μοι σήμερον· και ώμοσεν εις αυτόν· και επώλησε τα πρωτοτόκια αυτού εις τον Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Τότε ο Ιακώβ έδωκεν εις τον Ησαύ άρτον και μαγείρευμα της φακής· και έφαγε και έπιε και σηκωθείς ανεχώρησεν· ούτως ο Ησαύ κατεφρόνησε τα πρωτοτόκια.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Έγεινε δε πείνα εν τη γη, εκτός της προτέρας πείνης, της γενομένης επί των ημερών του Αβραάμ. Και υπήγεν ο Ισαάκ προς τον Αβιμέλεχ, βασιλέα των Φιλισταίων, εις Γέραρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Εφάνη δε εις αυτόν ο Κύριος και είπε, Μη καταβής εις Αίγυπτον· κατοίκησον εν τη γη την οποίαν θέλω σοι ειπεί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'παροίκει εν τη γη ταύτη, και εγώ θέλω είσθαι μετά σου, και θέλω σε ευλογήσει διότι εις σε και εις το σπέρμα σου θέλω δώσει πάντας τους τόπους τούτους· και θέλω εκπληρώσει τον όρκον, τον οποίον ώμοσα προς Αβραάμ τον πατέρα σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'και θέλω πληθύνει το σπέρμα σου ως τα άστρα του ουρανού, και θέλω δώσει εις το σπέρμα σου πάντας τους τόπους τούτους, και θέλουσιν ευλογηθή εν τω σπέρματί σου πάντα τα έθνη της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'επειδή ο Αβραάμ υπήκουσεν εις την φωνήν μου, και εφύλαξε τα προστάγματά μου, τας εντολάς μου, τα διατάγματά μου και τους νόμους μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Και κατώκησεν ο Ισαάκ εν Γεράροις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Ηρώτησαν δε οι άνδρες του τόπου περί της γυναικός αυτού· και είπεν, Αδελφή μου είναι· διότι εφοβήθη να είπη, Γυνή μου είναι· λέγων, Μήπως με φονεύσωσιν οι άνδρες του τόπου διά την Ρεβέκκαν· επειδή ήτο ώραία την όψιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Και αφού διέτριψεν εκεί πολλάς ημέρας, Αβιμέλεχ ο βασιλεύς των Φιλισταίων, κύψας από της θυρίδος είδε, και ιδού, ο Ισαάκ έπαιζε μετά Ρεβέκκας της γυναικός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Εκάλεσε δε ο Αβιμέλεχ τον Ισαάκ και είπεν, Ιδού, βεβαίως γυνή σου είναι αύτη· διά τι λοιπόν είπας, Αδελφή μου είναι; Και είπε προς αυτόν ο Ισαάκ, διότι είπον, Μήπως αποθάνω εξ αιτίας αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Και είπεν ο Αβιμέλεχ, Τι είναι τούτο, το οποίον έκαμες εις ημάς; παρ\' ολίγον ήθελε κοιμηθή τις εκ του λαού μετά της γυναικός σου, και ήθελες φέρει εφ\' ημάς ανομίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Και προσέταξεν ο Αβιμέλεχ εις πάντα τον λαόν, λέγων, Όστις εγγίση τον άνθρωπον τούτον ή την γυναίκα αυτού, θέλει εξάπαντος θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Έσπειρε δε ο Ισαάκ εν τη γη εκείνη και εσύναξε κατ\' εκείνον τον χρόνον εκατονταπλάσια· και ευλόγησεν αυτόν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Και εμεγαλύνετο ο άνθρωπος και επροχώρει αυξανόμενος, εωσού έγεινε μέγας σφόδρα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'και απέκτησε πρόβατα και βόας και δούλους πολλούς· εφθόνησαν δε αυτόν οι Φιλισταίοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Και πάντα τα φρέατα, τα οποία έσκαψαν οι δούλοι του πατρός αυτού επί των ημερών Αβραάμ του πατρός αυτού, ενέφραξαν ταύτα οι Φιλισταίοι και εγέμισαν αυτά χώμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Και είπεν ο Αβιμέλεχ προς τον Ισαάκ, Άπελθε αφ\' ημών, διότι έγεινες δυνατώτερος ημών σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Και απήλθεν εκείθεν ο Ισαάκ και έστησε την σκηνήν αυτού εν τη κοιλάδι των Γεράρων και κατώκησεν εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Και ήνοιξε πάλιν ο Ισαάκ τα φρέατα του ύδατος, τα οποία έσκαψαν επί των ημερών Αβραάμ του πατρός αυτού, οι δε Φιλισταίοι ενέφραξαν αυτά μετά τον θάνατον του Αβραάμ· και ωνόμασεν αυτά κατά τα ονόματα, με τα οποία ο πατήρ αυτού είχεν ονομάσει αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Και έσκαψαν οι δούλοι του Ισαάκ εν τη κοιλάδι και εύρηκαν εκεί φρέαρ ύδατος ζώντος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Ελογομάχησαν δε οι ποιμένες των Γεράρων μετά των ποιμένων του Ισαάκ, λέγοντες, Ιδικόν μας είναι το ύδωρ· και ωνόμασε το φρέαρ Εσέκ· διότι εφιλονείκησαν μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Και έσκαψαν άλλο φρέαρ και ελογομάχησαν και περί αυτού· διά τούτο ωνόμασεν αυτό Σιτνά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Και μετοικήσας εκείθεν έσκαψεν άλλο φρέαρ, και περί τούτου δεν ελογομάχησαν· και ωνόμασεν αυτό Ρεχωβώθ, λέγων, διότι τώρα επλάτυνεν ημάς ο Κύριος και ηύξησεν ημάς επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Και εκείθεν ανέβη εις Βηρ-σαβεέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Και εφάνη εις αυτόν ο Κύριος την νύκτα εκείνην, και είπεν, Εγώ είμαι ο Θεός Αβραάμ του πατρός σου· μη φοβού, διότι εγώ είμαι μετά σου, και θέλω σε ευλογήσει και θέλω πληθύνει το σπέρμα σου, διά Αβραάμ τον δούλον μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Και ωκοδόμησεν εκεί θυσιαστήριον και επεκαλέσθη το όνομα του Κυρίου· και έστησεν εκεί την σκηνήν αυτού· έσκαψαν δε εκεί οι δούλοι του Ισαάκ φρέαρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Τότε ο Αβιμέλεχ υπήγε προς αυτόν από Γεράρων, και Οχοζάθ ο οικείος αυτού, και Φιχόλ ο αρχιστράτηγος της δυνάμεως αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Και είπε προς αυτούς ο Ισαάκ, Διά τι ήλθετε προς εμέ, αφού σεις με εμισήσατε και με εδιώξατε από σας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'οι δε είπον, Είδομεν φανερά, ότι ο Κύριος είναι μετά σου, και είπομεν, Ας γείνη τώρα όρκος μεταξύ ημών, μεταξύ ημών και σου, και ας κάμωμεν συνθήκην μετά σου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'ότι δεν θέλεις κάμει κακόν εις ημάς, καθώς ημείς δεν σε ηγγίσαμεν, και καθώς επράξαμεν εις σε μόνον καλόν, και σε εξαπεστείλαμεν εν ειρήνη· τώρα συ είσαι ευλογημένος του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Και έκαμεν εις αυτούς συμπόσιον· και έφαγον και έπιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Και εσηκώθησαν ενωρίς το πρωΐ, και ώμοσεν ο εις προς τον άλλον· τότε ο Ισαάκ εξαπέστειλεν αυτούς, και απήλθον απ\' αυτού εν ειρήνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Και την ημέραν εκείνην ήλθον οι δούλοι του Ισαάκ και ανήγγειλαν προς αυτόν περί του φρέατος το οποίον έσκαψαν, και είπαν προς αυτόν, Ευρήκαμεν ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Και ωνόμασεν αυτό Σαβεέ· διά τούτο είναι το όνομα της πόλεως Βηρ-σαβεέ έως της σήμερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Ήτο δε ο Ησαύ ετών τεσσαράκοντα, ότε έλαβεν εις γυναίκα Ιουδίθ, την θυγατέρα Βεηρί του Χετταίου, και Βασεμάθ, την θυγατέρα Αιλών του Χετταίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'και αύται ήσαν πικρία ψυχής εις τον Ισαάκ και την Ρεβέκκαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Και αφού εγήρασεν ο Ισαάκ, και οι οφθαλμοί αυτού ημβλύνθησαν, ώστε δεν έβλεπεν, εκάλεσεν Ησαύ τον υιόν αυτού τον μεγαλήτερον, και είπε προς αυτόν, Υιέ μου. Ο δε είπε προς αυτόν, Ιδού, εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Και εκείνος είπεν, Ιδού, τώρα, εγώ εγήρασα· δεν γνωρίζω την ημέραν του θανάτου μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'λάβε λοιπόν, παρακαλώ, τα όπλα σου, την φαρέτραν σου και το τόξον σου, και έξελθε εις την πεδιάδα και κυνήγησόν μοι κυνήγιον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'και κάμε μοι εδέσματα καθώς αγαπώ, και φέρε μοι να φάγω, διά να σε ευλογήση η ψυχή μου πριν αποθάνω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Η δε Ρεβέκκα ήκουσεν ενώ ελάλει ο Ισαάκ προς Ησαύ τον υιόν αυτού. Και υπήγεν ο Ησαύ εις την πεδιάδα διά να κυνηγήση κυνήγιον και να φέρη αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Και η Ρεβέκκα ελάλησε προς Ιακώβ τον υιόν αυτής, λέγουσα, Ιδού, εγώ ήκουσα τον πατέρα σου λαλούντα προς Ησαύ τον αδελφόν και λέγοντα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Φέρε μοι κυνήγιον και κάμε μοι εδέσματα, διά να φάγω, και να σε ευλογήσω ενώπιον του Κυρίου πριν αποθάνω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Τώρα λοιπόν, υιέ μου, άκουσον την φωνήν μου εις όσα εγώ σοι παραγγέλλω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'ύπαγε τώρα εις το ποίμνιον, και λάβε μοι εκείθεν δύο καλά ερίφια εξ αιγών· διά να κάμω αυτά εδέσματα διά τον πατέρα σου, καθώς αγαπά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'και θέλεις φέρει αυτά προς τον πατέρα σου να φάγη, διά σε ευλογήση πριν αποθάνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Και είπεν ο Ιακώβ προς Ρεβέκκαν την μητέρα αυτού, Ιδού, ο Ησαύ ο αδελφός μου είναι ανήρ δασύτριχος, εγώ δε ανήρ άτριχος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'ίσως με ψηλαφήση ο πατήρ μου, και θέλω φανή εις αυτόν ως απατεών, και θέλω σύρει επ\' εμαυτόν κατάραν και ουχί ευλογίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Είπε δε προς αυτόν η μήτηρ αυτού, Επ\' εμέ η κατάρα σου, τέκνον μου· μόνον υπάκουσον εις την φωνήν μου και ύπαγε, φέρε μοι αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Και υπήγε, και έλαβε, και έφερεν αυτά προς την μητέρα αυτού· και έκαμεν η μήτηρ αυτού εδέσματα καθώς ηγάπα ο πατήρ αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Και λαβούσα η Ρεβέκκα τα καλήτερα φορέματα Ησαύ του μεγαλητέρου υιού αυτής, τα οποία είχεν εν τη οικία, ενέδυσε με αυτά Ιακώβ, τον υιόν αυτής τον νεώτερον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'και με τα δέρματα των εριφίων εσκέπασε τας χείρας αυτού, και τα γυμνά του τραχήλου αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'και έδωκεν εις τας χείρας Ιακώβ του υιού αυτής τα εδέσματα και τον άρτον, τα οποία ητοίμασε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Και ήλθε προς τον πατέρα αυτού· και είπε, Πάτερ μου. Ο δε είπεν, Ιδού, εγώ· τις είσαι, τέκνον μου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Και είπεν ο Ιακώβ προς τον πατέρα αυτού, Εγώ είμαι Ησαύ ο πρωτότοκός σου· έκαμα καθώς μοι είπας, σηκώθητι λοιπόν, κάθισον και φάγε εκ του κυνηγίου μου, διά να με ευλογήση η ψυχή σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Και είπεν ο Ισαάκ προς τον υιόν αυτού, Πόθεν τούτο, τέκνον μου, ότι εύρηκας τόσον ταχέως; Ο δε είπε, Διότι Κύριος ο Θεός σου έφερεν αυτό έμπροσθέν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Και είπεν ο Ισαάκ προς τον Ιακώβ, Πλησίασον, τέκνον μου, διά να σε ψηλαφήσω, αν συ ήσαι αυτός ο υιός Ησαύ, ή ουχί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Και επλησίασεν ο Ιακώβ εις τον Ισαάκ τον πατέρα αυτού· ο δε εψηλάφησεν αυτόν, και είπεν, Η μεν φωνή είναι φωνή Ιακώβ, αι δε χείρες, χείρες Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Και δεν εγνώρισεν αυτόν, διότι αι χείρες αυτού ήσαν ως αι χείρες Ησαύ αδελφού αυτού, δασύτριχοι· και ευλόγησεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Και είπε, Συ είσαι αυτός ο υιός μου Ησαύ; Ο δε είπεν, Εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Και είπε, Φέρε πλησίον μου, και θέλω φάγει εκ του κυνηγίου του υιού μου, διά να σε ευλογήση η ψυχή μου. Και έφερε πλησίον αυτού, και έφαγεν· έφερε δε προς αυτόν οίνον και έπιε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Και είπε προς αυτόν Ισαάκ ο πατήρ αυτού, Πλησίασον τώρα, και φίλησόν με, τέκνον μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Και επλησίασε, και εφίλησεν αυτόν· και ωσφράνθη την οσμήν των ενδυμάτων αυτού, και ευλόγησεν αυτόν και είπεν, Ιδού, η οσμή του υιού μου είναι ως οσμή πεδιάδος, την οποίαν ευλόγησεν ο Κύριος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Λοιπόν ο Θεός να σοι δώση από της δρόσου του ουρανού και από του πάχους της γης και αφθονίαν σίτου και οίνου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Λαοί να σε δουλεύσωσι και έθνη να σε προσκυνήσωσι· να ήσαι κύριος των αδελφών σου, και οι υιοί της μητρός σου να σε προσκυνήσωσι· κατηραμένος όστις σε καταράται, και ευλογημένος όστις σε ευλογεί');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Και καθώς έπαυσεν ο Ισαάκ ευλογών τον Ιακώβ, μόλις ο Ιακώβ είχεν εξέλθει απ\' έμπροσθεν του πατρός αυτού Ισαάκ· και ήλθεν Ησαύ ο αδελφός αυτού εκ του κυνηγίου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Και έκαμε και αυτός εδέσματα και έφερε προς τον πατέρα αυτού· και είπε προς τον πατέρα αυτού, Ας σηκωθή ο πατήρ μου, και ας φάγη εκ του κυνηγίου του υιού αυτού, διά να με ευλογήση η ψυχή σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Και είπε προς αυτόν Ισαάκ ο πατήρ αυτού, Τις είσαι; Ο δε είπεν, Είμαι ο υιός σου, ο πρωτότοκός σου Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Και εξεπλάγη ο Ισαάκ έκπληξιν μεγάλην σφόδρα, και είπε, Ποίος είναι λοιπόν εκείνος, όστις εκυνήγησε κυνήγιον, και μοι έφερε και έφαγον από πάντων πριν εισέλθης, και ευλόγησα αυτόν; και ευλογημένος θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Ότε ήκουσεν ο Ησαύ τους λόγους του πατρός αυτού, ανέκραξε κραυγήν μεγάλην και πικράν σφόδρα· και είπε προς τον πατέρα αυτού, Ευλόγησόν με, και εμέ, πάτερ μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Ο δε είπεν, Ήλθεν ο αδελφός σου μετά δόλου, και έλαβε την ευλογίαν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Και είπεν ο Ησαύ, Δικαίως εκαλέσθη το όνομα αυτού Ιακώβ, διότι τώρα δευτέραν ταύτην φοράν με υπεσκέλισεν· έλαβε τα πρωτοτόκιά μου, και ιδού, τώρα έλαβε και την ευλογίαν μου. Και είπε, Δεν εφύλαξας δι\' εμέ ευλογίαν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Και, απεκρίθη ο Ισαάκ, και είπε προς τον Ησαύ, Ιδού, κύριόν σου έκαμα αυτόν, και πάντας τους αδελφούς αυτού έκαμα δούλους αυτού, και εστήριξα αυτόν με σίτον και οίνον· και τι λοιπόν να κάμω εις σε, τέκνον μου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Και είπεν ο Ησαύ προς τον πατέρα αυτού, Μήπως ταύτην μόνην την ευλογίαν έχεις, πάτερ μου; ευλόγησόν με, και εμέ, πάτερ μου. και ύψωσεν ο Ησαύ την φωνήν αυτού, και έκλαυσε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Και απεκρίθη Ισαάκ ο πατήρ αυτού, και είπε προς αυτόν, Ιδού, η κατοίκησίς σου θέλει είσθαι εις το πάχος της γης, και εις την δρόσον του ουρανού άνωθεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'και με την μάχαιράν σου θέλεις ζη, και εις τον αδελφόν σου θέλεις δουλεύσει, όταν δε υπερισχύσης, θέλεις συντρίψει τον ζυγόν αυτού από του τραχήλου σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Και εμίσει ο Ησαύ τον Ιακώβ, διά την ευλογίαν με την οποίαν ευλόγησεν αυτόν ο πατήρ αυτού· και είπεν ο Ησαύ εν τη καρδία αυτού, Πλησιάζουσιν αι ημέραι του πένθους του πατρός μου· τότε θέλω φονεύσει Ιακώβ τον αδελφόν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Ανηγγέλθησαν, δε προς την Ρεβέκκαν οι λόγοι Ησαύ του υιού αυτής του μεγαλητέρου· και πέμψασα εκάλεσεν Ιακώβ τον υιόν αυτής τον νεώτερον, και είπε προς αυτόν, Ιδού, Ησαύ ο αδελφός σου παρηγορεί εαυτόν κατά σου, ότι θέλει σε φονεύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Τώρα λοιπόν, τέκνον μου, άκουσον την φωνήν μου· και σηκωθείς, φύγε προς Λάβαν τον αδελφόν μου εις Χαρράν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'και κατοίκησον μετ\' αυτού ημέρας τινάς, εωσού παρέλθη ο θυμός του αδελφού σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'εωσού παύση η κατά σου οργή του αδελφού σου, και λησμονήση τα όσα έπραξας εις αυτόν· τότε θέλω στείλει, και θέλω σε φέρει εκείθεν· διά τι να σας στερηθώ και τους δύο εν μιά ημέρα;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Και είπεν η Ρεβέκκα προς τον Ισαάκ, Αηδίασα την ζωήν μου εξ αιτίας των θυγατέρων του Χέτ· εάν ο Ιακώβ λάβη γυναίκα εκ των θυγατέρων του Χετ, καθώς είναι αύται εκ των θυγατέρων της γης ταύτης, τι με ωφελεί να ζω;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Και προσκαλέσας ο Ισαάκ τον Ιακώβ ευλόγησεν αυτόν, και παρήγγειλε προς αυτόν λέγων, Δεν θέλεις λάβει γυναίκα εκ των θυγατέρων Χαναάν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'σηκωθείς ύπαγε εις Παδάν-αράμ, εις την οικίαν Βαθουήλ του πατρός της μητρός σου· και εκείθεν λάβε εις σεαυτόν γυναίκα, εκ των θυγατέρων Λάβαν του αδελφού της μητρός σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'και ο Θεός ο Παντοδύναμος να σε ευλογήση και να σε αυξήση και να σε πληθύνη, ώστε να γείνης εις πλήθος λαών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'και να σοι δώση την ευλογίαν του Αβραάμ, εις σε και εις το σπέρμα σου μετά σε, διά να κληρονομήσης την γην της παροικήσεώς σου, την οποίαν έδωκεν ο Θεός εις τον Αβραάμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Και εξαπέστειλεν ο Ισαάκ τον Ιακώβ· και υπήγεν εις Παδάν-αράμ προς Λάβαν, τον υιόν του Βαθουήλ του Σύρου, τον αδελφόν Ρεβέκκας της μητρός του Ιακώβ και του Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Ιδών δε ο Ησαύ ότι ευλόγησεν ο Ισαάκ τον Ιακώβ και εξαπέστειλεν αυτόν εις Παδάν-αράμ, διά να λάβη εις εαυτόν γυναίκα εκείθεν, και ότι, ενώ ευλόγει αυτόν, παρήγγειλεν εις αυτόν, λέγων, Δεν θέλεις λάβει γυναίκα εκ των θυγατέρων Χαναάν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'και ότι υπήκουσεν ο Ιακώβ εις τον πατέρα αυτού και την μητέρα αυτού· και υπήγεν εις Παδάν-αράμ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'και ιδών ο Ησαύ ότι αι θυγατέρες Χαναάν είναι μισηταί εις τους οφθαλμούς του πατρός αυτού Ισαάκ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'υπήγεν ο Ησαύ προς τον Ισμαήλ, και εκτός των άλλων γυναικών αυτού έλαβεν εις εαυτόν γυναίκα την Μαελέθ, θυγατέρα Ισμαήλ του υιού του Αβραάμ, την αδελφήν του Ναβαϊώθ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Και εξήλθεν ο Ιακώβ από Βηρ-σαβεέ, και υπήγεν εις Χαρράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Και έφθασεν εις τινά τόπον και διενυκτέρευσεν εκεί, διότι είχε δύσει ο ήλιος· και έλαβεν εκ των λίθων του τόπου και έθεσε προσκεφάλαιον αυτού, και εκοιμήθη εν τω τόπω εκείνω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Και είδεν ενύπνιον, και ιδού, κλίμαξ εστηριγμένη εις την γην, της οποίας η κορυφή έφθανεν εις τον ουρανόν· και ιδού, οι άγγελοι του Θεού ανέβαινον και κατέβαινον επ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Και ιδού, ο Κύριος ίστατο επάνωθεν αυτής και είπεν, Εγώ είμαι Κύριος ο Θεός του Αβραάμ του πατρός σου, και ο Θεός του Ισαάκ· την γην, επί της οποίας κοιμάσαι, εις σε θέλω δώσει αυτήν και εις το σπέρμα σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'και θέλει είσθαι το σπέρμα σου ως η άμμος της γης, και θέλεις εξαπλωθή προς δύσιν και προς ανατολήν και προς βορράν και προς νότον· και θέλουσιν ευλογηθή εν σοι, και εν τω σπέρματί σου πάσαι αι φυλαί της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'και ιδού, εγώ είμαι μετά σου, και θέλω σε διαφυλάττει πανταχού, όπου αν υπάγης, και θέλω σε επαναφέρει εις την γην ταύτην· διότι δεν θέλω σε εγκαταλείψει, εωσού κάμω όσα ελάλησα προς σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Και εξεγερθείς ο Ιακώβ εκ του ύπνου αυτού, είπε, Βέβαια ο Κύριος είναι εν τω τόπω τούτω, και εγώ δεν ήξευρον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Και εφοβήθη και είπε, Πόσον φοβερός είναι ο τόπος ούτος· δεν είναι τούτο, ειμή οίκος Θεού, και αύτη η πύλη του ουρανού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Και σηκωθείς ο Ιακώβ ενωρίς το πρωΐ, έλαβε τον λίθον τον οποίον είχε θέσει προσκεφάλαιον αυτού, και έστησεν αυτόν διά στήλην και έχυσεν έλαιον επί την κορυφήν αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Και εκάλεσε το όνομα του τόπου εκείνου, Βαιθήλ· το δε όνομα της πόλεως εκείνης ήτο πρότερον Λούζ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Και ευχήθη ο Ιακώβ ευχήν, λέγων, Αν ο Θεός ήναι μετ\' εμού και με διαφυλάξη εν τη οδώ ταύτη εις την οποίαν υπάγω, και μοι δώση άρτον να φάγω και ένδυμα να ενδυθώ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'και επιστρέψω εν ειρήνη εις τον οίκον του πατρός μου, τότε ο Κύριος θέλει είσθαι Θεός μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'και ο λίθος ούτος, τον οποίον έστησα διά στήλην, θέλει είσθαι οίκος Θεού· και εκ πάντων όσα μοι δώσης, το δέκατον θέλω προσφέρει εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Και εκίνησεν ο Ιακώβ και υπήγεν εις την γην των κατοίκων της ανατολής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Και είδε, και ιδού, φρέαρ εν τη πεδιάδι και ιδού, εκεί τρία ποίμνια προβάτων αναπαυόμενα πλησίον αυτού, διότι εκ του φρέατος εκείνου επότιζον τα ποίμνια· λίθος δε μέγας ήτο επί το στόμιον του φρέατος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Και ότε συνήγοντο εκεί πάντα τα ποίμνια, απεκύλιον τον λίθον από του στομίου του φρέατος, και επότιζον τα ποίμνια· έπειτα έθετον πάλιν τον λίθον επί το στόμιον του φρέατος εις τον τόπον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Και είπε προς αυτούς ο Ιακώβ, Αδελφοί, πόθεν είσθε; Οι δε είπον, Εκ της Χαρράν είμεθα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Και είπε προς αυτούς, Γνωρίζετε Λάβαν τον υιόν του Ναχώρ; οι δε είπον, Γνωρίζομεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Και είπε προς αυτούς, Υγιαίνει; Οι δε είπον, Υγιαίνει· και ιδού, Ραχήλ η θυγάτηρ αυτού έρχεται μετά των προβάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Και είπεν, Ιδού, μένει ακόμη ημέρα πολλή, δεν είναι ώρα να συρθώσι τα κτήνη· ποτίσατε τα πρόβατα και υπάγετε να βοσκήσητε αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Οι δε είπον, Δεν δυνάμεθα, εωσού συναχθώσι πάντα τα ποίμνια, και να αποκυλίσωσι τον λίθον από του στομίου του φρέατος· τότε ποτίζομεν τα πρόβατα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Και ενώ ακόμη ελάλει προς αυτούς, ήλθεν η Ραχήλ μετά των προβάτων του πατρός αυτής· διότι αυτή έβοσκε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Και ως είδεν ο Ιακώβ την Ραχήλ, θυγατέρα του Λάβαν του αδελφού της μητρός αυτού, και τα πρόβατα του Λάβαν του αδελφού της μητρός αυτού, επλησίασεν ο Ιακώβ και απεκύλισε τον λίθον από του στομίου του φρέατος, και επότισε τα πρόβατα του Λάβαν, του αδελφού της μητρός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Και εφίλησεν ο Ιακώβ την Ραχήλ και υψώσας την φωνήν αυτού έκλαυσε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Και απήγγειλεν ο Ιακώβ προς την Ραχήλ, ότι είναι αδελφός του πατρός αυτής, και ότι είναι υιός της Ρεβέκκας· και εκείνη δραμούσα απήγγειλε τούτο εις τον πατέρα αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Και ως ήκουσεν ο Λάβαν το όνομα του Ιακώβ του υιού της αδελφής αυτού, έδραμεν εις συνάντησιν αυτού· και εναγκαλισθείς αυτόν, εφίλησεν αυτόν και έφερεν αυτόν εις την οικίαν αυτού· και διηγήθη ο Ιακώβ προς τον Λάβαν πάντα τα γενόμενα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Και είπε προς αυτόν ο Λάβαν, Βέβαια οστούν μου και σαρξ μου είσαι. Και κατώκησε μετ\' αυτού ένα μήνα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Και είπεν ο Λάβαν προς τον Ιακώβ, Επειδή είσαι αδελφός μου, διά τούτο θέλεις με δουλεύει δωρεάν; ειπέ μοι, τις θέλει είσθαι ο μισθός σου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Είχε δε Λάβαν δύο θυγατέρας· το όνομα της πρεσβυτέρας, Λεία, και το όνομα της μικροτέρας Ραχήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Και της μεν Λείας οι οφθαλμοί ήσαν ασθενείς· η δε Ραχήλ ήτο ευειδής και ώραία την όψιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Και ηγάπησεν ο Ιακώβ την Ραχήλ· και είπε, Θέλω σε δουλεύει επτά έτη διά την Ραχήλ, την θυγατέρα σου την μικροτέραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Και είπεν ο Λάβαν, Καλήτερα να δώσω αυτήν εις σε, παρά να δώσω αυτήν εις άλλον άνδρα· κατοίκησον μετ\' εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Και εδούλευσεν ο Ιακώβ διά την Ραχήλ επτά έτη· και εφαίνοντο εις αυτόν ως ημέραι ολίγαι, διά την προς αυτήν αγάπην αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Και είπεν ο Ιακώβ προς τον Λάβαν, Δος μοι την γυναίκα μου, διότι επληρώθησαν αι ημέραι μου, διά να εισέλθω προς αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Και συνήγαγεν ο Λάβαν πάντας τους ανθρώπους του τόπου και έκαμε συμπόσιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Και το εσπέρας, λαβών την Λείαν την θυγατέρα αυτού, έφερεν αυτήν προς αυτόν· και εισήλθε προς αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Και έδωκεν ο Λάβαν εις Λείαν την θυγατέρα αυτού, διά θεράπαιναν αυτής, Ζελφάν την θεράπαιναν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Και το πρωΐ, ιδού, αύτη ήτο η Λεία· και είπε προς τον Λάβαν, Τι τούτο το οποίον έπραξας εις εμέ; δεν σε εδούλευσα διά την Ραχήλ; και διά τι με ηπάτησας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Και είπεν ο Λάβαν, Δεν γίνεται ούτως εν τω τόπω ημών, να δίδωται η μικροτέρα προ της πρεσβυτέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'εκπλήρωσον την εβδομάδα ταύτης, και θέλω σοι δώσει και αυτήν, αντί της εργασίας την οποίαν θέλεις κάμει εις εμέ ακόμη άλλα επτά έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Και έκαμεν ο Ιακώβ ούτω και εξεπλήρωσε την εβδομάδα αυτής· και έδωκεν εις αυτόν την Ραχήλ την θυγατέρα αυτού εις γυναίκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Και έδωκεν ο Λάβαν εις Ραχήλ την θυγατέρα αυτού, διά θεράπαιναν αυτής, Βαλλάν την θεράπαιναν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Και εισήλθεν ο Ιακώβ και προς την Ραχήλ· και ηγάπησε την Ραχήλ περισσότερον παρά την Λείαν· και εδούλευσεν αυτόν ακόμη άλλα επτά έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Και ιδών ο Κύριος ότι εμισείτο η Λεία, ήνοιξε την μήτραν αυτής· η δε Ραχήλ ήτο στείρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Και συνέλαβεν η Λεία και εγέννησεν υιόν και εκάλεσε το όνομα αυτού Ρουβήν· διότι είπεν, Είδε βέβαια ο Κύριος την ταπείνωσίν μου· τώρα λοιπόν θέλει με αγαπήσει ο ανήρ μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Και συνέλαβε πάλιν και εγέννησεν υιόν· και είπεν, Επειδή ήκουσεν ο Κύριος ότι μισούμαι, διά τούτο μοι έδωκεν ακόμη και τούτον· και εκάλεσε το όνομα αυτού Συμεών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Και συνέλαβεν ακόμη και εγέννησεν υιόν· και είπε, Τώρα ταύτην την φοράν ο ανήρ μου θέλει ενωθή μετ\' εμού, διότι εγέννησα εις αυτόν τρεις υιούς· διά τούτο ωνόμασεν αυτόν Λευΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Και συνέλαβε πάλιν και εγέννησεν υιόν· και είπε, Ταύτην την φοράν θέλω δοξολογήσει τον Κύριον· διά τούτο εκάλεσε το όνομα αυτού Ιούδαν· και έπαυσε να γεννά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Και ότε είδεν η Ραχήλ ότι δεν ετεκνοποίησεν εις τον Ιακώβ, εφθόνησεν η Ραχήλ την αδελφήν αυτής· και είπε προς τον Ιακώβ, Δος μοι τέκνα· ειδέ μη, εγώ αποθνήσκω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Και εξήφθη ο θυμός του Ιακώβ κατά της Ραχήλ και είπε, Μήπως είμαι εγώ αντί του Θεού όστις σε εστέρησεν από καρπού κοιλίας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Η δε είπεν, Ιδού, η θεράπαινά μου Βαλλά· είσελθε προς αυτήν, και θέλει γεννήσει επί των γονάτων μου, διά να αποκτήσω και εγώ τέκνα εξ αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Και έδωκεν εις αυτόν την Βαλλάν την θεράπαιναν αυτής διά γυναίκα· και εισήλθεν ο Ιακώβ προς αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Και συνέλαβεν η Βαλλά, και εγέννησεν υιόν εις τον Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'και είπεν η Ραχήλ, Ο Θεός με έκρινε και ήκουσε και την φωνήν μου και μοι έδωκεν υιόν· διά τούτο εκάλεσε το όνομα αυτού Δαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Και συνέλαβε πάλιν η Βαλλά, η θεράπαινα της Ραχήλ, και εγέννησε δεύτερον υιόν εις τον Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'και είπεν η Ραχήλ, Δυνατήν πάλην επάλαισα μετά της αδελφής μου, και υπερίσχυσα· και εκάλεσε το όνομα αυτού Νεφθαλί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Και ότε είδεν η Λεία ότι έπαυσε να γεννά, έλαβε την Ζελφάν την θεράπαιναν αυτής, και έδωκεν αυτήν εις τον Ιακώβ διά γυναίκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Και η Ζελφά, η θεράπαινα της Λείας, εγέννησεν υιόν εις τον Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'και είπεν η Λεία, Ευτυχία έρχεται· και εκάλεσε το όνομα αυτού Γαδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Και εγέννησεν η Ζελφά, η θεράπαινα της Λείας, δεύτερον υιόν εις τον Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'και είπεν η Λεία, Μακαρία εγώ, διότι θέλουσι με μακαρίζει αι γυναίκες· και εκάλεσε το όνομα αυτού Ασήρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Και υπήγεν ο Ρουβήν εν ταις ημέραις του θερισμού του σίτου και εύρηκε μανδραγόρας εν τω αγρώ, και έφερεν αυτούς προς την Λείαν την μητέρα αυτού. Είπε δε η Ραχήλ προς την Λείαν, Δος μοι, παρακαλώ, από τους μανδραγόρας του υιού σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Η δε είπε προς αυτήν, Μικρόν πράγμα είναι, ότι έλαβες τον άνδρα μου; και θέλεις να λάβης και τους μανδραγόρας του υιού μου; και η Ραχήλ είπε, Λοιπόν ας κοιμηθή μετά σου ταύτην την νύκτα, διά τους μανδραγόρας του υιού σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Και ήλθεν ο Ιακώβ το εσπέρας εκ του αγρού, και εξελθούσα η Λεία εις συνάντησιν αυτού, είπε, Προς εμέ θέλεις εισέλθει, διότι σε εμίσθωσα τωόντι με τους μανδραγόρας του υιού μου. Και εκοιμήθη μετ\' αυτής εκείνην την νύκτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Και εισήκουσεν ο Θεός της Λείας· και συνέλαβε και εγέννησεν εις τον Ιακώβ πέμπτον υιόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Και είπεν η Λεία, Εδωκέ μοι ο Θεός τον μισθόν μου, διότι έδωκα την θεράπαινάν μου εις τον άνδρα μου· και εκάλεσε το όνομα αυτού Ισσάχαρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Και συνέλαβεν ακόμη η Λεία, και εγέννησεν έκτον υιόν εις τον Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'και είπεν η Λεία, Με επροίκισεν ο Θεός με καλήν προίκα· τώρα θέλει κατοικήσει μετ\' εμού ο ανήρ μου, διότι εγέννησα εις αυτόν εξ υιούς· και εκάλεσε το όνομα αυτού Ζαβουλών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Και μετά ταύτα εγέννησε θυγατέρα, και εκάλεσε το όνομα αυτής Δείναν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Ενεθυμήθη δε ο Θεός την Ραχήλ και εισήκουσεν αυτής ο Θεός, και ήνοιξε την μήτραν αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'και συνέλαβε, και εγέννησεν υιόν· και είπεν, Ο Κύριος αφήρεσε το όνειδός μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Και εκάλεσε το όνομα αυτού Ιωσήφ, λέγουσα, Ο Θεός να προσθέση εις εμέ και άλλον υιόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Και αφού η Ραχήλ εγέννησε τον Ιωσήφ, είπεν ο Ιακώβ προς τον Λάβαν, Εξαπόστειλόν με, διά να απέλθω εις τον τόπον μου, και εις την πατρίδα μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'δος μοι τας γυναίκάς μου και τα παιδία μου, διά τας οποίας σε εδούλευσα διά να απέλθω· διότι συ γνωρίζεις την δούλευσίν μου, την οποίαν σε εδούλευσα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Είπε δε προς αυτόν ο Λάβαν, Παρακαλώ σε, να εύρω χάριν έμπροσθέν σου· εγνώρισα εκ πείρας, ότι ο Κύριος με ευλόγησεν εξ αιτίας σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Και είπε, Διόρισόν μοι τον μισθόν σου, και θέλω σοι δώσει αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Ο δε είπε προς αυτόν, Συ γνωρίζεις τίνι τρόπω σε εδούλευσα, και πόσα έγειναν τα κτήνη σου μετ\' εμού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'διότι όσα είχες προ εμού ήσαν ολίγα, και τώρα ηύξησαν εις πλήθος· και ο Κύριος σε ευλόγησε με την έλευσίν μου· και τώρα πότε θέλω προβλέψει και εγώ διά τον οίκόν μου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Ο δε είπε, Τι να σοι δώσω; Και ο Ιακώβ είπε, δεν θέλεις μοι δώσει ουδέν· εάν κάμης εις εμέ το πράγμα τούτο, πάλιν θέλω ποιμαίνει το ποίμνιόν σου και φυλάττει αυτό·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'να περάσω σήμερον διά μέσον όλου του ποιμνίου σου, διαχωρίζων εκείθεν παν πρόβατον έχον ποικίλματα και κηλίδας, και παν το μελανωπόν μεταξύ των αρνίων, και το έχον κηλίδας και ποικίλματα μεταξύ των αιγών· και ταύτα να ήναι ο μισθός μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'και εις το εξής η δικαιοσύνη μου θέλει μαρτυρήσει περί εμού, όταν έλθη έμπροσθέν σου διά τον μισθόν μου· παν ό,τι δεν είναι με ποικίλματα και κηλίδας μεταξύ των αιγών, και μελανωπόν μεταξύ των αρνίων, θέλει λογισθή κλεμμένον υπ\' εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Και είπεν ο Λάβαν, Ιδού, έστω κατά τον λόγον σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Και την ημέραν εκείνην διεχώρισε τους τράγους τους παρδαλούς και κηλιδωτούς και πάσας τας αίγας όσαι είχον ποικίλματα και κηλίδας, πάντα όσα ήσαν διάλευκα, και πάντα τα μελανωπά μεταξύ των αρνίων, και έδωκεν αυτά εις τας χείρας των υιών αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'και έθεσε τριών ημερών οδόν μεταξύ εαυτού και του Ιακώβ· ο δε Ιακώβ εποίμαινε το υπόλοιπον του ποιμνίου του Λάβαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Και έλαβεν εις εαυτόν ο Ιακώβ ράβδους χλωράς εκ λεύκης και καρύας και πλατάνου και εξελέπισεν αυτάς κατά λεπίσματα λευκά, ώστε εφαίνετο το λευκόν το εις τας ράβδους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'και έθεσε τας ράβδους, τας οποίας εξελέπισεν, εις τα αυλάκια του ύδατος, εις τας ποτίστρας, όπου τα ποίμνια ήρχοντο να πίνωσι, διά να συλλαμβάνωσι τα ποίμνια ενώ ήρχοντο να πίνωσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Και συνελάμβανον τα ποίμνια βλέποντα τας ράβδους, και εγέννων πρόβατα παρδαλά, ποικίλα και κηλιδωτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Διεχώρισε δε ο Ιακώβ τα αρνία, και έστρεψε τα πρόσωπα των προβάτων του ποιμνίου του Λάβαν προς τα παρδαλά και προς πάντα τα μελανωπά· τα δε εαυτού ποίμνια έθεσε χωριστά, και δεν έθεσεν αυτά μετά των προβάτων του Λάβαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Και καθ\' ον καιρόν τα πρώϊμα πρόβατα ήρχοντο εις σύλληψιν, ο Ιακώβ έθετε τας ράβδους εις τα αυλάκια έμπροσθεν των οφθαλμών του ποιμνίου, διά να συλλαμβάνωσι βλέποντα προς τας ράβδους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'ότε δε τα πρόβατα ήσαν όψιμα, δεν έθετεν αυτάς· και ούτω τα όψιμα ήσαν του Λάβαν, τα δε πρώϊμα του Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Και ηύξησεν ο άνθρωπος σφόδρα σφόδρα, και απέκτησε ποίμνια πολλά και δούλας και δούλους και καμήλους και όνους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Και ήκουσεν ο Ιακώβ τους λόγους των υιών του Λάβαν, λεγόντων, Ο Ιακώβ έλαβε πάντα τα υπάρχοντα του πατρός ημών, και εκ των υπαρχόντων του πατρός ημών απέκτησε πάσαν την δόξαν ταύτην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Και είδεν ο Ιακώβ το πρόσωπον του Λάβαν, και ιδού, δεν ήτο προς αυτόν ως χθές και προχθές.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Είπε δε ο Κύριος προς τον Ιακώβ, Επίστρεψον εις την γην των πατέρων σου, και εις την συγγένειάν σου, και θέλω είσθαι μετά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Τότε έστειλεν ο Ιακώβ και εκάλεσε την Ραχήλ και την Λείαν εις την πεδιάδα προς το ποίμνιον αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'και είπε προς αυτάς, Βλέπω το πρόσωπον του πατρός σας, ότι δεν είναι προς εμέ ως χθές και προχθές· ο Θεός όμως του πατρός μου εστάθη μετ\' εμού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'και σεις εξεύρετε ότι εν όλη τη δυνάμει μου εδούλευσα τον πατέρα σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'αλλ\' ο πατήρ σας με ηπάτησε και ήλλαξε τους μισθούς μου δεκάκις· πλην ο Θεός δεν αφήκεν αυτόν να με κακοποιήση·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'ότε έλεγεν ούτω, τα ποικίλα θέλουσιν είσθαι ο μισθός σου, τότε άπαν το ποίμνιον εγέννα ποικίλα· και ότε έλεγεν ούτω, τα παρδαλά θέλουσιν είσθαι ο μισθός σου, τότε άπαν το ποίμνιον εγέννα παρδαλά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Ούτως αφήρεσεν ο Θεός το ποίμνιον του πατρός σας και έδωκεν εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Και καθ\' ον καιρόν συνελάμβανε το ποίμνιον, ύψωσα τους οφθαλμούς μου και είδον κατ\' όναρ, και ιδού, οι τράγοι και οι κριοί, οι αναβαίνοντες επί τα πρόβατα και τας αίγας, ήσαν παρδαλοί, ποικίλοι και στικτοί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Και μοι είπεν ο άγγελος του Θεού κατ\' όναρ, Ιακώβ· και είπα, Ιδού, εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Και είπεν, Ύψωσον τώρα τους οφθαλμούς σου, και ιδέ πάντας τους τράγους και τους κριούς, τους αναβαίνοντας επί τα πρόβατα και τας αίγας, ότι είναι παρδαλοί, ποικίλοι και στικτοί· διότι είδον πάντα όσα κάμνει εις σε ο Λάβαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'εγώ είμαι ο Θεός της Βαιθήλ, όπου έχρισας την στήλην και όπου ευχήθης ευχήν προς εμέ· σηκώθητι τώρα, έξελθε εκ της γης ταύτης και επίστρεψον εις την γην της συγγενείας σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Και απεκρίθησαν η Ραχήλ και η Λεία και είπον προς αυτόν, Έχομεν ημείς πλέον μερίδιον ή κληρονομίαν εν τω οίκω του πατρός ημών;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'δεν εθεωρήθημεν υπ\' αυτού ως ξέναι; διότι επώλησεν ημάς και ακόμη ολοκλήρως κατέφαγε το αργύριον ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Όθεν πάντα τα πλούτη, τα οποία αφήρεσεν ο Θεός από του πατρός ημών, είναι ημών και των τέκνων ημών· τώρα λοιπόν κάμε όσα σοι είπεν ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Τότε σηκωθείς ο Ιακώβ, έβαλε τα παιδία αυτού και τας γυναίκας αυτού επί τας καμήλους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'και απήγαγε πάντα τα κτήνη αυτού, και πάντα τα αγαθά αυτού τα οποία απέκτησε, το ποίμνιον της αποκτήσεως αυτού, το οποίον απέκτησεν εις Παδάν-αράμ, διά να απέλθη προς Ισαάκ τον πατέρα αυτού εις γην Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Ο δε Λάβαν είχεν υπάγει διά να κουρεύση τα πρόβατα αυτού και η Ραχήλ έκλεψε τα είδωλα του πατρός αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Έκρυψε δε ο Ιακώβ την φυγήν αυτού εις τον Λάβαν τον Σύρον, μη αναγγείλας προς αυτόν ότι αναχωρεί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'και έφυγεν αυτός μετά πάντων των υπαρχόντων αυτού και εσηκώθη και διέβη τον ποταμόν και διευθύνθη προς το όρος Γαλαάδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Και την τρίτην ημέραν ανηγγέλθη προς τον Λάβαν, ότι έφυγεν ο Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'και παραλαβών τους αδελφούς αυτού μεθ\' εαυτού, κατεδίωξεν οπίσω αυτού οδόν επτά ημερών· και επρόφθασεν αυτόν εν τω όρει Γαλαάδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Ήλθε δε ο Θεός προς Λάβαν τον Σύρον κατ\' όναρ την νύκτα, και είπε προς αυτόν, Φυλάχθητι, μη λαλήσης σκληρά προς τον Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Επρόφθασε λοιπόν ο Λάβαν τον Ιακώβ· ο δε Ιακώβ είχε στήσει την σκηνήν αυτού επί του όρους· ο δε Λάβαν μετά των αδελφών αυτού εσκήνωσεν επί του όρους Γαλαάδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Και είπεν ο Λάβαν προς τον Ιακώβ, Τι έκαμες, και διά τι έκρυψας εις εμέ την φυγήν σου και απήγαγες τας θυγατέρας μου ως αιχμαλώτους μαχαίρας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'διά τι έφυγες κρυφίως και έκλεψας σεαυτόν απ\' εμού και δεν μοι εφανέρωσας τούτο; διότι εγώ ήθελον σε εξαποστείλει μετ\' ευφροσύνης και μετά ασμάτων, μετά τυμπάνων και κιθάρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'και δεν με ηξίωσας μηδέ να φιλήσω τους υιούς μου, και τας θυγατέρας μου; τώρα αφρόνως έπραξας τούτο·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'δυνατή είναι η χειρ μου να σας κακοποιήση· πλην ο Θεός του πατρός σας χθές την νύκτα είπε προς εμέ, λέγων, Φυλάχθητι, μη λαλήσης σκληρά προς τον Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'τώρα λοιπόν έστω, ανεχώρησας, επειδή επεθύμησας πολύ τον οίκον του πατρός σου· αλλά διά τι έκλεψας τους θεούς μου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Και αποκριθείς ο Ιακώβ είπε προς τον Λάβαν, Έφυγον επειδή εφοβήθην· διότι είπον, Μήπως αφαιρέσης τας θυγατέρας σου απ\' εμού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'εις όντινα όμως εύρης τους θεούς σου, ας μη ζήση· έμπροσθεν των αδελφών ημών γνώρισον τι ευρίσκεται εις εμέ εκ των ιδικών σου, και λάβε. Διότι δεν ήξευρεν ο Ιακώβ ότι η Ραχήλ είχε κλέψει αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Εισήλθε λοιπόν ο Λάβαν εις την σκηνήν του Ιακώβ, και εις την σκηνήν της Λείας, και εις τας σκηνάς των δύο θεραπαινών· αλλά δεν εύρηκεν αυτούς. Τότε εξήλθεν εκ της σκηνής της Λείας, και εισήλθεν εις την σκηνήν της Ραχήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Η δε Ραχήλ είχε λάβει τα είδωλα, και βάλει αυτά εις σαμάριον καμήλου, και εκάθητο επ\' αυτά. Και ερευνήσας ο Λάβαν όλην την σκηνήν, δεν εύρηκεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Η δε είπε προς τον πατέρα αυτής, Ας μη φανή βαρύ εις τον κύριόν μου, διότι δεν δύναμαι να σηκωθώ έμπροσθέν σου, επειδή έχω τα γυναικεία. Και αυτός ηρεύνησεν, αλλά δεν εύρηκε τα είδωλα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Και ωργίσθη ο Ιακώβ και επέπληξε τον Λάβαν· και αποκριθείς ο Ιακώβ είπε προς τον Λάβαν, Τι είναι το ανόμημά μου; τι το αμάρτημά μου, ότι κατεδίωξας οπίσω μου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'αφού ηρεύνησας πάντα τα σκεύη μου, τι εύρηκας εκ πάντων των σκευών της οικίας σου; θες αυτό εδώ έμπροσθεν των αδελφών μου και αδελφών σου, διά να κρίνωσι μεταξύ των δύο ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'είκοσι έτη είναι τώρα, αφ\' ότου είμαι μετά σού· τα πρόβατά σου και αι αίγές σου δεν ητεκνώθησαν, και τους κριούς του ποιμνίου σου δεν έφαγον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'θηριάλωτον δεν έφερα εις σέ· εγώ επλήρωνον αυτό· από της χειρός μου εζήτεις ό,τι με εκλέπτετο την ημέραν, ή ό,τι με εκλέπτετο την νύκτα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'την ημέραν εκαιόμην υπό του καύματος και την νύκτα υπό του παγετού· και έφευγεν ο ύπνος μου από των οφθαλμών μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'είκοσι έτη ήδη ευρίσκομαι εν τη οικία σου· δεκατέσσαρα έτη σε εδούλευσα διά τας δύο σου θυγατέρας, και εξ έτη διά τα πρόβατά σου· και ήλλαξας τον μισθόν μου δεκάκις·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'εάν ο Θεός του πατρός μου, ο Θεός του Αβραάμ και ο φόβος του Ισαάκ, δεν ήτο μετ\' εμού, βέβαια κενόν ήθελες με εξαποστείλει τώρα· είδεν ο Θεός την ταλαιπωρίαν μου και τον κόπον των χειρών μου, και σε ήλεγξεν εχθές την νύκτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Και αποκριθείς ο Λάβαν, είπε προς τον Ιακώβ, Αι θυγατέρες αύται είναι θυγατέρες μου, και οι υιοί ούτοι υιοί μου, και τα πρόβατα ταύτα πρόβατά μου, και πάντα όσα βλέπεις είναι ιδικά μου· και τι να κάμω σήμερον εις τας θυγατέρας μου ταύτας, ή εις τα τέκνα αυτών, τα οποία εγέννησαν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'ελθέ λοιπόν τώρα, ας κάμωμεν συνθήκην, εγώ και σύ· διά να ήναι εις μαρτύριον μεταξύ εμού και σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Και έλαβεν ο Ιακώβ λίθον και έστησεν αυτόν στήλην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Και είπεν ο Ιακώβ προς τους αδελφούς αυτού, Συνάξατε λίθους· και έλαβον λίθους, και έκαμον σωρόν· και έφαγον εκεί επί του σωρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Και ο μεν Λάβαν εκάλεσεν αυτόν Ιεγάρ-σαχαδουθά· ο δε Ιακώβ εκάλεσεν αυτόν Γαλεέδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Και είπεν ο Λάβαν, Ο σωρός ούτος είναι σήμερον μαρτύριον μεταξύ εμού και σού· διά τούτο εκαλέσθη το όνομα αυτού Γαλεέδ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'και Μισπά, διότι είπεν, Ας επιβλέψη ο Κύριος αναμέσον εμού και σου, όταν αποχωρισθώμεν ο εις από του άλλου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'εάν ταλαιπωρήσης τας θυγατέρας μου, ή εάν λάβης άλλας γυναίκας εκτός των θυγατέρων μου, δεν είναι ουδείς μεθ\' ημών· βλέπε, ο Θεός είναι μάρτυς μεταξύ εμού και σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Και είπεν ο Λάβαν προς τον Ιακώβ, Ιδού, ο σωρός ούτος, και ιδού, η στήλη αύτη, την οποίαν έστησα μεταξύ εμού και σού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'ο σωρός ούτος είναι μαρτύριον, και η στήλη μαρτύριον, ότι εγώ δεν θέλω διαβή τον σωρόν τούτον προς σε, ούτε συ θέλεις διαβή τον σωρόν τούτον και την στήλην ταύτην, προς εμέ, διά κακόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'ο Θεός του Αβραάμ και ο Θεός του Ναχώρ, ο Θεός του πατρός αυτών, ας κρίνη αναμέσον ημών. Ο δε Ιακώβ ώμοσεν εις τον φόβον του πατρός αυτού Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Τότε έθυσεν ο Ιακώβ θυσίαν επί του όρους και προσεκάλεσε τους αδελφούς αυτού διά να φάγωσιν άρτον· και έφαγον άρτον και διενυκτέρευσαν επί του όρους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Και σηκωθείς ο Λάβαν ενωρίς το πρωΐ, εφίλησε τους υιούς αυτού και τας θυγατέρας αυτού, και ευλόγησεν αυτούς· και ανεχώρησεν ο Λάβαν και επέστρεψεν εις τον τόπον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Και απήλθεν ο Ιακώβ εις την οδόν αυτού· και συνήντησαν αυτόν οι άγγελοι του Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Και ότε είδεν αυτούς ο Ιακώβ είπε, Στρατόπεδον Θεού είναι τούτο· και εκάλεσε το όνομα του τόπου εκείνου, Μαχαναΐμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Και απέστειλεν ο Ιακώβ μηνυτάς έμπροσθεν αυτού προς Ησαύ τον αδελφόν αυτού εις την γην Σηείρ, εις τον τόπον του Εδώμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Και παρήγγειλεν εις αυτούς, λέγων, ούτω θέλετε ειπεί προς τον κύριόν μου τον Ησαύ, Ούτω λέγει ο δούλός σου Ιακώβ, μετά του Λάβαν παρώκησα, και διέμεινα έως του νύν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'και απέκτησα βόας και όνους πρόβατα και δούλους και δούλας· και απέστειλα να αναγγείλω προς τον κύριόν μου, διά να εύρω χάριν έμπροσθέν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Και επέστρεψαν οι μηνυταί προς τον Ιακώβ, λέγοντες, Υπήγαμεν προς τον αδελφόν σου τον Ησαύ, και μάλιστα έρχεται εις συνάντησίν σου, και τετρακόσιοι άνδρες μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Εφοβήθη δε ο Ιακώβ σφόδρα και ήτο εν αμηχανία· και διήρεσε τον λαόν, τον μεθ\' αυτού, και τα ποίμνια και τους βόας και τας καμήλους, εις δύο τάγματα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'λέγων, Εάν έλθη ο Ησαύ εις το εν τάγμα και πατάξη αυτό, το επίλοιπον τάγμα θέλει διασωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Και είπεν ο Ιακώβ, Θεέ του πατρός μου Αβραάμ και Θεέ του πατρός μου Ισαάκ, Κύριε, όστις είπας προς εμέ· Επίστρεψον εις την γην σου και εις την συγγένειάν σου και θέλω σε αγαθοποιήσει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'πολύ μικρός είμαι ως προς πάντα τα ελέη και πάσαν την αλήθειαν τα οποία έκαμες εις τον δούλον σου· διότι με την ράβδον μου διέβην τον Ιορδάνην τούτον, και τώρα έγεινα δύο τάγματα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'σώσον με, δέομαί σου, εκ της χειρός του αδελφού μου, εκ της χειρός του Ησαύ· διότι φοβούμαι αυτόν, μήπως ελθών πατάξη εμέ και την μητέρα επί τα τέκνα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'συ δε είπας, Βέβαια θέλω σε αγαθοποιήσει, και θέλω καταστήσει το σπέρμα σου ως την άμμον της θαλάσσης, ήτις εκ του πλήθους δεν δύναται να αριθμηθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Και εκοιμήθη εκεί την νύκτα εκείνην· και έλαβεν εκ των όσα έτυχον εν τη χειρί αυτού, δώρον προς Ησαύ τον αδελφόν αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'αίγας διακοσίας και τράγους είκοσι, πρόβατα διακόσια και κριούς είκοσι,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'καμήλους θηλαζούσας μετά των τέκνων αυτών τριάκοντα, δαμάλια τεσσαράκοντα και ταύρους δέκα, όνους θηλυκάς είκοσι και πωλάρια δέκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Και παρέδωκεν εις τας χείρας των δούλων αυτού, έκαστον ποίμνιον χωριστά· και είπε προς τους δούλους αυτού, Περάσατε έμπροσθέν μου και αφήσατε διάστημα μεταξύ ποιμνίου και ποιμνίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Και εις τον πρώτον παρήγγειλε, λέγων, Όταν σε συναντήση Ησαύ ο αδελφός μου, και σε ερωτήση λέγων, Τίνος είσαι; και που υπάγεις; και τίνος είναι ταύτα, τα οποία έχεις έμπροσθέν σου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'τότε θέλεις ειπεί, Ταύτα είναι του δούλου σου του Ιακώβ, δώρα στελλόμενα προς τον κύριόν μου Ησαύ· και ιδού, και αυτός οπίσω ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'ούτω παρήγγειλε και εις τον δεύτερον, και εις τον τρίτον και εις πάντας τους ακολουθούντας οπίσω των ποιμνίων, λέγων, Κατά τους λόγους τούτους θέλετε λαλήσει προς τον Ησαύ, όταν εύρητε αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'και θέλετε ειπεί, Ιδού, οπίσω ημών και αυτός ο δούλός σου Ιακώβ. Διότι έλεγε, Θέλω εξιλεώσει το πρόσωπον αυτού με το δώρον, το προπορευόμενον έμπροσθέν μου· και μετά ταύτα θέλω ιδεί το πρόσωπον αυτού· ίσως θέλει με δεχθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Το δώρον λοιπόν επέρασεν έμπροσθεν αυτού· αυτός δε έμεινε την νύκτα εκείνην εν τω στρατοπέδω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Σηκωθείς δε την νύκτα εκείνην, έλαβε τας δύο γυναίκας αυτού και τας δύο θεραπαίνας αυτού και τα ένδεκα παιδία αυτού και διέβη το πέρασμα του Ιαβόκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Και έλαβεν αυτούς και διεβίβασεν αυτούς τον χείμαρρον· διεβίβασε και τα υπάρχοντα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Ο δε Ιακώβ έμεινε μόνος· και επάλαιε μετ\' αυτού άνθρωπος έως τα χαράγματα της αυγής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'ιδών δε ότι δεν υπερίσχυσε κατ\' αυτού, ήγγισε την άρθρωσιν του μηρού αυτού· και μετετοπίσθη η άρθρωσις του μηρού του Ιακώβ, ενώ επάλαιε μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Ο δε είπεν, Άφες με να απέλθω, διότι εχάραξεν η αυγή. Και αυτός είπε, δεν θέλω σε αφήσει να απέλθης, εάν δεν με ευλογήσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Και είπε προς αυτόν, Τι είναι το όνομά σου; Ο δε είπεν, Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Και εκείνος είπε, Δεν θέλει καλεσθή πλέον το όνομά σου Ιακώβ, αλλά Ισραήλ· διότι ενίσχυσας μετά Θεού, και μετά ανθρώπων θέλεις είσθαι δυνατός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Ηρώτησε δε ο Ιακώβ λέγων, Φανέρωσόν μοι, παρακαλώ, το όνομά σου. Ο δε είπε, Διά τι ερωτάς το όνομά μου; Και ευλόγησεν αυτόν εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Και εκάλεσεν Ιακώβ το όνομα του τόπου εκείνον Φανουήλ, λέγων, Διότι είδον τον Θεόν πρόσωπον προς πρόσωπον, και εφυλάχθη η ζωή μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Και ανέτειλεν ο ήλιος επ\' αυτού, καθώς διέβη το Φανουήλ· εχώλαινε δε κατά τον μηρόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Διά τούτο μέχρι της σήμερον δεν τρώγουσιν οι υιοί του Ισραήλ τον ναρκωθέντα μυώνα, όστις είναι επί της αρθρώσεως του μηρού· διότι εκείνος ήγγισε την άρθρωσιν του μηρού του Ιακώβ κατά τον μυώνα τον ναρκωθέντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Αναβλέψας δε ο Ιακώβ είδε· και ιδού, ο Ησαύ ήρχετο, και μετ\' αυτού τετρακόσιοι άνδρες· και εμοίρασεν ο Ιακώβ τα παιδία εις την Λείαν και εις την Ραχήλ και εις τας δύο θεραπαίνας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Και τας μεν θεραπαίνας και τα τέκνα αυτών έβαλεν έμπροσθεν, την δε Λείαν και τα τέκνα αυτής, κατόπιν, και την Ραχήλ και τον Ιωσήφ, τελευταίους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Αυτός δε επέρασεν έμπροσθεν αυτών και προσεκύνησεν έως εδάφους επτάκις, έως να πλησιάση εις τον αδελφόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Και έδραμεν ο Ησαύ εις συνάντησιν αυτού και ενηγκαλίσθη αυτόν και έπεσεν επί τον τράχηλον αυτού και κατεφίλησεν αυτόν· και έκλαυσαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Και αναβλέψας είδε τας γυναίκας και τα παιδία· και είπε, Τι σου είναι ούτοι; Ο δε είπε τα παιδία, τα οποία εχάρισεν ο Θεός εις τον δούλον σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Τότε επλησίασαν αι θεράπαιναι, αυταί και τα τέκνα αυτών, και προσεκύνησαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'παρομοίως επλησίασαν και η Λεία και τα τέκνα αυτής, και προσεκύνησαν· και μετά ταύτα επλησίασαν ο Ιωσήφ και η Ραχήλ και προσεκύνησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Και είπε, Προς τι άπαν το στρατόπεδόν σου τούτο, το οποίον απήντησα; Ο δε είπε, διά να εύρω χάριν έμπροσθεν του κυρίου μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Και είπεν ο Ησαύ, Έχω πολλά, αδελφέ μου· έχε συ τα ιδικά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Και είπεν ο Ιακώβ, Ουχί, παρακαλώ· εάν εύρηκα χάριν έμπροσθέν σου, δέξαι το δώρον μου εκ των χειρών μου· διότι διά τούτο είδον το πρόσωπόν σου, ως εάν έβλεπον πρόσωπον Θεού, και συ ευηρεστήθης εις εμέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'δέξαι, παρακαλώ, τας ευλογίας μου, τας προσφερομένας προς σέ· διότι με ηλέησεν ο Θεός και έχω τα πάντα. Και εβίασεν αυτόν και εδέχθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Και είπεν, Ας σηκωθώμεν και ας υπάγωμεν, και εγώ θέλω προπορεύεσθαι έμπροσθέν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Και είπε προς αυτόν ο Ιακώβ, Ο κύριός μου εξεύρει ότι τα παιδία είναι τρυφερά, και έχω μετ\' εμού εγκυμονούντα πρόβατα και βόας· και εάν βιάσωσιν αυτά μίαν μόνην ημέραν, άπαν το ποίμνιον θέλει αποθάνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Ας περάση, παρακαλώ, ο κύριός μου έμπροσθεν του δούλου αυτού· και εγώ θέλω ακολουθεί βραδέως, κατά το βάδισμα των κτηνών των έμπροσθέν μου, και κατά το βάδισμα των παιδαρίων, εωσού φθάσω προς τον κύριόν μου εις Σηείρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Και είπεν ο Ησαύ, Ας αφήσω λοιπόν μετά σου μέρος εκ του λαού, του μετ\' εμού. Ο δε είπε, Διά τι τούτο; αρκεί ότι εύρηκα χάριν έμπροσθεν του κυρίου μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Επέστρεψε λοιπόν ο Ησαύ την ημέραν εκείνην εις την οδόν αυτού εις Σηείρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Και απήλθεν ο Ιακώβ εις Σοκχώθ, και ωκοδόμησεν εις εαυτόν οικίαν, και διά τα κτήνη αυτού έκαμε σκηνάς· διά τούτο εκάλεσε το όνομα του τόπου Σοκχώθ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Και αφού επέστρεψεν ο Ιακώβ από Παδάν-αράμ, ήλθεν εις Σαλήμ, πόλιν Συχέμ, την εν τη γη Χαναάν· και κατεσκήνωσεν έμπροσθεν της πόλεως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Και ηγόρασε την μερίδα του αγρού, όπου έστησε την σκηνήν αυτού, παρά των υιών του Εμμώρ, πατρός του Συχέμ, δι\' εκατόν αργύρια.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Και έστησεν εκεί θυσιαστήριον, και εκάλεσεν αυτό Ελ-ελωέ-Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Και εξήλθε Δείνα η θυγάτηρ της Λείας, την οποίαν εγέννησεν εις τον Ιακώβ, διά να ίδη τας θυγατέρας του τόπου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Και ιδών αυτήν Συχέμ, ο υιός του Εμμώρ του Ευαίου, άρχοντος του τόπου, έλαβεν αυτήν, και εκοιμήθη μετ\' αυτής και εταπείνωσεν αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Και η ψυχή αυτού προσεκολλήθη εις την Δείναν, την θυγατέρα του Ιακώβ· και ηγάπησε την κόρην και ελάλησε κατά την καρδίαν της κόρης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Και είπεν ο Συχέμ προς Εμμώρ τον πατέρα αυτού, λέγων, Λάβε μοι την κόρην ταύτην εις γυναίκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Και ήκουσεν ο Ιακώβ, ότι εμίανε την Δείναν την θυγατέρα αυτού· οι δε υιοί αυτού ήσαν μετά των κτηνών αυτού εν τω αγρώ· και παρεσιώπησεν ο Ιακώβ εωσού έλθωσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Εμμώρ δε, ο πατήρ του Συχέμ, εξήλθε προς τον Ιακώβ, διά να ομιλήση μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Και ήλθον οι υιοί του Ιακώβ εκ του αγρού, καθώς ήκουσαν τούτο· και ηγανάκτησαν οι άνδρες και εθυμώθησαν σφόδρα, ότι έπραξεν αισχρά εις τον Ισραήλ, κοιμηθείς μετά της θυγατρός του Ιακώβ· το οποίον δεν έπρεπε να γείνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Και ελάλησε προς αυτούς ο Εμμώρ, λέγων, Η ψυχή του Συχέμ του υιού μου προσηλώθη εις την θυγατέρα σας· δότε αυτήν εις αυτόν, παρακαλώ, εις γυναίκα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'και συμπενθερεύσατε μεθ\' ημών· τας θυγατέρας σας δότε εις ημάς, και τας θυγατέρας ημών λάβετε εις εαυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'και κατοικήσατε μεθ\' ημών· ιδού, η γη είναι έμπροσθέν σας· κατοικείτε και εμπορεύεσθε επ\' αυτής και κάμετε κτήματα εν αυτή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Είπε δε ο Συχέμ προς τον πατέρα αυτής και προς τους αδελφούς αυτής, Ας εύρω χάριν έμπροσθέν σας· και ό,τι είπητε εις εμέ θέλω δώσει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'ζητήσατε παρ\' εμού όσην προίκα θέλετε, και όσα χαρίσματα, και θέλω δώσει αυτά, καθώς ηθέλετε μοι ειπεί· μόνον δότε μοι την κόρην εις γυναίκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Απεκρίθησαν δε οι υιοί του Ιακώβ προς τον Συχέμ και προς τον Εμμώρ τον πατέρα αυτού, μετά δόλου· και ελάλησαν επειδή αυτός είχε μιάνει την Δείναν την αδελφήν αυτών');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'και είπον προς αυτούς, Δεν δυνάμεθα να κάμωμεν το πράγμα τούτο, να δώσωμεν την αδελφήν ημών εις άνθρωπον απερίτμητον· διότι τούτο είναι όνειδος εις ημάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'επί τούτω μόνον θέλομεν συμφωνήσει με σάς· Εάν σεις γείνετε ως ημείς, περιτέμνοντες παν αρσενικόν μεταξύ σας,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'τότε θέλομεν δώσει τας θυγατέρας ημών εις εσάς, και τας θυγατέρας σας θέλομεν λάβει εις ημάς, και θέλομεν κατοικήσει με σας και θέλομεν γείνει εις λαός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'εάν όμως δεν μας ακούσητε να περιτμηθήτε, τότε θέλομεν λάβει την θυγατέρα ημών και θέλομεν αναχωρήσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Και ήρεσαν οι λόγοι αυτών εις τον Εμμώρ και εις τον Συχέμ τον υιόν του Εμμώρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'και δεν εβράδυνεν ο νέος να κάμη το πράγμα, διότι υπερηγάπα την θυγατέρα του Ιακώβ· και ήτο ο ενδοξότερος παντός του οίκου του πατρός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Και ήλθεν ο Εμμώρ και ο Συχέμ ο υιός αυτού εις την πύλην της πόλεως αυτών, και ελάλησαν προς τους άνδρας της πόλεως αυτών λέγοντες,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Οι άνθρωποι ούτοι είναι ειρηνικοί μεθ\' ημών· ας κατοικήσωσι λοιπόν εν τη γη και ας εμπορεύωνται εν αυτή· διότι η γη, ιδού, είναι αρκετά ευρύχωρος δι\' αυτούς· τας θυγατέρας αυτών ας λάβωμεν εις γυναίκας, και τας θυγατέρας ημών ας δώσωμεν εις αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'επί τούτω μόνον θέλουσι συμφωνήσει με ημάς οι άνθρωποι διά να κατοικήσωσι μεθ\' ημών, ώστε να γείνωμεν εις λαός, εάν περιτμηθή παν αρσενικόν μεταξύ ημών, καθώς αυτοί περιτέμνονται·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'τα ποίμνια αυτών και τα υπάρχοντα αυτών και πάντα τα κτήνη αυτών δεν θέλουσιν είσθαι ιδικά μας; μόνον ας συμφωνήσωμεν με αυτούς, και θέλουσι κατοικήσει μεθ\' ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Και εισήκουσαν του Εμμώρ και Συχέμ του υιού αυτού πάντες οι εξερχόμενοι εκ της πύλης της πόλεως αυτού· και περιετμήθη παν αρσενικόν, πάντες οι εξερχόμενοι διά της πύλης της πόλεως αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Την δε τρίτην ημέραν, ότε ήσαν εν τω πόνω, δύο εκ των υιών του Ιακώβ, ο Συμεών και ο Λευΐ, αδελφοί της Δείνας, έλαβον έκαστος την μάχαιραν αυτού, και εισήλθον εις την πόλιν ασφαλώς και εφόνευσαν παν αρσενικόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Και τον Εμμώρ και τον Συχέμ τον υιόν αυτού εφόνευσαν εν στόματι μαχαίρας· και έλαβον την Δείναν εκ του οίκου του Συχέμ και εξήλθον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Οι δε υιοί του Ιακώβ ήλθον επί τους πεφονευμένους και διήρπασαν την πόλιν, επειδή είχον μιάνει την αδελφήν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Έλαβον τα πρόβατα αυτών και τους βόας αυτών και τους όνους αυτών και ό,τι ήτο εν τη πόλει και ό,τι εν τω αγρώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'και πάσαν την περιουσίαν αυτών και πάντα τα παιδία αυτών και τας γυναίκας αυτών ηχμαλώτισαν· και παν ό,τι ευρίσκετο εν ταις οικίαις διήρπασαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Είπε δε ο Ιακώβ προς τον Συμεών και προς τον Λευΐ, Εις ταραχήν με εβάλετε, κάμνοντές με μισητόν μεταξύ των κατοίκων της γης, μεταξύ των Χαναναίων και Φερεζαίων· εγώ δε ολίγους ανθρώπους έχω, και εκείνοι θέλουσι συναχθή εναντίον μου και θέλουσι με πατάξει και θέλω απολεσθή εγώ και ο οίκός μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Οι δε είπον, Έπρεπε λοιπόν την αδελφήν ημών να μεταχειρισθώσιν ως πόρνην;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Και είπεν ο Θεός προς τον Ιακώβ, Σηκωθείς ανάβηθι εις Βαιθήλ και κατοίκησον εκεί· και κάμε εκεί θυσιαστήριον εις τον Θεόν, όστις εφάνη εις σε ότε έφευγες από προσώπου Ησαύ του αδελφού σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Και είπεν ο Ιακώβ προς τον οίκον αυτού και προς πάντας τους μεθ\' εαυτού, Εκβάλετε τους θεούς τους ξένους τους μεταξύ σας, και καθαρίσθητε και αλλάξατε τα ενδύματά σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'και σηκωθέντες, ας αναβώμεν εις Βαιθήλ· και εκεί θέλω κάμει θυσιαστήριον εις τον Θεόν, όστις μου επήκουσεν εν τη ημέρα της θλίψεώς μου και ήτο μετ\' εμού εν τη οδώ, καθ\' ην επορευόμην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Και έδωκαν εις τον Ιακώβ πάντας τους ξένους θεούς, όσοι ήσαν εις τας χείρας αυτών, και τα ενώτια τα εις τα ωτία αυτών· και έκρυψεν αυτά ο Ιακώβ υπό την δρυν, την πλησίον της Συχέμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Μετά ταύτα ανεχώρησαν· και επέπεσε τρόμος του Θεού επί τας πόλεις τας κύκλω αυτών· και δεν κατεδίωξαν οπίσω των υιών του Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Ήλθε δε ο Ιακώβ εις Λούζ, την εν τη γη Χαναάν, ήτις είναι η Βαιθήλ, αυτός και πας ο λαός ο μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Και ωκοδόμησεν εκεί θυσιαστήριον, και εκάλεσε το όνομα του τόπου Ελ-βαιθήλ· διότι εκεί εφανερώθη εις αυτόν ο Θεός, ότε έφευγεν από προσώπου του αδελφού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Απέθανε δε η Δεβόρρα, η τροφός της Ρεβέκκας, και ετάφη παρακάτω της Βαιθήλ, υπό την δρύν· και ωνομάσθη η δρυς Αλλόν-βακούθ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Εφάνη δε πάλιν ο Θεός εις τον Ιακώβ, αφού επέστρεψεν από Παδάν-αράμ, και ευλόγησεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Και είπε προς αυτόν ο Θεός, Το όνομά σου είναι Ιακώβ· δεν θέλεις ονομάζεσθαι πλέον Ιακώβ, αλλά Ισραήλ θέλει είσθαι το όνομα σου· και εκάλεσε το όνομα αυτού Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Είπε δε προς αυτόν ο Θεός, Εγώ είμαι ο Θεός ο Παντοκράτωρ· αυξάνου και πληθύνου· έθνος, και πλήθος εθνών θέλουσι γείνει εκ σου, και βασιλείς θέλουσιν εξέλθει εκ της οσφύος σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'και την γην, την οποίαν έδωκα εις τον Αβραάμ και εις τον Ισαάκ, εις σε θέλω δώσει αυτήν· και εις το σπέρμα σου μετά σε θέλω δώσει την γην ταύτην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Και ανέβη ο Θεός απ\' αυτού, εκ του τόπου όπου ελάλησε μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Και έστησεν ο Ιακώβ στήλην εν τω τόπω όπου ελάλησε μετ\' αυτού, στήλην λιθίνην· και έκαμεν επ\' αυτήν σπονδήν και επέχυσεν επ\' αυτήν έλαιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Και εκάλεσεν ο Ιακώβ το όνομα του τόπου, όπου ελάλησε μετ\' αυτού ο Θεός, Βαιθήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Μετά ταύτα ανεχώρησαν από Βαιθήλ· και ενώ έμενεν ολίγον διάστημα διά να φθάσωσιν εις Εφραθά, εγέννησεν η Ραχήλ· και υπέφερε μεγάλον αγώνα εις την γένναν αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Ενώ δε ευρίσκετο εις τον σκληρόν αγώνα της γέννας, είπε προς αυτήν η μαία, Μη φοβού, διότι και ούτος σου είναι υιός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'και ενώ παρέδιδε την ψυχήν διότι απέθανεν, εκάλεσε το όνομα αυτού Βεν-ονί· ο δε πατήρ αυτού εκάλεσεν αυτόν Βενιαμίν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Και απέθανεν η Ραχήλ και ετάφη εν τη οδώ της Εφραθά, ήτις είναι Βηθλεέμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Και έστησεν ο Ιακώβ στήλην επί του τάφου αυτής· αύτη είναι η στήλη του τάφου της Ραχήλ μέχρι της σήμερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Σηκωθείς δε ο Ισραήλ, έστησε την σκηνήν αυτού πέραν του Μιγδώλ-εδέρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Και ότε κατώκει ο Ισραήλ εν τη γη εκείνη, υπήγεν ο Ρουβήν και εκοιμήθη μετά της Βαλλάς παλλακής του πατρός αυτού· και ήκουσε τούτο ο Ισραήλ. Ήσαν δε οι υιοί του Ιακώβ δώδεκα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'οι υιοί της Λείας, Ρουβήν, ο πρωτότοκος του Ιακώβ, και Συμεών και Λευΐ και Ιούδας και Ισσάχαρ και Ζαβουλών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'οι υιοί της Ραχήλ, Ιωσήφ και Βενιαμίν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'οι δε υιοί της Βαλλάς, θεραπαίνης της Ραχήλ, Δαν και Νεφθαλί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'και οι υιοί της Ζελφάς, θεραπαίνης της Λείας, Γαδ και Ασήρ· ούτοι είναι οι υιοί του Ιακώβ, οίτινες εγεννήθησαν εις αυτόν εν Παδάν-αράμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Ήλθε δε ο Ιακώβ προς Ισαάκ τον πατέρα αυτού εις Μαμβρή, εις Κιριάθ-αρβά, ήτις είναι η Χεβρών, όπου ο Αβραάμ και ο Ισαάκ είχον παροικήσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Και ήσαν αι ημέραι του Ισαάκ εκατόν ογδοήκοντα έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Και εκπνεύσας ο Ισαάκ απέθανε και προσετέθη εις τον λαόν αυτού, γέρων και πλήρης ημερών· και έθαψαν αυτόν Ησαύ και Ιακώβ οι υιοί αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Αύτη δε είναι η γενεαλογία του Ησαύ, όστις είναι ο Εδώμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ο Ησαύ έλαβε γυναίκας εις εαυτόν εκ των θυγατέρων Χαναάν· την Αδά, θυγατέρα Αιλών του Χετταίου, και την Ολιβαμά, θυγατέρα του Ανά, εγγονήν Σεβεγών του υαίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'και την Βασεμάθ, θυγατέρα του Ισμαήλ, αδελφήν του Νεβαϊώθ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Εγέννησε δε εις τον Ησαύ η Αδά τον Ελιφάς· και η Βασεμάθ εγέννησε τον Ραγουήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'και η Ολιβαμά εγέννησε τον Ιεούς και τον Ιεγλόμ και τον Κορέ. Ούτοι είναι οι υιοί του Ησαύ, οι γεννηθέντες εις αυτόν εν τη γη Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Έλαβε δε ο Ησαύ τας γυναίκας αυτού και τους υιούς αυτού και τας θυγατέρας αυτού και πάντας τους ανθρώπους του οίκου αυτού και τα ποίμνια αυτού και πάντα τα κτήνη αυτού και πάντα τα υπάρχοντα τα οποία απέκτησεν εν γη Χαναάν, και υπήγεν εις άλλην γην μακράν από Ιακώβ του αδελφού αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'διότι τα υπάρχοντα αυτών ήσαν τόσον πολλά, ώστε δεν ηδύναντο να κατοικήσωσιν ομού· και δεν ηδύνατο η γη της παροικήσεως αυτών να χωρέση αυτούς, εξ αιτίας των κτηνών αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Κατώκησε δε ο Ησαύ εν τω όρει Σηείρ· ο Ησαύ είναι ο Εδώμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Και αύτη είναι η γενεαλογία του Ησαύ, πατρός των Εδωμιτών, εν τω όρει Σηείρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'ταύτα είναι τα ονόματα των υιών του Ησαύ· Ελιφάς ο υιός της Αδά γυναικός του Ησαύ, Ραγουήλ ο υιός της Βασεμάθ γυναικός του Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Και οι υιοί του Ελιφάς ήσαν Θαιμάν, Ωμάρ, Σωφάρ και Γοθώμ και Κενέζ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Η δε Θαμνά ήτο παλλακή του Ελιφάς υιού του Ησαύ, και εγέννησεν εις τον Ελιφάς τον Αμαλήκ· ούτοι ήσαν οι υιοί της Αδά γυναικός του Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Και ούτοι είναι οι υιοί του Ραγουήλ· Ναχάθ και Ζερά, Σομέ και Μοζέ· ούτοι ήσαν οι υιοί της Βασεμάθ γυναικός του Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Και ούτοι ήσαν οι υιοί της Ολιβαμά θυγατρός του Ανά, εγγόνης του Σεβεγών, της γυναικός του Ησαύ· και εγέννησεν εις τον Ησαύ τον Ιεούς και τον Ιεγλόμ και τον Κορέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Ούτοι ήσαν οι ηγεμόνες των υιών Ησαύ· οι υιοί του Ελιφάς πρωτοτόκου του Ησαύ, ηγεμών Θαιμάν, ηγεμών Ωμάρ, ηγεμών Σωφάρ, ηγεμών Κενέζ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'ηγεμών Κορέ, ηγεμών Γοθώμ, ηγεμών Αμαλήκ· ούτοι είναι οι ηγεμόνες του Ελιφάς εν τη γη Εδώμ· ούτοι ήσαν οι υιοί της Αδά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Και ούτοι ήσαν οι υιοί του Ραγουήλ υιού του Ησαύ· ηγεμών Ναχάθ, ηγεμών Ζερά, ηγεμών Σομέ, ηγεμών Μοζέ· ούτοι είναι οι ηγεμόνες του Ραγουήλ εν τη γη Εδώμ· ούτοι ήσαν οι υιοί της Βασεμάθ γυναικός του Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Και ούτοι ήσαν οι υιοί της Ολιβαμά γυναικός του Ησαύ· ηγεμών Ιεούς, ηγεμών Ιεγλόμ, ηγεμών Κορέ· ούτοι ήσαν οι ηγεμόνες της Ολιβαμά θυγατρός του Ανά, γυναικός του Ησαύ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Ούτοι είναι οι υιοί του Ησαύ, όστις είναι ο Εδώμ· και ούτοι οι ηγεμόνες αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Ούτοι είναι οι υιοί του Σηείρ του Χορραίου, οίτινες κατώκουν την γήν· Λωτάν και Σωβάλ και Σεβεγών και Ανά,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'και Δησών και Εσέρ και Δισάν· ούτοι είναι οι ηγεμόνες των Χορραίων, των υιών του Σηείρ, εν τη γη Εδώμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Οι δε υιοί του Λωτάν ήσαν Χορρί και Αιμάμ· αδελφή δε του Λωτάν, η Θαμνά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Ούτοι δε ήσαν οι υιοί του Σωβάλ· Αλβάν και Μαναχάθ και Εβάλ, Σεφώ και Ωνάμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Ούτοι δε ήσαν οι υιοί του Σεβεγών· και Αϊέ και Ανά· ούτος είναι ο Ανά όστις εύρηκε τα ύδατα εν τη ερήμω, ότε έβοσκε τους όνους Σεβεγών του πατρός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Ούτοι δε ήσαν οι υιοί του Ανά· Δησών και Ολιβαμά η θυγάτηρ του Ανά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Ούτοι δε ήσαν οι υιοί του Δησών· Αμαδάν και Ασβάν και Ιθράμ και Χαρράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ούτοι ήσαν οι υιοί του Εσέρ· Βαλαάν και Ζααβάν και Ακάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Ούτοι ήσαν οι υιοί του Δισάν· Ουζ και Αράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Ούτοι είναι οι ηγεμόνες των Χορραίων· ηγεμών Λωτάν, ηγεμών Σωβάλ, ηγεμών Σεβεγών, ηγεμών Ανά,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'ηγεμών Δησών, ηγεμών Εσέρ, ηγεμών Δισάν· ούτοι είναι οι ηγεμόνες των Χορραίων μεταξύ των ηγεμόνων αυτών εν τη γη Σηείρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Και ούτοι είναι οι βασιλείς οίτινες εβασίλευσαν εν τη γη Εδώμ, πριν βασιλεύση βασιλεύς επί τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Και εβασίλευσεν εν Εδώμ Βελά, ο υιός του Βεώρ· το δε όνομα της πόλεως αυτού ήτο Δενναβά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Και απέθανεν ο Βελά και εβασίλευσεν αντ\' αυτού ο Ιωβάβ, υιός του Ζερά, εκ Βοσόρρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Και απέθανεν ο Ιωβάβ και εβασίλευσεν αντ\' αυτού ο Χουσάμ εκ της γης των Θαιμανιτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Και απέθανεν ο Χουσάμ και εβασίλευσεν αντ\' αυτού ο Αδάδ, υιός του Βεράδ, ο πατάξας τους Μαδιανίτας εν τη πεδιάδι Μωάβ· το δε όνομα της πόλεως αυτού ήτο Αβίθ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Και απέθανεν ο Αδάδ, και εβασίλευσεν αντ\' αυτού ο Σαμλά εκ Μασρεκάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Και απέθανεν ο Σαμλά και εβασίλευσεν αντ\' αυτού ο Σαούλ εκ Ρεχωβώθ της παρά τον ποταμόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Και απέθανεν ο Σαούλ και εβασίλευσεν αντ\' αυτού Βάαλ-ανάν, ο υιός του Αχβώρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Και απέθανεν ο Βάαλ-ανάν, υιός του Αχβώρ, και εβασίλευσεν αντ\' αυτού ο Χαδδάρ· το δε όνομα της πόλεως αυτού ήτο Παού· και το όνομα της γυναικός αυτού, Μεεταβεήλ, θυγάτηρ του Ματραίδ, εγγονή του Μαιζαάβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Και ταύτα είναι τα ονόματα των ηγεμόνων του Ησαύ, κατά τας οικογενείας αυτών, κατά τους τόπους αυτών, κατά τα ονόματα αυτών. ηγεμών Θαμνά, ηγεμών Αλβά, ηγεμών Ιεθέθ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'ηγεμών Ολιβαμά, ηγεμών Ηλά, ηγεμών Φινών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'ηγεμών Κενέζ, ηγεμών Θαιμάν, ηγεμών Μιβσάρ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'ηγεμών Μαγεδιήλ, ηγεμών Ιράμ· ούτοι είναι οι ηγεμόνες του Εδώμ, κατά τας κατοικίας αυτών εν τη γη της κτήσεως αυτών· ούτος είναι ο Ησαύ, ο πατήρ των Εδωμιτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Κατώκησε δε ο Ιακώβ εν τη γη, εν ή παρώκησεν ο πατήρ αυτού, εν τη γη Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Αύτη είναι γενεαλογία του Ιακώβ. Ο Ιωσήφ, νέος ων ετών δεκαεπτά, εποίμαινε τα πρόβατα μετά των αδελφών αυτού, των υιών της Βαλλάς και των υιών της Ζελφάς, των γυναικών του πατρός αυτού· και ανέφερεν ο Ιωσήφ προς τον πατέρα αυτών την κακήν αυτών φήμην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Ο δε Ισραήλ ηγάπα τον Ιωσήφ υπέρ πάντας τους υιούς αυτού, διότι ήτο υιός του γήρατος αυτού· και έκαμεν εις αυτόν χιτώνα ποικιλόχρωμον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Βλέποντες δε οι αδελφοί αυτού, ότι αυτόν ηγάπα ο πατήρ αυτών υπέρ πάντας τους αδελφούς αυτού, εμίσησαν αυτόν και δεν ηδύναντο να ομιλώσι προς αυτόν ειρηνικώς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Ενυπνιασθείς δε ο Ιωσήφ ενύπνιον, διηγήθη αυτό εις τους αδελφούς αυτού· και εμίσησαν αυτόν έτι μάλλον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Και είπε προς αυτούς, Ακούσατε, παρακαλώ, το ενύπνιον τούτο το οποίον ενυπνιάσθην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Ιδού, ημείς εδένομεν δεμάτια εν μέσω της πεδιάδος· και ιδού, εσηκώθη το ιδικόν μου δεμάτιον και εστάθη όρθιον· και ιδού, τα ιδικά σας δεμάτια περιστραφέντα προσεκύνησαν το ιδικόν μου δεμάτιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Είπον δε προς αυτόν οι αδελφοί αυτού, Βασιλεύς θέλεις γείνει εφ\' ημάς; ή κύριος θέλεις γείνει εις ημάς; Και εμίσησαν αυτόν έτι μάλλον διά τα ενύπνια αυτού και διά τους λόγους αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Ενυπνιάσθη δε και άλλο ενύπνιον, και διηγήθη αυτό προς τους αδελφούς αυτού· και είπεν, Ιδού, ενυπνιάσθην άλλο ενύπνιον· και ιδού, ο ήλιος και η σελήνη και ένδεκα αστέρες με προσεκύνουν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Και διηγήθη αυτό προς τον πατέρα αυτού και προς τους αδελφούς αυτού και επέπληξεν αυτόν ο πατήρ αυτού και είπε προς αυτόν, Τι είναι το ενύπνιον τούτο, το οποίον ενυπνιάσθης; άραγε θέλομεν ελθεί, εγώ και η μήτηρ σου και οι αδελφοί σου, διά να σε προσκυνήσωμεν έως εδάφους;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Και εφθόνησαν αυτόν οι αδελφοί αυτού· ο δε πατήρ αυτού εφύλαττε τον λόγον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Και υπήγαν οι αδελφοί αυτού να βοσκήσωσι τα πρόβατα του πατρός αυτών εις Συχέμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Και είπεν ο Ισραήλ προς τον Ιωσήφ, Δεν βόσκουσιν οι αδελφοί σου εν Συχέμ; ελθέ να σε στείλω προς αυτούς. Ο δε είπε προς αυτόν, Ιδού, εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Και είπε προς αυτόν, Ύπαγε λοιπόν να ίδης, αν ήναι καλά οι αδελφοί σου και καλά τα πρόβατα, και φέρε μοι είδησιν. Και απέστειλεν αυτόν από της κοιλάδος της Χεβρών· και ήλθεν εις Συχέμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Και εύρηκεν αυτόν άνθρωπός τις, ενώ περιεπλανάτο εν τη πεδιάδι· και ηρώτησεν αυτόν ο άνθρωπος, λέγων, Τι ζητείς;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Ο δε είπε, Τους αδελφούς μου ζητώ· ειπέ μοι, παρακαλώ, που βόσκουσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Και είπεν ο άνθρωπος, Ανεχώρησαν από εδώ· διότι ήκουσα αυτούς λέγοντας, Ας υπάγωμεν εις Δωθάν. Και υπήγεν ο Ιωσήφ κατόπιν των αδελφών αυτού, και εύρηκεν αυτούς εν Δωθάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Οι δε ιδόντες αυτόν μακρόθεν, πριν πλησιάση εις αυτούς, συνεβουλεύθησαν κατ\' αυτού να φονεύσωσιν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Και είπεν ο εις προς τον άλλον, Ιδού, έρχεται εκείνος ο κύριος των ενυπνίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'έλθετε λοιπόν τώρα και ας φονεύσωμεν αυτόν και ας ρίψωμεν αυτόν εις ένα εκ των λάκκων· και θέλομεν ειπεί, Θηρίον κακόν κατέφαγεν αυτόν· και θέλομεν ιδεί τι θέλουσι γείνει τα ενύπνια αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Και ακούσας ο Ρουβήν ηλευθέρωσεν αυτόν εκ των χειρών αυτών, λέγων, Ας μη βλάψωμεν αυτόν εις την ζωήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Και είπε προς αυτούς ο Ρουβήν, Μη χύσητε αίμα· ρίψατε αυτόν εις τούτον τον λάκκον, τον εν τη ερήμω, και χείρα μη βάλητε επ\' αυτόν· διά να ελευθερώση αυτόν εκ των χειρών αυτών, και να αποδώση αυτόν εις τον πατέρα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Ότε λοιπόν ήλθεν ο Ιωσήφ προς τους αδελφούς αυτού, εξέδυσαν τον Ιωσήφ τον χιτώνα αυτού, τον χιτώνα τον ποικιλόχρωμον, τον επ\' αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'και λαβόντες αυτόν, έρριψαν εις τον λάκκον· ο δε λάκκος ήτο κενός· δεν είχεν ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Έπειτα εκάθησαν να φάγωσιν άρτον, και αναβλέψαντες είδον· και ιδού, συνοδία Ισμαηλιτών ήρχετο από Γαλαάδ μετά των καμήλων αυτών φορτωμένων αρώματα και βάλσαμον και μύρον, και επορεύοντο να φέρωσιν αυτά κάτω εις την Αίγυπτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Και είπεν ο Ιούδας προς τους αδελφούς αυτού, Τις η ωφέλεια, εάν φονεύσωμεν τον αδελφόν ημών και κρύψωμεν το αίμα αυτού;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'έλθετε και ας πωλήσωμεν αυτόν εις τους Ισμαηλίτας· και ας μη βάλωμεν τας χείρας ημών επ\' αυτόν· διότι αδελφός ημών, σαρξ ημών είναι. Και υπήκουσαν οι αδελφοί αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Και ενώ διέβαινον οι Μαδιανίται έμποροι, ανέσυραν και ανεβίβασαν τον Ιωσήφ εκ του λάκκου και επώλησαν τον Ιωσήφ διά είκοσι αργύρια εις τους Ισμαηλίτας· οι δε έφεραν τον Ιωσήφ εις Αίγυπτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Επέστρεψε δε ο Ρουβήν εις τον λάκκον, και ιδού, ο Ιωσήφ δεν ήτο εν τω λάκκω· και διέσχισε τα ιμάτια αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Και επέστρεψε προς τους αδελφούς αυτού, και είπε, Το παιδίον δεν υπάρχει και εγώ, εγώ που να υπάγω;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Τότε έλαβον τον χιτώνα του Ιωσήφ και έσφαξαν ερίφιον εκ των αιγών, και έβαψαν τον χιτώνα εν τω αίματι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'και απέστειλαν τον χιτώνα τον ποικιλόχρωμον, και έφεραν αυτόν προς τον πατέρα αυτών και είπον, Ευρήκαμεν τούτον· γνώρισον τώρα, αν ήναι ο χιτών του υιού σου ή ουχί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Ο δε εγνώρισεν αυτόν και είπε, Ο χιτών του υιού μου είναι· θηρίον κακόν κατέφαγεν αυτόν· όλος κατεσπαράχθη ο Ιωσήφ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Και διέσχισεν ο Ιακώβ τα ιμάτια αυτού και έβαλε σάκκον εις την οσφύν αυτού και επένθησε τον υιόν αυτού ημέρας πολλάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Και εσηκώθησαν πάντες οι υιοί αυτού και πάσαι αι θυγατέρες αυτού, διά να παρηγορήσωσιν αυτόν· αλλά δεν ήθελε να παρηγορηθή, λέγων, Ότι πενθών θέλω καταβή προς τον υιόν μου εις τον τάφον. Και έκλαυσεν αυτόν ο πατήρ αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Οι δε Μαδιανίται επώλησαν αυτόν εν τη Αιγύπτω εις τον Πετεφρήν, αυλικόν του Φαραώ, άρχοντα των σωματοφυλάκων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Και κατ\' εκείνον τον καιρόν κατέβη ο Ιούδας από των αδελφών αυτού και ετράπη προς άνθρωπον τινά Οδολλαμίτην ονομαζόμενον Ειρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Και είδεν εκεί ο Ιούδας την θυγατέρα τινός Χαναναίου, ονομαζομένου Σουά· και έλαβεν αυτήν και εισήλθε προς αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Η δε συνέλαβε, και εγέννησεν υιόν· και εκάλεσε το όνομα αυτού Ηρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Συνέλαβε δε πάλιν και εγέννησεν υιόν· και εκάλεσε το όνομα αυτού Αυνάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Εγέννησε δε πάλιν και άλλον υιόν· και εκάλεσε το όνομα αυτού Σηλά· ήτο δε ο Ιούδας εν Χασβί, ότε εγέννησε τούτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Και έλαβεν ο Ιούδας γυναίκα εις τον Ηρ τον πρωτότοκον αυτού, ονομαζομένην Θάμαρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Ο Ηρ δε ο πρωτότοκος του Ιούδα εστάθη κακός έμπροσθεν του Κυρίου· και εθανάτωσεν αυτόν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Είπε δε ο Ιούδας προς τον Αυνάν· είσελθε προς την γυναίκα του αδελφού σου, και νυμφεύθητι αυτήν, και ανάστησον σπέρμα εις τον αδελφόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Αλλ\' ο Αυνάν ήξευρεν, ότι το σπέρμα δεν ήθελεν είσθαι ιδικόν του· διά τούτο, ότε εισήρχετο προς την γυναίκα του αδελφού αυτού, εξέχυνεν επί την γην, διά να μη δώση σπέρμα εις τον αδελφόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Και τούτο το οποίον έπραττεν εφάνη κακόν έμπροσθεν του Κυρίου· όθεν εθανάτωσε και τούτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Και είπεν ο Ιούδας προς την Θάμαρ την νύμφην αυτού, Κάθου χήρα εν τω οίκω του πατρός σου, εωσού Σηλά ο υιός μου γείνη μεγάλος· διότι έλεγε, Μήπως αποθάνη και ούτος, καθώς οι αδελφοί αυτού. Υπήγε λοιπόν η Θάμαρ και κατώκησεν εν τω οίκω του πατρός αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Και μετά πολλάς ημέρας απέθανεν η θυγάτηρ του Σουά, η γυνή του Ιούδα· και αφού παρηγορήθη ο Ιούδας, ανέβη προς τους κουρευτάς των προβάτων αυτού εις Θαμνά, αυτός και ο φίλος αυτού Ειρά ο Οδολλαμίτης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Και ανήγγειλαν προς την Θάμαρ, λέγοντες, Ιδού, ο πενθερός σου αναβαίνει εις Θαμνά διά να κουρεύση τα πρόβατα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Η δε απεκδυθείσα τα ενδύματα της χηρείας αυτής, εσκεπάσθη με κάλυμμα και περιετυλίχθη και εκάθισε κατά την δίοδον την εν τη οδώ της Θαμνά· διότι είδεν ότι έγεινε μεγάλος ο Σηλά, και αυτή δεν εδόθη εις αυτόν διά γυναίκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Και ότε είδεν αυτήν ο Ιούδας, ενόμισεν αυτήν πόρνην· διότι είχε κεκαλυμμένον το πρόσωπον αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Και κατά την οδόν ετράπη προς αυτήν, και είπεν, Άφες με, παρακαλώ, να εισέλθω προς σέ· διότι δεν εγνώρισεν ότι ήτο η νύμφη αυτού. Η δε είπε, Τι θέλεις μοι δώσει, διά να εισέλθης προς εμέ;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Ο δε είπεν, Εγώ θέλω σοι στείλει ερίφιον αιγών εκ του ποιμνίου. Και εκείνη είπε, Μοι δίδεις ενέχυρον, εωσού να στείλης αυτό;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Ο δε είπε, Τι ενέχυρον να σοι δώσω; Και εκείνη είπε, την σφραγίδά σου και το περιδέρραιόν σου και την ράβδον σου την εν τη χειρί σου. Και έδωκεν αυτά εις αυτήν και εισήλθε προς αυτήν, και συνέλαβεν εξ αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Μετά ταύτα σηκωθείσα, ανεχώρησε και απεκδυθείσα το κάλυμμα αυτής, ενεδύθη τα ενδύματα της χηρείας αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Ο δε Ιούδας έστειλε το ερίφιον των αιγών διά χειρός του φίλου αυτού του Οδολλαμίτου, διά να παραλάβη το ενέχυρον εκ της χειρός της γυναικός· πλην δεν εύρηκεν αυτήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'και ηρώτησε τους ανθρώπους του τόπου αυτής, λέγων, Που είναι η πόρνη, ήτις ήτο κατά την δίοδον επί της οδού; οι δε είπον, Δεν εστάθη εδώ πόρνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Και επέστρεψε προς τον Ιούδαν και είπε, Δεν εύρηκα αυτήν· μάλιστα οι άνθρωποι του τόπου είπον, Δεν εστάθη εδώ πόρνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Και είπεν ο Ιούδας, Ας έχη αυτά, διά να μη γείνωμεν όνειδος· ιδού, εγώ έστειλα το ερίφιον τούτο, συ όμως δεν εύρηκας αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Και μετά τρεις μήνας περίπου, ανήγγειλαν προς τον Ιούδαν, λέγοντες, Θάμαρ η νύμφη σου επορνεύθη, και μάλιστα, ιδού, είναι έγκυος εκ πορνείας. Και είπεν ο Ιούδας, Φέρετε αυτήν έξω και ας κατακαυθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Και ότε εφέρετο έξω, απέστειλε προς τον πενθερόν αυτής, λέγουσα, Εκ του ανθρώπου, του οποίου είναι ταύτα, είμαι έγγυος· και είπεν έτι, Γνώρισον, παρακαλώ, τίνος είναι η σφραγίς και το περιδέρραιον, και η ράβδος αύτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Και ο Ιούδας εγνώρισεν αυτά· και είπεν, Αύτη είναι δικαιοτέρα εμού, διότι δεν έδωκα αυτήν εις τον Σηλά τον υιόν μου. Και έτι πλέον δεν εγνώρισεν αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Και καθ\' ον καιρόν έμελλε να γεννήση, ιδού, δίδυμα εν τη κοιλία αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Και ενώ εγέννα, το εν επρόβαλεν έξω την χείρα· και η μαία λαβούσα, έδεσεν επί την χείρα αυτού νήμα κόκκινον, λέγουσα, Ούτος εξήλθε πρώτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Και καθώς έσυρεν οπίσω την χείρα αυτού, ιδού, εξήλθεν ο αδελφός αυτού· και αυτή είπε, Ποίον χαλασμόν έκαμες; επί σε ας ήναι ο χαλασμός· διά τούτο εκαλέσθη το όνομα αυτού Φαρές.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Και έπειτα εξήλθεν ο αδελφός αυτού, όστις είχε το κόκκινον νήμα επί την χείρα αυτού· και εκαλέσθη το όνομα αυτού Ζαρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Ο δε Ιωσήφ κατεβιβάσθη εις την Αίγυπτον· και ο Πετεφρής ο αυλικός του Φαραώ, ο άρχων των σωματοφυλάκων, άνθρωπος Αιγύπτιος, ηγόρασεν αυτόν εκ των χειρών των Ισμαηλιτών, οίτινες κατεβίβασαν αυτόν εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Και ήτο ο Κύριος μετά του Ιωσήφ, και ήτο άνθρωπος ευοδούμενος· και ευρίσκετο εν τω οίκω του κυρίου αυτού Αιγυπτίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Και είδεν ο κύριος αυτού, ότι ο Κύριος ήτο μετ\' αυτού, και ευώδωνεν ο Κύριος εις τας χείρας αυτού πάντα όσα έκαμνε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Και εύρηκεν ο Ιωσήφ χάριν έμπροσθεν αυτού και υπηρέτει αυτόν· και κατέστησεν αυτόν επιστάτην επί του οίκου αυτού· και πάντα όσα είχε, παρέδωκεν εις τας χείρας αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Και εξ εκείνου του καιρού, αφού κατέστησεν αυτόν επιστάτην επί του οίκου αυτού και επί πάντων όσα είχεν, ευλόγησεν ο Κύριος τον οίκον του Αιγυπτίου εξ αιτίας του Ιωσήφ· και ήτο η ευλογία του Κυρίου επί πάντα όσα είχεν, εν τω οίκω και εν τοις αγροίς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Και παρέδωκε πάντα όσα είχεν εις τας χείρας του Ιωσήφ· και δεν ήξευρεν εκ των υπαρχόντων αυτού ουδέν, πλην του άρτου τον οποίον έτρωγεν. Ήτο δε ο Ιωσήφ ευειδής και ώραίος την όψιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Και μετά τα πράγματα ταύτα, η γυνή του κυρίου αυτού έρριψε τους οφθαλμούς αυτής επί τον Ιωσήφ· και είπε, Κοιμήθητι μετ\' εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Αλλ\' εκείνος δεν ήθελε, και είπε προς την γυναίκα του κυρίου αυτού, Ιδού· ο κύριός μου δεν γνωρίζει ουδέν εκ των όσα είναι μετ\' εμού εν τω οίκω· και πάντα όσα έχει, παρέδωκεν εις τας χείρας μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'δεν είναι εν τω οίκω τούτω ουδείς μεγαλήτερός μου, ούτε είναι απηγορευμένον εις εμέ άλλο τι πλην σου, διότι είσαι η γυνή αυτού· και πως να πράξω τούτο το μέγα κακόν, και να αμαρτήσω εναντίον του Θεού;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Αν και ελάλει προς τον Ιωσήφ καθ\' εκάστην ημέραν, ούτος όμως δεν υπήκουσεν εις αυτήν να κοιμηθή μετ\' αυτής, διά να συνευρεθή μετ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Και ημέραν τινά εισήλθεν ο Ιωσήφ εις την οικίαν διά να κάμη τα έργα αυτού, και ουδείς εκ των ανθρώπων του οίκου ήτο εκεί εν τω οίκω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Και εκείνη ήρπασεν αυτόν από του ιματίου αυτού, λέγουσα, Κοιμήθητι μετ\' εμού· αλλ\' εκείνος αφήσας το ιμάτιον αυτού εις τας χείρας αυτής, έφυγε, και εξήλθεν έξω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Και ως είδεν ότι αφήκε το ιμάτιον αυτού εις τας χείρας αυτής και έφυγεν έξω,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'εβόησε προς τους ανθρώπους της οικίας αυτής και ελάλησε προς αυτούς, λέγουσα, Ίδετε, έφερεν εις ημάς άνθρωπον Εβραίον διά να μας εμπαίξη· εισήλθε προς εμέ διά να κοιμηθή μετ\' εμού και εγώ εβόησα μετά φωνής μεγάλης·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'και ως ήκουσεν ότι ύψωσα την φωνήν μου και εβόησα, αφήσας το ιμάτιον αυτού παρ\' εμοί έφυγε και εξήλθεν έξω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Και απέθεσε το ιμάτιον αυτού παρ\' αυτή, εωσού ήλθεν ο κύριος αυτού εις τον οίκον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Και είπε προς αυτόν κατά τους λόγους τούτους, λέγουσα, Ο δούλος ο Εβραίος, τον οποίον έφερες εις ημάς, εισήλθε προς εμέ διά να με εμπαίξη,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'και ως ύψωσα την φωνήν μου και εβόησα, αφήσας το ιμάτιον αυτού παρ\' εμοί, έφυγεν έξω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Και ως ήκουσεν ο κύριος αυτού τους λόγους της γυναικός αυτού, τους οποίους ελάλησε προς αυτόν, λέγουσα, Ούτω μοι έκαμεν ο δούλός σου, εξήφθη η οργή αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Και λαβών ο κύριος του Ιωσήφ αυτόν, έβαλεν αυτόν εις την οχυράν φυλακήν, εις τον τόπον όπου οι δέσμιοι του βασιλέως ήσαν πεφυλακισμένοι και έμενεν εκεί εν τη οχυρά φυλακή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Αλλ\' ο Κύριος ήτο μετά του Ιωσήφ και επέχεεν εις αυτόν έλεος, και έδωκε χάριν εις αυτόν έμπροσθεν του αρχιδεσμοφύλακος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Και παρέδωκεν ο αρχιδεσμοφύλαξ εις τας χείρας του Ιωσήφ πάντας τους δεσμίους, τους εν τη οχυρά φυλακή· και πάντα όσα επράττοντο εκεί, αυτός έκαμνεν αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Ο αρχιδεσμοφύλαξ δεν εθεώρει ουδέν εκ των όσα ήσαν εις τας χείρας αυτού· διότι ο Κύριος ήτο μετ\' αυτού και ο Κύριος ευώδονεν όσα αυτός έκαμνε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Και μετά τα πράγματα ταύτα, ο οινοχόος του βασιλέως της Αιγύπτου και ο αρτοποιός ημάρτησαν εις τον κύριον αυτών τον βασιλέα της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Και ωργίσθη ο Φαραώ κατά των δύο αυλικών αυτού, κατά του αρχιοινοχόου, και κατά του αρχισιτοποιού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Και έβαλεν αυτούς υπό φύλαξιν εν τω οίκω του άρχοντος των σωματοφυλάκων, εις την οχυράν φυλακήν, εις τον τόπον όπου ο Ιωσήφ ήτο πεφυλακισμένος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Ο δε άρχων των σωματοφυλάκων ενεπιστεύθη αυτούς εις τον Ιωσήφ και ούτος υπηρέτει αυτούς· ήσαν δε καιρόν τινά εν τη φυλακή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'και ο οινοχόος και ο αρτοποιός του βασιλέως της Αιγύπτου, οίτινες ήσαν πεφυλακισμένοι εν τη οχυρά φυλακή, ενυπνιάσθησαν ενύπνιον αμφότεροι, έκαστος το ενύπνιον αυτού κατά την αυτήν νύκτα, έκαστος κατά την εξήγησιν του ενυπνίου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Ο δε Ιωσήφ εισελθών προς αυτούς το πρωΐ, είδεν αυτούς· και ιδού, ήσαν τεταραγμένοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Και ηρώτησε τους αυλικούς του Φαραώ, τους όντας μετ\' αυτού εν τη φυλακή εν τω οίκω του κυρίου αυτού, λέγων, Διά τι τα πρόσωπά σας είναι σκυθρωπά σήμερον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Οι δε είπον προς αυτόν, Ενυπνιάσθημεν ενύπνιον και δεν είναι ουδείς όστις να εξηγήση αυτό. Και είπε προς αυτούς ο Ιωσήφ, Δεν ανήκουσιν εις τον Θεόν αι εξηγήσεις; διηγήθητέ μοι, παρακαλώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Και διηγήθη ο αρχιοινοχόος το ενύπνιον αυτού προς τον Ιωσήφ και είπε προς αυτόν, Είδον εις το όνειρόν μου και ιδού, άμπελος έμπροσθέν μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'και εις την άμπελον ήσαν τρεις κλάδοι και εφαίνετο ως βλαστάνουσα και τα άνθη αυτής εξήνθησαν και οι βότρυες της σταφυλής ωρίμασαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'το δε ποτήριον του Φαραώ ήτο εν τη χειρί μου· και έλαβον τα σταφύλια και έθλιψα αυτά εις το ποτήριον του Φαραώ και έδωκα το ποτήριον εις την χείρα του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Και είπεν ο Ιωσήφ προς αυτόν, Αύτη είναι η εξήγησις αυτού· οι τρεις κλάδοι είναι τρεις ημέραι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'μετά τρεις ημέρας, ο Φαραώ θέλει υψώσει την κεφαλήν σου και θέλει σε αποκαταστήσει εις το υπούργημά σου· και θέλεις δώσει το ποτήριον του Φαραώ εις την χείρα αυτού κατά την προτέραν συνήθειαν, ότε ήσο οινοχόος αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'πλην ενθυμήθητί με, όταν γείνη εις σε το καλόν· και κάμε, παρακαλώ, έλεος προς εμέ και ανάφερε περί εμού προς τον Φαραώ και εξάγαγέ με εκ του οίκου τούτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'επειδή τη αληθεία εκλέφθην εκ της γης των Εβραίων· και εδώ πάλιν δεν έπραξα ουδέν, ώστε να με βάλωσιν εις τον λάκκον τούτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Και ιδών ο αρχισιτοποιός ότι η εξήγησις ήτο καλή, είπε προς τον Ιωσήφ, Και εγώ είδον εις το όνειρόν μου και ιδού, τρία κάνιστρα λευκά επί της κεφαλής μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'εν δε τω κανίστρω τω ανωτέρω ήσαν εκ πάντων των φαγητών του Φαραώ, της τέχνης του αρτοποιού· και τα πτηνά έτρωγον αυτά εκ του κανίστρου επάνωθεν της κεφαλής μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Και αποκριθείς ο Ιωσήφ είπεν, Αύτη είναι η εξήγησις τούτου· τα τρία κάνιστρα είναι τρεις ημέραι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'μετά τρεις ημέρας ο Φαραώ θέλει υψώσει την κεφαλήν σου επάνωθέν σου και θέλει σε κρεμάσει εις ξύλον και τα πτηνά θέλουσι φάγει την σάρκα σου επάνωθέν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Και την τρίτην ημέραν, ημέραν των γενεθλίων του Φαραώ, έκαμε συμπόσιον εις πάντας τους δούλους αυτού· και ύψωσε την κεφαλήν του αρχιοινοχόου και την κεφαλήν του αρχισιτοποιού μεταξύ των δούλων αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Και τον μεν αρχιοινοχόον αποκατέστησεν εις την οινοχοΐαν αυτού, και έδωκε το ποτήριον εις την χείρα του Φαραώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'τον δε αρχισιτοποιόν εκρέμασε, καθώς εξήγησεν ο Ιωσήφ εις αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Ο αρχιοινοχόος όμως δεν ενεθυμήθη τον Ιωσήφ, αλλά ελησμόνησεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Και μετά παρέλευσιν δύο ετών ο Φαραώ είδεν ενύπνιον· και ιδού, ίστατο πλησίον του ποταμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'και ιδού, επτά δαμάλια εύμορφα και παχύσαρκα ανέβαινον εκ του ποταμού και εβόσκοντο εις το λιβάδιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'και ιδού, άλλα επτά δαμάλια ανέβαινον μετ\' εκείνα εκ του ποταμού, άσχημα και λεπτόσαρκα, και ίσταντο πλησίον των άλλων δαμαλίων επί το χείλος του ποταμού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'και τα δαμάλια τα άσχημα και λεπτόσαρκα κατέφαγον τα επτά δαμάλια τα εύμορφα και παχύσαρκα. Τότε εξύπνησεν ο Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Και αποκοιμηθείς ενυπνιάσθη δευτέραν φοράν· και ιδού, επτά αστάχυα παχέα και καλά ανέβαινον εκ του αυτού κορμού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'και ιδού, άλλα επτά αστάχυα λεπτά και κεκαυμένα υπό του ανατολικού ανέμου ανεφύοντο μετ\' εκείνα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'και τα αστάχυα τα λεπτά κατέπιον τα επτά αστάχυα τα παχέα και μεστά. Και εξύπνησεν ο Φαραώ και ιδού, ήτο όνειρον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Και το πρωΐ το πνεύμα αυτού ήτο τεταραγμένον· και αποστείλας εκάλεσε πάντας τους μάγους της Αιγύπτου και πάντας τους σοφούς αυτής· και διηγήθη προς αυτούς ο Φαραώ τα ενύπνια αυτού· αλλά δεν ήτο ουδείς όστις να εξηγήση αυτά προς τον Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Τότε ο αρχιοινοχόος ελάλησε προς τον Φαραώ λέγων, την αμαρτίαν μου ενθυμούμαι σήμερον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'ο Φαραώ είχεν οργισθή εναντίον των δούλων αυτού και με έβαλεν εις φυλακήν εν τω οίκω του άρχοντος των σωματοφυλάκων, εμέ και τον αρχισιτοποιόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'και είδομεν ενύπνιον κατά την αυτήν νύκτα, εγώ και εκείνος· ενυπνιάσθημεν έκαστος κατά την εξήγησιν του ενυπνίου αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'και ήτο εκεί μεθ\' ημών νέος τις Εβραίος, δούλος του άρχοντος των σωματοφυλάκων· και διηγήθημεν προς αυτόν και εξήγησεν εις ημάς τα ενύπνια ημών· εις έκαστον κατά το ενύπνιον αυτού έκαμε την εξήγησιν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'και καθώς εξήγησεν εις ημάς, ούτω και συνέβη· εμέ μεν αποκατέστησεν εις το υπούργημά μου, εκείνον δε εκρέμασε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Τότε αποστείλας ο Φαραώ, εκάλεσε τον Ιωσήφ, και εξήγαγον αυτόν μετά σπουδής εκ της φυλακής· και εξυρίσθη και ήλλαξε την στολήν αυτού και ήλθε προς τον Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Και είπεν ο Φαραώ προς τον Ιωσήφ, Είδον ενύπνιον, και δεν είναι ουδείς όστις να εξηγήση αυτό· και εγώ ήκουσα περί σου να λέγωσιν ότι εννοείς τα όνειρα ώστε να εξηγής αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Και απεκρίθη ο Ιωσήφ προς τον Φαραώ λέγων, Ουχί εγώ· ο Θεός θέλει δώσει εις τον Φαραώ σωτήριον απόκρισιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Και είπεν ο Φαραώ προς τον Ιωσήφ, Εις το όνειρόν μου, ιδού, ιστάμην επί το χείλος του ποταμού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'και ιδού, επτά δαμάλια παχύσαρκα και εύμορφα ανέβαινον εκ του ποταμού και εβόσκοντο εις το λιβάδιον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'και ιδού, άλλα επτά δαμάλια ανέβαινον κατόπιν εκείνων αδύνατα και πολύ άσχημα και λεπτόσαρκα, οποία δεν είδον ποτέ ασχημότερα καθ\' όλην την γην της Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'και τα δαμάλια τα λεπτά και άσχημα κατέφαγον τα πρώτα επτά δαμάλια τα παχέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'και αφού εισήλθον εις τας κοιλίας αυτών, δεν διεκρίνετο ότι εισήλθον εις τας κοιλίας αυτών, αλλ\' η θεωρία αυτών ήτο άσχημος καθώς και πρότερον· τότε εξύπνησα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Έπειτα είδον εις το όνειρόν μου και ιδού, επτά αστάχυα ανέβαινον εκ του αυτού κορμού μεστά και καλά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'και ιδού, άλλα επτά αστάχυα ξηρά, λεπτά, κεκαυμένα υπό του ανατολικού ανέμου, ανεφύοντο κατόπιν αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'και τα αστάχυα τα λεπτά κατέπιον τα επτά αστάχυα τα καλά· και είπον ταύτα προς τους μάγους, αλλά δεν ήτο ουδείς όστις να μοι εξηγήση αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Και είπεν ο Ιωσήφ προς τον Φαραώ, Το ενύπνιον του Φαραώ εν είναι· ο Θεός εφανέρωσεν εις τον Φαραώ όσα μέλλει να κάμη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Τα επτά δαμάλια τα καλά είναι επτά έτη· και τα επτά αστάχυα τα καλά είναι επτά έτη· το ενύπνιον εν είναι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Και τα επτά δαμάλια τα λεπτά και άσχημα, τα οποία ανέβαινον κατόπιν αυτών, είναι επτά έτη· και τα επτά αστάχυα τα άμεστα, τα κεκαυμένα υπό του ανατολικού ανέμου, θέλουσιν είσθαι επτά έτη πείνης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Τούτο είναι το πράγμα το οποίον είπα προς τον Φαραώ· ο Θεός εφανέρωσεν εις τον Φαραώ όσα μέλλει να κάμη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Ιδού, έρχονται επτά έτη μεγάλης αφθονίας καθ\' όλην την γην της Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'και θέλουσιν επέλθει μετά ταύτα επτά έτη πείνης· και όλη η αφθονία θέλει λησμονηθή εν τη γη της Αιγύπτου και η πείνα θέλει καταφθείρει την γήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'και δεν θέλει γνωρισθή η αφθονία επί της γης εξ αιτίας εκείνης της πείνης, ήτις μέλλει να ακολουθήση· διότι θέλει είσθαι βαρεία σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Το δε ότι εδευτερώθη το ενύπνιον εις τον Φαραώ δις, φανερόνει ότι το πράγμα είναι αποφασισμένον παρά του Θεού και ότι ο Θεός θέλει ταχύνει να εκτελέση αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Τώρα λοιπόν ας προβλέψη ο Φαραώ άνθρωπον συνετόν και φρόνιμον και ας καταστήση αυτόν επί της γης της Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'ας κάμη ο Φαραώ και ας διορίση επιστάτας επί της γής· και ας λαμβάνη το πέμπτον από της γης Αιγύπτου εις τα επτά έτη της αφθονίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'και ας συνάξωσι πάσας τας τροφάς τούτων των ερχομένων καλών ετών, και ας αποταμιεύσωσι σίτον υπό την χείρα του Φαραώ διά τροφάς εις τας πόλεις, και ας φυλάττωσιν αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'και αι τροφαί θέλουσι μένει πεφυλαγμέναι διά την γην εις τα επτά έτη της πείνης, τα οποία θέλουσιν ακολουθήσει εν τη γη της Αιγύπτου, διά να μη απολεσθή ο τόπος υπό της πείνης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Και ήρεσεν ο λόγος εις τον Φαραώ και εις πάντας τους δούλους αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Και είπεν ο Φαραώ προς τους δούλους αυτού, Δυνάμεθα να εύρωμεν καθώς τούτον, άνθρωπον εις τον οποίον υπάρχει το πνεύμα του Θεού;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Και είπεν ο Φαραώ προς τον Ιωσήφ, Επειδή ο Θεός έδειξεν εις σε πάντα ταύτα, δεν είναι ουδείς τόσον συνετός και φρόνιμος όσον συ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Συ θέλεις είσθαι επί του οίκου μου και εις τον λόγον του στόματός σου θέλει υπακούει πας ο λαός μου· μόνον κατά τον θρόνον θέλω είσθαι ανώτερός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Και είπεν ο Φαραώ προς τον Ιωσήφ, Ιδού, σε κατέστησα εφ\' όλης της γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Και εκβαλών ο Φαραώ το δακτυλίδιον αυτού εκ της χειρός αυτού, έβαλεν αυτό εις την χείρα του Ιωσήφ και ενέδυσεν αυτόν ιμάτια βύσσινα, και περιέβαλε χρυσούν περιδέρραιον περί τον τράχηλον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Και ανεβίβασεν αυτόν επί την άμαξαν αυτού την δευτέραν· και εκήρυττον έμπροσθεν αυτού, Γονατίσατε· και κατέστησεν αυτόν εφ\' όλης της γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Και είπεν ο Φαραώ προς τον Ιωσήφ, Εγώ είμαι ο Φαραώ, και χωρίς σου ουδείς θέλει σηκώσει την χείρα αυτού ή τον πόδα αυτού καθ\' όλην την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Και ωνόμασεν ο Φαραώ τον Ιωσήφ αφνάθ-πανεάχ· και έδωκεν εις αυτόν διά γυναίκα Ασενέθ, την θυγατέρα του Ποτιφερά ιερέως της Ων. Και εξήλθεν ο Ιωσήφ εις την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Ήτο δε ο Ιωσήφ τριάκοντα ετών, ότε παρεστάθη έμπροσθεν του Φαραώ βασιλέως της Αιγύπτου· και εξήλθεν ο Ιωσήφ απ\' έμπροσθεν του Φαραώ, και διήλθεν όλην την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Και εκαρποφόρησεν η γη πλουσιοπαρόχως εις τα επτά έτη της αφθονίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'και συνήγαγε πάσας τας τροφάς των επτά ετών των γενομένων εν τη γη της Αιγύπτου· και εναπέθεσε τας τροφάς εν ταις πόλεσι· τας τροφάς των αγρών των πέριξ εκάστης πόλεως έθεσεν εν αυτή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Και συνήγαγεν ο Ιωσήφ σίτον ως την άμμον της θαλάσσης πολύν σφόδρα, ώστε έπαυσε να μετρή αυτόν· διότι ήτο αμέτρητος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Εγεννήθησαν δε δύο υιοί εις τον Ιωσήφ, πριν έλθωσι τα έτη της πείνης· τους οποίους εγέννησεν εις αυτόν Ασενέθ, η θυγάτηρ του Ποτιφερά ιερέως της Ων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Και εκάλεσεν ο Ιωσήφ το όνομα του πρωτοτόκου Μανασσή· διότι είπεν, Ο Θεός με έκαμε να λησμονήσω πάντας τους πόνους μου και πάντα τον οίκον του πατρός μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Το δε όνομα του δευτέρου εκάλεσεν Εφραΐμ· διότι είπεν, Ο Θεός με ηύξησεν εν τη γη της θλίψεώς μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Και παρήλθον τα επτά έτη της αφθονίας, της γενομένης εν τη γη της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Και ήρχισαν να έρχωνται τα επτά έτη της πείνης, καθώς είπεν ο Ιωσήφ· και έγεινεν η πείνα εις πάντας τους τόπους· καθ\' όλην όμως την γην της Αιγύπτου ήτο άρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Και ότε επείνασε πάσα η γη της Αιγύπτου, εβόησεν ο λαός προς τον Φαραώ διά άρτον. Και είπεν ο Φαραώ προς πάντας τους Αιγυπτίους, Υπάγετε προς τον Ιωσήφ· ό,τι σας είπη, κάμετε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Και ήτο η πείνα επί παν το πρόσωπον της γης. Ήνοιξε δε ο Ιωσήφ πάσας τας αποθήκας και επώλει σίτον εις τους Αιγυπτίους· και η πείνα επεβάρυνεν επί την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Και πάντες οι τόποι ήρχοντο εις την Αίγυπτον προς τον Ιωσήφ διά να αγοράζωσι σίτον· διότι η πείνα επεβάρυνεν επί πάσαν την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Και είδεν ο Ιακώβ ότι ευρίσκετο σίτος εν Αιγύπτω· και είπεν ο Ιακώβ προς τους υιούς αυτού, Τι βλέπετε ο εις τον άλλον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Και είπεν, Ιδού, ήκουσα ότι ευρίσκεται σίτος εν Αιγύπτω· κατάβητε εκεί και αγοράσατε δι\' ημάς εκείθεν, διά να ζήσωμεν και να μη αποθάνωμεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Και κατέβησαν οι δέκα αδελφοί του Ιωσήφ διά να αγοράσωσι σίτον εξ Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'τον Βενιαμίν όμως, τον αδελφόν του Ιωσήφ, δεν απέστειλεν ο Ιακώβ μετά των αδελφών αυτού· διότι είπε, Μήπως συμβή εις αυτόν συμφορά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Και ήλθον οι υιοί του Ισραήλ διά να αγοράσωσι σίτον μεταξύ των εκεί ερχομένων· διότι η πείνα ήτο εν τη γη Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Ο Ιωσήφ δε ήτο ο διοικητής του τόπου· αυτός επώλει εις πάντα τον λαόν του τόπου· ήλθον λοιπόν οι αδελφοί του Ιωσήφ και προσεκύνησαν αυτόν επί πρόσωπον έως εδάφους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Ιδών δε ο Ιωσήφ τους αδελφούς αυτού, εγνώρισεν αυτούς· προσεποιήθη όμως τον ξένον προς αυτούς και ελάλει προς αυτούς σκληρά· και είπε προς αυτούς, Πόθεν έρχεσθε; οι δε είπον, Εκ της γης Χαναάν, διά να αγοράσωμεν τροφάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Και ο μεν Ιωσήφ εγνώρισε τους αδελφούς αυτού· εκείνοι όμως δεν εγνώρισαν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Και ενεθυμήθη ο Ιωσήφ τα ενύπνια, τα οποία ενυπνιάσθη περί αυτών· και είπε προς αυτούς, Κατάσκοποι είσθε· ήλθετε να παρατηρήσητε τα γυμνά του τόπου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Οι δε είπον προς αυτόν, Ουχί, κύριέ μου· αλλ\' ήλθομεν οι δούλοί σου διά να αγοράσωμεν τροφάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'ημείς πάντες είμεθα υιοί ενός ανθρώπου· καλοί άνθρωποι είμεθα· οι δούλοί σου δεν είναι κατάσκοποι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Και είπε προς αυτούς, Ουχί, αλλά τα γυμνά του τόπου ήλθετε διά να παρατηρήσητε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Οι δε είπον, Οι δούλοί σου είμεθα δώδεκα αδελφοί, υιοί ενός ανθρώπου εν τη γη Χαναάν· και ιδού, ο νεώτερος ευρίσκεται σήμερον μετά του πατρός ημών, ο δε άλλος δεν υπάρχει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Και είπε προς αυτούς ο Ιωσήφ, τούτο είναι το οποίον σας είπα λέγων, Κατάσκοποι είσθε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Με τούτο θέλετε δοκιμασθή· Μα την ζωήν του Φαραώ δεν θέλετε εξέλθει εντεύθεν, εάν δεν έλθη εδώ ο αδελφός σας ο νεώτερος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'αποστείλατε ένα από σας και ας φέρη τον αδελφόν σας· σεις δε θέλετε μένει δέσμιοι, εωσού αποδειχθώσιν οι λόγοι σας, αν λέγητε την αλήθειαν· ει δε μη, μα την ζωήν του Φαραώ, κατάσκοποι βεβαίως είσθε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Και έθεσεν αυτούς υπό φύλαξιν τρεις ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Και την τρίτην ημέραν είπε προς αυτούς ο Ιωσήφ, τούτο κάμετε και θέλετε ζήσει διότι εγώ φοβούμαι τον Θεόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Εάν ήσθε καλοί, εις εκ των αδελφών σας ας μείνη δέσμιος εν τη φυλακή, όπου είσθε· σεις δε υπάγετε, λάβετε σίτον διά την πείναν των οικιών σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'φέρετε όμως προς εμέ τον αδελφόν σας τον νεώτερον· ούτω θέλουσιν αληθεύσει οι λόγοι σας και δεν θέλετε αποθάνει. Και έκαμον ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Και είπεν ο εις προς τον άλλον, Αληθώς ένοχοι είμεθα διά τον αδελφόν ημών, καθότι είδομεν την θλίψιν της ψυχής αυτού, ότε παρεκάλει ημάς και δεν εισηκούσαμεν αυτού· διά τούτο επήλθεν εφ\' ημάς η θλίψις αύτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Απεκρίθη δε ο Ρουβήν προς αυτούς λέγων, Δεν είπον προς εσάς λέγων, Μη αμαρτήσητε κατά του παιδίου, και δεν εισηκούσατε; διά τούτο, ιδού, και το αίμα αυτού εκζητείται.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Και αυτοί δεν ήξευρον ότι ενόει ο Ιωσήφ· διότι συνωμίλουν δι\' ερμηνέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Και συρθείς από πλησίον αυτών έκλαυσε· και πάλιν επέστρεψε προς αυτούς και ελάλει εις αυτούς· και έλαβεν εξ αυτών τον Συμεών και έδεσεν αυτόν ενώπιον αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Τότε προσέταξεν ο Ιωσήφ να γεμίσωσι τα αγγεία αυτών σίτον και να επιστρέψωσι το αργύριον εκάστου εν τω σακκίω αυτού και να δώσωσιν εις αυτούς ζωοτροφίαν διά την οδόν· και έγεινεν εις αυτούς ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Και φορτώσαντες τον σίτον αυτών επί τους όνους αυτών, ανεχώρησαν εκείθεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Ότε δε εις εξ αυτών έλυσε το σακκίον αυτού, διά να δώση εις τον όνον αυτού τροφήν εν τω καταλύματι, είδε το αργύριον αυτού, και ιδού, ήτο εν τω στόματι του σακκίου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Και είπε προς τους αδελφούς αυτού, το αργύριόν μου μοι εδόθη οπίσω και μάλιστα ιδού, είναι εν τω σακκίω μου· και εξεπλάγη η καρδία αυτών και συνεταράχθησαν, λέγοντες προς αλλήλους, Τι είναι τούτο, το οποίον μας έκαμεν ο Θεός;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Ήλθον δε προς Ιακώβ τον πατέρα αυτών εις την γην Χαναάν και απήγγειλαν προς αυτόν πάντα τα συμβάντα εις αυτούς, λέγοντες,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Ο άνθρωπος, ο κύριος του τόπου, ελάλησε προς ημάς σκληρά και εξέλαβεν ημάς ως κατασκόπους του τόπου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Και είπομεν εις αυτόν, Είμεθα καλοί άνθρωποι δεν είμεθα κατάσκοποι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'δώδεκα αδελφοί είμεθα, υιοί του πατρός ημών· ο εις δεν υπάρχει ο δε νεώτερος είναι την σήμερον μετά του πατρός ημών εν τη γη Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Είπε δε προς ημάς ο άνθρωπος, ο κύριος του τόπου, Με τούτο θέλω γνωρίσει ότι είσθε καλοί άνθρωποι· ένα εκ των αδελφών σας αφήσατε μετ\' εμού, και λαβόντες σίτον διά την πείναν των οικιών σας απέλθετε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'και φέρετε προς εμέ τον αδελφόν σας τον νεώτερον· τότε θέλω γνωρίσει ότι δεν είσθε κατάσκοποι, άλλ\' είσθε καλοί· και θέλω σας αποδώσει τον αδελφόν σας και θέλετε εμπορεύεσθαι εν τω τόπω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Και ότε εκένουν τα σακκία αυτών, ιδού, εκάστου το κομβόδεμα του αργυρίου ήτο εν τω σακκίω αυτού· και ιδόντες αυτοί και ο πατήρ αυτών τα κομβοδέματα του αργυρίου αυτών, εφοβήθησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Και είπε προς αυτούς Ιακώβ ο πατήρ αυτών, Σεις με ητεκνώσατε· ο Ιωσήφ δεν υπάρχει και ο Συμεών δεν υπάρχει, και τον Βενιαμίν θέλετε λάβει επ\' εμέ ήλθον πάντα ταύτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Είπε δε ο Ρουβήν προς τον πατέρα αυτού λέγων, τους δύο υιούς μου θανάτωσον, εάν δεν φέρω αυτόν προς σέ· παράδος αυτόν εις την χείρα μου και εγώ θέλω επαναφέρει αυτόν προς σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Ο δε είπε, δεν θέλει καταβή ο υιός μου μεθ\' υμών· διότι ο αδελφός αυτού απέθανε και αυτός μόνος έμεινε· και εάν συμβή εις αυτόν συμφορά εν τη οδώ, όπου υπάγετε, τότε θέλετε καταβιβάσει την πολιάν μου μετά λύπης εις τον τάφον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Η δε πείνα επεβάρυνεν επί την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Και αφού ετελείωσαν τρώγοντες τον σίτον, τον οποίον έφεραν εξ Αιγύπτου, είπε προς αυτούς ο πατήρ αυτών, Υπάγετε πάλιν, αγοράσατε εις ημάς ολίγας τροφάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Και είπε προς αυτόν ο Ιούδας λέγων, Εντόνως διεμαρτυρήθη προς ημάς ο άνθρωπος λέγων, Δεν θέλετε ιδεί το πρόσωπόν μου, εάν δεν ήναι μεθ\' υμών ο αδελφός υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Εάν λοιπόν αποστείλης τον αδελφόν ημών μεθ\' ημών, θέλομεν καταβή και θέλομεν σοι αγοράσει τροφάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'αλλ\' εάν δεν αποστείλης αυτόν, δεν θέλομεν καταβή· διότι ο άνθρωπος είπε προς ημάς, Δεν θέλετε ιδεί το πρόσωπόν μου, εάν ο αδελφός υμών δεν ήναι μεθ\' υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Είπε δε ο Ισραήλ, Διά τι με εκακοποιήσατε, φανερόνοντες προς τον άνθρωπον ότι έχετε άλλον αδελφόν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Οι δε είπον, Ο άνθρωπος ηρώτησεν ημάς ακριβώς περί ημών και περί της συγγενείας ημών λέγων, Ο πατήρ σας έτι ζη; έχετε άλλον αδελφόν; Και απεκρίθημεν προς αυτόν κατά την ερώτησιν ταύτην· ηδυνάμεθα να εξεύρωμεν ότι ήθελεν ειπεί, Φέρετε τον αδελφόν σας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Και είπεν ο Ιούδας προς Ισραήλ τον πατέρα αυτού, Απόστειλον το παιδάριον μετ\' εμού, και σηκωθέντες ας υπάγωμεν, διά να ζήσωμεν και να μη αποθάνωμεν και ημείς και συ και αι οικογένειαι ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'εγώ εγγυώμαι περί αυτού· εκ της χειρός μου ζήτησον αυτόν· εάν δεν φέρω αυτόν προς σε και στήσω αυτόν έμπροσθέν σου, τότε ας ήμαι διαπαντός υπεύθυνος προς σέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'επειδή, εάν δεν εβραδύνομεν, βέβαια έως τώρα δευτέραν ταύτην φοράν ηθέλομεν επιστρέψει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Και είπε προς αυτούς Ισραήλ ο πατήρ αυτών, Εάν ούτω πρέπη να γείνη, κάμετε λοιπόν τούτο· λάβετε εις τα αγγείά σας εκ των καλητέρων καρπών της γης και φέρετε δώρα προς τον άνθρωπον, ολίγον βάλσαμον και ολίγον μέλι, αρώματα και μύρον, πιστάκια και αμύγδαλα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'και λάβετε διπλάσιον αργύριον εις τας χείρας σας· και το αργύριον το επιστραφέν εν τω στόματι των σακκίων σας φέρετε πάλιν εις τας χείρας σας· ίσως έγεινε κατά λάθος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'και τον αδελφόν σας λάβετε και σηκωθέντες επιστρέψατε προς τον άνθρωπον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'και ο Θεός ο Παντοδύναμος να σας δώση χάριν έμπροσθεν του ανθρώπου, διά να αποστείλη με σας τον άλλον σας αδελφόν και τον Βενιαμίν· και εγώ, αν ήναι να ατεκνωθώ, ας ατεκνωθώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Λαβόντες δε οι άνθρωποι τα δώρα ταύτα, έλαβον και αργύριον διπλάσιον εις τας χείρας αυτών και τον Βενιαμίν· και σηκωθέντες κατέβησαν εις Αίγυπτον και παρεστάθησαν έμπροσθεν του Ιωσήφ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Και ότε είδεν ο Ιωσήφ τον Βενιαμίν μετ\' αυτών, είπε προς τον επιστάτην της οικίας αυτού, Φέρε τους ανθρώπους εις την οικίαν και σφάξον σφακτόν και ετοίμασον, διότι μετ\' εμού θέλουσι φάγει οι άνθρωποι το μεσημέριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Και έπραξεν ο άνθρωπος καθώς ελάλησεν ο Ιωσήφ· και ο άνθρωπος εισήγαγε τους ανθρώπους εις την οικίαν του Ιωσήφ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Και εφοβήθησαν οι άνθρωποι, διότι εισήχθησαν εις την οικίαν του Ιωσήφ· και είπον, διά το αργύριον το επιστραφέν εις τα σακκία ημών την πρώτην φοράν ημείς εισαγόμεθα, διά να εύρη αφορμήν εναντίον ημών και να επιπέση εφ\' ημάς και να λάβη ημάς δούλους και τους όνους ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Και προσελθόντες προς τον άνθρωπον τον επιστάτην της οικίας του Ιωσήφ, ελάλησαν προς αυτόν εν τη πύλη της οικίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'και είπον, Δεόμεθα, κύριε· κατέβημεν την πρώτην φοράν διά να αγοράσωμεν τροφάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'και ότε ήλθομεν εις το κατάλυμα, ηνοίξαμεν τα σακκία ημών και ιδού, εκάστου το αργύριον ήτο εν τω στόματι του σακκίου αυτού, το αργύριον ημών σωστόν· όθεν εφέραμεν αυτό οπίσω εις τας χείρας ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'εφέραμεν και άλλο αργύριον εις τας χείρας ημών, διά να αγοράσωμεν τροφάς· δεν εξεύρομεν τις έβαλε το αργύριον ημών εις τα σακκία ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Ο δε είπεν, Ειρήνη εις εσάς· μη φοβείσθε· ο Θεός σας και ο Θεός του πατρός σας, έδωκεν εις εσάς θησαυρόν εις τα σακκία σας· το αργύριόν σας ήλθεν εις εμέ. Και εξήγαγε προς αυτούς τον Συμεών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Και ο άνθρωπος εισήγαγε τους ανθρώπους εις την οικίαν του Ιωσήφ και έδωκεν ύδωρ και ένιψαν τους πόδας αυτών· και έδωκε τροφήν εις τους όνους αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Οι δε ητοίμασαν τα δώρα, εωσού έλθη ο Ιωσήφ το μεσημέριον· διότι ήκουσαν ότι εκεί μέλλουσι να φάγωσιν άρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Και ότε ήλθεν ο Ιωσήφ εις την οικίαν, προσέφεραν εις αυτόν τα δώρα τα εις τας χείρας αυτών εν τη οικία και προσεκύνησαν αυτόν έως εδάφους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Και ηρώτησεν αυτούς περί της υγιείας αυτών· και είπεν, Υγιαίνει ο πατήρ σας, ο γέρων περί του οποίου μοι είπετε; έτι ζη;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Οι δε είπον, Υγιαίνει ο δούλός σου ο πατήρ ημών· έτι ζη. Και κύψαντες προσεκύνησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Υψώσας δε τους οφθαλμούς αυτού είδε τον Βενιαμίν τον αδελφόν αυτού τον ομομήτριον και είπεν, Ούτος είναι ο αδελφός σας ο νεώτερος, περί του οποίου μοι είπετε; Και είπεν, Ο Θεός να σε ελεήση, τέκνον μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Και έσπευσε να αποσυρθή ο Ιωσήφ· διότι συνεταράττοντο τα σπλάγχνα αυτού διά τον αδελφόν αυτού· και εζήτει τόπον να κλαύση· εισελθών δε εις το ταμείον, έκλαυσεν εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Έπειτα νίψας το πρόσωπον αυτού εξήλθε, και συγκρατών εαυτόν είπε, Βάλετε άρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Και έβαλον χωριστά δι\' αυτόν και χωριστά δι\' εκείνους και διά τους Αιγυπτίους, τους συντρώγοντας μετ\' αυτού, χωριστά· διότι οι Αιγύπτιοι δεν ηδύναντο να συμφάγωσιν άρτον μετά των Εβραίων, επειδή τούτο είναι βδέλυγμα εις τους Αιγυπτίους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Εκάθισαν λοιπόν έμπροσθεν αυτού, ο πρωτότοκος κατά την πρωτοτοκίαν αυτού και ο νεώτερος κατά την νεότητα αυτού· και εθαύμαζον οι άνθρωποι προς αλλήλους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Λαβών δε απ\' έμπροσθεν αυτού μερίδια έστειλε προς αυτούς· το μερίδιον όμως του Βενιαμίν ήτο πενταπλασίως μεγαλήτερον παρά εκάστου αυτών. Και έπιον και ευφράνθησαν μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Προσέταξε δε τον επιστάτην της οικίας αυτού λέγων, Γέμισον τα σακκία των ανθρώπων τροφάς, όσας δύνανται να φέρωσι, και βάλε το αργύριον εκάστου εν τω στόματι του σακκίου αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'και βάλε το ποτήριόν μου, το ποτήριον το αργυρούν, εν τω στόματι του σακκίου του νεωτέρου και το αργύριον του σίτου αυτού. Και έκαμε κατά τον λόγον τον οποίον είπεν ο Ιωσήφ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Το πρωΐ καθώς έφεγξεν, απεστάλησαν οι άνθρωποι, αυτοί και οι όνοι αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Αφού δε εξήλθον εκ της πόλεως, πριν απομακρυνθώσι πολύ, είπεν ο Ιωσήφ προς τον επιστάτην της οικίας αυτού, Σηκωθείς, δράμε κατόπιν των ανθρώπων· και προφθάσας ειπέ προς αυτούς, διά τι ανταπεδώκατε κακόν αντί καλού;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'δεν είναι τούτο το ποτήριον, εις το οποίον πίνει ο κύριός μου, και διά του οποίου αληθώς μαντεύει; κακώς εκάμετε πράξαντες τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Και καθώς επρόφθασεν αυτούς, είπε προς αυτούς τους λόγους τούτους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Οι δε είπον προς αυτόν, Διά τι ο κύριος ημών λαλεί κατά τους λόγους τούτους; μη γένοιτο οι δούλοί σου να πράξωσι τοιούτον πράγμα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'ιδού, το αργύριον, το οποίον ευρήκαμεν εν τω στόματι των σακκίων ημών, επεστρέψαμεν προς σε εκ της γης Χαναάν, και πως ηθέλομεν κλέψει εκ της οικίας του κυρίου σου αργύριον ή χρυσίον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'εις όντινα εκ των δούλων σου ευρεθή, ας αποθάνη, και ημείς έτι θέλομεν γείνει δούλοι του κυρίου ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Ο δε είπε, Και τώρα ας γείνη καθώς λέγετε· εις όντινα ευρεθή, θέλει γείνει δούλός μου, σεις δε θέλετε είσθαι αθώοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Και σπεύσαντες, κατεβίβασαν έκαστος το σακκίον αυτού εις την γην και ήνοιξεν έκαστος το σακκίον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Και ηρεύνησεν, αρχίσας από του πρεσβυτέρου και τελειώσας εις τον νεώτερον· και ευρέθη το ποτήριον εν τω σακκίω του Βενιαμίν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Τότε έσχισαν τα ιμάτια αυτών και φορτώσαντες έκαστος τον όνον αυτού, επέστρεψαν εις την πόλιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Εισήλθε δε ο Ιούδας και οι αδελφοί αυτού εις την οικίαν του Ιωσήφ, έτι αυτού όντος εκεί· και έπεσαν έμπροσθεν αυτού επί την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Και είπε προς αυτούς ο Ιωσήφ, Τι είναι το πράγμα τούτο, το οποίον επράξατε; δεν εξεύρετε ότι άνθρωπος οποίος εγώ αληθώς μαντεύει;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Και είπεν ο Ιούδας, Τι να είπωμεν προς τον κύριόν μου; τι να λαλήσωμεν; ή πως να δικαιωθώμεν; ο Θεός εύρηκε την αδικίαν των δούλων σου· ιδού, είμεθα δούλοι του κυρίου μου και εμείς και εκείνος εις τον οποίον ευρέθη το ποτήριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Ο δε είπε, Μη γένοιτο εις εμέ να πράξω τούτο· ο άνθρωπος εις τον οποίον ευρέθη το ποτήριον, ούτος θέλει είσθαι εις εμέ δούλος· σεις δε ανάβητε εν ειρήνη προς τον πατέρα σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Τότε επλησίασεν εις αυτόν ο Ιούδας και είπε, Δέομαι, κύριέ μου· ας λαλήση, παρακαλώ, ο δούλός σου λόγον εις τα ώτα του κυρίου μου και ας μη εξαφθή ο θυμός σου κατά του δούλου σου· διότι συ είσαι ως Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Ο κύριός μου ηρώτησε τους δούλους αυτού λέγων, Έχετε πατέρα, ή αδελφόν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Και είπομεν προς τον κύριόν μου, Έχομεν πατέρα γέροντα και παιδίον του γήρατος αυτού μικρόν, ο δε αδελφός αυτού απέθανε· και αυτός μόνος έμεινεν εκ της μητρός αυτού και ο πατήρ αυτού αγαπά αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Και είπας προς τους δούλους σου, Φέρετε αυτόν προς εμέ διά να ίδω αυτόν ιδίοις οφθαλμοίς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Και είπομεν προς τον κύριόν μου, το παιδίον δεν δύναται να αφήση τον πατέρα αυτού διότι εάν αφήση τον πατέρα αυτού, ούτος θέλει αποθάνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Συ δε είπας προς τους δούλους σου, Εάν δεν καταβή ο αδελφός υμών ο νεώτερος μεθ\' υμών, δεν θέλετε ιδεί πλέον το πρόσωπόν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Και ότε ανέβημεν προς τον δούλον σου τον πατέρα μου, απηγγείλαμεν προς αυτόν τους λόγους του κυρίου μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Ο δε πατήρ ημών είπεν, Υπάγετε πάλιν, αγοράσατε εις ημάς ολίγας τροφάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Και είπομεν, Δεν δυνάμεθα να καταβώμεν· εάν ο αδελφός ημών ο νεώτερος ήναι μεθ\' ημών, τότε θέλομεν καταβή· διότι δεν δυνάμεθα να ίδωμεν το πρόσωπον του ανθρώπου, εάν ο αδελφός ημών ο νεώτερος δεν ήναι μεθ\' ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Και ο δούλός σου ο πατήρ μου είπε προς ημάς, Σεις εξεύρετε ότι δύο υιούς εγέννησεν εις εμέ η γυνή μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'και ο εις εξήλθεν από πλησίον μου και είπα, Βεβαίως κατεσπαράχθη υπό θηρίου· και δεν είδον αυτόν έως του νύν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'εάν δε λάβητε και τούτον απ\' έμπροσθέν μου και συμβή εις αυτόν συμφορά, θέλετε καταβιβάσει την πολιάν μου μετά λύπης εις τον τάφον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Τώρα λοιπόν όταν υπάγω προς τον δούλον σου τον πατέρα μου, και το παιδίον δεν ήναι μεθ\' ημών επειδή η ψυχή αυτού κρέμαται εκ της ψυχής εκείνου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'καθώς ίδη ότι το παιδίον δεν είναι, θέλει αποθάνει και οι δούλοί σου θέλουσι καταβιβάσει την πολιάν του δούλου σου του πατρός ημών μετά λύπης εις τον τάφον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Διότι ο δούλός σου εγγυήθη περί του παιδίου προς τον πατέρα μου λέγων, Εάν δεν φέρω αυτόν προς σε, τότε θέλω είσθαι υπεύθυνος προς τον πατέρα μου διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Τώρα λοιπόν, δέομαί σου, ας μείνη ο δούλός σου αντί του παιδίου δούλος εις τον κύριόν μου, το δε παιδίον ας αναβή μετά των αδελφών αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'διότι πως να αναβώ προς τον πατέρα μου, εάν το παιδίον δεν ήναι μετ\' εμού; ουχί, διά να μη ίδω το κακόν, το οποίον θέλει ευρεί τον πατέρα μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Τότε ο Ιωσήφ δεν ηδυνήθη να συγκρατήση εαυτόν ενώπιον πάντων των παρισταμένων έμπροσθεν αυτού· και εφώνησεν, Εκβάλετε πάντας απ\' εμού· και δεν έμεινεν ουδείς μετ\' αυτού, ενώ ο Ιωσήφ ανεγνωρίζετο εις τους αδελφούς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'και αφήκε φωνήν μετά κλαυθμού· και ήκουσαν οι Αιγύπτιοι· ήκουσε δε και ο οίκος του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Και είπεν ο Ιωσήφ προς τους αδελφούς αυτού, Εγώ είμαι ο Ιωσήφ· ο πατήρ μου έτι ζη; Και δεν ηδύναντο οι αδελφοί αυτού να αποκριθώσι προς αυτόν· διότι εταράχθησαν εκ της παρουσίας αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Και είπεν ο Ιωσήφ προς τους αδελφούς αυτού, Πλησιάσατε προς εμέ, παρακαλώ. Και επλησίασαν. Και είπεν, Εγώ είμαι Ιωσήφ ο αδελφός σας, τον οποίον επωλήσατε εις την Αίγυπτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Τώρα λοιπόν μη λυπείσθε μηδ\' ας φανή εις εσάς σκληρόν ότι με επωλήσατε εδώ· επειδή εις διατήρησιν ζωής με απέστειλεν ο Θεός έμπροσθέν σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Διότι τούτο είναι το δεύτερον έτος της πείνης επί της γής· και μένουσιν ακόμη πέντε έτη, εις τα οποία δεν θέλει είσθαι ούτε αροτρίασις ούτε θερισμός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Και ο Θεός με απέστειλεν έμπροσθέν σας διά να διατηρήσω εις εσάς διαδοχήν επί της γης και να διαφυλάξω την ζωήν σας μετά μεγάλης λυτρώσεως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Τώρα λοιπόν δεν με απεστείλατε εδώ σεις, αλλ\' ο Θεός· και με έκαμε πατέρα εις τον Φαραώ και κύριον παντός του οίκου αυτού και άρχοντα πάσης της γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Σπεύσαντες ανάβητε προς τον πατέρα μου και είπατε προς αυτόν, Ούτω λέγει ο υιός σου Ιωσήφ· Ο Θεός με έκαμε κύριον πάσης Αιγύπτου· κατάβηθι προς εμέ, μη σταθής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'και θέλεις κατοικήσει εν γη Γεσέν και θέλεις είσθαι πλησίον μου, συ και οι υιοί σου και οι υιοί των υιών σου και τα ποίμνιά σου και αι αγέλαι σου, και πάντα όσα έχεις·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'και θέλω σε εκτρέφει εκεί διότι μένουσιν ακόμη πέντε έτη πείνης, διά να μη έλθης εις στέρησιν, συ και ο οίκος σου και πάντα όσα έχεις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Και ιδού, οι οφθαλμοί σας βλέπουσι και οι οφθαλμοί του αδελφού μου Βενιαμίν, ότι το στόμα μου λαλεί προς εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'απαγγείλατε λοιπόν προς τον πατέρα μου πάσαν την δόξαν μου εν Αιγύπτω και πάντα όσα είδετε, και σπεύσαντες καταβιβάσατε τον πατέρα μου εδώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Και πεσών επί τον τράχηλον Βενιαμίν του αδελφού αυτού, έκλαυσε· και ο Βενιαμίν έκλαυσεν επί τον τράχηλον εκείνου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Και καταφιλήσας πάντας τους αδελφούς αυτού, έκλαυσεν επ\' αυτούς· και μετά ταύτα ώμίλησαν οι αδελφοί αυτού μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Και η φήμη ηκούσθη εις τον οίκον του Φαραώ λέγουσα, Οι αδελφοί του Ιωσήφ ήλθον· εχάρη δε ο Φαραώ και οι δούλοι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Και είπεν ο Φαραώ προς τον Ιωσήφ, Ειπέ προς τους αδελφούς σου, τούτο κάμετε· φορτώσατε τα ζώα σας και υπάγετε, ανάβητε εις γην Χαναάν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'και παραλαβόντες τον πατέρα σας, και τας οικογενείας σας, έλθετε προς εμέ· και θέλω σας δώσει τα αγαθά της γης Αιγύπτου και θέλετε φάγει το πάχος της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Και συ πρόσταξον· Τούτο κάμετε, λάβετε εις εαυτούς αμάξας εκ της γης Αιγύπτου, διά τα παιδία σας και διά τας γυναίκάς σας· και σηκώσαντες τον πατέρα σας έλθετε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'και μη λυπηθήτε την αποσκευήν σας· διότι τα αγαθά πάσης της γης Αιγύπτου θέλουσιν είσθαι ιδικά σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Και έκαμον ούτως οι υιοί του Ισραήλ· και ο Ιωσήφ έδωκεν εις αυτούς αμάξας κατά την προσταγήν του Φαραώ· έδωκεν εις αυτούς και ζωοτροφίαν διά την οδόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Εις πάντας αυτούς έδωκεν εις έκαστον αλλαγάς ενδυμάτων· εις δε τον Βενιαμίν έδωκε τριακόσια αργύρια και πέντε αλλαγάς ενδυμάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Προς δε τον πατέρα αυτού έστειλε ταύτα· δέκα όνους φορτωμένους εκ των αγαθών της Αιγύπτου και δέκα θηλυκάς όνους φορτωμένας σίτον και άρτους και ζωοτροφίας εις τον πατέρα αυτού διά την οδόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Και εξαπέστειλε τους αδελφούς αυτού και ανεχώρησαν· και είπε προς αυτούς, Μη συγχύζεσθε καθ\' οδόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Και ανέβησαν εξ Αιγύπτου και ήλθον εις γην Χαναάν προς Ιακώβ τον πατέρα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Και απήγγειλαν προς αυτόν λέγοντες, Έτι ζη ο Ιωσήφ και είναι άρχων εφ\' όλης της γης Αιγύπτου· και ελειποθύμησεν η καρδία αυτού· διότι δεν επίστευεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Είπον δε προς αυτόν πάντας τους λόγους του Ιωσήφ, τους οποίους είχεν ειπεί προς αυτούς· και αφού είδε τας αμάξας τας οποίας έστειλεν ο Ιωσήφ διά να σηκώσωσιν αυτόν, ανεζωπυρήθη το πνεύμα του Ιακώβ του πατρός αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Και είπεν ο Ισραήλ, Αρκεί· Ιωσήφ ο υιός μου έτι ζή· θέλω υπάγει και θέλω ιδεί αυτόν, πριν αποθάνω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Αναχωρήσας δε ο Ισραήλ μετά πάντων των υπαρχόντων αυτού, ήλθεν εις Βηρ-σαβεέ και προσέφερε θυσίας εις τον Θεόν του πατρός αυτού Ισαάκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Και είπεν ο Θεός προς τον Ισραήλ δι\' οράματος της νυκτός λέγων, Ιακώβ, Ιακώβ. Ο δε είπεν, Ιδού, εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Και είπεν, Εγώ είμαι ο Θεός, ο Θεός του πατρός σου· μη φοβηθής να καταβής εις Αίγυπτον· διότι έθνος μέγα θέλω σε καταστήσει εκεί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'εγώ θέλω καταβή μετά σου εις Αίγυπτον και εγώ βεβαίως θέλω σε αναβιβάσει πάλιν· και ο Ιωσήφ θέλει βάλει τας χείρας αυτού επί τους οφθαλμούς σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Και εσηκώθη ο Ιακώβ από Βηρ-σαβεέ και έβαλον οι υιοί του Ισραήλ Ιακώβ τον πατέρα αυτών και τα παιδία αυτών και τας γυναίκας αυτών επί τας αμάξας τας οποίας έστειλεν ο Φαραώ διά να σηκώσωσιν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Και λαβόντες τα κτήνη αυτών και τα υπάρχοντα αυτών, τα οποία απέκτησαν εν τη γη Χαναάν, ήλθον εις Αίγυπτον, ο Ιακώβ και παν το σπέρμα αυτού μετ\' αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'τους υιούς αυτού και τους υιούς των υιών αυτού μεθ\' εαυτού, τας θυγατέρας αυτού και τας θυγατέρας των υιών αυτού και παν το σπέρμα αυτού έφερε μεθ\' εαυτού εις Αίγυπτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Ταύτα δε είναι τα ονόματα των υιών Ισραήλ, των εισελθόντων εις Αίγυπτον, Ιακώβ και οι υιοί αυτού· Ρουβήν ο πρωτότοκος του Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'και οι υιοί του Ρουβήν, Ανώχ και Φαλλού και Εσρών και Χαρμί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Και οι υιοί του Συμεών, Ιεμουήλ και Ιαμείν και Αώδ και Ιαχείν και Σωάρ και Σαούλ, υιός Χανανίτιδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Και οι υιοί του Λευΐ, Γηρσών, Καάθ και Μεραρί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Και οι υιοί του Ιούδα, Ηρ και Αυνάν και Σηλά και Φαρές και Ζαρά· ο Ηρ όμως και ο Αυνάν απέθανον εν τη γη Χαναάν. Και οι υιοί του Φαρές ήσαν Εσρών και Αμούλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Και οι υιοί του Ισσάχαρ, Θωλά και Φουά και Ιώβ και Σιμβρών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Και οι υιοί του Ζαβουλών, Σερέδ και Αιλών και Ιαλεήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Ούτοι είναι οι υιοί της Λείας, τους οποίους εγέννησεν εις τον Ιακώβ εν Παδάν-αράμ, και Δείναν την θυγατέρα αυτού· πάσαι αι ψυχαί, οι υιοί αυτού και αι θυγατέρες αυτού, ήσαν τριάκοντα τρεις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Και οι υιοί του Γαδ, Σιφών και Αγγί, Σουνί και Εσβών, Ηρί και Αροδί και Αριηλί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Και οι υιοί του Ασήρ, Ιεμνά και Ιεσσουά και Ιεσουεί και Βεριά και Σερά η αδελφή αυτών. Και οι υιοί του Βεριά, Έβερ και Μαλχιήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Ούτοι είναι οι υιοί της Ζελφάς, την οποίαν έδωκεν ο Λάβαν εις την Λείαν την θυγατέρα αυτού· και τούτους εγέννησεν εις τον Ιακώβ, δεκαέξ ψυχάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Οι δε υιοί της Ραχήλ γυναικός του Ιακώβ, Ιωσήφ και Βενιαμίν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Εγεννήθησαν δε εις τον Ιωσήφ εν τη γη της Αιγύπτου Μανασσής και Εφραΐμ, τους οποίους εγέννησεν εις αυτόν Ασενέθ, η θυγάτηρ του Ποτιφερά ιερέως της Ων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Και οι υιοί του Βενιαμίν ήσαν Βελά και Βεχέρ και Ασβήλ, Γηρά και Νααμάν, Ηχί και Ρως, Μουπίμ και Ουπίμ και Αρέδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Ούτοι είναι οι υιοί της Ραχήλ, οι γεννηθέντες εις τον Ιακώβ· πάσαι αι ψυχαί δεκατέσσαρες.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Και οι υιοί του Δαν, Ουσίμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Και οι υιοί του Νεφθαλί, Ιασιήλ και Γουνί και Ιεσέρ και Σιλλήμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ούτοι είναι οι υιοί της Βαλλάς, την οποίαν έδωκεν ο Λάβαν εις Ραχήλ την θυγατέρα αυτού· και τούτους εγέννησεν εις τον Ιακώβ· πάσαι αι ψυχαί επτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Πάσαι αι ψυχαί αι εισελθούσαι μετά του Ιακώβ εις Αίγυπτον, αίτινες εξήλθον εκ των μηρών αυτού, χωρίς των γυναικών των υιών του Ιακώβ, πάσαι αι ψυχαί ήσαν εξήκοντα εξ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Και οι υιοί του Ιωσήφ, οι γεννηθέντες εις αυτόν εν Αιγύπτω, ήσαν ψυχαί δύο· πάσαι αι ψυχαί του οίκου του Ιακώβ, αι εισελθούσαι εις Αίγυπτον, ήσαν εβδομήκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Απέστειλε δε ο Ιακώβ τον Ιούδαν έμπροσθεν αυτού προς τον Ιωσήφ, διά να καταβή προ αυτού εις Γεσέν· και ήλθον εις την γην Γεσέν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Ζεύξας δε ο Ιωσήφ την άμαξαν αυτού, ανέβη εις συνάντησιν Ισραήλ του πατρός αυτού εις Γεσέν· και ιδών αυτόν, έπεσεν επί τον τράχηλον αυτού και έκλαυσε πολλήν ώραν επί τον τράχηλον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Και είπεν ο Ισραήλ προς τον Ιωσήφ, Ας αποθάνω τώρα, αφού είδον το πρόσωπόν σου, διότι συ έτι ζης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Είπε δε ο Ιωσήφ προς τους αδελφούς αυτού και προς τον οίκον του πατρός αυτού, Εγώ θέλω αναβή και θέλω απαγγείλει προς τον Φαραώ και ειπεί προς αυτόν, Οι αδελφοί μου και ο οίκος του πατρός μου, οίτινες ήσαν εν τη γη Χαναάν, ήλθον προς εμέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'οι δε άνθρωποι είναι ποιμένες, διότι άνδρες κτηνοτρόφοι είναι και έφεραν τα ποίμνια αυτών και τας αγέλας αυτών και πάντα όσα έχουσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Εάν λοιπόν σας καλέση ο Φαραώ και είπη, Ποίον το επιτήδευμά σας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'θέλετε ειπεί, Άνδρες κτηνοτρόφοι είμεθα οι δούλοί σου εκ νεότητος ημών έως του νυν και ημείς και οι πατέρες ημών· διά να κατοικήσητε εν τη γη Γεσέν· διότι είναι βδέλυγμα εις τους Αιγυπτίους πας ποιμήν προβάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Ελθών δε ο Ιωσήφ, απήγγειλε προς τον Φαραώ λέγων, Ο πατήρ μου και οι αδελφοί μου, και τα ποίμνια αυτών και αι αγέλαι αυτών και πάντα όσα έχουσιν, ήλθον εκ της γης Χαναάν· και ιδού, είναι εν τη γη Γεσέν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Και παραλαβών εκ των αδελφών αυτού πέντε άνδρας, παρέστησεν αυτούς ενώπιον του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Και είπεν ο Φαραώ προς τους αδελφούς αυτού, Τι είναι το επιτήδευμά σας; οι δε είπον προς τον Φαραώ, Ποιμένες προβάτων είναι οι δούλοί σου και ημείς και οι πατέρες ημών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Είπον έτι προς τον Φαραώ, Ήλθομεν διά να παροικήσωμεν εν τη γή· διότι δεν υπάρχει βοσκή διά τα ποίμνια των δούλων σου, επειδή επεβάρυνεν η πείνα εν τη γη Χαναάν· τώρα λοιπόν ας κατοικήσωσι, παρακαλούμεν, οι δούλοί σου εν τη γη Γεσέν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Και είπεν ο Φαραώ προς τον Ιωσήφ λέγων, Ο πατήρ σου και οι αδελφοί σου ήλθον προς σέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'η γη της Αιγύπτου είναι έμπροσθέν σου· εις το καλήτερον της γης κατοίκισον τον πατέρα σου και τους αδελφούς σου· ας κατοικήσωσιν εν τη γη Γεσέν· και εάν γνωρίζης ότι ευρίσκονται μεταξύ αυτών άνδρες άξιοι, κατάστησον αυτούς επιστάτας επί των ποιμνίων μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Εισήγαγε δε ο Ιωσήφ Ιακώβ τον πατέρα αυτού και παρέστησεν αυτόν ενώπιον του Φαραώ· και ευλόγησεν ο Ιακώβ τον Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Και είπεν ο Φαραώ προς τον Ιακώβ, Ως πόσαι είναι αι ημέραι των ετών της ζωής σου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Και ο Ιακώβ είπε προς τον Φαραώ, Αι ημέραι των ετών της παροικίας μου είναι εκατόν τριάκοντα έτη· ολίγαι και κακαί υπήρξαν αι ημέραι των ετών της ζωής μου και δεν έφθασαν εις τας ημέρας των ετών της ζωής των πατέρων μου εν ταις ημέραις της παροικίας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Και ευλόγησεν ο Ιακώβ τον Φαραώ και εξήλθεν απ\' έμπροσθεν του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Και κατώκισεν ο Ιωσήφ τον πατέρα αυτού και τους αδελφούς αυτού, και έδωκεν εις αυτούς ιδιοκτησίαν εν τη γη της Αιγύπτου, εις το καλήτερον της γης, εν τη γη Ραμεσσή, καθώς προσέταξεν ο Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Και έτρεφεν ο Ιωσήφ τον πατέρα αυτού και τους αδελφούς αυτού και πάντα τον οίκον του πατρός αυτού με άρτον, κατά τας οικογενείας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Και άρτος δεν ήτο καθ\' όλην την γήν· διότι η πείνα ήτο βαρεία σφόδρα, ώστε η γη της Αιγύπτου και η γη της Χαναάν απέκαμον υπό της πείνης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Και συνήγαγεν ο Ιωσήφ άπαν το αργύριον, το ευρισκόμενον εν τη γη της Αιγύπτου και εν τη γη Χαναάν, διά τον σίτον τον οποίον ηγόραζον· και έφερεν ο Ιωσήφ το αργύριον εις τον οίκον του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Και αφού εξέλιπε το αργύριον εκ της γης Αιγύπτου και εκ της γης Χαναάν, ήλθον πάντες οι Αιγύπτιοι προς τον Ιωσήφ, λέγοντες, Δος άρτον εις ημάς· επειδή διά τι να αποθάνωμεν έμπροσθέν σου; διότι εξέλιπε το αργύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Είπε δε ο Ιωσήφ, Φέρετε τα κτήνη σας και θέλω σας δώσει άρτον αντί των κτηνών σας, εάν εξέλιπε το αργύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Και έφεραν τα κτήνη αυτών προς τον Ιωσήφ και έδωκεν εις αυτούς ο Ιωσήφ άρτον αντί των ίππων και αντί των προβάτων και αντί των βοών και αντί των όνων· και έθρεψεν αυτούς με άρτον εν τω ενιαυτώ εκείνω αντί πάντων των κτηνών αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Αφού δε ετελείωσεν ο ενιαυτός εκείνος, ήλθον προς αυτόν το δεύτερον έτος και είπον προς αυτόν, δεν θέλομεν κρύψει από του κυρίου ημών ότι εξέλιπε το αργύριον· και τα κτήνη έγειναν του κυρίου ημών· δεν έμεινεν άλλο έμπροσθεν του κυρίου ημών, ειμή τα σώματα ημών και η γη ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'διά τι να απολεσθώμεν ενώπιόν σου και ημείς και η γη ημών; αγόρασον ημάς και την γην ημών διά άρτον· και θέλομεν είσθαι ημείς και η γη ημών δούλοι εις τον Φαραώ· και δος εις ημάς σπόρον, διά να ζήσωμεν και να μη αποθάνωμεν και η γη να μη ερημωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Και ηγόρασεν ο Ιωσήφ πάσαν την γην Αιγύπτου διά τον Φαραώ· διότι οι Αιγύπτιοι επώλησαν έκαστος τον αγρόν αυτού, επειδή η πείνα υπερεβάρυνεν επ\' αυτούς· ούτως η γη έγεινε του Φαραώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'τον δε λαόν μετετόπισεν αυτόν εις πόλεις, απ\' άκρου των ορίων της Αιγύπτου έως άκρου αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'μόνον την γην των ιερέων δεν ηγόρασε· διότι οι ιερείς είχον μερίδιον προσδιωρισμένον υπό του Φαραώ· και έτρωγον το μερίδιον αυτών, το οποίον έδωκεν εις αυτούς ο Φαραώ· διά τούτο δεν επώλησαν την γην αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Τότε είπεν ο Ιωσήφ προς τον λαόν, Ιδού, ηγόρασα εσάς και την γην σας σήμερον εις τον Φαραώ· ιδού, λάβετε σπόρον και σπείρατε την γήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'και εν τω καιρώ των γεννημάτων, θέλετε δώσει το πέμπτον εις τον Φαραώ· τα δε τέσσαρα μέρη θέλουσιν είσθαι εις εσάς διά σπόρον των αγρών και διά τροφήν σας και διά τους όντας εν τοις οίκοις υμών και διά τροφήν των παιδίων υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Οι δε είπον, συ έσωσας την ζωήν ημών· ας εύρωμεν χάριν έμπροσθεν του κυρίου ημών και θέλομεν είσθαι δούλοι του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Και έθεσεν ο Ιωσήφ τούτο νόμον εν τη γη της Αιγύπτου μέχρι της σήμερον, να δίδεται το πέμπτον εις τον Φαραώ· εκτός της γης των ιερέων μόνον, ήτις δεν έγεινε του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Κατώκησε δε ο Ισραήλ εν τη γη της Αιγύπτου, εν τη γη Γεσέν· και απέκτησαν εν αυτή κτήματα, και ηυξήνθησαν και επληθύνθησαν σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Επέζησε δε ο Ιακώβ εν τη γη της Αιγύπτου δεκαεπτά έτη· και έγειναν αι ημέραι των ετών της ζωής του Ιακώβ εκατόν τεσσαράκοντα επτά έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Και επλησίασαν αι ημέραι του Ισραήλ διά να αποθάνη· και καλέσας τον υιόν αυτού τον Ιωσήφ, είπε προς αυτόν, Εάν εύρηκα τώρα χάριν έμπροσθέν σου, βάλε, παρακαλώ, την χείρα σου υπό τον μηρόν μου, και κάμε εις εμέ έλεος και αλήθειαν· μη με θάψης, παρακαλώ, εν τη Αιγύπτω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'αλλά θέλω κοιμηθή μετά των πατέρων μου και θέλεις με μετακομίσει εκ της Αιγύπτου και θέλεις με θάψει εν τω τάφω αυτών. Ο δε είπεν, Εγώ θέλω κάμει κατά τον λόγον σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Ο δε είπεν, Ομοσόν μοι και ώμοσεν εις αυτόν. Και προσεκύνησεν ο Ισραήλ επί το άκρον της ράβδου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Μετά δε τα πράγματα ταύτα, είπον προς τον Ιωσήφ, Ιδού, ο πατήρ σου ασθενεί. Και έλαβε μεθ\' εαυτού τους δύο υιούς αυτού, τον Μανασσή και τον Εφραΐμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Και απήγγειλαν προς τον Ιακώβ, λέγοντες, Ιδού, ο υιός σου Ιωσήφ έρχεται προς σέ· και αναλαβών δύναμιν, ο Ισραήλ εκάθισεν επί την κλίνην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Και είπεν ο Ιακώβ προς τον Ιωσήφ, Ο Θεός ο Παντοδύναμος εφάνη εις εμέ εν Λούζ εν τη γη Χαναάν και με ευλόγησε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'και είπε προς εμέ, Ιδού, εγώ θέλω σε αυξήσει και θέλω σε πληθύνει και θέλω σε καταστήσει εις πλήθος λαών· και θέλω δώσει την γην ταύτην εις το σπέρμα σου μετά σε παντοτεινήν ιδιοκτησίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Τώρα λοιπόν οι δύο υιοί σου, οι γεννηθέντες εις σε εν τη γη της Αιγύπτου, πριν εγώ έλθω προς σε εις την Αίγυπτον είναι ιδικοί μου· ο Εφραΐμ και ο Μανασσής θέλουσιν είσθαι εις εμέ ως ο Ρουβήν και ο Συμεών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'τα δε τέκνα σου όσα γεννήσης μετά τούτους, θέλουσιν είσθαι ιδικά σου· κατά το όνομα των αδελφών αυτών θέλουσιν ονομασθή εν τη κληρονομία αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Ότε δε εγώ ηρχόμην από Παδάν, απέθανεν εις εμέ η Ραχήλ καθ\' οδόν εν τη γη Χαναάν, ενώ δεν έλειπεν ειμή ολίγον διάστημα διά να φθάσωμεν εις Εφραθά· και έθαψα αυτήν εκεί εν τη οδώ της Εφραθά· αύτη είναι η Βηθλεέμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Ιδών δε ο Ισραήλ τους υιούς του Ιωσήφ, είπε, Τίνες είναι ούτοι;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'και είπεν ο Ιωσήφ προς τον πατέρα αυτού, Ούτοι είναι οι υιοί μου, τους οποίους μοι έδωκεν ο Θεός ενταύθα. Ο δε είπε, Φέρε αυτούς, παρακαλώ, προς εμέ, διά να ευλογήσω αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Ήσαν δε οι οφθαλμοί του Ισραήλ βαρυωποί υπό του γήρατος, δεν ηδύνατο να βλέπη. Και επλησίασεν αυτούς προς αυτόν· και εφίλησεν αυτούς και ενηγκαλίσθη αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Και είπεν ο Ισραήλ προς τον Ιωσήφ, Δεν ήλπιζον να ίδω το πρόσωπόν σου· και ιδού, ο Θεός έδειξεν εις εμέ και το σπέρμα σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Και εξήγαγεν αυτούς ο Ιωσήφ εκ μέσου των γονάτων αυτού. Και προσεκύνησεν επί πρόσωπον έως εδάφους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Λαβών δε αυτούς ο Ιωσήφ αμφοτέρους, τον Εφραΐμ εν τη δεξιά αυτού προς την αριστεράν του Ισραήλ, και τον Μανασσή εν τη αριστερά αυτού προς την δεξιάν του Ισραήλ, επλησίασεν εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Και εκτείνας ο Ισραήλ την δεξιάν αυτού επέθεσεν επί την κεφαλήν του Εφραΐμ, όστις ήτο ο νεώτερος, την δε αριστεράν αυτού επί την κεφαλήν του Μανασσή, εναλλάξας τας χείρας αυτού· διότι ο Μανασσής ήτο ο πρωτότοκος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Και ευλόγησε τον Ιωσήφ και είπεν, Ο Θεός, έμπροσθεν του οποίου περιεπάτησαν οι πατέρες μου Αβραάμ και Ισαάκ, ο Θεός όστις με εποίμανεν εκ γεννήσεώς μου έως της ημέρας ταύτης,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'ο άγγελος όστις με ελύτρωσεν εκ πάντων των κακών, να ευλογήση τα παιδία ταύτα· και να ονομασθή επ\' αυτά το όνομά μου και το όνομα των πατέρων μου Αβραάμ και Ισαάκ, και να πληθυνθώσιν εις πλήθος μέγα επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Και ιδών ο Ιωσήφ ότι επέθεσεν ο πατήρ αυτού την χείρα αυτού την δεξιάν επί την κεφαλήν του Εφραΐμ, δυσηρεστήθη· και επίασε την χείρα του πατρός αυτού διά να μεταθέση αυτήν από της κεφαλής του Εφραΐμ επί την κεφαλήν του Μανασσή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Και είπεν ο Ιωσήφ προς τον πατέρα αυτού, Μη ούτω, πάτερ μου, διότι ούτος είναι ο πρωτότοκος· επίθες την δεξιάν σου επί την κεφαλήν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Αλλ\' ο πατήρ αυτού δεν ηθέλησε· και είπεν, Εξεύρω, τέκνον μου, εξεύρω· και ούτος θέλει κατασταθή λαός και ούτος έτι θέλει γείνει μέγας· αλλ\' όμως ο αδελφός αυτού ο νεώτερος θέλει είσθαι μεγαλήτερος αυτού και το σπέρμα αυτού θέλει γείνει πλήθος εθνών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Και ευλόγησεν αυτούς την ημέραν εκείνην, λέγων, Εις σε αναφερόμενος θέλει ευλογεί ο Ισραήλ, λέγων, Ο Θεός να σε κάμη ως τον Εφραΐμ και ως τον Μανασσή. Και έστησε τον Εφραΐμ προ του Μανασσή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Και είπεν ο Ισραήλ προς τον Ιωσήφ, Ιδού, εγώ αποθνήσκω· και ο Θεός θέλει είσθαι με σας και θέλει σας επαναφέρει εις την γην των πατέρων σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'και εγώ δίδω εις σε μερίδιον εν υπέρ τους αδελφούς σου, το οποίον έλαβον εκ της χειρός των Αμορραίων διά της μαχαίρας μου και διά του τόξου μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Εκάλεσε δε ο Ιακώβ τους υιούς αυτού και είπε, Συνάχθητε, διά να σας αναγγείλω τι μέλλει να συμβή εις εσάς εν ταις εσχάταις ημέραις·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'συνάχθητε και ακούσατε, υιοί του Ιακώβ, και ακροάσθητε τον Ισραήλ τον πατέρα σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ρουβήν ο πρωτότοκός μου, συ ισχύς μου και αρχή των δυνάμεών μου, έξοχος κατά την αξίαν και έξοχος κατά την δύναμιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Εξέβρασας ως ύδωρ· δεν θέλεις έχει την υπεροχήν· διότι ανέβης επί την κλίνην του πατρός σου· τότε εμίανας αυτήν· επί την κλίνην μου ανέβη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Συμεών και Λευΐ οι αδελφοί, όργανα αδικίας είναι αι μάχαιραι αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'εις την βουλήν αυτών μη εισέλθης, ψυχή μου· εις την συνέλευσιν αυτών μη ενωθής, τιμή μου· διότι εν τω θυμώ αυτών εφόνευσαν ανθρώπους και εν τω πείσματι αυτών κατηδάφισαν τείχος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Επικατάρατος ο θυμός αυτών, διότι ήτο αυθάδης· και η οργή αυτών, διότι ήτο σκληρά· θέλω διαμοιράσει αυτούς εις τον Ιακώβ, και θέλω διασκορπίσει αυτούς εις τον Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Ιούδα, σε θέλουσι επαινέσει οι αδελφοί σου· η χειρ σου θέλει είσθαι επί τον τράχηλον των εχθρών σου· οι υιοί του πατρός σου θέλουσι σε προσκυνήσει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'σκύμνος λέοντος είναι ο Ιούδας· εκ του θηρεύματος, υιέ μου, ανέβης· αναπεσών εκοιμήθη ως λέων και ως σκύμνος λέοντος· τις θέλει εγείρει αυτόν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Δεν θέλει εκλείψει το σκήπτρον εκ του Ιούδα ουδέ νομοθέτης εκ μέσου των ποδών αυτού, εωσού έλθη ο Σηλώ· και εις αυτόν θέλει είσθαι η υπακοή των λαών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Εις την άμπελον δένει το πωλάριον αυτού, και εις τον εκλεκτόν βλαστόν το παιδίον της όνου αυτού· θέλει πλύνει εν οίνω το ένδυμα αυτού και εν τω αίματι της σταφυλής το περιβόλαιον αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Οι οφθαλμοί αυτού θέλουσιν είσθαι ερυθροί εκ του οίνου και οι οδόντες αυτού λευκοί εκ του γάλακτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Ο Ζαβουλών θέλει κατοικήσει εν λιμένι θαλάσσης και θέλει είσθαι εν λιμένι πλοίων· το δε όριον αυτού θέλει εκταθή έως Σιδώνος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Ο Ισσάχαρ είναι όνος δυνατός, κοιτώμενος εν τω μέσω των επαύλεων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Και ιδών ότι η ανάπαυσις ήτο καλή και ο τόπος τερπνός, έκλινε τον ώμον αυτού εις φορτίον και έγεινε δούλος υποτελής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Ο Δαν θέλει κρίνει τον λαόν αυτού, ως μία εκ των φυλών του Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Ο Δαν θέλει είσθαι όφις επί της οδού, ασπίς επί της τρίβου, δάκνων τας πτέρνας του ίππου, ώστε ο ιππεύς αυτού θέλει πίπτει εις τα οπίσω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Την σωτηρίαν σου περιέμεινα, Κύριε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Τον Γαδ θέλουσι πειρατεύσει πειραταί· πλην και αυτός εις το τέλος θέλει πειρατεύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Του Ασήρ ο άρτος θέλει είσθαι παχύς· και αυτός θέλει δίδει βασιλικάς τρυφάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Ο Νεφθαλί είναι έλαφος απολελυμένη, δίδων λόγους αρεστούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Ο Ιωσήφ, κλάδος καρποφόρος, κλάδος καρποφόρος πλησίον πηγής, του οποίου οι βλαστοί εκτείνονται επί του τοίχου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Οι τοξόται επίκραναν αυτόν και ετόξευσαν κατ\' αυτού, και εχθρεύθησαν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Αλλά το τόξον αυτού έμεινε δυνατόν και οι βραχίονες των χειρών αυτού ενεδυναμώθησαν διά των χειρών του ισχυρού Θεού του Ιακώβ· εκείθεν ο ποιμήν, η πέτρα του Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'και τούτο διά του Θεού του πατρός σου, όστις θέλει σε βοηθεί, και διά του Παντοδυνάμου, όστις θέλει σε ευλογεί, ευλογίας του ουρανού άνωθεν, ευλογίας της αβύσσου κάτωθεν, ευλογίας των μαστών και της μήτρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Αι ευλογίαι του πατρός σου υπερίσχυσαν υπέρ τας ευλογίας των προγόνων μου έως των υψηλών κορυφών των αιωνίων ορέων· θέλουσιν είσθαι επί της κεφαλής του Ιωσήφ και επί της κορυφής του εκλεκτού μεταξύ των αδελφών αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Ο Βενιαμίν θέλει είσθαι λύκος άρπαξ· το πρωΐ θέλει κατατρώγει θήραμα, και το εσπέρας θέλει διαιρεί λάφυρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Πάντες ούτοι είναι αι δώδεκα φυλαί του Ισραήλ, και τούτο είναι το οποίον ελάλησε προς αυτούς ο πατήρ αυτών και ευλόγησεν αυτούς· έκαστον κατά την ευλογίαν αυτού ευλόγησεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Και παρήγγειλεν εις αυτούς και είπε προς αυτούς, Εγώ προστίθεμαι εις τον λαόν μου· θάψατέ με μετά των πατέρων μου εν τω σπηλαίω τω εν τω αγρώ Εφρών του Χετταίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'εν τω σπηλαίω τω εν τω αγρώ Μαχπελάχ τω απέναντι της Μαμβρή εν τη γη Χαναάν, το οποίον ο Αβραάμ ηγόρασε μετά του αγρού παρά του Εφρών του Χετταίου διά κτήμα μνημείου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'εκεί έθαψαν τον Αβραάμ και την Σάρραν την γυναίκα αυτού· εκεί έθαψαν τον Ισαάκ και την Ρεβέκκαν την γυναίκα αυτού· και εκεί έθαψα εγώ την Λείαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'η αγορά του αγρού και του σπηλαίου του εν αυτώ έγεινε παρά των υιών του Χετ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Και αφού ετελείωσεν ο Ιακώβ παραγγέλλων εις τους υιούς αυτού, έσυρε τους πόδας αυτού επί την κλίνην και εξέπνευσε· και προσετέθη εις τον λαόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Και έπεσεν ο Ιωσήφ επί το πρόσωπον του πατρός αυτού και έκλαυσεν επ\' αυτόν και εφίλησεν αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Και προσέταξεν ο Ιωσήφ τους δούλους αυτού τους ιατρούς να βαλσαμώσωσι τον πατέρα αυτού· και εβαλσάμωσαν οι ιατροί τον Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Και συνεπληρώθησαν δι\' αυτόν τεσσαράκοντα ημέραι· διότι ούτω συμπληρούνται αι ημέραι της βαλσαμώσεως· και επένθησαν αυτόν οι Αιγύπτιοι εβδομήκοντα ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Αφού δε παρήλθον αι ημέραι του πένθους αυτού, ελάλησεν ο Ιωσήφ προς τον οίκον του Φαραώ, λέγων, Εάν τώρα εύρηκα χάριν ενώπιόν σας, λαλήσατε, παρακαλώ, εις τα ώτα του Φαραώ, λέγοντες,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Ο πατήρ μου με ώρκισε, λέγων, Ιδού, εγώ αποθνήσκω· εις το μνημείόν μου, το οποίον έσκαψα εις εμαυτόν εν γη Χαναάν, εκεί θέλεις με θάψει· τώρα λοιπόν ας αναβώ, παρακαλώ, και ας θάψω τον πατέρα μου· και θέλω επιστρέψει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Και είπεν ο Φαραώ, Ανάβηθι και θάψον τον πατέρα σου καθώς σε ώρκισε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Και ανέβη ο Ιωσήφ διά να θάψη τον πατέρα αυτού· και συνανέβησαν μετ\' αυτού πάντες οι δούλοι του Φαραώ, οι πρεσβύτεροι του οίκου αυτού, και πάντες οι πρεσβύτεροι της γης Αιγύπτου');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'και πας ο οίκος του Ιωσήφ και οι αδελφοί αυτού και ο οίκος του πατρός αυτού· μόνον τας οικογενείας αυτών και τα ποίμνια αυτών και τας αγέλας αυτών αφήκαν εν τη γη Γεσέν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Και συνανέβησαν μετ\' αυτού και άμαξαι και ιππείς· ώστε έγεινε συνοδία μεγάλη σφόδρα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'και ήλθον εις το αλώνιον του Ατάδ το πέραν του Ιορδάνου· και εκεί εθρήνησαν θρήνον μέγαν και δυνατόν σφόδρα· και έκαμεν ο Ιωσήφ διά τον πατέρα αυτού πένθος επτά ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Και ιδόντες οι κάτοικοι του τόπου, οι Χαναναίοι, το πένθος εν τω αλωνίω του Ατάδ, είπον, Πένθος μέγα είναι τούτο εις τους Αιγυπτίους· διά τούτο ωνομάσθη το όνομα αυτού Αβέλ-μισραΐμ, το οποίον είναι πέραν του Ιορδάνου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Και έκαμον εις αυτόν οι υιοί αυτού καθώς παρήγγειλεν εις αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'και μετακομίσαντες αυτόν οι υιοί αυτού εις γην Χαναάν, έθαψαν αυτόν εν τω σπηλαίω του αγρού Μαχπελάχ, το οποίον ο Αβραάμ ηγόρασε μετά του αγρού διά κτήμα μνημείου παρά του Εφρών του Χετταίου κατέναντι της Μαμβρή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Και αφού ο Ιωσήφ έθαψε τον πατέρα αυτού, επέστρεψεν εις Αίγυπτον αυτός και οι αδελφοί αυτού και πάντες οι συναναβάντες μετ\' αυτού διά να θάψωσι τον πατέρα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Και ιδόντες οι αδελφοί του Ιωσήφ ότι απέθανεν ο πατήρ αυτών, είπον, Ίσως ο Ιωσήφ θέλει μνησικακήσει εις ημάς και θέλει μας ανταποδώσει αυστηρώς πάντα τα κακά όσα επράξαμεν εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Και εμήνυσαν προς τον Ιωσήφ, λέγοντες, Ο πατήρ σου προσέταξε, πριν αποθάνη, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Ούτω θέλετε ειπεί προς τον Ιωσήφ· Συγχώρησον, παρακαλώ, την αδικίαν των αδελφών σου και την αμαρτίαν αυτών· διότι έπραξαν κακόν εις σέ· τώρα λοιπόν συγχώρησον, παρακαλούμεν, την αδικίαν των δούλων του Θεού του πατρός σου. Και έκλαυσεν ο Ιωσήφ ότε ελάλησαν προς αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Υπήγαν δε και οι αδελφοί αυτού και πεσόντες έμπροσθεν αυτού, είπον, Ιδού, ημείς είμεθα δούλοί σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Και είπε προς αυτούς ο Ιωσήφ, Μη φοβείσθε· μήπως αντί Θεού είμαι εγώ;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'σεις μεν εβουλεύθητε κακόν εναντίον μου· ο δε Θεός εβουλεύθη να μεταστρέψη τούτο εις καλόν, διά να γείνη καθώς την σήμερον, ώστε να σώση την ζωήν πολλού λαού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'τώρα λοιπόν μη φοβείσθε· εγώ θέλω θρέψει εσάς και τας οικογενείας σας. Και παρηγόρησεν αυτούς και ελάλησε κατά την καρδίαν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Και κατώκησεν ο Ιωσήφ εν Αιγύπτω, αυτός και ο οίκος του πατρός αυτού· και έζησεν ο Ιωσήφ εκατόν δέκα έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Και είδεν ο Ιωσήφ τέκνα του Εφραΐμ, έως τρίτης γενεάς· και τα παιδία του Μαχείρ, υιού του Μανασσή, επί των γονάτων του Ιωσήφ εγεννήθησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Και είπεν ο Ιωσήφ προς τους αδελφούς αυτού, Εγώ αποθνήσκω· ο δε Θεός θέλει βεβαίως σας επισκεφθή και θέλει σας αναβιβάσει εκ της γης ταύτης εις την γην, την οποίαν ώμοσε προς τον Αβραάμ, προς τον Ισαάκ και προς τον Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Και ώρκισεν ο Ιωσήφ τους υιούς Ισραήλ, λέγων, Ο Θεός βεβαίως θέλει σας επισκεφθή και θέλετε αναβιβάσει τα οστά μου εντεύθεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Και ετελεύτησεν ο Ιωσήφ εν ηλικία ετών εκατόν δέκα· και εβαλσάμωσαν αυτόν· και ετέθη εις θήκην εν τη Αιγύπτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Και ταύτα είναι τα ονόματα των υιών Ισραήλ, των εισελθόντων εις Αίγυπτον μετά του Ιακώβ· έκαστος μετά της οικογένειας αυτού εισήλθον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ρουβήν, Συμεών, Λευΐ και Ιούδας,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Ισσάχαρ, Ζαβουλών και Βενιαμίν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Δαν και Νεφθαλί, Γαδ και Ασήρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Και πάσαι αι ψυχαί αι εξελθούσαι εκ του μηρού του Ιακώβ ήσαν ψυχαί εβδομήκοντα· ο δε Ιωσήφ ήτο ήδη εν Αιγύπτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Ετελεύτησε δε ο Ιωσήφ και πάντες οι αδελφοί αυτού, και πάσα η γενεά εκείνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Και ηυξήνθησαν οι υιοί Ισραήλ και επληθύνθησαν, και επολλαπλασιάσθησαν, και ενεδυναμώθησαν σφόδρα, ώστε ο τόπος εγέμισεν απ\' αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Εσηκώθη δε νέος βασιλεύς επί την Αίγυπτον, όστις δεν εγνώριζε τον Ιωσήφ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Και είπε προς τον λαόν αυτού, Ιδού, ο λαός των υιών Ισραήλ είναι πολύ πλήθος και ισχυρότερος ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'έλθετε, ας σοφισθώμεν κατ\' αυτών, διά να μη πολλαπλασιασθώσι, και αν συμβή πόλεμος ενωθώσι και ούτοι μετά των εχθρών ημών και πολεμήσωσιν ημάς και αναχωρήσωσιν εκ του τόπου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Κατέστησαν λοιπόν επ\' αυτούς επιστάτας των εργασιών, διά να καταθλίβωσιν αυτούς με τα βάρη αυτών· και ωκοδόμησαν εις τον Φαραώ πόλεις αποθηκών, την Πιθώμ και την Ραμεσσή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Όσον όμως κατέθλιβον αυτούς, τόσω μάλλον επληθύνοντο και ηυξάνοντο. Και οι Αιγύπτιοι απεστρέφοντο τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Και κατεδυνάστευον οι Αιγύπτιοι τους υιούς Ισραήλ αυστηρώς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'και κατεπίκραινον την ζωήν αυτών διά της σκληράς δουλείας εις τον πηλόν και εις τας πλίνθους, και εις πάσας τας εργασίας των πεδιάδων· πάσαι αι εργασίαι αυτών, με τας οποίας κατεδυνάστευον αυτούς, ήσαν αυστηραί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Και ελάλησεν ο βασιλεύς των Αιγυπτίων προς τας μαίας των Εβραίων, εκ των οποίων η μία ωνομάζετο Σεπφώρα, και η άλλη Φουά,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'και είπεν, Όταν μαιεύητε τας Εβραίας και ίδητε αυτάς επί της γέννας, εάν μεν ήναι αρσενικόν, θανατόνετε αυτό· εάν δε ήναι θηλυκόν, τότε ας ζήση.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Εφοβήθησαν δε αι μαίαι τον Θεόν και δεν έκαμνον ως είπε προς αυτάς ο βασιλεύς της Αιγύπτου, αλλ\' άφινον ζώντα τα αρσενικά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Καλέσας δε ο βασιλεύς της Αιγύπτου τας μαίας, είπε προς αυτάς, Διά τι εκάμετε το πράγμα τούτο, και αφίνετε ζώντα τα αρσενικά;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Και απεκρίθησαν αι μαίαι προς τον Φαραώ, Ότι αι Εβραίαι δεν είναι ως αι γυναίκες της Αιγύπτου· διότι είναι εύρωστοι και γεννώσι πριν εισέλθωσιν εις αυτάς αι μαίαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Ο δε Θεός ηγαθοποίει τας μαίας· και επληθύνετο ο λαός και ενεδυναμούτο σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Και επειδή αι μαίαι εφοβούντο τον Θεόν, έκαμεν εις αυτάς οίκους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Ο δε Φαραώ προσέταξε πάντα τον λαόν αυτού, λέγων, Παν αρσενικόν το οποίον γεννηθή, εις τον ποταμόν ρίπτετε αυτό· παν δε θηλυκόν, αφίνετε να ζη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Υπήγε δε άνθρωπός τις εκ του οίκου Λευΐ, και έλαβεν εις γυναίκα μίαν εκ των θυγατέρων Λευΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Και συνέλαβεν η γυνή και εγέννησεν υιόν· ιδούσα δε αυτόν ότι ήτο εύμορφος, έκρυψεν αυτόν τρεις μήνας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Μη δυναμένη δε να κρύπτη αυτόν πλέον, έλαβε δι\' αυτόν κιβώτιον σπάρτινον και κατέχρισεν αυτό με άσφαλτον και πίσσαν και ενέβαλε το παιδίον εις αυτό και έθεσεν εις το ελώδες μέρος παρά το χείλος του ποταμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Η δε αδελφή αυτού παρεμόνευε μακρόθεν, διά να ίδη το αποβησόμενον εις αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Και κατέβη η θυγάτηρ του Φαραώ διά να λουσθή εις τον ποταμόν, αι δε θεράπαιναι αυτής περιεπάτουν επί την όχθην του ποταμού· και ότε είδε το κιβώτιον εις το ελώδες μέρος, έστειλε την παιδίσκην αυτής και έλαβεν αυτό·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'και ανοίξασα βλέπει το παιδίον και ιδού, το νήπιον έκλαιε· και ελυπήθη αυτό, λέγουσα, Εκ των παιδίων των Εβραίων είναι τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Τότε είπεν η αδελφή αυτού προς την θυγατέρα του Φαραώ, Θέλεις να υπάγω να καλέσω εις σε γυναίκα θηλάζουσαν εκ των Εβραίων, διά να σοι θηλάση το παιδίον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Και είπε προς αυτήν η θυγάτηρ του Φαραώ, Ύπαγε. Και υπήγε το κοράσιον και εκάλεσε την μητέρα του παιδίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Και είπε προς αυτήν η θυγάτηρ του Φαραώ, Λάβε το παιδίον τούτο και θήλασόν μοι αυτό, και εγώ θέλω σοι δώσει τον μισθόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Έλαβε δε η γυνή το παιδίον και εθήλαζεν αυτό. Και αφού εμεγάλωσε το παιδίον, έφερεν αυτό προς την θυγατέρα του Φαραώ, και έγεινεν υιός αυτής· και εκάλεσε το όνομα αυτού Μωϋσήν, λέγουσα, Ότι εκ του ύδατος ανέσυρα αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Κατά δε τας ημέρας εκείνας, αφού ο Μωϋσής εμεγάλωσεν, εξήλθε προς τους αδελφούς αυτού· και παρατηρών τα βάρη αυτών, βλέπει άνθρωπον Αιγύπτιον τύπτοντα Εβραίον τινά εκ των αδελφών αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Περιβλέψας δε εδώ και εκεί και ιδών ότι δεν ήτο ουδείς, επάταξε τον Αιγύπτιον και έκρυψεν αυτόν εν τη άμμω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Και εξήλθε την ακόλουθον ημέραν και ιδού, δύο άνδρες Εβραίοι διεπληκτίζοντο· και λέγει προς τον αδικούντα, Διά τι τύπτεις τον πλησίον σου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Ο δε είπε, Τις σε κατέστησεν άρχοντα και κριτήν εφ\' ημάς; Μήπως θέλεις συ να με φονεύσης, καθώς εφόνευσας τον Αιγύπτιον; Και εφοβήθη ο Μωϋσής και είπε, Βεβαίως το πράγμα τούτο έγεινε γνωστόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Ακούσας δε ο Φαραώ το πράγμα τούτο, εζήτει να θανατώση τον Μωϋσήν· αλλ\' ο Μωϋσής έφυγεν από προσώπου του Φαραώ και κατώκησεν εν τη γη Μαδιάμ· εκάθισε δε πλησίον του φρέατος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Ο δε ιερεύς της Μαδιάμ είχεν επτά θυγατέρας, αίτινες ελθούσαι ήντλησαν ύδωρ και εγέμισαν τας ποτίστρας διά να ποτίσωσι τα πρόβατα του πατρός αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Ελθόντες δε οι ποιμένες εδίωξαν αυτάς· και σηκωθείς ο Μωϋσής εβοήθησεν αυτάς και επότισε τα πρόβατα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Και ότε ήλθον προς Ραγουήλ τον πατέρα αυτών, είπε προς αυτάς, Διά τι τόσον ταχέως ήλθετε σήμερον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Αι δε είπον, Άνθρωπος Αιγύπτιος ελύτρωσεν ημάς εκ των χειρών των ποιμένων και προσέτι ήντλησεν εις ημάς ύδωρ και επότισε τα πρόβατα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Ο δε είπε προς τας θυγατέρας αυτού, Και που είναι; διά τι αφήκατε τον άνθρωπον; καλέσατε αυτόν διά να φάγη άρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Και ευχαριστήθη ο Μωϋσής να κατοική μετά του ανθρώπου· όστις έδωκεν εις τον Μωϋσήν εις γυναίκα Σεπφώραν την θυγατέρα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Και εγέννησεν υιόν· και εκάλεσε το όνομα αυτού Γηρσώμ, λέγων, Πάροικος είμαι εν ξένη γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Μετά δε πολύν καιρόν, ετελεύτησεν ο βασιλεύς της Αιγύπτου· και κατεστέναξαν οι υιοί Ισραήλ διά την δουλείαν και ανεβόησαν· και η βοή αυτών ανέβη προς τον Θεόν εξ αιτίας της δουλείας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Και εισήκουσεν ο Θεός των στεναγμών αυτών· και ενεθυμήθη ο Θεός την διαθήκην αυτού την προς τον Αβραάμ, τον Ισαάκ και τον Ιακώβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'και επέβλεψεν ο Θεός επί τους υιούς Ισραήλ και ηλέησεν αυτούς ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Ο δε Μωϋσής έβοσκε τα πρόβατα του Ιοθόρ, πενθερού αυτού, ιερέως της Μαδιάμ· και έφερε τα πρόβατα εις το όπισθεν μέρος της ερήμου και ήλθεν εις το όρος του Θεού, το Χωρήβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Εφάνη δε εις αυτόν άγγελος Κυρίου εν φλογί πυρός εκ μέσου της βάτου· και είδε και ιδού, η βάτος εκαίετο υπό του πυρός και η βάτος δεν κατεκαίετο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Και είπεν ο Μωϋσής, Ας στρέψω και ας παρατηρήσω το μέγα τούτο θέαμα, διά τι η βάτος δεν κατακαίεται.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Και ως είδεν ο Κύριος τον Μωϋσήν ότι έστρεψε να παρατηρήση, εφώνησε προς αυτόν ο Θεός εκ μέσου της βάτου και είπε, Μωϋσή, Μωϋσή. Ο δε είπεν, Ιδού, εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Και είπε, Μη πλησιάσης εδώ· λύσον τα υποδήματά σου εκ των ποδών σου· διότι ο τόπος επί του οποίου ίστασαι είναι γη αγία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Και είπε προς αυτόν, Εγώ είμαι ο Θεός του πατρός σου, ο Θεός του Αβραάμ, ο Θεός του Ισαάκ και ο Θεός του Ιακώβ. Έκρυψε δε το πρόσωπον αυτού ο Μωϋσής· διότι εφοβείτο να εμβλέψη εις τον Θεόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Και είπεν ο Κύριος, Είδον, είδον την ταλαιπωρίαν του λαού μου του εν Αιγύπτω και ήκουσα την κραυγήν αυτών εξ αιτίας των εργοδιωκτών αυτών· διότι εγνώρισα την οδύνην αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'και κατέβην διά να ελευθερώσω αυτούς εκ της χειρός των Αιγυπτίων και να αναβιβάσω αυτούς εκ της γης εκείνης εις γην καλήν και ευρύχωρον, εις γην ρέουσαν γάλα και μέλι, εις τον τόπον των Χαναναίων και Χετταίων και Αμορραίων και Φερεζαίων και Ευαίων και Ιεβουσαίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'και τώρα ιδού, η κραυγή των υιών Ισραήλ ήλθεν εις εμέ· και είδον έτι την κατάθλιψιν, με την οποίαν οι Αιγύπτιοι καταθλίβουσιν αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'ελθέ λοιπόν τώρα και θέλω σε αποστείλει προς τον Φαραώ, και θέλεις εξαγάγει τον λαόν μου τους υιούς Ισραήλ εξ Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Και απεκρίθη ο Μωϋσής προς τον Θεόν, Τις είμαι εγώ, διά να υπάγω προς τον Φαραώ και να εξαγάγω τους υιούς Ισραήλ εξ Αιγύπτου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Και είπεν ο Θεός, Βεβαίως εγώ θέλω είσθαι μετά σού· και τούτο θέλει είσθαι εις σε το σημείον, ότι εγώ σε απέστειλα· Αφού εξαγάγης τον λαόν μου εξ Αιγύπτου, θέλετε λατρεύσει τον Θεόν επί του όρους τούτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Και είπεν ο Μωϋσής προς τον Θεόν, Ιδού, όταν εγώ υπάγω προς τους υιούς Ισραήλ και είπω προς αυτούς, Ο Θεός των πατέρων σας με απέστειλε προς εσάς, και εκείνοι μ\' ερωτήσωσι, Τι είναι το όνομα αυτού; τι θέλω ειπεί προς αυτούς;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Και είπεν ο Θεός προς τον Μωϋσήν, Εγώ είμαι ο Ων· και είπεν, Ούτω θέλεις ειπεί προς τους υιούς Ισραήλ· Ο Ων με απέστειλε προς εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Και είπεν έτι ο Θεός προς τον Μωϋσήν, Ούτω θέλεις ειπεί προς τους υιούς Ισραήλ· Κύριος ο Θεός των πατέρων σας, ο Θεός του Αβραάμ, ο Θεός του Ισαάκ και ο Θεός του Ιακώβ, με απέστειλε προς εσάς· τούτο θέλει είσθαι το όνομά μου εις τον αιώνα και τούτο το μνημόσυνόν μου εις γενεάς γενεών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'ύπαγε και σύναξον τους πρεσβυτέρους του Ισραήλ και ειπέ προς αυτούς, Κύριος ο Θεός των πατέρων σας, ο Θεός του Αβραάμ, του Ισαάκ και του Ιακώβ, εφάνη εις εμέ, λέγων, Επεσκέφθην αληθώς εσάς και τα όσα κάμνουσιν εις εσάς εν Αιγύπτω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'και είπα, Θέλω σας αναβιβάσει εκ της ταλαιπωρίας των Αιγυπτίων εις την γην των Χαναναίων και Χετταίων και Αμορραίων και Φερεζαίων και Ευαίων και Ιεβουσαίων, εις γην ρέουσαν γάλα και μέλι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'και θέλουσιν υπακούσει εις την φωνήν σου· και θέλεις υπάγει, συ και οι πρεσβύτεροι του Ισραήλ, προς τον βασιλέα της Αιγύπτου και θέλετε ειπεί προς αυτόν, Κύριος ο Θεός των Εβραίων συνήντησεν ημάς· τώρα λοιπόν άφες να υπάγωμεν οδόν τριών ημερών εις την έρημον, διά να προσφέρωμεν θυσίαν εις Κύριον τον Θεόν ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'εγώ δε εξεύρω, ότι δεν θέλει σας αφήσει ο βασιλεύς της Αιγύπτου να υπάγητε, ειμή διά χειρός κραταιάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'και εκτείνας την χείρα μου, θέλω πατάξει την Αίγυπτον με πάντα τα θαυμάσιά μου τα οποία θέλω κάμει εν μέσω αυτής· και μετά ταύτα θέλει σας εξαποστείλει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'και θέλω δώσει χάριν εις τον λαόν τούτον έμπροσθεν των Αιγυπτίων· και όταν αναχωρήτε, δεν θέλετε αναχωρήσει κενοί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'αλλά πάσα γυνή θέλει ζητήσει παρά της γείτονος αυτής και παρά της συγκατοίκου αυτής σκεύη αργυρά και σκεύη χρυσά και ενδύματα· και θέλετε επιθέσει αυτά επί τους υιούς σας και επί τας θυγατέρας σας και θέλετε γυμνώσει τους Αιγυπτίους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Απεκρίθη δε ο Μωϋσής και είπε, Αλλ\' ιδού, δεν θέλουσι πιστεύσει εις εμέ ουδέ θέλουσιν εισακούσει εις την φωνήν μου· διότι θέλουσιν ειπεί, δεν εφάνη εις σε ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Και είπε προς αυτόν ο Κύριος, Τι είναι τούτο, το εν τη χειρί σου; Ο δε είπε, Ράβδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Και είπε, Ρίψον αυτήν κατά γης. Και έρριψεν αυτήν κατά γης και έγεινεν όφις· και έφυγεν ο Μωϋσής απ\' έμπροσθεν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Και είπε Κύριος προς τον Μωϋσήν, Έκτεινον την χείρα σου και πίασον αυτόν από της ουράς· και εκτείνας την χείρα αυτού επίασεν αυτόν και έγεινε ράβδος εν τη χειρί αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'διά να πιστεύσωσιν ότι εφάνη εις σε Κύριος ο Θεός των πατέρων αυτών, ο Θεός του Αβραάμ, ο Θεός του Ισαάκ και ο Θεός του Ιακώβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Και είπεν έτι προς αυτόν ο Κύριος, Βάλε τώρα την χείρα σου εις τον κόλπον σου. Και έβαλε την χείρα αυτού εις τον κόλπον αυτού· και ότε εξήγαγεν αυτήν, ιδού, η χειρ αυτού λεπρά ως χιών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Και είπε, Βάλε πάλιν την χείρα σου εις τον κόλπον σου. Και έβαλε την χείρα αυτού εις τον κόλπον αυτού· και ότε εξήγαγεν αυτήν εκ του κόλπου αυτού, ιδού, αποκατεστάθη καθώς η σαρξ αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Εάν δε, είπεν ο Κύριος, δεν πιστεύσωσιν εις σε μηδέ εισακούσωσιν εις την φωνήν του σημείου του πρώτου, θέλουσι πιστεύσει εις την φωνήν του σημείου του δευτέρου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'εάν δε δεν πιστεύσωσι και εις τα δύο ταύτα σημεία μηδέ εισακούσωσιν εις την φωνήν σου, θέλεις λάβει εκ του ύδατος του ποταμού και θέλεις χύσει αυτό επί της ξηράς· και το ύδωρ, το οποίον ήθελες λάβει εκ του ποταμού, θέλει γείνει αίμα επί της ξηράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Και είπεν ο Μωϋσής προς τον Κύριον, Δέομαι, Κύριε· εγώ δεν είμαι εύλαλος ούτε από χθές ούτε από προχθές ούτε αφ\' ης ώρας ελάλησας προς τον δούλον σου· αλλ\' είμαι βραδύστομος και βραδύγλωσσος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Και είπε προς αυτόν ο Κύριος, Τις έδωκε στόμα εις τον άνθρωπον; ή τις έκαμε τον εύλαλον, ή τον κωφόν ή τον βλέποντα ή τον τυφλόν; ουχί εγώ ο Κύριος;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'ύπαγε λοιπόν τώρα και εγώ θέλω είσθαι μετά του στόματός σου και θέλω σε διδάξει ό,τι μέλλεις να λαλήσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Ο δε είπε, Δέομαι, Κύριε, απόστειλον όντινα έχεις να αποστείλης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Και εξήφθη ο θυμός του Κυρίου κατά του Μωϋσέως· και είπε, Δεν είναι Ααρών ο αδελφός σου ο Λευΐτης; εξεύρω ότι αυτός δύναται να λαλή καλώς· και μάλιστα, ιδού, εξέρχεται εις συνάντησίν σου και όταν σε ίδη, θέλει χαρή εν τη καρδία αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'συ λοιπόν θέλεις λαλεί προς αυτόν και θέλεις βάλλει τους λόγους εις το στόμα αυτού· εγώ δε θέλω είσθαι μετά του στόματός σου και μετά του στόματος εκείνου και θέλω σας διδάξει ό,τι πρέπει να πράξητε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'και αυτός θέλει λαλεί αντί σου προς τον λαόν· και αυτός θέλει είσθαι εις σε αντί στόματος, συ δε θέλεις είσθαι εις αυτόν αντί Θεού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'λάβε δε εις την χείρα σου την ράβδον ταύτην, με την οποίαν θέλεις κάμνει τα σημεία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Και ανεχώρησεν ο Μωϋσής και επέστρεψε προς τον Ιοθόρ τον πενθερόν αυτού και είπε προς αυτόν, Ας υπάγω, παρακαλώ, και ας επιστρέψω προς τους αδελφούς μου, τους εν Αιγύπτω, και ας ίδω αν ζώσιν έτι. Και είπεν ο Ιοθόρ προς τον Μωϋσήν, Ύπαγε εν ειρήνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Ο δε Κύριος είπε προς τον Μωϋσήν εν Μαδιάμ, Ύπαγε, επίστρεψον εις Αίγυπτον· διότι απέθανον πάντες οι άνθρωποι οι ζητούντες την ψυχήν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Τότε παραλαβών ο Μωϋσής την γυναίκα αυτού και τα τέκνα αυτού και καθίσας αυτά επί όνους επέστρεψεν εις την γην της Αιγύπτου· έλαβε δε ο Μωϋσής την ράβδον του Θεού εν τη χειρί αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Και είπε Κύριος προς τον Μωϋσήν, Όταν υπάγης και επιστρέψης εις Αίγυπτον, ιδέ να κάμης έμπροσθεν του Φαραώ πάντα τα θαυμάσια, τα οποία έδωκα εις την χείρα σου· πλην εγώ θέλω σκληρύνει την καρδίαν αυτού, και δεν θέλει εξαποστείλει τον λαόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'και θέλεις ειπεί προς τον Φαραώ, Ούτω λέγει Κύριος· Υιός μου είναι, πρωτότοκός μου, ο Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'και προς σε λέγω, Εξαπόστειλον τον υιόν μου, διά να με λατρεύση· και εάν δεν θέλης να εξαποστείλης αυτόν, ιδού, εγώ θέλω θανατώσει τον υιόν σου, τον πρωτότοκόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Ενώ δε ο Μωϋσής ήτο εν τη οδώ, εν τω καταλύματι, συνήντησεν αυτόν ο Κύριος και εζήτει να θανατώση αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Και λαβούσα η Σεπφώρα λιθάριον κοπτερόν, περιέτεμε την ακροβυστίαν του υιού αυτής, και έρριψεν εις τους πόδας αυτού, λέγουσα, Βεβαίως νυμφίος αιμάτων είσαι εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Και απήλθεν απ\' αυτού· η δε είπε, Νυμφίος αιμάτων είσαι ένεκα της περιτομής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Είπε δε Κύριος προς τον Ααρών, Ύπαγε προς συνάντησιν του Μωϋσέως εις την έρημον. Και υπήγε και συνήντησεν αυτόν εν τω όρει του Θεού και ησπάσθη αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Και απήγγειλεν ο Μωϋσής προς τον Ααρών πάντας τους λόγους του Κυρίου, τους οποίους παρήγγειλεν εις αυτόν, και πάντα τα σημεία, τα οποία προσέταξεν εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Υπήγαν λοιπόν ο Μωϋσής και ο Ααρών και συνήγαγον πάντας τους πρεσβυτέρους των υιών Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'και ελάλησεν ο Ααρών πάντας τους λόγους, τους οποίους ο Κύριος ελάλησε προς τον Μωϋσήν, και έκαμε τα σημεία ενώπιον του λαού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Και επίστευσεν ο λαός· και ότε ήκουσεν ότι ο Κύριος επεσκέφθη τους υιούς Ισραήλ και ότι επέβλεψεν επί την ταλαιπωρίαν αυτών, κύψαντες προσεκύνησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Μετά δε ταύτα, εισελθόντες ο Μωϋσής και ο Ααρών, είπαν προς τον Φαραώ, Ούτω λέγει Κύριος ο Θεός του Ισραήλ· Εξαπόστειλον τον λαόν μου, διά να εορτάσωσιν εις εμέ εν τη ερήμω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Ο δε Φαραώ είπε, Τις είναι ο Κύριος, εις του οποίου την φωνήν θέλω υπακούσει, ώστε να εξαποστείλω τον Ισραήλ; δεν γνωρίζω τον Κύριον και ουδέ τον Ισραήλ θέλω εξαποστείλει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Οι δε είπον, Ο Θεός των Εβραίων συνήντησεν ημάς· άφες λοιπόν να υπάγωμεν οδόν τριών ημερών εις την έρημον, διά να προσφέρωμεν θυσίαν εις Κύριον τον Θεόν ημών, μήποτε έλθη καθ\' ημών με θανατικόν ή με μάχαιραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Και είπε προς αυτούς ο βασιλεύς της Αιγύπτου, Διά τι, Μωϋσή και Ααρών, αποκόπτετε τον λαόν από των εργασιών αυτού; υπάγετε εις τα έργα σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Και είπεν ο Φαραώ, Ιδού, ο λαός του τόπου είναι τώρα πολυπληθής και σεις κάμνετε αυτούς να παύωσιν από των έργων αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Και την αυτήν ημέραν προσέταξεν ο Φαραώ τους εργοδιώκτας τον λαού και τους επιτρόπους αυτών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Δεν θέλετε δώσει πλέον εις τον λαόν τούτον άχυρον καθώς χθές και προχθές, διά να κάμνωσι τας πλίνθους· ας υπάγωσιν αυτοί και ας συνάγωσιν εις εαυτούς άχυρον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'θέλετε όμως επιβάλει εις αυτούς το ποσόν των πλίνθων, το οποίον έκαμνον πρότερον· παντελώς δεν θέλετε ελαττώσει αυτό· διότι μένουσιν αργοί και διά τούτο φωνάζουσι, λέγοντες, Άφες να υπάγωμεν, διά να προσφέρωμεν θυσίαν εις τον Θεόν ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'ας επιβαρυνθώσιν αι εργασίαι των ανθρώπων τούτων, διά να ήναι ενησχολημένοι εις αυτάς και να μη προσέχωσιν εις λόγια μάταια.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Εξήλθον λοιπόν οι εργοδιώκται του λαού και οι επίτροποι αυτού και ελάλησαν προς τον λαόν, λέγοντες, Ούτως είπεν ο Φαραώ· Δεν σας δίδω άχυρον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'σεις αυτοί υπάγετε, συνάγετε άχυρον, όπου δύνασθε να εύρητε· πλην δεν θέλει ελαττωθή εκ των εργασιών σας ουδέν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Και διεσπάρη ο λαός καθ\' όλην την γην της Αιγύπτου, διά να συνάγη καλάμην αντί αχύρου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Οι δε εργοδιώκται εβίαζον αυτούς, λέγοντες, Τελειόνετε τας εργασίας σας, το διωρισμένον καθ\' ημέραν, καθώς ότε εδίδετο το άχυρον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Και εμαστιγώθησαν οι επίτροποι των υιών Ισραήλ, οι διωρισμένοι επ\' αυτούς υπό των εργοδιωκτών του Φαραώ, λεγόντων, Διά τι δεν ετελειώσατε χθές και σήμερον το διωρισμένον εις εσάς ποσόν των πλίνθων, καθώς πρότερον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Εισελθόντες δε οι επίτροποι των υιών Ισραήλ, κατεβόησαν προς τον Φαραώ, λέγοντες, Διά τι κάμνεις ούτως εις τους δούλους σου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'άχυρον δεν δίδεται εις τους δούλους σου και λέγουσιν εις ημάς, Κάμνετε πλίνθους· και ιδού, εμαστιγώθησαν οι δούλοί σου· το δε σφάλμα είναι του λαού σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Ο δε απεκρίθη, Οκνηροί είσθε, οκνηροί· διά τούτο λέγετε, Άφες να υπάγωμεν να προσφέρωμεν θυσίαν προς τον Κύριον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'υπάγετε λοιπόν τώρα, δουλεύετε· διότι άχυρον δεν θέλει σας δοθή· θέλετε όμως αποδίδει το ποσόν των πλίνθων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Και έβλεπον εαυτούς οι επίτροποι των υιών Ισραήλ εν κακή περιστάσει, αφού ερρέθη προς αυτούς, Δεν θέλει ελαττωθή ουδέν από του καθημερινού ποσού των πλίνθων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Εξερχόμενοι δε από του Φαραώ, συνήντησαν τον Μωϋσήν και τον Ααρών, ερχομένους εις συνάντησιν αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'και είπον προς αυτούς, Ο Κύριος να σας ίδη και να κρίνη· διότι σεις εκάμετε βδελυκτήν την οσμήν ημών έμπροσθεν του Φαραώ και έμπροσθεν των δούλων αυτού, ώστε να δώσητε εις τας χείρας αυτών μάχαιραν διά να θανατώσωσιν ημάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Και επέστρεψεν ο Μωϋσής προς τον Κύριον και είπε, Κύριε, διά τι κατέθλιψας τον λαόν τούτον; και διά τι με απέστειλας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'διότι, αφού ήλθον προς τον Φαραώ να ομιλήσω εν ονόματί σου, κατέθλιψε τον λαόν τούτον· και συ ποσώς δεν ηλευθέρωσας τον λαόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Τώρα θέλεις ιδεί τι θέλω κάμει εις τον Φαραώ· διότι διά χειρός κραταιάς θέλει εξαποστείλει αυτούς· και διά χειρός κραταιάς θέλει εκδιώξει αυτούς εκ της γης αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Ο Θεός ελάλησεν έτι προς τον Μωϋσήν και είπε προς αυτόν, Εγώ είμαι ο Κυριος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'και εφάνην εις τον Αβραάμ, εις τον Ισαάκ και εις τον Ιακώβ, με το όνομα, Θεός Παντοκράτωρ· δεν εγνωρίσθην όμως εις αυτούς με το όνομά μου Ιεοβά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'και έτι έστησα προς αυτούς την διαθήκην μου, να δώσω εις αυτούς την γην Χαναάν την γην της παροικίας αυτών, εν ή παρώκησαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'εγώ προσέτι ήκουσα τους στεναγμούς των υιών Ισραήλ διά την υπό των Αιγυπτίων καταδούλωσιν αυτών· και ενεθυμήθην την διαθήκην μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'διά τούτο ειπέ προς τους υιούς Ισραήλ, Εγώ είμαι ο Κύριος· και θέλω σας εκβάλει υποκάτωθεν των φορτίων των Αιγυπτίων και θέλω σας ελευθερώσει από της δουλείας αυτών και θέλω σας λυτρώσει με βραχίονα εξηπλωμένον και με κρίσεις μεγάλας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'και θέλω σας λάβει εις εμαυτόν διά λαόν μου και θέλω είσθαι Θεός υμών· και θέλετε γνωρίσει ότι εγώ είμαι Κύριος ο Θεός υμών, όστις σας εκβάλλω υποκάτωθεν των φορτίων των Αιγυπτίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'και θέλω σας φέρει εις την γην, περί της οποίας ύψωσα την χείρα μου, ότι θέλω δώσει αυτήν εις τον Αβραάμ, εις τον Ισαάκ και εις τον Ιακώβ· και θέλω σας δώσει αυτήν εις κληρονομίαν. Εγώ ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Και ελάλησεν ο Μωϋσής ούτω προς τους υιούς Ισραήλ· αλλά δεν εισήκουσαν εις τον Μωϋσήν, διά την στενοχωρίαν της ψυχής αυτών και διά την σκληράν δουλείαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Είσελθε, λάλησον προς Φαραώ, τον βασιλέα της Αιγύπτου, διά να εξαποστείλη τους υιούς Ισραήλ εκ της γης αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Και ελάλησεν ο Μωϋσής ενώπιον του Κυρίου, λέγων, Ιδού, οι υιοί Ισραήλ δεν μου εισήκουσαν· και πως θέλει μου εισακούσει ο Φαραώ, και εγώ είμαι απερίτμητος τα χείλη;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών και απέστειλεν αυτούς προς τους υιούς Ισραήλ και προς Φαραώ τον βασιλέα της Αιγύπτου, διά να εξαγάγωσι τους υιούς Ισραήλ εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ούτοι είναι οι αρχηγοί των οίκων των πατριών αυτών· Οι υιοί του Ρουβήν, του πρωτοτόκου του Ισραήλ, Ανώχ και Φαλλού, Εσρών και Χαρμί· αύται είναι αι συγγένειαι του Ρουβήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Και οι υιοί του Συμεών, Ιεμουήλ και Ιαμείν και Αώδ και Ιαχείν και Σωάρ και Σαούλ υιός Χανανίτιδος· αύται είναι αι συγγένειαι του Συμεών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Τα δε ονόματα των υιών του Λευΐ κατά τας γενεάς αυτών είναι ταύτα· Γηρσών και Καάθ και Μεραρί· και τα έτη της ζωής του Λευΐ έγειναν εκατόν τριάκοντα επτά έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Οι υιοί του Γηρσών, Λιβνί και Σεμεΐ, κατά τας συγγενείας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Και οι υιοί του Καάθ, Αμράμ και Ισαάρ και Χεβρών και Οζιήλ· και τα έτη της ζωής του Καάθ έγειναν εκατόν τριάκοντα τρία έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Και οι υιοί του Μεραρί, Μααλί και Μουσί· αύται είναι αι συγγένειαι του Λευΐ, κατά τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Έλαβε δε ο Αμράμ εις γυναίκα εαυτού την Ιωχαβέδ, θυγατέρα του αδελφού του πατρός αυτού· και εγέννησεν εις αυτόν τον Ααρών και τον Μωϋσήν· τα δε έτη της ζωής του Αμράμ έγειναν εκατόν τριάκοντα επτά έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Και οι υιοί του Ισαάρ, Κορέ και Νεφέγ και Ζιθρί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Και οι υιοί του Οζιήλ, Μισαήλ και Ελισαφάν και Σιθρί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Έλαβε δε ο Ααρών εις γυναίκα εαυτού την Ελισάβετ, θυγατέρα του Αμμιναδάβ, αδελφήν του Ναασσών· και εγέννησεν εις αυτόν τον Ναδάβ και τον Αβιούδ, τον Ελεάζαρ και τον Ιθάμαρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Και οι υιοί του Κορέ, Ασείρ και Ελκανά και Αβιάσαφ· αύται είναι αι συγγένειαι των Κοριτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Ο δε Ελεάζαρ, ο υιός του Ααρών, έλαβεν εις γυναίκα εαυτού μίαν εκ των θυγατέρων του Φουτιήλ· και εγέννησεν εις αυτόν τον Φινεές· ούτοι είναι οι αρχηγοί των πατριών των Λευϊτών, κατά τας συγγενείας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Ούτοι είναι ο Ααρών και ο Μωϋσής, προς τους οποίους είπεν ο Κύριος, Εξαγάγετε τους υιούς Ισραήλ, εκ γης Αιγύπτου κατά τα τάγματα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ούτοι είναι οι λαλήσαντες προς Φαραώ τον βασιλέα της Αιγύπτου, διά να εξαγάγωσι τους υιούς Ισραήλ εξ Αιγύπτου· αυτοί, ο Μωϋσής και ο Ααρών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Καθ\' ην δε ημέραν ελάλησε Κύριος προς τον Μωϋσήν εν τη γη της Αιγύπτου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'είπε Κύριος προς τον Μωϋσήν, λέγων, Εγώ είμαι ο Κύριος· λάλησον προς Φαραώ, τον βασιλέα της Αιγύπτου, πάντα όσα λέγω προς σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Και είπεν ο Μωϋσής ενώπιον του Κυρίου, Ιδού, εγώ είμαι απερίτμητος τα χείλη· και πως θέλει μου εισακούσει ο Φαραώ;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Ιδέ, εγώ σε κατέστησα Θεόν εις τον Φαραώ· και Ααρών ο αδελφός σου θέλει είσθαι προφήτης σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'συ θέλεις λαλήσει πάντα όσα σε προστάζω· ο δε Ααρών ο αδελφός σου θέλει λαλήσει προς τον Φαραώ, διά να εξαποστείλη τους υιούς Ισραήλ εκ της γης αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'εγώ δε θέλω σκληρύνει την καρδίαν του Φαραώ και θέλω πληθύνει τα σημείά μου και τα θαυμάσιά μου εν τη γη της Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'πλην ο Φαραώ δεν θέλει σας υπακούσει και θέλω επιβάλει την χείρα μου επί την Αίγυπτον και θέλω εξαγάγει τα στρατεύματά μου, τον λαόν μου, τους υιούς Ισραήλ, εκ γης Αιγύπτου με κρίσεις μεγάλας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'και θέλουσι γνωρίσει οι Αιγύπτιοι ότι εγώ είμαι ο Κύριος, όταν εκτείνω την χείρα μου επί την Αίγυπτον και εξαγάγω τους υιούς Ισραήλ εκ μέσου αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Έκαμον δε ο Μωϋσής και ο Ααρών καθώς προσέταξεν εις αυτούς ο Κύριος· ούτως έκαμον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Ήτο δε ο Μωϋσής ηλικίας ογδοήκοντα ετών, ο δε Ααρών ογδοήκοντα τριών ετών, ότε ελάλησαν προς τον Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Και είπε Κύριος προς τον Μωϋσήν, και προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Όταν σας είπη ο Φαραώ, λέγων, Δείξατε σεις θαύμα· τότε θέλεις ειπεί προς τον Ααρών, Λάβε την ράβδον σου και ρίψον έμπροσθεν του Φαραώ· και θέλει γείνει όφις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Εισήλθον λοιπόν ο Μωϋσής και ο Ααρών προς τον Φαραώ, και έκαμον ούτως ως προσέταξεν ο Κύριος· και έρριψεν ο Ααρών την ράβδον αυτού έμπροσθεν του Φαραώ και έμπροσθεν των δούλων αυτού, και έγεινεν όφις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Εκάλεσε δε και ο Φαραώ τους σοφούς και τους μάγους· και οι μάγοι της Αιγύπτου έκαμον και αυτοί ωσαύτως με τας επωδάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Διότι έρριψαν έκαστος την ράβδον αυτού, και έγειναν όφεις· η ράβδος όμως του Ααρών κατέπιε τας ράβδους εκείνων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Και εσκληρύνθη η καρδία του Φαραώ και δεν εισήκουσεν εις αυτούς, καθώς ελάλησεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Και είπε Κύριος προς τον Μωϋσήν, Εσκληρύνθη η καρδία του Φαραώ, ώστε να μη εξαποστείλη τον λαόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'ύπαγε προς τον Φαραώ το πρωΐ· ιδού, εξέρχεται εις το ύδωρ· και θέλεις σταθή παρά το χείλος του ποταμού, διά να συναντήσης αυτόν· και την ράβδον, την μεταβληθείσαν εις όφιν, θέλεις κρατεί εις την χείρα σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'και θέλεις ειπεί προς αυτόν· Κύριος ο Θεός των Εβραίων με απέστειλε προς σε, λέγων, Εξαπόστειλον τον λαόν μου, διά να με λατρεύση εν τη ερήμω· αλλ ιδού, δεν εισήκουσας έως του νύν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'ούτω λέγει Κύριος· Με τούτο θέλεις γνωρίσει ότι εγώ είμαι ο Κύριος· ιδού, με την ράβδον την εν τη χειρί μου θέλω κτυπήσει επί τα ύδατα του ποταμού και θέλουσι μεταβληθή εις αίμα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'και τα οψάρια τα εν τω ποταμώ θέλουσι τελευτήσει, και ο ποταμός θέλει βρωμήσει, και οι Αιγύπτιοι θέλουσιν αηδιάσει να πίωσιν ύδωρ εκ του ποταμού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Και είπε Κύριος προς τον Μωϋσήν, Ειπέ προς τον Ααρών, Λάβε την ράβδον σου και έκτεινον την χείρα σου επί τα ύδατα της Αιγύπτου, επί τους ρύακας αυτών, επί τους ποταμούς αυτών, επί τας λίμνας αυτών, και επί πάσαν συναγωγήν ύδατος αυτών, και θέλουσι γείνει αίμα· και θέλει είσθαι αίμα καθ\' όλην την γην της Αιγύπτου και εις τα ξύλινα και πέτρινα αγγεία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Και έκαμον ούτως ο Μωϋσής και ο Ααρών καθώς προσέταξεν ο Κύριος· και υψώσας ο Ααρών την ράβδον, εκτύπησε τα ύδατα του ποταμού ενώπιον του Φαραώ και ενώπιον των θεραπόντων αυτού· και μετεβλήθησαν εις αίμα πάντα τα ύδατα του ποταμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Και τα οψάρια τα εν τω ποταμώ ετελεύτησαν, και ο ποταμός εβρώμησεν, ώστε οι Αιγύπτιοι δεν ηδύναντο να πίωσιν ύδωρ εκ του ποταμού· και ήτο αίμα καθ\' όλην την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Έκαμον δε το όμοιον και οι μάγοι της Αιγύπτου με τας επωδάς αυτών· και εσκληρύνθη η καρδία του Φαραώ και δεν εισήκουσεν εις αυτούς, καθώς είπεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Και επιστρέψας ο Φαραώ, ήλθεν εις τον οίκον αυτού, και δεν επέστησε την καρδίαν αυτού ουδέ εις τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Πάντες δε οι Αιγύπτιοι έσκαπτον πέριξ του ποταμού διά να πίωσιν ύδωρ, διότι δεν ηδύναντο να πίωσιν εκ του ύδατος του ποταμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Και συνεπληρώθησαν επτά ημέραι, αφού ο Κύριος εκτύπησε τον ποταμόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Ύπαγε προς τον Φαραώ, και ειπέ προς αυτόν, ούτω λέγει Κύριος, Εξαπόστειλον τον λαόν μου διά να με λατρεύση·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'και αν δεν θέλης να εξαποστείλης αυτόν, ιδού, εγώ θέλω κτυπήσει πάντα τα όριά σου με βατράχους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'και ο ποταμός θέλει εξεμέσει βατράχους, οίτινες αναβαίνοντες θέλουσιν εισέλθει εις τον οίκόν σου και εις τον κοιτώνά σου και επί της κλίνης σου και εις τας οικίας των θεραπόντων σου και επί τον λαόν σου και εις τους κλιβάνους σου και εις τας σκάφας σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'και επί σε και επί τον λαόν σου και επί πάντας τους θεράποντάς σου θέλουσιν αναβή οι βάτραχοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Είπε δε Κύριος προς τον Μωϋσήν, Ειπέ προς τον Ααρών, Έκτεινον την χείρα σου με την ράβδον σου επί τους ρύακας, επί τους ποταμούς και επί τας λίμνας και ανάγαγε τους βατράχους επί την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Και εξέτεινεν ο Ααρών την χείρα αυτού επί τα ύδατα της Αιγύπτου· και ανέβησαν οι βάτραχοι και εκάλυψαν την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Και έκαμον ομοίως οι μάγοι με τας επωδάς αυτών και ανήγαγον τους βατράχους επί την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Τότε εκάλεσεν ο Φαραώ τον Μωϋσήν και τον Ααρών και είπε, Δεήθητε του Κυρίου να σηκώση τους βατράχους απ\' εμού και από του λαού μου· και θέλω εξαποστείλει τον λαόν διά να θυσιάσωσιν εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Και είπεν ο Μωϋσής προς τον Φαραώ, Διόρισον εις εμέ, πότε να δεηθώ υπέρ σου και υπέρ των θεραπόντων σου και υπέρ του λαού σου· διά να εξαλείψη τους βατράχους από σου, και από των οικιών σου, και μόνον εν τω ποταμώ να μείνωσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Ο δε είπεν, Αύριον. Και είπε, Θέλει γείνει κατά τον λόγον σου· διά να γνωρίσης ότι δεν είναι ουδείς ως ο Κύριος ο Θεός ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'και θέλουσι σηκωθή οι βάτραχοι από σου και από των οικιών σου και από των θεραπόντων σου και από του λαού σου· μόνον εν τω ποταμώ θέλουσι μείνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Τότε εξήλθον ο Μωϋσής και ο Ααρών από του Φαραώ· και εβόησεν ο Μωϋσής προς τον Κύριον περί των βατράχων, τους οποίους έφερεν επί τον Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Και έκαμεν ο Κύριος κατά τον λόγον του Μωϋσέως· και ετελεύτησαν οι βάτραχοι εκ των οικιών, εκ των επαύλεων και εκ των αγρών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Και συνήγαγον αυτούς σωρούς, και εβρώμησεν η γη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Ιδών δε ο Φαραώ ότι έγεινεν αναψυχή, εσκλήρυνε την καρδίαν αυτού, και δεν εισήκουσεν εις αυτούς, καθώς ελάλησεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Και είπε Κύριος προς τον Μωϋσήν, Ειπέ προς τον Ααρών, Έκτεινον την ράβδον σου και κτύπησον το χώμα της γης, διά να γείνη σκνίπες καθ\' όλην την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Και έκαμον ούτω· διότι εξέτεινεν ο Ααρών την χείρα αυτού με την ράβδον αυτού, και εκτύπησε το χώμα της γης, και έγεινε σκνίπες εις τους ανθρώπους και εις τα κτήνη· όλον το χώμα της γης έγεινε σκνίπες καθ\' όλην την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Και έκαμον ομοίως οι μάγοι με τας επωδάς αυτών διά να εκβάλωσι σκνίπας· πλην δεν ηδυνήθησαν· οι σκνίπες λοιπόν ήσαν επί τους ανθρώπους και επί τα κτήνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Τότε είπον οι μάγοι προς τον Φαραώ, Δάκτυλος Θεού είναι τούτο. Η καρδία όμως του Φαραώ εσκληρύνθη και δεν εισήκουσεν εις αυτούς, καθώς ελάλησεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Και είπε Κύριος προς τον Μωϋσήν, Σηκώθητι ενωρίς το πρωΐ και στάθητι ενώπιον του Φαραώ· ιδού, εξέρχεται εις το ύδωρ· και ειπέ προς αυτόν, Ούτω λέγει Κύριος· Εξαπόστειλον τον λαόν μου διά να με λατρεύση·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'διότι εάν δεν εξαποστείλης τον λαόν μου, ιδού, θέλω στείλει επί σε και επί τους θεράποντάς σου και επί τον λαόν σου και επί τας οικίας σου κυνόμυιαν, και αι οικίαι των Αιγυπτίων και η γη έτι επί της οποίας κατοικούσι θέλουσι γεμίσει από κυνόμυιαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'θέλω όμως εξαιρέσει εν εκείνη τη ημέρα την γην Γεσέν, εν ή κατοικεί ο λαός μου, ώστε να μη ήναι εκεί παντελώς κυνόμυια· διά να γνωρίσης ότι εγώ είμαι ο Κύριος εν τω μέσω της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'και θέλω βάλει διαφοράν μεταξύ του λαού μου και του λαού σου· αύριον θέλει γείνει το σημείον τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Και έκαμε Κύριος ούτω· και ήλθε κυνόμυια πλήθος εις την οικίαν του Φαραώ και εις τας οικίας των θεραπόντων αυτού και εις όλην την γην της Αιγύπτου· η γη διεφθάρη εκ του πλήθους της κυνομυίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Και εκάλεσεν ο Φαραώ τον Μωϋσήν και τον Ααρών και είπεν, Υπάγετε, κάμετε θυσίαν εις τον Θεόν σας εν ταύτη τη γη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Είπε δε ο Μωϋσής, Δεν αρμόζει να γείνη ούτω· διότι ημείς θυσιάζομεν εις Κύριον τον Θεόν ημών θυσίας, τας οποίας οι Αιγύπτιοι βδελύττονται· ιδού, εάν ημείς θυσιάσωμεν θυσίας, τας οποίας οι Αιγύπτιοι βδελύττονται, έμπροσθεν των οφθαλμών αυτών, δεν θέλουσι μας λιθοβολήσει;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'θέλομεν υπάγει οδόν τριών ημερών εις την έρημον και θέλομεν θυσιάσει εις Κύριον τον Θεόν ημών, καθώς είπε προς ημάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Τότε είπεν ο Φαραώ, Εγώ θέλω σας εξαποστείλει, διά να θυσιάσητε εις Κύριον τον Θεόν σας εν τη ερήμω· μόνον να μη υπάγητε πολύ μακράν· δεήθητε υπέρ εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Και είπεν ο Μωϋσής, Ιδού, εγώ εξέρχομαι από σου και θέλω δεηθή του Κυρίου, ώστε η κυνόμυια να σηκωθή αύριον από του Φαραώ, από των θεραπόντων αυτού και από του λαού αυτού· πλην ας μη εξακολουθή ο Φαραώ να απατά ημάς, μη εξαποστέλλων τον λαόν, διά να θυσιάση εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Τότε εξήλθεν ο Μωϋσής από του Φαραώ και εδεήθη του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Και έκαμε Κύριος κατά τον λόγον του Μωϋσέως· και εσήκωσε την κυνόμυιαν από του Φαραώ, από των θεραπόντων αυτού και από του λαού αυτού· δεν έμεινεν ουδέ μία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Πλην ο Φαραώ και ταύτην την φοράν εσκλήρυνε την καρδίαν αυτού και δεν εξαπέστειλε τον λαόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Ύπαγε προς τον Φαραώ και ειπέ προς αυτόν, Ούτω λέγει Κύριος ο Θεός των Εβραίων. Εξαπόστειλον τον λαόν μου, διά να με λατρεύση·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'διότι, εάν δεν θέλης να εξαποστείλης και εάν έτι κρατής αυτούς,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'ιδού, η χειρ του Κυρίου θέλει είσθαι επί τα κτήνη σου τα εν τω αγρώ, επί τους ίππους, επί τους όνους, επί τας καμήλους, επί τους βόας, και επί τα πρόβατα· θανατικόν βαρύ σφόδρα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'και θέλει κάμει ο Κύριος διάκρισιν μεταξύ των κτηνών του Ισραήλ και των κτηνών των Αιγυπτίων· και εκ πάντων των ανηκόντων εις τους υιούς Ισραήλ δεν θέλει αποθάνει ουδέ εν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Και διώρισεν ο Κύριος καιρόν, λέγων, Αύριον θέλει κάμει ο Κύριος το πράγμα τούτο εν τη γη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Και έκαμεν ο Κύριος το πράγμα τούτο την επαύριον, και απέθανον πάντα τα κτήνη των Αιγυπτίων· εκ δε των κτηνών των υιών Ισραήλ δεν απέθανεν ουδέ εν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Και απέστειλεν ο Φαραώ να ίδωσι, και ιδού, εκ των κτηνών του Ισραήλ δεν απέθανεν ουδέ έν· και εσκληρύνθη η καρδία του Φαραώ και δεν εξαπέστειλε τον λαόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Τότε είπεν ο Κύριος προς τον Μωϋσήν και προς τον Ααρών, Γεμίσατε τας χείρας σας από στάκτην καμίνου και ας σκορπίση αυτήν ο Μωϋσής προς τον ουρανόν έμπροσθεν του Φαραώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'και θέλει γείνει λεπτός κονιορτός εφ\' όλην την γην της Αιγύπτου· και θέλει γείνει επί τους ανθρώπους και επί τα κτήνη καύσις αναδιδούσα ελκώδη εξανθήματα καθ\' όλην την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Έλαβον λοιπόν την στάκτην της καμίνου και εστάθησαν ενώπιον του Φαραώ· και εσκόρπισεν αυτήν ο Μωϋσής προς τον ουρανόν, και έγεινε καύσις αναδιδούσα ελκώδη εξανθήματα επί τους ανθρώπους και επί τα κτήνη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'και δεν ηδύναντο οι μάγοι να σταθώσιν έμπροσθεν του Μωϋσέως εξ αιτίας της καύσεως· διότι η καύσις ήτο επί τους μάγους και επί πάντας τους Αιγυπτίους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Εσκλήρυνε δε Κύριος την καρδίαν του Φαραώ, και δεν εισήκουσεν εις αυτούς, καθώς ελάλησε Κύριος προς τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Και είπε Κύριος προς τον Μωϋσήν, Σηκώθητι ενωρίς το πρωΐ και παραστάθητι έμπροσθεν του Φαραώ και ειπέ προς αυτόν, ούτω λέγει Κύριος ο Θεός των Εβραίων· Εξαπόστειλον τον λαόν μου, διά να με λατρεύση·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'διότι ταύτην την φοράν εγώ εξαποστέλλω πάσας μου τας πληγάς επί την καρδίαν σου και επί τους θεράποντάς σου και επί τον λαόν σου· διά να γνωρίσης ότι δεν είναι ουδείς όμοιός μου εν πάση τη γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'επειδή τώρα θέλω εκτείνει την χείρα μου και θέλω πατάξει σε και τον λαόν σου με θανατικόν, και θέλεις απολεσθή από της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'και διά τούτο βεβαίως σε διετήρησα, διά να δείξω εν σοι την δύναμίν μου και να κηρυχθή το όνομά μου εν πάση τη γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'ότι επεγείρεσαι κατά του λαού μου, διά να μη εξαποστείλης αυτόν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'ιδού, αύριον περί την ώραν ταύτην θέλω βρέξει χάλαζαν βαρείαν σφόδρα, οποία δεν έγεινε ποτέ εν τη Αιγύπτω αφ\' ης ημέρας εθεμελιώθη μέχρι του νύν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'τώρα λοιπόν απόστειλον να συνάξης τα κτήνη σου και πάντα όσα έχεις εν τοις αγροίς· διότι πας άνθρωπος και ζώον, το οποίον ευρεθή εν τοις αγροίς και δεν φερθή εις οικίαν, και η χάλαζα καταβή επ\' αυτά, θέλουσιν αποθάνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Όστις εκ των θεραπόντων του Φαραώ εφοβήθη τον λόγον του Κυρίου, συνήγαγε ταχέως εις τας οικίας τους δούλους αυτού και τα κτήνη αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'όστις όμως δεν επρόσεξεν εις τον λόγον του Κυρίου, αφήκε τους δούλους αυτού και τα κτήνη αυτού εν τοις αγροίς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Και είπε Κύριος προς τον Μωϋσήν, Έκτεινον την χείρα σου προς τον ουρανόν, και θέλει γείνει χάλαζα εφ\' όλην την γην της Αιγύπτου, επί ανθρώπους και επί κτήνη και επί πάντα χόρτον του αγρού εν τη γη της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Και εξέτεινεν ο Μωϋσής την ράβδον αυτού προς τον ουρανόν, και ο Κύριος έπεμψε βροντάς και χάλαζαν και διέτρεχε το πυρ επί την γήν· και ο Κύριος έβρεξε χάλαζαν επί την γην της Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'ώστε ήτο χάλαζα και πυρ φλογίζον εν τη χαλάζη, χάλαζα βαρεία, οποία δεν έγεινε ποτέ εφ\' όλην την γην της Αιγύπτου, αφού κατεστάθη έθνος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Και επάταξεν η χάλαζα εν πάση τη γη της ιγύπτου παν το εν τοις αγροίς, από ανθρώπου έως κτήνους· και πάντα τον χόρτον του αγρού επάταξεν η χάλαζα και πάντα τα δένδρα του αγρού συνέτριψε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Μόνον εν τη γη Γεσέν, όπου ήσαν οι υιοί Ισραήλ, δεν έγεινε χάλαζα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Τότε ο Φαραώ αποστείλας εκάλεσε τον Μωϋσήν και τον Ααρών και είπε προς αυτούς, Ταύτην την φοράν ημάρτησα· ο Κύριος είναι δίκαιος· εγώ δε και ο λαός μου είμεθα ασεβείς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'δεήθητε του Κυρίου, ώστε να παύσωσι του να γίνωνται βρονταί Θεού και χάλαζα· και εγώ θέλω σας εξαποστείλει, και δεν θέλετε μείνει πλέον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Και είπεν ο Μωϋσής προς αυτόν, καθώς εξέλθω εκ της πόλεως, θέλω εκτείνει τας χείρας μου προς τον Κύριον· αι βρονταί θέλουσι παύσει και χάλαζα δεν θέλει είσθαι πλέον· διά να γνωρίσης ότι του Κυρίου είναι η γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'πλην συ και οι θεράποντές σου, εξεύρω ότι ακόμη δεν θέλετε φοβηθή από προσώπου Κυρίου του Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Εκτυπήθησαν δε το λινάριον και η κριθή· διότι η κριθή ήτο σταχυωμένη και το λινάριον καλαμωμένον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'ο σίτος όμως και η ζέα δεν εκτυπήθησαν, διότι ήσαν όψιμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Και εξήλθεν ο Μωϋσής έξω της πόλεως από του Φαραώ και εξέτεινε τας χείρας αυτού προς τον Κύριον· και αι βρονταί και η χάλαζα έπαυσαν και βροχή δεν έσταξε πλέον επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Και ότε είδεν ο Φαραώ ότι έπαυσεν η βροχή και η χάλαζα και αι βρονταί, εξηκολούθησε να αμαρτάνη και εσκλήρυνε την καρδίαν αυτού, αυτός και οι θεράποντες αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Και εσκληρύνθη η καρδία του Φαραώ και δεν εξαπέστειλε τους υιούς Ισραήλ, καθώς ελάλησε Κύριος διά του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Είσελθε προς τον Φαραώ· διότι εγώ εσκλήρυνα την καρδίαν αυτού και την καρδίαν των θεραπόντων αυτού, διά να δείξω τα σημείά μου ταύτα εν μέσω αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'και διά να διηγήσαι εις τα ώτα του υιού σου και εις τον υιόν του υιού σου, τα όσα έπραξα εις τους Αιγυπτίους και τα σημείά μου όσα έκαμα εν μέσω αυτών, και να γνωρίσητε ότι εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Εισήλθον δε ο Μωϋσής και ο Ααρών προς τον Φαραώ και είπον προς αυτόν, Ούτω λέγει Κύριος ο Θεός των Εβραίων· Έως πότε αρνείσαι να ταπεινωθής έμπροσθέν μου; εξαπόστειλον τον λαόν μου διά να με λατρεύση·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'διότι εάν δεν θέλης να εξαποστείλης τον λαόν μου, ιδού, αύριον θέλω φέρει ακρίδα επί τα όριά σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'και θέλει σκεπάσει το πρόσωπον της γης, ώστε να μη δύναταί τις να ίδη την γήν· και θέλει καταφάγει το επίλοιπον το διασωθέν, όσον αφήκεν εις εσάς η χάλαζα, και θέλει καταφάγει πάντα τα δένδρα τα φυόμενα εις εσάς εκ των αγρών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'και θέλουσι γεμισθή αι οικίαι σου και αι οικίαι πάντων των θεραπόντων σου και αι οικίαι πάντων των Αιγυπτίων· το οποίον δεν είδον οι πατέρες σου ούτε οι πατέρες των πατέρων σου, αφ\' ης ημέρας υπήρξαν επί της γης μέχρι της σήμερον. Έπειτα στραφείς εξήλθεν από του Φαραώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Και είπον οι θεράποντες του Φαραώ προς αυτόν, Έως πότε ούτος θέλει είσθαι πρόσκομμα εις ημάς; εξαπόστειλον τους ανθρώπους, διά να λατρεύσωσι Κύριον τον Θεόν αυτών· ακόμη δεν εξεύρεις ότι ηφανίσθη η Αίγυπτος;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Τότε έφεραν πάλιν τον Μωϋσήν και τον Ααρών προς τον Φαραώ· και είπε προς αυτούς, Υπάγετε, λατρεύσατε τον Κύριον τον Θεόν σας· αλλά ποίοι και ποίοι θέλουσιν υπάγει;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Και είπεν ο Μωϋσής· μετά των νέων ημών και μετά των γερόντων ημών θέλομεν υπάγει, μετά των υιών ημών και μετά των θυγατέρων ημών, μετά των προβάτων ημών και μετά των βοών ημών θέλομεν υπάγει διότι έχομεν εορτήν εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Ο δε είπε προς αυτούς, Ούτως ας ήναι ο Κύριος μεθ\' υμών, καθώς εγώ θέλω σας εξαποστείλει μετά των τέκνων σας· ίδετε· διότι κακόν πρόκειται έμπροσθέν σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'ουχί ούτως, οι άνδρες υπάγετε τώρα, και λατρεύσατε τον Κύριον, διότι τούτο ζητείτε. Και εξέβαλεν αυτούς ο Φαραώ απ\' έμπροσθεν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Είπε δε Κύριος προς τον Μωϋσήν, Έκτεινον την χείρα σου επί την γην της Αιγύπτου διά την ακρίδα, διά να αναβή επί την γην της Αιγύπτου και να καταφάγη πάντα τον χόρτον της γης, παν ό,τι η χάλαζα αφήκε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Και εξέτεινεν ο Μωϋσής την ράβδον αυτού επί την γην της Αίγυπτον, και ο Κύριος επέφερεν επί την γην όλην την ημέραν εκείνην και όλην την νύκτα ανατολικόν άνεμον· και το πρωΐ ο άνεμος ο ανατολικός έφερε την ακρίδα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Και ανέβη η ακρίς εφ\' όλην την γην της Αιγύπτου και εκάθισεν επί πάντα τα όρια της Αιγύπτου, πολλή σφόδρα· πρότερον αυτής δεν υπήρξε τοιαύτη ακρίς, ουδέ θέλει υπάρξει τοιαύτη μετ\' αυτήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'και εκάλυψε το πρόσωπον όλης της γης και εσκοτίσθη η γή· και κατέφαγε πάντα τον χόρτον της γης και πάντας τους καρπούς των δένδρων, όσους η χάλαζα αφήκε, και δεν έμεινεν ουδέν χλωρόν ούτε εις τα δένδρα ούτε εις τα χόρτα του αγρού καθ\' όλην την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Τότε έσπευσεν ο Φαραώ να καλέση τον Μωϋσήν και τον Ααρών και είπεν, Ημάρτησα εις Κύριον τον Θεόν σας και εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'πλην τώρα συγχωρήσατέ μοι, παρακαλώ, το αμάρτημά μου, μόνον ταύτην την φοράν, και δεήθητε Κυρίου του Θεού υμών διά να σηκώση απ\' εμού τον θάνατον τούτον μόνον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Και εξήλθεν ο Μωϋσής από του Φαραώ και εδεήθη του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Και μετέφερεν ο Κύριος σφοδρότατον δυτικόν άνεμον, όστις εσήκωσε την ακρίδα και έρριψεν αυτήν εις την Ερυθράν θάλασσαν· δεν έμεινεν ουδεμία ακρίς επί πάντα τα όρια της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Πλην ο Κύριος εσκλήρυνε την καρδίαν του Φαραώ, και δεν εξαπέστειλε τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Και είπε Κύριος προς τον Μωϋσήν, Έκτεινον την χείρα σου προς τον ουρανόν και θέλει γείνει σκότος επί την γην της Αιγύπτου και σκότος ψηλαφητόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Και εξέτεινεν ο Μωϋσής την χείρα αυτού προς τον ουρανόν, και έγεινε σκότος πυκνόν εφ\' όλην την γην της Αιγύπτου τρεις ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Δεν έβλεπεν ο εις τον άλλον· ουδέ εσηκώθη τις από του τόπου αυτού τρεις ημέρας· εις πάντας δε τους υιούς Ισραήλ ήτο φως εν ταις κατοικίαις αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Τότε εκάλεσεν ο Φαραώ τον Μωϋσήν και είπεν, Υπάγετε, λατρεύσατε τον Κύριον· μόνον τα πρόβατά σας και οι βόες σας ας μείνωσι και τα τέκνα σας ας έλθωσι μεθ\' υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Και είπεν ο Μωϋσής, Αλλά και θυσίας και ολοκαυτώματα πρέπει συ να μας δώσης, διά να θυσιάσωμεν εις Κύριον τον Θεόν ημών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'τα κτήνη ημών ομοίως θέλουσιν υπάγει μεθ\' ημών· δεν θέλει μείνει οπίσω ουδέ ονύχιον· διότι εκ τούτων πρέπει να λάβωμεν, διά να λατρεύσωμεν Κύριον τον Θεόν ημών· και ημείς δεν εξεύρομεν με τι έχομεν να λατρεύσωμεν τον Κύριον, εωσού να φθάσωμεν εκεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Αλλ\' ο Κύριος εσκλήρυνε την καρδίαν του Φαραώ, και δεν ηθέλησε να εξαποστείλη αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Και είπεν ο Φαραώ προς αυτόν, Φύγε απ\' εμού· πρόσεχε εις σεαυτόν, να μη ίδης πλέον το πρόσωπόν μου· διότι εις οποίαν ημέραν ίδης το πρόσωπόν μου, θέλεις αποθάνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Και είπεν ο Μωϋσής, Καθώς είπας, δεν θέλω ιδεί πλέον το πρόσωπόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Είπε δε Κύριος προς τον Μωϋσήν, Έτι μίαν πληγήν θέλω φέρει επί τον Φαραώ και επί την Αίγυπτον· μετά ταύτα θέλει σας εξαποστείλει εντεύθεν· εξαποστέλλων υμάς θέλει βεβαίως και διώξει υμάς ολοκλήρως εντεύθεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'λάλησον τώρα εις τα ώτα του λαού, και ας ζητήση πας ανήρ παρά του γείτονος αυτού, και πάσα γυνή παρά της γείτονος αυτής, σκεύη αργυρά, και σκεύη χρυσά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Και έδωκεν ο Κύριος χάριν εις τον λαόν ενώπιον των Αιγυπτίων· έτι δε ο άνθρωπος ο Μωϋσής ήτο μέγας σφόδρα εν τη γη της Αιγύπτου έμπροσθεν των θεραπόντων του Φαραώ και έμπροσθεν του λαού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Και είπεν ο Μωϋσής, Ούτω λέγει ο Κύριος· Περί το μεσονύκτιον εγώ θέλω εξέλθει εις το μέσον της Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'και παν πρωτότοκον εν τη γη της Αιγύπτου θέλει αποθάνει, από του πρωτοτόκου του Φαραώ, όστις κάθηται επί του θρόνου αυτού, έως του πρωτοτόκου της δούλης, ήτις δουλεύει εν τω μύλω, και παν πρωτότοκον των κτηνών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'και θέλει είσθαι καθ\' όλην την γην της Αιγύπτου κραυγή μεγάλη, οποία ποτέ δεν έγεινεν, ουδέ μετά ταύτα θέλει γείνει τοιαύτη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'επί πάντας όμως τους υιούς Ισραήλ δεν θέλει κινήσει σκύλος την γλώσσαν αυτού, από ανθρώπου έως κτήνους· διά να γνωρίσητε ότι ο Κύριος έκαμε διάκρισιν μεταξύ των Αιγυπτίων και του Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'και πάντες ούτοι οι δούλοί σου θέλουσι καταβή προς εμέ και θέλουσι προσπέσει έμπροσθέν μου λέγοντες, Έξελθε συ και πας ο λαός ο ακολουθών σε· και μετά ταύτα θέλω εξέλθει. Και εξήλθεν ο Μωϋσής από του Φαραώ μετά θυμού μεγάλου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Και είπε Κύριος προς τον Μωϋσήν, Δεν θέλει σας εισακούσει ο Φαραώ, διά να πληθυνθώσι τα θαυμάσιά μου εν τη γη της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Ο Μωϋσής δε και ο Ααρών έκαμον πάντα τα θαυμάσια ταύτα ενώπιον του Φαραώ· ο δε Κύριος εσκλήρυνε την καρδίαν του Φαραώ, και δεν εξαπέστειλε τους υιούς Ισραήλ εκ της γης αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Και είπε Κύριος προς τον Μωϋσήν και προς τον Ααρών εν τη γη της Αιγύπτου, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ο μην ούτος θέλει είσθαι εις εσάς αρχή μηνών· θέλει είσθαι εις εσάς πρώτος των μηνών του ενιαυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Λαλήσατε προς πάσαν την συναγωγήν του Ισραήλ, λέγοντες, Την δεκάτην τούτου του μηνός ας λάβωσιν εις εαυτούς έκαστος εν αρνίον κατά τους οίκους των πατριών αυτών, εν αρνίον δι\' έκαστον οίκον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Εάν όμως ήναι οι εν τω οίκω ολιγοστοί διά το αρνίον, αυτός και ο γείτων αυτού ο πλησιέστερος της οικίας αυτού ας λάβωσιν αυτό κατά τον αριθμόν των ψυχών· έκαστος θέλει συναριθμείσθαι διά το αρνίον αναλόγως με το αρκετόν εις αυτόν να φάγη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Το δε αρνίον σας θέλει είσθαι τέλειον, αρσενικόν ενιαύσιον· εκ των προβάτων ή εκ των αιγών θέλετε λάβει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Και θέλετε φυλάττει αυτό μέχρι της δεκάτης τετάρτης του αυτού μηνός· και τότε άπαν το πλήθος της συναγωγής του Ισραήλ θέλει σφάξει αυτό προς το εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Και θέλουσι λάβει εκ του αίματος και βάλει επί τους δύο παραστάτας και επί το ανώφλιον της θύρας των οικιών, όπου θέλουσι φάγει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Και θέλουσι φάγει το κρέας την νύκτα εκείνην, οπτόν εν πυρί· με άζυμα, και με χόρτα πικρά θέλουσι φάγει αυτό·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'μη φάγητε απ\' αυτού ωμόν, μηδέ βραστόν εν ύδατι, αλλά οπτόν εν πυρί· την κεφαλήν αυτού μετά των ποδών αυτού και μετά των εντοσθίων αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'και μη αφήσητε υπόλοιπον απ\' αυτού έως το πρωΐ· ό,τι δε περισσεύση απ\' αυτού έως το πρωΐ, καύσατε εν πυρί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Και ούτω θέλετε φάγει αυτό· Εζωσμένοι τας οσφύας σας, έχοντες τα υποδήματά σας εις τους πόδας σας και την ράβδον σας εις την χείρα σας· και θέλετε φάγει αυτό μετά σπουδής· είναι πάσχα του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Διότι την νύκτα ταύτην θέλω περάσει διά μέσου της γης της Αιγύπτου και θέλω πατάξει παν πρωτότοκον εν τη γη της Αιγύπτου, από ανθρώπου έως κτήνους· και θέλω κάμει κρίσεις εναντίον πάντων των θεών της Αιγύπτου. Εγώ ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Και το αίμα θέλει είσθαι εις εσάς διά σημείον επί των οικιών, εις τας οποίας κατοικείτε· και όταν ίδω το αίμα, θέλω σας παρατρέξει, και η πληγή δεν θέλει είσθαι εις εσάς διά να σας εξολοθρεύση, όταν πατάξω την γην της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Και η ημέρα αύτη θέλει είσθαι εις εσάς εις μνημόσυνον· και θέλετε εορτάζει αυτήν εορτήν εις τον Κύριον εις τας γενεάς σας· κατά νόμον παντοτεινόν θέλετε εορτάζει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Επτά ημέρας θέλετε τρώγει άζυμα· από της πρώτης ημέρας θέλετε σηκώσει το προζύμιον εκ των οικιών σας· διότι όστις φάγη ένζυμα από της πρώτης έως της εβδόμης ημέρας, η ψυχή εκείνη θέλει εξολοθρευθή εκ του Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Και εν τη πρώτη ημέρα θέλει είσθαι σύναξις αγία· και εν τη εβδόμη ημέρα σύναξις αγία θέλει είσθαι εις εσάς· ουδεμία εργασία θέλει γίνεσθαι εν αυταίς, εκτός ό,τι χρειάζεται εις έκαστον άνθρωπον διά να φάγη· τούτο μόνον θέλετε κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Θέλετε φυλάξει λοιπόν την εορτήν των αζύμων· διότι την αυτήν ταύτην ημέραν θέλω εξαγάγει τα τάγματά σας εκ της γης της Αιγύπτου· όθεν κατά νόμον παντοτεινόν θέλετε φυλάττει την ημέραν ταύτην εις τας γενεάς σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'αρχόμενοι από της δεκάτης τετάρτης ημέρας του μηνός αφ\' εσπέρας, θέλετε τρώγει άζυμα έως της εικοστής πρώτης ημέρας του μηνός την εσπέραν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'επτά ημέρας δεν θέλει ευρίσκεσθαι προζύμιον εν ταις οικίαις υμών· διότι όστις φάγη ένζυμα, η ψυχή εκείνη θέλει εξολοθρευθή εκ της συναγωγής του Ισραήλ, είτε ξένος είναι είτε αυτόχθων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'ουδέν ένζυμον θέλετε φάγει· εν πάσαις ταις κατοικίαις υμών άζυμα θέλετε τρώγει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Τότε εκάλεσεν ο Μωϋσής πάντας τους πρεσβυτέρους του Ισραήλ και είπε προς αυτούς, Εκλέξατε και λάβετε εις εαυτούς εν αρνίον, κατά τας οικογενείας σας, και θύσατε το πάσχα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'έπειτα θέλετε λάβει δέσμην υσσώπου και θέλετε εμβάψει αυτήν εις το αίμα, το οποίον θέλει είσθαι εις λεκάνην· και από του αίματος του εν τη λεκάνη θέλετε κτυπήσει το ανώφλιον και τους δύο παραστάτας των θυρών· και ουδείς από σας θέλει εξέλθει εκ της θύρας της οικίας αυτού έως το πρωΐ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'διότι ο Κύριος θέλει περάσει διά να πατάξη τους Αιγυπτίους· και όταν ίδη το αίμα επί το ανώφλιον και επί τους δύο παραστάτας, ο Κύριος θέλει παρατρέξει την θύραν, και δεν θέλει αφήσει τον εξολοθρευτήν να εισέλθη εις τας οικίας σας, διά να πατάξη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Και θέλετε φυλάξει το πράγμα τούτο ως νόμον, εις σεαυτόν και εις τους υιούς σου, έως αιώνος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Και όταν εισέλθητε εις την γην, την οποίαν ο Κύριος θέλει σας δώσει καθώς ελάλησε, θέλετε φυλάξει την λατρείαν ταύτην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Και όταν σας λέγωσιν οι υιοί σας, Τι σημαίνει εις εσάς η λατρεία αύτη;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'θέλετε αποκρίνεσθαι, Τούτο είναι θυσία του πάσχα εις τον Κύριον, διότι παρέτρεξε τας οικίας των υιών Ισραήλ εν Αιγύπτω, ότε επάταξε τους Αιγυπτίους και έσωσε τας οικίας ημών. Τότε ο λαός κύψας προσεκύνησε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Και αναχωρήσαντες οι υιοί Ισραήλ, έκαμον καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν και τον Ααρών· ούτως έκαμον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Κατά δε το μεσονύκτιον ο Κύριος επάταξε παν πρωτότοκον εν τη γη της Αιγύπτου· από του πρωτοτόκου του Φαραώ όστις κάθηται επί του θρόνου αυτού, έως του πρωτοτόκου του αιχμαλώτου του εν τω δεσμωτηρίω· και πάντα τα πρωτότοκα των κτηνών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Και εσηκώθη ο Φαραώ την νύκτα, αυτός και πάντες οι θεράποντες αυτού και πάντες οι Αιγύπτιοι· και έγεινε βοή μεγάλη εν τη Αιγύπτω· διότι δεν ήτο οικία εις την οποίαν δεν υπήρχε νεκρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Και εκάλεσε τον Μωϋσήν και τον Ααρών διά νυκτός και είπε, Σηκώθητε, εξέλθετε εκ μέσου του λαού μου και σεις και οι υιοί του Ισραήλ· και υπάγετε, λατρεύσατε τον Κύριον, καθώς είπετε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'και τα ποίμνιά σας και τας αγέλας σας λάβετε, καθώς είπετε, και απέλθετε· ευλογήσατε δε και εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Και εβίαζον οι Αιγύπτιοι τον λαόν διά να εκβάλωσιν αυτόν ταχέως εκ του τόπου· διότι είπον, Ημείς πάντες αποθνήσκομεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Και εσήκωσεν ο λαός την ζύμην αυτού πριν αναβή, έχων έκαστος την σκάφην αυτού επί τους ώμους αυτού, εντετυλιγμένην εις τα φορέματα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Και έκαμον οι υιοί του Ισραήλ κατά τον λόγον του Μωϋσέως και εζήτησαν παρά των Αιγυπτίων σκεύη αργυρά και σκεύη χρυσά, και ενδύματα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'και ο Κύριος έδωκεν εις τον λαόν χάριν ενώπιον των Αιγυπτίων, και εδάνεισαν εις αυτούς όσα εζήτησαν· και εγύμνωσαν τους Αιγυπτίους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Ανεχώρησαν δε οι υιοί Ισραήλ από Ραμεσσή εις Σοκχώθ, περίπου εξακόσιαι χιλιάδες άνδρες πεζοί χωρίς των παιδίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Μετ\' αυτών συνανέβη και μέγα πλήθος σύμμικτον ανθρώπων και ποίμνια και αγέλαι, κτήνη πολλά σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Και εκ της ζύμης, την οποίαν έφεραν εξ Αιγύπτου, έψησαν εγκρυφίας αζύμους· διότι δεν ήτο προζύμιον, επειδή εδιώχθησαν εξ Αιγύπτου και δεν εδυνήθησαν να βραδύνωσιν, ουδέ εφόδιον προητοίμασαν εις εαυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Ο καιρός δε της παροικίας των υιών Ισραήλ, την οποίαν παρώκησαν εν Αιγύπτω, ήτο τετρακόσια και τριάκοντα έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Και μετά τα τετρακόσια και τριάκοντα έτη, την αυτήν εκείνην ημέραν εξήλθον πάντα τα τάγματα του Κυρίου εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Αύτη είναι νυξ, ήτις πρέπει να φυλάττηται εις τον Κύριον, διότι εξήγαγεν αυτούς εκ γης Αιγύπτου· αύτη είναι η νυξ εκείνη του Κυρίου, ήτις πρέπει να φυλάττηται παρά πάντων των υιών Ισραήλ εις τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Είπε δε Κύριος προς τον Μωϋσήν και Ααρών, Ούτος είναι ο νόμος του πάσχα· ουδείς αλλογενής θέλει φάγει απ\' αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'και έκαστος δούλος αργυρώνητος αφού περιτμηθή, τότε θέλει φάγει απ\' αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'ο ξένος δε και ο μισθωτός δεν θέλουσι φάγει απ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Εν τη αυτή οικία θέλει φαγωθή· από του κρέατος δεν θέλετε φέρει έξω της οικίας, και οστούν δεν θέλετε συντρίψει απ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Πάσα η συναγωγή του Ισραήλ θέλει κάμει τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Και εάν τις ξένος, παροικών μετά σου, θέλη να κάμη το πάσχα εις τον Κύριον, ας περιτμηθώσι πάντα τα αρσενικά αυτού, και τότε ας πλησιάση διά να κάμη αυτό· και θέλει είσθαι ως ο αυτόχθων της γής· διότι ουδείς απερίτμητος θέλει φάγει απ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ο αυτός νόμος θέλει είσθαι διά τον αυτόχθονα και διά τον ξένον τον παροικούντα μεταξύ σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Και έκαμον πάντες οι υιοί του Ισραήλ καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν και τον Ααρών· ούτως έκαμον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Και την αυτήν εκείνην ημέραν εξήγαγεν ο Κύριος τους υιούς Ισραήλ εκ γης Αιγύπτου κατά τα τάγματα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Καθιέρωσον εις εμέ παν πρωτότοκον διανοίγον πάσαν μήτραν μεταξύ των υιών Ισραήλ, από ανθρώπου έως κτήνους· ιδικόν μου είναι τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Και είπεν ο Μωϋσής προς τον λαόν, Έχετε εις την μνήμην σας την ημέραν ταύτην, καθ\' ην εξήλθετε εξ Αιγύπτου εξ οίκου δουλείας· διότι ο Κύριος διά χειρός κραταιάς εξήγαγεν υμάς εκείθεν· ουδείς θέλει φάγει ένζυμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Σήμερον εξέρχεσθε κατά τον μήνα Αβίβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Όταν λοιπόν ο Κύριος σε φέρη εις την γην των Χαναναίων και των Χετταίων και των Αμορραίων και των Ευαίων και των Ιεβουσαίων, την οποίαν ώμοσε προς τους πατέρας σου ότι θέλει σοι δώσει, γην ρέουσαν γάλα και μέλι, τότε θέλεις κάμει την λατρείαν ταύτην κατά τούτον τον μήνα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Επτά ημέρας θέλεις τρώγει άζυμα· εις δε την εβδόμην ημέραν θέλει είσθαι εορτή εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Άζυμα θέλουσι τρώγεσθαι τας επτά ημέρας· και δεν θέλει φανή παρά σοι ένζυμον ουδέ θέλει φανή παρά σοι προζύμιον καθ\' όλα τα όριά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Και κατ\' εκείνην την ημέραν θέλεις αναγγείλει προς τον υιόν σου, λέγων, Τούτο γίνεται δι\' εκείνο, το οποίον ο Κύριος έκαμεν εις εμέ, ότε εξήλθον εξ Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Και τούτο θέλει είσθαι εις σε διά σημείον επί της χειρός σου και διά ενθύμησιν μεταξύ των οφθαλμών σου, διά να ήναι ο νόμος του Κυρίου εν τω στόματί σου· διότι διά χειρός κραταιάς σε εξήγαγεν ο Κύριος εξ Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Θέλεις φυλάττει λοιπόν τον νόμον τούτον εν τω καιρώ αυτού κατ\' έτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Και όταν ο Κύριος σε φέρη εις την γην των Χαναναίων, καθώς ώμοσε προς σε και προς τους πατέρας σου, και δώση αυτήν εις σε,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'τότε θέλεις αποχωρίσει διά τον Κύριον παν το ανοίγον μήτραν και παν πρωτότοκον των ζώων σου όσα έχεις· τα αρσενικά θέλουσιν είσθαι του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Και παν πρωτότοκον όνου θέλεις εξαγοράζει με αρνίον· και αν δεν εξαγοράσης αυτό, τότε θέλεις λαιμοτομήσει αυτό· και παν πρωτότοκον ανθρώπου μεταξύ των υιών σου θέλεις εξαγοράζει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Και όταν εις το μέλλον σε ερωτήση ο υιός σου, λέγων, Τι είναι τούτο; θέλεις ειπεί προς αυτόν, Διά κραταιάς χειρός εξήγαγεν ημάς ο Κύριος εξ Αιγύπτου, εξ οίκου δουλείας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'και ότε ο Φαραώ επέμεινεν εις το να μη μας εξαποστείλη, ο Κύριος εθανάτωσε παν πρωτότοκον εν τη γη της Αιγύπτου, από πρωτοτόκου ανθρώπου έως πρωτοτόκου κτήνους· διά τούτο θυσιάζω εις τον Κύριον παν αρσενικόν το οποίον ανοίγει την μήτραν, και παν πρωτότοκον των υιών μου εξαγοράζω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Και τούτο θέλει είσθαι διά σημείον επί της χειρός σου και διά προμετωπίδιον μεταξύ των οφθαλμών σου· επειδή διά κραταιάς χειρός εξήγαγεν ημάς ο Κύριος εξ Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Ότε δε ο Φαραώ εξαπέστειλε τον λαόν, ο Θεός δεν ώδήγησεν αυτούς διά της οδού της γης των Φιλισταίων, αν και ήτο η συντομωτέρα· διότι ο Θεός είπε, Μήποτε ο λαός ιδών πόλεμον μεταμεληθή, και επιστρέψη εις Αίγυπτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Αλλ\' ο Θεός περιέφερε τον λαόν διά της οδού της ερήμου προς την Ερυθράν θάλασσαν· και ανέβησαν οι υιοί Ισραήλ εκ της γης Αιγύπτου παρατεταγμένοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Και έλαβε μεθ\' εαυτού ο Μωϋσής τα οστά του Ιωσήφ· διότι είχεν ορκίσει μεθ\' όρκου τους υιούς Ισραήλ, λέγων· Ο Θεός βεβαίως θέλει σας επισκεφθή· και θέλετε αναβιβάσει τα οστά μου εντεύθεν μεθ\' υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Και αναχωρήσαντες από Σοκχώθ, εστρατοπέδευσαν εν Εθάμ κατά τα άκρα της ερήμου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Ο δε Κύριος προεπορεύετο αυτών, την ημέραν εν στύλω νεφέλης, διά να οδηγή αυτούς εν τη οδώ, την δε νύκτα εν στύλω πυρός, διά να φέγγη εις αυτούς· ώστε να οδοιπορώσιν ημέραν και νύκτα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'δεν απεμάκρυνεν από της όψεως του λαού τον στύλον της νεφέλης την ημέραν, ούτε τον στύλον του πυρός την νύκτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Ειπέ προς τους υιούς Ισραήλ να στρέψωσι και να στρατοπεδεύσωσιν απέναντι Πι-αϊρώθ μεταξύ Μιγδώλ και της θαλάσσης, κατάντικρυ Βέελ-σεφών· κατάντικρυ τούτου θέλετε στρατοπεδεύσει πλησίον της θαλάσσης·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'διότι ο Φαραώ θέλει ειπεί περί των υιών Ισραήλ, Αυτοί πλανώνται εν τη γή· συνέκλεισεν αυτούς η έρημος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'και εγώ θέλω σκληρύνει την καρδίαν του Φαραώ, ώστε να καταδιώξη οπίσω αυτών· και θέλω δοξασθή επί τον Φαραώ και επί παν το στράτευμα αυτού· και οι Αιγύπτιοι θέλουσι γνωρίσει ότι εγώ είμαι ο Κύριος. Και έκαμον ούτω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Ανηγγέλθη δε προς τον βασιλέα της Αιγύπτου ότι έφυγεν ο λαός· και η καρδία του Φαραώ και των θεραπόντων αυτού μετεβλήθη κατά του λαού και είπον, Διά τι εκάμομεν τούτο, ώστε να εξαποστείλωμεν τον Ισραήλ και να μη μας δουλεύη πλέον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Έζευξε λοιπόν την άμαξαν αυτού και παρέλαβε τον λαόν αυτού μεθ\' εαυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'έλαβε δε εξακοσίας αμάξας εκλεκτάς, και πάσας τας αμάξας της Αιγύπτου, και αρχηγούς επί πάντων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Και εσκλήρυνε Κύριος την καρδίαν Φαραώ του βασιλέως της Αιγύπτου, και κατεδίωξεν οπίσω των υιών Ισραήλ· οι δε υιοί Ισραήλ εξήρχοντο διά χειρός υψηλής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Και κατεδίωξαν οι Αιγύπτιοι οπίσω αυτών, πάντες οι ίπποι, αι άμαξαι του Φαραώ, και οι ιππείς αυτού, και το στράτευμα αυτού· και έφθασαν αυτούς εστρατοπεδευμένους πλησίον της θαλάσσης απέναντι Πι-αϊρώθ, κατάντικρυ Βέελ-σεφών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Και ότε επλησίασεν ο Φαραώ, οι υιοί Ισραήλ ύψωσαν τους οφθαλμούς αυτών, και ιδού, οι Αιγύπτιοι ήρχοντο οπίσω αυτών· και εφοβήθησαν σφόδρα· και ανεβόησαν οι υιοί Ισραήλ προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Και είπον προς τον Μωϋσήν, Διότι δεν ήσαν μνήματα εν Αιγύπτω, εξήγαγες ημάς διά να αποθάνωμεν εν τη ερήμω; Διά τι έκαμες εις ημάς τούτο και εξήγαγες ημάς εξ Αιγύπτου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'δεν είναι ούτος ο λόγος τον οποίον σοι είπομεν εν Αιγύπτω, λέγοντες, Άφες ημάς και ας δουλεύωμεν τους Αιγυπτίους; διότι καλήτερον ήτο εις ημάς να δουλεύωμεν τους Αιγυπτίους, παρά να αποθάνωμεν εν τη ερήμω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Και είπεν ο Μωϋσής προς τον λαόν, Μη φοβείσθε· σταθήτε και βλέπετε την σωτήριαν του Κυρίου, την οποίαν θέλει κάμει εις εσάς σήμερον· διότι τους Αιγυπτίους, τους οποίους είδετε σήμερον, δεν θέλετε ιδεί αυτούς πλέον εις τον αιώνα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'ο Κύριος θέλει πολεμήσει διά σάς· σεις δε θέλετε μένει ήσυχοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Και είπε Κύριος προς τον Μωϋσήν, Τι βοάς προς εμέ; ειπέ προς τους υιούς Ισραήλ να κινήσωσι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'συ δε ύψωσον την ράβδον σου και έκτεινον την χείρα σου επί την θάλασσαν και σχίσον αυτήν, και ας διέλθωσιν οι υιοί Ισραήλ διά ξηράς εν μέσω της θαλάσσης·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'και εγώ, ιδού, θέλω σκληρύνει την καρδίαν των Αιγυπτίων, και θέλουσιν εμβή κατόπιν αυτών· και θέλω δοξασθή επί τον Φαραώ και επί παν το στράτευμα αυτού, επί τας αμάξας αυτού και επί τους ιππείς αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'και θέλουσι γνωρίσει οι Αιγύπτιοι ότι εγώ είμαι ο Κύριος, όταν δοξασθώ επί τον Φαραώ, επί τας αμάξας αυτού και επί τους ιππείς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Τότε ο άγγελος του Θεού, ο προπορευόμενος του στρατεύματος του Ισραήλ, εσηκώθη και ήλθεν οπίσω αυτών· και ο στύλος της νεφέλης εσηκώθη απ\' έμπροσθεν αυτών, και εστάθη όπισθεν αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'και ήλθε μεταξύ του στρατεύματος των Αιγυπτίων και του στρατεύματος του Ισραήλ· και εις εκείνους μεν ήτο νέφος σκοτίζον, εις τούτους δε φωτίζον την νύκτα· ώστε το εν δεν επλησίασε το άλλο καθ\' όλην την νύκτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Ο δε Μωϋσής εξέτεινε την χείρα αυτού επί την θάλασσαν· και έκαμεν ο Κύριος την θάλασσαν να συρθή όλην εκείνην την νύκτα υπό σφοδρού ανατολικού ανέμου και κατέστησε την θάλασσαν ξηράν, και τα ύδατα διεχωρίσθησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Και εισήλθον οι υιοί του Ισραήλ εις το μέσον της θαλάσσης κατά το ξηρόν, και τα ύδατα ήσαν εις αυτούς τοίχος εκ δεξιών και εξ αριστερών αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Κατεδίωξαν δε οι Αιγύπτιοι και εισήλθον κατόπιν αυτών, πάντες οι ίπποι του Φαραώ, αι άμαξαι αυτού και οι ιππείς αυτού, εν τω μέσω της θαλάσσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Και εν τη φυλακή τη πρωϊνή επέβλεψεν ο Κύριος εκ του στύλου του πυρός και της νεφέλης επί το στράτευμα των Αιγυπτίων και συνετάραξε το στράτευμα των Αιγυπτίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'και εξέβαλε τους τροχούς των αμαξών αυτών, ώστε εσύροντο δυσκόλως· και είπον οι Αιγύπτιοι, Ας φύγωμεν απ\' έμπροσθεν του Ισραήλ, διότι ο Κύριος πολεμεί τους Αιγυπτίους υπέρ αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Ο δε Κύριος είπε προς τον Μωϋσήν, Έκτεινον την χείρα σου επί την θάλασσαν, και ας επαναστρέψωσι τα ύδατα επί τους Αιγυπτίους, επί τας αμάξας αυτών και επί τους ιππείς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Και εξέτεινεν ο Μωϋσής την χείρα αυτού επί την θάλασσαν· και η θάλασσα επανέλαβε την ορμήν αυτής περί την αυγήν· οι δε Αιγύπτιοι φεύγοντες απήντησαν αυτήν· και κατέστρεψε Κύριος τους Αιγυπτίους εν τω μέσω της θαλάσσης·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'διότι τα ύδατα επαναστρέψαντα εσκέπασαν τας αμάξας και τους ιππείς, παν το στράτευμα του Φαραώ, το οποίον είχεν εμβή κατόπιν αυτών εις την θάλασσαν· δεν έμεινεν εξ αυτών ουδέ εις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Οι δε υιοί Ισραήλ επέρασαν διά ξηράς εν μέσω της θαλάσσης· και τα ύδατα ήσαν εις αυτούς τοίχος εκ δεξιών αυτών και εξ αριστερών αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Και έσωσε Κύριος εν τη ημέρα εκείνη τον Ισραήλ εκ χειρός των Αιγυπτίων· και είδεν ο Ισραήλ τους Αιγυπτίους νεκρούς επί το χείλος της θαλάσσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Και είδεν ο Ισραήλ το μέγα εκείνο έργον, το οποίον έκαμεν ο Κύριος επί τους Αιγυπτίους· και εφοβήθη ο λαός τον Κύριον, και επίστευσεν εις τον Κύριον, και εις τον Μωϋσήν τον θεράποντα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Τότε έψαλεν ο Μωϋσής και οι υιοί Ισραήλ την ωδήν ταύτην προς τον Κύριον, και είπον λέγοντες, Ας ψάλλω προς τον Κύριον· διότι εδοξάσθη ενδόξως· τον ίππον και τον αναβάτην αυτού έρριψεν εις την θάλασσαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Ο Κύριος είναι η δύναμίς μου και το άσμά μου, και εστάθη η σωτηρία μου· αυτός είναι Θεός μου και θέλω δοξάσει αυτόν· Θεός του πατρός μου, και θέλω υψώσει αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Ο Κύριος είναι δυνατός πολεμιστής· Κύριος το όνομα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Του Φαραώ τας αμάξας και το στράτευμα αυτού έρριψεν εις την θάλασσαν· και εκλεκτοί πολέμαρχοι αυτού κατεποντίσθησαν εν τη Ερυθρά θαλάσση.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Αι άβυσσοι εσκέπασαν αυτούς· ως πέτρα κατεβυθίσθησαν εις τα βάθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Η δεξιά σου, Κύριε, εδοξάσθη εις δύναμιν· η δεξιά σου, Κύριε, συνέτριψε τον εχθρόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Και με το μέγεθος της υπεροχής σου εξωλόθρευσας τους υπεναντίους σου· εξαπέστειλας την οργήν σου και κατέφαγεν αυτούς ως καλάμην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Και με την πνοήν του θυμού σου τα ύδατα επεσωρεύθησαν ομού· τα κύματα εστάθησαν ως σωρός, αι άβυσσοι έπηξαν εν τω μέσω της θαλάσσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Ο εχθρός είπε, Θέλω καταδιώξει, θέλω καταφθάσει, θέλω διαμοιρασθή τα λάφυρα· η ψυχή μου θέλει χορτασθή επ\' αυτούς· θέλω σύρει την μάχαιράν μου, η χειρ μου θέλει αφανίσει αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Εφύσησας με τον άνεμόν σου και η θάλασσα εσκέπασεν αυτούς· κατεβυθίσθησαν ως μόλυβδος εις τα φοβερά ύδατα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Τις όμοιός σου Κύριε, μεταξύ των θεών; Τις όμοιός σου, ένδοξος εις αγιότητα, θαυμαστός εις ύμνους, ενεργών τεράστια;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Εξέτεινας την δεξιάν σου, και η γη κατέπιεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Με το έλεός σου ώδήγησας τον λαόν τούτον, τον οποίον ελύτρωσας· ώδήγησας αυτόν με την δύναμίν σου προς την κατοικίαν της αγιότητός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Οι λαοί θέλουσιν ακούσει και φρίξει· πόνοι θέλουσι κατακυριεύσει τους κατοίκους της Παλαιστίνης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Τότε θέλουσιν εκπλαγή οι ηγεμόνες Εδώμ· τρόμος θέλει καταλάβει τους άρχοντας του Μωάβ· πάντες οι κάτοικοι της Χαναάν θέλουσιν αναλυθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Φόβος και τρόμος θέλει επιπέσει επ\' αυτούς· από του μεγέθους του βραχίονός σου θέλουσιν απολιθωθή, εωσού περάση ο λαός σου, Κύριε, εωσού περάση ο λαός ούτος, τον οποίον απέκτησας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Θέλεις εισαγάγει αυτούς και φυτεύσει αυτούς εις το όρος της κληρονομίας σου, τον τόπον, Κύριε, τον οποίον ητοίμασας διά κατοικίαν σου, το αγιαστήριον, Κύριε, το οποίον αι χείρες σου έστησαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Ο Κύριος θέλει βασιλεύει εις τους αιώνας των αιώνων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Διότι εισήλθον οι ίπποι του Φαραώ εις την θάλασσαν μετά των αμαξών αυτού και μετά των ιππέων αυτού, και ο Κύριος έστρεψεν επ\' αυτούς τα ύδατα της θαλάσσης· οι δε υιοί Ισραήλ επέρασαν διά ξηράς εν τω μέσω της θαλάσσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Μαριάμ δε η προφήτις, η αδελφή του Ααρών έλαβε το τύμπανον εν τη χειρί αυτής και πάσαι αι γυναίκες εξήλθον κατόπιν αυτής μετά τυμπάνων και χορών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Και η Μαριάμ ανταπεκρίνετο προς αυτούς, λέγουσα, Ψάλλετε εις τον Κύριον· διότι εδοξάσθη ενδόξως· τον ίππον και τον αναβάτην αυτού έρριψεν εις θάλασσαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Τότε εσήκωσεν ο Μωϋσής τους Ισραηλίτας από της Ερυθράς θαλάσσης, και εξήλθον εις την έρημον Σούρ· και περιεπάτουν τρεις ημέρας εν τη ερήμω και δεν εύρισκον ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Και εκείθεν ήλθον εις Μερράν· δεν ηδύναντο όμως να πίωσιν εκ των υδάτων της Μερράς, διότι ήσαν πικρά· διά τούτο και επωνομάσθη Μερρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Και εγόγγυζεν ο λαός κατά του Μωϋσέως, λέγων, Τι θέλομεν πίει;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Ο δε Μωϋσής εβόησε προς τον Κύριον· και έδειξεν εις αυτόν ο Κύριος ξύλον, το οποίον ότε έρριψεν εις τα ύδατα, τα ύδατα εγλυκάνθησαν. Εκεί έδωκεν εις αυτούς παραγγελίαν και διάταγμα, και εκεί εδοκίμασεν αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'και είπεν, Εάν ακούσης επιμελώς την φωνήν Κυρίου του Θεού σου και πράττης το αρεστόν εις τους οφθαλμούς αυτού και δώσης ακρόασιν εις τας εντολάς αυτού και φυλάξης πάντα τα προστάγματα αυτού, δεν θέλω φέρει επί σε ουδεμίαν εκ των νόσων, τας οποίας έφερα κατά των Αιγυπτίων· διότι εγώ είμαι ο Κύριος ο θεραπεύων σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Έπειτα ήλθον εις Αιλείμ, όπου ήσαν δώδεκα πηγαί υδάτων και εβδομήκοντα δένδρα φοινίκων· και εκεί εστρατοπέδευσαν πλησίον των υδάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Εσηκώθησαν δε από Αιλείμ· και ήλθον πάσα η συναγωγή των υιών Ισραήλ εις την έρημον Σιν, την μεταξύ Αιλείμ και Σινά, την δεκάτην πέμπτην ημέραν του δευτέρου μηνός αφού εξήλθον εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Και εγόγγυζε πάσα η συναγωγή των υιών Ισραήλ κατά του Μωϋσέως και κατά του Ααρών εν τη ερήμω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Και είπον προς αυτούς οι υιοί Ισραήλ, Είθε να απεθνήσκομεν υπό της χειρός του Κυρίου εν τη γη της Αιγύπτου, ότε εκαθήμεθα πλησίον των λεβήτων του κρέατος και ότε ετρώγομεν άρτον εις χορτασμόν· διότι εξηγάγετε ημάς εις την έρημον ταύτην, διά να θανατώσητε με την πείναν πάσαν την συναγωγήν ταύτην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Και είπε Κύριος προς τον Μωϋσήν, Ιδού, θέλω βρέξει εις εσάς άρτον εξ ουρανού· και θέλει εξέρχεσθαι ο λαός και συνάγει καθ\' ημέραν το αρκούν της ημέρας, διά να δοκιμάσω αυτούς, αν θέλωσι περιπατεί εις τον νόμον μου ή ουχί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'την δε έκτην ημέραν ας ετοιμάζωσιν εκείνο το οποίον ήθελον εισαγάγει, και ας ήναι διπλάσιον του όσον συνάγουσι καθ\' ημέραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Και είπον ο Μωϋσής και ο Ααρών προς πάντας τους υιούς Ισραήλ, Το εσπέρας θέλετε γνωρίσει ότι ο Κύριος εξήγαγεν υμάς εκ γης Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'και το πρωΐ θέλετε ιδεί την δόξαν του Κυρίου, διότι ήκουσε τους γογγυσμούς σας εναντίον του Κυρίου· επειδή ημείς τι είμεθα, ώστε να γογγύζητε καθ\' ημών;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Και είπεν ο Μωϋσής, Τούτο θέλει γείνει, όταν ο Κύριος δώση εις εσάς το εσπέρας κρέας να φάγητε και το πρωΐ άρτον εις χορτασμόν· διότι ήκουσε Κύριος τους γογγυσμούς σας τους οποίους γογγύζετε κατ\' αυτού· και τι είμεθα ημείς; οι γογγυσμοί σας δεν είναι καθ\' ημών, αλλά κατά του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Και είπεν ο Μωϋσής προς τον Ααρών, Ειπέ προς πάσαν την συναγωγήν των υιών Ισραήλ, Πλησιάσατε έμπροσθεν του Κυρίου· διότι ήκουσε τους γογγυσμούς σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Και ενώ ελάλει ο Ααρών προς πάσαν την συναγωγήν των υιών Ισραήλ, έστρεψαν το πρόσωπον προς την έρημον, και ιδού, η δόξα του Κυρίου εφάνη εν τη νεφέλη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ήκουσα τους γογγυσμούς των υιών Ισραήλ· λάλησον προς αυτούς, λέγων, Το εσπέρας θέλετε φάγει κρέας, και το πρωΐ θέλετε χορτασθή από άρτου, και θέλετε γνωρίσει ότι εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Και το εσπέρας ανέβησαν ορτύκια και εσκέπασαν το στρατόπεδον· και το πρωΐ καθ\' όλα τα πέριξ του στρατοπέδου ήτο στρώμα δρόσου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Και αφού το στρώμα της δρόσου ανέβη, ιδού, επί το πρόσωπον της ερήμου ήτο λεπτόν τι στρογγύλον, λεπτόν ως πάχνη επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Και ότε είδον οι υιοί Ισραήλ, είπον προς αλλήλους, Τι είναι τούτο; διότι δεν ήξευρον τι ήτο. Και ο Μωϋσής είπε προς αυτούς, Ούτος είναι ο άρτος, τον οποίον ο Κύριος σας δίδει διά να φάγητε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'ούτος είναι ο λόγος τον οποίον προσέταξεν ο Κύριος, Συνάξατε εξ αυτού έκαστος όσον χρειάζεται διά να φάγη, εν γομόρ κατά κεφαλήν, κατά τον αριθμόν των ψυχών σας· λάβετε έκαστος διά τους ομοσκήνους αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Και έκαμον ούτως οι υιοί Ισραήλ, και συνήγαγον άλλος πολύ και άλλος ολίγον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Και ότε εμέτρησαν με το γομόρ, όστις είχε συνάξει πολύ, δεν ελάμβανε πλειότερον· και όστις είχε συνάξει ολίγον, δεν ελάμβανεν ολιγώτερον· έκαστος ελάμβανεν όσον εχρειάζετο εις αυτόν διά τροφήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'είπε δε προς αυτούς ο Μωϋσής, Ας μη αφίνη εξ αυτού μηδείς υπόλοιπον έως πρωΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Πλην δεν υπήκουσαν εις τον Μωϋσήν· αλλά αφήκαν τινές υπόλοιπον εξ αυτού έως πρωΐ, και εγέννησε σκώληκας και εβρώμησε· και εθυμώθη εναντίον αυτών ο Μωϋσής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Και συνήγον αυτό καθ\' εκάστην πρωΐαν, έκαστος όσον εχρειάζετο διά τροφήν αυτού· και ότε ο ήλιος εθέρμαινε, διελύετο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Την δε έκτην ημέραν συνήγαγον τροφήν διπλασίαν, δύο γομόρ δι\' ένα· και ήλθον πάντες οι άρχοντες της συναγωγής και ανήγγειλαν τούτο προς τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Ο δε είπε προς αυτούς, Τούτο είναι το οποίον είπε Κύριος· Αύριον είναι σάββατον, ανάπαυσις αγία εις τον Κύριον· ψήσατε ό,τι έχετε να ψήσητε και βράσατε ό,τι έχετε να βράσητε· και παν το περισσεύον εναποταμιεύσατε εις εαυτούς διά να φυλάττηται έως πρωΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Και εναπεταμίευσαν αυτό έως πρωΐ, καθώς προσέταξεν ο Μωϋσής· και δεν εβρώμησεν ουδέ έγεινε σκώληξ εν αυτώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Και είπεν ο Μωϋσής, Φάγετε αυτό σήμερον· διότι σήμερον είναι σάββατον εις τον Κύριον· σήμερον δεν θέλετε ευρεί αυτό εν τη πεδιάδι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'εξ ημέρας θέλετε συνάγει αυτό· εν τη εβδόμη όμως ημέρα, τω σαββάτω, εν ταύτη δεν θέλει ευρίσκεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Τινές δε εκ του λαού εξήλθον την εβδόμην ημέραν διά να συνάξωσι, πλην δεν εύρον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Και είπε Κύριος προς τον Μωϋσήν, Έως πότε δεν θέλετε να φυλάττητε τας εντολάς μου και τους νόμους μου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'ίδετε ότι ο Κύριος έδωκεν εις εσάς το σάββατον, διά τούτο την έκτην ημέραν σας δίδει άρτον δύο ημερών· καθίσατε έκαστος εις τον τόπον αυτού· ας μη εξέρχεται μηδείς εκ του τόπου αυτού την εβδόμην ημέραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Και έκαμε κατάπαυσιν ο λαός την εβδόμην ημέραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Και εκάλεσεν ο οίκος του Ισραήλ το όνομα αυτού Μάν· ήτο δε όμοιον με σπόρον κοριάνδρου λευκόν· και η γεύσις αυτού ως πλακούντιον με μέλι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Και είπεν ο Μωϋσής, Ούτος είναι ο λόγος τον οποίον προσέταξεν ο Κύριος· Γεμίσατε εξ αυτού εν γομόρ, διά να φυλάττηται εις τας γενεάς σας, διά να βλέπωσι τον άρτον με τον οποίον έθρεψα υμάς εν τη ερήμω, αφού εξήγαγον υμάς εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Και είπεν ο Μωϋσής προς τον Ααρών, Λάβε μίαν στάμνον, και βάλε εν αυτή εν γομόρ πλήρες από μάννα, και θες αυτήν έμπροσθεν του Κυρίου, διά να φυλάττηται εις τας γενεάς σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Και έθεσεν αυτήν ο Ααρών έμπροσθεν του Μαρτυρίου, διά να φυλάττηται, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Και έτρωγον οι υιοί Ισραήλ το μάννα τεσσαράκοντα έτη, εωσού ήλθον εις γην κατοικουμένην· έτρωγον το μάννα, εωσού ήλθον εις τα όρια της γης Χαναάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Το δε γομόρ είναι το δέκατον του εφά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Και εσηκώθη πάσα η συναγωγή των υιών Ισραήλ εκ της ερήμου Σιν, ακολουθούντες τας οδοιπορείας αυτών κατά την προσταγήν του Κυρίου, και εστρατοπέδευσαν εν Ραφιδείν· όπου δεν ήτο ύδωρ διά να πίη ο λαός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Και ελοιδόρει ο λαός κατά του Μωϋσέως, λέγοντες, Δος εις ημάς ύδωρ διά να πίωμεν. Και είπε προς αυτούς ο Μωϋσής, Διά τι λοιδορείτε κατ\' εμού; διά τι πειράζετε τον Κύριον;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Και εδίψησεν ο λαός εκεί διά ύδωρ· και εγόγγυζεν ο λαός κατά του Μωϋσέως, λέγοντες, Διά τι τούτο; ανεβίβασας ημάς εξ Αιγύπτου, διά να θανατώσης ημάς και τα τέκνα ημών και τα κτήνη ημών με την δίψαν;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Και εβόησεν ο Μωϋσής προς τον Κύριον, λέγων, Τι να κάμω εις τούτον τον λαόν; ολίγον λείπει να με λιθοβολήσωσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Και είπε Κύριος προς τον Μωϋσήν, Διάβα έμπροσθεν του λαού, και λάβε μετά σεαυτού εκ των πρεσβυτέρων του Ισραήλ· και την ράβδον, σου, με την οποίαν εκτύπησας τον ποταμόν, λάβε εν τη χειρί σου και ύπαγε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'ιδού, εγώ θέλω σταθή εκεί έμπροσθέν σου επί της πέτρας εν Χωρήβ, και θέλεις κτυπήσει την πέτραν και θέλει εξέλθει ύδωρ εξ αυτής διά να πίη ο λαός. Και έκαμεν ούτως ο Μωϋσής ενώπιον των πρεσβυτέρων του Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Και εκάλεσε το όνομα του τόπου Μασσά, και Μεριβά, διά την λοιδορίαν των υιών Ιαραήλ, και διότι επείρασαν τον Κύριον, λέγοντες, Είναι ο Κύριος μεταξύ ημών ή ουχί;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Τότε ήλθεν ο Αμαλήκ και επολέμησε με τον Ισραήλ εν Ραφιδείν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Και είπεν ο Μωϋσής προς τον Ιησούν, Έκλεξον εις ημάς άνδρας και εξελθών πολέμησον με τον Αμαλήκ· αύριον εγώ θέλω σταθή επί της κορυφής του βουνού, κρατών εν τη χειρί μου την ράβδον του Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Και έκαμεν ο Ιησούς καθώς είπε προς αυτόν ο Μωϋσής και επολέμησε με τον Αμαλήκ· ο δε Μωϋσής, ο Ααρών και ο Ωρ ανέβησαν επί την κορυφήν του βουνού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Και οπότε ο Μωϋσής ύψονε την χείρα αυτού, ενίκα ο Ισραήλ· οπότε δε κατεβίβαζε την χείρα αυτού, ενίκα ο Αμαλήκ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Αι χείρες δε του Μωϋσέως ήσαν βεβαρημέναι· όθεν λαβόντες λίθον, έθεσαν υποκάτω αυτού και εκάθισεν επ\' αυτού· ο δε Ααρών και ο Ωρ, εις εκ του ενός μέρους και εις εκ του άλλου, υπεστήριζον τας χείρας αυτού· και αι χείρες αυτού έμενον εστηριγμέναι μέχρι δύσεως ηλίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Και κατέστρεψεν ο Ιησούς τον Αμαλήκ και τον λαόν αυτού, εν στόματι μαχαίρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Και είπε Κύριος προς τον Μωϋσήν, Γράψον τούτο εν βιβλίω προς μνημόσυνον, και παράδος εις τα ώτα του Ιησού· ότι θέλω εξαλείψει εξάπαντος την μνήμην του Αμαλήκ εκ της υπό τον ουρανόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Και ωκοδόμησεν εκεί ο Μωϋσής θυσιαστήριον και εκάλεσε το όνομα αυτού Ιεοβά-Νισσί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'και είπεν, Επειδή χειρ υψώθη κατά του θρόνου του Κυρίου, θέλει είσθαι πόλεμος του Κυρίου προς τον Αμαλήκ από γενεάς εις γενεάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Ήκουσε δε ο Ιοθόρ, ο ιερεύς της Μαδιάμ, ο πενθερός του Μωϋσέως, πάντα όσα έκαμεν ο Θεός εις τον Μωϋσήν και εις τον Ισραήλ τον λαόν αυτού, ότι εξήγαγεν ο Κύριος τον Ισραήλ εξ Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Και έλαβεν ο Ιοθόρ, ο πενθερός του Μωϋσέως, Σεπφώραν την γυναίκα του Μωϋσέως, την οποίαν είχε πέμψει οπίσω,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'και τους δύο αυτής υιούς, εκ των οποίων του ενός το όνομα ήτο Γηρσώμ, Διότι πάροικος, είπεν, εστάθην εν ξένη γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'του δε άλλου το όνομα Ελιέζερ, Διότι ο Θεός, είπε, του πατρός μου εστάθη βοηθός μου και με έσωσεν εκ της μαχαίρας του Φαραώ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'και ήλθεν ο Ιοθόρ ο πενθερός του Μωϋσέως προς τον Μωϋσήν μετά των υιών αυτού και μετά της γυναικός αυτού εις την έρημον, όπου ήτο εστρατοπεδευμένος εις το όρος του Θεού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'και ανήγγειλε προς τον Μωϋσήν, Εγώ Ιοθόρ ο πενθερός σου έρχομαι προς σε και η γυνή σου και οι δύο υιοί αυτής μετ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Και εξήλθεν ο Μωϋσής εις συνάντησιν του πενθερού αυτού και προσεκύνησεν αυτόν και εφίλησεν αυτόν· και ηρώτησαν ο εις τον άλλον περί της υγείας αυτών, και εισήλθον εις την σκηνήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Και διηγήθη ο Μωϋσής προς τον πενθερόν αυτού πάντα όσα ο Κύριος έκαμεν εις τον Φαραώ και εις τους Αιγυπτίους υπέρ του Ισραήλ, πάντας τους μόχθους οίτινες συνέβησαν εις αυτούς καθ\' οδόν, και ηλευθέρωσεν αυτούς ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Υπερεχάρη δε ο Ιοθόρ διά πάντα τα αγαθά όσα ο Κύριος έκαμεν εις τον Ισραήλ, τον οποίον ηλευθέρωσεν εκ χειρός των Αιγυπτίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Και είπεν ο Ιοθόρ, Ευλογητός Κύριος, όστις σας ηλευθέρωσεν εκ χειρός των Αιγυπτίων και εκ χειρός του Φαραώ· όστις ηλευθέρωσε τον λαόν υποκάτωθεν της χειρός των Αιγυπτίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'τώρα γνωρίζω ότι ο Κύριος είναι μέγας υπέρ πάντας τους θεούς· διότι εις το πράγμα, εις το οποίον υπερηφανεύθησαν, εστάθη ανώτερος αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Έλαβεν έπειτα ο Ιοθόρ, ο πενθερός του Μωϋσέως, ολοκαυτώματα και θυσίας διά να προσφέρη εις τον Θεόν· και ήλθεν ο Ααρών, και πάντες οι πρεσβύτεροι του Ισραήλ, να φάγωσιν άρτον μετά του πενθερού του Μωϋσέως, έμπροσθεν του Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Και την επαύριον εκάθισεν ο Μωϋσής διά να κρίνη τον λαόν. και παρίστατο ο λαός έμπροσθεν του Μωϋσέως από πρωΐας έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Και ιδών ο πενθερός του Μωϋσέως πάντα όσα έκαμνεν εις τον λαόν, είπε, Τι είναι τούτο το πράγμα, το οποίον κάμνεις εις τον λαόν; διά τι συ κάθησαι μόνος, άπας δε ο λαός παρίσταται έμπροσθέν σου από πρωΐας έως εσπέρας;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Και είπεν ο Μωϋσής προς τον πενθερόν αυτού, διότι ο λαός έρχεται προς εμέ διά να ερωτήση τον Θεόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'όταν έχωσιν υπόθεσίν τινά, έρχονται προς εμέ και εγώ κρίνω μεταξύ του ενός και του άλλου· και δεικνύω εις αυτούς τα προστάγματα του Θεού και τους νόμους αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Και είπεν ο πενθερός του Μωϋσέως προς αυτόν, Δεν είναι καλόν το πράγμα, το οποίον κάμνεις·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'βεβαίως και συ θέλεις αποκάμει και ο λαός ούτος ο μετά σού· διότι το πράγμα είναι πολύ βαρύ διά σέ· δεν δύνασαι μόνος να κάμνης τούτο.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Άκουσον λοιπόν την φωνήν μου· θέλω σε συμβουλεύσει και ο Θεός θέλει είσθαι μετά σού· συ μεν έσο ενώπιον του Θεού υπέρ του λαού, διά να αναφέρης τας υποθέσεις προς τον Θεόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'και δίδασκε αυτούς τα προστάγματα και τους νόμους και δείκνυε προς αυτούς την οδόν εις την οποίαν πρέπει να περιπατώσι, και τα έργα τα οποία πρέπει να πράττωσι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'πλην έκλεξον εκ παντός του λαού άνδρας αξίους, φοβουμένους τον Θεόν, άνδρας φιλαλήθεις, μισούντας την φιλαργυρίαν· και κατάστησον αυτούς επ\' αυτών χιλιάρχους, εκατοντάρχους, πεντηκοντάρχους και δεκάρχους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'και ας κρίνωσι τον λαόν πάντοτε· και πάσαν μεν μεγάλην υπόθεσιν ας αναφέρωσι προς σέ· πάσαν δε μικράν υπόθεσιν ας κρίνωσιν αυτοί· ούτω θέλεις ανακουφισθή, και θέλουσι βαστάζει το βάρος μετά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'εάν κάμης τούτο το πράγμα και ο Θεός σε προστάζη ούτω, τότε θέλεις δυνηθή να ανθέξης, και προσέτι πας ο λαός ούτος θέλει φθάσει εις τον τόπον αυτού εν ειρήνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Και ήκουσεν ο Μωϋσής την φωνήν του πενθερού αυτού και έκαμε πάντα όσα είπε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Και έκλεξεν ο Μωϋσής εκ παντός του Ισραήλ άνδρας αξίους και κατέστησεν αυτούς αρχηγούς επί του λαού, χιλιάρχους, εκατοντάρχους, πεντηκοντάρχους και δεκάρχους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'και έκρινον τον λαόν εν παντί καιρώ· τας μεν υποθέσεις τας δυσκόλους ανέφερον προς τον Μωϋσήν, πάσαν δε μικράν υπόθεσιν έκρινον αυτοί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Έπειτα προέπεμψεν ο Μωϋσής τον πενθερόν αυτού και απήλθεν εις την γην αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Εις τον τρίτον μήνα της εξόδου των υιών Ισραήλ εκ της Αιγύπτου, την ημέραν ταύτην ήλθον εις την έρημον Σινά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Εσηκώθησαν δε από Ραφιδείν και ήλθον εις την έρημον Σινά και εστρατοπέδευσαν εν τη ερήμω· και εκεί κατεσκήνωσεν ο Ισραήλ απέναντι του όρους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Ο δε Μωϋσής ανέβη προς τον Θεόν· και εκάλεσεν αυτόν ο Κύριος εκ του όρους, λέγων, Ούτω θέλεις ειπεί προς τον οίκον Ιακώβ, και αναγγείλει προς τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Σεις είδετε όσα έκαμα εις τους Αιγυπτίους, και σας εσήκωσα ως επί πτερύγων αετού και σας έφερα προς εμαυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'τώρα λοιπόν εάν τωόντι υπακούσητε εις την φωνήν μου, και φυλάξητε την διαθήκην μου, θέλετε είσθαι εις εμέ ο εκλεκτός από πάντων των λαών· διότι ιδική μου είναι πάσα η γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'και σεις θέλετε είσθαι εις εμέ βασίλειον ιεράτευμα και έθνος άγιον. Ούτοι είναι οι λόγοι, τους οποίους θέλεις ειπεί προς τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Και ήλθεν ο Μωϋσής και εκάλεσε τους πρεσβυτέρους του λαού και έθεσεν έμπροσθεν αυτών πάντας εκείνους τους λόγους, τους οποίους προσέταξεν εις αυτόν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Και απεκρίθη ομοφώνως πας ο λαός, λέγων, Πάντα όσα είπεν ο Κύριος θέλομεν πράξει. Και ανέφερεν ο Μωϋσής προς τον Κύριον τους λόγους του λαού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Και είπε Κύριος προς τον Μωϋσήν, Ιδού, εγώ έρχομαι προς σε εν νεφέλη πυκνή, διά να ακούση ο λαός όταν λαλήσω προς σε, και έτι να πιστεύη εις σε πάντοτε. Ανήγγειλε δε ο Μωϋσής προς τον Κύριον τους λόγους του λαού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Και είπε Κύριος προς τον Μωϋσήν, Ύπαγε προς τον λαόν και αγίασον αυτούς σήμερον και αύριον, και ας πλύνωσι τα ιμάτια αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'και ας ήναι έτοιμοι εις την ημέραν την τρίτην· διότι εν τη ημέρα τη τρίτη θέλει καταβή ο Κύριος επί το όρος Σινά ενώπιον παντός του λαού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'και θέλεις βάλει εις τον λαόν όρια κυκλόθεν, λέγων, Προσέχετε εις εαυτούς μη αναβήτε εις το όρος ή εγγίσητε εις τα άκρα αυτού· όστις εγγίση το όρος, θέλει εξάπαντος θανατωθή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'δεν θέλει εγγίσει εις αυτόν χειρ, διότι με λίθους θέλει λιθοβοληθή ή με βέλη θέλει κατατοξευθή· είτε ζώον είναι είτε άνθρωπος, δεν θέλει ζήσει. Όταν η σάλπιγξ ηχήση, τότε θέλουσιν αναβή επί το όρος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Και κατέβη ο Μωϋσής από του όρους προς τον λαόν και ηγίασε τον λαόν· και έπλυναν τα ιμάτια αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Και είπε προς τον λαόν, Γίνεσθε έτοιμοι διά την ημέραν την τρίτην· μη πλησιάσητε εις γυναίκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Και εν τη ημέρα τη τρίτη το πρωΐ έγειναν βρονταί και αστραπαί, και νεφέλη πυκνή ήτο επί του όρους, και φωνή σάλπιγγος δυνατή σφόδρα· και έτρεμε πας ο λαός ο εν τω στρατοπέδω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Τότε εξήγαγεν ο Μωϋσής τον λαόν εκ του στρατοπέδου εις την συνάντησιν του Θεού· και εστάθησαν υπό το όρος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Το δε όρος Σινά ήτο όλον καπνός, διότι κατέβη ο Κύριος εν πυρί επ\' αυτό· ανέβαινε δε ο καπνός αυτού ως καπνός καμίνου και όλον το όρος εσείετο σφόδρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Και ότε η φωνή της σάλπιγγος προέβαινεν αυξανομένη σφόδρα, ο Μωϋσής ελάλει και ο Θεός απεκρίνετο προς αυτόν μετά φωνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Και κατέβη ο Κύριος επί το όρος Σινά, επί την κορυφήν του όρους· και εκάλεσε Κύριος τον Μωϋσήν επί την κορυφήν του όρους, και ανέβη ο Μωϋσής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Και είπε Κύριος προς τον Μωϋσήν, Καταβάς, διαμαρτυρήθητι προς τον λαόν, μήποτε υπερβώσι τα όρια και αναβώσι προς τον Κύριον διά να περιεργασθώσι και πέσωσι πολλοί εξ αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'και οι ιερείς δε οι πλησιάζοντες προς τον Κύριον ας αγιασθώσι, διά να μη εξορμήση ο Κύριος επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Και είπεν ο Μωϋσής προς τον Κύριον, Ο λαός δεν δύναται να αναβή εις το όρος Σινά· διότι συ προσέταξας εις ημάς, λέγων, Βάλε όρια κυκλόθεν του όρους και αγίασον αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Και είπε Κύριος προς αυτόν, Ύπαγε, κατάβα· έπειτα θέλεις αναβή, συ και ο Ααρών μετά σού· οι ιερείς όμως και ο λαός ας μη υπερβώσι τα όρια διά να αναβώσι προς τον Κύριον, διά να μη εξορμήση επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Και κατέβη ο Μωϋσής προς τον λαόν και ώμίλησε προς αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Και ελάλησεν ο Θεός πάντας τους λόγους τούτους, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Εγώ είμαι Κύριος ο Θεός σου, ο εξαγαγών σε εκ γης Αιγύπτου, εξ οίκου δουλείας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Μη έχης άλλους θεούς πλην εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Μη κάμης εις σεαυτόν είδωλον, μηδέ ομοίωμά τινός, όσα είναι εν τω ουρανώ άνω, ή όσα εν τη γη κάτω, όσα εν τοις ύδασιν υποκάτω της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'μη προσκυνήσης αυτά μηδέ λατρεύσης αυτά· διότι εγώ Κύριος ο Θεός σου είμαι Θεός ζηλότυπος, ανταποδίδων τας αμαρτίας των πατέρων επί τα τέκνα, έως τρίτης και τετάρτης γενεάς των μισούντων με·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'και κάμνων έλεος εις χιλιάδας γενεών των αγαπώντων με και φυλαττόντων τα προστάγματά μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Μη λάβης το όνομα Κυρίου του Θεού σου επί ματαίω· διότι δεν θέλει αθωώσει ο Κύριος τον λαμβάνοντα επί ματαίω το όνομα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Ενθυμού την ημέραν του σαββάτου, διά να αγιάζης αυτήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'εξ ημέρας εργάζου και κάμνε πάντα τα έργα σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'η ημέρα όμως η εβδόμη είναι σάββατον Κυρίου του Θεού σου· μη κάμης εν ταύτη ουδέν έργον, μήτε συ, μήτε ο υιός σου, μήτε η θυγάτηρ σου, μήτε ο δούλός σου, μήτε η δούλη σου, μήτε το κτήνός σου, μήτε ο ξένος σου, ο εντός των πυλών σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'διότι εις εξ ημέρας εποίησεν ο Κύριος τον ουρανόν και την γην, την θάλασσαν και πάντα τα εν αυτοίς· εν δε τη ημέρα τη εβδόμη κατέπαυσε· διά τούτο ευλόγησε Κύριος την ημέραν του σαββάτου και ηγίασεν αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Τίμα τον πατέρα σου και την μητέρα σου, διά να γείνης μακροχρόνιος επί της γης, την οποίαν σοι δίδει Κύριος ο Θεός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Μη φονεύσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Μη μοιχεύσης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Μη κλέψης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Μη ψευδομαρτυρήσης κατά του πλησίον σου μαρτυρίαν ψευδή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Μη επιθυμήσης την οικίαν του πλησίον σου· μη επιθυμήσης την γυναίκα του πλησίον σου· μηδέ τον δούλον αυτού· μηδέ την δούλην αυτού, μηδέ τον βουν αυτού, μηδέ τον όνον αυτού, μηδέ παν ό,τι είναι του πλησίον σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Και πας ο λαός έβλεπε τας βροντάς και τας αστραπάς και την φωνήν της σάλπιγγος και το όρος καπνίζον· και ότε ο λαός είδε ταύτα, απεσύρθησαν και εστάθησαν μακρόθεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Και είπον προς τον Μωϋσήν, συ λάλησον προς ημάς και θέλομεν ακούσει και ας μη λαλήση προς ημάς ο Θεός, διά να μη αποθάνωμεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Και είπεν ο Μωϋσής προς τον λαόν, Μη φοβείσθε· διότι ο Θεός ήλθε διά να σας δοκιμάση, και διά να ήναι ο φόβος αυτού έμπροσθέν σας διά να μη αμαρτάνητε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Και εστάθη ο λαός μακρόθεν· ο δε Μωϋσής επλησίασεν εις την ομίχλην όπου ήτο ο Θεός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Είπε δε Κύριος προς τον Μωϋσήν, Ούτως ειπέ προς τους υιούς Ισραήλ· Σεις είδετε ότι εκ του ουρανού ελάλησα με σάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'μη κάμητε θεούς μετ\' εμού αργυρούς· μηδέ κάμητε εις εαυτούς θεούς χρυσούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'θυσιαστήριον εκ γης κάμε εις εμέ· και θυσίαζε επ\' αυτού τα ολοκαυτώματά σου και τας ειρηνικάς προσφοράς σου, τα πρόβατά σου και τους βόας σου· εν παντί τόπω όπου αναμνήσω το όνομά μου, θέλω έρχεσθαι προς σε και θέλω σε ευλογεί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'εάν δε εκ λίθων κάμης θυσιαστήριον εις εμέ, δεν θέλεις οικοδομήσει αυτό εκ πέτρας πελεκητής· διότι εάν περάσης επάνω αυτού το εργαλείόν σου, θέλεις μολύνει αυτό·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'και μη αναβής δι\' αναβαθμίδων επί το θυσιαστήριόν μου, διά να μη αποκαλυφθή επ\' αυτού η γυμνωσίς σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Αύται δε είναι αι κρίσεις, τας οποίας θέλεις εκθέσει έμπροσθεν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Εάν αγοράσης δούλον Εβραίον, εξ έτη θέλει δουλεύσει· εν δε τω εβδόμω θέλει εξέλθει ελεύθερος, δωρεάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Εάν εισήλθε μόνος, μόνος θέλει εξέλθει· εάν είχε γυναίκα, τότε η γυνή αυτού θέλει εξέλθει μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Εάν ο κύριος αυτού έδωκεν εις αυτόν γυναίκα, και εγέννησεν εις αυτόν υιούς η θυγατέρας, η γυνή και τα τέκνα αυτής θέλουσιν είσθαι του κυρίου αυτής, αυτός δε θέλει εξέλθει μόνος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Αλλ\' εάν ο δούλος είπη φανερά, Αγαπώ τον κύριόν μου, την γυναίκα μου και τα τέκνα μου, δεν θέλω εξέλθει ελεύθερος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'τότε ο κύριος αυτού θέλει φέρει αυτόν προς τους κριτάς· και θέλει φέρει αυτόν εις την θύραν ή εις τον παραστάτην της θύρας, και ο κύριος αυτού θέλει τρυπήσει το ωτίον αυτού με τρυπητήριον· και θέλει δουλεύει αυτόν διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Και εάν τις πωλήση την θυγατέρα αυτού διά δούλην, δεν θέλει εξέλθει καθώς εξέρχονται οι δούλοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Εάν δεν αρέση εις τον κύριον αυτής, όστις ηρραβωνίσθη αυτήν εις εαυτόν, τότε θέλει απολυτρώσει αυτήν· εις ξένον έθνος δεν θέλει έχει εξουσίαν να πωλήση αυτήν, επειδή εφέρθη προς αυτήν απίστως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Αν όμως ηρραβώνισεν αυτήν με τον υιόν αυτού, θέλει κάμει προς αυτήν κατά το δικαίωμα των θυγατέρων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Εάν λάβη εις εαυτόν άλλην, δεν θέλει στερήσει την τροφήν αυτής, τα ενδύματα αυτής, και το προς αυτήν χρέος του γάμου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Εάν όμως δεν κάμνη εις αυτήν τα τρία ταύτα, τότε θέλει εξέλθει δωρεάν άνευ αργυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Όστις πατάξη άνθρωπον, και αποθάνη, θέλει εξάπαντος θανατωθή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'εάν όμως δεν παρεμόνευσεν, αλλ\' ο Θεός παρέδωκεν αυτόν εις την χείρα αυτού, τότε εγώ θέλω σοι διορίσει τόπον, όπου θέλει καταφύγει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'εάν δε τις εγερθή κατά του πλησίον αυτού διά να δολοφονήση αυτόν, από του θυσιαστηρίου μου θέλεις αποσπάσει αυτόν διά να θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Και όστις πατάξη τον πατέρα αυτού ή την μητέρα αυτού, θέλει εξάπαντος θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Και όστις κλέψη άνθρωπον και πωλήση αυτόν, ή εάν ευρεθή εις τας χείρας αυτού, θέλει εξάπαντος θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Και όστις κακολογή τον πατέρα αυτού ή την μητέρα αυτού, θέλει εξάπαντος θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Και εάν άνθρωποι λογομαχώσι μετ\' αλλήλων και ο εις πατάξη τον άλλον με λίθον ή με γρόνθον, και δεν αποθάνη αλλά γείνη κλινήρης,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'εάν σηκωθή και περιπατήση έξω με την βακτηρίαν αυτού, τότε θέλει είσθαι ελεύθερος ο πατάξας· μόνον θέλει αποζημιώσει αυτόν διά την αργίαν αυτού και θέλει επιμεληθή την τελείαν θεραπείαν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Και εάν τις πατάξη τον δούλον αυτού ή την δούλην αυτού με ράβδον, και αποθάνη υπό τας χείρας αυτού, θέλει εξάπαντος τιμωρηθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Αν όμως ζήση μίαν ημέραν ή δύο, δεν θέλει τιμωρηθή· διότι είναι αργύριον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Εάν μάχωνται άνδρες και πατάξωσι γυναίκα έγκυον και εξέλθη το παιδίον αυτής, δεν συμβή όμως συμφορά· θέλει εξάπαντος κάμει αποζημίωσιν ο πατάξας, οποίαν ο ανήρ της γυναικός επιβάλη εις αυτόν· και θέλει πληρώσει κατά την απόφασιν των κριτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Αν όμως συμβή συμφορά, τότε θέλεις δώσει ζωήν αντί ζωής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'οφθαλμόν αντί οφθαλμού, οδόντα αντί οδόντος, χείρα αντί χειρός, πόδα αντί ποδός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'καύσιμον αντί καυσίματος, πληγήν αντί πληγής, κτύπημα αντί κτυπήματος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Εάν τις πατάξη τον οφθαλμόν του δούλου αυτού ή τον οφθαλμόν της δούλης αυτού και τυφλώση αυτόν, θέλει αφήσει αυτόν ελεύθερον εξ αιτίας του οφθαλμού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Και εάν εκβάλη τον οδόντα του δούλον αυτού ή τον οδόντα της δούλης αυτού, θέλει αφήσει αυτόν ελεύθερον εξ αιτίας του οδόντος αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Εάν βους κερατίση άνδρα ή γυναίκα, και αποθάνη, τότε ο βους θέλει λιθοβοληθή με λίθους και δεν θέλει τρώγεσθαι το κρέας αυτού· ο κύριος δε του βοός θέλει είσθαι αθώος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Εάν όμως ο βους ήτο κερατιστής από πρότερον, και έγεινε διαμαρτυρία εις τον κύριον αυτού και δεν εφύλαξεν αυτόν, εάν θανατώση άνδρα ή γυναίκα, ο βους θέλει λιθοβοληθή και ακόμη ο κύριος αυτού θέλει θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Εάν επιβληθή εις αυτόν τιμή εξαγοράσεως, θέλει δώσει διά την εξαγόρασιν της ζωής αυτού όσα ήθελον επιβληθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Είτε υιόν κερατίση, είτε θυγατέρα κερατίση, κατά την κρίσιν ταύτην θέλει γείνει εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Εάν ο βους κερατίση δούλον ή δούλην, θέλει δώσει εις τον κύριον αυτών τριάκοντα σίκλους αργυρίου· ο δε βους θέλει λιθοβοληθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Και εάν τις ανοίξη λάκκον ή εάν τις σκάψη λάκκον και δεν σκεπάση αυτόν, και πέση εις αυτόν βους ή όνος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'ο κύριος του λάκκου θέλει κάμει αποζημίωσιν, αργύριον θέλει αποδώσει εις τον κύριον αυτών· το δε θανατωθέν θέλει είσθαι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Και εάν ο βους τινός κερατίση τον βουν του πλησίον αυτού και θανατωθή, τότε θέλουσι πωλήσει τον ζώντα βουν, και θέλουσι μοιρασθή το αργύριον αυτού και τον θανατωθέντα ομοίως θέλουσι μοιρασθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Εάν όμως ήναι γνωστόν ότι ο βους ήτο κερατιστής από πρότερον, και ο κύριος αυτού δεν εφύλαξεν αυτόν, θέλει εξάπαντος πληρώσει βουν αντί βοός· ο δε θανατωθείς θέλει είσθαι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Εάν τις κλέψη βουν ή πρόβατον και σφάξη αυτό ή πωλήση αυτό, θέλει πληρώσει πέντε βόας αντί του βοός και τέσσαρα πρόβατα αντί του προβάτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Εάν ο κλέπτης ευρεθή κάμνων ρήξιν και κτυπηθή και αποθάνη, δεν θέλει χυθή αίμα δι\' αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Εάν όμως ο ήλιος ανατείλη επάνω αυτού, θέλει χυθή αίμα δι\' αυτόν· πρέπει να κάμη ανταπόδοσιν· και αν δεν έχη, θέλει πωληθή διά την κλοπήν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Εάν το κλοπιμαίον ευρεθή εις τας χείρας αυτού ζων, είτε βους είτε όνος είτε πρόβατον, θέλει αποδώσει το διπλούν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Εάν τις καταβοσκήση αγρόν ή αμπελώνα και αφήση το κτήνος αυτού να βοσκηθή εν αγρώ ξένου ανθρώπου, θέλει κάμει ανταπόδοσιν εκ του καλητέρου του αγρού αυτού και εκ του καλητέρου του αμπελώνος αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Εάν εξέλθη πυρ και εύρη ακάνθας, και καώσι θημωνίαι σίτου ή αστάχυα ιστάμενα ή αγρός, ο ανάψας το πυρ θέλει εξάπαντος κάμει ανταπόδοσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Εάν τις παραδώση εις τον πλησίον αυτού αργύριον ή σκεύη διά να φυλάττη αυτά, και κλαπώσιν εκ της οικίας του ανθρώπου, αν ευρεθή ο κλέπτης, θέλει αποδώσει το διπλούν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'αν ο κλέπτης δεν ευρεθή, τότε ο κύριος της οικίας θέλει φερθή έμπροσθεν των κριτών, διά να εξετασθή αν δεν έβαλε την χείρα αυτού επί τα κτήματα του πλησίον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Περί παντός είδους αδικήματος, περί βοός, περί όνου, περί προβάτου, περί ενδύματος, περί παντός πράγματος χαμένου, το οποίον άλλος ήθελε διαφιλονεικεί ότι είναι αυτού, η κρίσις αμφοτέρων θέλει ελθεί έμπροσθεν των κριτών· και όντινα καταδικάσωσιν οι κριταί, εκείνος θέλει αποδώσει το διπλούν εις τον πλησίον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Εάν τις παραδώση εις τον πλησίον αυτού όνον ή βουν ή πρόβατον ή οποιονδήποτε κτήνος, διά να φυλάττη αυτό, και αποθάνη ή συντριφθή ή αρπαχθή χωρίς να ίδη τις,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'όρκος Θεού θέλει γείνει ανά μέσον αμφοτέρων αυτών, ότι δεν έβαλε την χείρα αυτού επί το κτήμα του πλησίον αυτού· και ο κύριος αυτού θέλει λάβει αυτό, ο δε άλλος δεν θέλει κάμει ανταπόδοσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Εάν όμως εκλέφθη παρ\' αυτού, θέλει κάμει ανταπόδοσιν εις τον κύριον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Εάν έγεινε θηριάλωτον, θέλει φέρει αυτό διά μαρτυρίαν και δεν θέλει πληρώσει το θηριάλωτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Και εάν τις δανεισθή ζώον παρά του πλησίον αυτού, και συντριφθή ή αποθάνη, ο δε κύριος αυτού δεν ήναι μετ\' αυτού, θέλει εξάπαντος πληρώσει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Εάν όμως ο κύριος αυτού ήναι μετ\' αυτού, δεν θέλει πληρώσει· αν ήτο μεμισθωμένον, ήλθε διά τον μισθόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Και εάν τις απατήση παρθένον μη ηρραβωνισμένην, και κοιμηθή μετ\' αυτής, θέλει εξάπαντος προικίσει αυτήν με προίκα διά γυναίκα εις εαυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Εάν όμως ο πατήρ αυτής δεν στέργη να δώση αυτήν εις αυτόν, αργύριον θέλει πληρώσει κατά την προίκα των παρθένων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Μάγισσαν δεν θέλεις αφήσει να ζη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Όστις συνευρεθή με κτήνος, θέλει εξάπαντος θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Ο θυσιάζων εις θεούς, εκτός εις μόνον τον Κύριον, θέλει εξολοθρευθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Και ξένον δεν θέλεις κακοποιήσει ουδέ θέλεις καταδυναστεύσει αυτόν· διότι ξένοι εστάθητε εν τη γη της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Ουδεμίαν χήραν ή ορφανόν δεν θέλετε καταθλίψει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Εάν καταθλίψητε αυτούς οπωσδήποτε και βοήσωσι προς εμέ, θέλω εξάπαντος εισακούσει της φωνής αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'και ο θυμός μου θέλει εξαφθή και θέλω σας θανατώσει εν μαχαίρα· και αι γυναίκές σας θέλουσιν είσθαι χήραι και τα τέκνα σας ορφανά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Εάν δανείσης αργύριον εις τον πτωχόν γείτονά σου μεταξύ του λαού μου, δεν θέλεις φερθή προς αυτόν ως τοκιστής, δεν θέλεις επιβάλει επ\' αυτόν τόκον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Εάν λάβης ενέχυρον το ένδυμα του πλησίον σου, θέλεις επιστρέψει αυτό προς αυτόν πριν δύση ο ήλιος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'διότι τούτο μόνον είναι το σκέπασμα αυτού, τούτο το ένδυμα του δέρματος αυτού· με τι θέλει κοιμηθή; και όταν βοήση προς εμέ, θέλω εισακούσει· διότι εγώ είμαι ελεήμων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Δεν θέλεις κακολογήσει κριτάς, ουδέ θέλεις καταρασθή άρχοντα του λαού σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Τας απαρχάς του αλωνίου σου και του ληνού σου δεν θέλεις καθυστερήσει· τον πρωτότοκόν σου εκ των υιών σου θέλεις δώσει εις εμέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'ομοίως θέλεις κάμει διά τον βουν σου και διά το πρόβατόν σου· επτά ημέρας θέλει είσθαι μετά της μητρός αυτού, την ογδόην ημέραν θέλεις δώσει αυτό εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Και άνδρες άγιοι θέλετε είσθαι εις εμέ· και κρέας θηριάλωτον εν τω αγρώ δεν θέλετε φάγει· εις τον σκύλον θέλετε ρίψει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Δεν θέλεις διαδώσει ψευδή φήμην· δεν θέλεις συμφωνήσει μετά του αδίκου διά να γείνης ψευδομάρτυς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Δεν θέλεις ακολουθήσει τους πολλούς επί κακώ· ουδέ θέλεις ομιλήσει εν κρισολογία, ώστε να κλίνης κατόπιν πολλών διά να διαστρέψης κρίσιν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'ουδέ θέλεις αποβλέψει εις πρόσωπον πτωχού εν τη κρίσει αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Εάν απαντήσης τον βουν του εχθρού σου ή τον όνον αυτού πλανώμενον, θέλεις εξάπαντος επιστρέψει αυτόν προς αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Εάν ίδης τον όνον του μισούντός σε πεπτωκότα υπό το φορτίον αυτού και ήθελες αποφύγει να βοηθήσης αυτόν, εξάπαντος θέλεις συμβοηθήσει αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Δεν θέλεις διαστρέψει το δίκαιον του πένητός σου εν τη κρίσει αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Άπεχε από αδίκου υποθέσεως· και μη γείνης αιτία να θανατωθή ο αθώος και ο δίκαιος· διότι εγώ δεν θέλω δικαιώσει τον ασεβή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Και δώρα δεν θέλεις λάβει· διότι τα δώρα τυφλόνουσι και τους σοφούς, και διαστρέφουσι τους λόγους των δικαίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Και ξένον δεν θέλεις καταδυναστεύσει διότι σεις γνωρίζετε την ψυχήν του ξένου, επειδή ξένοι εστάθητε εν τη γη της Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Και εξ έτη θέλεις σπείρει την γην σου και θέλεις συνάγει τα γεννήματα αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'το δε έβδομον θέλεις αφήσει αυτήν να αναπαυθή και να μένη αργή, διά να τρώγωσιν οι πτωχοί του λαού σου· και το εναπολειφθέν αυτών ας τρώγωσι τα ζώα του αγρού. Ούτω θέλεις κάμει διά τον αμπελώνά σου και διά τον ελαιώνά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Εξ ημέρας θέλεις κάμνει τας εργασίας σου· την δε εβδόμην ημέραν θέλεις αναπαύεσθαι, διά να αναπαυθή ο βους σου και ο οίνος σου και να λάβη αναψυχήν ο υιός της δούλης σου και ο ξένος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Και εις πάντα όσα ελάλησα προς εσάς, θέλετε προσέξει· και όνομα άλλων θεών δεν θέλετε αναφέρει, ουδέ θέλει ακουσθή εκ του στόματός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Τρίς του ενιαυτού θέλεις κάμνει εορτήν εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Θέλεις φυλάττει την εορτήν των αζύμων· επτά ημέρας θέλεις τρώγει άζυμα, καθώς προσέταξα εις σε, κατά τον διωρισμένον καιρόν του μηνός Αβίβ· διότι εν τούτω εξήλθες εξ Αιγύπτου· και ουδείς θέλει φανή ενώπιόν μου κενός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'και την εορτήν του θερισμού, των πρωτογεννημάτων των κόπων σου, τα οποία έσπειρας εις τον αγρόν· και την εορτήν της συγκομιδής των καρπών, εις το τέλος του ενιαυτού, αφού συνάξης τους καρπούς σου εκ του αγρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Τρίς του ενιαυτού θέλει εμφανίζεσθαι παν αρσενικόν σου ενώπιον Κυρίου του Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Δεν θέλεις προσφέρει το αίμα της θυσίας μου με άρτον ένζυμον· ουδέ θέλει μένει το πάχος της εορτής μου έως πρωΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Τας απαρχάς των πρωτογεννημάτων της γης σου θέλεις φέρει εις τον οίκον Κυρίου του Θεού σου. Δεν θέλεις ψήσει ερίφιον εν τω γάλακτι της μητρός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Ιδού, εγώ αποστέλλω άγγελον έμπροσθέν σου διά να σε φυλάττη εν τη οδώ, και να σε φέρη εις τον τόπον τον οποίον προητοίμασα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'φοβού αυτόν, και υπάκουε εις την φωνήν αυτού· μη παροργίσης αυτόν· διότι δεν θέλει συγχωρήσει τας παραβάσεις σας· επειδή το όνομά μου είναι εν αυτώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Εάν όμως προσέχης να υπακούης εις την φωνήν αυτού και πράττης πάντα όσα λέγω, τότε εγώ θέλω είσθαι εχθρός των εχθρών σου και εναντίος των εναντίων σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Διότι ο άγγελός μου θέλει προπορεύσθαι έμπροσθέν σου, και θέλει σε εισαγάγει εις τους Αμορραίους και Χετταίους και Φερεζαίους και Χαναναίους, Ευαίους και Ιεβουσαίους· και θέλω εξολοθρεύσει αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Δεν θέλεις προσκυνήσει τους θεούς αυτών, ουδέ θέλεις λατρεύσει αυτούς, ουδέ θέλεις πράξει κατά τα έργα εκείνων· αλλά θέλεις εξολοθρεύσει αυτούς, και θέλεις κατασυντρίψει τα είδωλα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Και θέλετε λατρεύει Κύριον τον Θεόν σας, και αυτός θέλει ευλογεί τον άρτον σου, και το ύδωρ σου· και θέλω απομακρύνει πάσαν νόσον εκ μέσου σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'και δεν θέλει είσθαι άγονος και στείρα επί της γης σου· τον αριθμόν των ημερών σου θέλω κάμει πλήρη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'τον φόβον μου θέλει στείλει έμπροσθέν σου και θέλω καταστρέψει πάντα λαόν επί τον οποίον έρχεσαι και θέλω κάμει πάντας τους εχθρούς σου να στρέψωσι τα νώτα εις σέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'και θέλω στείλει έμπροσθέν σου σφήκας, και θέλουσιν εκδιώξει τους Ευαίους, τους Χαναναίους και τους Χετταίους απ\' έμπροσθέν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Δεν θέλω εκδιώξει αυτούς απ\' έμπροσθέν σου εις εν έτος, διά να μη γείνη έρημος η γη και πληθυνθώσι τα θηρία του αγρού εναντίον σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'ολίγον κατ\' ολίγον θέλω εκδιώξει αυτούς απ\' έμπροσθέν σου, εωσού αυξηθής και κυριεύσης την γην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Και θέλω θέσει τα όριά σου από της Ερυθράς θαλάσσης μέχρι της θαλάσσης των Φιλισταίων, και από της ερήμου μέχρι του ποταμού· διότι εις τας χείρας υμών θέλω παραδώσει τους κατοίκους του τόπου, και θέλεις εκδιώξει αυτούς απ\' έμπροσθέν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Δεν θέλεις κάμει μετ\' αυτών, ουδέ μετά των θεών αυτών, συνθήκην·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'δεν θέλουσι κατοικεί εν τη γη σου, διά να μη σε κάμωσι να αμαρτήσης εις εμέ· διότι αν λατρεύσης τους θεούς αυτών, τούτο θέλει εξάπαντος είσθαι παγίς εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Μετά ταύτα είπε προς τον Μωϋσήν, Ανάβα προς τον Κύριον, συ και Ααρών, Ναδάβ και Αβιούδ, και εβδομήκοντα εκ των πρεσβυτέρων του Ισραήλ, και προσκυνήσατε μακρόθεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'και ο Μωϋσής μόνος θέλει πλησιάσει προς τον Κύριον, αυτοί όμως δεν θέλουσι πλησιάσει ουδέ ο λαός θέλει αναβή μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Και ήλθεν ο Μωϋσής και διηγήθη προς τον λαόν πάντας τους λόγους του Κυρίου και πάντα τα δικαιώματα αυτού· απεκρίθη δε πας ο λαός ομοφώνως και είπε, Πάντας τους λόγους, τους οποίους ελάλησεν ο Κύριος, θέλομεν κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Και έγραψεν ο Μωϋσής πάντας τους λόγους του Κυρίου· και σηκωθείς ενωρίς το πρωΐ, ωκοδόμησε θυσιαστήριον υπό το όρος, και έστησε δώδεκα στήλας κατά τας δώδεκα φυλάς του Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Και απέστειλε τους νεανίσκους των υιών Ισραήλ, και προσέφεραν ολοκαυτώματα και εθυσίασαν θυσίας ειρηνικάς εις τον Κύριον, μοσχάρια.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Λαβών δε ο Μωϋσής το ήμισυ του αίματος, έβαλεν εις λεκάνας· και το ήμισυ του αίματος ερράντισεν επί το θυσιαστήριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Έπειτα λαβών το βιβλίον της διαθήκης, ανέγνωσεν εις τα ώτα του λαού· οι δε είπον, Πάντα όσα ελάλησεν ο Κύριος, θέλομεν κάμνει και θέλομεν υπακούει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Και λαβών ο Μωϋσής το αίμα, ερράντισεν επί τον λαόν, και είπεν, Ιδού, το αίμα της διαθήκης, την οποίαν ο Κύριος έκαμε προς εσάς κατά πάντας τούτους τους λόγους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Τότε ανέβη Μωϋσής και Ααρών, Ναδάβ και Αβιούδ και εβδομήκοντα εκ των πρεσβυτέρων του Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'και είδον τον Θεόν του Ισραήλ· και υπό τους πόδας αυτού ως έδαφος εστρωμένον εκ λίθου σαπφείρου και ως το στερέωμα του ουρανού κατά την καθαρότητα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'και επί τους εκλεκτούς των υιών Ισραήλ δεν έβαλε την χείρα αυτού· και είδον τον Θεόν, και έφαγον και έπιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Και είπε Κύριος προς τον Μωϋσήν, Ανάβα προς εμέ εις το όρος και έσο εκεί· και θέλω σοι δώσει τας πλάκας τας λιθίνας, και τον νόμον, και τας εντολάς τας οποίας έγραψα, διά να διδάσκης αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Και εσηκώθη ο Μωϋσής μετά Ιησού του θεράποντος αυτού, και ανέβη ο Μωϋσής επί το όρος του Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Προς δε τους πρεσβυτέρους είπε, Περιμένετε ημάς εδώ, εωσού επιστρέψωμεν προς εσάς· και ιδού, Ααρών και Ωρ είναι μεθ\' υμών· εάν τις έχη υπόθεσιν, ας έρχηται προς αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Ο Μωϋσής λοιπόν ανέβη επί το όρος, και η νεφέλη εσκέπασε το όρος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Και εκάθησεν η δόξα του Κυρίου επί του όρους Σινά, και η νεφέλη εσκέπασεν αυτό εξ ημέρας· και την εβδόμην ημέραν εκάλεσεν ο Κύριος τον Μωϋσήν εκ μέσου της νεφέλης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Και η θέα της δόξης του Κυρίου ήτο, εις τους οφθαλμούς των υιών Ισραήλ, ως πυρ κατατρώγον επί της κορυφής του όρους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Και εισήλθεν ο Μωϋσής εις το μέσον της νεφέλης και ανέβη επί το όρος· και εστάθη ο Μωϋσής επί του όρους τεσσαράκοντα ημέρας και τεσσαράκοντα νύκτας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Ειπέ προς τους υιούς Ισραήλ να φέρωσι προς εμέ προσφοράν· παρά παντός ανθρώπου προαιρουμένου εν τη καρδία αυτού θέλετε λάβει την προσφοράν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Και αύτη είναι η προσφορά, την οποίαν θέλετε λάβει παρ\' αυτών· χρυσίον και αργύριον και χαλκός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'και κυανούν και πορφυρούν και κόκκινον και βύσσος και τρίχες αιγών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'και δέρματα κριών κοκκινοβαφή και δέρματα θώων και ξύλον σιττίμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'έλαιον διά το φως, αρώματα διά το έλαιον του χρίσματος και διά το ευώδες θυμίαμα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'λίθοι ονυχίται και λίθοι διά να εντεθώσιν εις το εφόδ και εις το περιστήθιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Και ας κάμωσιν εις εμέ αγιαστήριον, διά να κατοικώ μεταξύ αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Κατά πάντα όσα εγώ δεικνύω προς σε, κατά το παράδειγμα της σκηνής, και κατά το παράδειγμα πάντων των σκευών αυτής, ούτω θέλετε κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Και θέλουσι κατασκευάσει κιβωτόν εκ ξύλου σιττίμ· δύο πηχών και ημισείας το μήκος αυτής, και μιας πήχης και ημισείας το πλάτος αυτής, και μιας πήχης και ημισείας το ύψος αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'και θέλεις περικαλύψει αυτήν με καθαρόν χρυσίον, έσωθεν και έξωθεν θέλεις περικαλύψει αυτήν, και επ\' αυτής θέλεις κάμει χρυσήν στεφάνην κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Και θέλεις χύσει δι\' αυτήν τέσσαρας κρίκους χρυσούς και θέλεις βάλει αυτούς εις τας τέσσαρας γωνίας αυτής· δύο μεν κρίκους εις την μίαν πλευράν αυτής, δύο δε κρίκους εις την άλλην πλευράν αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Και θέλεις κάμει μοχλούς εκ ξύλου σιττίμ, και θέλεις περικαλύψει αυτούς με χρυσίον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'και θέλεις εισάξει τους μοχλούς εις τους κρίκους των πλευρών της κιβωτού, διά να βαστάζηται η κιβωτός δι\' αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'εν τοις κρίκοις της κιβωτού θέλουσι μένει οι μοχλοί· δεν θέλουσι μετακινείσθαι απ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'και θέλεις θέσει εν τη κιβωτώ τα μαρτύρια τα οποία θέλω δώσει εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Και θέλεις κάμει ιλαστήριον εκ χρυσίου καθαρού· δύο πηχών και ημισείας το μήκος αυτού, και μιας πήχης και ημισείας το πλάτος αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Και θέλεις κάμει δύο χερουβείμ εκ χρυσίου· σφυρήλατα θέλεις κάμει αυτά, επί των δύο άκρων του ιλαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'και κάμε εν χερούβ επί του ενός άκρου, και εν χερούβ επί του άλλου άκρου· εκ του ιλαστηρίου θέλεις κάμει τα χερουβείμ επί των δύο άκρων αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'και θέλουσιν εκτείνει τα χερουβείμ επάνωθεν τας πτέρυγας, επικαλύπτοντα με τας πτέρυγας αυτών το ιλαστήριον· και τα πρόσωπα αυτών θέλουσι βλέπει το εν προς το άλλο· προς το ιλαστήριον θέλουσιν είσθαι τα πρόσωπα των χερουβείμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Και θέλεις επιθέσει το ιλαστήριον επί της κιβωτού άνωθεν· και θέλεις θέσει εν τη κιβωτώ τα μαρτύρια, τα οποία θέλω δώσει εις σέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'και εκεί θέλω γνωρισθή προς σέ· και επάνωθεν του ιλαστηρίου, εκ του μέσου των δύο χερουβείμ, των επί της κιβωτού του μαρτυρίου, θέλω λαλήσει προς σε περί πάντων όσα θέλω προστάξει εις σε να είπης προς τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Και θέλεις κάμει τράπεζαν εκ ξύλου σιττίμ· δύο πηχών το μήκος αυτής, και μιας πήχης το πλάτος αυτής, το δε ύψος αυτής μιας πήχης και ημισείας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'και θέλεις περικαλύψει αυτήν με χρυσίον καθαρόν, και θέλεις κάμει εις αυτήν χρυσήν στεφάνην κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Και θέλεις κάμει εις αυτήν χείλος κύκλω μιας παλάμης το πλάτος και θέλεις κάμει επί το χείλος αυτής στεφάνην χρυσήν κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Και θέλεις κάμει εις αυτήν τέσσαρας κρίκους χρυσούς και θέλεις βάλει τους κρίκους επί τας τέσσαρας γωνίας, τας επί των τεσσάρων ποδών αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'οι κρίκοι θέλουσιν είσθαι υπό το χείλος θήκαι των μοχλών, διά να βαστάζηται η τράπεζα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Και θέλεις κάμει τους μοχλούς εκ ξύλου σιττίμ, και θέλεις περικαλύψει αυτούς με χρυσίον, διά να βαστάζηται η τράπεζα δι\' αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Και θέλεις κάμει τους δίσκους αυτής και τους θυμιαματοδόχους αυτής και τα σπονδεία αυτής και τας λεκάνας αυτής, διά να γίνωνται δι\' αυτών αι σπονδαί· εκ χρυσίου καθαρού θέλεις κάμει αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Και θέλεις θέσει επί της τραπέζης άρτους προθέσεως ενώπιόν μου διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Και θέλεις κάμει λυχνίαν εκ χρυσίου καθαρού· σφυρήλατον θέλεις κάμει την λυχνίαν· ο κορμός αυτής και οι κλάδοι αυτής, αι λεκάναι αυτής, οι κόμβοι αυτής και τα άνθη αυτής, θέλουσιν είσθαι εν σώμα μετ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Και θέλουσιν εξέρχεσθαι εξ κλάδοι εκ των πλαγίων αυτής· τρεις κλάδοι της λυχνίας εκ του ενός πλαγίου, και τρεις κλάδοι της λυχνίας εκ του άλλου πλαγίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'εις τον ένα κλάδον θέλουσιν είσθαι τρεις λεκάναι αμυγδαλοειδείς, εις κόμβος και εν άνθος· και εις τον άλλον κλάδον τρεις λεκάναι αμυγδαλοειδείς, εις κόμβος και εν άνθος· ούτω θέλει γείνει εις τους εξ κλάδους, τους εξερχομένους εκ της λυχνίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Και εις την λυχνίαν θέλουσιν είσθαι τέσσαρες λεκάναι αμυγδαλοειδείς, οι κόμβοι αυτών και τα άνθη αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Και θέλει είσθαι εις κόμβος υπό τους δύο κλάδους εξ αυτής, και εις κόμβος υπό τους δύο κλάδους εξ αυτής, και εις κόμβος υπό τους δύο κλάδους εξ αυτής, εις τους εξ κλάδους τους εξερχομένους εκ της λυχνίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Οι κόμβοι αυτών και οι κλάδοι αυτών θέλουσιν είσθαι εν σώμα μετ\' αυτής· το όλον αυτής εν σφυρήλατον εκ χρυσίου καθαρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Και θέλεις κάμει τους λύχνους αυτής επτά· και θέλουσιν ανάπτει τους λύχνους αυτής, διά να φέγγωσιν έμπροσθεν αυτής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Και τα λυχνοψάλιδα αυτής και τα υποθέματα αυτής θέλουσιν είσθαι εκ χρυσίου καθαρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Εξ ενός ταλάντου χρυσίου καθαρού θέλει κατασκευασθή αυτή και πάντα ταύτα τα σκεύη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Και πρόσεχε να κάμης κατά τον τύπον αυτών τον δειχθέντα εις σε επί του όρους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Και θέλεις κάμει την σκηνήν, δέκα παραπετάσματα εκ βύσσου κεκλωσμένης και κυανού και πορφυρού και κοκκίνου· με χερουβείμ εντέχνως ενειργασμένα θέλεις κάμει αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Το μήκος του ενός παραπετάσματος εικοσιοκτώ πηχών, και το πλάτος του ενός παραπετάσματος τεσσάρων πηχών· πάντα τα παραπετάσματα του αυτού μέτρου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Τα πέντε παραπετάσματα θέλουσι συνάπτεσθαι το εν μετά του άλλου· και τα άλλα πέντε παραπετάσματα θέλουσι συνάπτεσθαι το εν μετά του άλλου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Και θέλεις κάμει θηλυκωτήρια κυανά επί της άκρας του πρώτου παραπετάσματος, κατά το πλάγιον όπου γίνεται η ένωσις· ομοίως θέλεις κάμει και επί της τελευταίας άκρας του δευτέρου παραπετάσματος, όπου γίνεται η ένωσις του δευτέρου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'πεντήκοντα θηλυκωτήρια θέλεις κάμει εις το εν παραπέτασμα, και πεντήκοντα θηλυκωτήρια θέλεις κάμει εις την άκραν του παραπετάσματος την κατά την ένωσιν του δευτέρου, διά να αντικρύζωσι τα θηλυκωτήρια προς άλληλα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Και θέλεις κάμει πεντήκοντα περόνας χρυσάς, και με τας περόνας θέλεις συνάψει τα παραπετάσματα προς άλληλα· ούτως η σκηνή θέλει είσθαι μία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Και θέλεις κάμει παραπετάσματα εκ τριχών αιγών, διά να ήναι κάλυμμα επί της σκηνής· ένδεκα θέλεις κάμει τα παραπετάσματα ταύτα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'το μήκος του ενός παραπετάσματος τριάκοντα πηχών, και το πλάτος του ενός παραπετάσματος τεσσάρων πηχών· του αυτού μέτρου θέλουσιν είσθαι τα ένδεκα παραπετάσματα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Και θέλεις συνάψει τα πέντε παραπετάσματα χωριστά, και τα εξ παραπετάσματα χωριστά· το έκτον όμως παραπέτασμα θέλεις επιδιπλώσει κατά το πρόσωπον της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Και θέλεις κάμει πεντήκοντα θηλυκωτήρια επί της άκρας του ενός παραπετάσματος του τελευταίου κατά την ένωσιν, και πεντήκοντα θηλυκωτήρια επί της άκρας του παραπετάσματος, το οποίον ενόνεται με το δεύτερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Θέλεις κάμει και πεντήκοντα περόνας χαλκίνας, και θέλεις εμβάλει τας περόνας εις τα θηλυκωτήρια, και θέλεις συνάψει την σκηνήν, ώστε να ήναι μία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Το δε υπόλοιπον, το περισσεύον εκ των παραπετασμάτων της σκηνής, το ήμισυ του παραπετάσματος του εναπολειπομένου, θέλει κρέμασθαι επί τα όπισθεν της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Και μία πήχη εκ του ενός πλαγίου και μία πήχη εκ του άλλου πλαγίου εκ του εναπολειπομένου εις το μήκος των παραπετασμάτων της σκηνής θέλει κρέμασθαι επάνωθεν επί τα πλάγια της σκηνής εντεύθεν και εντεύθεν, διά να καλύπτη αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Και θέλεις κάμει κατακάλυμμα διά την σκηνήν εκ δερμάτων κριών κοκκινοβαφών και επικάλυμμα υπεράνωθεν εκ δερμάτων θώων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Και θέλεις κάμει διά την σκηνήν σανίδας εκ ξύλου σιττίμ ορθίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'δέκα πηχών το μήκος της μιας σανίδος, και μιας πήχης και ημισείας το πλάτος της μιας σανίδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Δύο αγκωνίσκοι θέλουσιν είσθαι εις την μίαν σανίδα αντικρύζοντες προς αλλήλους· ούτω θέλεις κάμει εις πάσας τας σανίδας της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Και θέλεις κάμει τας σανίδας διά την σκηνήν, είκοσι σανίδας από το νότιον μέρος προς μεσημβρίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'και υποκάτω των είκοσι σανίδων θέλεις κάμει τεσσαράκοντα υποβάσια αργυρά· δύο υποβάσια υποκάτω της μιας σανίδος διά τους δύο αγκωνίσκους αυτής, και δύο υποβάσια υποκάτω της άλλης σανίδος διά τους δύο αγκωνίσκους αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Και διά το δεύτερον μέρος της σκηνής το προς βορράν, θέλεις κάμει είκοσι σανίδας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'και τα τεσσαράκοντα αυτών υποβάσια αργυρά, δύο υποβάσια υποκάτω της μιας σανίδος, και δύο υποβάσια υποκάτω της άλλης σανίδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Και διά τα όπισθεν μέρη της σκηνής τα προς δυσμάς θέλεις κάμει εξ σανίδας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Θέλεις κάμει και δύο σανίδας διά τας γωνίας της σκηνής εις τα όπισθεν μέρη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'και θέλουσιν ενωθή κάτωθεν και θέλουσιν ενωθή ομού άνωθεν δι\' ενός κρίκου· ούτω θέλει είσθαι δι\' αυτάς αμφοτέρας· διά τας δύο γωνίας θέλουσιν είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'και θέλουσιν είσθαι οκτώ σανίδες και τα αργυρά υποβάσια αυτών, δεκαέξ υποβάσια· δύο υποβάσια υποκάτω της μιας σανίδος και δύο υποβάσια υποκάτω της άλλης σανίδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Και θέλεις κάμει μοχλούς εκ ξύλου σιττίμ· πέντε διά τας σανίδας του ενός μέρους της σκηνής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'και πέντε μοχλούς διά τας σανίδας του άλλου μέρους της σκηνής, και πέντε μοχλούς διά τας σανίδας του μέρους της σκηνής διά το πλάγιον το προς δυσμάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'και ο μέσος μοχλός, ο εν τω μέσω των σανίδων, θέλει διαπερά απ\' άκρου έως άκρου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Και τας σανίδας θέλεις περικαλύψει με χρυσίον και τους κρίκους αυτών θέλεις κάμει χρυσούς, διά να ήναι θήκαι των μοχλών. και θέλεις περικαλύψει τους μοχλούς με χρυσίον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Και θέλεις ανεγείρει την σκηνήν κατά το σχέδιον αυτής το δειχθέν εις σε επί του όρους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Και θέλεις κάμει καταπέτασμα εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης, εντέχνου εργασίας· με χερουβείμ θέλει είσθαι κατεσκευασμένον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Και θέλεις κρεμάσει αυτό επί τεσσάρων στύλων εκ σιττίμ περικεκαλυμμένων με χρυσίον· τα άγκιστρα αυτών θέλουσιν είσθαι χρυσά, επί των τεσσάρων αργυρών υποβασίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Και θέλεις κρεμάσει το καταπέτασμα υπό τας περόνας, διά να φέρης εκεί, έσωθεν του καταπετάσματος, την κιβωτόν του μαρτυρίου· και το καταπέτασμα θέλει κάμνει εις εσάς χώρισμα μεταξύ του αγίου και του αγίου των αγίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Και θέλεις επιθέσει το ιλαστήριον επί της κιβωτού του μαρτυρίου εν τω αγίω των αγίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Και θέλεις θέσει την τράπεζαν έξωθεν του καταπετάσματος και την λυχνίαν αντικρύ της τραπέζης προς το νότιον μέρος της σκηνής· την δε τράπεζαν θέλεις θέσει προς το βόρειον μέρος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Και θέλεις κάμει διά την θύραν της σκηνής τάπητα εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης, κατεσκευασμένον με εργασίαν κεντητού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Και θέλεις κάμει διά τον τάπητα πέντε στύλους εκ σιττίμ, και θέλεις περικαλύψει αυτούς με χρυσίον· τα άγκιστρα αυτών θέλουσιν είσθαι χρυσά· και θέλεις χύσει δι\' αυτούς πέντε υποβάσια χάλκινα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Και θέλεις κάμει θυσιαστήριον εκ ξύλου σιττίμ, πέντε πηχών το μήκος και πέντε πηχών το πλάτος· τετράγωνον θέλει είσθαι το θυσιαστήριον· και το ύψος αυτού τριών πηχών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'και θέλεις κάμει τα κέρατα αυτού επί των τεσσάρων γωνιών αυτού· τα κέρατα αυτού θέλουσιν είσθαι εκ του αυτού και θέλεις περικαλύψει αυτό με χαλκόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Και θέλεις κάμει τους στακτοδόχους λέβητας αυτού και τα πτυάρια αυτού και τας λεκάνας αυτού και τας κρεάγρας αυτού και τα πυροδόχα αυτού· χάλκινα θέλεις κάμει πάντα τα σκεύη αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Και θέλεις κάμει δι\' αυτό χαλκίνην εσχάραν δικτυωτής εργασίας· και επί του δικτύου θέλεις κάμει τέσσαρας κρίκους χαλκίνους επί των τεσσάρων γωνιών αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Και θέλεις θέσει αυτήν υπό την περιοχήν του θυσιαστηρίου κάτωθεν, ώστε το δίκτυον να ήναι μέχρι του μέσου του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Και θέλεις κάμει μοχλούς διά το θυσιαστήριον, μοχλούς εκ ξύλου σιττίμ, και θέλεις περικαλύψει αυτούς με χαλκόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'και οι μοχλοί θέλουσι τεθή εντός των κρίκων και θέλουσιν είσθαι οι μοχλοί επί των δύο πλευρών του θυσιαστηρίου, διά να βαστάζωσιν αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Κοίλον σανιδωτόν θέλεις κάμει αυτό, καθώς εδείχθη εις σε επί του όρους· ούτω θέλουσι κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Και θέλεις κάμει την αυλήν της σκηνής· από το νότιον μέρος προς μεσημβρίαν θέλουσιν είσθαι παραπετάσματα διά την αυλήν εκ βύσσου κεκλωσμένης, το μήκος εκατόν πηχών διά το εν πλευρόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Και οι είκοσι στύλοι αυτής και τα είκοσι υποβάσια τούτων θέλουσιν είσθαι χάλκινα· τα άγκιστρα των στύλων και αι ζώναι αυτών αργυρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Και ομοίως κατά το βόρειον πλευρόν κατά μήκος θέλουσιν είσθαι παραπετάσματα, μήκος εκατόν πηχών, και οι είκοσι στύλοι αυτών και τα είκοσι αυτών χάλκινα υποβάσια· τα δε άγκιστρα των στύλων και αι ζώναι αυτών αργυρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Και διά το πλάτος της αυλής κατά το δυτικόν πλευρόν θέλουσιν είσθαι παραπετάσματα πεντήκοντα πηχών· στύλοι αυτών δέκα και υποβάσια αυτών δέκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Και το πλάτος της αυλής κατά το ανατολικόν πλευρόν το προς ανατολάς θέλει είσθαι πεντήκοντα πηχών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Και τα παραπετάσματα του ενός μέρους της πύλης θέλουσιν είσθαι δεκαπέντε πηχών· στύλοι αυτών τρεις και υποβάσια αυτών τρία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Και εις το άλλο μέρος θέλουσιν είσθαι παραπετάσματα δεκαπέντε πηχών· στύλοι αυτών τρεις και υποβάσια αυτών τρία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Διά δε την πύλην της αυλής θέλει είσθαι καταπέτασμα είκοσι πηχών, εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης, κατεσκευασμένον με εργασίαν κεντητού· στύλοι αυτών τέσσαρες και υποβάσια τούτων τέσσαρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Πάντες οι στύλοι κύκλω της αυλής θέλουσιν είσθαι εζωσμένοι με άργυρον, τα άγκιστρα αυτών αργυρά και τα υποβάσια αυτών χάλκινα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Το μήκος της αυλής θέλει είσθαι εκατόν πηχών και το πλάτος εκατέρωθεν πεντήκοντα και το ύψος πέντε πηχών, εκ βύσσου κεκλωσμένης, και τα υποβάσια αυτών χάλκινα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Πάντα τα σκεύη της σκηνής διά πάσαν την υπηρεσίαν αυτής και πάντες οι πάσσαλοι αυτής και πάντες οι πάσσαλοι της αυλής θέλουσιν είσθαι χάλκινοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Και συ πρόσταξον τους υιούς Ισραήλ να φέρωσι προς σε καθαρόν έλαιον από ελαίας κοπανισμένας διά το φως, διά να καίη πάντοτε ο λύχνος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Εν τη σκηνή του μαρτυρίου έξωθεν του καταπετάσματος, το οποίον είναι έμπροσθεν του μαρτυρίου, ο Ααρών και οι υιοί αυτού θέλουσι διαθέσει αυτόν αφ\' εσπέρας έως πρωΐ έμπροσθεν του Κυρίου· τούτο θέλει είσθαι νόμος παντοτεινός εις τους υιούς Ισραήλ κατά τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Και συ προσάγαγε προς σεαυτόν Ααρών τον αδελφόν σου και τους υιούς αυτού μετ\' αυτού, εκ μέσου των υιών Ισραήλ, διά να ιερατεύωσιν εις εμέ, Ααρών, Ναδάβ και Αβιούδ, Ελεάζαρ και Ιθάμαρ, τους υιούς του Ααρών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Και θέλεις κάμει στολήν αγίαν εις τον Ααρών τον αδελφόν σου προς δόξαν και τιμήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Και συ λάλησον προς πάντας τους σοφούς την καρδίαν, τους οποίους εγώ ενέπλησα από πνεύματος σοφίας, να κάμωσι την στολήν του Ααρών, διά να καθιερώσης αυτόν, ώστε να ιερατεύη εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Και αύτη είναι η στολή την οποίαν θέλουσι κάμει· περιστήθιον και εφόδ και ποδήρης και χιτών κεντητός, μίτρα και ζώνη· και θέλουσι κάμει στολάς αγίας εις τον Ααρών τον αδελφόν σου, και εις τους υιούς αυτού, διά να ιερατεύωσιν εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Και αυτοί θέλουσι λάβει το χρυσίον και το κυανούν και το πορφυρούν και το κόκκινον και την βύσσον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Και θέλουσι κάμει το εφόδ εκ χρυσίου, εκ κυανού και πορφυρού, εκ κοκκίνου και βύσσου κεκλωσμένης, εντέχνου εργασίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'θέλει έχει τας δύο επωμίδας αυτού συναπτάς κατά τα δύο άκρα αυτού, ώστε να συνάπτωνται.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Και η κεντητή ζώνη του εφόδ, η επ\' αυτό, θέλει είσθαι εκ του αυτού, κατά την εργασίαν αυτού· εκ χρυσίου, εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Και θέλεις λάβει δύο ονυχίτας λίθους, και θέλεις εγχαράξει επ\' αυτούς τα ονόματα των υιών Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'εξ εκ των ονομάτων αυτών επί του ενός λίθου και τα λοιπά εξ ονόματα επί του άλλου λίθου, κατά τας γενέσεις αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'με εργασίαν λιθογλύφου κατά την γλυφήν της σφραγίδος, θέλεις εγχαράξει τους δύο λίθους με τα ονόματα των υιών Ισραήλ· θέλεις εναρμόσει αυτούς εις χρυσούς οικίσκους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Και θέλεις θέσει τους δύο λίθους επί των επωμίδων του εφόδ, λίθους μνημοσύνης εις τους υιούς Ισραήλ· και ο Ααρών θέλει βαστάζει τα ονόματα αυτών ενώπιον του Κυρίου επί των δύο ώμων αυτού εις μνημόσυνον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Και θέλεις κάμει οικίσκους χρυσούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'και δύο αλύσεις εκ καθαρού χρυσίου επί των άκρων· εργασίαν πλεκτήν θέλεις κάμει αυτάς, και θέλεις συνάψει τας πλεκτάς αλύσεις με τους οικίσκους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Και θέλεις κάμει το περιστήθιον της κρίσεως εντέχνου εργασίας· κατά την εργασίαν του εφόδ θέλεις κάμει αυτό· εκ χρυσίου, κυανού, και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης θέλεις κάμει αυτό·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'τετράγωνον θέλει είσθαι διπλούν· μιας σπιθαμής το μήκος αυτού και μιας σπιθαμής το πλάτος αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Και θέλεις εναρμόσει εις αυτό λίθους, τέσσαρας σειράς λίθων· σειρά σαρδίου, τοπαζίου και σμαράγδου θέλει είσθαι πρώτη σειρά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'και η δευτέρα σειρά, άνθραξ, σάπφειρος και αδάμας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'και η τρίτη σειρά, λιγύριον, αχάτης και αμέθυστος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'και η τετάρτη σειρά, βηρύλλιον και όνυξ και ίασπις· ενηρμοσμένοι θέλουσιν είσθαι εις τους χρυσούς οικίσκους αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'και οι λίθοι θέλουσιν είσθαι με τα ονόματα των υιών Ισραήλ, δώδεκα, κατά τα ονόματα αυτών, κατά την γλυφήν της σφραγίδος· έκαστος με το όνομα αυτού θέλουσιν είσθαι κατά τας δώδεκα φυλάς');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Και θέλεις κάμει επί το περιστήθιον αλύσεις κατά τα άκρα, πλεκτής εργασίας εκ χρυσίου καθαρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Και θέλεις κάμει επί το περιστήθιον δύο κρίκους χρυσούς, και θέλεις περάσει τους δύο κρίκους εις τα δύο άκρα του περιστηθίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Και θέλεις περάσει τας δύο πλεκτάς αλύσεις χρυσάς εις τους δύο κρίκους, τους εις τα άκρα του περιστηθίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Και τα άλλα δύο άκρα των δύο πλεκτών αλύσεων θέλεις συνάψει με τους δύο οικίσκους και θέλεις βάλει αυτούς εις τας επωμίδας του εφόδ έμπροσθεν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Και θέλεις κάμει δύο κρίκους χρυσούς και θέλεις βάλει αυτούς επί των δύο άκρων του περιστηθίου εις το χείλος αυτού, το οποίον είναι κατά το μέρος του εφόδ έσωθεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'και θέλεις κάμει δύο άλλους κρίκους χρυσούς, και θέλεις βάλει αυτούς εις τα δύο πλάγια του εφόδ κάτωθεν, προς το εμπροσθινόν μέρος αυτού, αντικρύ της άλλης ενώσεως αυτού, άνωθεν της κεντητής ζώνης του εφόδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Και θέλουσι δένει το περιστήθιον διά των κρίκων αυτού εις τους κρίκους του εφόδ με ταινίαν εκ κυανού, διά να ήναι άνωθεν της κεντητής ζώνης του εφόδ και διά να μη ήναι το περιστήθιον κεχωρισμένον από του εφόδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Και ο Ααρών θέλει βαστάζει τα ονόματα των υιών Ισραήλ εν τω περιστηθίω της κρίσεως επί της καρδίας αυτού, όταν εισέρχηται εις το άγιον, εις μνημόσυνον ενώπιον του Κυρίου διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Και θέλεις βάλει εις το περιστήθιον της κρίσεως το Ουρίμ και το Θουμμίμ, και θέλουσιν είσθαι επί της καρδίας του Ααρών, όταν εισέρχηται ενώπιον του Κυρίου· και ο Ααρών θέλει βαστάζει την κρίσιν των υιών Ισραήλ επί της καρδίας αυτού ενώπιον του Κυρίου διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Και θέλεις κάμει τον ποδήρη του εφόδ όλον εκ κυανού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Και θέλει είσθαι εις την κορυφήν αυτού άνοιγμα κατά το μέσον αυτού· θέλει έχει ταινίαν υφαντήν κύκλω του ανοίγματος αυτού, καθώς είναι το άνοιγμα του θώρακος, διά να μη σχίζηται.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Και θέλεις κάμει επί των κρασπέδων αυτού ρόδια εκ κυανού και πορφυρού και κοκκίνου επί των κρασπέδων αυτού κύκλω· και κώδωνας χρυσούς μεταξύ αυτών κύκλω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'χρυσούν κώδωνα και ρόδιον, χρυσούν κώδωνα και ρόδιον, επί των κρασπέδων του ποδήρους κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Και θέλει είσθαι επί του Ααρών διά να λειτουργή· και ο ήχος αυτού θέλει είσθαι ακουστός, όταν εισέρχηται εις το άγιον ενώπιον του Κυρίου και όταν εξέρχηται, διά να μη αποθάνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Και θέλεις κάμει πέταλον εκ χρυσίου καθαρού και θέλεις εγχαράξει επ\' αυτό, ως χάραγμα σφραγίδος, ΑΓΙΑΣΜΟΣ ΕΙΣ ΤΟΝ ΚΥΡΙΟΝ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Και θέλεις βάλει αυτό επί κυανής ταινίας, διά να ήναι επί της μίτρας· εις το έμπροσθεν μέρος της μίτρας θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Και θέλει είσθαι επί του μετώπου του Ααρών, διά να σηκόνη ο Ααρών την ανομίαν των αγίων πραγμάτων, τα οποία οι υιοί του Ισραήλ θέλουσιν αγιάζει εις πάσας αυτών τας αγίας προσφοράς· και θέλει είσθαι διαπαντός επί του μετώπου αυτού, διά να ήναι δεκταί ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Και θέλεις υφάνει τον χιτώνα εκ βύσσου και θέλεις κάμει μίτραν εκ βύσσου και θέλεις κάμει ζώνην εργασίας κεντητού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Και διά τους υιούς του Ααρών θέλεις κάμει χιτώνας και θέλεις κάμει δι\' αυτούς ζώνας και μιτρίδια θέλεις κάμει δι\' αυτούς προς δόξαν και τιμήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Και θέλεις ενδύσει αυτά τον Ααρών τον αδελφόν σου και τους υιούς αυτού μετ\' αυτού, και θέλεις χρίσει αυτούς και θέλεις καθιερώσει αυτούς και αγιάσει αυτούς, διά να ιερατεύωσιν εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Και θέλεις κάμει εις αυτούς λινά περισκελή, διά να σκεπάζωσι την γύμνωσιν της σαρκός αυτών· από της οσφύος μέχρι των μηρών θέλουσι φθάνει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'και θέλουσιν είσθαι επί του Ααρών και επί των υιών αυτού, όταν εισέρχωνται εις την σκηνήν του μαρτυρίου ή όταν πλησιάζωσιν εις το θυσιαστήριον διά να λειτουργήσωσιν εν τω αγίω, διά να μη φέρωσιν εφ\' εαυτούς ανομίαν και αποθάνωσι τούτο θέλει είσθαι νόμος παντοτεινός εις αυτόν και εις το σπέρμα αυτού μετ\' αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Και τούτο είναι το πράγμα, το οποίον θέλεις κάμει εις αυτούς διά να αγιάσης αυτούς, ώστε να ιερατεύωσιν εις εμέ. Λάβε εν μοσχάριον βοός και δύο κριούς αμώμους,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'και άζυμον άρτον και πήττας αζύμους εζυμωμένας με έλαιον και λάγανα άζυμα κεχρισμένα με έλαιον· εκ σεμιδάλεως σίτου θέλεις κάμει αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Και θέλεις βάλει αυτά εις εν κάνιστρον και θέλεις φέρει αυτά εν τω κανίστρω μετά του μοσχαρίου και των δύο κριών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Και τον Ααρών και τους υιούς αυτού θέλεις προσαγάγει εις την θύραν της σκηνής του μαρτυρίου και θέλεις λούσει αυτούς εν ύδατι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Και θέλεις λάβει τας στολάς και θέλεις ενδύσει τον Ααρών τον χιτώνα και τον ποδήρη του εφόδ και το εφόδ και το περιστήθιον, και θέλεις ζώσει αυτόν με την κεντητήν ζώνην του εφόδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Και θέλεις βάλει την μίτραν επί την κεφαλήν αυτού και θέλεις βάλει το άγιον διάδημα επί την μίτραν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Τότε θέλεις λάβει το έλαιον του χρίσματος και θέλεις χύσει εξ αυτού επί την κεφαλήν αυτού και θέλεις χρίσει αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Και θέλεις προσαγάγει τους υιούς αυτού και ενδύσει αυτούς χιτώνας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'και θέλεις ζώσει αυτούς με ζώνας, τον Ααρών και τους υιούς αυτού, και θέλεις περιθέσει εις αυτούς μιτρίδια, και η ιερατεία θέλει είσθαι εις αυτούς κατά νόμον παντοτεινόν· και θέλεις καθιερώσει τον Ααρών και τους υιούς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Και θέλεις προσαγάγει το μοσχάριον έμπροσθεν της σκηνής του μαρτυρίου, και ο Ααρών και οι υιοί αυτού θέλουσιν επιθέσει τας χείρας αυτών επί την κεφαλήν του μοσχαρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'και θέλεις σφάξει το μοσχάριον ενώπιον Κυρίου παρά την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Και θέλεις λάβει εκ του αίματος του μοσχαρίου και θέσει επί των κεράτων του θυσιαστηρίου με τον δάκτυλόν σου· και θέλεις χύσει όλον το αίμα παρά την βάσιν του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Και θέλεις λάβει όλον το στέαρ το περικαλύπτον τα εντόσθια και τον επάνω λοβόν του ήπατος και τους δύο νεφρούς και το στέαρ το επ\' αυτών και θέλεις καύσει αυτά επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Το δε κρέας του μοσχαρίου και το δέρμα αυτού και την κόπρον αυτού θέλεις καύσει εν πυρί έξω του στρατοπέδου· τούτο είναι θυσία περί αμαρτίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Και τον κριόν τον ένα θέλεις λάβει, και θέλουσιν επιθέσει ο Ααρών και οι υιοί αυτού τας χείρας αυτών επί την κεφαλήν του κριού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'και θέλεις σφάξει τον κριόν και θέλεις λάβει το αίμα αυτού και ραντίσει επί το θυσιαστήριον κύκλω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'και θέλεις διαμελίσει τον κριόν εις τμήματα και θέλεις πλύνει τα εντόσθια αυτού και τους πόδας αυτού, και βάλει αυτά μετά των τμημάτων αυτού και μετά της κεφαλής αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'και θέλεις καύσει όλον τον κριόν επί του θυσιαστηρίου· τούτο είναι ολοκαύτωμα εις τον Κύριον· είναι οσμή ευωδίας, θυσία γινομένη διά πυρός εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Και θέλεις λάβει τον δεύτερον κριόν· και θέλουσιν επιθέσει ο Ααρών και οι υιοί αυτού τας χείρας αυτών επί την κεφαλήν του κριού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'τότε θέλεις σφάξει τον κριόν και θέλεις λάβει εκ του αίματος αυτού και θέσει επί τον λοβόν του δεξιού ωτίου του Ααρών, και επί τον λοβόν του δεξιού ωτίου των υιών αυτού, και επί τον αντίχειρα της δεξιάς χειρός αυτών, και επί τον μεγάλον δάκτυλον του δεξιού ποδός αυτών, και θέλεις ραντίσει το αίμα επί το θυσιαστήριον κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Και θέλεις λάβει εκ του αίματος, του επί του θυσιαστηρίου, και εκ του ελαίου του χρίσματος, και θέλεις ραντίσει επί τον Ααρών, και επί τας στολάς αυτού και επί τους υιούς αυτού και επί τας στολάς των υιών αυτού μετ\' αυτού· και θέλουσιν αγιασθή, αυτός, και αι στολαί αυτού, και οι υιοί αυτού, και αι στολαί των υιών αυτού μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Και θέλεις λάβει εκ του κριού το στέαρ και την ουράν και το στέαρ το περικαλύπτον τα εντόσθια και τον επάνω λοβόν του ήπατος και τους δύο νεφρούς, και το στέαρ το επ\' αυτών και τον δεξιόν βραχίονα, διότι είναι κριός καθιερώσεως,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'και ένα ψωμόν, και μίαν πήτταν ελαιωμένην, και εν λάγανον εκ του κανίστρου των αζύμων των προτεθειμένων ενώπιον Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'και θέλεις επιθέσει τα πάντα εις τας χείρας του Ααρών και εις τας χείρας των υιών αυτού· και θέλεις κινήσει αυτά εις κινητήν προσφοράν ενώπιον Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Και θέλεις λάβει αυτά εκ των χειρών αυτών και καύσει επί του θυσιαστηρίου επάνω του ολοκαυτώματος εις οσμήν ευωδίας ενώπιον Κυρίου· τούτο είναι θυσία γινομένη διά πυρός εις τον Κύριον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Και θέλεις λάβει το στήθος εκ του κριού της καθιερώσεως, όστις είναι διά τον Ααρών, και θέλεις κινήσει αυτό εις κινητήν προσφοράν ενώπιον Κυρίου και θέλει είσθαι μερίδιόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Και θέλεις αγιάσει το στήθος της κινητής προσφοράς και τον βραχίονα της προσφοράς της υψώσεως, ήτις εκινήθη και ήτις υψώθη, εκ του κριού της καθιερώσεως, εξ εκείνου όστις είναι διά τον Ααρών, και εξ εκείνου όστις είναι διά τους υιούς αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'και θέλει είσθαι του Ααρών και των υιών αυτού κατά νόμον παντοτεινόν παρά των υιών Ισραήλ· διότι είναι προσφορά υψώσεως· και θέλει είσθαι προσφορά υψώσεως παρά των υιών Ισραήλ εκ των ειρηνικών θυσιών αυτών, η υψουμένη προσφορά αυτών προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Και η αγία στολή του Ααρών θέλει είσθαι των υιών αυτού μετ\' αυτόν, διά να χρισθώσιν εν αυτή και να καθιερωθώσιν εν αυτή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Επτά ημέρας θέλει ενδύεσθαι αυτήν ο ιερεύς, ο αντ\' αυτού εκ των υιών αυτού, όστις εισέρχεται εις την σκηνήν του μαρτυρίου διά να λειτουργήση εν τω αγίω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Και θέλεις λάβει τον κριόν της καθιερώσεως και βράσει το κρέας αυτού εν τόπω αγίω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Και θέλουσι φάγει ο Ααρών και οι υιοί αυτού το κρέας του κριού και τον άρτον τον εν τω κανίστρω παρά την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Και θέλουσι φάγει εκείνα, διά των οποίων έγεινεν η εξιλέωσις, προς καθιέρωσιν και αγιασμόν αυτών· ξένος όμως δεν θέλει φάγει, διότι είναι άγια·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'και αν μείνη τι εκ του κρέατος των καθιερώσεων ή εκ του άρτου έως πρωΐ, τότε θέλεις καύσει το εναπολειφθέν εν πυρί· δεν θέλει φαγωθή, διότι είναι άγιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Και ούτω θέλεις κάμει εις τον Ααρών και εις τους υιούς αυτού κατά πάντα όσα προσέταξα εις σέ· επτά ημέρας θέλεις καθιερώσει αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'και θέλεις προσφέρει πάσαν ημέραν εν μοσχάριον εις προσφοράν περί αμαρτίας διά εξιλέωσιν. Και θέλεις καθαρίζει το θυσιαστήριον, κάμνων εξιλέωσιν υπέρ αυτού, και θέλεις χρίσει αυτό διά να αγιάσης αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Επτά ημέρας θέλεις κάμνει εξιλέωσιν υπέρ του θυσιαστηρίου και θέλεις αγιάζει αυτό· και θέλει είσθαι θυσιαστήριον αγιώτατον· παν το εγγίζον το θυσιαστήριον θέλει είσθαι άγιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Τούτο δε είναι εκείνο, το οποίον θέλεις προσφέρει επί του θυσιαστηρίου· δύο αρνία ενιαύσια την ημέραν διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'το εν αρνίον θέλεις προσφέρει το πρωΐ, και το άλλο αρνίον θέλεις προσφέρει το δειλινόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'και μετά του ενός αρνίου εν δέκατον σεμιδάλεως εζυμωμένης με το τέταρτον ενός ιν ελαίου κοπανισμένου· και το τέταρτον ενός ιν οίνου διά σπονδήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'και το δεύτερον αρνίον θέλεις προσφέρει το δειλινόν· κατά την προσφοράν της πρωΐας, και κατά την σπονδήν αυτής, θέλεις κάμει εις αυτό, εις οσμήν ευωδίας, θυσίαν γινομένην διά πυρός προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'τούτο θέλει είσθαι παντοτεινόν ολοκαύτωμα εις τας γενεάς σας παρά την θύραν της σκηνής του μαρτυρίου ενώπιον Κυρίου· όπου θέλω εμφανίζεσθαι εις σας, διά να λαλώ εκεί προς σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Και εκεί θέλει εμφανίζεσθαι εις τους υιούς Ισραήλ, και η σκηνή θέλει αγιάζεσθαι με την δόξαν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Και θέλω αγιάζει την σκηνήν του μαρτυρίου και το θυσιαστήριον· θέλω αγιάζει και τον Ααρών και τους υιούς αυτού, διά να ιερατεύωσιν εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Και θέλω κατοικεί εν μέσω των υιών Ισραήλ, και θέλω είσθαι Θεός αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Και αυτοί θέλουσι γνωρίζει ότι εγώ είμαι Κύριος ο Θεός αυτών, ο εξαγαγών αυτούς εκ γης Αιγύπτου διά να κατοικώ εν μέσω αυτών· εγώ Κύριος ο Θεός αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Και θέλεις κάμει θυσιαστήριον διά να θυμιάζης θυμίαμα· εκ ξύλου σιττίμ θέλεις κάμει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'μιας πήχης το μήκος αυτού και μιας πήχης το πλάτος αυτού τετράγωνον θέλει είσθαι και δύο πηχών το ύψος αυτού τα κέρατα αυτού εκ του αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Και θέλεις περικαλύψει αυτό με χρυσίον καθαρόν, την κορυφήν αυτού και τα πλάγια αυτού κύκλω και τα κέρατα αυτού και θέλεις κάμει εις αυτό στεφάνην χρυσήν κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Και δύο χρυσούς κρίκους θέλεις κάμει εις αυτό υπό την στεφάνην αυτού· πλησίον των δύο γωνιών αυτού επί τα δύο πλάγια αυτού θέλεις κάμει αυτούς, και θέλουσιν είσθαι θήκαι των μοχλών, ώστε να βαστάζωσιν αυτό δι\' αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Και θέλεις κάμει τους μοχλούς εκ ξύλου σιττίμ, και θέλεις περικαλύψει αυτούς με χρυσίον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Και θέλεις βάλει αυτό απέναντι του καταπετάσματος του ενώπιον της κιβωτού του μαρτυρίου, αντικρύ του ιλαστηρίου του επί του μαρτυρίου, όπου θέλω εμφανίζεσθαι εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Και θέλει θυμιάζει ο Ααρών επ\' αυτού θυμίαμα ευώδες καθ\' εκάστην πρωΐαν· όταν ετοιμάζη τους λύχνους, θέλει θυμιάζει επ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Και όταν ανάπτη ο Ααρών τους λύχνους το εσπέρας, θέλει θυμιάζει επ\' αυτού, θυμίαμα παντοτεινόν ενώπιον του Κυρίου εις τας γενεάς σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'δεν θέλετε προσφέρει επ\' αυτού ξένον θυμίαμα ουδέ ολοκαύτωμα ουδέ προσφοράν εξ αλφίτων ουδέ θέλετε χύσει επ\' αυτού σπονδήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Και θέλει κάμνει ο Ααρών εξιλέωσιν επί των κεράτων αυτού άπαξ του ενιαυτού με το αίμα της περί αμαρτίας προσφοράς της εξιλεώσεως· άπαξ του ενιαυτού θέλει κάμνει εξιλέωσιν επ\' αυτού εις τας γενεάς σας· τούτο είναι αγιώτατον προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Όταν λαμβάνης το κεφάλαιον των υιών Ισραήλ κατά την απαρίθμησιν αυτών, τότε θέλουσι δώσει πας άνθρωπος λύτρον διά την ψυχήν αυτού προς τον Κύριον, όταν απαριθμής αυτούς, διά να μη επέλθη πληγή επ\' αυτούς, όταν απαριθμής αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'τούτο θέλουσι δίδει πας όστις περνά εις την απαρίθμησιν, ήμισυ του σίκλου κατά τον σίκλον του αγίου· ο σίκλος είναι είκοσι γερά· ήμισυ του σίκλου θέλει είσθαι η προσφορά του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'πας όστις περνά εις την απαρίθμησιν, από είκοσι ετών ηλικίας και επάνω, θέλει δώσει προσφοράν εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Ο πλούσιος δεν θέλει δώσει πλειότερον, και ο πτωχός δεν θέλει δώσει ολιγώτερον ημίσεος σίκλου, όταν δίδωσι την προσφοράν εις τον Κύριον διά να κάμωσιν εξιλέωσιν υπέρ των ψυχών υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Και θέλεις λάβει το αργύριον της εξιλεώσεως παρά των υιών Ισραήλ, και θέλεις μεταχειρισθή αυτό εις την υπηρεσίαν της σκηνής του μαρτυρίου, και θέλει είσθαι εις τους υιούς Ισραήλ εις μνημόσυνον ενώπιον του Κυρίου, διά να γείνη εξιλέωσις υπέρ των ψυχών υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Και θέλεις κάμει νιπτήρα χάλκινον και την βάσιν αυτού χαλκίνην, διά να νίπτωνται και θέλεις θέσει αυτόν μεταξύ της σκηνής του μαρτυρίου και του θυσιαστηρίου και θέλεις βάλει ύδωρ εις αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'και θέλουσι νίπτει ο Ααρών και οι υιοί αυτού τας χείρας αυτών και τους πόδας αυτών εξ αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Όταν εισέρχωνται εις την σκηνήν του μαρτυρίου, θέλουσι νίπτεσθαι με ύδωρ, διά να μη αποθάνωσιν· ή όταν πλησιάζωσιν εις το θυσιαστήριον διά να λειτουργήσωσι, διά να καύσωσι θυσίαν γινομένην διά πυρός εις τον Κύριον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'τότε θέλουσι νίπτει τας χείρας αυτών και τους πόδας αυτών, διά να μη αποθάνωσι και τούτο θέλει είσθαι νόμος παντοτεινός εις αυτούς, εις αυτόν και εις το σπέρμα αυτού εις τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Και συ λάβε εις σεαυτόν εκλεκτά αρώματα, καθαράς σμύρνης πεντακοσίους σίκλους και ευώδους κινναμώμου ήμισυ αυτής, διακοσίους πεντήκοντα, και ευώδους καλάμου διακοσίους πεντήκοντα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'και κασσίας πεντακοσίους, κατά τον σίκλον του αγίου, και ελαίου ελαίας εν ίν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'και θέλεις κάμει αυτό έλαιον αγίου χρίσματος, χρίσμα μυρεψικόν κατά την τέχνην του μυρεψού· άγιον χριστήριον έλαιον θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Και θέλεις χρίσει με αυτό την σκηνήν του μαρτυρίου και την κιβωτόν του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'και την τράπεζαν και πάντα τα σκεύη αυτής και την λυχνίαν και τα σκεύη αυτής και το θυσιαστήριον του θυμιάματος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'και το θυσιαστήριον του ολοκαυτώματος μετά πάντων των σκευών αυτού και τον νιπτήρα και την βάσιν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Και θέλεις αγιάσει αυτά, διά να ήναι αγιώτατα· παν το εγγίζον αυτά θέλει είσθαι άγιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Και τον Ααρών και τους υιούς αυτού θέλεις χρίσει και θέλεις αγιάσει αυτούς, διά να ιερατεύωσιν εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Και θέλεις λαλήσει προς τους υιούς Ισραήλ, λέγων, τούτο θέλει είσθαι εις εμέ άγιον χριστήριον έλαιον εις τας γενεάς σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'επί σάρκα ανθρώπου δεν θέλει χυθή ουδέ θέλετε κάμει όμοιον αυτού κατά την σύνθεσιν αυτού· τούτο είναι άγιον και άγιον θέλει είσθαι εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'όστις συνθέση όμοιον αυτού ή όστις βάλη εξ αυτού επί αλλογενή, θέλει εξολοθρευθή εκ του λαού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Και είπε Κύριος προς τον Μωϋσήν, Λάβε εις σεαυτόν ευώδη αρώματα, στακτήν και όνυχα και χαλβάνην, ταύτα τα ευώδη αρώματα μετά καθαρού λιβανίου· ίσου βάρους θέλει είσθαι έκαστον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Και θέλεις κάμει τούτο θυμίαμα, σύνθεσιν κατά την τέχνην του μυρεψού μεμιγμένον, καθαρόν, άγιον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'και θέλεις κοπανίσει μέρος εκ τούτου πολλά λεπτόν, και θέλεις βάλει εξ αυτού έμπροσθεν του μαρτυρίου εν τη σκηνή του μαρτυρίου, όπου θέλω εμφανίζεσθαι εις σέ· τούτο θέλει είσθαι εις εσάς αγιώτατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Κατά δε την σύνθεσιν του θυμιάματος τούτου, το οποίον θέλεις κάμει, σεις δεν θέλετε κάμει εις εαυτούς· άγιον θέλει είσθαι εις σε διά τον Κύριον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'όστις κάμη όμοιον αυτού διά να μυρίζηται αυτό, θέλει εξολοθρευθή εκ του λαού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Ιδέ, εγώ εκάλεσα εξ ονόματος Βεσελεήλ τον υιόν του Ουρί, υιού του Ωρ, εκ της φυλής του Ιούδα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'και ενέπλησα αυτόν πνεύματος θείου, σοφίας και συνέσεως και επιστήμης και πάσης καλλιτεχνίας,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'διά να επινοή έντεχνα έργα, ώστε να εργάζηται εις χρυσόν και εις άργυρον και εις χαλκόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'και να γλύφη λίθους ενθέσεως, και να σκαλίζη ξύλα δι\' εργασίαν εις πάσαν καλλιτεχνίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Και εγώ, ιδού, έδωκα εις αυτόν Ελιάβ τον υιόν του Αχισαμάχ, εκ της φυλής του Δάν· και εις πάντα συνετόν την καρδίαν έδωκα σοφίαν, διά να κάμωσι πάντα όσα προσέταξα εις σέ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'την σκηνήν του μαρτυρίου, και την κιβωτόν του μαρτυρίου και το ιλαστήριον το επάνωθεν αυτής και πάντα τα σκεύη της σκηνής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'και την τράπεζαν και τα σκεύη αυτής και την καθαράν λυχνίαν μετά πάντων των σκευών αυτής και το θυσιαστήριον του θυμιάματος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'και το θυσιαστήριον του ολοκαυτώματος μετά των σκευών αυτού και τον νιπτήρα και την βάσιν αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'και τας στολάς τας λειτουργικάς, και τας αγίας στολάς του Ααρών του ιερέως, και τας στολάς των υιών αυτού, διά να ιερατεύωσι,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'και το χριστήριον έλαιον, και το ευώδες θυμίαμα διά το άγιον· κατά πάντα όσα προσέταξα εις σε θέλουσι κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Και συ λάλησον προς τους υιούς Ισραήλ, λέγων, Προσέχετε να φυλάττητε τα σάββατά μου· διότι τούτο είναι σημείον μεταξύ εμού και υμών εις τας γενεάς υμών, διά να γνωρίζητε ότι εγώ είμαι Κύριος, ο αγιάζων υμάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'και θέλετε φυλάττει το σάββατον, διότι είναι άγιον εις εσάς· όστις βεβηλώση αυτό, θέλει εξάπαντος θανατωθή· διότι πας όστις κάμη εργασίαν εν αυτώ, η ψυχή εκείνη θέλει εξολοθρευθή εκ μέσου του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Εξ ημέρας θέλει γίνεσθαι εργασία· εν δε τη εβδόμη ημέρα σάββατον θέλει είσθαι, ανάπαυσις αγία εις τον Κύριον· και όστις κάμη εργασίαν εν τη ημέρα του σαββάτου θέλει εξάπαντος θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Και θέλουσι φυλάττει οι υιοί Ισραήλ το σάββατον, διά να εορτάζωσιν αυτό εις τας γενεάς αυτών εις διαθήκην αιώνιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Τούτο είναι σημείον μεταξύ εμού και των υιών Ισραήλ διαπαντός· διότι εις εξ ημέρας εποίησεν ο Κύριος τον ουρανόν και την γην, εν δε τη εβδόμη ημέρα κατέπαυσε και ανεπαύθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Και έδωκεν εις τον Μωϋσήν, αφού ετελείωσε λαλών προς αυτόν επί του όρους Σινά, δύο πλάκας του μαρτυρίου, πλάκας λιθίνας γεγραμμένας με τον δάκτυλον του Θεού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Και ιδών ο λαός ότι εβράδυνεν ο Μωϋσής να καταβή εκ του όρους, συνήχθη ο λαός επί τον Ααρών και έλεγον προς αυτόν, Σηκώθητι, κάμε εις ημάς θεούς, οίτινες να προπορεύωνται ημών· διότι ούτος ο Μωϋσής, ο άνθρωπος όστις εξήγαγεν ημάς εκ γης Αιγύπτου, δεν εξεύρομεν τι απέγεινεν αυτός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Και είπε προς αυτούς ο Ααρών, Αφαιρέσατε τα χρυσά ενώτια, τα οποία είναι εις τα ώτα των γυναικών σας, των υιών σας και των θυγατέρων σας, και φέρετε προς εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Και αφήρεσε πας ο λαός τα χρυσά ενώτια, τα οποία ήσαν εις τα ώτα αυτών, και έφεραν προς τον Ααρών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Και λαβών εκ των χειρών αυτών, διεμόρφωσεν αυτό με εργαλείον εγχαρακτικόν, και έκαμεν αυτό μόσχον χωνευτόν· οι δε είπον, Ούτοι είναι οι θεοί σου, Ισραήλ, οίτινες σε ανεβίβασαν εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Και ότε είδε τούτο ο Ααρών, ωκοδόμησε θυσιαστήριον έμπροσθεν αυτού· και εκήρυξεν ο Ααρών, λέγων, Αύριον είναι εορτή εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Και σηκωθέντες ενωρίς την επαύριον, προσέφεραν ολοκαυτώματα και έφεραν ειρηνικάς προσφοράς· και εκάθισεν ο λαός να φάγη και να πίη, και εσηκώθησαν να παίζωσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Και είπε Κύριος προς τον Μωϋσήν, Ύπαγε, κατάβηθι διότι ηνόμησεν ο λαός σου, τον οποίον εξήγαγες εκ γης Αιγύπτου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'εξετράπησαν ταχέως εκ της οδού την οποίαν προσέταξα εις αυτούς· έκαμαν εις εαυτούς μόσχον χωνευτόν και προσεκύνησαν αυτόν και εθυσίασαν εις αυτόν και είπον, Ούτοι είναι οι θεοί σου, Ισραήλ, οίτινες σε ανεβίβασαν εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Και είπε Κύριος προς τον Μωϋσήν, είδον τον λαόν τούτον, και ιδού, είναι λαός σκληροτράχηλος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'τώρα λοιπόν, άφες με, και θέλει εξαφθή η οργή μου εναντίον αυτών και θέλω εξολοθρεύσει αυτούς· και θέλω σε καταστήσει έθνος μέγα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Και ικέτευσεν ο Μωϋσής Κύριον τον Θεόν αυτού και είπε, Διά τι, Κύριε, εξάπτεται η οργή σου εναντίον του λαού σου, τον οποίον εξήγαγες εκ γης Αιγύπτου μετά μεγάλης δυνάμεως και κραταιάς χειρός;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'διά τι να είπωσιν οι Αιγύπτιοι, λέγοντες, Με πονηρίαν εξήγαγεν αυτούς, διά να θανατώση αυτούς εις τα όρη και να εξολοθρεύση αυτούς από προσώπου της γης; επίστρεψον από της εξάψεως της οργής σου και μεταμελήθητι περί του κακού του προς τον λαόν σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'ενθυμήθητι τον Αβραάμ, τον Ισαάκ και τον Ισραήλ, τους δούλους σου, προς τους οποίους ώμοσας επί σεαυτόν και είπας προς αυτούς, Θέλω πληθύνει το σπέρμα σας ως τα άστρα του ουρανού· και πάσαν την γην ταύτην περί της οποίας ελάλησα, θέλω δώσει εις το σπέρμα σας, και θέλουσι κληρονομήσει αυτήν διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Και μετεμελήθη ο Κύριος περί του κακού, το οποίον είπε να κάμη κατά του λαού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Και στραφείς ο Μωϋσής κατέβη εκ του όρους, και αι δύο πλάκες του μαρτυρίου ήσαν εν ταις χερσίν αυτού· πλάκες γεγραμμέναι εξ αμφοτέρων των μερών· εκ του ενός μέρους και εκ του άλλου ήσαν γεγραμμέναι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Και αι πλάκες ήσαν έργον Θεού και η γραφή ήτο γραφή Θεού εγκεχαραγμένη επί τας πλάκας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Και ακούσας ο Ιησούς τον θόρυβον του λαού αλαλάζοντος, είπε προς τον Μωϋσήν, Θόρυβος πολέμου είναι εν τω στρατοπέδω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Ο δε είπε, Δεν είναι φωνή αλαλαζόντων διά νίκην ουδέ φωνή βοώντων διά ήτταν· φωνήν αδόντων εγώ ακούω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Καθώς δε επλησίασεν εις το στρατόπεδον, είδε τον μόσχον και χορούς· και εξήφθη ο θυμός του Μωϋσέως, και έρριψε τας πλάκας από των χειρών αυτού και συνέτριψεν αυτάς υπό το όρος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'και λαβών τον μόσχον, τον οποίον είχον κάμει, κατέκαυσεν εν πυρί, και συντρίψας εωσού ελεπτύνθη, έσπειρεν επί το ύδωρ και επότισε τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Και είπεν ο Μωϋσής προς τον Ααρών, Τι έκαμεν εις σε ο λαός ούτος, ώστε επέφερες επ\' αυτούς αμαρτίαν μεγάλην;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Και είπεν ο Ααρών, Ας μη εξάπτηται ο θυμός του κυρίου μου· συ γνωρίζεις τον λαόν, ότι έγκειται εις την κακίαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'διότι είπον προς εμέ, Κάμε εις ημάς θεούς, οίτινες να προπορεύωνται ημών· διότι ούτος ο Μωϋσής, ο άνθρωπος όστις εξήγαγεν ημάς εκ γης Αιγύπτου, δεν εξεύρομεν τι απέγεινεν αυτός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'και είπα προς αυτούς, Όστις έχει χρυσίον, ας αφαιρέσωσιν αυτό· και έδωκαν εις εμέ· τότε έρριψα αυτό εις το πυρ, και εξήλθεν ο μόσχος ούτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Και ιδών ο Μωϋσής τον λαόν ότι ήτο αχαλίνωτος, διότι ο Ααρών είχε αφήσει αυτούς αχαλινώτους προς καταισχύνην, μεταξύ των εχθρών αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'εστάθη ο Μωϋσής παρά την πύλην του στρατοπέδου και είπεν, Όστις είναι του Κυρίου, ας έλθη προς εμέ. Και συνήχθησαν προς αυτόν πάντες οι υιοί του Λευΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Και είπε προς αυτούς, Ούτω λέγει Κύριος ο Θεός του Ισραήλ· Ας βάλη έκαστος την ρομφαίαν αυτού επί τον μηρόν αυτού· και διέλθετε και εξέλθετε από πύλης εις πύλην διά του στρατοπέδου, και ας θανατώση έκαστος τον αδελφόν αυτού και έκαστος τον φίλον αυτού και έκαστος τον πλησίον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Και έκαμον οι υιοί του Λευΐ κατά τον λόγον του Μωϋσέως· και έπεσαν εκ του λαού εκείνην την ημέραν περίπου τρεις χιλιάδες άνδρες.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'διότι είπεν ο Μωϋσής, Καθιερώσατε εαυτούς σήμερον εις τον Κύριον, έκαστος επί τον υιόν αυτού και έκαστος επί τον αδελφόν αυτού, διά να δοθή εις εσάς ευλογία σήμερον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Και την επαύριον είπεν ο Μωϋσής προς τον λαόν, Σεις ημαρτήσατε αμαρτίαν μεγάλην· και τώρα θέλω αναβή προς τον Κύριον· ίσως κάμω εξιλέωσιν διά την αμαρτίαν σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Και επέστρεψεν ο Μωϋσής προς τον Κύριον και είπε, Δέομαι· ούτος ο λαός ημάρτησεν αμαρτίαν μεγάλην και έκαμον εις εαυτούς θεούς χρυσούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'πλην τώρα, εάν συγχωρήσης την αμαρτίαν αυτών· ει δε μη, εξάλειψόν με, δέομαι, εκ της βίβλου σου, την οποίαν έγραψας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Και είπε Κύριος προς τον Μωϋσήν, Όστις ημάρτησεν εναντίον εμού, τούτον θέλω εξαλείψει εκ της βίβλου μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'όθεν τώρα ύπαγε, οδήγησον τον λαόν εις τον τόπον περί του οποίου σε είπα· ιδού, ο άγγελός μου θέλει προπορεύεσθαι έμπροσθέν σου\' αλλ\' όμως εν τη ημέρα της ανταποδώσεώς μου θέλω ανταποδώσει την αμαρτίαν αυτών επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Και επάταξε Κύριος τον λαόν, διά την κατασκευήν του μόσχου τον οποίον κατεσκεύασεν ο Ααρών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Ύπαγε, ανάβηθι εντεύθεν συ και ο λαός τον οποίον εξήγαγες εκ γης Αιγύπτου, εις την γην την οποίαν ώμοσα προς τον Αβραάμ, προς τον Ισαάκ και προς τον Ιακώβ, λέγων, Εις το σπέρμα σου θέλω δώσει αυτήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'και θέλω αποστείλει άγγελον έμπροσθέν σου και θέλω εκδιώξει τον Χαναναίον, τον Αμορραίον και τον Χετταίον και τον Φερεζαίον τον Ευαίον και τον Ιεβουσαίον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'εις γην ρέουσαν γάλα και μέλι διότι εγώ δεν θέλω αναβή εν τω μέσω σου, επειδή είσαι λαός σκληροτράχηλος, διά να μη σε εξολοθρεύσω καθ\' οδόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Και ότε ήκουσεν ο λαός τον κακόν τούτον λόγον, κατεπένθησαν και ουδείς έβαλε τον στολισμόν αυτού εφ\' εαυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Διότι ο Κύριος είπε προς τον Μωϋσήν, Ειπέ προς τους υιούς Ισραήλ, Σεις είσθε λαός σκληροτράχηλος· μίαν στιγμήν εάν αναβώ εις το μέσον σου, θέλω σε εξολοθρεύσει· όθεν τώρα εκδύθητι τους στολισμούς σου από σου, διά να γνωρίσω τι θέλω κάμει εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Και εξεδύθησαν οι υιοί του Ισραήλ τους στολισμούς αυτών πλησίον του όρους Χωρήβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Και λαβών ο Μωϋσής την σκηνήν, έστησεν αυτήν έξω του στρατοπέδου, μακράν του στρατοπέδου, και ωνόμασεν αυτήν Σκηνήν του μαρτυρίου· και πας ο ζητών τον Κύριον εξήρχετο προς την σκηνήν του μαρτυρίου την έξω του στρατοπέδου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Και ότε εξήρχετο ο Μωϋσής προς την σκηνήν, πας ο λαός εσηκόνετο και ίστατο έκαστος παρά την θύραν της σκηνής αυτού και έβλεπον κατόπιν του Μωϋσέως, εωσού εισήρχετο εις την σκηνήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Και καθώς εισήρχετο ο Μωϋσής εις την σκηνήν, κατέβαινεν ο στύλος της νεφέλης και ίστατο επί των θυρών της σκηνής· και ελάλει ο Κύριος μετά του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Και έβλεπε πας ο λαός τον στύλον της νεφέλης ιστάμενον επί των θυρών της σκηνής· και πας ο λαός ανιστάμενος προσεκύνει, έκαστος από της θύρας της σκηνής αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Και ελάλει ο Κύριος προς τον Μωϋσήν πρόσωπον προς πρόσωπον, καθώς λαλεί άνθρωπος προς τον φίλον αυτού. Και επέστρεφεν εις το στρατόπεδον· ο δε θεράπων αυτού νέος, Ιησούς ο υιός του Ναυή, δεν ανεχώρει από της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Και είπεν ο Μωϋσής προς τον Κύριον, Ιδέ, συ μοι λέγεις, Ανάγαγε τον λαόν τούτον· και συ δεν με εφανέρωσας ποίον θέλεις αποστείλει μετ\' εμού· και συ είπας, σε γνωρίζω κατ\' όνομα, και μάλιστα εύρηκας χάριν έμπροσθέν μου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'τώρα λοιπόν, εάν εύρηκα χάριν έμπροσθέν σου, δείξόν μοι, δέομαι, την οδόν σου, διά να σε γνωρίσω, διά να εύρω χάριν ενώπιόν σου· και ιδέ ότι τούτο το έθνος είναι ο λαός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'και είπεν, Η παρουσία μου θέλει ελθεί μετά σου και θέλω σοι δώσει ανάπαυσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Ο δε είπε προς αυτόν, Εάν η παρουσία σου δεν έλθη μετ\' εμού, μη αναγάγης ημάς εντεύθεν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'διότι πως θέλει γνωρισθή τώρα, ότι εύρηκα χάριν ενώπιόν σου εγώ και ο λαός σου; ουχί διά της ελεύσεώς σου μεθ\' ημών; ούτω θέλομεν διακριθή, εγώ και ο λαός σου, από παντός λαού, του επί προσώπου της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Και είπε Κύριος προς τον Μωϋσήν, Και τούτο το πράγμα το οποίον είπας, θέλω κάμει διότι εύρηκας χάριν ενώπιόν μου και σε γνωρίζω κατ\' όνομα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Και είπε, Δείξον μοι, δέομαι, την δόξαν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Ο δε είπεν, Εγώ θέλω κάμει να περάση έμπροσθέν σου όλη η αγαθότης μου και θέλω κηρύξει το όνομα του Κυρίου έμπροσθέν σου και θέλω ελεήσει όντινα ελεώ και θέλω οικτειρήσει όντινα οικτείρω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Και είπε, δεν δύνασαι να ίδης το πρόσωπόν μου· διότι άνθρωπος δεν θέλει με ιδεί και ζήσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Και είπεν ο Κύριος, Ιδού, τόπος πλησίον μου, και θέλεις σταθή επί της πέτρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'και όταν η δόξα μου διαβαίνη, θέλω σε βάλει εις το σχίσμα της πέτρας και θέλω σε σκεπάσει με την χείρα μου, εωσού παρέλθω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'και θέλω σηκώσει την χείρα μου και θέλεις ιδεί τα οπίσω μου· το δε πρόσωπόν μου δεν θέλεις ιδεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Κόψον εις σεαυτόν δύο πλάκας λιθίνας καθώς τας πρώτας· και θέλω γράψει επί των πλακών τους λόγους, οίτινες ήσαν επί των πρώτων πλακών, τας οποίας συνέτριψας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'και γίνου έτοιμος το πρωΐ, και ανάβηθι το πρωΐ επί το όρος Σινά, και παράστηθι εκεί ενώπιόν μου επί της κορυφής του όρους·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'και ουδείς θέλει αναβή μετά σου ουδέ θέλει φανή τις καθ\' όλον το όρος· και τα ποίμνια και αι αγέλαι δεν θέλουσι βοσκηθή έμπροσθεν του όρους εκείνου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Και έκοψε δύο πλάκας λιθίνας καθώς τας πρώτας· και σηκωθείς ο Μωϋσής ενωρίς το πρωΐ, ανέβη επί το όρος Σινά, καθώς προσέταξεν εις αυτόν ο Κύριος, και έλαβεν εις τας χείρας αυτού τας δύο πλάκας τας λιθίνας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Και κατέβη ο Κύριος εν νεφέλη και εστάθη μετ\' αυτού εκεί και εκήρυξε το όνομα του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Και παρήλθε Κύριος έμπροσθεν αυτού και εκήρυξε, Κύριος, Κύριος ο Θεός, οικτίρμων και ελεήμων, μακρόθυμος και πολυέλεος, και αληθινός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'φυλάττων έλεος εις χιλιάδας, συγχωρών ανομίαν και παράβασιν και αμαρτίαν και ουδόλως αθωόνων τον ένοχον· ανταποδίδων την ανομίαν των πατέρων επί τα τέκνα και επί τα τέκνα των τέκνων, έως τρίτης και τετάρτης γενεάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Και έσπευσεν ο Μωϋσής και κύψας εις την γην, προσεκύνησε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'και είπεν, Εάν τώρα εύρηκα χάριν ενώπιόν σου, Κύριε, ας έλθη, δέομαι, ο Κύριός μου εν τω μέσω ημών· διότι ο λαός ούτος είναι σκληροτράχηλος· και συγχώρησον την ανομίαν ημών και την αμαρτίαν ημών και λάβε ημάς εις κληρονομίαν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Και είπεν, Ιδού, εγώ κάμνω διαθήκην· έμπροσθεν παντός του λαού σου θέλω κάμει θαυμάσια, οποία δεν έγειναν καθ\' όλην την γην και εις ουδέν έθνος· και πας ο λαός, εν μέσω του οποίου είσαι, θέλει ιδεί το έργον του Κυρίου· διότι φοβερόν είναι εκείνο, το οποίον εγώ θέλω κάμει μετά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Φύλαξον εκείνο, το οποίον εγώ σε προστάζω σήμερον· ιδού, εγώ εκβάλλω απ\' έμπροσθέν σου τον Αμορραίον και τον Χαναναίον και τον Χετταίον και τον Φερεζαίον και τον Ευαίον και τον Ιεβουσαίον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Προσέχε εις σεαυτόν, μη κάμης συνθήκην μετά των κατοίκων της γης εις την οποίαν υπάγεις, μήποτε γείνη παγίς εν τω μέσω σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'αλλά τους βωμούς αυτών θέλεις καταστρέψει και τα είδωλα αυτών θέλεις συντρίψει και τα άλση αυτών θέλεις κατακόψει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Διότι δεν θέλεις προσκυνήσει άλλον θεόν· επειδή ο Κύριος, του οποίου το όνομα είναι Ζηλότυπος, είναι Θεός ζηλότυπος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'μήποτε κάμης συνθήκην μετά των κατοίκων της γης, και όταν πορνεύσωσι κατόπιν των θεών αυτών και θυσιάσωσι προς τους θεούς αυτών, σε προσκαλέση τις και φάγης από της θυσίας αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'και μήποτε λάβης εκ των θυγατέρων αυτού εις τους υιούς σου, και όταν αι θυγατέρες αυτού πορνεύσωσι κατόπιν των θεών αυτών, κάμωσι τους υιούς σου να πορνεύσωσι κατόπιν των θεών αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Θεούς χωνευτούς δεν θέλεις κάμει εις σεαυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Την εορτήν των αζύμων θέλεις φυλάττει. Επτά ημέρας θέλεις τρώγει άζυμα, καθώς προσέταξα εις σε, κατά τον καιρόν του μηνός Αβίβ· διότι κατά τον μήνα Αβίβ εξήλθες εξ Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Παν το διανοίγον μήτραν είναι ιδικόν μου· και παν πρωτότοκον αρσενικόν μεταξύ των κτηνών σου, είτε βους είτε πρόβατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Το δε πρωτότοκον της όνου θέλεις εξαγοράζει με αρνίον· και εάν δεν εξαγοράσης αυτό, τότε θέλεις λαιμοτομήσει αυτό. Πάντας τους πρωτοτόκους των υιών σου θέλεις εξαγοράζει. Και ουδείς θέλει φανή ενώπιόν μου κενός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Εξ ημέρας θέλεις εργάζεσθαι την δε εβδόμην ημέραν θέλεις αναπαύεσθαι κατά τον σπορητόν και κατά τον θερισμόν θέλεις αναπαύεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Και θέλεις φυλάττει την εορτήν των εβδομάδων, των απαρχών του θερισμού του σίτου, και την εορτήν της συγκομιδής εις την επιστροφήν του ενιαυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Τρίς του ενιαυτού θέλει εμφανίζεσθαι παν αρσενικόν σου ενώπιον Κυρίου, Κυρίου του Θεού του Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Διότι αφού εκδιώξω τα έθνη απ\' έμπροσθέν σου και πλατύνω τα όριά σου, δεν θέλει επιθυμήσει ουδείς την γην σου, όταν αναβαίνης διά να εμφανισθής έμπροσθεν Κυρίου του Θεού σου τρίς του ενιαυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Δεν θέλεις προσφέρει το αίμα της θυσίας μου με ένζυμα· και η θυσία της εορτής του πάσχα δεν θέλει μείνει έως το πρωΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Τα πρωτογεννήματα της γης σου θέλεις φέρει εις τον οίκον Κυρίου του Θεού σου. Δεν θέλεις ψήσει ερίφιον εν τω γάλακτι της μητρός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Και είπε Κύριος προς τον Μωϋσήν, Γράψον εις σεαυτόν τους λόγους τούτους· διότι κατά τους λόγους τούτους έκαμα διαθήκην προς σε και προς τον Ισραήλ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Και ήτο εκεί μετά του Κυρίου τεσσαράκοντα ημέρας και τεσσαράκοντα νύκτας· άρτον δεν έφαγε και ύδωρ δεν έπιε. Και έγραψεν επί των πλακών τους λόγους της διαθήκης, τας δέκα εντολάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Και ότε κατέβαινεν ο Μωϋσής από του όρους Σινά, και αι δύο πλάκες του μαρτυρίου ήσαν εις την χείρα του Μωϋσέως, ότε κατέβαινεν από του όρους, ο Μωϋσής δεν ήξευρεν ότι το δέρμα του προσώπου αυτού έγεινε λαμπρόν ενώ ελάλει μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Και είδεν ο Ααρών και πάντες οι υιοί Ισραήλ τον Μωϋσήν, και ιδού, το δέρμα του προσώπου αυτού έλαμπε· και εφοβήθησαν να πλησιάσωσιν εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Και εκάλεσεν αυτούς ο Μωϋσής· και επεστράφησαν προς αυτόν ο Ααρών και πάντες οι άρχοντες της συναγωγής, και ελάλησε προς αυτούς ο Μωϋσής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Και μετά ταύτα πάντες οι υιοί Ισραήλ προσήλθον· και προσέταξεν εις αυτούς πάντα όσα ελάλησεν ο Κύριος προς αυτόν επί του όρους Σινά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Και ετελείωσεν ο Μωϋσής λαλών προς αυτούς· είχε δε κάλυμμα επί το πρόσωπον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Και ότε εισήρχετο ο Μωϋσής ενώπιον του Κυρίου διά να λαλήση μετ\' αυτού, εσήκονε το κάλυμμα, εωσού εξέλθη. Και εξήρχετο και ελάλει προς τους υιούς Ισραήλ ό,τι ήτο προστεταγμένος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Και είδον οι υιοί Ισραήλ το πρόσωπον του Μωϋσέως, ότι το δέρμα του προσώπου του Μωϋσέως έλαμπε· και έβαλλε πάλιν ο Μωϋσής το κάλυμμα επί το πρόσωπον αυτού, εωσού εισέλθη διά να λαλήση μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Και συνήθροισεν ο Μωϋσής πάσαν την συναγωγήν των υιών Ισραήλ, και είπε προς αυτούς, Ούτοι είναι οι λόγοι, τους οποίους προσέταξεν ο Κύριος, διά να κάμνητε αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Εξ ημέρας θέλει γίνεσθαι εργασία· η δε εβδόμη ημέρα θέλει είσθαι εις εσάς αγία, σάββατον αναπαύσεως εις τον Κύριον· πας όστις κάμη εν αυτή εργασίαν θέλει θανατωθή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'δεν θέλετε ανάπτει πυρ εν πάσαις ταις κατοικίαις υμών την ημέραν του σαββάτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Και ελάλησεν ο Μωϋσής προς πάσαν την συναγωγήν των υιών Ισραήλ, λέγων, τούτο είναι το πράγμα το οποίον ο Κύριος προσέταξε, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Λάβετε από ό,τι έχετε προσφοράν εις τον Κύριον· όστις προαιρείται εν τη καρδία αυτού, ας φέρη την προσφοράν του Κυρίου· χρυσίον και αργύριον και χαλκόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'και κυανούν και πορφυρούν και κόκκινον και βύσσον και τρίχας αιγών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'και δέρματα κριών κοκκινοβαφή και δέρματα θώων και ξύλον σιττίμ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'και έλαιον διά το φως και αρώματα διά το χριστήριον έλαιον και διά το ευώδες θυμίαμα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'και λίθους ονυχίτας και λίθους διά να εντεθώσιν εις το εφόδ και εις το περιστήθιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Και πας συνετός την καρδίαν μεταξύ σας θέλει ελθεί και κάμει πάντα όσα προσέταξεν ο Κύριος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'την σκηνήν, το περικάλυμμα αυτής και την σκέπην αυτής, τας περόνας αυτής και τας σανίδας αυτής, τους μοχλούς αυτής, τους στύλους αυτής και τα υποβάσια αυτής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'την κιβωτόν και τους μοχλούς αυτής, το ιλαστήριον και το καλυπτήριον καταπέτασμα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'την τράπεζαν και τους μοχλούς αυτής και πάντα τα σκεύη αυτής και τον άρτον της προθέσεως,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'και την λυχνίαν διά το φως και τα σκεύη αυτής και τους λύχνους αυτής και το έλαιον του φωτός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'και το θυσιαστήριον του θυμιάματος, και τους μοχλούς αυτού και το χριστήριον έλαιον και το ευώδες θυμίαμα και τον τάπητα της θύρας της εισόδου της σκηνής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'το θυσιαστήριον του ολοκαυτώματος και την χαλκίνην εσχάραν αυτού τους μοχλούς αυτού και πάντα τα σκεύη αυτού, τον νιπτήρα και την βάσιν αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'τα παραπετάσματα της αυλής, τους στύλους αυτής και τα υποβάσια αυτών και το παραπέτασμα της θύρας της αυλής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'τους πασσάλους της σκηνής και τους πασσάλους της αυλής και τα σχοινία αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'τας λειτουργικάς στολάς διά να λειτουργώσιν εν τω αγίω, τας αγίας στολάς διά τον Ααρών τον ιερέα και τας στολάς των υιών αυτού, διά να ιερατεύωσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Και εξήλθε πάσα η συναγωγή των υιών Ισραήλ απ\' έμπροσθεν του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Και ήλθον, πας άνθρωπος του οποίου η καρδία διήγειρεν αυτόν· και πας τις τον οποίον το πνεύμα αυτού έκαμε πρόθυμον, έφεραν την προσφοράν του Κυρίου διά το έργον της σκηνής του μαρτυρίου και διά πάσαν την υπηρεσίαν αυτής και διά τας αγίας στολάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Και ήλθον, άνδρες τε και γυναίκες, όσοι ήσαν προθύμου καρδίας, φέροντες βραχιόλια και ενώτια και δακτυλίδια και περιδέραια, παν σκεύος χρυσούν· και πάντες όσοι προσέφεραν προσφοράν χρυσίον εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Και πας άνθρωπος εις τον οποίον ευρίσκετο κυανούν και πορφυρούν και κόκκινον και βύσσος και τρίχες αιγών και δέρματα κριών κοκκινοβαφή και δέρματα θώων, έφεραν αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Πας όστις ηδύνατο να κάμη προσφοράν αργυρίου και χαλκού, έφεραν την προσφοράν του Κυρίου· και πας άνθρωπος, εις τον οποίον ευρίσκετο ξύλον σιττίμ διά παν έργον της υπηρεσίας, έφεραν αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Και πάσα γυνή συνετή την καρδίαν έκλωθον με τας χείρας αυτών και έφερον κεκλωσμένα, το κυανούν και το πορφυρούν, το κόκκινον και την βύσσον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Και πάσαι αι γυναίκες, των οποίων η καρδία διήγειρεν αυτάς εις ευμηχανίαν, έκλωσαν τας τρίχας των αιγών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Και οι άρχοντες έφεραν τους λίθους τους ονυχίτας και τους λίθους της ενθέσεως διά το εφόδ και διά το περιστήθιον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'και τα αρώματα, και το έλαιον διά το φως και διά το χριστήριον έλαιον και διά το ευώδες θυμίαμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Οι υιοί Ισραήλ έφεραν προαιρετικήν προσφοράν εις τον Κύριον, πας ανήρ και γυνή, των οποίων η καρδία έκαμεν αυτούς προθύμους εις το να φέρωσι διά πάσαν την εργασίαν, την οποίαν προσέταξεν ο Κύριος να γείνη διά χειρός του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Και είπεν ο Μωϋσής προς τους υιούς Ισραήλ, Ιδέτε, ο Κύριος εκάλεσεν εξ ονόματος Βεσελεήλ τον υιόν του Ουρί, υιού του Ωρ, εκ φυλής Ιούδα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'και ενέπλησεν αυτόν πνεύματος θείου, σοφίας συνέσεως και επιστήμης και πάσης καλλιτεχνίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'και διά να επινοή έντεχνα έργα, ώστε να εργάζηται εις χρυσίον και εις αργύριον και εις χαλκόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'και να γλύφη λίθους ενθέσεως και να σκαλίζη ξύλα δι\' εργασίαν, διά παν έντεχνον έργον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Και έδωκεν εις την καρδίαν αυτού το να διδάσκη, αυτός και Ελιάβ ο υιός του Αχισαμάχ, εκ φυλής Δαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Τούτους ενέπλησε συνέσεως καρδίας, διά να εργάζωνται παν έργον εγχαράκτου και καλλιτέχνου και κεντητού εις κυανούν και εις πορφυρούν, εις κόκκινον και εις βύσσον, και υφαντού, των εργαζομένων παν έργον και επινοούντων έντεχνα έργα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Και έκαμεν ο Βεσελεήλ και ο Ελιάβ και πας σοφός την καρδίαν, εις τον οποίον ο Κύριος έδωκε σοφίαν και σύνεσιν διά να εξεύρη να εργάζηται παν το έργον της υπηρεσίας του αγιαστηρίου, κατά πάντα όσα προσέταξεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Και εκάλεσεν ο Μωϋσής τον Βεσελεήλ και τον Ελιάβ και πάντα σοφόν την καρδίαν, εις του οποίου την καρδίαν ο Κύριος έδωκε σοφίαν, πάντα άνθρωπον του οποίου η καρδία διήγειρεν αυτόν εις το να έλθη προς το έργον διά να κάμη αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Και έλαβον απ\' έμπροσθεν του Μωϋσέως πάσας τας προσφοράς, τας οποίας έφεραν οι υιοί Ισραήλ διά το έργον της υπηρεσίας του αγιαστηρίου, διά να κάμωσιν αυτό. Και έφερον έτι προς αυτόν αυτοπροαιρέτους προσφοράς καθ\' εκάστην πρωΐαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Και ήλθον πάντες οι σοφοί οι εργαζόμενοι παν το έργον του αγιαστηρίου, έκαστος από του έργου αυτού, το οποίον έκαμνον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'και είπον προς τον Μωϋσήν, λέγοντες, Ο λαός φέρει πλειότερον παρά το ικανόν διά την υπηρεσίαν του έργον, το οποίον ο Κύριος προσέταξε να γείνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Και προσέταξεν ο Μωϋσής και εκήρυξαν εν τω στρατοπέδω, λέγοντες, Μηδείς ανήρ μήτε γυνή, ας μη κάμνη πλέον εργασίαν διά την προσφοράν του αγιαστηρίου. Και ο λαός έπαυσεν από του να φέρη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'διότι η ύλη, την οποίαν είχον, ήτο ικανή δι\' όλον το έργον, ώστε να κάμωσιν αυτό, και επερίσσευεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Και πας σοφός την καρδίαν εκ των εργαζομένων το έργον της σκηνής έκαμον δέκα παραπετάσματα εκ βύσσου κεκλωσμένης και κυανού και πορφυρού και κοκκίνου· με χερουβείμ εντέχνου εργασίας έκαμον αυτά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'το μήκος του ενός παραπετάσματος εικοσιοκτώ πηχών και το πλάτος του ενός παραπετάσματος τεσσάρων πηχών· πάντα τα παραπετάσματα του αυτού μέτρου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'και συνήψε τα πέντε παραπετάσματα το εν μετά του άλλου· και τα άλλα πέντε παραπετάσματα συνήψε το εν μετά του άλλου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Και έκαμε θυλειάς κυανά επί της άκρας του ενός παραπετάσματος κατά το πλάγιον όπου έγεινεν η ένωσις· ομοίως έκαμεν επί της τελευταίας άκρας του δευτέρου παραπετάσματος, όπου έγεινεν η ένωσις του δευτέρου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'πεντήκοντα θυλειάς έκαμεν εις το εν παραπέτασμα και πεντήκοντα θυλειάς έκαμεν επί της άκρας του παραπετάσματος, όπου έγεινεν η ένωσις του δευτέρου, διά να αντικρύζωσι αι θυλειαί προς άλληλα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Και έκαμε πεντήκοντα περόνας χρυσάς και συνήψε τα παραπετάσματα προς άλληλα με τας περόνας. και έγεινεν η σκηνή μία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Και έκαμε παραπετάσματα εκ τριχών αιγών διά να ήναι κάλυμμα επί της σκηνής· ένδεκα παραπετάσματα έκαμεν αυτά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'το μήκος του ενός παραπετάσματος τριάκοντα πηχών και το πλάτος του ενός παραπετάσματος τεσσάρων πηχών· τα ένδεκα παραπετάσματα του αυτού μέτρου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'και συνήψε τα πέντε παραπετάσματα χωριστά, και τα εξ παραπετάσματα χωριστά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Και έκαμε πεντήκοντα θυλειάς επί της τελευταίας άκρας του παραπετάσματος κατά την ένωσιν, και πεντήκοντα θυλειάς έκαμεν επί της άκρας του παραπετάσματος, κατά την ένωσιν του δευτέρου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Έκαμεν έτι πεντήκοντα περόνας χαλκίνας, διά να συνάψη την σκηνήν, ώστε να ήναι μία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Και έκαμε επικάλυμμα διά την σκηνήν εκ δερμάτων κριών κοκκινοβαφών, και επικάλυμμα υπεράνωθεν εκ δερμάτων θώων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Και έκαμε τας σανίδας διά την σκηνήν εκ ξύλου σιττίμ, ορθίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'το μήκος της μιας σανίδος δέκα πηχών, και το πλάτος της μιας σανίδος μιας πήχης και ημισείας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'μία σανίς είχε δύο αγκωνίσκους αντικρύζοντας προς αλλήλους· ούτως έκαμε δι\' όλας τας σανίδας της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Και έκαμε τας σανίδας διά την σκηνήν, είκοσι σανίδας από του νοτίου μέρους προς τα δεξιά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Και τεσσαράκοντα υποβάσια αργυρά έκαμεν υποκάτω των είκοσι σανίδων· δύο υποβάσια υποκάτω της μιας σανίδος διά τους δύο αγκωνίσκους αυτής και δύο υποβάσια υποκάτω της άλλης σανίδος διά τους δύο αγκωνίσκους αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Και διά το δεύτερον μέρος της σκηνής, το προς βορράν, έκαμεν είκοσι σανίδας,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'και τα τεσσαράκοντα αυτών υποβάσια αργυρά· δύο υποβάσια υποκάτω της μιας σανίδος και δύο υποβάσια υποκάτω της άλλης σανίδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Και διά τα μέρη της σκηνής τα προς δυσμάς έκαμεν εξ σανίδας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Και δύο σανίδας έκαμε διά τας γωνίας της σκηνής εις τα δύο πλάγια·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'και ηνώθησαν κάτωθεν και ηνώθησαν ομού άνωθεν διά του ενός κρίκου· ούτως έκαμε δι\' αυτάς αμφοτέρας διά τας δύο γωνίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Και ήσαν οκτώ σανίδες· και τα υποβάσια αυτών δεκαέξ υποβάσια αργυρά, ανά δύο υποβάσια υποκάτω εκάστης σανίδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Και έκαμε τους μοχλούς εκ ξύλου σιττίμ· πέντε διά τας σανίδας του ενός μέρους της σκηνής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'και πέντε μοχλούς διά τας σανίδας του άλλου μέρους της σκηνής και πέντε μοχλούς διά τας σανίδας της σκηνής, διά τα όπισθεν μέρη τα προς δυσμάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'και έκαμε τον μέσον μοχλόν διά να διαπερά διά των σανίδων απ\' άκρου έως άκρου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Και περιεκάλυψε τας σανίδας με χρυσίον και έκαμε τους κρίκους αυτών χρυσούς διά να ήναι θήκαι των μοχλών, και περιεκάλυψε τους μοχλούς με χρυσίον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Και έκαμε το καταπέτασμα εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης· εντέχνου εργασίας έκαμεν αυτό με χερουβείμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Και έκαμεν εις αυτό τους τέσσαρας στύλους εκ ξύλου σιττίμ και περιεκάλυψεν αυτούς με χρυσίον· τα άγκιστρα αυτών χρυσά· και έχυσε δι\' αυτούς τέσσαρα υποβάσια αργυρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Και έκαμε τον τάπητα διά την θύραν της σκηνής εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης, εργασίας κεντητού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'και τους πέντε στύλους αυτής και τα άγκιστρα αυτών· και περιεκάλυψε τα κιονόκρανα αυτών και τας ταινίας αυτών με χρυσίον· τα πέντε όμως υποβάσια αυτών ήσαν χάλκινα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Και έκαμεν ο Βεσελεήλ την κιβωτόν εκ ξύλου σιττίμ· δύο πηχών και ημισείας το μήκος αυτής και μιας πήχης και ημισείας το πλάτος αυτής και μιας πήχης και ημισείας το ύψος αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'και περιεκάλυψεν αυτήν με καθαρόν χρυσίον έσωθεν και έξωθεν και έκαμεν εις αυτήν στεφάνην χρυσήν κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Και έχυσε δι\' αυτήν τέσσαρας κρίκους χρυσούς διά τας τέσσαρας γωνίας αυτής· δύο μεν κρίκους εις το εν πλάγιον αυτής δύο δε κρίκους εις το άλλο πλάγιον αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Και έκαμε μοχλούς εκ ξύλου σιττίμ και περιεκάλυψεν αυτούς με χρυσίον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'και εισήγαγε τους μοχλούς εις τους κρίκους κατά τα πλάγια της κιβωτού, διά να βαστάζωσι την κιβωτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Και έκαμε το ιλαστήριον εκ χρυσίου καθαρού· δύο πηχών και ημισείας το μήκος αυτού και μιας πήχης και ημισείας το πλάτος αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Και έκαμε δύο χερουβείμ εκ χρυσίου· σφυρήλατα έκαμεν αυτά, επί των δύο άκρων του ιλαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'εν χερούβ επί του ενός άκρου, και εν χερούβ επί του άλλου άκρου· επί του ιλαστηρίου έκαμε τα χερουβείμ επί των δύο άκρων αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'και τα χερουβείμ εξέτεινον τας πτέρυγας άνωθεν, επικαλύπτοντα με τας πτέρυγας αυτών το ιλαστήριον και τα πρόσωπα αυτών έβλεπον το εν προς το άλλο· προς το ιλαστήριον ήσαν τα πρόσωπα των χερουβείμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Και έκαμε την τράπεζαν εκ ξύλου σιττίμ· δύο πηχών το μήκος αυτής και μιας πήχης το πλάτος αυτής, το δε ύψος αυτής μιας πήχης και ημισείας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'και περιεκάλυψεν αυτήν με χρυσίον καθαρόν, και έκαμεν εις αυτήν στεφάνην χρυσήν κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Έκαμεν έτι εις αυτήν χείλος κύκλω, μιας παλάμης το πλάτος· και επί το χείλος αυτής κύκλω έκαμε στεφάνην χρυσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Και έχυσε δι\' αυτήν τέσσαρας κρίκους χρυσούς, και έβαλε τους κρίκους επί τας τέσσαρας γωνίας, τας επί των τεσσάρων ποδών αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'υπό το χείλος ήσαν οι κρίκοι, θήκαι των μοχλών, διά να βαστάζωσι την τράπεζαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'και έκαμε τους μοχλούς εκ ξύλου σιττίμ, και περιεκάλυψεν αυτούς με χρυσίον, διά να βαστάζωσι την τράπεζαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'και έκαμε τα σκεύη τα επί της τραπέζης, τους δίσκους αυτής και τους θυμιαματοδόχους αυτής και τας λεκάνας αυτής και τα σπονδεία, διά να γίνωνται δι\' αυτών αι σπονδαί, εκ χρυσίου καθαρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'και έκαμε την λυχνίαν εκ χρυσίου καθαρού· σφυρήλατον έκαμε την λυχνίαν· ο κορμός αυτής και οι κλάδοι αυτής, αι λεκάναι αυτής, οι κόμβοι αυτής και τα άνθη αυτής ήσαν εν σώμα μετ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'και εξ κλάδοι εξήρχοντο εκ των πλαγίων αυτής· τρεις κλάδοι της λυχνίας εκ του ενός πλαγίου αυτής και τρεις κλάδοι της λυχνίας εκ του άλλου πλαγίου αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'τρεις λεκάναι αμυγδαλοειδείς εις τον ένα κλάδον, εις κόμβος και εν άνθος· και τρεις λεκάναι αμυγδαλοειδείς εις τον άλλον κλάδον, εις κόμβος και εν άνθος· ούτως έκαμεν εις τους εξ κλάδους τους εξερχομένους εκ της λυχνίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Και εις την λυχνίαν ήσαν τέσσαρες λεκάναι αμυγδαλοειδείς, οι κόμβοι αυτών και τα άνθη αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Και εις κόμβος υπό τους δύο κλάδους εξ αυτής και εις κόμβος υπό τους δύο κλάδους εξ αυτής και εις κόμβος υπό τους δύο κλάδους εξ αυτής, εις τους εξ κλάδους τους εξερχομένους εξ αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Οι κόμβοι αυτών και οι κλάδοι αυτών ήσαν εν σώμα μετ\' αυτής· το όλον αυτής εν σφυρήλατον εκ χρυσίου καθαρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Και έκαμε τους επτά λύχνους αυτής, και τα λυχνοψάλιδα αυτής και τα υποθέματα αυτής εκ χρυσίου καθαρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Εξ ενός ταλάντου χρυσίου καθαρού έκαμεν αυτήν και πάντα τα σκεύη αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Και έκαμε το θυσιαστήριον του θυμιάματος εκ ξύλου σιττίμ· το μήκος αυτού μιας πήχης και το πλάτος αυτού μιας πήχης, τετράγωνον· και δύο πηχών το ύψος αυτού· τα κέρατα αυτού ήσαν εκ του αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Και περιεκάλυψεν αυτό με χρυσίον καθαρόν, την κορυφήν αυτού και τα πλάγια αυτού κύκλω και τα κέρατα αυτού· και έκαμεν εις αυτό στεφάνην χρυσήν κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Και δύο κρίκους χρυσούς έκαμε δι\' αυτό υπό την στεφάνην αυτού πλησίον των δύο γωνιών αυτού επί τα δύο πλάγια αυτού, διά να ήναι θήκαι των μοχλών, ώστε να βαστάζωσιν αυτό δι\' αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Και έκαμε τους μοχλούς εκ ξύλου σιττίμ και περιεκάλυψεν αυτούς με χρυσίον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Και έκαμε το άγιον χριστήριον έλαιον και το καθαρόν ευώδες θυμίαμα κατά την τέχνην του μυρεψού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Και έκαμε το θυσιαστήριον του ολοκαυτώματος εκ ξύλου σιττίμ· πέντε πηχών το μήκος αυτού και πέντε πηχών το πλάτος αυτού, τετράγωνον· και το ύψος αυτού τριών πηχών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'και έκαμε τα κέρατα αυτού επί των τεσσάρων γωνιών αυτού· τα κέρατα αυτού ήσαν εκ του αυτού· και περιεκάλυψεν αυτό χαλκόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Και έκαμε πάντα τα σκεύη του θυσιαστηρίου, τους λέβητας και τα πτυάρια και τας λεκάνας, τας κρεάγρας και τα πυροδόχα· πάντα τα σκεύη αυτού έκαμε χάλκινα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Και έκαμε διά το θυσιαστήριον χαλκίνην εσχάραν δικτυωτής εργασίας υπό την περιοχήν αυτού κάτωθεν έως του μέσου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Και έχυσε τέσσαρας κρίκους διά τα τέσσαρα άκρα της χαλκίνης εσχάρας, διά να ήναι θήκαι των μοχλών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Και έκαμε τους μοχλούς εκ ξύλου σιττίμ, και περιεκάλυψεν αυτούς με χαλκόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Και εισήξε τους μοχλούς εις τους κρίκους κατά τα πλάγια του θυσιαστηρίου, διά να βαστάζωσιν αυτό δι\' αυτών· κοίλον σανιδωτόν έκαμεν αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Και έκαμε τον νιπτήρα χάλκινον και την βάσιν αυτού χαλκίνην εκ των κατόπτρων των συναθροιζομένων γυναικών, αίτινες συνηθροίζοντο παρά την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Και έκαμε την αυλήν· κατά το πλευρόν το προς μεσημβρίαν τα παραπετάσματα της αυλής ήσαν εκ βύσσου κεκλωσμένης, εκατόν πηχών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Οι στύλοι αυτών ήσαν είκοσι και τα χάλκινα αυτών υποβάσια είκοσι τα άγκιστρα των στύλων και αι ζώναι αυτών αργυρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Και κατά το βόρειον πλευρόν τα παραπετάσματα ήσαν εκατόν πηχών· οι στύλοι αυτών είκοσι και τα χάλκινα υποβάσια αυτών είκοσι τα άγκιστρα των στύλων και αι ζώναι αυτών αργυρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Και κατά το δυτικόν πλευρόν ήσαν παραπετάσματα πεντήκοντα πηχών· οι στύλοι αυτών δέκα και τα υποβάσια αυτών δέκα· τα άγκιστρα των στύλων και αι ζώναι αυτών αργυρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Και κατά το ανατολικόν πλευρόν το προς ανατολάς, πεντήκοντα πηχών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Τα παραπετάσματα του ενός μέρους της πύλης ήσαν δεκαπέντε πηχών· οι στύλοι αυτών τρεις και τα υποβάσια αυτών τρία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Και εις το άλλο μέρος της πύλης της αυλής εκατέρωθεν ήσαν παραπετάσματα δεκαπέντε πηχών· οι στύλοι αυτών τρεις και τα υποβάσια αυτών τρία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Πάντα τα παραπετάσματα της αυλής κύκλω ήσαν εκ βύσσου κεκλωσμένης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Και τα υποβάσια διά τους στύλους ήσαν χάλκινα· τα άγκιστρα των στύλων και αι ζώναι αυτών αργυρά· και τα κιονόκρανα αυτών ήσαν περικεκαλυμμένα με αργύριον· και πάντες οι στύλοι της αυλής ήσαν εζωσμένοι με αργύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Και το καταπέτασμα διά την πύλην της αυλής ήτο εργασίας κεντητού εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης· και ήτο είκοσι πηχών το μήκος και το ύψος εις το πλάτος πέντε πηχών, καθώς εις τα παραπετάσματα της αυλής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Και οι στύλοι αυτών τέσσαρες και τα χάλκινα υποβάσια αυτών τέσσαρα· τα άγκιστρα αυτών αργυρά, και τα κιονόκρανα αυτών περικεκαλυμμένα με αργύριον και αι ζώναι αυτών αργυραί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Και πάντες οι πάσσαλοι της σκηνής και της αυλής κύκλω χάλκινοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Αύτη είναι η απαρίθμησις των πραγμάτων της σκηνής, της σκηνής του μαρτυρίου, καθώς ηριθμήθησαν κατά την προσταγήν του Μωϋσέως, διά την υπηρεσίαν των Λευϊτών διά χειρός του Ιθάμαρ, υιού του Ααρών του ιερέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Και ο Βεσελεήλ ο υιός του Ουρί, υιού του Ωρ, εκ φυλής Ιούδα, έκαμε πάντα όσα προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Και ήτο μετ\' αυτού Ελιάβ, ο υιός του Αχισαμάχ, εκ φυλής Δαν, εγχαράκτης και ευμήχανος τεχνίτης και κεντητής εις κυανούν και εις πορφυρούν και εις κόκκινον και εις βύσσον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Παν το χρυσίον το δαπανηθέν διά την εργασίαν εις όλον το έργον του αγιαστηρίου, το χρυσίον της προσφοράς, ήτο εικοσιεννέα τάλαντα και επτακόσιοι τριάκοντα σίκλοι, κατά τον σίκλον του αγιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Και το αργύριον των απαριθμηθέντων εκ της συναγωγής εκατόν τάλαντα, και χίλιοι επτακόσιοι και εβδομήκοντα πέντε σίκλοι, κατά τον σίκλον του αγιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'εν βεκάχ κατά κεφαλήν, το ήμισυ του σίκλου, κατά τον σίκλον του αγιαστηρίου, διά πάντα περνώντα εις την απαρίθμησιν, από είκοσι ετών ηλικίας και επάνω, διά εξακοσίας και τρεις χιλιάδας και πεντακοσίους και πεντήκοντα ανθρώπους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Και εκ του αργυρίου των εκατόν ταλάντων εχύθησαν τα υποβάσια του αγιαστηρίου και τα υποβάσια του καταπετάσματος· εκατόν υποβάσια από εκατόν ταλάντων, εν τάλαντον δι\' εν υποβάσιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Και από των χιλίων επτακοσίων εβδομήκοντα πέντε σίκλων έκαμεν άγκιστρα διά τους στύλους και περιεκάλυψε τα κιονόκρανα αυτών και έζωσεν αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Και ο χαλκός της προσφοράς ήτο εβδομήκοντα τάλαντα και δύο χιλιάδες και τετρακόσιοι σίκλοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Και εκ τούτου έκαμε τα υποβάσια εις την θύραν της σκηνής του μαρτυρίου και το χάλκινον θυσιαστήριον και την χαλκίνην εσχάραν δι\' αυτό, και πάντα τα σκεύη του θυσιαστηρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'και τα υποβάσια της αυλής κύκλω και τα υποβάσια της πύλης της αυλής και πάντας τους πασσάλους της σκηνής και πάντας τους πασσάλους της αυλής κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Και εκ του κυανού και πορφυρού και κοκκίνου έκαμον στολάς λειτουργικάς διά να λειτουργώσιν εν τω αγίω, και έκαμον τας αγίας στολάς διά τον Ααρών, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Και έκαμε το εφόδ εκ χρυσίου, εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Και εσφυρηλάτησαν το χρυσίον εις λεπτάς πλάκας και έκοψαν αυτό εις σύρματα, διά να εργασθώσιν αυτό εις το κυανούν και εις το πορφυρούν και εις το κόκκινον και εις την βύσσον με έντεχνον εργασίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Έκαμον επωμίδας συναπτάς δι\' αυτό· συναπτομένας επί των δύο άκρων αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Και η κεντητή ζώνη του εφόδ επ\' αυτό ήτο εκ του αυτού κατά την εργασίαν αυτού· εκ χρυσίου, εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Και ειργάσθησαν τους ονυχίτας λίθους ενηρμοσμένους εν οικίσκοις χρυσοίς, εγκεχαραγμένους, καθώς εγχαράττονται αι σφραγίδες, με τα ονόματα των υιών Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Και έθεσεν αυτούς επί των επωμίδων του εφόδ, λίθους μνημοσύνου εις τους υιούς Ισραήλ, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Και έκαμε το περιστήθιον εντέχνου εργασίας, κατά την εργασίαν του εφόδ, εκ χρυσίου, εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Τετράγωνον ήτο· διπλούν έκαμον το περιστήθιον· μιας σπιθαμής το μήκος αυτού και μιας σπιθαμής το πλάτος αυτού, διπλού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Και ενήρμοσαν εις αυτό τέσσαρας σειράς λίθων· σειρά σαρδίου, τοπαζίου και σμαράγδου ήτο η σειρά η πρώτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Και η δευτέρα σειρά, άνθραξ, σάπφειρος και αδάμας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Και η τρίτη σειρά, λιγύριον, αχάτης και αμέθυστος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Και η τετάρτη σειρά, βηρύλλιον, όνυξ και ίασπις· ούτοι ήσαν ενηρμοσμένοι εν οικίσκοις χρυσοίς εις τα περικλείσματα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Και οι λίθοι ήσαν κατά τα ονόματα των υιών Ισραήλ, δώδεκα, κατά τα ονόματα αυτών, κατά την γλυφήν της σφραγίδος, έκαστος με το όνομα αυτού κατά τας δώδεκα φυλάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Και έκαμον επί το περιστήθιον αλύσεις κατά τα άκρα, πλεκτής εργασίας εκ χρυσίου καθαρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Και έκαμον δύο οικίσκους χρυσούς και δύο κρίκους χρυσούς και επέρασαν τους δύο κρίκους εις τα δύο άκρα του περιστηθίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Και επέρασαν τας δύο πλεκτάς χρυσάς αλύσεις εις τους δύο κρίκους τους εις τα άκρα του περιστηθίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Και τα δύο άκρα των δύο πλεκτών αλύσεων συνήψαν με τους δύο οικίσκους και έβαλον αυτούς επί των επωμίδων του εφόδ, εις το έμπροσθεν μέρος αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Και έκαμον δύο κρίκους χρυσούς και έβαλον αυτούς επί των δύο άκρων του περιστηθίου, εις το χείλος αυτού, το οποίον ήτο κατά το μέρος του εφόδ έσωθεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Και έκαμον δύο άλλους κρίκους χρυσούς και έβαλον αυτούς εις τα δύο πλάγια του εφόδ κάτωθεν, προς το εμπροσθινόν μέρος αυτού αντικρύ της άλλης ενώσεως αυτού άνωθεν της κεντητής ζώνης του εφόδ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Και έδεσαν το περιστήθιον διά των κρίκων αυτού εις τους κρίκους του εφόδ με ταινίαν εκ κυανού, διά να ήναι άνωθεν της κεντητής ζώνης του εφόδ, και διά να μη ήναι το περιστήθιον κεχωρισμένον από του εφόδ· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Και έκαμε τον ποδήρη του εφόδ εργασίας υφαντής, όλον εκ κυανού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Και ήτο άνοιγμα εν τω μέσω του ποδήρους, ως άνοιγμα θώρακος, με ταινίαν κύκλω του ανοίγματος, διά να μη σχίζηται.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Και έκαμον επί των κρασπέδων του ποδήρους ρόδια εκ κυανού και πορφυρού και κοκκίνου και βύσσου κεκλωσμένης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Και έκαμον κώδωνας εκ χρυσίου καθαρού και έβαλον τους κώδωνας μεταξύ των ροδίων επί του κρασπέδου του ποδήρους κύκλω μεταξύ των ροδίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'κώδωνα και ρόδιον, κώδωνα και ρόδιον, επί των κρασπέδων του ποδήρους του λειτουργικού κύκλω καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Και έκαμον τους χιτώνας εκ βύσσου υφαντής εργασίας, διά τον Ααρών και διά τους υιούς αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'και την μίτραν εκ βύσσου και τα μιτρίδια κεκοσμημένα εκ βύσσου και τα λινά περισκελή εκ βύσσου κεκλωσμένης,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'και την ζώνην εκ βύσσου κεκλωσμένης και κυανού και πορφυρού και κοκκίνου, κεντητής εργασίας· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Και έκαμον το πέταλον του ιερού στέμματος εκ χρυσίου καθαρού και ενεχάραξαν επ\' αυτό γράμματα ως χάραγμα σφραγίδος, ΑΓΙΑΣΜΟΣ ΕΙΣ ΤΟΝ ΚΥΡΙΟΝ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Και έδεσαν εις αυτό ταινίαν κυανήν, διά να συνάψωσιν αυτό άνωθεν επί της μίτρας· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Ούτως ετελειώθη άπαν το έργον της σκηνής του μαρτυρίου· και έκαμον οι υιοί Ισραήλ κατά πάντα όσα προσέταξεν ο Κύριος εις τον Μωϋσήν· ούτως έκαμον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Και έφεραν την σκηνήν προς τον Μωϋσήν· την σκηνήν, και πάντα τα σκεύη αυτής, τας περόνας αυτής, τας σανίδας αυτής, τους μοχλούς αυτής και τους στύλους αυτής, και τα υποβάσια αυτής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'και το επικάλυμμα το εκ δερμάτων κριών κοκκινοβαφών και το επικάλυμμα το εκ δερμάτων θώων και το καλυπτήριον καταπέτασμα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'την κιβωτόν του μαρτυρίου και τους μοχλούς αυτής και το ιλαστήριον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'την τράπεζαν, πάντα τα σκεύη αυτής και τους άρτους της προθέσεως,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'την καθαράν λυχνίαν, τους λύχνους αυτής, τους λύχνους κατά την διάταξιν αυτών και πάντα τα σκεύη αυτής και το έλαιον του φωτός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'και το χρυσούν θυσιαστήριον και το χριστήριον έλαιον και το ευώδες θυμίαμα και τον τάπητα διά την θύραν της σκηνής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'το χάλκινον θυσιαστήριον και την χαλκίνην εσχάραν αυτού, τους μοχλούς αυτού και πάντα τα σκεύη αυτού, τον νιπτήρα και την βάσιν αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'τα παραπετάσματα της αυλής, τους στύλους αυτής και τα υποβάσια αυτής και το καταπέτασμα διά την πύλην της αυλής, τα σχοινία αυτής και τους πασσάλους αυτής και πάντα τα σκεύη της υπηρεσίας της σκηνής διά την σκηνήν του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'τας λειτουργικάς στολάς, διά να λειτουργώσιν εν τω αγίω, και τας αγίας στολάς διά τον Ααρών τον ιερέα και τας στολάς των υιών αυτού, διά να ιερατεύωσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Κατά πάντα όσα προσέταξεν ο Κύριος εις τον Μωϋσήν, ούτως έκαμον οι υιοί Ισραήλ άπαν το έργον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Και είδεν ο Μωϋσής άπαν το έργον και ιδού, είχον κάμει αυτό καθώς προσέταξεν ο Κύριος· ούτως έκαμον· και ευλόγησεν αυτούς ο Μωϋσής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Την πρώτην ημέραν του πρώτου μηνός θέλεις στήσει την σκηνήν, την σκηνήν του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Και θέλεις θέσει εκεί την κιβωτόν του μαρτυρίου, και σκεπάσει την κιβωτόν με το καταπέτασμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Και θέλεις εισάξει την τράπεζαν και διατάξει τα διατακτέα επ\' αυτής· και θέλεις εισάξει την λυχνίαν και ανάψει τους λύχνους αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Και θέλεις θέσει το χρυσούν θυσιαστήριον του θυμιάματος έμπροσθεν της κιβωτού του μαρτυρίου και επιβάλει τον τάπητα της θύρας εις την σκηνήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Και θέλεις θέσει το θυσιαστήριον του ολοκαυτώματος έμπροσθεν της θύρας της σκηνής, της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Και θέλεις θέσει τον νιπτήρα μεταξύ της σκηνής του μαρτυρίου και του θυσιαστηρίου και βάλει ύδωρ εν αυτώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Και θέλεις στήσει την αυλήν κύκλω και κρεμάσει το καταπέτασμα της πύλης της αυλής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Και θέλεις λάβει το χριστήριον έλαιον και χρίσει την σκηνήν και πάντα τα εν αυτή, και θέλεις αγιάσει αυτήν και πάντα τα σκεύη αυτής και θέλει είσθαι αγία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Και θέλεις χρίσει το θυσιαστήριον του ολοκαυτώματος και πάντα τα σκεύη αυτού και θέλεις αγιάσει το θυσιαστήριον· και θέλει είσθαι θυσιαστήριον αγιώτατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Και θέλεις χρίσει τον νιπτήρα και την βάσιν αυτού και αγιάσει αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Και θέλεις προσαγάγει τον Ααρών και τους υιούς αυτού εις την θύραν της σκηνής του μαρτυρίου και νίψει αυτούς με ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Και θέλεις ενδύσει τον Ααρών τας αγίας στολάς και θέλεις χρίσει αυτόν, και αγιάσει αυτόν, και θέλει ιερατεύει εις εμέ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Και θέλεις προσαγάγει τους υιούς αυτού και ενδύσει αυτούς χιτώνας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Και θέλεις χρίσει αυτούς, καθώς έχρισας τον πατέρα αυτών, και θέλουσιν ιερατεύει εις εμέ· και θέλει είσθαι εις αυτούς το χρίσμα αυτών προς παντοτεινήν ιερατείαν εις τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Και έκαμεν ο Μωϋσής κατά πάντα όσα προσέταξεν ο Κύριος εις αυτόν· ούτως έκαμε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Και τον πρώτον μήνα του δευτέρου έτους, την πρώτην του μηνός, εστήθη η σκηνή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Και έστησεν ο Μωϋσής την σκηνήν και έβαλε τα υποβάσια αυτής και έστησε τας σανίδας αυτής και έβαλε τους μοχλούς αυτής και έστησε τους στύλους αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Και εξήπλωσε τα παραπετάσματα επί την σκηνήν, και έβαλε το επικάλυμμα της σκηνής επ\' αυτήν άνωθεν· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Και λαβών το μαρτύριον έθεσεν εν τη κιβωτώ, και έβαλε τους μοχλούς εις την κιβωτόν, και έβαλε το ιλαστήριον επί την κιβωτόν άνωθεν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'και έφερε την κιβωτόν εις την σκηνήν, και επέθηκε το καλυπτήριον καταπέτασμα και εσκέπασε την κιβωτόν του μαρτυρίου· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Και έθεσε την τράπεζαν εν τη σκηνή του μαρτυρίου κατά το μέρος της σκηνής το προς βορράν έξωθεν του καταπετάσματος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'και διέταξεν επ\' αυτής τους άρτους τους διατεταγμένους, ενώπιον Κυρίου· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Και έθεσε την λυχνίαν εν τη σκηνή του μαρτυρίου απέναντι της τραπέζης κατά το μέρος της σκηνής το προς μεσημβρίαν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'και ανήψε τους λύχνους ενώπιον Κυρίου· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Και έθεσε το χρυσούν θυσιαστήριον εν τη σκηνή του μαρτυρίου απέναντι του καταπετάσματος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'και εθυμίασεν επ\' αυτού ευώδες θυμίαμα· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Και επέθηκε τον τάπητα εις την θύραν της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Και το θυσιαστήριον του ολοκαυτώματος έθεσε παρά την θύραν της σκηνής, της σκηνής του μαρτυρίου, και προσέφερεν επ\' αυτού το ολοκαύτωμα και την εξ αλφίτων προσφοράν· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Και έθεσε τον νιπτήρα μεταξύ της σκηνής του μαρτυρίου και του θυσιαστηρίου και έβαλεν εν αυτώ, ύδωρ, διά να νίπτωνται·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'και ένιπτον εξ αυτού ο Μωϋσής και ο Ααρών και οι υιοί αυτού τας χείρας αυτών και τους πόδας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Ότε εισήρχοντο εις την σκηνήν του μαρτυρίου και ότε προσήρχοντο εις το θυσιαστήριον, ενίπτοντο καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Και έστησε την αυλήν κύκλω της σκηνής και του θυσιαστηρίου και εκρέμασε τον τάπητα της πύλης της αυλής. Και συνετέλεσεν ο Μωϋσής το έργον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Τότε εκάλυψεν η νεφέλη την σκηνήν του μαρτυρίου και δόξα Κυρίου ενέπλησε την σκηνήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Και δεν ηδυνήθη ο Μωϋσής να εισέλθη εις την σκηνήν του μαρτυρίου· διότι η νεφέλη εκάθητο επ\' αυτήν, και δόξα Κυρίου ενέπλησε την σκηνήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Και ότε η νεφέλη ανέβαινεν επάνωθεν της σκηνής, οι υιοί Ισραήλ εσηκόνοντο καθ\' όλας αυτών τας οδοιπορίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'αν όμως η νεφέλη δεν ανέβαινε, τότε δεν εσηκόνοντο μέχρι της ημέρας της αναβάσεως αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'διότι η νεφέλη του Κυρίου ήτο επί της σκηνής την ημέραν, και πυρ ήτο επ\' αυτής την νύκτα, ενώπιον παντός του οίκου Ισραήλ· καθ\' όλας αυτών τας οδοιπορίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Και εκάλεσε Κύριος τον Μωϋσήν και ελάλησε προς αυτόν εκ της σκηνής του μαρτυρίου, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Εάν τις από σας προσφέρη δώρον προς τον Κύριον, θέλετε προσφέρει το δώρον σας από των κτηνών, από των βοών ή από των προβάτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Εάν το δώρον αυτού ήναι ολοκαύτωμα από των βοών, αρσενικόν άμωμον ας προσφέρη αυτό· παρά την θύραν της σκηνής του μαρτυρίου θέλει προσφέρει αυτό, διά να ήναι δεκτόν ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν του ολοκαυτώματος και θέλει είσθαι δεκτόν υπέρ αυτού, διά να γείνη εξιλέωσις περί αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Και θέλουσι σφάξει τον μόσχον ενώπιον Κυρίου· και οι υιοί του Ααρών, οι ιερείς, θέλουσι φέρει το αίμα και θέλουσι ραντίσει το αίμα κύκλω επί το θυσιαστήριον το παρά την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Και θέλουσιν εκδάρει το ολοκαύτωμα και θέλουσι διαμελίσει αυτό κατά τα μέλη αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Και οι υιοί του Ααρών του ιερέως θέλουσι βάλει πυρ επί το θυσιαστήριον και θέλουσι στοιβάσει ξύλα επί το πυρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Και οι υιοί του Ααρών, οι ιερείς, θέλουσιν επιστοιβάσει τα μέλη, την κεφαλήν και το στέαρ, επί τα ξύλα τα επί του πυρός, του επί του θυσιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'τα δε εντόσθια αυτού και τους πόδας αυτού θέλουσι πλύνει με ύδωρ· και θέλει καύσει ο ιερεύς τα πάντα επί του θυσιαστηρίου· ολοκαύτωμα είναι, θυσία γινομένη διά πυρός εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Εάν δε το δώρον αυτού διά το ολοκαύτωμα ήναι εκ των ποιμνίων, εκ των προβάτων ή εκ των αιγών, αρσενικόν άμωμον θέλει προσφέρει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Και θέλουσι σφάξει αυτό εις τα πλάγια του θυσιαστηρίου προς βορράν ενώπιον Κυρίου· και θέλουσι ραντίσει οι υιοί του Ααρών, οι ιερείς, το αίμα αυτού επί το θυσιαστήριον κύκλω·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'και θέλουσι διαμελίσει αυτό κατά τα μέλη αυτού και την κεφαλήν αυτού και το στέαρ αυτού· και θέλει επιστοιβάσει αυτά ο ιερεύς επί τα ξύλα τα επί του πυρός του επί του θυσιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'τα δε εντόσθια και τους πόδας θέλουσι πλύνει με ύδωρ· και θέλει φέρει τα πάντα ο ιερεύς και καύσει αυτά επί του θυσιαστηρίου· ολοκαύτωμα είναι, θυσία γινομένη διά πυρός εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Και εάν το δώρον αυτού προς τον Κύριον ήναι ολοκαύτωμα από πτηνών, τότε θέλει προσφέρει το δώρον αυτού από τρυγόνων ή από νεοσσών περιστερών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Και θέλει προσαγάγει αυτό ο ιερεύς προς το θυσιαστήριον και θέλει αποκόψει διά των ονύχων την κεφαλήν αυτού και καύσει αυτό επί του θυσιαστηρίου· και το αίμα αυτού θέλει στραγγίσει προς το πλάγιον του θυσιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'και θέλει εκβάλει τον πρόλοβον αυτού μετά της κόπρου αυτού και ρίψει αυτά εις τα πλάγια του θυσιαστηρίου κατά ανατολάς, εις τον τόπον της στάκτης·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'και θέλει διασχίσει αυτό εκ των πτερύγων αυτού, πλην δεν θέλει διαχωρίσει και θέλει καύσει αυτό ο ιερεύς επί του θυσιαστηρίου, επί των ξύλων των επί του πυρός· ολοκαύτωμα είναι, θυσία γινομένη διά πυρός εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Εάν δε προσφέρη τις δώρον προσφοράν εξ αλφίτων προς τον Κύριον, σεμίδαλις θέλει είσθαι το δώρον αυτού· και θέλει επιχύσει επ\' αυτό έλαιον και επιθέσει επ\' αυτό λιβάνιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Και θέλει φέρει αυτό προς τους υιούς του Ααρών, τους ιερείς· και ο ιερεύς θέλει δράξει από της σεμιδάλεως αυτού και από του ελαίου αυτού όσον χωρεί η χειρ αυτού και άπαν το λιβάνιον αυτού· και θέλει καύσει ο ιερεύς το μνημόσυνον αυτού επί του θυσιαστηρίου· είναι θυσία γινομένη διά πυρός εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Το δε υπόλοιπον της εξ αλφίτων προσφοράς θέλει είσθαι του Ααρών και των υιών αυτού· είναι αγιώτατον εκ των θυσιών των γινομένων διά πυρός προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Και όταν προσφέρης δώρον προσφοράν εξ αλφίτων εψημένην εν κλιβάνω, θέλει είσθαι άρτοι άζυμοι από σεμιδάλεως εζυμωμένης μετά ελαίου και λάγανα άζυμα κεχρισμένα με έλαιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Εάν δε το δώρον σου ήναι προσφορά εξ αλφίτων εψημένη εις κάψαν, άζυμον θέλει είσθαι εκ σεμιδάλεως εζυμωμένης μετά ελαίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Θέλεις διαμερίσει αυτήν εις τμήματα και θέλεις επιχύσει επ\' αυτής έλαιον· είναι προσφορά εξ αλφίτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Και εάν το δώρον σου ήναι προσφορά εξ αλφίτων εψημένη εν τηγανίω, θέλει γείνει από σεμιδάλεως μετά ελαίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Και θέλεις φέρει προς τον Κύριον την εξ αλφίτων προσφοράν, την οποίαν έκαμες εκ τούτων· και όταν φερθή προς τον ιερέα, αυτός θέλει πλησιάσει αυτήν εις το θυσιαστήριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Και θέλει χωρίσει ο ιερεύς από της εξ αλφίτων προσφοράς το μνημόσυνον αυτής και καύσει αυτό επί του θυσιαστηρίου· είναι θυσία γινομένη διά πυρός εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Το δε υπόλοιπον της εξ αλφίτων προσφοράς θέλει είσθαι του Ααρών και των υιών αυτού· είναι αγιώτατον εκ τών διά πυρός γινομένων θυσιών εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Ουδεμία προσφορά εξ αλφίτων, την οποίαν προσφέρετε προς τον Κύριον, θέλει είσθαι ένζυμος· διότι ουδέν προζύμιον ουδέ μέλι θέλετε καύσει εις ουδεμίαν θυσίαν γινομένην διά πυρός προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Περί δε του δώρου των απαρχών, θέλετε προσφέρει αυτάς προς τον Κύριον· δεν θέλουσιν όμως καυθή επί του θυσιαστηρίου εις οσμήν ευωδίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Και παν δώρον της εξ αλφίτων προσφοράς σου θέλεις αλατίζει με άλας· και δεν θέλεις αφήσει να λείψη από της εξ αλφίτων προσφοράς σου το άλας της διαθήκης του Θεού σου· επί παντός δώρου σου θέλεις προσφέρει άλας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Και εάν προσφέρης προσφοράν εξ αλφίτων από των πρωτογεννημάτων σου προς τον Κύριον, θέλεις προσφέρει διά την εξ αλφίτων προσφοράν των πρωτογεννημάτων σου αστάχυα χλωρά εψημένα εν πυρί, σίτον πεφρυγανισμένον εξ ασταχύων μεστών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Και θέλεις χύσει επ\' αυτήν έλαιον και θέλεις θέσει επ\' αυτήν λιβάνιον· είναι προσφορά εξ αλφίτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Και ο ιερεύς θέλει καύσει το μνημόσυνον αυτής εκ του πεφρυγανισμένον σίτου αυτής και εκ του ελαίου αυτής, μεθ\' όλου λιβανίου αυτής· είναι θυσία γινομένη διά πυρός εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Εάν δε το δώρον αυτού ήναι θυσία ειρηνική, εάν προσφέρη αυτό εκ των βοών, είτε αρσενικόν είτε θηλυκόν, άμωμον θέλει προσφέρει αυτό ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν του δώρου αυτού, και θέλουσι σφάξει αυτό παρά την θύραν της σκηνής του μαρτυρίου· και οι υιοί του Ααρών, οι ιερείς, θέλουσι ραντίσει το αίμα επί το θυσιαστήριον κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Και θέλει προσφέρει εκ της ειρηνικής προσφοράς, θυσίαν γινομένην διά πυρός εις τον Κύριον· το στέαρ το περικαλύπτον τα εντόσθια και άπαν το στέαρ το επί των εντοσθίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'και τους δύο νεφρούς και το στέαρ το επ\' αυτών το προς τα πλευρά, και τον επάνω λοβόν του ήπατος, τον οποίον μετά των νεφρών θέλει αφαιρέσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Και οι υιοί του Ααρών θέλουσι καύσει αυτά επί του θυσιαστηρίου επί του ολοκαυτώματος του επί των ξύλων των επί του πυρός· είναι θυσία γινομένη διά πυρός εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Εάν δε το δώρον αυτού, το εις θυσίαν ειρηνικήν προσφερόμενον προς τον Κύριον, ήναι εκ του ποιμνίου, αρσενικόν ή θηλυκόν, άμωμον θέλει προσφέρει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Εάν αρνίον προσφέρη το δώρον αυτού, θέλει προσφέρει αυτό ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν του δώρου αυτού, και θέλουσι σφάξει αυτό έμπροσθεν της σκηνής του μαρτυρίου· και οι υιοί του Ααρών θέλουσι ραντίσει το αίμα αυτού επί το θυσιαστήριον κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Και θέλει προσφέρει εκ της προσφοράς της ειρηνικής θυσίαν γινομένην διά πυρός εις τον Κύριον· το στέαρ αυτού, την ουράν ολόκληρον, την οποίαν θέλει αφαιρέσει από της ράχης και το στέαρ το περικαλύπτον τα εντόσθια και παν το στέαρ το επί των εντοσθίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'και τους δύο νεφρούς και το στέαρ το επ\' αυτών το προς τα πλευρά, και τον επάνω λοβόν του ήπατος, τον οποίον μετά των νεφρών θέλει αφαιρέσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Και θέλει καύσει αυτά ο ιερεύς επί του θυσιαστηρίου· είναι τροφή της διά πυρός γινομένης θυσίας εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Εάν δε το δώρον αυτού ήναι εξ αιγών, τότε θέλει προσφέρει αυτό ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν αυτού, και θέλουσι σφάξει αυτό έμπροσθεν της σκηνής του μαρτυρίου· και οι υιοί του Ααρών θέλουσι ραντίσει το αίμα αυτού επί το θυσιαστήριον κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Και θέλει προσφέρει εξ αυτού το δώρον αυτού, θυσίαν γινομένην διά πυρός εις τον Κύριον· το στέαρ το περικαλύπτον τα εντόσθια και παν το στέαρ το επί των εντοσθίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'και τους δύο νεφρούς και το στέαρ το επ\' αυτών το προς τα πλευρά, και τον επάνω λοβόν του ήπατος, τον οποίον μετά των νεφρών θέλει αφαιρέσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Και θέλει καύσει αυτά ο ιερεύς επί του θυσιαστηρίου· είναι τροφή της θυσίας της γινομένης διά πυρός εις οσμήν ευωδίας· παν το στέαρ είναι του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Νόμιμον αιώνιον θέλει είσθαι εις τας γενεάς σας, εις πάσας τας κατοικήσεις σας· δεν θέλετε τρώγει ούτε στέαρ ούτε αίμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Λάλησον προς τους υιούς Ισραήλ, λέγων, Εάν ψυχή τις αμαρτήση εξ αγνοίας και εκ των όσα είναι προστεταγμένον υπό του Κυρίου να μη πράττωνται πράξη τι εξ αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'εάν μεν ο ιερεύς ο κεχρισμένος αμαρτήση ώστε να ενοχοποιήση τον λαόν, τότε θέλει φέρει, διά την αμαρτίαν αυτού την οποίαν ημάρτησε, μόσχον βοός άμωμον προς τον Κύριον διά προσφοράν περί αμαρτίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Και θέλει φέρει τον μόσχον εις την θύραν της σκηνής του μαρτυρίου ενώπιον του Κυρίου· και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν του μόσχου, και θέλουσι σφάξει τον μόσχον ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Και θέλει λάβει ο ιερεύς ο κεχρισμένος από του αίματος του μόσχου και φέρει αυτό εις την σκηνήν του μαρτυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'και θέλει εμβάψει ο ιερεύς τον δάκτυλον αυτού εις το αίμα και θέλει ραντίσει από του αίματος επτάκις ενώπιον του Κυρίου, έμπροσθεν του καταπετάσματος του αγιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Και θέλει βάλει ο ιερεύς από του αίματος επί τα κέρατα του θυσιαστηρίου του ευώδους θυμιάματος, το οποίον είναι ενώπιον του Κυρίου εν τη σκηνή του μαρτυρίου· και θέλει χύσει παν το αίμα του μόσχου εις την βάσιν του θυσιαστηρίου του ολοκαυτώματος, το οποίον είναι εις την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Και άπαν το στέαρ του μόσχου της περί αμαρτίας προσφοράς θέλει αφαιρέσει απ\' αυτού· το στέαρ το περικαλύπτον τα εντόσθια, και άπαν το στέαρ το επί των εντοσθίων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'και τους δύο νεφρούς και το στέαρ το επ\' αυτών το προς τα πλευρά, και τον επάνω λοβόν του ήπατος, τον οποίον μετά των νεφρών θέλει αφαιρέσει,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'καθ\' ον τρόπον αφαιρείται από του μόσχου της θυσίας της ειρηνικής· και θέλει καύσει αυτά ο ιερεύς επί του θυσιαστηρίου του ολοκαυτώματος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'και το δέρμα του μόσχου και παν το κρέας αυτού μετά της κεφαλής αυτού και μετά των ποδών αυτού και τα εντόσθια αυτού και την κόπρον αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'και θέλει φέρει όλον τον μόσχον έξω του στρατοπέδου εις τόπον καθαρόν, όπου χύνεται η στάκτη, και θέλει καύσει αυτόν επί ξύλων διά πυρός· όπου χύνεται η στάκτη, θέλει καυθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Εάν δε πάσα η συναγωγή του Ισραήλ αμαρτήση εξ αγνοίας και το πράγμα κρυφθή από των οφθαλμών της συναγωγής και εκ των όσα είναι προστεταγμένον υπό του Κυρίου να μη πράττωνται, πράξωσι και ήναι ένοχοι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'όταν γνωρισθή η αμαρτία την οποίαν ημάρτησαν κατά τούτο, τότε θέλει προσφέρει η συναγωγή μόσχον εκ βοών διά την αμαρτίαν και θέλει φέρει αυτόν έμπροσθεν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Και οι πρεσβύτεροι της συναγωγής θέλουσιν επιθέσει τας χείρας αυτών επί την κεφαλήν του μόσχου ενώπιον του Κυρίου· και θέλουσι σφάξει τον μόσχον ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Και ο ιερεύς ο κεχρισμένος θέλει φέρει από του αίματος του μόσχον εις την σκηνήν του μαρτυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'και θέλει εμβάψει ο ιερεύς τον δάκτυλον αυτού εις το αίμα και θέλει ραντίσει επτάκις ενώπιον του Κυρίου έμπροσθεν του καταπετάσματος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'και θέλει βάλει από του αίματος επί τα κέρατα του θυσιαστηρίου, του ενώπιον του Κυρίου, το οποίον είναι εν τη σκηνή του μαρτυρίου· και θέλει χύσει παν το αίμα εις την βάσιν του θυσιαστηρίου του ολοκαυτώματος, το οποίον είναι εις την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Και παν το στέαρ αυτού θέλει αφαιρέσει απ\' αυτού και καύσει επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Και θέλει κάμει εις τον μόσχον καθ\' ον τρόπον έκαμεν εις τον μόσχον της περί αμαρτίας προσφοράς· ούτω θέλει κάμει εις αυτόν· και θέλει κάμει εξιλέωσιν υπέρ αυτών ο ιερεύς και θέλει συγχωρηθή εις αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Και θέλει εκβάλει τον μόσχον έξω του στρατοπέδου και καύσει αυτόν, καθώς έκαυσε τον πρώτον μόσχον· είναι προσφορά περί αμαρτίας υπέρ της συναγωγής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Όταν δε άρχων τις αμαρτήση και πράξη εξ αγνοίας τι εκ των όσα είναι προστεταγμένον υπό Κυρίου του Θεού αυτού να μη πράττωνται, και ήναι ένοχος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'ή εάν η αμαρτία αυτού, την οποίαν ημάρτησε, γνωστοποιηθή εις αυτόν, τότε θέλει φέρει την προσφοράν αυτού, τράγον εξ αιγών, αρσενικόν άμωμον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν του τράγου, και θέλουσι σφάξει αυτό εν τω τόπω όπου σφάζουσι το ολοκαύτωμα ενώπιον του Κυρίου· είναι προσφορά περί αμαρτίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Και θέλει λάβει ο ιερεύς από του αίματος της περί αμαρτίας προσφοράς διά του δακτύλου αυτού, και βάλει επί τα κέρατα του θυσιαστηρίου του ολοκαυτώματος και θέλει χύσει το αίμα αυτού εις την βάσιν του θυσιαστηρίου του ολοκαυτώματος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Και άπαν το στέαρ αυτού θέλει καύσει επί του θυσιαστηρίου, ως το στέαρ της θυσίας της ειρηνικής προσφοράς· και θέλει κάμει εξιλέωσιν υπέρ αυτού ο ιερεύς περί της αμαρτίας αυτού, και θέλει συγχωρηθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Εάν δε ψυχή τις εκ του λαού της γης αμαρτήση εξ αγνοίας, πράττων τι εκ των όσα είναι προστεταγμένον υπό του Κυρίου να μη πράττωνται, και ήναι ένοχος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'ή εάν γνωστοποιηθή εις αυτόν η αμαρτία αυτού την οποίαν ημάρτησε· τότε θέλει φέρει την προσφοράν αυτού, τράγον εξ αιγών, θηλυκόν άμωμον, διά την αμαρτίαν αυτού την οποίαν ημάρτησε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν της περί αμαρτίας προσφοράς, και θέλουσι σφάξει την περί αμαρτίας προσφοράν εν τω τόπω του ολοκαυτώματος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Και θέλει λάβει ο ιερεύς διά του δακτύλου αυτού από του αίματος αυτού, και βάλει επί τα κέρατα του θυσιαστηρίου του ολοκαυτώματος και παν το αίμα αυτού θέλει χύσει εις την βάσιν του θυσιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'και παν το στέαρ αυτού θέλει αφαιρέσει, καθώς αφαιρείται το στέαρ από της θυσίας της ειρηνικής προσφοράς· και θέλει καύσει αυτό ο ιερεύς επί του θυσιαστηρίου εις οσμήν ευωδίας προς τον Κύριον· και θέλει κάμει εξιλέωσιν υπέρ αυτού ο ιερεύς, και θέλει συγχωρηθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Εάν δε φέρη πρόβατον διά προσφοράν αυτού περί αμαρτίας, θέλει φέρει αυτό θηλυκόν άμωμον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'και θέλει επιθέσει την χείρα αυτού επί την κεφαλήν της περί αμαρτίας προσφοράς, και θέλουσι σφάξει αυτό διά προσφοράν περί αμαρτίας, εν τω τόπω όπου σφάζουσι το ολοκαύτωμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Και θέλει λάβει ο ιερεύς από του αίματος της περί αμαρτίας προσφοράς διά του δακτύλου αυτού και βάλει επί τα κέρατα του θυσιαστηρίου του ολοκαυτώματος και άπαν το αίμα αυτού θέλει χύσει εις την βάσιν του θυσιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'και θέλει αφαιρέσει παν το στέαρ αυτού, καθώς αφαιρείται το στέαρ του προβάτου από της θυσίας της ειρηνικής προσφοράς· και θέλει καύσει αυτά ο ιερεύς επί του θυσιαστηρίου κατά τας προσφοράς τας γινομένας διά πυρός εις τον Κύριον· και θέλει κάμει ο ιερεύς εξιλέωσιν περί της αμαρτίας αυτού την οποίαν ημάρτησε, και θέλει συγχωρηθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Εάν δε τις αμαρτήση και ακούση φωνήν ορκισμού και ήναι μάρτυς, είτε είδεν είτε εξεύρει εάν δεν φανερώση αυτό, τότε θέλει βαστάσει την ανομίαν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Η εάν τις εγγίση πράγμά τι ακάθαρτον, είτε θνησιμαίον ακαθάρτον θηρίου είτε θνησιμαίον ακαθάρτου κτήνους είτε θνησιμαίον ερπετών ακαθάρτων, και έλαθεν αυτόν, όμως θέλει είσθαι ακάθαρτος και ένοχος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Η εάν εγγίση ακαθαρσίαν ανθρώπου, εξ οποιασδήποτε ήθελεν είσθαι η ακαθαρσία αυτού, διά της οποίας μιαίνεταί τις, και έλαθεν αυτόν· όταν αυτός γνωρίση τούτο, τότε θέλει είσθαι ένοχος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Η εάν τις ομόση, προφέρων αστοχάστως διά των χειλέων αυτού να κακοποιήση, ή να αγαθοποιήση εις παν ό,τι ήθελε προφέρει αστοχάστως ο άνθρωπος μεθ\' όρκου και έλαθεν αυτόν· όταν γνωρίση τούτο, τότε θέλει είσθαι ένοχος εις εν εκ τούτων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Όταν λοιπόν είναι τις ένοχος εις εν εκ τούτων, θέλει εξομολογηθή κατά τι ημάρτησε·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'και θέλει φέρει προς τον Κύριον προσφοράν περί της παραβάσεως αυτού, διά την αμαρτίαν αυτού την οποίαν ημάρτησε, θηλυκόν αρνίον εκ προβάτων ή τράγον εξ αιγών, εις προσφοράν περί αμαρτίας· και θέλει κάμει εξιλέωσιν ο ιερεύς υπέρ αυτού περί της αμαρτίας αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Και εάν δεν ευπορή να φέρη πρόβατον ή αίγα, θέλει φέρει προς τον Κύριον, διά την αμαρτίαν αυτού την οποίαν ημάρτησε, δύο τρυγόνας ή δύο νεοσσούς περιστερών· μίαν διά προσφοράν περί αμαρτίας και μίαν διά ολοκαύτωμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Και θέλει φέρει αυτάς προς τον ιερέα, όστις θέλει προσφέρει πρώτον εκείνην την περί αμαρτίας προσφοράν· και θέλει κόψει διά των ονύχων την κεφαλήν αυτής από του αυχένος αυτής, πλην δεν θέλει διαχωρίσει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Και από του αίματος της περί αμαρτίας προσφοράς θέλει ραντίσει τον τοίχον του θυσιαστηρίου· το δε εναπολειφθέν του αίματος θέλει στραγγίσει έξω εις την βάσιν του θυσιαστηρίου· είναι προσφορά περί αμαρτίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Την δε δευτέραν θέλει κάμει ολοκαύτωμα κατά το διατεταγμένον· και θέλει κάμει ο ιερεύς εξιλέωσιν υπέρ αυτού, περί της αμαρτίας αυτού την οποίαν ημάρτησε, και θέλει συγχωρηθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Αλλ\' εάν δεν ευπορή να φέρη δύο τρυγόνας ή δύο νεοσσούς περιστερών, τότε θέλει φέρει ο αμαρτήσας διά προσφοράν αυτού το δέκατον ενός εφά σεμιδάλεως εις προσφοράν περί αμαρτίας· δεν θέλει βάλει επ\' αυτήν έλαιον ουδέ θέλει βάλει επ\' αυτήν λιβάνιον· διότι είναι προσφορά περί αμαρτίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'και θέλει φέρει αυτήν προς τον ιερέα· και ο ιερεύς θέλει δράξει απ\' αυτής όσον χωρεί η χειρ αυτού, το μνημόσυνον αυτής, και θέλει καύσει αυτό επί του θυσιαστηρίου, κατά τας προσφοράς τας διά πυρός γινομένας εις τον Κύριον· είναι προσφορά περί αμαρτίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Και θέλει κάμει ο ιερεύς εξιλέωσιν υπέρ αυτού περί της αμαρτίας αυτού την οποίαν ημάρτησεν εις εν εκ τούτων, και θέλει συγχωρηθή εις αυτόν· το δε υπόλοιπον θέλει είσθαι του ιερέως, ως η εξ αλφίτων προσφορά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Εάν τις πράξη παρανομίαν και αμαρτήση εξ αγνοίας εις τα άγια του Κυρίου, τότε θέλει φέρει προς τον Κύριον διά την ανομίαν αυτού κριόν άμωμον εκ του ποιμνίου, κατά την εκτίμησίν σου εις σίκλους αργυρίου, κατά τον σίκλον του αγιαστηρίου, διά προσφοράν περί ανομίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'και θέλει αποδώσει ό,τι ημάρτησεν εις τα άγια και θέλει προσθέσει επ\' αυτό το πέμπτον αυτού και δώσει αυτό εις τον ιερέα· και θέλει κάμει ο ιερεύς εξιλέωσιν υπέρ αυτού διά του κριού της περί ανομίας προσφοράς, και θέλει συγχωρηθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Και εάν τις αμαρτήση και πράξη τι εκ των όσα είναι προστεταγμένον υπό του Κυρίου να μη πράττωνται, και δεν εγνώρισεν αυτό, όμως θέλει είσθαι ένοχος και θέλει βαστάσει την ανομίαν αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'και θέλει φέρει κριόν άμωμον εκ του ποιμνίου κατά την εκτίμησίν σου, εις προσφοράν περί ανομίας, προς τον ιερέα· και θέλει κάμει ο ιερεύς εξιλέωσιν υπέρ αυτού περί της αγνοίας αυτού, εις την οποίαν ελανθάσθη και δεν εγνώρισε τούτο, και θέλει συγχωρηθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Είναι προσφορά περί ανομίας· αυτός ανομίαν έπραξε κατά του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Εάν τις αμαρτήση και πράξη παρανομίαν κατά του Κυρίου και ψευσθή προς τον πλησίον αυτού διά παρακαταθήκην ή διά πράγμά τι εμπεπιστευμένον εις τας χείρας αυτού, ή διά αρπαγήν, ή ηπάτησε τον πλησίον αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'ή εύρε πράγμα χαμένον και ψεύδεται περί αυτού, ή ομόση ψευδώς περί τινός εκ πάντων όσα πράττει ο άνθρωπος, ώστε να αμαρτήση εις αυτά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'όταν αμαρτήση και ήναι ένοχος, θέλει αποδώσει το άρπαγμα το οποίον ήρπασεν, ή το πράγμα το οποίον έλαβε δι\' απάτης, ή την παρακαταθήκην την εμπιστευθείσαν εις αυτόν, ή το χαμένον πράγμα το οποίον εύρεν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'ή παν εκείνο περί του οποίου ώμοσε ψευδώς· θέλει αποδώσει το κεφάλαιον αυτού, και θέλει προσθέσει το πέμπτον επ\' αυτό· εις όντινα ανήκει, εις τούτον θέλει αποδώσει αυτό την ημέραν καθ\' ην φανερωθή ένοχος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Και θέλει φέρει προς τον Κύριον την περί ανομίας προσφοράν αυτού, κριόν άμωμον εκ του ποιμνίου, κατά την εκτίμησίν σου, εις προσφοράν περί ανομίας, προς τον ιερέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'και ο ιερεύς θέλει κάμει εξιλέωσιν υπέρ αυτού ενώπιον του Κυρίου· και θέλει συγχωρηθή εις αυτόν, περί παντός πράγματος εκ των όσα έπραξε, ώστε να ανομήση εις αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Πρόσταξον τον Ααρών και τους υιούς αυτού, λέγων, Ούτος είναι ο νόμος του ολοκαυτώματος· το ολοκαύτωμα θέλει καίεσθαι επί του θυσιαστηρίου όλην την νύκτα έως το πρωΐ, και το πυρ του θυσιαστηρίου θέλει καίεσθαι επ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Και θέλει ενδυθή ο ιερεύς χιτώνα λινούν και περισκελή λινά θέλει φορέσει επί την σάρκα αυτού, και θέλει αφαιρέσει την στάκτην του ολοκαυτώματος το οποίον κατέφαγε το πυρ επί του θυσιαστηρίου· και θέλει βάλει αυτήν εις το πλάγιον του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Και θέλει εκδυθή την στολήν αυτού και ενδυθή άλλην στολήν· και θέλει φέρει την στάκτην έξω του στρατοπέδου εις τόπον καθαρόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Και το πυρ το επί του θυσιαστηρίου θέλει καίεσθαι επ\' αυτού· δεν θέλει σβεσθή· και θέλει καίει ο ιερεύς επ\' αυτού ξύλα καθ\' εκάστην πρωΐαν, και θέλει στοιβάσει το ολοκαύτωμα επ\' αυτού, και θέλει καίει επ\' αυτού το στέαρ της ειρηνικής προσφοράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Το πυρ θέλει καίεσθαι διαπαντός επί του θυσιαστηρίου· δεν θέλει σβεσθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Ούτος δε είναι ο νόμος της αλφίτων προσφοράς· οι υιοί του Ααρών θέλουσι προσφέρει αυτήν ενώπιον του Κυρίου έμπροσθεν του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Και θέλει αφαιρέσει απ\' αυτής όσον χωρεί η χειρ αυτού, από της σεμιδάλεως της εξ αλφίτων προσφοράς μετά του ελαίου αυτής και παν το λιβάνιον το επί της εξ αλφίτων προσφοράς· και θέλει καύσει αυτό επί του θυσιαστηρίου εις οσμήν ευωδίας, μνημόσυνον αυτής προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Το δε εναπολειφθέν εκ τούτων θέλουσι φάγει ο Ααρών και οι υιοί αυτού· άζυμον θέλει τρώγεσθαι εν τόπω αγίω εν τη αυλή της σκηνής του μαρτυρίου θέλουσι τρώγει αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Δεν θέλει εψηθή μετά προζυμίου· διά μερίδιον αυτών έδωκα αυτό από των διά πυρός γινομένων προσφορών μου· είναι αγιώτατον, καθώς η περί αμαρτίας προσφορά, και καθώς η περί ανομίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Παν αρσενικόν μεταξύ των τέκνων του Ααρών θέλει τρώγει αυτό· τούτο θέλει είσθαι νόμιμον αιώνιον εις τας γενεάς σας, από των διά πυρός γινομένων προσφορών του Κυρίου· πας όστις εγγίση αυτά, θέλει αγιασθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'τούτο είναι το δώρον του Ααρών και των υιών αυτού το οποίον θέλουσι προσφέρει προς τον Κύριον την ημέραν καθ\' ην χρισθή· το δέκατον ενός εφά σεμιδάλεως εις παντοτεινήν προσφοράν εξ αλφίτων, το ήμισυ αυτής το πρωΐ, και το ήμισυ αυτής το εσπέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'επί κάψης θέλει ετοιμασθή μετά ελαίου· εψημένον θέλεις φέρει αυτό· και τα εψημένα τμήματα των εξ αλφίτων προσφορών θέλεις προσφέρει εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Και ο ιερεύς ο κεχρισμένος αντ\' αυτού μεταξύ των υιών αυτού θέλει προσφέρει αυτό· τούτο είναι νόμιμον αιώνιον διά τον Κύριον. ολοκλήρως θέλει καίεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Και πάσα προσφορά εξ αλφίτων ιερέως θέλει καίεσθαι ολοκλήρως· δεν θέλει τρώγεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Λάλησον προς τον Ααρών και προς τους υιούς αυτού, λέγων, Ούτος είναι ο νόμος της περί αμαρτίας προσφοράς· Εν τω τόπω όπου σφάζεται το ολοκαύτωμα, θέλει σφαγή η περί αμαρτίας προσφορά έμπροσθεν του Κυρίου· είναι αγιώτατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Ο ιερεύς ο προσφέρων αυτήν περί αμαρτίας θέλει τρώγει αυτήν· εν τόπω αγίω θέλει τρώγεσθαι, εν τη αυλή της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'παν ό,τι εγγίση το κρέας αυτής θέλει είσθαι άγιον· και εάν ραντισθή από του αίματος αυτής επί τι φόρεμα, εκείνο, επί του οποίου ερραντίσθη, θέλει πλύνεσθαι εν τόπω αγίω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Το δε πήλινον αγγείον εν τω οποίω έβρασε, θέλει συντρίβεσθαι αλλ\' εάν βράση εν αγγείω χαλκίνω, τούτο θέλει τρίβεσθαι επιμελώς και θέλει πλύνεσθαι με ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Παν αρσενικόν μεταξύ των ιερέων θέλει τρώγει εξ αυτής· είναι αγιώτατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Και πάσα προσφορά περί αμαρτίας, από του αίματος της οποίας φέρεται εις την σκηνήν του μαρτυρίου διά να γείνη εξιλέωσις εν τω αγιαστηρίω, δεν θέλει τρώγεσθαι με πυρ θέλει καίεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Ούτος δε είναι ο νόμος της περί ανομίας προσφοράς· είναι αγιώτατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Εν τω τόπω όπου σφάζουσι το ολοκαύτωμα, θέλουσι σφάζει την περί ανομίας προσφοράν· και το αίμα αυτής θέλει ραντίζεσθαι επί το θυσιαστήριον κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Και θέλει προσφέρεσθαι εξ αυτής παν το στέαρ αυτής, η ουρά και το στέαρ το περικαλύπτον τα εντόσθια,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'και οι δύο νεφροί και το στέαρ το επ\' αυτών, το προς τα πλευρά, και ο επάνω λοβός του ήπατος, όστις μετά των νεφρών θέλει αφαιρείσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Και θέλει καίει αυτά ο ιερεύς επί του θυσιαστηρίου, εις προσφοράν γινομένην διά πυρός προς τον Κύριον· είναι προσφορά περί ανομίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Παν αρσενικόν μεταξύ των ιερέων θέλει τρώγει αυτήν· εν τόπω αγίω θέλει τρώγεσθαι· είναι αγιώτατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Καθώς είναι η περί αμαρτίας προσφορά, ούτω και η περί ανομίας προσφορά· εις νόμος είναι περί αυτών· ο ιερεύς, όστις κάμνει εξιλέωσιν δι\' αυτής, θέλει λαμβάνει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Ο δε ιερεύς όστις προσφέρει ολοκαύτωμα τινός, ο ιερεύς θέλει λαμβάνει δι\' εαυτόν το δέρμα του ολοκαυτώματος, το οποίον προσέφερε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Και πάσα προσφορά εξ αλφίτων, ήτις ήθελεν εψηθή εν κλιβάνω, και παν ό,τι ετοιμάζεται εν τηγανίω και επί κάψης, θέλει είσθαι του ιερέως του προσφέροντος αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Και πάσα προσφορά εξ αλφίτων, εζυμωμένη μετά ελαίου ή ξηρά, θέλει είσθαι πάντων των υιών του Ααρών, ίσον το μερίδιον εκάστου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Και ούτος είναι ο νόμος της θυσίας της ειρηνικής προσφοράς, την οποίαν θέλει προσφέρει τις εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Εάν προσφέρη αυτήν περί ευχαριστίας, τότε θέλει προσφέρει μετά της ευχαριστηρίου προσφοράς, πήττας αζύμους εζυμωμένας με έλαιον και λάγανα άζυμα κεχρισμένα μετά ελαίου και σεμίδαλιν κατεσκευασμένην, πήττας εζυμωμένας μετά ελαίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Με τας πήττας άρτον ένζυμον θέλει προσφέρει διά το δώρον αυτού μετά της προς ευχαριστίαν αυτού ειρηνικής προσφοράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Και εκ τούτων θέλει προσφέρει εν από πάντων των δώρων αυτού προσφοράν υψουμένην προς τον Κύριον· τούτο θέλει είσθαι του ιερέως του ραντίζοντος το αίμα της ειρηνικής προσφοράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Και το κρέας της θυσίας της προς ευχαριστίαν ειρηνικής αυτού προσφοράς θέλει τρώγεσθαι την αυτήν ημέραν καθ\' ην προσφέρεται δεν θέλουσιν αφήσει απ\' αυτού έως το πρωΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Και εάν η θυσία της προσφοράς αυτού ήναι ευχή, ή προσφορά προαιρετική, θέλει τρώγεσθαι την αυτήν ημέραν καθ\' ην προσφέρει τις την θυσίαν αυτού· και εάν μείνη τι, τούτο θέλει τρώγεσθαι την επαύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Το εναπολειφθέν όμως του κρέατος της θυσίας έως της τρίτης ημέρας με πυρ θέλει καίεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Εάν δε φαγωθή τι από του κρέατος της θυσίας της ειρηνικής προσφοράς αυτού την τρίτην ημέραν, δεν θέλει είσθαι δεκτός ο προσφέρων αυτήν, ουδέ θέλει λογισθή εις αυτόν· βδέλυγμα θέλει είσθαι· η δε ψυχή, ήτις ήθελε φάγει απ\' αυτού, θέλει βαστάσει την ανομίαν αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Και το κρέας, το οποίον ήθελεν εγγίσει ακάθαρτόν τι, δεν θέλει τρώγεσθαι· εν πυρί θέλει καίεσθαι περί δε του κρέατος, όστις είναι καθαρός θέλει τρώγει κρέας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Η δε ψυχή ήτις έχουσα την ακαθαρσίαν αυτής εφ\' εαυτής ήθελε φάγει από του κρέατος της θυσίας της ειρηνικής προσφοράς, ήτις είναι του Κυρίου, η ψυχή αύτη θέλει απολεσθή εκ του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Και η ψυχή ήτις ήθελεν εγγίσει ακάθαρτόν τι, ακαθαρσίαν ανθρώπου ή ζώον ακάθαρτον ή βδελυρόν τι ακάθαρτον, και φάγει από του κρέατος της θυσίας της ειρηνικής προσφοράς, ήτις είναι του Κυρίου, και η ψυχή αύτη θέλει απολεσθή εκ του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Λάλησον προς τους υιούς Ισραήλ, λέγων, Δεν θέλετε τρώγει παντελώς στέαρ βοός ή προβάτου ή αιγός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Και το στέαρ του θνησιμαίου ζώου και το στέαρ του θηριαλώτου δύναται να χρησιμεύη εις πάσαν άλλην χρείαν· δεν θέλετε όμως τρώγει διόλου απ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Διότι όστις φάγη το στέαρ του ζώου, από του οποίου προσφέρεται θυσία γινομένη διά πυρός εις τον Κύριον, και εκείνη ψυχή, ήτις ήθελε φάγει θέλει απολεσθή εκ του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Παρομοίως δεν θέλετε τρώγει ουδέν αίμα, είτε πτηνού είτε ζώου εν ουδεμιά εκ των κατοικιών σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Πάσα ψυχή ήτις ήθελε φάγει οποιονδήποτε αίμα, και εκείνη η ψυχή θέλει απολεσθή εκ του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Λάλησον προς τους υιούς Ισραήλ, λέγων, Ο προσφέρων την θυσίαν της ειρηνικής προσφοράς αυτού προς τον Κύριον, θέλει φέρει το δώρον αυτού προς τον Κύριον, από της θυσίας της ειρηνικής προσφοράς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Αι χείρες αυτού θέλουσι φέρει τας διά πυρός γινομένας προσφοράς του Κυρίου· θέλει φέρει το στέαρ μετά του στήθους, διά να κινήται το στήθος ως προσφορά κινητή έμπροσθεν του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Και ο ιερεύς θέλει καίει το στέαρ επί του θυσιαστηρίου· το στήθος όμως θέλει είσθαι του Ααρών και των υιών αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Και θέλετε δίδει προς τον ιερέα προσφοράν υψουμένην, τον δεξιόν ώμον εκ των θυσιών της ειρηνικής προσφοράς σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Όστις εκ των υιών του Ααρών προσφέρει το αίμα της ειρηνικής προσφοράς και το στέαρ, θέλει λαμβάνει τον δεξιόν ώμον εις μερίδιον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Διότι το κινητόν στήθος και τον υψούμενον ώμον έλαβον παρά των υιών Ισραήλ εκ των θυσιών της ειρηνικής προσφοράς αυτών, και έδωκα αυτά προς τον Ααρών τον ιερέα και προς τους υιούς αυτού εις νόμιμον αιώνιον μεταξύ των υιών Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Τούτο είναι το χρίσμα του Ααρών, και το χρίσμα των υιών αυτού, από των διά πυρός γινομένων προσφορών του Κυρίου, την ημέραν καθ\' ην παρέστησεν αυτούς διά να ιερατεύωσιν εις τον Κύριον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'το οποίον προσέταξεν ο Κύριος να δίδωται εις αυτούς παρά των υιών Ισραήλ, καθ\' ην ημέραν έχρισεν αυτούς, εις νόμιμον αιώνιον εις τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Ούτος είναι ο νόμος του ολοκαυτώματος, της εξ αλφίτων προσφοράς και της περί αμαρτίας προσφοράς και της περί ανομίας προσφοράς και των καθιερώσεων και της θυσίας της ειρηνικής προσφοράς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'τον οποίον προσέταξεν ο Κύριος εις τον Μωϋσήν εν τω όρει Σινά, καθ\' ην ημέραν προσέταξε τους υιούς Ισραήλ να προσφέρωσι προς τον Κύριον τα δώρα αυτών εν τη ερήμω Σινά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Λάβε τον Ααρών και τους υιούς αυτού μετ\' αυτού, και τας στολάς και το έλαιον του χρίσματος και τον μόσχον της περί αμαρτίας προσφοράς και τους δύο κριούς και το κάνιστρον των αζύμων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Και σύναξον πάσαν την συναγωγήν εις την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Και έκαμεν ο Μωϋσής καθώς προσέταξεν εις αυτόν ο Κύριος· και συνήχθη η συναγωγή εις την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Και είπεν ο Μωϋσής προς την συναγωγήν, Ούτος είναι ο λόγος τον οποίον προσέταξεν ο Κύριος να γείνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Και έφερεν ο Μωϋσής τον Ααρών και τους υιούς αυτού και έλουσεν αυτούς με ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Και έβαλε τον χιτώνα επ\' αυτόν, και έζωσεν αυτόν την ζώνην, και ενέδυσεν αυτόν τον ποδήρη, και έβαλεν επ\' αυτού το εφόδ, και έζωσεν αυτόν την κεντητήν ζώνην του εφόδ, και περιέζωσεν αυτόν με αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Και έβαλεν επ\' αυτού το περιστήθιον· εις δε το περιστήθιον έβαλε το Ουρίμ και το Θουμμίμ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Και έβαλε την μίτραν επί της κεφαλής αυτού· επί δε της μίτρας, κατά το έμπροσθεν αυτής, έβαλε το πέταλον το χρυσούν, το διάδημα το άγιον, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Και έλαβεν ο Μωϋσής το έλαιον του χρίσματος και έχρισε την σκηνήν και πάντα τα εν αυτή και ηγίασεν αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Και ερράντισεν απ\' αυτού επί το θυσιαστήριον επτάκις και έχρισε το θυσιαστήριον· και πάντα τα σκεύη αυτού και τον νιπτήρα και την βάσιν αυτού, διά να αγιάση αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Και έχυσεν από του ελαίου του χρίσματος επί την κεφαλήν του Ααρών και έχρισεν αυτόν, διά να αγιάση αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Και έφερεν ο Μωϋσής τους υιούς του Ααρών και ενέδυσεν αυτούς χιτώνας και έζωσεν αυτούς ζώνας και έβαλε μιτρίδια επ\' αυτών, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Και έφερε τον μόσχον της περί αμαρτίας προσφοράς· ο δε Ααρών και οι υιοί αυτού επέθεσαν τας χείρας αυτών επί την κεφαλήν του μόσχου της περί αμαρτίας προσφοράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Και έσφαξεν αυτόν και έλαβεν ο Μωϋσής από του αίματος και έβαλεν επί τα κέρατα του θυσιαστηρίου κύκλω διά του δακτύλου αυτού, και εκαθάρισε το θυσιαστήριον· και το αίμα έχυσεν εις την βάσιν του θυσιαστηρίου και ηγίασεν αυτό, διά να κάμη εξιλέωσιν επ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Και έλαβε παν το στέαρ το επί των εντοσθίων και τον λοβόν του ήπατος και τους δύο νεφρούς και το στέαρ αυτών, και έκαυσεν αυτά ο Μωϋσής επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Τον μόσχον όμως και το δέρμα αυτού και το κρέας αυτού και την κόπρον αυτού, έκαυσεν εν πυρί έξω του στρατοπέδου, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Και έφερε τον κριόν του ολοκαυτώματος· και ο Ααρών και οι υιοί αυτού επέθεσαν τας χείρας αυτών επί την κεφαλήν του κριού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Και έσφαξεν αυτόν και ερράντισεν ο Μωϋσής το αίμα επί το θυσιαστήριον κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Και διεμέλισε τον κριόν κατά τα μέλη αυτού· και έκαυσεν ο Μωϋσής την κεφαλήν και τα μέλη και το στέαρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Τα δε εντόσθια και τους πόδας έπλυνε με ύδωρ· και έκαυσεν ο Μωϋσής όλον τον κριόν επί του θυσιαστηρίου· ήτο ολοκαύτωμα εις οσμήν ευωδίας, προσφορά γινομένη διά πυρός εις τον Κύριον· καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Και έφερε τον κριόν τον δεύτερον, τον κριόν της καθιερώσεως· ο δε Ααρών και οι υιοί αυτού επέθεσαν τας χείρας αυτών επί την κεφαλήν του κριού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Και έσφαξεν αυτόν, και έλαβεν ο Μωϋσής από του αίματος αυτού και έβαλεν επί τον λοβόν του δεξιού ωτίου του Ααρών, και επί τον αντίχειρα της δεξιάς αυτού χειρός, και επί τον μεγάλον δάκτυλον του δεξιού αυτού ποδός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Και έφερε τους υιούς του Ααρών και έβαλεν ο Μωϋσής από του αίματος επί τον λοβόν του δεξιού ωτίου αυτών και επί τους αντίχειρας των δεξιών χειρών αυτών και επί τους μεγάλους δακτύλους των δεξιών ποδών αυτών· και ερράντισεν ο Μωϋσής το αίμα επί του θυσιαστηρίου κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Και έλαβε το στέαρ και την ουράν και παν το στέαρ το επί των εντοσθίων και τον λοβόν του ήπατος και τους δύο νεφρούς και το στέαρ αυτών και τον δεξιόν ώμον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'και από του κανίστρου των αζύμων του έμπροσθεν του Κυρίου έλαβε μίαν πήτταν άζυμον, και ένα άρτον ελαιωμένον και εν λάγανον και έβαλεν αυτά επί το στέαρ και επί τον δεξιόν ώμον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'και έβαλε τα πάντα εις τας χείρας του Ααρών και εις τας χείρας των υιών αυτού, και εκίνησεν αυτά εις προσφοράν κινητήν έμπροσθεν του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Και έλαβεν αυτά ο Μωϋσής εκ των χειρών αυτών και έκαυσεν επί του θυσιαστηρίου επί το ολοκαύτωμα· αύται ήσαν καθιερώσεις εις οσμήν ευωδίας· ήτο θυσία γινομένη διά πυρός εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Και λαβών ο Μωϋσής το στήθος, εκίνησεν αυτό εις προσφοράν κινητήν έμπροσθεν του Κυρίου· εκ του κριού της καθιερώσεως τούτο ήτο το μερίδιον του Μωϋσέως, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Και έλαβεν ο Μωϋσής από του ελαίου του χρίσματος και από του αίματος του επί του θυσιαστηρίου και ερράντισεν επί τον Ααρών, επί τας στολάς αυτού και επί τους υιούς αυτού και επί τας στολάς των υιών αυτού μετ\' αυτού· και ηγίασε τον Ααρών, τας στολάς αυτού και τους υιούς αυτού και τας στολάς των υιών αυτού μετ\' αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Και είπεν ο Μωϋσής προς τον Ααρών και προς τους υιούς αυτού, Βράσατε το κρέας εις την θύραν της σκηνής του μαρτυρίου· και εκεί φάγετε αυτό και τον άρτον τον εν τω κανίστρω των καθιερώσεων, καθώς με προσέταξεν ο Κύριος, λέγων, Ο Ααρών και οι υιοί αυτού θέλουσι τρώγει αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Το δε υπόλοιπον του κρέατος και του άρτου εν πυρί θέλετε κατακαύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Και από της θύρας της σκηνής του μαρτυρίου δεν θέλετε εξέλθει επτά ημέρας, εωσού πληρωθώσιν αι ημέραι της καθιερώσεώς σας· διότι εν επτά ημέραις θέλει τελειωθή η καθιέρωσίς σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Καθώς έκαμεν εις την ημέραν ταύτην, ούτω προσέταξε Κύριος να εκτελήται, διά να γίνηται εξιλέωσις διά σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Θέλετε λοιπόν καθίσει επτά ημέρας εις την θύραν της σκηνής του μαρτυρίου ημέραν και νύκτα· και θέλετε φυλάττει τας παραγγελίας του Κυρίου, διά να μη αποθάνητε· διότι ούτω προσετάχθην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Και έκαμεν ο Ααρών και οι υιοί αυτού πάντας τους λόγους, τους οποίους προσέταξεν ο Κύριος διά χειρός του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Και την ογδόην ημέραν ο Μωϋσής εκάλεσε τον Ααρών και τους υιούς αυτού και τους πρεσβυτέρους του Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'και είπε προς τον Ααρών, Λάβε εις σεαυτόν μόσχον εκ βοών διά προσφοράν περί αμαρτίας και κριόν διά ολοκαύτωμα άμωμα και πρόσφερε αυτά έμπροσθεν του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Και εις τους υιούς του Ισραήλ θέλεις λαλήσει, λέγων, Λάβετε τράγον εξ αιγών διά προσφοράν περί αμαρτίας και μόσχον και αρνίον ενιαύσια, άμωμα, διά ολοκαύτωμα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'και βουν και κριόν διά ειρηνικήν προσφοράν, εις θυσίαν έμπροσθεν του Κυρίου, και προσφοράν εξ αλφίτων εζυμωμένην μετά ελαίου· διότι σήμερον θέλει εμφανισθή ο Κύριος εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Και έφεραν ό,τι προσέταξεν ο Μωϋσής έμπροσθεν της σκηνής του μαρτυρίου· και επλησίασε πάσα η συναγωγή και εστάθη έμπροσθεν του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Και είπεν ο Μωϋσής, Ούτος είναι ο λόγος τον οποίον προσέταξε Κύριος να κάμνητε· και θέλει εμφανισθή εις εσάς η δόξα του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Και είπεν ο Μωϋσής προς τον Ααρών, Πρόσελθε εις το θυσιαστήριον και κάμε την περί αμαρτίας προσφοράν σου, και το ολοκαύτωμά σου και κάμε εξιλέωσιν υπέρ σεαυτού και υπέρ του λαού· και πρόσφερε το δώρον του λαού και κάμε εξιλέωσιν υπέρ αυτών, καθώς προσέταξεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Και προσήλθεν ο Ααρών εις το θυσιαστήριον και έσφαξε τον μόσχον της περί αμαρτίας προσφοράς, όστις ήτο δι\' αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Και οι υιοί του Ααρών έφεραν το αίμα προς αυτόν· και ενέβαψε τον δάκτυλον αυτού εις το αίμα και έβαλεν επί τα κέρατα του θυσιαστηρίου και έχυσε το αίμα εις την βάσιν του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Το στέαρ όμως και τους νεφρούς και τον επάνω λοβόν του ήπατος της περί αμαρτίας προσφοράς έκαυσεν επί του θυσιαστηρίου, καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Το δε κρέας και το δέρμα έκαυσεν εν πυρί έξω του στρατοπέδου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Και έσφαξε το ολοκαύτωμα· και οι υιοί του Ααρών παρέστησαν εις αυτόν το αίμα, και ερράντισεν αυτό επί του θυσιαστηρίου κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Και έφεραν προς αυτόν το ολοκαύτωμα διαμεμελισμένον και την κεφαλήν· και έκαυσεν αυτά επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Και έπλυνε τα εντόσθια και τους πόδας· και έκαυσεν αυτά επί το ολοκαύτωμα επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Και προσέφερε το δώρον του λαού· και έλαβε τον τράγον της περί αμαρτίας προσφοράς του λαού και έσφαξεν αυτόν, και προσέφερεν αυτόν περί αμαρτίας, καθώς και το πρώτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Και προσέφερε το ολοκαύτωμα και έκαμεν αυτό κατά το διατεταγμένον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Και προσέφερε την εξ αλφίτων προσφοράν· και ενέπλησε την χείρα αυτού απ\' αυτής και έκαυσεν αυτήν επί του θυσιαστηρίου, εκτός του πρωϊνού ολοκαυτώματος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Έσφαξεν έτι τον βουν και τον κριόν της ειρηνικής θυσίας της υπέρ του λαού· και οι υιοί του Ααρών παρέστησαν το αίμα προς αυτόν, και ερράντισεν αυτό επί του θυσιαστηρίου κύκλω,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'και το στέαρ του βοός και του κριού, την ουράν και το στέαρ το καλύπτον τα εντόσθια και τους νεφρούς και τον λοβόν του ήπατος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'και έθεσαν τα στέατα επί τα στήθη, και έκαυσε τα στέατα επί του θυσιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'τα δε στήθη και τον ώμον τον δεξιόν εκίνησεν ο Ααρών εις προσφοράν κινητήν ενώπιον του Κυρίου, καθώς προσέταξεν ο Μωϋσής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Και υψώσας ο Ααρών τας χείρας αυτού προς τον λαόν, ευλόγησεν αυτούς· και κατέβη, αφού προσέφερε την περί αμαρτίας προσφοράν και το ολοκαύτωμα και τας ειρηνικάς προσφοράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Και εισήλθεν ο Μωϋσής και ο Ααρών εις την σκηνήν του μαρτυρίου· και εξελθόντες ευλόγησαν τον λαόν· και εφάνη η δόξα του Κυρίου εις πάντα τον λαόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Και εξήλθε πυρ απ\' έμπροσθεν του Κυρίου και κατέφαγεν επί του θυσιαστηρίου το ολοκαύτωμα, και τα στέατα· ιδών δε πας ο λαός ηλάλαξαν και έπεσον κατά πρόσωπον αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Και λαβόντες οι υιοί του Ααρών, Ναδάβ και Αβιούδ, έκαστος το θυμιατήριον αυτού, έβαλον πυρ εις αυτό, και επ\' αυτό έβαλον θυμίαμα και προσέφεραν ενώπιον του Κυρίου πυρ ξένον, το οποίον δεν προσέταξεν εις αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Και εξήλθε πυρ παρά του Κυρίου και κατέφαγεν αυτούς· και απέθανον έμπροσθεν του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Τότε είπεν ο Μωϋσής προς τον Ααρών, Τούτο είναι το οποίον είπεν ο Κύριος, λέγων, Εγώ θέλω αγιασθή εις τους πλησιάζοντας εις εμέ, και έμπροσθεν παντός του λαού θέλω δοξασθή. Και ο Ααρών εσιώπησε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Και εκάλεσεν ο Μωϋσής τον Μισαήλ και τον Ελισαφάν, υιούς του Οζιήλ, θείου του Ααρών, και είπε προς αυτούς, Πλησιάσατε, σηκώσατε τους αδελφούς σας απ\' έμπροσθεν του αγιαστηρίου έξω του στρατοπέδου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Και επλησίασαν και εσήκωσαν αυτούς με τους χιτώνας αυτών έξω του στρατοπέδου, καθώς είπεν ο Μωϋσής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Και είπεν ο Μωϋσής προς τον Ααρών και προς τον Ελεάζαρ και προς τον Ιθάμαρ, τους υιούς αυτού, Τας κεφαλάς σας μη αποκαλύψητε, και τα ιμάτιά σας μη διασχίσητε, διά να μη αποθάνητε και έλθη οργή εφ\' όλην την συναγωγήν· αλλ\' οι αδελφοί σας, πας ο οίκος του Ισραήλ, ας κλαύσωσι το καύσιμον το οποίον έκαμεν ο Κύριος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'και δεν θέλετε εξέλθει εκ της θύρας της σκηνής του μαρτυρίου, διά να μη αποθάνητε· διότι το έλαιον του χρίσματος του Κυρίου είναι εφ\' υμάς. Και έκαμον κατά τον λόγον του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Και ελάλησε Κύριος προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Οίνον και σίκερα δεν θέλετε πίει, συ, και οι υιοί σου μετά σου, όταν εισέρχησθε εις την σκηνήν του μαρτυρίου, διά να μη αποθάνητε· τούτο θέλει είσθαι νόμιμον αιώνιον εις τας γενεάς σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'και διά να διακρίνητε μεταξύ αγίου και βεβήλου και μεταξύ ακαθάρτου και καθαρού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'και διά να διδάσκητε τους υιούς Ισραήλ πάντα τα διατάγματα, όσα ελάλησε Κύριος προς αυτούς διά χειρός του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Και είπεν ο Μωϋσής προς τον Ααρών και προς τον Ελεάζαρ και προς τον Ιθάμαρ, τους υιούς αυτού τους εναπολειφθέντας, Λάβετε την εξ αλφίτων προσφοράν την εναπολειφθείσαν από των διά πυρός γινομένων θυσιών του Κυρίου και φάγετε αυτήν άζυμον πλησίον του θυσιαστηρίου· διότι είναι αγιώτατον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'και θέλετε φάγει αυτήν εν τόπω αγίω· επειδή είναι το δίκαιόν σου και το δίκαιον των υιών σου εκ των διά πυρός γινομένων θυσιών του Κυρίου· διότι ούτω προσετάχθην·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'και το κινητόν στήθος και τον υψούμενον ώμον θέλετε φάγει εν καθαρώ τόπω, συ και οι υιοί σου και αι θυγατέρες σου μετά σού· διότι είναι το δίκαιόν σου και το δίκαιον των υιών σου, δοθέντα εκ των θυσιών της ειρηνικής προσφοράς των υιών του Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'τον υψούμενον ώμον και το κινητόν στήθος θέλουσι φέρει μετά των διά πυρός γινομένων προσφορών του στέατος, διά να κινήσωσιν αυτά εις κινητήν προσφοράν ενώπιον του Κυρίου· και θέλει είσθαι εις σε και εις τους υιούς σου μετά σου εις νόμιμον αιώνιον, καθώς προσέταξεν ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Και εζήτησεν επιμελώς ο Μωϋσής τον τράγον της περί αμαρτίας προσφοράς· και ιδού, ήτο κατακεκαυμένος· και εθυμώθη κατά του Ελεάζαρ και κατά του Ιθάμαρ, των υιών του Ααρών των εναπολειφθέντων, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Διά τι δεν εφάγετε την περί αμαρτίας προσφοράν εν τόπω αγίω; διότι είναι αγιώτατον· και έδωκεν αυτό εις εσάς Κύριος διά να σηκόνητε την ανομίαν της συναγωγής, ώστε να κάμνητε εξιλέωσιν υπέρ αυτών ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'ιδού, το αίμα αυτού δεν εφέρθη εις το αγιαστήριον· πρέπει εξάπαντος να φάγητε αυτό εν τω αγιαστηρίω, καθώς προσέταξα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Και είπεν ο Ααρών προς τον Μωϋσήν, Ιδού, αυτοί προσέφεραν σήμερον την περί αμαρτίας προσφοράν αυτών και το ολοκαύτωμα αυτών ενώπιον του Κυρίου και συνέβησαν εις εμέ τοιαύτα· εάν λοιπόν ήθελον φάγει την περί αμαρτίας προσφοράν σήμερον, τούτο ήθελεν είσθαι αρεστόν εις τους οφθαλμούς του Κυρίου;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Και ήκουσεν ο Μωϋσής και ήρεσεν εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών λέγων προς αυτούς,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Λαλήσατε προς τους υιούς Ισραήλ, λέγοντες, ταύτα είναι τα ζώα τα οποία θέλετε τρώγει εκ πάντων των κτηνών των επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Παν δίχηλον μεταξύ των κτηνών έχον τον πόδα εσχισμένον και αναμασσών, τούτο θέλετε τρώγει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Ταύτα όμως δεν θέλετε τρώγει εκ των όσα αναμασσώσιν ή εκ των όσα είναι δίχηλα· την κάμηλον, διότι αναμασσά μεν, πλην δεν είναι δίχηλος· είναι ακάθαρτος εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'και τον δασύποδα, διότι αναμασσά μεν, πλην δεν είναι δίχηλος· είναι ακάθαρτος εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'και τον λαγωόν, διότι αναμασσά μεν, πλην δεν είναι δίχηλος· είναι ακάθαρτος εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'και τον χοίρον, διότι είναι μεν δίχηλος και έχει τον πόδα εσχισμένον, πλην δεν αναμασσά· είναι ακάθαρτος εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'από του κρέατος αυτών δεν θέλετε τρώγει και το θνησιμαίον αυτών δεν θέλετε εγγίζει είναι ακάθαρτα εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Ταύτα θέλετε τρώγει εκ πάντων των εν τοις ύδασι πάντα όσα έχουσι πτερά και λέπη, εν τοις ύδασι, εν ταις θαλάσσαις και εν τοις ποταμοίς, ταύτα θέλετε τρώγει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Και πάντα όσα δεν έχουσι πτερά και λέπη, εν ταις θαλάσσαις και εν τοις ποταμοίς, από πάντων όσα κινούνται εν τοις ύδασι και από παντός εμψύχου ζώου το οποίον είναι εν τοις ύδασι, θέλουσιν είσθαι βδελυκτά εις εσάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'ταύτα εξάπαντος θέλουσιν είσθαι βδελυκτά εις εσάς· από του κρέατος αυτών δεν θέλετε τρώγει και το θνησιμαίον αυτών θέλετε βδελύττεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Πάντα όσα εν τοις ύδασι δεν έχουσι πτερά ούτε λέπη, θέλουσιν είσθαι βδελυκτά εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Ταύτα δε θέλετε βδελύττεσθαι μεταξύ των πτηνών· δεν θέλουσι τρώγεσθαι είναι βδελυκτά· ο αετός, και ο γρυπαετός, και ο μελαναετός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'και ο γυψ, και ο ίκτινος κατά το είδος αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'πας κόραξ κατά το είδος αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'και η στρουθοκάμηλος, και η γλαύξ, και ο ίβις, και ο ιέραξ κατά το είδος αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'και ο νυκτικόραξ, και η αίθυια, και η μεγάλη γλαύξ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'και ο κύκνος, και ο πελεκάν, και η κίσσα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'και ο πελαργός, και ο ερωδιός κατά το είδος αυτού, και ο έποψ, και η νυκτερίς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Πάντα τα πετώμενα ερπετά, τα οποία περιπατούσιν επί τέσσαρας πόδας, θέλουσιν είσθαι βδελυκτά εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Ταύτα όμως δύνασθε να τρώγητε από παντός πετωμένου ερπετού, περιπατούντος επί τέσσαρας πόδας, τα οποία έχουσι σκέλη όπισθεν των ποδών αυτών, διά να πηδώσι δι\' αυτών επί της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'ταύτα θέλετε τρώγει εξ αυτών· τον βρούχον κατά το είδος αυτού και τον αττάκην κατά το είδος αυτού και τον οφιομάχον κατά το είδος αυτού και την ακρίδα κατά το είδος αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Πάντα δε τα πετώμενα ερπετά, έχοντα τέσσαρας πόδας, θέλουσιν είσθαι βδελυκτά εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Και εις ταύτα θέλετε είσθαι ακάθαρτοι· πας ο εγγίζων το θνησιμαίον αυτών θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Και πας όστις βαστάση από του θνησιμαίον αυτών, θέλει πλύνει τα ιμάτια αυτού και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Εκ πάντων των κτηνών, όσα είναι δίχηλα, πλην δεν είναι ο πους αυτών εσχισμένος ουδέ αναμασσώσι, θέλουσιν είσθαι ακάθαρτα εις εσάς· πας ο εγγίζων αυτά θέλει είσθαι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Και όσα περιπατούσιν επί τας παλάμας αυτών, μεταξύ πάντων των ζώων των περιπατούντων επί τέσσαρας πόδας, θέλουσιν είσθαι ακάθαρτα εις εσάς· πας ο εγγίζων το θνησιμαίον αυτών θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Και όστις βαστάση το θνησιμαίον αυτών, θέλει πλύνει τα ιμάτια αυτού και θέλει είσθαι ακάθαρτος έως εσπέρας· ταύτα θέλουσιν είσθαι ακάθαρτα εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Και ταύτα θέλουσιν είσθαι ακάθαρτα εις εσάς μεταξύ των ερπετών των ερπόντων επί της γής· η γαλή και ο ποντικός, και η χελώνη κατά το είδος αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'και ο ακανθόχοιρος, και ο χαμαιλέων, και η σαύρα, και ο σαμιάμιθος, και ο ασπάλαξ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ταύτα είναι ακάθαρτα εις εσάς μεταξύ πάντων των ερπετών· πας ο εγγίζων αυτά τεθνεώτα, θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Και παν πράγμα επί του οποίου ήθελε πέσει τι εκ τούτων τεθνεώτων θέλει είσθαι ακάθαρτον· παν αγγείον ξύλινον ή ιμάτιον ή δέρμα ή σάκκος ή οποιονδήποτε αγγείον, εις το οποίον γίνεται εργασία, θέλει εμβληθή εις ύδωρ και θέλει είσθαι ακάθαρτον έως εσπέρας· τότε θέλει είσθαι καθαρόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'και παν αγγείον πήλινον, εις το οποίον εμπέση τι εκ τούτων, παν ό,τι είναι εντός αυτού θέλει είσθαι ακάθαρτον· αυτό δε θέλετε συντρίψει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'από παντός φαγητού εσθιωμένου, εις το οποίον εμβαίνει ύδωρ, θέλει είσθαι ακάθαρτον· και παν ποτόν πινόμενον εν οποιωδήποτε αγγείω, θέλει είσθαι ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Και παν πράγμα επί το οποίον πέση από του θνησιμαίου αυτών, θέλει είσθαι ακάθαρτον· κλίβανος είτε εστία θέλουσι κρημνισθή· είναι ακάθαρτα και ακάθαρτα θέλουσιν είσθαι εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Πηγή όμως ή λάκκος, σύναξις υδάτων, θέλει είσθαι καθαρόν· πλην ό,τι εγγίση το θνησιμαίον αυτών, θέλει είσθαι ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Και εάν πέση από του θνησιμαίου αυτών επί τι σπέρμα σπόριμον, το οποίον μέλλει να σπαρθή, καθαρόν θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Εάν δε επιχυθή ύδωρ επί του σπέρματος και πέση από του θνησιμαίου αυτών επ\' αυτό, ακάθαρτον θέλει είσθαι εις εσάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Και εάν αποθάνη τι εκ των κτηνών τα οποία δύνασθε να τρώγητε, όστις εγγίση το θνησιμαίον αυτού, θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Και όστις φάγη από του θνησιμαίου αυτού, θέλει πλύνει τα ιμάτια αυτού και θέλει είσθαι ακάθαρτος έως εσπέρας· και όστις βαστάση το θνησιμαίον αυτού, θέλει πλύνει τα ιμάτια αυτού και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Και παν ερπετόν, έρπον επί της γης, θέλει είσθαι βδέλυγμα· δεν θέλει τρώγεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Παν ό,τι περιπατεί επί της κοιλίας και παν ό,τι περιπατεί επί τέσσαρας πόδας ή παν το έχον πολλούς πόδας, μεταξύ πάντων των ερπετών των ερπόντων επί της γης, ταύτα δεν θέλετε τρώγει, διότι είναι βδέλυγμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Δεν θέλετε κάμει βδελυκτάς τας ψυχάς σας δι\' ουδενός ερπετού έρποντος ουδέ θέλετε μιανθή δι\' αυτών, ώστε να γείνητε ακάθαρτοι δι\' αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Διότι εγώ είμαι Κύριος ο Θεός σας· θέλετε λοιπόν αγιασθή και θέλετε είσθαι άγιοι, διότι άγιος είμαι εγώ· και δεν θέλετε μιάνει τας ψυχάς σας δι\' ουδενός ερπετού έρποντος επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Διότι εγώ είμαι ο Κύριος, όστις σας ανεβίβασα εκ γης Αιγύπτου, διά να ήμαι Θεός σας· θέλετε λοιπόν είσθαι άγιοι, διότι άγιος είμαι εγώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Ούτος είναι ο νόμος περί των κτηνών και περί των πτηνών και περί παντός εμψύχου όντος κινουμένου εν τοις ύδασι και περί παντός όντος έρποντος επί της γής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'διά να διακρίνητε μεταξύ του ακαθάρτου και του καθαρού και μεταξύ των ζώων τα οποία τρώγονται των ζώων και οποία δεν τρώγονται.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Λάλησον προς τους υιούς Ισραήλ, λέγων, Εάν γυνή τις συλλάβη και γεννήση αρσενικόν, τότε θέλει είσθαι ακάθαρτος επτά ημέρας· κατά τας ημέρας του χωρισμού διά τα γυναικεία αυτής θέλει είσθαι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Και την ογδόην ημέραν θέλει περιτέμνεσθαι η σαρξ της ακροβυστίας αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Και έτι τριάκοντα τρεις ημέρας θέλει μείνει εις το αίμα του καθαρισμού αυτής· ουδέν πράγμα άγιον θέλει εγγίσει και εις το αγιαστήριον δεν θέλει εισέλθει, εωσού πληρωθώσιν αι ημέραι του καθαρισμού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Αλλ\' εάν γεννήση θηλυκόν, τότε θέλει είσθαι ακάθαρτος δύο εβδομάδας, καθώς εν τω χωρισμώ αυτής· και θέλει μείνει έτι εις το αίμα του καθαρισμού αυτής εξήκοντα εξ ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Και αφού πληρωθώσιν αι ημέραι του καθαρισμού αυτής, διά υιόν, ή διά θυγατέρα, θέλει φέρει αρνίον ενιαύσιον εις ολοκαύτωμα, και νεοσσόν περιστεράς, ή τρυγόνα, διά προσφοράν περί αμαρτίας, εις την θύραν της σκηνής του μαρτυρίου προς τον ιερέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'ούτος δε θέλει προσφέρει αυτό ενώπιον του Κυρίου και θέλει κάμει εξιλέωσιν υπέρ αυτής και θέλει καθαρισθή από της ροής του αίματος αυτής. Ούτος είναι ο νόμος της γεννώσης αρσενικόν ή θηλυκόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Εάν όμως δεν ευπορή να φέρη αρνίον, τότε θέλει φέρει δύο τρυγόνας ή δύο νεοσσούς περιστερών, μίαν διά ολοκαύτωμα και μίαν διά προσφοράν περί αμαρτίας· και θέλει κάμει εξιλέωσιν υπέρ αυτής ο ιερεύς, και θέλει καθαρισθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Όταν άνθρωπός τις έχη επί του δέρματος της σαρκός αυτού πρήσμα ή ψώραν, ή εξάνθημα, και γείνη εις το δέρμα της σαρκός αυτού πληγή λέπρας, τότε θέλει φερθή προς τον Ααρών τον ιερέα ή προς ένα των υιών αυτού των ιερέων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'και ο ιερεύς θέλει θεωρήσει την πληγήν εις το δέρμα της σαρκός. Και εάν η θριξ εις την πληγήν μετεβλήθη εις λευκήν, και η πληγή εις την όψιν ήναι βαθυτέρα του δέρματος της σαρκός αυτού, είναι πληγή λέπρας· ο δε ιερεύς θέλει θεωρήσει αυτόν και θέλει κρίνει αυτόν ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Αλλ\' εάν το εξάνθημα ήναι λευκόν εις το δέρμα της σαρκός αυτού και εις την όψιν δεν είναι βαθύτερον του δέρματος και η θριξ αυτού δεν μετεβλήθη εις λευκήν, τότε θέλει κλείσει ο ιερεύς τον έχοντα την πληγήν επτά ημέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'και θέλει θεωρήσει αυτόν ο ιερεύς την εβδόμην ημέραν· και ιδού, εάν ίδη ότι η πληγή είναι εις στάσιν και η πληγή δεν εξηπλώθη εις το δέρμα, τότε θέλει κλείσει αυτόν ο ιερεύς άλλας επτά ημέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'και θέλει θεωρήσει αυτόν ο ιερεύς εκ δευτέρου την εβδόμην ημέραν· και ιδού, εάν η πληγή ημαυρώθη και δεν εξηπλώθη η πληγή εις το δέρμα, θέλει κρίνει αυτόν ο ιερεύς καθαρόν· αύτη είναι ψώρα· και θέλει πλύνει τα ιμάτια αυτού και θέλει είσθαι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Εάν όμως εξηπλώθη περισσότερον η ψώρα επί του δέρματος, αφού εθεωρήθη υπό του ιερέως διά τον καθαρισμόν αυτού, θέλει δειχθή πάλιν εις τον ιερέα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Και εάν ίδη ο ιερεύς, ότι εξηπλώθη η ψώρα επί του δέρματος, τότε θέλει κρίνει αυτόν ο ιερεύς ακάθαρτον· είναι λέπρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Όταν η πληγή της λέπρας ήναι εις άνθρωπον, τότε θέλει φερθή προς τον ιερέα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'και θέλει θεωρήσει ο ιερεύς· και ιδού, εάν το πρήσμα ήναι λευκόν εις το δέρμα και μετέβαλε την τρίχα εις λευκήν, και ευρίσκεται κρέας ζων εις το πρήσμα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'είναι λέπρα παλαιά εις το δέρμα της σαρκός αυτού και θέλει κρίνει αυτόν ο ιερεύς ακάθαρτον· δεν θέλει κλείσει αυτόν, διότι είναι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Αλλ\' εάν εξηπλώθη πολύ η λέπρα επί του δέρματος και η λέπρα εσκέπασεν όλον το δέρμα του έχοντος την πληγήν από κεφαλής αυτού και έως ποδών αυτού, όπου και αν θεωρήση ο ιερεύς,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'τότε θέλει θεωρήσει ο ιερεύς, και ιδού, εάν η λέπρα εσκέπασεν όλην την σάρκαν αυτού, θέλει κρίνει καθαρόν τον έχοντα την πληγήν· είναι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Αλλ\' εν οποία ημέρα φανή εις αυτόν κρέας ζων, θέλει είσθαι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Και θέλει θεωρήσει ο ιερεύς το κρέας το ζων και θέλει κρίνει αυτόν ακάθαρτον· το ζων κρέας είναι ακάθαρτον· είναι λέπρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Η εάν το κρέας το ζων αλλάξη πάλιν και μεταβληθή εις λευκόν, θέλει ελθεί προς τον ιερέα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Και θέλει θεωρήσει αυτόν ο ιερεύς· και ιδού, εάν η πληγή μετεβλήθη εις λευκήν, τότε θέλει κρίνει ο ιερεύς καθαρόν τον έχοντα την πληγήν· είναι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Η δε σαρξ επί του δέρματος της οποίας ήτο έλκος, και ιατρεύθη,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'και εν τω τόπω του έλκους έγεινε πρήσμα λευκόν, ή εξάνθημα λευκόν κοκκινωπόν, θέλει δειχθή εις τον ιερέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'και θέλει θεωρήσει ο ιερεύς, και ιδού, εάν φαίνηται βαθύτερον του δέρματος και η θριξ αυτού μετεβλήθη εις λευκήν, θέλει κρίνει αυτόν ο ιερεύς ακάθαρτον· είναι πληγή λέπρας, ήτις εξήνθησεν εις το έλκος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Εάν δε θεωρήση αυτό ο ιερεύς, και ιδού, δεν ήναι λευκαί τρίχες εις αυτό και δεν ήναι βαθύτερον του δέρματος και ήναι ημαυρωμένον, τότε ο ιερεύς θέλει κλείσει αυτόν επτά ημέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'και εάν εξηπλώθη πολύ επί του δέρματος, τότε θέλει κρίνει αυτόν ο ιερεύς ακάθαρτον· είναι πληγή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Αλλ\' εάν το εξάνθημα μένη εν τω τόπω αυτού και δεν εξηπλώθη, τούτο είναι ουλή του έλκους· και θέλει κρίνει αυτόν ο ιερεύς καθαρόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Εάν δε ήναι κρέας, έχον επί του δέρματος αυτού καυστικήν φλόγωσιν, και το ζων κρέας του πεφλογισμένου μέρους έχη εξάνθημα λευκόν, κοκκινωπόν ή κατάλευκον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'τότε θέλει θεωρήσει αυτό ο ιερεύς· και ιδού, εάν η θριξ εις το εξάνθημα μετεβλήθη εις λευκήν και εις την όψιν ήναι βαθύτερον του δέρματος, είναι λέπρα εξανθήσασα εις την φλόγωσιν· και θέλει κρίνει αυτόν ο ιερεύς ακάθαρτον· είναι πληγή λέπρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Αλλ\' εάν ο ιερεύς θεωρήση αυτό, και ιδού, δεν ήναι θριξ λευκή εις το εξάνθημα και δεν ήναι βαθύτερον του δέρματος και ήναι ημαυρωμένον, τότε θέλει κλείσει αυτόν ο ιερεύς επτά ημέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'και θέλει θεωρήσει αυτόν ο ιερεύς την εβδόμην ημέραν· και εάν αυτό εξηπλώθη πολύ εις το δέρμα, τότε θέλει κρίνει αυτόν ο ιερεύς ακάθαρτον· είναι πληγή λέπρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Εάν δε το εξάνθημα μένη εν τω τόπω αυτού και δεν εξηπλώθη επί του δέρματος και ήναι ημαυρωμένον, είναι πρήσμα φλογώσεως, και θέλει κρίνει αυτόν ο ιερεύς καθαρόν· επειδή είναι ουλή της φλογώσεως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Και εάν ανήρ, ή γυνή, έχη πληγήν εις την κεφαλήν, ή εις το πωγώνιον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'τότε θέλει θεωρήσει ο ιερεύς την πληγήν· και ιδού, εάν εις την όψιν ήναι βαθυτέρα του δέρματος και εις αυτήν θριξ ξανθίζουσα, τότε θέλει κρίνει αυτόν ο ιερεύς ακάθαρτον· είναι κασίδα, λέπρα της κεφαλής ή του πωγωνίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Και εάν θεωρήση ο ιερεύς την πληγήν της κασίδας και ιδού, εις την όψιν δεν ήναι βαθυτέρα του δέρματος και δεν ήναι θριξ μελανή εν αυτή, τότε θέλει κλείσει ο ιερεύς επτά ημέρας τον έχοντα την πληγήν της κασίδας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'και θέλει θεωρήσει ο ιερεύς την πληγήν την εβδόμην ημέραν· και ιδού, εάν δεν εξηπλώθη η κασίδα και δεν ήναι εις αυτήν θριξ ξανθίζουσα και εις την όψιν η κασίδα δεν ήναι βαθυτέρα του δέρματος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'αυτός θέλει ξυρισθή, αλλ\' η κασίδα δεν θέλει ξυρισθή· ο δε ιερεύς θέλει κλείσει τον έχοντα την κασίδαν άλλας επτά ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Και την εβδόμην ημέραν θέλει θεωρήσει ο ιερεύς την κασίδαν· και ιδού, εάν η κασίδα δεν εξηπλώθη εις το δέρμα και εις την όψιν δεν ήναι βαθυτέρα του δέρματος, τότε θέλει κρίνει αυτόν ο ιερεύς καθαρόν· και αυτός θέλει πλύνει τα ιμάτια αυτού και θέλει είσθαι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Αλλ\' εάν η κασίδα εξηπλώθη πολύ επί του δέρματος μετά τον καθαρισμόν αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'τότε θέλει θεωρήσει αυτόν ο ιερεύς· και ιδού, εάν η κασίδα εξηπλώθη επί του δέρματος, δεν θέλει ερευνήσει ο ιερεύς περί της ξανθιζούσης τριχός· είναι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Αλλ\' εάν θεωρήση ότι η κασίδα είναι εις στάσιν και εκφύεται θριξ μελανή εν αυτή, η κασίδα είναι τεθεραπευμένη· είναι καθαρός· και θέλει κρίνει αυτόν ο ιερεύς καθαρόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Και εάν ανήρ, ή γυνή, έχωσιν επί του δέρματος της σαρκός αυτών εξανθήματα, εξανθήματα λευκωπά,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'τότε θέλει θεωρήσει ο ιερεύς· και ιδού, εάν τα εξανθήματα επί του δέρματος της σαρκός αυτών ήναι υπόλευκα, είναι αλφός εξανθών επί του δέρματος· είναι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Εάν δε η κεφαλή τινός μαδήση, αυτός είναι φαλακρός· είναι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Και εάν η κεφαλή αυτού μαδήση προς το πρόσωπον, είναι αναφάλαντος· είναι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Αλλ\' εάν ήναι εις το φαλάκρωμα, ή εις το αναφαλάντωμα, πληγή λευκή κοκκινωπή, είναι λέπρα εξανθήσασα εις το φαλάκρωμα αυτού ή εις το αναφαλάντωμα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Και θέλει θεωρήσει αυτόν ο ιερεύς· και ιδού, εάν το πρήσμα της πληγής ήναι λευκόν κοκκινωπόν εις το φαλάκρωμα αυτού ή εις το αναφαλάντωμα αυτού, ως το φαινόμενον της λέπρας επί του δέρματος της σαρκός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'είναι άνθρωπος λεπρός, είναι ακάθαρτος· θέλει κρίνει αυτόν ο ιερεύς όλως ακάθαρτον· εις την κεφαλήν αυτού είναι η πληγή αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Και του λεπρού, εις τον οποίον είναι η πληγή, τα ιμάτια αυτού θέλουσι σχισθή και η κεφαλή αυτού θέλει είσθαι ασκεπής, και το επάνω χείλος αυτού θέλει καλύψει και θέλει φωνάζει, Ακάθαρτος, ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Πάσας τας ημέρας καθ\' ας η πληγή θέλει είσθαι εν αυτώ, θέλει είσθαι ακάθαρτος· είναι ακάθαρτος· μόνος θέλει κατοικεί· έξω του στρατοπέδου θέλει είσθαι η κατοικία αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Και εάν υπάρχη εις ιμάτιον πληγή λέπρας, εις ιμάτιον μάλλινον ή εις ιμάτιον λινούν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'είτε εις στημόνιον, είτε εις υφάδιον, εκ λινού ή εκ μαλλίου, είτε εις δέρμα, είτε εις παν πράγμα κατεσκευασμένον εκ δέρματος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'και η πληγή ήναι πρασινωπή, ή κοκκινωπή, εις το ιμάτιον, ή εις το δέρμα, ή εις το στημόνιον, εις το υφάδιον, ή εις παν σκεύος δερμάτινον, είναι πληγή λέπρας και θέλει δειχθή εις τον ιερέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'ο δε ιερεύς θέλει θεωρήσει την πληγήν και θέλει κλείσει το έχον την πληγήν επτά ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Και θέλει θεωρήσει την πληγήν την εβδόμην ημέραν· εάν η πληγή εξηπλώθη επί του ιματίου, ή επί του στημονίου, ή επί του υφαδίου, ή επί του δέρματος, εκ παντός πράγματος το οποίον είναι κατεσκευασμένον εκ δέρματος, η πληγή είναι λέπρα διαβρωτική· τούτο είναι ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Και θέλει καύσει το ιμάτιον, ή το στημόνιον, ή το υφάδιον, μάλλινον, ή λινούν, ή παν σκεύος δερμάτινον επί του οποίου είναι η πληγή· διότι είναι λέπρα διαβρωτική· με πυρ θέλει καυθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Και εάν ίδη ο ιερεύς, και ιδού, η πληγή δεν εξηπλώθη επί του ιματίου, είτε επί του στημονίου, είτε επί του υφαδίου, ή επί παντός σκεύους δερματίνου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'τότε θέλει προστάξει ο ιερεύς να πλυθή το έχον την πληγήν και θέλει κλείσει αυτό άλλας επτά ημέρας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'και θέλει θεωρήσει ο ιερεύς την πληγήν, αφού επλύθη· και ιδού, εάν η πληγή δεν ήλλαξε το χρώμα αυτής και δεν εξηπλώθη η πληγή, είναι ακάθαρτον· με πυρ θέλεις καύσει αυτό· είναι διαβρωτικόν, το οποίον προχωρεί υποκάτωθεν ή επάνωθεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Και εάν ίδη ο ιερεύς, και ιδού, η πληγή, αφού επλύθη, είναι ημαυρωμένη, τότε θέλει εκκόψει αυτήν από του ιματίου, ή από του δέρματος, ή από του στημονίου, ή από του υφαδίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Αλλ\' εάν φανή έτι επί του ιματίου, επί του στημονίου, ή επί του υφαδίου, ή επί παντός σκεύους δερματίνου, είναι λέπρα εξανθίζουσα· με πυρ θέλεις καύσει το έχον την πληγήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Και το ιμάτιον, ή το στημόνιον, ή το υφάδιον, παν σκεύος δερμάτινον, το οποίον ήθελες πλύνει, εάν η πληγή εξηλείφθη απ\' αυτών, τότε θέλει πλυθή εκ δευτέρου και θέλει είσθαι καθαρόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Ούτος είναι ο νόμος της πληγής της λέπρας επί ιματίου μαλλίνου, ή λινού, είτε στημονίου, είτε υφαδίου, ή παντός σκεύους δερματίνου, διά να κρίνηται καθαρόν, ή να κρίνηται ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Ούτος είναι ο νόμος του λεπρού εν τη ημέρα του καθαρισμού αυτού· θέλει φερθή προς τον ιερέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'και θέλει εξέλθει ο ιερεύς έξω του στρατοπέδου και θέλει θεωρήσει ο ιερεύς, και ιδού, εάν ιατρεύθη η πληγή της λέπρας εις τον λεπρόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'τότε θέλει προστάξει ο ιερεύς να λάβωσι διά τον καθαριζόμενον δύο πτηνά ζώντα καθαρά και ξύλον κέδρινον και κόκκινον και ύσσωπον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Και θέλει προστάξει ο ιερεύς να σφάξωσι το εν πτηνόν εις αγγείον πήλινον επάνω ύδατος ζώντος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'το δε πτηνόν το ζων, θέλει λάβει αυτό και το ξύλον το κέδρινον και το κόκκινον και τον ύσσωπον και θέλει εμβάψει αυτά και το πτηνόν το ζων εις το αίμα του πτηνού του εσφαγμένου επάνω του ύδατος του ζώντος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'και θέλει ραντίσει επί τον καθαριζόμενον από της λέπρας επτάκις και θέλει κρίνει αυτόν καθαρόν· και θέλει απολύσει το πτηνόν το ζων επί πρόσωπον της πεδιάδος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Και θέλει πλύνει ο καθαριζόμενος τα ιμάτια αυτού και θέλει ξυρίσει πάσας τας τρίχας αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι καθαρός· και μετά ταύτα θέλει ελθεί εις το στρατόπεδον και θέλει διατρίψει έξω της σκηνής αυτού επτά ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Και την εβδόμην ημέραν θέλει ξυρίσει πάσας τας τρίχας αυτού, την κεφαλήν αυτού και τον πώγωνα αυτού και τα οφρύδια αυτού και πάσας τας τρίχας αυτού θέλει ξυρίσει και θέλει πλύνει τα ιμάτια αυτού και θέλει λούσει το σώμα αυτού εν ύδατι και θέλει είσθαι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Και την ογδόην ημέραν θέλει λάβει δύο αρνία αρσενικά άμωμα και εν αρνίον θηλυκόν ενιαύσιον άμωμον και τρία δέκατα σεμιδάλεως διά προσφοράν εξ αλφίτων, εζυμωμένης μετά ελαίου, και εν λογ ελαίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'και θέλει παραστήσει ο ιερεύς ο καθαρίζων τον άνθρωπον τον καθαριζόμενον και αυτά ενώπιον του Κυρίου, εις την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Και θέλει λάβει ο ιερεύς το εν αρσενικόν αρνίον και θέλει προσφέρει αυτό εις προσφοράν περί ανομίας και το λογ του ελαίου, και θέλει κινήσει αυτά εις κινητήν προσφοράν ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Και θέλει σφάξει το αρνίον εν τω τόπω όπου σφάζουσι την περί αμαρτίας προσφοράν και το ολοκαύτωμα, εν τω τόπω τω αγίω· διότι καθώς η περί αμαρτίας προσφορά, η περί ανομίας προσφορά είναι του ιερέως· είναι αγιώτατον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Και θέλει λάβει ο ιερεύς από του αίματος της περί ανομίας προσφοράς και θέλει βάλει αυτό ο ιερεύς επί τον λοβόν του δεξιού ωτίου του καθαριζομένου και επί τον αντίχειρα της δεξιάς αυτού χειρός και επί τον μεγάλον δάκτυλον του δεξιού αυτού ποδός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'και θέλει λάβει ο ιερεύς από του λογ του ελαίου και θέλει χύσει αυτό εις την παλάμην της αριστεράς αυτού χειρός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'και θέλει εμβάψει ο ιερεύς τον δάκτυλον αυτού τον δεξιόν εις το έλαιον το εν τη αριστερά αυτού παλάμη, και θέλει ραντίσει εκ του ελαίου διά του δακτύλου αυτού επτάκις ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'και εκ του υπολοίπου ελαίου του εν τη παλάμη αυτού θέλει βάλει ο ιερεύς επί τον λοβόν του δεξιού ωτίου του καθαριζομένου, και επί τον αντίχειρα της δεξιάς αυτού χειρός και επί τον μεγάλον δάκτυλον του δεξιού αυτού ποδός, επί το αίμα της περί ανομίας προσφοράς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'το δε εναπολειφθέν έλαιον το εν τη παλάμη του ιερέως θέλει χύσει επί την κεφαλήν του καθαριζομένου· και θέλει κάμει εξιλέωσιν ο ιερεύς υπέρ αυτού ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Και θέλει προσφέρει ο ιερεύς την περί αμαρτίας προσφοράν, και θέλει κάμει εξιλέωσιν υπέρ του καθαριζομένου από της ακαθαρσίας αυτού· και έπειτα θέλει σφάξει το ολοκαύτωμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Και θέλει προσφέρει ο ιερεύς το ολοκαύτωμα και την εξ αλφίτων προσφοράν επί του θυσιαστηρίου· και θέλει κάμει εξιλέωσιν υπέρ αυτού ο ιερεύς, και θέλει είσθαι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Εάν δε ήναι πτωχός και δεν ευπορή να φέρη τόσα, τότε θέλει λάβει εν αρνίον διά προσφοράν κινητήν περί ανομίας, διά να κάμη εξιλέωσιν υπέρ αυτού, και εν δέκατον σεμιδάλεως εζυμωμένης μετά ελαίου διά την εξ αλφίτων προσφοράν και εν λογ ελαίου');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'και δύο τρυγόνας ή δύο νεοσσούς περιστερών, όπως ευπορεί να φέρη· και η μεν μία θέλει είσθαι διά την περί αμαρτίας προσφοράν, η δε άλλη διά ολοκαύτωμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Και θέλει φέρει αυτά την ογδόην ημέραν διά τον καθαρισμόν αυτού προς τον ιερέα εις την θύραν της σκηνής του μαρτυρίου ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Και θέλει λάβει ο ιερεύς το αρνίον της περί ανομίας προσφοράς και το λογ του ελαίου και θέλει κινήσει αυτά ο ιερεύς εις προσφοράν κινητήν ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Και θέλει σφάξει το αρνίον της περί ανομίας προσφοράς· και θέλει λάβει ο ιερεύς από του αίματος της περί ανομίας προσφοράς και θέλει βάλει αυτό επί τον λοβόν του δεξιού ωτίου του καθαριζομένου και επί τον αντίχειρα της δεξιάς αυτού χειρός και επί τον μεγάλον δάκτυλον του δεξιού αυτού ποδός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Και θέλει χύσει ο ιερεύς από του ελαίου εις την παλάμην της αριστεράς αυτού χειρός·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'και θέλει ραντίσει ο ιερεύς διά του δακτύλου αυτού του δεξιού από του ελαίου, του εν τη παλάμη αυτού τη αριστερά, επτάκις ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'και θέλει βάλει ο ιερεύς από του ελαίου, του εν τη παλάμη αυτού, επί τον λοβόν του δεξιού ωτίου του καθαριζομένου, και επί τον αντίχειρα της δεξιάς αυτού χειρός και επί τον μεγάλον δάκτυλον του δεξιού αυτού ποδός, επί τον τόπον του αίματος της περί ανομίας προσφοράς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'το δε εναπολειφθέν εκ του ελαίου, του εν τη παλάμη του ιερέως, θέλει βάλει επί την κεφαλήν του καθαριζομένου, διά να κάμη εξιλέωσιν υπέρ αυτού ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Και θέλει προσφέρει την μίαν εκ των τρυγόνων ή εκ των νεοσσών των περιστερών, όπως ευπορεί να φέρη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'όπως ευπορεί να φέρη, την μεν διά προσφοράν περί αμαρτίας, την δε άλλην διά ολοκαύτωμα, μετά της εξ αλφίτων προσφοράς· και θέλει κάμει ο ιερεύς εξιλέωσιν υπέρ του καθαριζομένου ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Ούτος είναι ο νόμος περί του έχοντος πληγήν λέπρας, όστις δεν ευπορεί να φέρη τα προς τον καθαρισμόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Όταν εισέλθητε εις την γην Χαναάν, την οποίαν εγώ σας δίδω εις ιδιοκτησίαν, και βάλω την πληγήν της λέπρας εις τινά οικίαν της γης της ιδιοκτησίας σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'και εκείνος, του οποίου είναι η οικία, έλθη και αναγγείλη προς τον ιερέα, λέγων, Εφάνη εις εμέ ως πληγή εν τη οικία·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'τότε θέλει προστάξει ο ιερεύς να εκκενώσωσι την οικίαν, πριν υπάγη ο ιερεύς διά να θεωρήση την πληγήν, διά να μη γείνωσιν ακάθαρτα πάντα τα εν τη οικία και μετά ταύτα θέλει εμβή ο ιερεύς διά να θεωρήση την οικίαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'και θέλει θεωρήσει την πληγήν· και ιδού, εάν η πληγή ήναι εις τους τοίχους της οικίας με κοιλώματα πρασινίζοντα ή κοκκινωπά και η θεωρία αυτών ήναι βαθυτέρα του τοίχου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'τότε θέλει εξέλθει ο ιερεύς εκ της οικίας εις την θύραν της οικίας και θέλει κλείσει την οικίαν επτά ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Και θέλει επιστρέψει ο ιερεύς την εβδόμην ημέραν και θέλει θεωρήσει και ιδού, εάν η πληγή εξηπλώθη εις τους τοίχους της οικίας,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'τότε ο ιερεύς θέλει προστάξει να εκβάλωσι τους λίθους, εις τους οποίους είναι η πληγή, και θέλουσι ρίψει αυτούς έξω της πόλεως εις τόπον ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Και θέλει κάμει να αποξύσωσι την οικίαν έσωθεν κύκλω, και θέλουσι ρίψει το χώμα το απεξυσμένον έξω της πόλεως εις τόπον ακάθαρτον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'και θέλουσι λάβει άλλους λίθους, και βάλει αυτούς αντί των λίθων εκείνων· και θέλουσι λάβει άλλο χώμα, και θέλουσι χρίσει την οικίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Και εάν έλθη πάλιν η πληγή και αναφανή εις την οικίαν, αφού εξέβαλον τους λίθους και αφού απέξυσαν την οικίαν και αφού αυτή εχρίσθη,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'τότε θέλει εισέλθει ο ιερεύς και θέλει θεωρήσει· και ιδού, εάν η πληγή εξηπλώθη εις την οικίαν, είναι λέπρα διαβρωτική εν τη οικία· είναι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Και θέλουσι κρημνίσει την οικίαν, τους λίθους αυτής και τα ξύλα αυτής και παν το χώμα της οικίας· και θέλουσι φέρει αυτά έξω της πόλεως εις τόπον ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Και όστις εισέλθη εις την οικίαν κατά πάσας τας ημέρας, καθ\' ας είναι κεκλεισμένη, θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Και όστις κοιμηθή εν τη οικία, θέλει πλύνει τα ιμάτια αυτού· και όστις φάγη εν τη οικία, θέλει πλύνει τα ιμάτια αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Αλλ\' εάν ο ιερεύς εισελθών θεωρήση και ιδού, δεν εξηπλώθη η πληγή εν τη οικία, αφού εχρίσθη η οικία, τότε ο ιερεύς θέλει κρίνει την οικίαν καθαράν, διότι ιατρεύθη η πληγή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Και θέλει λάβει, διά να καθαρίση την οικίαν, δύο πτηνά, και ξύλον κέδρινον και κόκκινον και ύσσωπον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Και θέλει σφάξει το εν πτηνόν εις αγγείον πήλινον επάνω ύδατος ζώντος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Και θέλει λάβει το ξύλον το κέδρινον και τον ύσσωπον και το κόκκινον και το πτηνόν το ζων, και εμβάψει αυτά εις το αίμα του εσφαγμένου πτηνού και εις το ύδωρ το ζων, και θέλει ραντίσει την οικίαν επτάκις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Και θέλει καθαρίσει την οικίαν διά του αίματος του πτηνού και διά του ύδατος του ζώντος και διά του πτηνού του ζώντος και διά του ξύλου του κεδρίνου και διά του υσσώπου και διά του κοκκίνου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Το δε ζων πτηνόν θέλει απολύσει έξω της πόλεως επί πρόσωπον της πεδιάδος, και θέλει κάμει εξιλέωσιν υπέρ της οικίας· και θέλει είσθαι καθαρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Ούτος είναι ο νόμος περί πάσης πληγής λέπρας και κασίδας,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'και περί λέπρας ιματίου και οικίας,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'και περί πρήσματος και περί ψώρας και περί εξανθήματος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'διά να γίνηται γνωστόν πότε είναι τι ακάθαρτον και πότε καθαρόν· ούτος είναι ο νόμος περί της λέπρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Λαλήσατε προς τους υιούς Ισραήλ, και είπατε προς αυτούς, Εάν τις άνθρωπος έχη ρεύσιν εκ του σώματος αυτού, διά την ρεύσιν αυτού είναι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Και αύτη θέλει είσθαι η ακαθαρσία αυτού εν τη ρεύσει αυτού· αν τε το σώμα αυτού παύση από της ρεύσεως αυτού· είναι η ακαθαρσία εν αυτώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Πάσα κλίνη, επί της οποίας ήθελε κοιμηθή ο έχων την ρεύσιν, θέλει είσθαι ακάθαρτος· και παν σκεύος, επί του οποίου ήθελε καθίσει, θέλει είσθαι ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Και ο άνθρωπος, όστις εγγίση την κλίνην αυτού, θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Και όστις καθίση επί του σκεύους, επί του οποίου εκάθισεν ο έχων την ρεύσιν, θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Και όστις εγγίση το σώμα του έχοντος την ρεύσιν, θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Και εάν ο έχων την ρεύσιν πτύση επί τον καθαρόν, ούτος θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Και παν σαμάριον επί του οποίου ήθελε καθίσει ο έχων την ρεύσιν, θέλει είσθαι ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Και όστις εγγίση πάντα, όσα ήθελον είσθαι υποκάτω αυτού, θέλει είσθαι ακάθαρτος έως εσπέρας· και όστις βαστάση αυτά, θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Και όντινα εγγίση ο έχων την ρεύσιν, χωρίς να έχη νιμμένας τας χείρας αυτού εν ύδατι, ούτος θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Και το αγγείον το πήλινον, το οποίον ήθελεν εγγίσει ο έχων την ρεύσιν, θέλει συντριφθή· και παν σκεύος ξύλινον θέλει πλυθή εν ύδατι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Και αφού ο έχων την ρεύσιν καθαρισθή από της ρεύσεως αυτού, τότε θέλει αριθμήσει εις εαυτόν επτά ημέρας διά τον καθαρισμόν αυτού· και θέλει πλύνει τα ιμάτια αυτού και θέλει λούσει το σώμα αυτού εν ύδατι ζώντι και θέλει είσθαι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Και την ογδόην ημέραν θέλει λάβει εις εαυτόν δύο τρυγόνας ή δύο νεοσσούς περιστερών και θέλει ελθεί ενώπιον του Κυρίου εις την θύραν της σκηνής του μαρτυρίου και θέλει δώσει αυτάς εις τον ιερέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'και θέλει προσφέρει αυτάς ο ιερεύς, την μεν διά προσφοράν περί αμαρτίας, την δε άλλην διά ολοκαύτωμα· και θέλει κάμει εξιλέωσιν ο ιερεύς υπέρ αυτού ενώπιον του Κυρίου διά την ρεύσιν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Και ο άνθρωπος, εκ του οποίου ήθελεν εξέλθει σπέρμα συνουσίας, θέλει λούσει όλον αυτού το σώμα εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Και παν ιμάτιον και παν δέρμα, επί του οποίου ήθελεν είσθαι σπέρμα συνουσίας, θέλει πλυθή εν ύδατι και θέλει είσθαι ακάθαρτον έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Η δε γυνή, μετά της οποίας ήθελε συγκοιμηθή άνθρωπος εν σπέρματι συνουσίας, θέλουσι λουσθή εν ύδατι και θέλουσιν είσθαι ακάθαρτοι έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Και εάν η γυνή έχη ρεύσιν, η δε ρεύσις αυτής εν τω σώματι αυτής ήναι αίμα, θέλει είσθαι αποκεχωρισμένη επτά ημέρας· και πας όστις εγγίση αυτήν, θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Και παν πράγμα, επί του οποίου κοίτεται εις τον αποχωρισμόν αυτής, θέλει είσθαι ακάθαρτον· και παν πράγμα, επί του οποίου κάθηται, θέλει είσθαι ακάθαρτον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Και πας όστις εγγίση την κλίνην αυτής, θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Και πας όστις εγγίση σκεύος τι, επί του οποίου αυτή εκάθισε, θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Και εάν υπάρχη τι επί της κλίνης ή επί τινός σκεύους, επί του οποίου αυτή κάθηται, όταν αυτός εγγίση αυτό, θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Και εάν τις συγκοιμηθή μετ\' αυτής και έλθωσι τα γυναικεία αυτής επ\' αυτόν, θέλει είσθαι ακάθαρτος επτά ημέρας· και πάσα κλίνη, επί της οποίας ήθελε κοιμηθή, θέλει είσθαι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Και εάν τις γυνή έχη ρεύσιν του αίματος αυτής πολλάς ημέρας, εκτός του καιρού του αποχωρισμού αυτής, ή εάν έχη ρεύσιν επέκεινα του αποχωρισμού αυτής, πάσαι αι ημέραι της ρεύσεως της ακαθαρσίας αυτής θέλουσιν είσθαι ως αι ημέραι του αποχωρισμού αυτής· θέλει είσθαι ακάθαρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Πάσα κλίνη, επί της οποίας κοίτεται καθ\' όλας τας ημέρας της ρεύσεως αυτής, θέλει είσθαι εις αυτήν ως κλίνη του αποχωρισμού αυτής· και παν σκεύος, επί του οποίου κάθηται, θέλει είσθαι ακάθαρτον, ως η ακαθαρσία του αποχωρισμού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Και πας όστις εγγίση αυτά, θέλει είσθαι ακάθαρτος και θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Αλλ\' εάν καθαρισθή από της ρεύσεως αυτής, τότε θέλει αριθμήσει εις εαυτήν επτά ημέρας, και μετά ταύτα θέλει είσθαι καθαρά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Και την ογδόην ημέραν θέλει λάβει μεθ\' εαυτής δύο τρυγόνας ή δύο νεοσσούς περιστερών και θέλει φέρει αυτάς προς τον ιερέα εις την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Και θέλει προσφέρει ο ιερεύς την μεν διά προσφοράν περί αμαρτίας, την δε άλλην διά ολοκαύτωμα· και ο ιερεύς θέλει κάμει εξιλέωσιν περί αυτής ενώπιον του Κυρίου διά την ρεύσιν της ακαθαρσίας αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Ούτω θέλετε χωρίζει τους υιούς Ισραήλ από των ακαθαρσιών αυτών· και δεν θέλουσιν αποθάνει διά την ακαθαρσίαν αυτών, μιαίνοντες την σκηνήν μου την εν τω μέσω αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Ούτος είναι ο νόμος περί του έχοντος ρεύσιν· και περί εκείνου, εκ του οποίου εξέρχεται το σπέρμα συνουσίας, διά να μιαίνηται δι\' αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'και περί της ασθενούσης διά τα γυναικεία αυτής· και περί του έχοντος την ρεύσιν αυτού, ανδρός ή γυναικός, και περί του συγκοιμηθέντος μετά της ακαθάρτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν μετά τον θάνατον των δύο υιών του Ααρών, ότε έκαμον προσφοράν ενώπιον του Κυρίου και απέθανον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'και είπε Κύριος προς τον Μωϋσήν, Λάλησον προς Ααρών τον αδελφόν σου, να μη εισέρχηται πάσαν ώραν εις το αγιαστήριον το ένδοθεν του καταπετάσματος έμπροσθεν του ιλαστηρίου του επί της κιβωτού, διά να μη αποθάνη· διότι εν νεφέλη θέλω εμφανίζεσθαι επί του ιλαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Ούτω θέλει εισέρχεσθαι ο Ααρών εις το αγιαστήριον, μετά μόσχου εκ βοών διά προσφοράν περί αμαρτίας και κριού διά ολοκαύτωμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Χιτώνα λινούν ηγιασμένον θέλει ενδύεσθαι, και περισκελή λινά θέλουσιν είσθαι επί της σαρκός αυτού, και ζώνην λινήν θέλει είσθαι εζωσμένος και μίτραν λινήν θέλει φορεί· ταύτα είναι ενδύματα άγια· και θέλει λούει εν ύδατι το σώμα αυτού και θέλει ενδύεσθαι αυτά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Και παρά της συναγωγής των υιών Ισραήλ θέλει λάβει δύο τράγους εξ αιγών διά προσφοράν περί αμαρτίας και ένα κριόν διά ολοκαύτωμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Και θέλει προσφέρει ο Ααρών τον μόσχον της περί αμαρτίας προσφοράς, όστις είναι δι\' εαυτόν, και θέλει κάμει εξιλέωσιν υπέρ εαυτού και υπέρ του οίκου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Και θέλει λάβει τους δύο τράγους και στήσει αυτούς ενώπιον του Κυρίου εις την θύραν της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Και θέλει ρίψει ο Ααρών κλήρους επί τους δύο τράγους· ένα κλήρον διά τον Κύριον και ένα κλήρον διά τον τράγον τον απολυτέον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Και θέλει φέρει ο Ααρών τον τράγον, επί του οποίου έπεσεν ο κλήρος του Κυρίου, και θέλει προσφέρει αυτόν διά προσφοράν περί αμαρτίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Τον δε τράγον, επί του οποίου έπεσεν ο κλήρος του να απολυθή, θέλει στήσει ζώντα ενώπιον του Κυρίου, διά να κάμη εξιλέωσιν επ\' αυτού, ώστε να αποστείλη αυτόν απόλυτον εις την έρημον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Και θέλει φέρει ο Ααρών τον μόσχον της περί αμαρτίας προσφοράς, όστις είναι δι\' εαυτόν, και θέλει κάμει εξιλέωσιν υπέρ εαυτού και υπέρ του οίκου αυτού· και θέλει σφάξει τον μόσχον της περί αμαρτίας προσφοράς τον περί εαυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Και θέλει λάβει το θυμιατήριον πλήρες ανθράκων πυρός εκ του θυσιαστηρίου απ\' έμπροσθεν του Κυρίου· και θέλει γεμίσει τας χείρας αυτού από ευώδους θυμιάματος λειοτριβημένον και θέλει φέρει αυτό ένδον του καταπετάσματος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Και θέλει βάλει το θυμίαμα επί το πυρ ενώπιον του Κυρίου, και θέλει καλύψει ο καπνός του θυμιάματος το ιλαστήριον το επί του μαρτυρίου, διά να μη αποθάνη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Και θέλει λάβει από του αίματος του μόσχου και ραντίσει διά του δακτύλου αυτού επί το ιλαστήριον κατά ανατολάς· και έμπροσθεν του ιλαστηρίου θέλει ραντίσει επτάκις από του αίματος διά του δακτύλου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Τότε θέλει σφάξει τον τράγον της περί αμαρτίας προσφοράς τον περί του λαού· και θέλει φέρει το αίμα αυτού ένδον του καταπετάσματος και θέλει κάμει το αίμα αυτού, καθώς έκαμε το αίμα του μόσχου, και θέλει ραντίσει αυτό επί το ιλαστήριον και έμπροσθεν του ιλαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Και θέλει κάμει εξιλέωσιν υπέρ του αγιαστηρίου διά τας ακαθαρσίας των υιών Ισραήλ, και διά τας παραβάσεις αυτών καθ\' όλας αυτών τας αμαρτίας· και ούτω θέλει κάμει περί της σκηνής του μαρτυρίου, ήτις κατοικεί μεταξύ αυτών εν τω μέσω της ακαθαρσίας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Ουδείς δε άνθρωπος θέλει είσθαι εν τη σκηνή του μαρτυρίου, όταν αυτός εισέρχηται να κάμη εξιλέωσιν εις το αγιαστήριον, εωσού εξέλθη, αφού κάμη εξιλέωσιν υπέρ εαυτού και υπέρ του οίκου αυτού και υπέρ πάσης της συναγωγής του Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Τότε θέλει εξέλθει προς το θυσιαστήριον το ενώπιον του Κυρίου και θέλει κάμει εξιλέωσιν περί αυτού· και θέλει λάβει από του αίματος του μόσχου και από του αίματος του τράγου και βάλει επί τα κέρατα του θυσιαστηρίου κύκλω.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Και θέλει ραντίσει επ\' αυτό από του αίματος διά του δακτύλου αυτού επτάκις και θέλει καθαρίσει αυτό, και αγιάσει αυτό από των ακαθαρσιών των υιών Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Αφού δε τελειώση να κάμνη εξιλέωσιν υπέρ του αγιαστηρίου και της σκηνής του μαρτυρίου και του θυσιαστηρίου, θέλει φέρει τον τράγον τον ζώντα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'και θέλει επιθέσει ο Ααρών τας δύο χείρας αυτού επί την κεφαλήν του τράγου του ζώντος και θέλει εξομολογηθή επ\' αυτού πάσας τας ανομίας των υιών Ισραήλ και πάσας τας παραβάσεις αυτών καθ\' όλας αυτών τας αμαρτίας· και θέλει επιθέσει αυτάς εις την κεφαλήν του τράγου· και θέλει αποστείλει αυτόν διά χειρός διωρισμένου ανθρώπου εις την έρημον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Και θέλει βαστάσει ο τράγος εφ\' εαυτού πάσας τας ανομίας αυτών εις γην ακατοίκητον· και θέλει απολύσει τον τράγον εις την έρημον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Και θέλει εισέλθει ο Ααρών εις την σκηνήν του μαρτυρίου και θέλει εκδυθή την λινήν στολήν, την οποίαν ενεδύθη εισερχόμενος εις το αγιαστήριον, και θέλει αποθέσει αυτήν εκεί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'και θέλει λούσει το σώμα αυτού εν ύδατι εν τόπω αγίω και ενδυθή τα ιμάτια αυτού, και θέλει έλθει και προσφέρει το ολοκαύτωμα αυτού και το ολοκαύτωμα του λαού και θέλει κάμει εξιλέωσιν περί εαυτού και περί του λαού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Το δε στέαρ της περί αμαρτίας προσφοράς θέλει καύσει επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Και ο αποστείλας τον τράγον τον απολυτέον θέλει πλύνει τα ιμάτια αυτού και λούσει το σώμα αυτού εν ύδατι και μετά ταύτα θέλει εισέλθει εις το στρατόπεδον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Τον δε μόσχον της περί αμαρτίας προσφοράς και τον τράγον της περί αμαρτίας προσφοράς, των οποίων το αίμα εισήχθη διά να γείνη εξιλέωσις εις το αγιαστήριον, θέλουσι φέρει έξω του στρατοπέδου· και θέλουσι καύσει εν τω πυρί τα δέρματα αυτών και το κρέας αυτών και την κόπρον αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Και ο καίων αυτά θέλει πλύνει τα ιμάτια αυτού και λούσει το σώμα αυτού εν ύδατι και μετά ταύτα θέλει εισέλθει εις το στρατόπεδον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Και τούτο θέλει είσθαι εις εσάς νόμιμον αιώνιον· εις τον έβδομον μήνα, την δεκάτην του μηνός, θέλετε ταπεινώσει τας ψυχάς σας και δεν θέλετε κάμει ουδέν έργον ούτε ο αυτόχθων ούτε ο ξένος ο παροικών μεταξύ σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'διότι εν τη ημέρα ταύτη ο ιερεύς θέλει κάμει εξιλέωσιν διά σας, διά να σας καθαρίση, ώστε να ήσθε καθαροί από πασών των αμαρτιών υμών ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Σάββατον αναπαύσεως θέλει είσθαι εις εσάς, και θέλετε ταπεινώσει τας ψυχάς σας κατά νόμιμον αιώνιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Και θέλει κάμει την εξιλέωσιν ο ιερεύς, ο χρισθείς και καθιερωθείς διά να ιερατεύη αντί του πατρός αυτού, και θέλει ενδυθή την λινήν στολήν, την στολήν την αγίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Και θέλει κάμει εξιλέωσιν υπέρ του αγίου αγιαστηρίου και θέλει κάμει εξιλέωσιν υπέρ της σκηνής του μαρτυρίου και υπέρ του θυσιαστηρίου· και θέλει κάμει εξιλέωσιν υπέρ των ιερέων και υπέρ παντός του λαού της συναγωγής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Και τούτο θέλει είσθαι εις εσάς νόμιμον αιώνιον, να κάμνητε εξιλέωσιν υπέρ των υιών Ισραήλ περί πασών των αμαρτιών αυτών άπαξ του ενιαυτού. Και έγεινε καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Λάλησον προς τον Ααρών και προς τους υιούς αυτού και προς πάντας τους υιούς Ισραήλ και ειπέ προς αυτούς, Ούτος είναι ο λόγος τον οποίον προσέταξεν ο Κύριος, λέγων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Όστις άνθρωπος εκ του οίκου Ισραήλ σφάξη βουν ή αρνίον ή αίγα εν τω στρατοπέδω, ή όστις σφάξη έξω του στρατοπέδου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'και εις την θύραν της σκηνής του μαρτυρίου δεν φέρη αυτό, διά να προσφέρη προσφοράν εις τον Κύριον έμπροσθεν της σκηνής του Κυρίου, αίμα θέλει λογισθή εις εκείνον τον άνθρωπον· αίμα έχυσε και θέλει εξολοθρευθή ο άνθρωπος εκείνος εκ μέσου του λαού αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'διά να φέρωσιν οι υιοί Ισραήλ τας θυσίας αυτών, τας οποίας θυσιάζουσιν εν τη πεδιάδι, και να προσφέρωσιν αυτάς προς τον Κύριον εις την θύραν της σκηνής του μαρτυρίου προς τον ιερέα και να θυσιάζωσιν αυτάς εις προσφοράς ειρηνικάς προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Και θέλει ραντίσει ο ιερεύς το αίμα επί το θυσιαστήριον του Κυρίου εις την θύραν της σκηνής του μαρτυρίου και θέλει καύσει το στέαρ εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Και δεν θέλουσι θυσιάσει πλέον τας θυσίας αυτών εις τους δαίμονας, κατόπιν των οποίων αυτοί πορνεύουσι· τούτο θέλει είσθαι εις αυτούς νόμιμον αιώνιον εις τας γενεάς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Και θέλεις ειπεί προς αυτούς, Όστις άνθρωπος εκ του οίκου Ισραήλ ή εκ των ξένων των παροικούντων μεταξύ σας προσφέρη ολοκαύτωμα ή θυσίαν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'και εις την θύραν της σκηνής του μαρτυρίου δεν φέρη αυτό, διά να προσφέρη αυτό προς τον Κύριον, θέλει εξολοθρευθή ο άνθρωπος εκείνος εκ μέσου του λαού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Και όστις άνθρωπος εκ του οίκου Ισραήλ ή εκ των ξένων των παροικούντων μεταξύ σας φάγη οιονδήποτε αίμα, θέλω στήσει το πρόσωπόν μου εναντίον εκείνης της ψυχής ήτις τρώγει το αίμα, και θέλω εξολοθρεύσει αυτήν εκ μέσου του λαού αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'διότι η ζωή της σαρκός είναι εν τω αίματι και εγώ έδωκα αυτό εις εσάς, διά να κάμνητε εξιλέωσιν υπέρ των ψυχών σας επί του θυσιαστηρίου· διότι το αίμα τούτο κάμνει εξιλασμόν υπέρ της ψυχής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Διά τούτο είπα προς τους υιούς Ισραήλ, Ουδεμία ψυχή από σας θέλει φάγει αίμα· ουδέ ο ξένος, ο παροικών μεταξύ σας, θέλει φάγει αίμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Και όστις άνθρωπος εκ των υιών Ισραήλ ή εκ των ξένων των παροικούντων μεταξύ σας, κυνηγήση και πιάση ζώον ή πτηνόν, το οποίον τρώγεται, θέλει χύσει το αίμα αυτού και θέλει σκεπάσει αυτό με χώμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Διότι η ζωή πάσης σαρκός είναι το αίμα αυτής· διά την ζωήν αυτής είναι· όθεν είπα προς τους υιούς Ισραήλ, Δεν θέλετε φάγει αίμα ουδεμιάς σαρκός· διότι η ζωή πάσης σαρκός είναι το αίμα αυτής· πας ο τρώγων αυτό θέλει εξολοθρευθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Και πάσα ψυχή, ήτις φάγη θνησιμαίον ή διεσπαραγμένον υπό θηρίου, αυτόχθων ή ξένος, θέλει πλύνει τα ιμάτια αυτού και θέλει λουσθή εν ύδατι και θέλει είσθαι ακάθαρτος έως εσπέρας· τότε θέλει είσθαι καθαρός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Αλλ\' εάν δεν πλύνη αυτά μηδέ λούση το σώμα αυτού, τότε θέλει βαστάσει την ανομίαν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Εγώ είμαι Κύριος, ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Κατά τας πράξεις της γης Αιγύπτου, εν ή κατωκήσατε, δεν θέλετε πράξει και κατά τας πράξεις της γης Χαναάν, εις την οποίαν εγώ σας φέρω, δεν θέλετε πράξει και κατά τα νόμιμα αυτών δεν θέλετε περιπατήσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Τας κρίσεις μου θέλετε κάμει και τα προστάγματά μου θέλετε φυλάττει, διά να περιπατήτε εις αυτά. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Θέλετε φυλάττει λοιπόν τα προστάγματά μου και τας κρίσεις μου· τα οποία κάμνων ο άνθρωπος, θέλει ζήσει δι\' αυτών. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ουδείς άνθρωπος θέλει πλησιάσει εις ουδένα συγγενή αυτού κατά σάρκα, διά να αποκαλύψη την ασχημοσύνην αυτού. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Ασχημοσύνην πατρός σου, ή ασχημοσύνην μητρός σου δεν θέλεις αποκαλύψει· είναι μήτηρ σου· δεν θέλεις αποκαλύψει την ασχημοσύνην αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Ασχημοσύνην γυναικός του πατρός σου δεν θέλεις αποκαλύψει· είναι ασχημοσύνη του πατρός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Ασχημοσύνην αδελφής σου θυγατρός του πατρός σου ή θυγατρός της μητρός σου, γεννημένης εν τη οικία ή γεννημένης έξω, τούτων την ασχημοσύνην δεν θέλεις αποκαλύψει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Ασχημοσύνην θυγατρός του υιού σου ή θυγατρός της θυγατρός σου, τούτων την ασχημοσύνην δεν θέλεις αποκαλύψει διότι ιδική σου είναι η ασχημοσύνη αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Ασχημοσύνην θυγατρός της γυναικός του πατρός σου, γεννημένης από του πατρός σου, ήτις είναι αδελφή σου, δεν θέλεις αποκαλύψει την ασχημοσύνην αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Ασχημοσύνην αδελφής του πατρός σου δεν θέλεις αποκαλύψει είναι στενή συγγενής του πατρός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Ασχημοσύνην αδελφής της μητρός σου δεν θέλεις αποκαλύψει· διότι είναι στενή συγγενής της μητρός σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Ασχημοσύνην αδελφού του πατρός σου δεν θέλεις αποκαλύψει· εις την γυναίκα αυτού δεν θέλεις πλησιάσει· είναι θεία σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Ασχημοσύνην νύμφης σου δεν θέλεις αποκαλύψει· είναι γυνή του υιού σου· δεν θέλεις αποκαλύψει την ασχημοσύνην αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Ασχημοσύνην αδελφού σου δεν θέλεις αποκαλύψει· είναι η ασχημοσύνη του αδελφού σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Ασχημοσύνην γυναικός και της θυγατρός αυτής δεν θέλεις αποκαλύψει ουδέ θέλεις λάβει την θυγατέρα του υιού αυτής ή την θυγατέρα της θυγατρός αυτής, διά να αποκαλύψης την ασχημοσύνην αυτής· είναι στεναί συγγενείς αυτής· είναι ασέβημα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Και γυναίκα προς τη αδελφή αυτής αντίζηλον δεν θέλεις λάβει, διά να αποκαλύψης την ασχημοσύνην αυτής προς τη άλλη, εν όσω ζη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Και εις γυναίκα, εν καιρώ αποχωρισμού διά την ακαθαρσίαν αυτής δεν θέλεις πλησιάσει διά να αποκαλύψης την ασχημοσύνην αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Και μετά της γυναικός του πλησίον σου δεν θέλεις συνουσιασθή, διά να μιανθής μετ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Και δεν θέλεις αφήσει τινά εκ του σπέρματός σου να περάση διά του πυρός εις τον Μολόχ και δεν θέλεις βεβηλώσει το όνομα του Θεού σου. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Και μετά άρρενος δεν θέλεις συνουσιασθή, ως μετά γυναικός· είναι βδέλυγμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Ουδέ θέλεις συνουσιασθή μετ\' ουδενός κτήνους, διά να μιανθής μετ\' αυτού· ουδέ γυνή θέλει σταθή έμπροσθεν κτήνους, διά να βατευθή· είναι μυσαρόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Μη μιαίνεσθε εις ουδέν εκ τούτων· διότι εις πάντα ταύτα εμιάνθησαν τα έθνη, τα οποία εγώ εκδιώκω απ\' έμπροσθέν σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'και εμιάνθη η γή· διά τούτο ανταποδίδω την ανομίαν αυτής επ\' αυτήν, και η γη θέλει εξεμέσει τους κατοίκους αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Σεις λοιπόν θέλετε φυλάξει τα προστάγματά μου και τας κρίσεις μου και δεν θέλετε πράττει ουδέν εκ πάντων των βδελυγμάτων τούτων, ο αυτόχθων ή ο ξένος ο παροικών μεταξύ σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'διότι πάντα τα βδελύγματα ταύτα έπραξαν οι άνθρωποι της γης, οι προ υμών, και εμιάνθη η γή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'διά να μη σας εξεμέση η γη, όταν μιάνητε αυτήν, καθώς εξήμεσε τα έθνη τα προ υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Διότι πας όστις πράξη τι εκ των βδελυγμάτων τούτων, αι ψυχαί αίτινες ήθελον πράξει αυτά θέλουσιν εξολοθρευθή εκ μέσου του λαού αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Όθεν θέλετε φυλάττει τα προστάγματά μου, ώστε να μη πράξητε μηδέν εκ των βδελυρών τούτων νομίμων, τα οποία επράχθησαν προ υμών, και να μη μιανθήτε εις αυτά. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Λάλησον προς πάσαν την συναγωγήν των υιών Ισραήλ και ειπέ προς αυτούς, Άγιοι θέλετε είσθαι· διότι άγιος είμαι εγώ Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Θέλετε φοβείσθαι έκαστος την μητέρα αυτού και τον πατέρα αυτού· και τα σάββατά μου θέλετε φυλάττει. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Μη στραφήτε εις είδωλα μηδέ κάμητε εις εαυτούς θεούς χωνευτούς. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Και όταν προσφέρητε θυσίαν ειρηνικής προσφοράς προς τον Κύριον, αυτοπροαιρέτως θέλετε προσφέρει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Θέλει τρώγεσθαι την ημέραν καθ\' ην προσφέρετε αυτήν, και την επαύριον· εάν δε μείνη τι έως της τρίτης ημέρας, με πυρ θέλει κατακαυθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Εάν δε ποτέ φαγωθή την ημέραν την τρίτην, είναι βδελυκτόν· δεν θέλει είσθαι ευπρόσδεκτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Διά τούτο όστις φάγη αυτήν, θέλει βαστάσει την ανομίαν αυτού, διότι εβεβήλωσε τα άγια του Κυρίου· και η ψυχή αύτη θέλει εξολοθρευθή εκ του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Και όταν θερίζητε τον θερισμόν της γης σας, δεν θέλεις θερίσει ολοκλήρως τας άκρας του αγρού σου και τα αποπίπτοντα του θερισμού σου δεν θέλεις συλλέξει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Και τον αμπελώνά σου δεν θέλεις επανατρυγήσει ούτε τας ρώγας του αμπελώνός σου θέλεις συλλέξει· εις τον πτωχόν και εις τον ξένον θέλεις αφήσει αυτάς. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Δεν θέλετε κλέπτει ουδέ θέλετε ψεύδεσθαι ουδέ θέλετε απατήσει έκαστος τον πλησίον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Και δεν θέλετε ομνύει εις το όνομά μου ψευδώς και δεν θέλεις βεβηλόνει το όνομα του Θεού σου. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Δεν θέλεις αδικήσει τον πλησίον σου ουδέ θέλεις αρπάσει· δεν θέλει διανυκτερεύσει ο μισθός του μισθωτού μετά σου έως πρωΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Δεν θέλεις κακολογήσει τον κωφόν, και έμπροσθεν του τυφλού δεν θέλεις βάλει πρόσκομμα, αλλά θέλεις φοβηθή τον Θεόν σου. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Δεν θέλετε κάμει αδικίαν εις κρίσιν· δεν θέλεις αποβλέψει εις πρόσωπον πτωχού ουδέ θέλεις σεβασθή πρόσωπον δυνάστου· εν δικαιοσύνη θέλεις κρίνει τον πλησίον σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Δεν θέλεις περιφέρεσθαι συκοφαντών μεταξύ του λαού σου· ουδέ θέλεις σηκωθή κατά του αίματος του πλησίον σου. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Δεν θέλεις μισήσει τον αδελφόν σου εν τη καρδία σου· θέλεις ελέγξει παρρησία τον πλησίον σου και δεν θέλεις υποφέρει αμαρτίαν επ\' αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Δεν θέλεις εκδικείσθαι ουδέ θέλεις μνησικακεί κατά των υιών του λαού σου· αλλά θέλεις αγαπά τον πλησίον σου ως σεαυτόν. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Τα νόμιμά μου θέλετε φυλάττει· δεν θέλεις κάμει τα κτήνη σου να βατεύωνται με ετεροειδή· εις τον αγρόν σου δεν θέλεις σπείρει ετεροειδή σπέρματα· ουδέ θέλεις βάλει επάνω σου ένδυμα σύμμικτον εξ ετεροειδούς κλωστής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Και εάν τις συνουσιασθή μετά γυναικός, ήτις είναι δούλη ηρραβωνισμένη μετά ανδρός και δεν είναι εξηγορασμένη, ουδέ εδόθη εις αυτήν η ελευθερία, θέλουσι μαστιγωθή· δεν θέλουσι φονευθή, διότι αυτή δεν ήτο ελευθέρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Και αυτός θέλει φέρει την περί ανομίας προσφοράν αυτού προς τον Κύριον εις την θύραν της σκηνής του μαρτυρίου, κριόν διά προσφοράν περί ανομίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Και θέλει κάμει ο ιερεύς εξιλέωσιν περί αυτού διά του κριού της περί ανομίας προσφοράς ενώπιον του Κυρίου, διά την αμαρτίαν αυτού την οποίαν ημάρτησε· και θέλει συγχωρηθή εις αυτόν η αμαρτία αυτού την οποίαν ημάρτησε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Και όταν εισέλθητε εις την γην και φυτεύσητε παν δένδρον τρόφιμον, τότε θέλετε περικαθαρίζει τον καρπόν αυτού ως ακάθαρτον· τρία έτη θέλει είσθαι εις εσάς ακάθαρτος· δεν θέλει τρώγεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Και εις το τέταρτον έτος θέλει είσθαι όλος ο καρπός αυτού άγιος εις δόξαν του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Εις δε το πέμπτον έτος θέλετε τρώγει τον καρπόν αυτού, διά να πληθυνθή εις εσάς το εισόδημα αυτού. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Δεν θέλετε τρώγει ουδέν μετά του αίματος αυτού· ουδέ θέλετε μεταχειρίζεσθαι μαντείας ουδέ θέλετε προμαντεύει καιρούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Δεν θέλετε κουρεύσει κυκλοειδώς την κόμην της κεφαλής σας ουδέ θέλετε φθείρει τα άκρα των πωγώνων σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Δεν θέλετε κάμει εντομίδας εις το σώμα σας διά νεκρόν, ουδέ γράμματα στικτά θέλετε εγχαράξει επάνω σας. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Δεν θέλεις βεβηλώσει την θυγατέρα σου, καθιστών αυτήν πόρνην· μήπως ο τόπος πέση εις πορνείαν και γεμίση ο τόπος από ασεβείας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Τα σάββατά μου θέλετε φυλάττει, και το αγιαστήριόν μου θέλετε σέβεσθαι. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Δεν θέλετε ακολουθεί τους έχοντας πνεύμα μαντείας ουδέ θέλετε προσκολληθή εις επαοιδούς, ώστε να μιαίνησθε δι\' αυτών. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Ενώπιον της πολιάς θέλεις προσηκόνεσθαι και θέλεις τιμήσει το πρόσωπον του γέροντος και θέλεις φοβηθή τον Θεόν σου. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Και εάν τις ξένος παροική μετά σου εν τη γη υμών, δεν θέλετε θλίψει αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'ο ξένος, ο παροικών με σας, θέλει είσθαι εις εσάς ως ο αυτόχθων, και θέλεις αγαπά αυτόν ως σεαυτόν· διότι ξένοι εστάθητε εν γη Αιγύπτου. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Δεν θέλετε πράξει αδικίαν εις κρίσιν, εις μέτρα, εις σταθμά και εις ζύγια·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'ζύγια δίκαια σταθμά δίκαια, εφά δίκαιον, και ιν δίκαιον, θέλετε έχει. Εγώ είμαι Κύριος ο Θεός σας, όστις σας εξήγαγον εκ γης Αιγύπτου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Θέλετε φυλάττει λοιπόν πάντα τα διατάγματά μου και πάσας τας κρίσεις μου και θέλετε κάμνει αυτά. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Και προς τους υιούς Ισραήλ θέλεις ειπεί, Όστις εκ των υιών Ισραήλ ή εκ των ξένων των παροικούντων εν τω Ισραήλ δώση από του σπέρματος αυτού εις τον Μολόχ, θέλει εξάπαντος θανατωθή· ο λαός του τόπου θέλει λιθοβολήσει αυτόν με λίθους.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Και εγώ θέλω επιστήσει το πρόσωπόν μου κατά του ανθρώπου εκείνου και θέλω εξολοθρεύσει αυτόν εκ μέσου του λαού αυτού· διότι από του σπέρματος αυτού έδωκεν εις τον Μολόχ, διά να μιάνη το αγιαστήριόν μου και να βεβηλώση το όνομά μου το άγιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Εάν δε ο λαός του τόπου παραβλέψη με τους οφθαλμούς αυτού τον άνθρωπον εκείνον, όταν δίδη από του σπέρματος αυτού εις τον Μολόχ, και δεν φονεύση αυτόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'τότε θέλω επιστήσει εγώ το πρόσωπόν μου κατά του ανθρώπου εκείνου και κατά της συγγενείας αυτού· και θέλω εξολοθρεύσει εκ μέσου του λαού αυτού αυτόν, και πάντας τους ακολουθούντας αυτόν εις την πορνείαν, διά να πορνεύωσι κατόπιν του Μολόχ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Και ψυχή, ήτις ακολουθήση τους έχοντας πνεύμα μαντείας και τους επαοιδούς, διά να πορνεύη κατόπιν αυτών, θέλω επιστήσει το πρόσωπόν μου κατά της ψυχής εκείνης, και θέλω εξολοθρεύσει αυτήν εκ μέσου του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Αγιάσθητε λοιπόν και γίνεσθε άγιοι διότι εγώ είμαι Κύριος ο Θεός σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Και θέλετε φυλάττει τα διατάγματά μου και θέλετε εκτελεί αυτά. Εγώ είμαι ο Κύριος, ο αγιάζων υμάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Πας άνθρωπος, όστις κακολογήση τον πατέρα αυτού ή την μητέρα αυτού, εξάπαντος θέλει θανατωθή· τον πατέρα αυτού ή την μητέρα αυτού, εκακολόγησε· το αίμα αυτού θέλει είσθαι επ\' αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Και άνθρωπος, όστις μοιχεύση την γυναίκα τινός, όστις μοιχεύση την γυναίκα του πλησίον αυτού, εξάπαντος θέλει θανατωθή, ο μοιχεύων και η μοιχευομένη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Και άνθρωπος, όστις κοιμηθή μετά της γυναικός του πατρός αυτού, την ασχημοσύνην του πατρός αυτού απεκάλυψεν· εξάπαντος θέλουσι θανατωθή αμφότεροι· το αίμα αυτών θέλει είσθαι επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Και εάν τις κοιμηθή μετά της νύμφης αυτού, εξάπαντος θέλουσι θανατωθή αμφότεροι· σύγχυσιν έπραξαν· το αίμα αυτών θέλει είσθαι επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Εάν δε τις κοιμηθή μετά άρρενος, καθώς κοιμάται μετά γυναικός, βδέλυγμα έπραξαν αμφότεροι· εξάπαντος θέλουσι θανατωθή· το αίμα αυτών θέλει είσθαι επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Και εάν τις λάβη γυναίκα και την μητέρα αυτής, είναι ανομία· εν πυρί θέλουσι καυθή, αυτός και αυταί, και δεν θέλει είσθαι ανομία μεταξύ σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Και εάν τις συνουσιασθή μετά κτήνους, εξάπαντος θέλει θανατωθή· και το κτήνος θέλετε φονεύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Και η γυνή, ήτις πλησιάση εις οιονδήποτε κτήνος διά να βατευθή, θέλεις φονεύσει την γυναίκα και το κτήνος· εξάπαντος θέλουσι θανατωθή· το αίμα αυτών θέλει είσθαι επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Και εάν τις λάβη την αδελφήν αυτού, την θυγατέρα του πατρός αυτού ή την θυγατέρα της μητρός αυτού, και ίδη την ασχημοσύνην αυτής και αυτή ίδη την ασχημοσύνην εκείνου, είναι αισχρόν· και θέλουσιν εξολοθρευθή έμπροσθεν του λαού αυτών· την ασχημοσύνην της αδελφής αυτού απεκάλυψε· την ανομίαν αυτού θέλει βαστάσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Και άνθρωπος, όστις κοιμηθή μετά γυναικός εχούσης τα γυναικεία αυτής και αποκαλύψη την ασχημοσύνην αυτής, ούτος την πηγήν αυτής εξεσκέπασε και αύτη την πηγήν του αίματος αυτής απεκάλυψεν· όθεν αμφότεροι θέλουσιν εξολοθρευθή εκ μέσου του λαού αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Και την ασχημοσύνην της αδελφής της μητρός σου ή της αδελφής του πατρός σου δεν θέλεις αποκαλύψει· διότι την στενήν συγγενή αυτού αποκαλύπτει· την ανομίαν αυτών θέλουσι βαστάσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Εάν δε τις κοιμηθή μετά της θείας αυτού, την ασχημοσύνην του θείου αυτού απεκάλυψε· την αμαρτίαν αυτών θέλουσι βαστάσει· άτεκνοι θέλουσιν αποθάνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Και εάν τις λάβη την γυναίκα του αδελφού αυτού, είναι ακαθαρσία· την ασχημοσύνην του αδελφού αυτού απεκάλυψεν· άτεκνοι θέλουσι μείνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Θέλετε λοιπόν φυλάττει πάντα τα διατάγματά μου και πάσας τας κρίσεις μου, και θέλετε κάμνει αυτά· διά να μη σας εξεμέση η γη, όπου εγώ σας φέρω διά να κατοικήσητε εν αυτή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Και δεν θέλετε περιπατεί κατά τα νόμιμα των εθνών, τα οποία εγώ εκδιώκω απ\' έμπροσθέν σας· διότι πάντα ταύτα έπραξαν, όθεν εβδελύχθην αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Και είπα προς εσάς, Σεις θέλετε κληρονομήσει την γην αυτών, και εγώ θέλω δώσει αυτήν εις εσάς προς ιδιοκτησίαν, γην ρέουσαν γάλα και μέλι. Εγώ είμαι Κύριος ο Θεός σας, όστις σας απεχώρισα από των λαών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Διά τούτο θέλετε αποχωρίσει τα κτήνη τα καθαρά από των ακαθάρτων και τα πτηνά τα ακάθαρτα από των καθαρών· και δεν θέλετε μιάνει τας ψυχάς σας με τα κτήνη ή με τα πτηνά ή με παν ό,τι έρπει επί της γης, τα οποία εγώ απεχώρισα εις σας ως ακάθαρτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Και θέλετε είσθαι άγιοι εις εμέ· διότι άγιος είμαι εγώ ο Κύριος και σας απεχώρισα από των λαών, διά να ήσθε εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Και ανήρ η γυνή, ήτις έχει πνεύμα μαντείας, ή είναι επαοιδός, εξάπαντος θέλει θανατωθή· με λίθους θέλουσι λιθοβολήσει αυτούς· το αίμα αυτών θέλει είσθαι επ\' αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Και είπε Κύριος προς τον Μωϋσήν, Λάλησον προς τους ιερείς τους υιούς του Ααρών, και ειπέ προς αυτούς, Ουδείς θέλει μιανθή μεταξύ του λαού αυτού διά νεκρόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'ει μη διά τον συγγενή αυτού τον πλησιέστερον, διά την μητέρα αυτού και διά τον πατέρα αυτού και διά τον υιόν αυτού και διά την θυγατέρα αυτού και διά τον αδελφόν αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'και διά την αδελφήν αυτού, παρθένον ούσαν, την πλησιεστάτην εις αυτόν, ήτις δεν έλαβεν άνδρα· διά ταύτην δύναται να μιανθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Δεν θέλει μιανθή αρχηγός ων του λαού αυτού, ώστε να βεβηλώση εαυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Δεν θέλουσι φαλακρώσει την κεφαλήν αυτών ουδέ θέλουσι ξυρίσει τα πλάγια των πωγώνων αυτών ουδέ θέλουσι κάμει εντομίδας επί τας σάρκας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Άγιοι θέλουσιν είσθαι εις τον Θεόν αυτών και δεν θέλουσι βεβηλώσει το όνομα του Θεού αυτών· διότι τας διά πυρός γινομένας προσφοράς του Κυρίου, τον άρτον του Θεού αυτών, προσφέρουσι διά τούτο θέλουσιν είσθαι άγιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Γυναίκα πόρνην και βεβηλωμένην δεν θέλουσι λάβει ουδέ γυναίκα αποβεβλημένην από του ανδρός αυτής θέλουσι λάβει· διότι ο ιερεύς είναι άγιος εις τον Θεόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Θέλεις λοιπόν αγιάσει αυτόν· διότι αυτός τον άρτον του Θεού σου προσφέρει· άγιος θέλει είσθαι εις σέ· διότι άγιος είμαι εγώ ο Κύριος, ο αγιάζων υμάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Και θυγάτηρ ιερέως τινός, εάν βεβηλωθή διά πορνείας, τον πατέρα αυτής αυτή βεβηλόνει· εν πυρί θέλει κατακαυθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Και ο ιερεύς ο μέγας μεταξύ των αδελφών αυτού, επί την κεφαλήν του οποίου εχύθη το έλαιον του χρίσματος, και όστις καθιερώθη διά να ενδύηται τας ιεράς στολάς, την κεφαλήν αυτού δεν θέλει αποκαλύψει, ουδέ τα ιμάτια αυτού θέλει διασχίσει·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'και εις ουδέν σώμα νεκρόν θέλει εισέλθει ουδέ διά τον πατέρα αυτού ή διά την μητέρα αυτού θέλει μιανθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Και εκ του αγιαστηρίου δεν θέλει εξέλθει ουδέ θέλει βεβηλώσει το αγιαστήριον του Θεού αυτού· διότι το άγιον έλαιον του χρίσματος του Θεού αυτού είναι επ\' αυτόν. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Και ούτος θέλει λάβει γυναίκα παρθένον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'χήραν ή αποβεβλημένην ή βέβηλον ή πόρνην, ταύτας δεν θέλει λάβει· αλλά παρθένον εκ του λαού αυτού θέλει λάβει εις γυναίκα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Και δεν θέλει βεβηλώσει το σπέρμα αυτού μεταξύ του λαού αυτού· διότι εγώ είμαι ο Κύριος, ο αγιάζων αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Ειπέ προς τον Ααρών, λέγων, Όστις εκ του σπέρματός σου εις τας γενεάς αυτών έχει μώμον, ας μη πλησιάση διά να προσφέρη τον άρτον του Θεού αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'διότι πας όστις έχει μώμον δεν θέλει πλησιάσει· άνθρωπος τυφλός, ή χωλός, ή κολοβομύττης, ή έχων τι περιττόν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ή άνθρωπος όστις έχει σύντριμμα ποδός, ή σύντριμμα χειρός,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ή είναι κυρτός, ή πολύ ισχνός, ή όστις έχει βεβλαμμένους τους οφθαλμούς, ή έχει ψώραν ξηράν, ή λειχήνα, ή είναι εσπασμένος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'ουδείς άνθρωπος εκ του σπέρματος του Ααρών του ιερέως, όστις έχει μώμον, θέλει πλησιάσει διά να προσφέρη τας διά πυρός γινομένας προσφοράς εις τον Κύριον· μώμον έχει· δεν θέλει πλησιάσει διά να προσφέρη τον άρτον του Θεού αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Θέλει τρώγει τον άρτον του Θεού αυτού εκ των αγιωτάτων, και εκ των αγίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Πλην εις το καταπέτασμα δεν θέλει εισέρχεσθαι ουδέ εις το θυσιαστήριον θέλει πλησιάσει, διότι έχει μώμον· διά να μη βεβηλώση το αγιαστήριόν μου· διότι εγώ είμαι ο Κύριος, ο αγιάζων αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Και ελάλησεν ο Μωϋσής ταύτα προς τον Ααρών και προς τους υιούς αυτού και προς πάντας τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Ειπέ προς τον Ααρών και προς τους υιούς αυτού να απέχωσιν από των αγίων των υιών Ισραήλ, και να μη βεβηλόνωσι το όνομα το άγιόν μου, εις όσα αγιάζουσιν εις εμέ. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Ειπέ προς αυτούς, πας άνθρωπος εκ παντός του σπέρματός σας εις τας γενεάς σας, όστις πλησιάση εις τα άγια, τα οποία οι υιοί του Ισραήλ αγιάζουσιν εις τον Κύριον, έχων την ακαθαρσίαν αυτού εφ\' εαυτόν, η ψυχή εκείνη θέλει εξολοθρευθή απ\' έμπροσθέν μου. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Όστις εκ του σπέρματος του Ααρών είναι λεπρός ή έχει ρεύσιν, από των αγίων δεν θέλει τρώγει, εωσού καθαρισθή. Και όστις εγγίση παν ακάθαρτον από νεκρόν ή άνθρωπον εκ του οποίου έγεινε ρεύσις σπέρματος,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'ή όστις εγγίση οιονδήποτε ερπετόν, εκ του οποίου δύναται να μιανθή, ή άνθρωπον, εκ του οποίου δύναται να μιανθή, οποιαδήποτε είναι η ακαθαρσία αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'η ψυχή, ήτις εγγίση αυτά, θέλει είσθαι ακάθαρτος έως εσπέρας· και δεν θέλει φάγει από των αγίων· εάν μη λούση το σώμα αυτού εν ύδατι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Και αφού δύση ο ήλιος θέλει είσθαι καθαρός, και έπειτα θέλει φάγει από των αγίων· διότι είναι η τροφή αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Θνησιμαίον ή θηριάλωτον δεν θέλει φάγει, ώστε να μιανθή εν αυτοίς. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Όθεν θέλουσι φυλάττει τα διατάγματά μου, διά να μη βαστάσωσιν αμαρτίαν εκ τούτου και αποθάνωσι δι\' αυτό, εάν βεβηλώσωσιν αυτά. Εγώ είμαι ο Κύριος, ο αγιάζων αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Και ουδείς αλλογενής θέλει φάγει από των αγίων· συγκάτοικος του ιερέως ή μισθωτός δεν θέλει φάγει από των αγίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Αλλ\' εάν ο ιερεύς αγοράση ψυχήν διά του αργυρίου αυτού, ούτος θέλει τρώγει εξ αυτών, καθώς και ο γεννηθείς εν τη οικία αυτού· ούτοι θέλουσι τρώγει από του άρτου αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Και η θυγάτηρ του ιερέως, αν ήναι νενυμφευμένη μετά ανδρός ξένου, αύτη δεν θέλει τρώγει από των αγίων των προσφορών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Αλλ\' εάν η θυγάτηρ του ιερέως χηρεύση ή αποβληθή και δεν έχη τέκνον και επιστρέψη εις τον πατρικόν αυτής οίκον, καθώς ευρίσκετο εν τη νεότητι αυτής, θέλει τρώγει από του άρτου του πατρός αυτής· ουδείς όμως ξένος θέλει φάγει απ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Εάν δε άνθρωπός τις φάγη από των αγίων εξ αγνοίας, τότε θέλει προσθέσει το πέμπτον τούτου εις αυτό, και θέλει αποδώσει εις τον ιερέα το άγιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Και δεν θέλουσι βεβηλώσει τα άγια των υιών Ισραήλ, τα οποία προσφέρουσιν εις τον Κύριον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'και δεν θέλουσιν αναλάβει εφ\' εαυτούς ανομίαν παραβάσεως, τρώγοντες τα άγια αυτών· διότι εγώ είμαι ο Κύριος, ο αγιάζων αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Λάλησον προς τον Ααρών και προς τους υιούς αυτού και προς πάντας τους υιούς Ισραήλ και ειπέ προς αυτούς, Πας άνθρωπος εκ του οίκου Ισραήλ ή εκ των ξένων των εν τω Ισραήλ, όστις προσφέρη το δώρον αυτού, κατά πάσας τας ευχάς αυτών ή κατά πάσας τας αυτοπροαιρέτους προσφοράς αυτών, τας οποίας προσφέρουσιν εις τον Κύριον διά ολοκαύτωμα,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'θέλετε προσφέρει, διά να ήσθε δεκτοί, αρσενικόν άμωμον εκ των βοών, εκ των προβάτων ή εκ των αιγών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'παν ό,τι έχει μώμον, δεν θέλετε προσφέρει διότι δεν θέλει είσθαι δεκτόν διά σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Και όστις προσφέρει θυσίαν ειρηνικής προσφοράς εις τον Κύριον διά να εκπληρώση ευχήν, ή προσφοράν αυτοπροαίρετον, εκ των βοών ή εκ των προβάτων, θέλει είσθαι άμωμον διά να ήναι δεκτόν· ουδείς μώμος θέλει είσθαι εις αυτό.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Τυφλόν, ή συντετριμμένον, ή κολοβόν, ή έχον εξόγκωμα, ή ψώραν ξηράν, ή λειχήνας, ταύτα δεν θέλετε προσφέρει εις τον Κύριον, ουδέ θέλετε κάμει εξ αυτών προσφοράν διά πυρός εις τον Κύριον επί του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Μόσχον δε ή πρόβατον, το οποίον έχει τι περιττόν ή κολοβόν, δύνασαι να προσφέρης αυτό διά προσφοράν αυτοπροαίρετον· δι\' ευχήν όμως δεν θέλει είσθαι δεκτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Θλαδίαν, ή εκτεθλιμμένον, ή εκτομίαν, ή ευνουχισμένον, δεν θέλετε προσφέρει εις τον Κύριον· ουδέ θέλετε κάμει τούτο εν τη γη υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Ουδέ εκ χειρός αλλογενούς θέλετε προσφέρει τον άρτον του Θεού σας εκ πάντων τούτων· διότι η διαφθορά αυτών είναι εν αυτοίς· μώμος είναι εν αυτοίς· δεν θέλουσιν είσθαι δεκτά διά σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Όταν μόσχος ή αρνίον ή ερίφιον γεννηθή, τότε θέλει είσθαι επτά ημέρας υποκάτω της μητρός αυτού· από δε της ογδόης ημέρας και επέκεινα θέλει είσθαι δεκτόν εις θυσίαν διά πυρός γινομένην εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Και δάμαλιν ή πρόβατον δεν θέλετε σφάξει αυτό και το παιδίον αυτού εν μιά ημέρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Και όταν προσφέρητε θυσίαν ευχαριστίας εις τον Κύριον, θέλετε προσφέρει αυτήν αυτοπροαιρέτως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Την αυτήν ημέραν θέλει φαγωθή· δεν θέλετε αφήσει ουδέν εξ αυτής έως το πρωΐ. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Θέλετε λοιπόν φυλάττει τας εντολάς μου και θέλετε εκτελεί αυτάς. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Και δεν θέλετε βεβηλόνει το όνομά μου το άγιον· αλλά θέλω αγιάζεσθαι μεταξύ των υιών Ισραήλ. Εγώ είμαι ο Κύριος, ο αγιάζων υμάς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'όστις εξήγαγον υμάς εκ γης Αιγύπτου, διά να ήμαι Θεός υμών. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Αι εορταί του Κυρίου, τας οποίας θέλετε διακηρύξει συγκαλέσεις αγίας, αύται είναι αι εορταί μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Εξ ημέρας θέλεις κάμνει εργασίαν, την δε εβδόμην ημέραν είναι σάββατον αναπαύσεως, συγκάλεσις αγία· ουδεμίαν εργασίαν θέλετε κάμει· είναι σάββατον του Κυρίου εις πάσας τας κατοικίας σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Αύται είναι αι εορταί του Κυρίου, συγκαλέσεις άγιαι, τας οποίας θέλετε διακηρύξει εν τοις καιροίς αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Τον πρώτον μήνα, την δεκάτην τετάρτην του μηνός, εις το δειλινόν, είναι πάσχα του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Και την δεκάτην πέμπτην ημέραν του αυτού μηνός, εορτή των αζύμων εις τον Κύριον· επτά ημέρας άζυμα θέλετε τρώγει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Εν τη πρώτη ημέρα θέλει είσθαι εις εσάς συγκάλεσις αγία· ουδέν έργον δουλευτικόν θέλετε κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Και θέλετε προσφέρει προσφοράν γινομένην διά πυρός εις τον Κύριον επτά ημέρας· εν τη εβδόμη ημέρα είναι συγκάλεσις αγία· ουδέν έργον δουλευτικόν θέλετε κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Όταν εισέλθητε εις την γην, την οποίαν εγώ δίδω εις εσάς, και θερίσητε τον θερισμόν αυτής, τότε θέλετε φέρει εν δράγμα εκ των απαρχών του θερισμού σας προς τον ιερέα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'και θέλει κινήσει το δράγμα ενώπιον του Κυρίου, διά να γείνη δεκτόν διά σάς· την επαύριον του σαββάτου θέλει κινήσει αυτό ο ιερεύς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Και την ημέραν εκείνην, καθ\' ην κινήσητε το δράγμα, θέλετε προσφέρει αρνίον άμωμον ενιαύσιον διά ολοκαύτωμα προς τον Κύριον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'και την εξ αλφίτων προσφοράν αυτού, δύο δέκατα σεμιδάλεως εζυμωμένης μετά ελαίου, εις προσφοράν γινομένην διά πυρός προς τον Κύριον, εις οσμήν ευωδίας· και την σπονδήν αυτού, το τέταρτον του ιν οίνου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Και άρτον ή σίτον εψημένον ή αστάχυα δεν θέλετε φάγει, μέχρι της αυτής ταύτης ημέρας καθ\' ην προσφέρητε το δώρον του Θεού σας· θέλει είσθαι νόμιμον αιώνιον εις τας γενεάς σας κατά πάσας τας κατοικίας σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Και θέλετε αριθμήσει εις εαυτούς από της επαύριον του σαββάτου, αφ\' ης ημέρας προσφέρητε το δράγμα της κινητής προσφοράς, επτά ολοκλήρους εβδομάδας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'μέχρι της επαύριον του εβδόμου σαββάτου θέλετε αριθμήσει πεντήκοντα ημέρας και θέλετε προσφέρει νέαν προσφοράν εξ αλφίτων προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Από των κατοικιών σας θέλετε φέρει εις προσφοράν κινητήν δύο άρτους· δύο δέκατα σεμιδάλεως θέλουσιν είσθαι· ένζυμα θέλουσιν εψηθή· πρωτογεννήματα είναι εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Και θέλετε προσφέρει μετά του άρτου επτά αρνία άμωμα ενιαύσια και ένα μόσχον εκ βοών και δύο κριούς· ολοκαύτωμα θέλουσιν είσθαι εις τον Κύριον μετά της εξ αλφίτων προσφοράς αυτών και μετά των σπονδών αυτών, προσφορά γινομένη διά πυρός εις οσμήν ευωδίας προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Και θέλετε προσφέρει ένα τράγον εξ αιγών εις προσφοράν περί αμαρτίας και δύο αρνία, ενιαύσια εις θυσίαν ειρηνικής προσφοράς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Και θέλει κινήσει αυτά ο ιερεύς μετά του άρτου των πρωτογεννημάτων εις προσφοράν κινητήν ενώπιον του Κυρίου, μετά των δύο αρνίων· άγια θέλουσιν είσθαι εις τον Κύριον διά τον ιερέα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Και θέλετε διακηρύξει την αυτήν εκείνην ημέραν, συγκάλεσιν αγίαν διά σάς· ουδέν έργον δουλευτικόν θέλετε κάμει θέλει είσθαι νόμιμον αιώνιον κατά πάσας τας κατοικίας σας εις τας γενεάς σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Και όταν θερίζητε τον θερισμόν της γης σας, δεν θέλεις θερίσει ολοκλήρως τας άκρας του αγρού σου και τα πίπτοντα του θερισμού σου δεν θέλεις συλλέξει· εις τον πτωχόν και εις τον ξένον θέλεις αφήσει αυτά. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Λάλησον προς τους υιούς Ισραήλ, λέγων, Τον έβδομον μήνα, την πρώτην του μηνός, θέλει είσθαι εις εσάς σάββατον, μνημόσυνον μετά αλαλαγμού σαλπίγγων, συγκάλεσις αγία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ουδέν έργον δουλευτικόν θέλετε κάμει και θέλετε προσφέρει προσφοράν γινομένην διά πυρός προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Και την δεκάτην του εβδόμου τούτου μηνός θέλει είσθαι ημέρα εξιλασμού· συγκάλεσις αγία θέλει είσθαι εις εσάς· και θέλετε ταπεινώσει τας ψυχάς σας και θέλετε προσφέρει προσφοράν γινομένην διά πυρός προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Και ουδεμίαν εργασίαν θέλετε κάμει εις αυτήν ταύτην την ημέραν· διότι είναι ημέρα εξιλασμού, διά να γείνη εξιλέωσις διά σας ενώπιον Κυρίου του Θεού σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Επειδή πάσα ψυχή, ήτις δεν ταπεινωθή εις αυτήν ταύτην την ημέραν, θέλει εξολοθρευθή εκ του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Και πάσα ψυχή, ήτις κάμη οποιανδήποτε εργασίαν εις αυτήν ταύτην την ημέραν, θέλω εξολοθρεύσει την ψυχήν εκείνην εκ μέσου του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ουδεμίαν εργασίαν θέλετε κάμει· θέλει είσθαι νόμιμον αιώνιον εις τας γενεάς σας, κατά πάσας τας κατοικίας σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Σάββατον αναπαύσεως θέλει είσθαι διά σας, και θέλετε ταπεινώσει τας ψυχάς σας την εννάτην του μηνός το εσπέρας· από εσπέρας έως εσπέρας, θέλετε εορτάσει το σάββατόν σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Λάλησον προς τους υιούς Ισραήλ, λέγων, την δεκάτην πέμπτην ημέραν του εβδόμου τούτου μηνός θέλει είσθαι η εορτή των σκηνών επτά ημέρας εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Την πρώτην ημέραν θέλει είσθαι συγκάλεσις αγία· ουδέν έργον δουλευτικόν θέλετε κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Επτά ημέρας θέλετε προσφέρει προσφοράν γινομένην διά πυρός προς τον Κύριον· την ογδόην ημέραν θέλει είσθαι εις εσάς συγκάλεσις αγία, και θέλετε προσφέρει προσφοράν γινομένην διά πυρός προς τον Κύριον· είναι σύναξις επίσημος· ουδέν έργον δουλευτικόν θέλετε κάμει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Αύται είναι αι εορταί του Κυρίου, τας οποίας θέλετε διακηρύξει συγκαλέσεις αγίας, διά να προσφέρητε προσφοράν γινομένην διά πυρός προς τον Κύριον, ολοκαύτωμα και προσφοράν εξ αλφίτων, θυσίαν και σπονδάς, το δι\' εκάστην διωρισμένον εις την ημέραν αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'εκτός των σαββάτων του Κυρίου και εκτός των δώρων σας και εκτός πασών των ευχών σας και εκτός πασών των αυτοπροαιρέτων προσφορών σας, τας οποίας δίδετε εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Και την δεκάτην πέμπτην ημέραν του εβδόμου μηνός, αφού συνάξητε τα γεννήματα της γης, θέλετε εορτάσει την εορτήν του Κυρίου επτά ημέρας· την πρώτην ημέραν θέλει είσθαι ανάπαυσις και την ογδόην ημέραν ανάπαυσις.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Και την πρώτην ημέραν θέλετε λάβει εις εαυτούς καρπόν δένδρου ώραίου, κλάδους φοινίκων και κλάδους δένδρων δασέων και ιτέας από χειμάρρου· και θέλετε ευφρανθή ενώπιον Κυρίου του Θεού σας επτά ημέρας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Και θέλετε εορτάσει αυτήν εορτήν εις τον Κύριον επτά ημέρας του ενιαυτού· νόμιμον αιώνιον θέλει είσθαι εις τας γενεάς σας· τον έβδομον μήνα θέλετε εορτάζει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Εν σκηναίς θέλετε κατοικεί επτά ημέρας· πάντες οι αυτόχθονες Ισραηλίται θέλουσι κατοικεί εν σκηναίς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'διά να γνωρίσωσιν αι γενεαί σας ότι εν σκηναίς κατώκισα τους υιούς Ισραήλ, ότε εξήγαγον αυτούς εκ γης Αιγύπτου· εγώ Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Και εφανέρωσεν ο Μωϋσής τας εορτάς του Κυρίου προς τους υιούς Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Πρόσταξον τους υιούς Ισραήλ να φέρωσι προς σε έλαιον καθαρόν από ελαίας κοπανισμένας διά το φως, διά να καίη ο λύχνος διαπαντός.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Έξωθεν του καταπετάσματος του μαρτυρίου, εν τη σκηνή του μαρτυρίου, θέλει βάλει αυτόν ο Ααρών από εσπέρας έως το πρωΐ ενώπιον του Κυρίου διαπαντός· νόμιμον αιώνιον θέλει είσθαι εις τας γενεάς σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Επί την λυχνίαν την καθαράν θέλει διαθέσει τους λύχνους ενώπιον του Κυρίου πάντοτε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Και θέλεις λάβει σεμίδαλιν και θέλεις εψήσει απ\' αυτής δώδεκα άρτους· δύο δέκατα θέλει είσθαι έκαστος άρτος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Και θέλεις βάλει αυτούς εις δύο σειράς, εξ κατά την σειράν, επί την τράπεζαν την καθαράν ενώπιον του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Και θέλεις βάλει εφ\' εκάστην σειράν λιβάνιον καθαρόν, και θέλει είσθαι επί τον άρτον προς μνημόσυνον, εις προσφοράν γινομένην διά πυρός προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Πάσαν ημέραν σαββάτου θέλει διαθέσει ταύτα διαπαντός ενώπιον του Κυρίου, παρά των υιών Ισραήλ εις διαθήκην αιώνιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Και θέλουσιν είσθαι του Ααρών και των υιών αυτού· και θέλουσι τρώγει αυτά εν τόπω αγίω διότι είναι αγιώτατα εις αυτόν εκ των διά πυρός γινομένων προσφορών του Κυρίου εις νόμιμον αιώνιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Και εξήλθεν υιός γυναικός τινός Ισραηλίτιδος, όστις ήτο υιός ανδρός Αιγυπτίου, μεταξύ των υιών Ισραήλ· και εμάχοντο εν τω στρατοπέδω ο υιός της Ισραηλίτιδος και άνθρωπός τις Ισραηλίτης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Και εβλασφήμησεν ο υιός της γυναικός της Ισραηλίτιδος το όνομα του Κυρίου και κατηράσθη· και έφεραν αυτόν προς τον Μωϋσήν. Και το όνομα της μητρός αυτού ήτο Σελωμείθ, θυγάτηρ του Διβρεί, εκ της φυλής Δαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Και έβαλον αυτόν εις φυλακήν, εωσού φανερωθή εις αυτούς η θέλησις του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Φέρε έξω του στρατοπέδου εκείνον όστις κατηράσθη· και ας θέσωσι πάντες οι ακούσαντες αυτόν τας χείρας αυτών επί την κεφαλήν αυτού, και ας λιθοβολήση αυτόν πάσα η συναγωγή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Και λάλησον προς τους υιούς Ισραήλ, λέγων, Όστις καταρασθή τον Θεόν αυτού, Θέλει βαστάσει την ανομίαν αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'και όστις βλασφημήση το όνομα του Κυρίου, εξάπαντος θέλει θανατωθή· με λίθους θέλει λιθοβολήσει αυτόν πάσα η συναγωγή· άντε ξένος, άντε αυτόχθων, όταν βλασφημήση το όνομα του Κυρίου, θέλει θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Και όστις φονεύση άνθρωπον, εξάπαντος θέλει θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Και όστις θανατώση κτήνος, θέλει ανταποδώσει ζώον αντί ζώου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Και εάν τις κάμη βλάβην εις τον πλησίον αυτού, καθώς έκαμεν, ούτω θέλει γείνει εις αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'σύντριμμα αντί συντρίμματος, οφθαλμόν αντί οφθαλμού, οδόντα αντί οδόντος· καθώς έκαμε βλάβην εις τον άνθρωπον, ούτω θέλει γείνει εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Και όστις θανατώση κτήνος, θέλει ανταποδώσει αυτό· και όστις φονεύσει άνθρωπον, θέλει θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Κρίσις μία θέλει είσθαι εις εσάς· ως εις τον ξένον, ούτω θέλει γίνεσθαι και εις τον αυτόχθονα· διότι εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Και είπεν ο Μωϋσής προς τους υιούς Ισραήλ, και έφεραν έξω του στρατοπέδου εκείνον όστις κατηράσθη και ελιθοβόλησαν αυτόν με λίθους· και οι υιοί Ισραήλ έκαμον καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν εν τω όρει Σινά, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Όταν εισέλθητε εις την γην, την οποίαν εγώ δίδω εις εσάς, τότε η γη θέλει φυλάξει σάββατον εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Εξ έτη θέλεις σπείρει τον αγρόν σου και εξ έτη θέλεις κλαδεύει την άμπελόν σου και θέλεις συνάγει τον καρπόν αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'το δε έβδομον έτος θέλει είσθαι σάββατον αναπαύσεως εις την γην, σάββατον διά τον Κύριον· τον αγρόν σου δεν θέλεις σπείρει και την άμπελόν σου δεν θέλεις κλαδεύσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Δεν θέλεις θερίσει τον βλαστάνοντα αφ\' εαυτού θερισμόν σου και τα σταφύλια της ακλαδεύτου αμπέλου σου δεν θέλεις τρυγήσει ενιαυτός αναπαύσεως θέλει είσθαι εις την γήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'και το σάββατον της γης θέλει είσθαι τροφή εις εσάς· εις σε, και εις τον δούλον σου, και εις την δούλην σου, και εις τον μισθωτόν σου, και εις τον ξένον τον παροικούντα μετά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Και εις τα κτήνη σου, και εις τα ζώα τα εν τη γη σου, θέλει είσθαι όλον το προϊόν αυτού εις τροφήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Και θέλεις αριθμήσει εις σεαυτόν επτά εβδομάδας ετών, επτάκις επτά έτη· και αι ημέραι των επτά εβδομάδων των ετών θέλουσιν είσθαι εις σε τεσσαράκοντα εννέα έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Τότε θέλεις κάμει να ηχήση ο αλαλαγμός της σάλπιγγος την δεκάτην του εβδόμου μηνός· την ημέραν του εξιλασμού θέλετε κάμει να ηχήση η σάλπιγξ καθ\' όλην την γην σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Και θέλετε αγιάσει το πεντηκοστόν έτος και θέλετε διακηρύξει άφεσιν εις την γην προς πάντας τους κατοίκους αυτής· ούτος θέλει είσθαι ενιαυτός αφέσεως εις εσάς· και θέλετε επιστρέψει έκαστος εις το κτήμα αυτού και θέλετε επιστρέψει έκαστος εις την οικογένειαν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ενιαυτός αφέσεως θέλει είσθαι εις εσάς το πεντηκοστόν έτος· δεν θέλετε σπείρει ουδέ θέλετε θερίσει το βλαστάνον αφ\' εαυτού εν αυτώ και δεν θέλετε τρυγήσει την ακλάδευτον άμπελον αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'διότι ενιαυτός αφέσεως είναι άγιος θέλει είσθαι εις εσάς· από της πεδιάδος θέλετε τρώγει το προϊόν αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Εις το έτος τούτο της αφέσεως θέλετε επιστρέψει έκαστος εις το κτήμα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Και εάν πωλήσης τι εις τον πλησίον σου ή αγοράσης παρά του πλησίον σου, ουδείς εξ υμών θέλει δυναστεύσει τον αδελφόν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Κατά τον αριθμόν των ετών μετά την άφεσιν θέλεις αγοράσει παρά του πλησίον σου, και κατά τον αριθμόν των ετών των γεννημάτων θέλει πωλήσει εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Κατά το πλήθος των ετών θέλεις αυξήσει την τιμήν αυτού και κατά την ολιγότητα των ετών θέλεις ελαττώσει την τιμήν αυτού· διότι κατά τον αριθμόν των ετών των γεννημάτων θέλει πωλήσει εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Και δεν θέλετε δυναστεύσει έκαστος τον πλησίον αυτού αλλά θέλεις φοβηθή τον Θεόν σου· διότι εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Και θέλετε κάμνει τα προστάγματά μου και τας κρίσεις μου θέλετε φυλάττει και θέλετε εκτελεί αυτά· και θέλετε κατοικεί ασφαλώς επί της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Και η γη θέλει δίδει τους καρπούς αυτής και θέλετε τρώγει εις χορτασμόν, και θέλετε κατοικεί ασφαλώς επ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Εάν δε είπητε, Τι θέλομεν φάγει το έβδομον έτος, αν ημείς δεν σπείρωμεν μήτε συνάξωμεν τα γεννήματα ημών;');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'τότε θέλω προστάξει την ευλογίαν μου να έλθη εφ\' υμάς το έκτον έτος, και θέλει κάμει τα γεννήματα αυτής διά τρία έτη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Και θέλετε σπείρει το όγδοον έτος, και θέλετε τρώγει από των παλαιών γεννημάτων μέχρι του εννάτου έτους· εωσού έλθωσι τα γεννήματα αυτής θέλετε τρώγει παλαιά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Και η γη δεν θέλει πωλείσθαι εις απαλλοτρίωσιν· διότι ιδική μου είναι η γή· διότι σεις είσθε ξένοι και πάροικοι έμπροσθέν μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Διά τούτο καθ\' όλην την γην της ιδιοκτησίας σας θέλετε συγχωρεί εξαγόρασιν της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Εάν ο αδελφός σου πτωχεύση και πωλήση εκ των κτημάτων αυτού και έλθη ο πλησιέστερος αυτού συγγενής διά να εξαγοράση αυτά, τότε θέλει εξαγοράσει ό,τι επώλησεν ο αδελφός αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Εάν δε ο άνθρωπος δεν έχη συγγενή διά να εξαγοράση αυτά, και ευπόρησε και εύρηκεν ικανά διά να εξαγοράση αυτά,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'τότε ας αριθμήση τα έτη της πωλήσεως αυτού και ας αποδώση το περιπλέον εις τον άνθρωπον, εις τον οποίον επώλησεν αυτά, και ας επιστρέψη εις τα κτήματα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Αλλ\' εάν δεν ήναι ικανός ώστε να δώση την τιμήν εις αυτόν, τότε το πωληθέν θέλει μένει εν τη χειρί του αγοράσαντος αυτό μέχρι του έτους της αφέσεως· και θέλει απελευθερωθή εν τη αφέσει και θέλει επιστρέψει εις τα κτήματα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Και εάν τις πωλήση οίκον οικήσιμον εν πόλει περιτετειχισμένη, τότε δύναται να εξαγοράση αυτόν εντός ενός έτους από της πωλήσεως αυτού· εντός ενός ολοκλήρου έτους δύναται να εξαγοράση αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Αλλ\' εάν δεν εξαγορασθή εωσού συμπληρωθή εις αυτόν ολόκληρον το έτος, τότε ο οίκος ο εν τη περιτετειχισμένη πόλει θέλει κυρωθή διαπαντός εις τον αγοράσαντα, εις τας γενεάς αυτού· δεν θέλει απελευθερωθή εν τη αφέσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Αι οικίαι όμως των χωρίων, τα οποία δεν είναι περιτετειχισμένα, θέλουσι λογίζεσθαι ως οι αγροί της γής· δύνανται να εξαγοράζωνται και θέλουσιν απελευθερούσθαι εν τη αφέσει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Περί δε των πόλεων των Λευϊτών, αι οικίαι των πόλεων της ιδιοκτησίας αυτών δύνανται να εξαγορασθώσιν υπό των Λευϊτών εν παντί καιρώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Και εάν τις αγοράση παρά τινός των Λευϊτών, τότε η εν τη πόλει της ιδιοκτησίας αυτού πωληθείσα οικία θέλει απελευθερωθή εν τη αφέσει· διότι αι οικίαι των πόλεων των Λευϊτών είναι η ιδιοκτησία αυτών μεταξύ των υιών Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Αλλ\' ο αγρός των προαστείων των πόλεων αυτών δεν θέλει πωλείσθαι· διότι είναι παντοτεινή ιδιοκτησία αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Και εάν πτωχεύση ο αδελφός σου και δυστυχήση, τότε θέλεις βοηθήσει αυτόν ως ξένον ή πάροικον, διά να ζήση μετά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Μη λάβης παρ\' αυτού τόκον ή πλεονασμόν· αλλά φοβού τον Θεόν σου· διά να ζη ο αδελφός σου μετά σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Το αργύριόν σου δεν θέλεις δώσει εις αυτόν επί τόκω, και επί πλεονασμώ, δεν θέλεις δώσει τας τροφάς σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Εγώ είμαι Κύριος ο Θεός σας, όστις εξήγαγον σας εκ γης Αιγύπτου, διά να δώσω εις εσάς την γην Χαναάν, ώστε να ήμαι Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Και εάν πτωχεύση ο αδελφός σου πλησίον σου και πωληθή εις σε, δεν θέλεις επιβάλει εις αυτόν δουλείαν δούλου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Ως μισθωτός ή πάροικος θέλει είσθαι πλησίον σου· μέχρι του έτους της αφέσεως θέλει δουλεύει εις σε.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Τότε θέλει εξέλθει από σου αυτός και τα τέκνα αυτού μετ\' αυτού και θέλει επιστρέψει εις την συγγένειαν αυτού και εις την ιδιοκτησίαν την πατρικήν αυτού θέλει επιστρέψει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Διότι δούλοί μου είναι ούτοι, τους το οποίους εξήγαγον εκ γης Αιγύπτου· δεν θέλουσι πωλείσθαι, καθώς πωλείται δούλος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Δεν θέλεις δεσπόζει επ\' αυτόν μετά αυστηρότητος αλλά θέλεις φοβηθή τον Θεόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Ο δε δούλός σου και η δούλη σου, όσους αν έχης, από των εθνών των πέριξ υμών, εκ τούτων θέλετε αγοράζει δούλον και δούλην.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Και εκ των υιών έτι των ξένων των παροικούντων μεταξύ σας, εκ τούτων θέλετε αγοράζει και εκ των συγγενειών αυτών αίτινες είναι μεταξύ σας, όσοι εγεννήθησαν εν τη γη υμών· και θέλουσιν είσθαι εις εσάς εις ιδιοκτησίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Και θέλετε έχει αυτούς κληρονομίαν διά τα τέκνα σας ύστερον από σας, διά να κληρονομήσωσιν αυτούς ως ιδιοκτησίαν· δούλοί σας θέλουσιν είσθαι διαπαντός· πλην επί τους αδελφούς σας, τους υιούς Ισραήλ, δεν θέλετε εξουσιάζει ο εις επί τον άλλον μετά αυστηρότητος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Και όταν ο ξένος και ο παροικών μετά σου πλουτήση, ο δε αδελφός σου ο μετ\' αυτού πτωχεύση και πωληθή εις τον ξένον, τον παροικούντα μετά σου, ή εις την γενεάν της συγγενείας του ξένου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'αφού πωληθή, θέλει εξαγορασθή πάλιν· εις εκ των αδελφών αυτού θέλει εξαγοράσει αυτόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'ή ο θείος αυτού ή ο υιός του θείου αυτού θέλει εξαγοράσει αυτόν, ή εξ αίματος αυτού συγγενής εκ της συγγενείας αυτού θέλει εξαγοράσει αυτόν· ή εάν αυτός ευπόρησε, θέλει εξαγοράσει αυτός εαυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Και θέλει λογαριάσει μετά του αγοραστού αυτού από του έτους, καθ\' ο επωλήθη εις αυτόν, μέχρι του έτους της αφέσεως· και η τιμή της πωλήσεως αυτού θέλει είσθαι κατά τον αριθμόν των ετών· αναλόγως του χρόνου ενός μισθωτού θέλει λογαριασθή εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Εάν δε μένωσι πολλά έτη, αναλόγως τούτων θέλει αποδώσει την τιμήν της εξαγοράς αυτού εκ του αργυρίου δι\' ου ηγοράσθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Και εάν υπολείπωνται ολίγα έτη μέχρι του έτους της αφέσεως, θέλει κάμει λογαριασμόν μετ\' αυτού και κατά τα έτη αυτού θέλει αποδώσει την τιμήν της εξαγοράς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Ως ετήσιος μισθωτός θέλει είσθαι μετ\' αυτού· δεν θέλει δεσπόζει επ\' αυτόν μετά αυστηρότητος ενώπιόν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Και εάν δεν εξαγορασθή κατά τα έτη ταύτα, τότε θέλει απελευθερωθή εις το έτος της αφέσεως, αυτός και τα τέκνα αυτού μετ\' αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Διότι εις εμέ οι υιοί του Ισραήλ είναι δούλοι· δούλοί μου είναι, τους οποίους εξήγαγον εκ γης Αιγύπτου. Εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Δεν θέλετε κάμει εις εαυτούς είδωλα ουδέ γλυπτά, ουδέ θέλετε ανεγείρει άγαλμα εις εαυτούς, ουδέ θέλετε στήσει λίθον εικονόγλυπτον εν τη γη υμών, διά να προσκυνήτε αυτόν· διότι εγώ είμαι Κύριος ο Θεός σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Τα σάββατά μου θέλετε φυλάττει και το αγιαστήριόν μου θέλετε σέβεσθαι. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Εάν περιπατήτε εις τα προστάγματά μου και φυλάττητε τας εντολάς μου και εκτελήτε αυτάς,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'τότε θέλω δώσει τας βροχάς σας εις τους καιρούς αυτών, και η γη θέλει δώσει τα γεννήματα αυτής, και τα δένδρα του αγρού θέλουσι δώσει τον καρπόν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Και το αλώνισμά σας θέλει σας φθάσει μέχρι του τρυγητού, και ο τρυγητός θέλει φθάσει μέχρι του σπορητού· και θέλετε τρώγει τον άρτον σας εις χορτασμόν· και θέλετε κατοικεί ασφαλώς εν τη γη υμών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Και θέλω δώσει ειρήνην εις την γην, και θέλετε πλαγιάζει και ουδείς θέλει σας φοβίζει και θέλω εξολοθρεύσει τα πονηρά θηρία από της γης και μάχαιρα δεν θέλει περάσει διά μέσου της γης σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Και θέλετε διώξει τους εχθρούς σας και θέλουσι πέσει έμπροσθέν σας εν μαχαίρα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'και πέντε από σας θέλουσι διώξει εκατόν, και εκατόν από σας θέλουσι διώξει μυρίους· και οι εχθροί σας θέλουσι πέσει έμπροσθέν σας εν μαχαίρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Και θέλω επιβλέψει εις εσάς και θέλω σας αυξήσει και θέλω σας πληθύνει και θέλω στερεώσει την διαθήκην μου με σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Και θέλετε φάγει παλαιά παλαιών, και θέλετε εκβάλει τα παλαιά απ\' έμπροσθεν των νέων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Και θέλω στήσει την σκηνήν μου μεταξύ σας· και η ψυχή μου δεν θέλει σας βδελυχθή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'και θέλω περιπατεί μεταξύ σας και θέλω είσθαι Θεός σας και σεις θέλετε είσθαι λαός μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Εγώ είμαι Κύριος ο Θεός σας, όστις σας εξήγαγον εκ της γης των Αιγυπτίων, εκ της δουλείας αυτών· και συνέτριψα τους δεσμούς του ζυγού σας και σας έκαμα να περιπατήτε όρθιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Αλλ\' εάν δεν μου υπακούσητε και δεν εκτελήτε πάσας ταύτας τας εντολάς μου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'και εάν καταφρονήσητε τα προστάγματά μου ή εάν η ψυχή σας αποστραφή τας κρίσεις μου, ώστε να μη εκτελήτε πάσας τας εντολάς μου, ώστε να εξουδενώσητε την διαθήκην μου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'και εγώ θέλω κάμει τούτο εις εσάς· θέλω βάλει εφ\' υμάς τρόμον, μαρασμόν, και καύσωνα, τα οποία θέλουσι φθείρει τους οφθαλμούς σας και θέλουσι κατατήκει την ψυχήν· και θέλετε σπείρει τον σπόρον σας εις μάτην, διότι οι εχθροί σας θέλουσι τρώγει αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Και θέλω στήσει το πρόσωπόν μου εναντίον σας, και θέλετε φονευθή έμπροσθεν των εχθρών σας· και εκείνοι, οίτινες σας μισούσι, θέλουσι σας εξουσιάσει και θέλετε φεύγει, ουδενός διώκοντος υμάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Και εάν μέχρι τούτου δεν μου υπακούσητε, θέλω επιβάλει εις εσάς επταπλάσιον τιμωρίαν διά τας αμαρτίας σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Και θέλω συντρίψει την υπερηφανίαν της δυνάμεώς σας· και θέλω κάμει τον ουρανόν σας ως σίδηρον και την γην σας ως χαλκόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'και η δύναμίς σας θέλει αναλωθή εις μάτην· διότι η γη σας δεν θέλει δίδει τα γεννήματα αυτής και τα δένδρα της γης δεν θέλουσι δίδει τον καρπόν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Και εάν πορεύησθε εναντίοι εις εμέ και δεν θέλητε να μου υπακούσητε, θέλω προσθέσει εις εσάς επταπλασίους πληγάς κατά τας αμαρτίας σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Και θέλω αποστείλει εναντίον σας τα θηρία τα άγρια, τα οποία θέλουσι καταφάγει τα τέκνα σας και εξολοθρεύσει τα κτήνη σας και θέλουσι σας κάμει ολιγοστούς· και θέλουσιν ερημωθή αι οδοί σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Και εάν εκ τούτων δεν διορθωθήτε επιστρέφοντες εις εμέ, αλλά πορεύησθε εναντίοι εις εμέ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'τότε θέλω πορευθή και εγώ εναντίος εις εσάς, και θέλω σας παιδεύσει και εγώ επταπλασίως διά τας αμαρτίας σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Και θέλω φέρει εφ\' υμάς μάχαιραν, ήτις θέλει κάμει την εκδίκησιν της διαθήκης μου· και όταν καταφύγητε εις τας πόλεις σας, θέλω στείλει θανατικόν εν μέσω υμών· και θέλετε παραδοθή εις τας χείρας του εχθρού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Και όταν κατασυντρίψω το στήριγμα του άρτου σας, δέκα γυναίκες θέλουσι ψήνει τους άρτους σας εν ενί κλιβάνω, και οι άρτοι σας θέλουσιν αποδοθή εις εσάς με ζύγιον· και θέλετε τρώγει και δεν θέλετε χορταίνει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Εάν δε και διά τούτων δεν μου υπακούσητε, αλλά πορεύησθε εναντίοι εις εμέ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'τότε εγώ θέλω πορευθή εναντίος εις εσάς μετά θυμού και θέλω σας παιδεύσει και εγώ επταπλασίως διά τας αμαρτίας σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Και θέλετε φάγει τας σάρκας των υιών σας και τας σάρκας των θυγατέρων σας θέλετε φάγει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Και θέλω κατεδαφίσει τους υψηλούς τόπους σας και θέλω καταστρέψει τα είδωλά σας και θέλω ρίψει τα πτώματά σας επί τα πτώματα των βδελυρών ειδώλων σας· και θέλει σας βδελυχθή η ψυχή μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Και θέλω καταστήσει τας πόλεις σας ερήμους και θέλω εξερημώσει τα αγιαστήριά σας και δεν θέλω οσφρανθή την οσμήν των ευωδιών σας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'και θέλω εξερημώσει εγώ την γην σας· και θέλουσι θαυμάσει εις τούτο οι εχθροί σας, οι κατοικούντες εν αυτή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Και θέλω σας διασπείρει μεταξύ των εθνών· και θέλω σύρει οπίσω σας μάχαιραν· και η γη σας θέλει μένει έρημος και αι πόλεις σας θέλουσιν είσθαι έρημοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Τότε η γη θέλει απολαύσει τα σάββατα αυτής καθ\' όλον τον καιρόν όσον αυτή μείνη έρημος και σεις εν τη γη των εχθρών σας· τότε θέλει αναπαυθή η γη και θέλει απολαύσει τα σάββατα αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Καθ\' όλον τον καιρόν της ερημώσεως αυτής θέλει αναπαύεσθαι διότι δεν ανεπαύετο εις τα σάββατά σας, ότε κατωκείτε επ\' αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Επί δε τους εναπολειφθέντας από σας θέλω επιφέρει δειλίαν εις την καρδίαν αυτών εν τοις τόποις των εχθρών αυτών· και ήχος φύλλου σειομένου θέλει διώκει αυτούς· και θέλουσι φεύγει, ως φεύγοντες από μαχαίρας και θέλουσι πίπτει, ουδενός διώκοντος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Και θέλουσι πίπτει ο εις επί τον άλλον ως έμπροσθεν μαχαίρας, ουδενός διώκοντος· και δεν θέλετε δυνηθή να σταθήτε έμπροσθεν των εχθρών σας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Και θέλετε απολεσθή μεταξύ των εθνών, και η γη των εχθρών σας θέλει σας καταφάγει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Και οι εναπολειφθέντες από σας θέλουσι φθείρεσθαι διά τας ανομίας αυτών εν τοις τόποις των εχθρών σας· και ότι διά τας ανομίας των πατέρων αυτών θέλουσι φθείρεσθαι μετ\' αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Εάν δε ομολογήσωσι την ανομίαν αυτών και την ανομίαν των πατέρων αυτών διά την παράβασιν αυτών, την οποίαν παρέβησαν εναντίον μου, και διότι επορεύθησαν έτι εναντίοι εις εμέ,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'και εγώ επορεύθην εναντίος εις αυτούς, και έφερα αυτούς εις την γην των εχθρών αυτών· εάν τότε ταπεινωθή η καρδία αυτών η απερίτμητος και δεχθώσι τότε την τιμωρίαν της ανομίας αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'τότε θέλω ενθυμηθή την διαθήκην μου την προς τον Ιακώβ, και την διαθήκην μου την προς τον Ισαάκ, και την διαθήκην μου την προς τον Αβραάμ θέλω ενθυμηθή· και την γην θέλω ενθυμηθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Και η γη θέλει μείνει παρητημένη απ\' αυτών και θέλει απολαύσει τα σάββατα αυτής, μένουσα έρημος αυτών· και αυτοί θέλουσι δεχθή την τιμωρίαν της ανομίας αυτών· διότι κατεφρόνησαν τας κρίσεις μου και διότι η ψυχή αυτών απεστράφη τα προστάγματά μου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Αλλά και ούτως ενώ ευρίσκονται εν τη γη των εχθρών αυτών, δεν θέλω απορρίψει αυτούς, ουδέ θέλω βδελυχθή αυτούς, ώστε να εξολοθρεύσω αυτούς, και να ματαιώσω την διαθήκην μου την προς αυτούς· διότι εγώ είμαι Κύριος ο Θεός αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'αλλά θέλω ενθυμηθή υπέρ αυτών την διαθήκην των πατέρων αυτών, τους οποίους εξήγαγον εκ γης Αιγύπτου, ενώπιον των εθνών, διά να ήμαι Θεός αυτών. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Ταύτα είναι τα προστάγματα και αι κρίσεις και οι νόμοι, τους οποίους έκαμεν ο Κύριος μεταξύ εαυτού και των υιών Ισραήλ επί του όρους Σινά διά χειρός του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Όταν τις κάμη επίσημον ευχήν, συ θέλεις κάμνει την εκτίμησιν των ψυχών προς τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Και η εκτίμησίς σου θέλει είσθαι του μεν αρσενικού, από είκοσι ετών μέχρις εξήκοντα ετών, η εκτίμησίς σου βεβαίως θέλει είσθαι πεντήκοντα σίκλοι αργυρίου, κατά τον σίκλον του αγιαστηρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'εάν δε ήναι θηλυκόν, η εκτίμησίς σου θέλει είσθαι τριάκοντα σίκλοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Εάν δε ήναι από πέντε ετών μέχρις είκοσι, η εκτίμησίς σου θέλει είσθαι του μεν αρσενικού είκοσι σίκλοι, του δε θηλυκού δέκα σίκλοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Εάν δε ήναι από ενός μηνός μέχρι πέντε ετών, η εκτίμησίς σου θέλει είσθαι του μεν αρσενικού πέντε σίκλοι αργυρίου· του δε θηλυκού η εκτίμησίς σου τρεις σίκλοι αργυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Εάν δε από εξήκοντα ετών και επάνω, εάν μεν ήναι αρσενικόν, η εκτίμησίς σου θέλει είσθαι δεκαπέντε σίκλοι εάν δε θηλυκόν, δέκα σίκλοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Και εάν ήναι πτωχότερος της εκτιμήσεώς σου, θέλει παρασταθή έμπροσθεν του ιερέως, και ο ιερεύς θέλει εκτιμήσει αυτόν· κατά την δύναμιν εκείνου όστις έκαμε την ευχήν, ο ιερεύς θέλει εκτιμήσει αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Και εάν η ευχή ήναι κτήνος, εκ των όσα προσφέρονται δώρον προς τον Κύριον, παν ό,τι δίδει τις εκ τούτων εις τον Κύριον θέλει είσθαι άγιον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Δεν θέλει αλλάξει αυτό, ουδέ θέλει αντικαταστήσει καλόν αντί κακού, ή κακόν αντί καλού· εάν δε ποτέ ανταλλάξη κτήνος αντί κτήνους, τότε και αυτό και το αντάλλαγμα αυτού θέλουσιν είσθαι άγια.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Εάν δε ήναι τι κτήνος ακάθαρτον, εκ των όσα δεν προσφέρονται δώρον προς τον Κύριον, τότε θέλει παραστήσει το κτήνος έμπροσθεν του ιερέως·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'και θέλει εκτιμήσει αυτό ο ιερεύς, είτε καλόν είναι είτε κακόν· κατά την εκτίμησίν σου, ω ιερεύ, ούτω θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Και εάν τις θελήση να εξαγοράση αυτό, τότε θέλει προσθέσει το πέμπτον αυτού εις την εκτίμησίν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Και όταν τις αφιερώση την οικίαν αυτού αφιέρωμα εις τον Κύριον, τότε ο ιερεύς θέλει εκτιμήσει αυτήν, είτε καλή είναι είτε κακή· καθώς εκτιμήση αυτήν ο ιερεύς, ούτω θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Και εάν ο αφιερώσας αυτήν θελήση να εξαγοράση την οικίαν αυτού, θέλει προσθέσει το πέμπτον του αργυρίου της εκτιμήσεώς σου εις αυτήν και θέλει είσθαι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Και εάν τις αφιερώση εις τον Κύριον μέρος του αγρού της ιδιοκτησίας αυτού, η εκτίμησίς σου θέλει είσθαι κατά τον σπόρον αυτού· εν χομόρ σπόρου κριθής θέλει εκτιμηθή αντί πεντήκοντα σίκλων αργυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Εάν από του έτους της αφέσεως αφιερώση τον αγρόν αυτού, κατά την εκτίμησίν σου θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Αλλ\' εάν μετά την άφεσιν αφιερώση τον αγρόν αυτού, ο ιερεύς θέλει λογαριάσει εις αυτόν το αργύριον κατά τα επίλοιπα έτη μέχρι του έτους της αφέσεως, και θέλει αφαιρεθή από της εκτιμήσεώς σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Εάν δε ποτέ ο αφιερώσας τον αγρόν θελήση να εξαγοράση αυτόν, θέλει προσθέσει εις αυτόν το πέμπτον του αργυρίου της εκτιμήσεώς σου, και θέλει είσθαι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Και εάν δεν εξαγοράση τον αγρόν ή εάν επώλησε τον αγρόν εις άλλον τινά, δεν θέλει εξαγοράζεσθαι πλέον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Αλλ\' όταν ο αγρός παρέλθη την άφεσιν, θέλει είσθαι άγιος εις τον Κύριον, ως αγρός καθιερωμένος· η κυριότης αυτού θέλει είσθαι του ιερέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Εάν δε αφιερώση τις εις τον Κύριον αγρόν τον οποίον ηγόρασεν, όστις δεν είναι εκ των αγρών της ιδιοκτησίας αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'ο ιερεύς θέλει λογαριάσει εις αυτόν την αξίαν της εκτιμήσεώς σου μέχρι του έτους της αφέσεως· και θέλει δώσει την εκτίμησίν σου την ημέραν εκείνην· είναι άγιον εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Εις το έτος της αφέσεως ο αγρός θέλει αποδοθή εις εκείνον, από του οποίου ηγοράσθη, εις τον έχοντα την κυριότητα της γης.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Και πάσαι αι εκτιμήσεις σου θέλουσιν είσθαι κατά τον σίκλον του αγιαστηρίου· είκοσι γερά θέλει είσθαι ο σίκλος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Πλην το πρωτότοκον μεταξύ των κτηνών, το οποίον ανήκει ως πρωτότοκον εις τον Κύριον, ουδείς θέλει αφιερώσει αυτό· είτε μόσχος είτε αρνίον, του Κυρίου είναι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Και εάν ήναι από ακαθάρτων κτηνών, θέλει εξαγοράσει αυτό κατά την εκτίμησίν σου και θέλει προσθέσει το πέμπτον αυτού επ\' αυτό· ή εάν δεν εξαγοράζηται, θέλει πωληθή κατά την εκτίμησίν σου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Ουδέν όμως καθιέρωμα, το οποίον καθιερώση τις εις τον Κύριον εκ των όσα έχει, από ανθρώπου έως κτήνους και έως αγρού της ιδιοκτησίας αυτού, θέλει πωληθή ουδέ θέλει εξαγορασθή· παν καθιέρωμα είναι αγιώτατον εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Ουδέν καθιέρωμα καθιερωθέν παρά ανθρώπου θέλει εξαγορασθή· εξάπαντος θέλει θανατωθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Και παν δέκατον της γης, είτε εκ του σπόρου της γης είτε εκ του καρπού των δένδρων, του Κυρίου είναι· είναι άγιον εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Και εάν ποτέ θελήση τις να εξαγοράση το δέκατον αυτού, θέλει προσθέσει εις αυτό το πέμπτον αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Και παν δέκατον βοών και προβάτων, παντός ζώου διαβαίνοντος υποκάτωθεν της ράβδου, το δέκατον θέλει είσθαι άγιον εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Δεν θέλει διακρίνει είτε καλόν είναι είτε κακόν ουδέ θέλει αλλάξει αυτό· και εάν ποτέ αλλάξη αυτό, και αυτό και το αντάλλαγμα αυτού θέλουσιν είσθαι άγια· δεν θέλει εξαγορασθή.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Αύται είναι αι εντολαί, τας οποίας προσέταξε Κύριος εις τον Μωϋσήν διά τους υιούς Ισραήλ εν τω όρει Σινά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν εν τη ερήμω Σινά, εν τη σκηνή του μαρτυρίου, την πρώτην του δευτέρου μηνός, εις το δεύτερον έτος αφού εξήλθον εκ γης Αιγύπτου, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Λάβετε το κεφάλαιον πάσης της συναγωγής των υιών Ισραήλ κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, απαριθμούντες κατ\' όνομα παν αρσενικόν κατά κεφαλήν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Από είκοσι ετών και επάνω, πάντας τους δυναμένους εν τω Ισραήλ να εξέλθωσιν εις πόλεμον, συ και ο Ααρών απαριθμήσατε αυτούς κατά τα στρατεύματα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Και με σας θέλει είσθαι εις άνθρωπος αφ\' εκάστης φυλής· έκαστος άρχων του οίκου των πατέρων αυτού θέλει είσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Και ταύτα είναι τα ονόματα των ανδρών οίτινες θέλουσι παρασταθή με σάς· εκ του Ρουβήν, Ελισούρ ο υιός του Σεδιούρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'εκ του Συμεών, Σελουμήλ ο υιός του Σουρισαδαΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'εκ του Ιούδα, Ναασσών ο υιός του Αμμιναδάβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'εκ του Ισσάχαρ, Ναθαναήλ ο υιός του Σουάρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'εκ του Ζαβουλών, Ελιάβ ο υιός του Χαιλών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'εκ των υιών του Ιωσήφ, εκ μεν του Εφραΐμ, Ελισαμά ο υιός του Αμμιούδ· εκ δε του Μανασσή, Γαμαλιήλ ο υιός του Φεδασσούρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'εκ του Βενιαμίν, Αβειδάν ο υιός του Γιδεωνί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'εκ του Δαν, Αχιέζερ ο υιός του Αμμισαδαΐ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'εκ του Ασήρ, Φαγαιήλ ο υιός του Οχράν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'εκ του Γαδ, Ελιασάφ ο υιός του Δεουήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'εκ του Νεφθαλί, Αχιρά ο υιός του Αινάν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ούτοι ήσαν οι εκλεκτοί της συναγωγής, άρχοντες των φυλών των πατέρων αυτών, αρχηγοί των χιλιάδων του Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Ο Μωϋσής λοιπόν και ο Ααρών έλαβον τους άνδρας τούτους τους ονομασθέντας κατ\' όνομα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'και συνεκάλεσαν πάσαν την συναγωγήν, την πρώτην του δευτέρου μηνός, και κατεγράφησαν κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, κατά κεφαλήν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Καθώς προσέταξεν ο Κύριος εις τον Μωϋσήν, ούτως απηρίθμησεν αυτούς εν τη ερήμω Σινά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Και οι υιοί Ρουβήν, του πρωτοτόκου του Ισραήλ, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, κατά κεφαλήν αυτών, παν αρσενικόν από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'οι απαριθμηθέντες εκ της φυλής Ρουβήν ήσαν τεσσαράκοντα εξ χιλιάδες και πεντακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Εκ των υιών Συμεών, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, οι απαριθμηθέντες κατά τον αριθμόν των ονομάτων εξ αυτών, κατά κεφαλήν αυτών, παν αρσενικόν από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'οι απαριθμηθέντες εκ της φυλής Συμεών ήσαν πεντήκοντα εννέα χιλιάδες και τριακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Εκ των υιών Γαδ, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'οι απαριθμηθέντες εκ της φυλής Γαδ ήσαν τεσσαράκοντα πέντε χιλιάδες και εξακόσιοι πεντήκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Εκ των υιών Ιούδα, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'οι απαριθμηθέντες εκ της φυλής Ιούδα ήσαν εβδομήκοντα τέσσαρες χιλιάδες και εξακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Εκ των υιών Ισσάχαρ, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'οι απαριθμηθέντες εκ της φυλής Ισσάχαρ ήσαν πεντήκοντα τέσσαρες χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Εκ των υιών Ζαβουλών, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'οι απαριθμηθέντες εκ της φυλής Ζαβουλών ήσαν πεντήκοντα επτά χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Εκ των υιών Ιωσήφ, εκ μεν των υιών Εφραΐμ, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'οι απαριθμηθέντες εκ της φυλής Εφραΐμ ήσαν τεσσαράκοντα χιλιάδες και πεντακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Εκ των υιών Μανασσή, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'οι απαριθμηθέντες εκ της φυλής Μανασσή ήσαν τριάκοντα δύο χιλιάδες και διακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Εκ των υιών Βενιαμίν, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'οι απαριθμηθέντες εκ της φυλής Βενιαμίν ήσαν τριάκοντα πέντε χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Εκ των υιών Δαν, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'οι απαριθμηθέντες εκ της φυλής Δαν ήσαν εξήκοντα δύο χιλιάδες και επτακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Εκ των υιών Ασήρ, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'οι απαριθμηθέντες εκ της φυλής Ασήρ ήσαν χιλιάδες τεσσαράκοντα μία και πεντακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Εκ των υιών Νεφθαλί, κατά τας γενεάς αυτών, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, κατά τον αριθμόν των ονομάτων, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'οι απαριθμηθέντες εκ της φυλής Νεφθαλί ήσαν πεντήκοντα τρεις χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Ούτοι είναι οι απαριθμηθέντες, τους οποίους απηρίθμησεν ο Μωϋσής και ο Ααρών και οι άρχοντες του Ισραήλ, οι δώδεκα άνδρες· έκαστος ήτο κατά τον οίκον των πατέρων αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Και ήσαν πάντες οι απαριθμηθέντες εκ των υιών Ισραήλ, κατά τους οίκους των πατέρων αυτών, από είκοσι ετών και επάνω, πάντες οι δυνάμενοι μεταξύ του Ισραήλ να εξέλθωσιν εις πόλεμον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'πάντες οι απαριθμηθέντες ήσαν εξακόσιαι τρεις χιλιάδες και πεντακόσιοι πεντήκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Οι Λευΐται όμως, κατά την φυλήν των πατέρων αυτών, δεν απηριθμήθησαν μεταξύ αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Διότι ο Κύριος είχε λαλήσει προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Μόνον την φυλήν του Λευΐ μη απαριθμήσης και το κεφάλαιον αυτών μη λάβης μετά των υιών Ισραήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'αλλά δος εις τους Λευΐτας την επιστασίαν της σκηνής του μαρτυρίου και πάντων των σκευών αυτής και πάντων των ανηκόντων εις αυτήν· ούτοι θέλουσι βαστάζει την σκηνήν και πάντα τα σκεύη αυτής, και ούτοι θέλουσιν υπηρετεί εις αυτήν, και θέλουσι στρατοπεδεύει κύκλω της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Και όταν η σκηνή μέλλη να σηκωθή, οι Λευΐται θέλουσι καταβιβάζει αυτήν· και όταν η σκηνή πρέπη να στηθή, οι Λευΐται θέλουσι στήνει αυτήν· και όστις ξένος πλησιάση, ας θανατόνηται.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Και οι μεν υιοί Ισραήλ θέλουσι στρατοπεδεύει, έκαστος εν τω στρατοπέδω αυτού, και έκαστος πλησίον της σημαίας αυτού κατά τα στρατεύματα αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Οι δε Λευΐται θέλουσι στρατοπεδεύει κύκλω της σκηνής του μαρτυρίου, διά να μη ήναι οργή επί την συναγωγήν των υιών Ισραήλ· και οι Λευΐται θέλουσι φυλάττει τας φυλακάς της σκηνής του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Και έκαμον οι υιοί Ισραήλ κατά πάντα όσα προσέταξεν ο Κύριος εις τον Μωϋσήν· ούτως έκαμον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Ας στρατοπεδεύωσιν οι υιοί Ισραήλ, έκαστος πλησίον της σημαίας αυτού, μετά του σημείου του οίκου των πατέρων αυτών· κύκλω της σκηνής του μαρτυρίου κατέναντι θέλουσι στρατοπεδεύει.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Και οι μεν προς ανατολάς στρατοπεδεύοντες θέλουσιν είσθαι οι εκ της σημαίας του στρατοπέδου Ιούδα, κατά τα τάγματα αυτών· και ο άρχων των υιών Ιούδα θέλει είσθαι Ναασσών ο υιός του Αμμιναδάβ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν εβδομήκοντα τέσσαρες χιλιάδες και εξακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Και οι στρατοπεδεύοντες πλησίον αυτού θέλουσιν είσθαι η φυλή Ισσάχαρ· και ο άρχων των υιών Ισσάχαρ θέλει είσθαι Ναθαναήλ ο υιός του Σουάρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'το στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν πεντήκοντα τέσσαρες χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Έπειτα η φυλή Ζαβουλών· και ο άρχων των υιών Ζαβουλών θέλει είσθαι Ελιάβ ο υιός του Χαιλών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν πεντήκοντα επτά χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Πάντες οι απαριθμηθέντες εν τω στρατοπέδω Ιούδα ήσαν εκατόν ογδοήκοντα εξ χιλιάδες και τετρακόσιοι, κατά τα τάγματα αυτών· ούτοι θέλουσι σηκόνεσθαι πρώτοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Προς μεσημβρίαν δε θέλει είσθαι σημαία του στρατοπέδου Ρουβήν κατά τα τάγματα αυτών· και ο άρχων των υιών Ρουβήν θέλει είσθαι Ελισούρ ο υιός του Σεδιούρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν τεσσαράκοντα εξ χιλιάδες και πεντακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Και οι στρατοπεδεύοντες πλησίον αυτού θέλουσιν είσθαι η φυλή Συμεών· και ο άρχων των υιών Συμεών θέλει είσθαι Σελουμιήλ ο υιός του Σουρισαδαΐ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν πεντήκοντα εννέα χιλιάδες και τριακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Έπειτα η φυλή Γάδ· και ο άρχων των υιών Γαδ θέλει είσθαι Ελιασάφ ο υιός του Δεουήλ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν τεσσαράκοντα πέντε χιλιάδες και εξακόσιοι πεντήκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Πάντες οι απαριθμηθέντες εν τω στρατοπέδω Ρουβήν ήσαν χιλιάδες εκατόν πεντήκοντα μία και τετρακόσιοι πεντήκοντα, κατά τα τάγματα αυτών· ούτοι θέλουσι σηκόνεσθαι δεύτεροι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Έπειτα θέλει σηκόνεσθαι η σκηνή του μαρτυρίου, το στρατόπεδον των Λευϊτών εν τω μέσω των στρατοπέδων· καθώς εστρατοπέδευσαν, ούτω θέλουσι σηκόνεσθαι έκαστος εις την τάξιν αυτού πλησίον της σημαίας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Προς δυσμάς δε θέλει είσθαι η σημαία του στρατοπέδου του Εφραΐμ κατά τα τάγματα αυτών· και ο άρχων των υιών Εφραΐμ θέλει είσθαι Ελισαμά ο υιός του Αμμιούδ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν τεσσαράκοντα χιλιάδες και πεντακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Και πλησίον αυτού η φυλή Μανασσή· και ο άρχων των υιών Μανασσή θέλει είσθαι Γαμαλιήλ ο υιός του Φεδασσούρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν τριάκοντα δύο χιλιάδες και διακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Έπειτα η φυλή Βενιαμίν· και ο άρχων των υιών Βενιαμίν θέλει είσθαι Αβειδάν ο υιός του Γιδεωνί·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν τριάκοντα πέντε χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Πάντες οι απαριθμηθέντες του στρατοπέδου Εφραΐμ ήσαν εκατόν οκτώ χιλιάδες και εκατόν, κατά τα τάγματα αυτών· ούτοι θέλουσι σηκόνεσθαι τρίτοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Προς βορράν δε θέλει είσθαι η σημαία του στρατοπέδου Δαν, κατά τα τάγματα αυτών· και ο άρχων των υιών Δαν θέλει είσθαι Αχιέζερ ο υιός του Αμμισαδαΐ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν εξήκοντα δύο χιλιάδες και επτακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Και οι στρατοπεδεύοντες πλησίον αυτού θέλουσιν είσθαι η φυλή Ασήρ· και ο άρχων των υιών Ασήρ θέλει είσθαι Φαγαιήλ ο υιός του Οχράν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν χιλιάδες τεσσαράκοντα μία και πεντακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Έπειτα η φυλή Νεφθαλί· και ο άρχων των υιών Νεφθαλί θέλει είσθαι Αχιρά ο υιός του Αινάν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'το δε στράτευμα αυτού και οι απαριθμηθέντες αυτών ήσαν πεντήκοντα τρεις χιλιάδες και τετρακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Πάντες οι απαριθμηθέντες του στρατοπέδου Δαν ήσαν εκατόν πεντήκοντα επτά χιλιάδες και εξακόσιοι ούτοι θέλουσι σηκόνεσθαι έσχατοι κατά τας σημαίας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ούτοι είναι οι απαριθμηθέντες εκ των υιών Ισραήλ κατά τους οίκους των πατέρων αυτών· πάντες οι απαριθμηθέντες εν τοις στρατοπέδοις κατά τα τάγματα αυτών ήσαν εξακόσιαι τρεις χιλιάδες και πεντακόσιοι πεντήκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Οι δε Λευΐται δεν συνηριθμήθησαν μεταξύ των υιών Ισραήλ, καθώς προσέταξε Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Και έκαμον οι υιοί Ισραήλ κατά πάντα όσα προσέταξε Κύριος εις τον Μωϋσήν· ούτως εστρατοπέδευσαν κατά τας σημαίας αυτών και ούτως εσηκώθησαν έκαστος κατά τας συγγενείας αυτού, κατά τους οίκους των πατέρων αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Αύται δε είναι αι γενεαί του Ααρών και του Μωϋσέως, την ημέραν καθ\' ην ελάλησεν ο Κύριος προς τον Μωϋσήν επί του όρους Σινά.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Και ταύτα είναι τα ονόματα των υιών του Ααρών· Ναδάβ ο πρωτότοκος και Αβιούδ, Ελεάζαρ και Ιθάμαρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ταύτα είναι τα ονόματα των υιών του Ααρών, των ιερέων των κεχρισμένων, οίτινες καθιερώθησαν διά να ιερατεύωσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Απέθανε δε ο Ναδάβ και ο Αβιούδ ενώπιον του Κυρίου, ενώ προσέφερον πυρ ξένον ενώπιον του Κυρίου εν τη ερήμω Σινά, και τέκνα δεν είχον· και ιεράτευσεν ο Ελεάζαρ και ο Ιθάμαρ ενώπιον Ααρών του πατρός αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Φέρε την φυλήν του Λευΐ και παράστησον αυτούς έμπροσθεν Ααρών του ιερέως, διά να υπηρετώσιν εις αυτόν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Και θέλουσι φυλάττει τας φυλακάς αυτού και τας φυλακάς πάσης της συναγωγής έμπροσθεν της σκηνής του μαρτυρίου, εκτελούντες τας υπηρεσίας της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Και θέλουσι φυλάττει πάντα τα σκεύη της σκηνής του μαρτυρίου και τας φυλακάς των υιών Ισραήλ, εκτελούντες τας υπηρεσίας της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Και θέλεις δώσει τους Λευΐτας εις τον Ααρών και εις τους υιούς αυτού· ούτοι είναι δεδομένοι δώρον εις αυτόν εκ των υιών Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Τον δε Ααρών και τους υιούς αυτού θέλεις καταστήσει εις το να εκτελώσι τα της ιερατείας αυτών· όστις δε ξένος πλησιάση θέλει θανατόνεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Ιδού, εγώ έλαβον τους Λευΐτας εκ μέσου των υιών Ισραήλ, αντί παντός πρωτοτόκου διανοίγοντος μήτραν εκ των υιών Ισραήλ· και θέλουσιν είσθαι οι Λευΐται εμού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Διότι παν πρωτότοκον είναι εμού· επειδή καθ\' ην ημέραν επάταξα παν πρωτότοκον εν γη Αιγύπτου, ηγίασα εις εμαυτόν παν πρωτότοκον εν τω Ισραήλ, από ανθρώπου έως κτήνους· εμού θέλουσιν είσθαι. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Και ελάλησε Κύριος προς τον Μωϋσήν εν τη ερήμω Σινά, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Απαρίθμησον τους υιούς Λευΐ κατά τους οίκους των πατέρων αυτών, κατά τας συγγενείας αυτών· παν αρσενικόν από ενός μηνός και επάνω θέλεις απαριθμήσει αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Και απηρίθμησεν αυτούς ο Μωϋσής, κατά τον λόγον του Κυρίου, ως προσετάχθη.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Ήσαν δε ούτοι οι υιοί Λευΐ κατά τα ονόματα αυτών· Γηρσών, και Καάθ, και Μεραρί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Και ταύτα ήσαν τα ονόματα των υιών Γηρσών, κατά τας συγγενείας αυτών· Λιβνί, και Σεμεΐ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Και οι υιοί Καάθ, κατά τας συγγενείας αυτών, Αμράμ, και Ισαάρ, Χεβρών, και Οζιήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Και οι υιοί Μεραρί, κατά τας συγγενείας αυτών, Μααλί, και Μουσί. Αύται είναι αι συγγένειαι των Λευϊτών, κατά τους οίκους των πατέρων αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Εκ του Γηρσών ήτο η συγγένεια του Λιβνί, και η συγγένεια του Σεμεΐ· αύται είναι αι συγγένειαι των Γηρσωνιτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Οι απαριθμηθέντες αυτών κατά τον αριθμόν πάντων των αρσενικών από ενός μηνός και επάνω, οι απαριθμηθέντες αυτών ήσαν επτά χιλιάδες και πεντακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Αι συγγένειαι των Γηρσωνιτών θέλουσι στρατοπεδεύει όπισθεν της σκηνής προς δυσμάς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Και ο άρχων του πατρικού οίκου των Γηρσωνιτών θέλει είσθαι Ελιασάφ ο υιός του Λαήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Και η φυλακή των υιών Γηρσών εν τη σκηνή του μαρτυρίου θέλει είσθαι η σκηνή και η σκέπη το κάλυμμα αυτής και το καταπέτασμα της θύρας της σκηνής του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'και τα παραπετάσματα της αυλής και το καταπέτασμα της θύρας της αυλής, τα οποία είναι διά την σκηνήν και διά το θυσιαστήριον κύκλω, και τα σχοινία αυτής διά πάσας τας υπηρεσίας αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Και εκ του Καάθ ήτο η συγγένεια των Αμραμιτών και η συγγένεια των Ισααριτών και η συγγένεια των Χεβρωνιτών και η συγγένεια των Οζιηλιτών· αύται είναι αι συγγένειαι των Κααθιτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Πάντα τα αρσενικά, από ενός μηνός και επάνω ήσαν κατά τον αριθμόν οκτώ χιλιάδες και εξακόσιοι, οίτινες εφύλαττον τας φυλακάς του αγιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Αι συγγένειαι των υιών Καάθ θέλουσι στρατοπεδεύει εις τα πλάγια της σκηνής προς μεσημβρίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Και ο άρχων του πατρικού οίκου των συγγενειών των Κααθιτών θέλει είσθαι Ελισαφάν ο υιός του Οζιήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Και η φυλακή αυτών θέλει είσθαι η κιβωτός, και η τράπεζα, και η λυχνία, και τα θυσιαστήρια, και τα σκεύη του αγιαστηρίου διά των οποίων λειτουργούσι, και το καταπέτασμα και πάντα τα προς υπηρεσίαν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Και Ελεάζαρ ο υιός Ααρών του ιερέως θέλει είσθαι αρχηγός επί των αρχηγών των Λευϊτών, έχων την επιστασίαν των φυλαττόντων τας φυλακάς του αγιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Εκ του Μεραρί ήτο η συγγένεια των Μααλιτών και η συγγένεια των Μουσιτών· αύται είναι αι συγγένειαι του Μεραρί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Και οι απαριθμηθέντες αυτών κατά τον αριθμόν πάντων των αρσενικών από ενός μηνός και επάνω ήσαν εξ χιλιάδες και διακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Και ο άρχων του πατρικού οίκου των συγγενειών του Μεραρί ήτο Σουρήλ ο υιός του Αβιχαίλ· ούτοι θέλουσι στρατοπεδεύει εις τα πλάγια της σκηνής προς βορράν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Και υπό την επιστασίαν της φυλακής των υιών Μεραρί θέλουσιν είσθαι αι σανίδες της σκηνής και οι μοχλοί αυτής και οι στύλοι αυτής και τα υποβάσια αυτής, και πάντα τα σκεύη αυτής, και πάντα τα προς υπηρεσίαν αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'και οι στύλοι της αυλής κύκλω και τα υποβάσια αυτών και οι πάσσαλοι αυτών, και τα σχοινία αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Οι δε στρατοπεδεύοντες κατά πρόσωπον της σκηνής προς ανατολάς, κατέναντι της σκηνής του μαρτυρίου κατά ανατολάς, θέλουσιν είσθαι Μωϋσής και Ααρών και οι υιοί αυτού, φυλάττοντες τας φυλακάς του αγιαστηρίου αντί των φυλακών των υιών Ισραήλ· και όστις ξένος πλησιάση θέλει θανατόνεσθαι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Πάντες οι απαριθμηθέντες των Λευϊτών, τους οποίους απηρίθμησεν ο Μωϋσής και ο Ααρών διά προσταγής του Κυρίου κατά τας συγγενείας αυτών, πάντα τα αρσενικά από ενός μηνός και επάνω, ήσαν είκοσι δύο χιλιάδες.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Και είπε Κύριος προς τον Μωϋσήν, Απαρίθμησον πάντα τα πρωτότοκα αρσενικά των υιών Ισραήλ, από ενός μηνός και επάνω, και λάβε τον αριθμόν των ονομάτων αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Και θέλεις λάβει τους Λευΐτας διά εμέ, εγώ είμαι ο Κύριος αντί πάντων των πρωτοτόκων των υιών Ισραήλ· και τα κτήνη των Λευϊτών αντί πάντων των πρωτοτόκων των κτηνών των υιών Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Και απηρίθμησεν ο Μωϋσής, καθώς προσέταξεν εις αυτόν ο Κύριος, πάντα τα πρωτότοκα των υιών Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Και πάντα τα πρωτότοκα αρσενικά απαριθμηθέντα κατ\' όνομα από ενός μηνός και επάνω, κατά την απαρίθμησιν αυτών ήσαν είκοσι δύο χιλιάδες διακόσια εβδομήκοντα τρία.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Λάβε τους Λευΐτας αντί πάντων των πρωτοτόκων των υιών Ισραήλ και τα κτήνη των Λευϊτών αντί των κτηνών αυτών· και οι Λευΐται θέλουσιν είσθαι εμού. Εγώ είμαι ο Κύριος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Και διά εξαγοράν των διακοσίων εβδομήκοντα τριών εκ των πρωτοτόκων των υιών Ισραήλ, οίτινες υπερβαίνουσι τον αριθμόν των Λευϊτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'θέλεις λάβει ανά πέντε σίκλους κατά κεφαλήν, κατά τον σίκλον τον άγιον θέλεις λάβει αυτούς· ο σίκλος είναι είκοσι γερά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'και θέλεις δώσει το αργύριον της εξαγοράς του περισσεύοντος αριθμού αυτών εις τον Ααρών και εις τους υιούς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Και έλαβεν ο Μωϋσής το αργύριον της εξαγοράς των υπερβαινόντων τον αριθμόν των εξαγορασθέντων εις ανταλλαγήν των Λευϊτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'παρά των πρωτοτόκων των υιών Ισραήλ έλαβε το αργύριον, χιλίους τριακοσίους εξήκοντα πέντε σίκλους, κατά τον σίκλον τον άγιον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'και έδωκεν ο Μωϋσής το αργύριον της εξαγοράς των υπερβαινόντων εις τον Ααρών και εις τους υιούς αυτού, κατά τον λόγον του Κυρίου, καθώς προσέταξε Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Λάβε το κεφάλαιον των υιών Καάθ εκ μέσου των υιών Λευΐ, κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'από τριάκοντα ετών και επάνω έως πεντήκοντα ετών, πάντων των εισερχομένων εις το τάγμα διά να κάμνωσιν εργασίας εν τη σκηνή του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Αύτη θέλει είσθαι η υπηρεσία των υιών Καάθ εν τη σκηνή του μαρτυρίου· τα άγια των αγίων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Και όταν σηκόνηται το στρατόπεδον, θέλουσιν έρχεσθαι ο Ααρών και οι υιοί αυτού και θέλουσι καταβιβάσει το καλυπτήριον καταπέτασμα και θέλουσι σκεπάζει δι\' αυτού την κιβωτόν του μαρτυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'και θέλουσι βάλει επ\' αυτήν κάλυμμα εκ δερμάτων θώων και επάνωθεν θέλουσιν εφαπλώσει ύφασμα όλον κυανούν και θέλουσι διαπεράσει τους μοχλούς αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Και επί της τραπέζης της προθέσεως θέλουσιν εφαπλώσει ύφασμα όλον κυανούν και θέλουσι βάλει επ\' αυτήν τους δίσκους, και τα θυμιαματοδόχα, και τα λεκάνια, και τα σπονδεία, διά να σπένδωσι· και οι παντοτεινοί άρτοι θέλουσιν είσθαι επ\' αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'και θέλουσιν εφαπλώσει επ\' αυτά ύφασμα κόκκινον και τούτο θέλουσι σκεπάσει διά καλύμματος εκ δερμάτων θώων και θέλουσι διαπεράσει τους μοχλούς αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Και θέλουσι λάβει ύφασμα κυανούν, και θέλουσι περισκεπάσει την λυχνίαν του φωτός, και τους λύχνους αυτής, και τα λυχνοψάλιδα αυτής, και τα υποθέματα αυτής, και πάντα τα ελαιοδόχα αγγεία αυτής, διά των οποίων εκτελούσι τας υπηρεσίας αυτής·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'και θέλουσι θέσει αυτήν μετά πάντων των σκευών αυτής εντός καλύμματος εκ δερμάτων θώων και θέλουσιν επιθέσει αυτήν επί τους μοχλούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Επί δε το θυσιαστήριον το χρυσούν θέλουσιν εφαπλώσει ύφασμα κυανούν και τούτο θέλουσι σκεπάσει διά καλύμματος εκ δερμάτων θώων και θέλουσι διαπεράσει τους μοχλούς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'και θέλουσι λάβει πάντα τα σκεύη της υπηρεσίας, διά των οποίων υπηρετούσιν εις τα άγια, και βάλει εις ύφασμα κυανούν και θέλουσι σκεπάσει αυτά διά καλύμματος εκ δερμάτων θώων και επιθέσει εις μοχλούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Και θέλουσι καθαρίσει το θυσιαστήριον από της στάκτης, και θέλουσι περισκεπάσει αυτό διά υφάσματος πορφυρού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'και θέλουσι βάλει επ\' αυτό πάντα τα σκεύη αυτού, διά των οποίων εκτελούσι τας υπηρεσίας αυτού, τα θυμιατήρια, τας κρεάγρας, και τα πτυάρια, και τας λεκάνας· πάντα τα σκεύη του θυσιαστηρίου, και θέλουσιν εφαπλώσει επ\' αυτό κάλυμμα εκ δερμάτων θώων και διαπεράσει τους μοχλούς αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Και αφού τελειώσωσιν ο Ααρών και οι υιοί αυτού να περισκεπάζωσι τα άγια και πάντα τα σκεύη τα άγια, όταν μέλλη να σηκωθή το στρατόπεδον, τότε θέλουσι πλησιάσει οι υιοί του Καάθ διά να βαστάσωσιν αυτά· και δεν θέλουσιν εγγίσει τα άγια, διά να μη αποθάνωσι· ταύτα είναι τα όσα θέλουσι βαστάζει οι υιοί του Καάθ εν τη σκηνή του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Και η επιστασία του Ελεάζαρ υιού του Ααρών του ιερέως θέλει είσθαι το έλαιον του φωτός, και το ευώδες θυμίαμα, και η καθημερινή εξ αλφίτων προσφορά, και το έλαιον του χρίσματος, η επιστασία πάσης της σκηνής, και πάντων των εν αυτή, του αγιαστηρίου, και πάντων των σκευών αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Και ελάλησε Κύριος προς τον Μωϋσήν και προς τον Ααρών, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Μη εξολοθρεύσητε την φυλήν των συγγενειών των Κααθιτών εκ μέσου των Λευϊτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'αλλά τούτο κάμετε εις αυτούς, διά να ζήσωσι και μη αποθάνωσι προσεγγίζοντες εις τα άγια των αγίων· ο Ααρών και οι υιοί αυτού ας εισέρχωνται και ας διορίζωσιν αυτούς έκαστον εις το έργον αυτού και εις το φορτίον αυτού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'ας μη εισέρχωνται όμως να ίδωσιν, όταν περισκεπάζωνται τα άγια, διά να μη αποθάνωσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Λάβε το κεφάλαιον και των υιών Γηρσών, κατά τους οίκους των πατέρων αυτών, κατά τας συγγενείας αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'από τριάκοντα ετών και επάνω έως πεντήκοντα ετών θέλεις απαριθμήσει αυτούς, πάντας τους εισερχομένους εις το τάγμα, διά να κάμνωσιν εργασίας εν τη σκηνή του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Αύτη είναι η υπηρεσία των συγγενειών των Γηρσωνιτών, να υπηρετώσι και να βαστάζωσι·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'θέλουσι λοιπόν βαστάζει τα παραπετάσματα της σκηνής και την σκηνήν του μαρτυρίου, το κάλυμμα αυτής και το κάλυμμα το εκ δερμάτων θώων το επάνωθεν αυτής και το καταπέτασμα της θύρας της σκηνής του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'και τα παραπετάσματα της αυλής και το καταπέτασμα της θύρας της πύλης της αυλής, τα οποία είναι διά την σκηνήν, και διά το θυσιαστήριον κύκλω, και τα σχοινία αυτών και πάντα τα σκεύη της υπηρεσίας αυτών και πάντα τα χρησιμεύοντα εις αυτά· ούτω θέλουσιν υπηρετεί.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Κατά προσταγήν του Ααρών και των υιών αυτού θέλουσι γίνεσθαι πάσαι αι υπηρεσίαι των υιών των Γηρσωνιτών, εις πάντα τα φορτία αυτών και εις πάσας τας υπηρεσίας αυτών· και σεις θέλετε διορίζει εις αυτούς πάντα όσα οφείλουσι να βαστάζωσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Αύτη είναι η υπηρεσία των συγγενειών των υιών των Γηρσωνιτών εν τη σκηνή του μαρτυρίου· και η φυλακή αυτών θέλει είσθαι υπό την επιστασίαν του Ιθάμαρ υιού του Ααρών του ιερέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Θέλεις απαριθμήσει και τους υιούς του Μεραρί κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'από τριάκοντα ετών και επάνω έως πεντήκοντα ετών θέλεις απαριθμήσει αυτούς πάντας τους εισερχομένους εις το τάγμα, διά να κάμνωσιν εργασίας εν τη σκηνή του μαρτυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Και ταύτα είναι, τα οποία οφείλουσι να βαστάζωσι καθ\' όλην την υπηρεσίαν αυτών εν τη σκηνή του μαρτυρίου· αι σανίδες της σκηνής και οι μοχλοί αυτής και οι στύλοι αυτής, και τα υποβάσια αυτής,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'και οι στύλοι της αυλής κύκλω και τα υποβάσια αυτών και οι πάσσαλοι αυτών και τα σχοινία αυτών, μετά πάντων των σκευών αυτών και πάντα τα προς υπηρεσίαν αυτών· και θέλετε διορίσει κατ όνομα τα σκεύη τα οποία οφείλουσι να βαστάζωσιν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Αύτη είναι η υπηρεσία των συγγενειών των υιών Μεραρί, καθ\' όλην την υπηρεσίαν αυτών εν τη σκηνή του μαρτυρίου, υπό την επιστασίαν του Ιθάμαρ υιού του Ααρών του ιερέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Ο Μωϋσής λοιπόν και ο Ααρών και οι άρχοντες της συναγωγής απηρίθμησαν τους υιούς των Κααθιτών κατά τας συγγενείας αυτών και κατά τους οίκους των πατέρων αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'από τριάκοντα ετών και επάνω έως πεντήκοντα ετών, πάντας τους εισερχομένους εις το τάγμα, διά να κάμνωσιν εργασίας εν τη σκηνή του μαρτυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'και οι απαριθμηθέντες αυτών κατά τας συγγενείας αυτών ήσαν δύο χιλιάδες επτακόσιοι πεντήκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ούτοι είναι οι απαριθμηθέντες των συγγενειών των Κααθιτών, πάντες οι υπηρετούντες εν τη σκηνή του μαρτυρίου, τους οποίους απηρίθμησαν ο Μωϋσής και ο Ααρών, καθώς προσέταξε Κύριος διά χειρός του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Οι δε απαριθμηθέντες των υιών Γηρσών κατά τας συγγενείας αυτών και κατά τους οίκους των πατέρων αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'από τριάκοντα ετών και επάνω έως πεντήκοντα ετών, πάντες οι εισερχόμενοι εις το τάγμα διά να κάμνωσιν εργασίας εν τη σκηνή του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'οι απαριθμηθέντες αυτών κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών, ήσαν δύο χιλιάδες εξακόσιοι τριάκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ούτοι είναι οι απαριθμηθέντες των συγγενειών των υιών Γηρσών, πάντες οι υπηρετούντες εν τη σκηνή του μαρτυρίου, τους οποίους απηρίθμησαν ο Μωϋσής και ο Ααρών κατά την προσταγήν του Κυρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Οι δε απαριθμηθέντες των συγγενειών των υιών Μεραρί κατά τας συγγενείας αυτών, κατά τους οίκους των πατέρων αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'από τριάκοντα ετών και επάνω έως πεντήκοντα ετών, πάντες οι εισερχόμενοι εις το τάγμα διά να κάμνωσιν εργασίας εν τη σκηνή του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'οι απαριθμηθέντες αυτών κατά τας συγγενείας αυτών ήσαν τρεις χιλιάδες και διακόσιοι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ούτοι είναι οι απαριθμηθέντες των συγγενειών των υιών Μεραρί, τους οποίους απηρίθμησαν ο Μωϋσής και ο Ααρών, καθώς προσέταξε Κύριος διά χειρός του Μωϋσέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Πάντες οι απαριθμηθέντες των Λευϊτών, τους οποίους απηρίθμησαν ο Μωϋσής και ο Ααρών και οι άρχοντες του Ισραήλ, κατά τας συγγενείας αυτών και κατά τους οίκους των πατέρων αυτών,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'από τριάκοντα ετών και επάνω έως πεντήκοντα ετών, πάντες οι εισερχόμενοι διά να υπηρετώσιν υπηρεσίαν και να βαστάζωσι το φορτίον εν τη σκηνή του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'οι απαριθμηθέντες αυτών ήσαν οκτώ χιλιάδες πεντακόσιοι ογδοήκοντα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Απηριθμήθησαν καθώς προσέταξεν ο Κύριος διά χειρός του Μωϋσέως, έκαστος κατά την υπηρεσίαν αυτού και κατά το φορτίον αυτού. Ούτως απηριθμήθησαν υπ\' αυτού, καθώς προσέταξε Κύριος εις τον Μωϋσήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Πρόσταξον τους υιούς Ισραήλ να αποπέμψωσιν από του στρατοπέδου πάντα λεπρόν και πάντα γονόρροιον και πάντα μεμολυσμένον διά νεκρόν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'αρσενικόν τε και θηλυκόν αποπέμψατε· έξω του στρατοπέδου αποπέμψατε αυτούς, διά να μη μολύνωσι τα στρατόπεδα αυτών, εν μέσω των οποίων εγώ κατοικώ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Και έκαμον ούτως οι υιοί Ισραήλ και απέπεμψαν αυτούς έξω του στρατοπέδου· καθώς είπεν ο Κύριος προς τον Μωϋσήν, ούτως έκαμον οι υιοί Ισραήλ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Ειπέ προς τους υιούς Ισραήλ, Όταν ανήρ ή γυνή κάμη τι εκ των αμαρτημάτων των ανθρωπίνων, πράττων παράβασιν εις τον Κύριον, και αμαρτήση η ψυχή εκείνη,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'τότε θέλει εξομολογηθή την αμαρτίαν αυτού, την οποίαν έπραξε, και θέλει αποδώσει το αδίκημα αυτού μετά του κεφαλαίου τούτου και εις αυτό θέλει προσθέσει το πέμπτον αυτού και θέλει δώσει αυτό εις όντινα ηδίκησεν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Εάν δε ο άνθρωπος δεν έχη συγγενή διά να αποδοθή εις αυτόν το αδίκημα, ας αποδίδεται το αδίκημα εις τον Κύριον προς τον ιερέα, εκτός του κριού της εξιλεώσεως, διά του οποίου θέλει γείνει εξιλέωσις περί αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Και πάσα υψουμένη προσφορά εκ πάντων των ηγιασμένων πραγμάτων των υιών Ισραήλ, την οποίαν προσφέρουσιν εις τον ιερέα, θέλει είσθαι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Αυτού λοιπόν θέλουσιν είσθαι τα αγιαζόμενα παντός ανθρώπου· ό,τι έκαστος δίδη εις τον ιερέα, θέλει είσθαι αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Εάν ανθρώπου τινός η γυνή παραδρομήση και αμαρτήση εναντίον αυτού,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'και συγκοιμηθή τις μετ\' αυτής, και λανθάση τους οφθαλμούς του ανδρός αυτής και κρυφθή, και αυτή μολυνθή και μάρτυς δεν υπάρχη κατ\' αυτής και δεν πιασθή,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'και επέλθη εις αυτόν πνεύμα ζηλοτυπίας και ζηλοτυπήση την γυναίκα αυτού και αυτή ήναι μεμολυσμένη· ή εάν επέλθη εις αυτόν το πνεύμα της ζηλοτυπίας, και ζηλοτυπήση την γυναίκα αυτού και αυτή δεν ήναι μεμολυσμένη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'τότε θέλει φέρει ο άνθρωπος την γυναίκα αυτού προς τον ιερέα και θέλει προσφέρει το δώρον αυτής υπέρ αυτής, το δέκατον του εφά άλευρον κρίθινον· έλαιον όμως δεν θέλει επιχύσει επ\' αυτό, ουδέ λιβάνιον θέλει επιθέσει επ\' αυτό· διότι είναι προσφορά ζηλοτυπίας, προσφορά ενθυμήσεως, φέρουσα εις ενθύμησιν ανομίαν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Και θέλει πλησιάσει αυτήν ο ιερεύς και στήσει αυτήν ενώπιον του Κυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Έπειτα θέλει λάβει ο ιερεύς ύδωρ άγιον εις αγγείον πήλινον· και από του χώματος, το οποίον είναι επί του εδάφους της σκηνής, θέλει λάβει ο ιερεύς και βάλει εις το ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Και θέλει στήσει ο ιερεύς την γυναίκα ενώπιον του Κυρίου και θέλει αποκαλύψει την κεφαλήν της γυναικός, και θέλει βάλει εις τας χείρας αυτής την προσφοράν της ενθυμήσεως, την προσφοράν της ζηλοτυπίας· εν δε τη χειρί του ιερέως θέλει είσθαι το ύδωρ το πικρόν, το οποίον φέρει την κατάραν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Και θέλει ορκίσει αυτήν ο ιερεύς και θέλει ειπεί προς την γυναίκα, Εάν δεν εκοιμήθη τις μετά σου και εάν δεν παρεδρόμησας διά να μολυνθής, δεχομένη άλλον αντί του ανδρός σου, ας ήσαι αβλαβής από του ύδατος τούτου του πικρού, το οποίον φέρει την κατάραν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'εάν όμως παρεδρόμησας, δεχομένη άλλον αντί του ανδρός σου, και εμολύνθης και εκοιμήθη τις μετά σου εκτός του ανδρός σου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'τότε ο ιερεύς θέλει ορκίσει την γυναίκα μεθ\' όρκου κατάρας, και θέλει ειπεί ο ιερεύς προς την γυναίκα, Ο Κύριος να σε καταστήση κατάραν και όρκον μεταξύ του λαού σου, κάμνων ο Κύριος να σαπή ο μηρός σου και να πρησθή η κοιλία σου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'και το ύδωρ τούτο, το οποίον φέρει την κατάραν, θέλει εισέλθει εις τα εντόσθιά σου, διά να κάμη να πρησθή η κοιλία σου και να σαπή ο μηρός σου. Και θέλει ειπεί η γυνή, Αμήν, αμήν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Έπειτα θέλει γράψει ο ιερεύς τας κατάρας ταύτας εν βιβλίω και θέλει εξαλείψει αυτάς διά του ύδατος του πικρού·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'και θέλει ποτίσει την γυναίκα το ύδωρ το πικρόν, το οποίον φέρει την κατάραν· και το ύδωρ, το φέρον την κατάραν, θέλει εισέλθει εις αυτήν διά πικρίαν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Και θέλει λάβει ο ιερεύς εκ της χειρός της γυναικός την προσφοράν της ζηλοτυπίας και θέλει κινήσει την προσφοράν ενώπιον του Κυρίου και θέλει προσφέρει αυτήν εις το θυσιαστήριον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'και θέλει δράξει ο ιερεύς από της προσφοράς το μνημόσυνον αυτής και θέλει καύσει επί το θυσιαστήριον, και μετά ταύτα θέλει ποτίσει την γυναίκα το ύδωρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Και αφού ποτίση αυτήν το ύδωρ τότε θέλει συμβή ώστε, αν ήναι μεμολυσμένη και ηδίκησε τον άνδρα αυτής, θέλει εισέλθει εις αυτήν το ύδωρ, το φέρον την κατάραν, διά πικρίαν, και η κοιλία αυτής θέλει πρησθή και ο μηρός αυτής θέλει σαπή και θέλει είσθαι η γυνή κατάρα εν μέσω του λαού αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Εάν όμως δεν ήναι μεμολυσμένη η γυνή αλλά καθαρά, τότε θέλει μείνει αβλαβής, και θέλει συλλάβει σπέρμα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Ούτος είναι ο νόμος της ζηλοτυπίας, όταν γυνή τις παραδρομήση, δεχομένη άλλον αντί του ανδρός αυτής και μολυνθή·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'ή όταν έλθη το πνεύμα της ζηλοτυπίας εις άνδρα τινά και ζηλοτυπήση την γυναίκα αυτού και στήση την γυναίκα αυτού ενώπιον του Κυρίου, και ο ιερεύς κάμη εις αυτήν κατά πάντα τον νόμον τούτον·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Τότε ο μεν ανήρ θέλει είσθαι αθώος από της ανομίας, η δε γυνή εκείνη θέλει βαστάσει την ανομίαν αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Λάλησον προς τους υιούς Ισραήλ και ειπέ προς αυτούς, Όταν ανήρ ή γυνή ευχηθή ευχήν Ναζηραίου, διά να αφιερωθή εις τον Κύριον,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'θέλει εγκρατεύεσθαι από οίνου και από σίκερα και δεν θέλει πίει όξος από οίνου ή όξος από σίκερα ούτε θέλει πίει ό,τι είναι κατεσκευασμένον από σταφυλής ούτε θέλει φάγει σταφυλήν πρόσφατον ουδέ σταφίδας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Πάσας τας ημέρας της αφιερώσεως αυτού δεν θέλει φάγει ουδέν εκ των όσα γίνονται εξ αμπέλου, από φλοιού σταφυλής έως κόκκου αυτής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Πάσας τας ημέρας της ευχής της αφιερώσεως αυτού δεν θέλει περάσει ξυράφιον επί της κεφαλής αυτού, εωσού πληρωθώσιν αι ημέραι, τας οποίας ευχήθη εις τον Κύριον· άγιος θέλει είσθαι, αφίνων τας τρίχας της κόμης της κεφαλής αυτού να αυξάνωσι.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Πάσας τας ημέρας της αφιερώσεως αυτού εις τον Κύριον δεν θέλει εισέλθει εις τεθνεώτα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Δεν θέλει μολυνθή διά τον πατέρα αυτού ή διά την μητέρα αυτού, διά τον αδελφόν αυτού ή διά την αδελφήν αυτού, όταν αποθάνωσιν· επειδή η προς τον Θεόν αφιέρωσις αυτού είναι επί της κεφαλής αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Πάσας τας ημέρας της αφιερώσεως αυτού είναι άγιος εις τον Κύριον.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Και εάν τις αποθάνη εξαίφνης πλησίον αυτού και μολυνθή η κεφαλή της αφιερώσεως αυτού, τότε θέλει ξυρίσει την κεφαλήν αυτού εν τη ημέρα του καθαρισμού αυτού· εις την εβδόμην ημέραν θέλει ξυρίσει αυτήν.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Την δε ογδόην ημέραν θέλει φέρει δύο τρυγόνας ή δύο νεοσσούς περιστερών προς τον ιερέα εις την θύραν της σκηνής του μαρτυρίου·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'και ο ιερεύς θέλει προσφέρει την μίαν εις προσφοράν περί αμαρτίας, την δε άλλην εις ολοκαύτωμα· και θέλει κάμει εξιλέωσιν υπέρ αυτού διά την περί τον νεκρόν αμαρτίαν αυτού και θέλει αγιάσει την κεφαλήν αυτού εν εκείνη τη ημέρα.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Και θέλει αφιερώσει εις τον Κύριον τας ημέρας της αφιερώσεως αυτού, και θέλει φέρει αρνίον ενιαύσιον διά προσφοράν περί ανομίας· αι δε ημέραι αι παρελθούσαι δεν θέλουσι λογισθή, διότι εμολύνθη η αφιέρωσις αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Ούτος δε είναι ο νόμος του Ναζηραίου αφού πληρωθώσιν αι ημέραι της αφιερώσεως αυτού· θέλει φερθή εις την θύραν της σκηνής του μαρτυρίου,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'και θέλει προσφέρει το δώρον αυτού εις τον Κύριον, εν αρνίον ενιαύσιον άμωμον εις ολοκαύτωμα και εν αρνίον θηλυκόν ενιαύσιον άμωμον εις προσφοράν περί αμαρτίας και ένα κριόν άμωμον εις προσφοράν ειρηνικήν,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'και κάνιστρον άρτων αζύμων εκ σεμιδάλεως εζυμωμένης μετά ελαίου, και λάγανα άζυμα κεχρισμένα μετά ελαίου και την εξ αλφίτων προσφοράν αυτών και την σπονδήν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Και ο ιερεύς θέλει προσφέρει αυτά ενώπιον του Κυρίου και θέλει κάμει την περί αμαρτίας προσφοράν αυτού και το ολοκαύτωμα αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Και θέλει προσφέρει τον κριόν εις θυσίαν ειρηνικήν προς τον Κύριον μετά του κανίστρου των αζύμων· θέλει προσφέρει έτι ο ιερεύς την εξ αλφίτων προσφοράν αυτού και την σπονδήν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Και ο Ναζηραίος θέλει ξυρισθή την κεφαλήν της αφιερώσεως αυτού εις την θύραν της σκηνής του μαρτυρίου, και θέλει λάβει τας τρίχας της κεφαλής της αφιερώσεως αυτού και επιθέσει επί του πυρός του υποκάτω της ειρηνικής θυσίας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Και ο ιερεύς θέλει λάβει τον εψημένον ώμον του κριού και ένα άρτον άζυμον εκ του κανίστρου, και εν λάγανον άζυμον και θέλει επιθέσει αυτά επί τας χείρας του Ναζηραίου, αφού ξυρισθή τας τρίχας της αφιερώσεως αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Και θέλει κινήσει αυτά ο ιερεύς εις κινητήν προσφοράν ενώπιον του Κυρίου· τούτο είναι άγιον εις τον ιερέα, μετά του στήθους της κινητής προσφοράς και μετά του ώμου της υψουμένης προσφοράς· και μετά ταύτα δύναται να πίη οίνον ο Ναζηραίος.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Του Ναζηραίου, όστις έκαμεν ευχήν, ούτος είναι ο νόμος του δώρου αυτού εις τον Κύριον διά την αφιέρωσιν αυτού, εκτός του ό,τι ήθελε προσφέρει εκουσίως· συμφώνως με την ευχήν, την οποίαν ευχήθη, ούτω θέλει κάμει κατά τον νόμον της αφιερώσεως αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Και ελάλησε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Λάλησον προς τον Ααρών και προς τους υιούς αυτού, λέγων, Ούτω θέλετε ευλογεί τους υιούς Ισραήλ, λέγοντες προς αυτούς·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Ο Κύριος να σε ευλογήση και να σε φυλάξη·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Ο Κύριος να επιλάμψη το πρόσωπον αυτού επί σε και να σε ελεήση·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Ο Κύριος να υψώση το πρόσωπον αυτού επί σε και να σοι δώση ειρήνην·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Και θέλουσιν επιθέσει το όνομά μου επί τους υιούς Ισραήλ· και εγώ θέλω ευλογήσει αυτούς.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Και την ημέραν, καθ\' ην ο Μωϋσής ετελείωσε να στήνη την σκηνήν και έχρισεν αυτήν και ηγίασεν αυτήν και πάντα τα σκεύη αυτής και το θυσιαστήριον και πάντα τα σκεύη αυτού και έχρισεν αυτά και ηγίασεν αυτά·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'τότε οι άρχοντες του Ισραήλ, οι αρχηγοί των οίκων των πατέρων αυτών οίτινες ήσαν οι άρχοντες των φυλών, οι επιστατήσαντες εις την απαρίθμησιν, έκαμον προσφοράν·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'και έφεραν τα δώρα αυτών ενώπιον του Κυρίου, εξ αμάξας σκεπαστάς και δώδεκα βόας, μίαν άμαξαν ανά δύο άρχοντες και ένα βουν έκαστος, και έφεραν αυτά έμπροσθεν της σκηνής.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Και είπε Κύριος προς τον Μωϋσήν, λέγων,');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Λάβε ταύτα παρ\' αυτών, και θέλουσιν είσθαι διά τα έργα της υπηρεσίας της σκηνής του μαρτυρίου· και θέλεις δώσει αυτά εις τους Λευΐτας, εις έκαστον κατά την υπηρεσίαν αυτού.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Και έλαβεν ο Μωϋσής τας αμάξας και τους βόας και έδωκεν αυτά εις τους Λευΐτας.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Τας δύο αμάξας και τους τέσσαρας βόας έδωκεν εις τους υιούς Γηρσών, κατά την υπηρεσίαν αυτών.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Και τας τέσσαρας αμάξας και τους οκτώ βόας έδωκεν εις τους υιούς Μεραρί· κατά την υπηρεσίαν αυτών, υπό την χείρα του Ιθάμαρ υιού του Ααρών του ιερέως.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Εις δε τους υιούς Καάθ δεν έδωκε· διότι η εν τω αγιαστηρίω υπηρεσία αυτών ήτο να βαστάζωσιν επ\' ώμων.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Και προσέφεραν οι άρχοντες διά τον εγκαινιασμόν του θυσιαστηρίου καθ\' ην ημέραν εχρίσθη, και προσέφεραν οι άρχοντες τα δώρα αυτών έμπροσθεν του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Και είπε Κύριος προς τον Μωϋσήν, Εις άρχων καθ\' ημέραν, θέλουσι προσφέρει τα δώρα αυτών διά τον εγκαινιασμόν του θυσιαστηρίου.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Και ο προσφέρων το δώρον αυτού την πρώτην ημέραν ήτο Ναασσών ο υιός του Αμμιναδάβ, εκ της φυλής Ιούδα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'και το δώρον αυτού ήτο εις αργυρούς δίσκος, βάρους εκατόν τριάκοντα σίκλων· λεκάνιον εν αργυρούν εβδομήκοντα σίκλων, κατά τον σίκλον τον άγιον· αμφότερα πλήρη σεμιδάλεως εζυμωμένης μετά ελαίου, διά προσφοράν εξ αλφίτων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'εις θυμιαματοδόχος χρυσούς δέκα σίκλων, πλήρης θυμιάματος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'εις μόσχος εκ βοών, εις κριός, εν αρνίον ενιαύσιον, εις ολοκαύτωμα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'εις τράγος εξ αιγών εις προσφοράν περί αμαρτίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'και εις θυσίαν ειρηνικήν, δύο βόες, κριοί πέντε, τράγοι πέντε, αρνία ενιαύσια πέντε. Τούτο ήτο το δώρον του Ναασσών, υιού του Αμμιναδάβ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Την δευτέραν ημέραν προσέφερεν ο Ναθαναήλ ο υιός του Σουάρ, ο άρχων της φυλής Ισσάχαρ·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'και προσέφερε το δώρον αυτού ένα δίσκον αργυρούν βάρους εκατόν τριάκοντα σίκλων· λεκάνιον εν αργυρούν εβδομήκοντα σίκλων, κατά τον σίκλον τον άγιον· αμφότερα πλήρη σεμιδάλεως εζυμωμένης μετά ελαίου, διά προσφοράν εξ αλφίτων·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'ένα θυμιαματοδόχον χρυσούν δέκα σίκλων, πλήρης θυμιάματος·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'ένα μόσχον εκ βοών, ένα κριόν, εν αρνίον ενιαύσιον, εις ολοκαύτωμα·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'τράγον εξ αιγών ένα, εις προσφοράν περί αμαρτίας·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'και εις θυσίαν ειρηνικήν, δύο βόας, κριούς πέντε, τράγους πέντε, αρνία ενιαύσια πέντε. Τούτο ήτο το δώρον του Ναθαναήλ, υιού του Σουάρ.');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Την τρίτην ημέραν προσέφερεν ο άρχων των υιών Ζαβουλών, Ελιάβ ο υιός του Χαιλών·');
INSERT INTO `GreVamvas_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'το δώρον αυτού ήτο εις αργυρούς δίσκος βάρους εκατόν τριάκοντα σίκλων· λεκάνιον εν αργυρούν εβδομήκοντα σίκλων, κατά τον σίκλον τον άγιον· αμφότερα πλήρη σεμιδάλεως εζυμωμένης μετά ελαίου, διά προσφοράν εξ αλφίτων·');
